final_template:
terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  default_tags = {
    Project     = "route53-dns-query-logging"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

variable "tags" {
  description = "Additional user-defined tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

# Public hosted zone for DNS query logging (stateful, protected from deletion)
resource "aws_route53_zone" "primary" {
  name = "example.com"

  tags = merge(local.default_tags, var.tags)

  lifecycle {
    prevent_destroy = true
  }
}

# CloudWatch Logs log group that receives the DNS query logs for the zone.
# Retention is finite (90 days) to avoid indefinite log storage.
resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "aws_route53_example_com"
  retention_in_days = 90

  tags = merge(local.default_tags, var.tags)
}

# Least-privilege resource policy granting the Route 53 service principal
# only the actions required to write query logs into the log group above.
data "aws_iam_policy_document" "route53_query_logging" {
  statement {
    sid    = "Route53LogsToCloudWatchLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["route53.amazonaws.com"]
    }

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.aws_route53_example_com.arn,
      "${aws_cloudwatch_log_group.aws_route53_example_com.arn}:*",
    ]
  }
}

resource "aws_cloudwatch_log_resource_policy" "route53_query_logging_policy" {
  policy_name     = "route53-query-logging-policy"
  policy_document = data.aws_iam_policy_document.route53_query_logging.json
}

# Associates the hosted zone with the CloudWatch log group. The resource
# policy must exist before the query logging configuration is created.
resource "aws_route53_query_log" "primary" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id                  = aws_route53_zone.primary.zone_id

  depends_on = [
    aws_cloudwatch_log_resource_policy.route53_query_logging_policy,
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC that will be associated with the private hosted zone."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_domain_name" {
  description = "Domain name for the private hosted zone."
  type        = string
  default     = "internal.example.local"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Name        = "route53-zone-association"
    Environment = "development"
  }
}

locals {
  common_tags = merge(
    var.tags,
    {
      ManagedBy = "terraform"
    },
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

# The hosted zone intentionally defines NO inline vpc {} blocks.
# The zone-to-VPC association is exclusively owned by the dedicated
# aws_route53_zone_association resource below to avoid conflicting
# association state and perpetual diffs.
resource "aws_route53_zone" "private" {
  name          = var.private_domain_name
  force_destroy = true

  tags = local.common_tags
}

resource "aws_route53_zone_association" "main" {
  zone_id    = aws_route53_zone.private.zone_id
  vpc_id     = aws_vpc.main.id
  vpc_region = "us-east-1"
}

output "hosted_zone_id" {
  description = "ID of the private hosted zone."
  value       = aws_route53_zone.private.zone_id
}

output "hosted_zone_name" {
  description = "Domain name of the private hosted zone."
  value       = aws_route53_zone.private.name
}

output "associated_vpc_id" {
  description = "ID of the VPC associated with the private hosted zone."
  value       = aws_route53_zone_association.main.vpc_id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Root domain for the primary Route 53 hosted zone (non-secret default so apply runs unattended)."
  type        = string
  default     = "example.com"
}

locals {
  name            = "main"
  app_record_name = "app.${var.domain_name}"
}

# ---------------------------------------------------------------------------
# Networking foundation (greenfield - everything created here)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name}-public-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-public"
  }
}

resource "aws_route" "public_internet_gateway" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "main-alb-sg"
  description = "Ingress on HTTP/HTTPS only for the main application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound so the ALB can reach its targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb" "main" {
  name                       = "main"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.main.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = local.name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "main" {
  name        = "main"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = local.name
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# ---------------------------------------------------------------------------
# Route 53 - new hosted zone and ALB alias record
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = {
    Name = "primary"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.app_record_name
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the main application load balancer."
  value       = aws_lb.main.dns_name
}

output "record_fqdn" {
  description = "FQDN of the Route 53 alias record pointing at the load balancer."
  value       = aws_route53_record.main.fqdn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Domain name used for both the public and private split-view hosted zones."
  type        = string
  default     = "example.com"
}

locals {
  db_engine          = "postgres"
  db_engine_version  = "15"
  db_instance_class  = "db.t3.micro"
  db_port            = 5432
  db_master_username = "dbadmin"
  db_record_name     = "db.${var.domain_name}"
  db_record_ttl      = 300

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = "10.0.${count.index + 1}.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = "10.0.${count.index + 11}.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "private-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Database subnet group (spans private and public subnets across two AZs)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "main"
  subnet_ids = concat(aws_subnet.public[*].id, aws_subnet.private[*].id)

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "internal" {
  name        = "internal"
  description = "Internal database access - PostgreSQL only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL responses to within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "internal"
  })
}

resource "aws_security_group" "public" {
  name        = "public"
  description = "Externally reachable database access - PostgreSQL port only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from anywhere - explicitly required for the externally reachable database endpoint"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL to within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

# ---------------------------------------------------------------------------
# RDS instances (identical engine configuration for interchangeable endpoints)
# ---------------------------------------------------------------------------

resource "aws_db_instance" "internal" {
  identifier     = "internal"
  engine         = local.db_engine
  engine_version = local.db_engine_version
  instance_class = local.db_instance_class
  port           = local.db_port

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  username                    = local.db_master_username
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.internal.id]
  publicly_accessible    = false

  multi_az                = false
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "internal"
  })
}

resource "aws_db_instance" "public" {
  identifier     = "public"
  engine         = local.db_engine
  engine_version = local.db_engine_version
  instance_class = local.db_instance_class
  port           = local.db_port

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  username                    = local.db_master_username
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.public.id]
  publicly_accessible    = true

  multi_az                = false
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  # Ensure internet-routable subnets (IGW and default routes) exist before the
  # publicly accessible instance is provisioned so it receives a public endpoint.
  depends_on = [aws_route_table_association.public]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

# ---------------------------------------------------------------------------
# Split-view DNS (Route 53)
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "public" {
  name = var.domain_name

  tags = merge(local.common_tags, {
    Name = "public"
  })
}

resource "aws_route53_zone" "private" {
  name = var.domain_name

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, {
    Name = "private"
  })
}

resource "aws_route53_record" "internal" {
  zone_id = aws_route53_zone.private.zone_id
  name    = local.db_record_name
  type    = "CNAME"
  ttl     = local.db_record_ttl
  records = [aws_db_instance.internal.address]
}

resource "aws_route53_record" "public" {
  zone_id = aws_route53_zone.public.zone_id
  name    = local.db_record_name
  type    = "CNAME"
  ttl     = local.db_record_ttl
  records = [aws_db_instance.public.address]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "domain_name" {
  description = "Private DNS domain name used for the Route 53 hosted zone."
  type        = string
  default     = "db.internal"
}

# -----------------------------------------------------------------------------
# Data sources and locals
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_master_username = "dbadmin"
  db_name            = "appdb"
  reader_record_name = "reader.${var.domain_name}"
  reader_record_ttl  = 60
  replica_weight     = 100
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = {
    Name = "main-private-${count.index + 1}"
  }
}

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "main"
  }
}

resource "aws_security_group" "database" {
  name        = "database-tier"
  description = "Database tier - permits MySQL access from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL replication from read replicas to the primary"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS (UDP) to the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "DNS (TCP) to the VPC resolver"
    from_port   = 53
    to_port     = 53
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "database-tier"
  }
}

# -----------------------------------------------------------------------------
# Database master credentials
# -----------------------------------------------------------------------------

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "rds-mysql-primary-master"
  description             = "Master credentials for the primary MySQL database instance"
  recovery_window_in_days = 0

  tags = {
    Name = "rds-mysql-primary-master"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master.result
    engine   = "mysql"
    host     = aws_db_instance.primary.address
    port     = 3306
    dbname   = local.db_name
  })
}

# -----------------------------------------------------------------------------
# Database instances
# -----------------------------------------------------------------------------

resource "aws_db_instance" "primary" {
  identifier                 = "primary"
  engine                     = "mysql"
  engine_version             = "8.0"
  instance_class             = "db.t4g.medium"
  allocated_storage          = 20
  max_allocated_storage      = 100
  storage_type               = "gp3"
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_master_username
  password                   = random_password.master.result
  db_subnet_group_name       = aws_db_subnet_group.main.name
  vpc_security_group_ids     = [aws_security_group.database.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  skip_final_snapshot        = true

  tags = {
    Name                       = "primary"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "replica_1" {
  identifier             = "replica-1"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = aws_db_instance.primary.instance_class
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  skip_final_snapshot    = true

  tags = {
    Name                       = "replica-1"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "replica_2" {
  identifier             = "replica-2"
  replicate_source_db    = aws_db_instance.primary.identifier
  instance_class         = aws_db_instance.primary.instance_class
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  skip_final_snapshot    = true

  tags = {
    Name                       = "replica-2"
    MasterCredentialsSecretArn = aws_secretsmanager_secret.db_master.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Route 53 private hosted zone, health checks, and weighted reader records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Private hosted zone for the RDS reader endpoints"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "main"
  }
}

resource "aws_route53_health_check" "replica_1" {
  fqdn              = aws_db_instance.replica_1.address
  port              = 3306
  type              = "TCP"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "replica-1-health-check"
  }
}

resource "aws_route53_health_check" "replica_2" {
  fqdn              = aws_db_instance.replica_2.address
  port              = 3306
  type              = "TCP"
  failure_threshold = 3
  request_interval  = 30

  tags = {
    Name = "replica-2-health-check"
  }
}

resource "aws_route53_record" "reader_replica_1" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.reader_record_name
  type    = "CNAME"
  ttl     = local.reader_record_ttl

  weighted_routing_policy {
    weight = local.replica_weight
  }

  set_identifier  = "replica-1"
  records         = [aws_db_instance.replica_1.address]
  health_check_id = aws_route53_health_check.replica_1.id
}

resource "aws_route53_record" "reader_replica_2" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.reader_record_name
  type    = "CNAME"
  ttl     = local.reader_record_ttl

  weighted_routing_policy {
    weight = local.replica_weight
  }

  set_identifier  = "replica-2"
  records         = [aws_db_instance.replica_2.address]
  health_check_id = aws_route53_health_check.replica_2.id
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "reader_fqdn" {
  description = "FQDN of the weighted CNAME record that splits read traffic between the two replicas."
  value       = aws_route53_record.reader_replica_1.fqdn
}

output "replica_1_weight" {
  description = "Route 53 weighted-routing weight assigned to the replica-1 CNAME record."
  value       = aws_route53_record.reader_replica_1.weighted_routing_policy[0].weight
}

output "replica_2_weight" {
  description = "Route 53 weighted-routing weight assigned to the replica-2 CNAME record."
  value       = aws_route53_record.reader_replica_2.weighted_routing_policy[0].weight
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied consistently to all resources"
  type        = string
  default     = "dev"
}

locals {
  public_subnet_ids = [aws_subnet.public_0.id, aws_subnet.public_1.id]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Network foundation (greenfield - all resources created in this configuration)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "my_application-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "my_application-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "my_application-public-0"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "my_application-public-1"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "my_application-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile for Elastic Beanstalk
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb_ec2_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "Basic Elastic Beanstalk application"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "app_env" {
  name                = "app-env"
  application         = aws_elastic_beanstalk_application.my_application.name
  tier                = "WebServer"
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.11"

  # EC2 instances assume eb_ec2_role via the instance profile
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  # VPC placement
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  # Auto Scaling bounds to control cost
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  tags = {
    Name        = "app-env"
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.app_env.cname
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application"
  value       = aws_elastic_beanstalk_application.my_application.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment (non-infrastructure value)."
  type        = string
  default     = "my-api-env"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk platform solution stack name (static, non-infrastructure configuration value)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.12"
}

variable "additional_tags" {
  description = "Optional additional non-infrastructure tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = merge(
    {
      Environment = var.environment_name
      ManagedBy   = "terraform"
    },
    var.additional_tags,
  )
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "eb_ec2_role" })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(local.common_tags, { Name = "eb_ec2_profile" })
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name = "eb_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEBAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "eb_service_role" })
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield VPC)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "my-api-app-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "my-api-app-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "my-api-app-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "my-api-app-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group for the Elastic Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_security_group" "eb_instances_sg" {
  name        = "eb-instances-sg"
  description = "Security group for Elastic Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "eb-instances-sg" })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_api_app" {
  name        = "my_api_app"
  description = "my_api_app Elastic Beanstalk application"

  tags = merge(local.common_tags, { Name = "my_api_app" })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environment (WebServer tier, ALB, CPU autoscaling)
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "my_api_env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.my_api_app.name
  description         = "my_api_app web server environment with CPU-based autoscaling"
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  # --- Autoscaling capacity ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  # --- Autoscaling triggers (CPU utilization) ---
  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "Average"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "70"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperBreachScaleIncrement"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "20"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerBreachScaleIncrement"
    value     = "-1"
  }

  # --- IAM wiring ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # --- Environment / load balancer ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # --- VPC wiring ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  # --- Instance security group ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances_sg.id
  }

  tags = merge(local.common_tags, { Name = var.environment_name })

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_instance_profile.eb_ec2_profile,
  ]
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.my_api_env.name
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.my_api_env.endpoint_url
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_ids = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield — everything defined in-file)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "eb-main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-main-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "eb-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

