    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project identifier applied to all resources via the Project tag."
  type        = string
  default     = "batch-job-processing"
}

variable "worker_environment_name" {
  description = "Name of the Elastic Beanstalk worker tier environment."
  type        = string
  default     = "batch-job-worker-env"
}

variable "worker_instance_type" {
  description = "EC2 instance type used by the worker tier Auto Scaling group."
  type        = string
  default     = "t3.small"
}

variable "batch_job_queue_visibility_timeout" {
  description = "Visibility timeout in seconds for the batch job SQS queue."
  type        = number
  default     = 300
}

locals {
  common_tags = {
    Project   = var.project_name
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Worker tier application source bundle (built locally, zipped for deployment)
# ---------------------------------------------------------------------------

data "archive_file" "worker_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/batch-worker-bundle.zip"

  source {
    content = <<-EOT
      """Minimal batch worker application for the Elastic Beanstalk worker tier.

      The worker environment daemon (sqsd) polls the batch job queue and
      forwards every SQS message to this WSGI application as an HTTP POST
      request on the local web server. Responding with HTTP 200 acknowledges
      successful processing so the message is deleted from the queue.
      """

      def application(environ, start_response):
          """WSGI entry point invoked for every polled batch job message."""
          if environ["REQUEST_METHOD"] == "POST":
              # Batch job payload processing would be implemented here; this
              # scaffold acknowledges every job so messages are consumed.
              start_response("200 OK", [("Content-Type", "text/plain")])
              return [b"Batch job accepted"]
          start_response("200 OK", [("Content-Type", "text/plain")])
          return [b"Batch worker running"]
    EOT
    filename = "application.py"
  }

  source {
    content = <<-EOT
      # The scaffold worker application relies on the Python standard library only.
    EOT
    filename = "requirements.txt"
  }
}

# ---------------------------------------------------------------------------
# S3 bucket storing the Elastic Beanstalk application version source bundles
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"

  tags = merge(
    local.common_tags,
    {
      Name = "sampleapril26426"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.id
  key    = "application-versions/batch-worker-bundle.zip"
  source = data.archive_file.worker_bundle.output_path
  etag   = data.archive_file.worker_bundle.output_md5

  content_type = "application/zip"

  tags = merge(
    local.common_tags,
    {
      Name = "examplebucket_object"
    },
  )

  depends_on = [
    aws_s3_bucket_server_side_encryption_configuration.sampleapril26426,
    aws_s3_bucket_versioning.sampleapril26426,
  ]
}

# ---------------------------------------------------------------------------
# SQS queue used as the batch job intake queue for the worker tier
# ---------------------------------------------------------------------------

resource "aws_sqs_queue" "batch_job_queue" {
  name                       = "batch_job_queue"
  visibility_timeout_seconds = var.batch_job_queue_visibility_timeout
  message_retention_seconds  = 345600
  sqs_managed_sse_enabled    = true

  tags = merge(
    local.common_tags,
    {
      Name = "batch_job_queue"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role, least-privilege inline policy, and instance profile for EC2
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "eb_ec2_role"
    },
  )
}

resource "aws_iam_role_policy" "eb_worker_sqs_s3" {
  name = "eb-worker-sqs-s3-access"
  role = aws_iam_role.eb_ec2_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConsumeBatchJobQueue"
        Effect = "Allow"
        Action = [
          "sqs:ReceiveMessage",
          "sqs:DeleteMessage",
          "sqs:GetQueueAttributes",
          "sqs:SendMessage",
        ]
        Resource = aws_sqs_queue.batch_job_queue.arn
      },
      {
        Sid      = "ListApplicationVersionBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.sampleapril26426.arn
      },
      {
        Sid      = "FetchApplicationVersions"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.sampleapril26426.arn}/*"
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(
    local.common_tags,
    {
      Name = "eb_ec2_profile"
    },
  )
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and worker tier environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name        = "batch_job_app"
  description = "Elastic Beanstalk application hosting batch processing jobs"

  tags = merge(
    local.common_tags,
    {
      Name = "batch_job_app"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.batch_job_app.name
  description = "Initial batch worker application source bundle"
  bucket      = aws_s3_bucket.sampleapril26426.id
  key         = aws_s3_object.examplebucket_object.key

  tags = merge(
    local.common_tags,
    {
      Name = "version"
    },
  )

  depends_on = [aws_s3_object.examplebucket_object]
}

resource "aws_elastic_beanstalk_environment" "batch_worker" {
  name                = var.worker_environment_name
  application         = aws_elastic_beanstalk_application.batch_job_app.name
  description         = "Worker tier environment for batch processing jobs"
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "Worker"
  version_label       = aws_elastic_beanstalk_application_version.version.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.worker_instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "WorkQueueURL"
    value     = aws_sqs_queue.batch_job_queue.url
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "WorkQueueSize"
    value     = "10"
  }

  setting {
    namespace = "aws:elasticbeanstalk:worker"
    name      = "MessageRetentionTimeout"
    value     = "345600"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.worker_environment_name
    },
  )

  depends_on = [
    aws_iam_role_policy.eb_worker_sqs_s3,
    aws_iam_role_policy_attachment.eb_worker_tier,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs for downstream batch producers
# ---------------------------------------------------------------------------

output "worker_environment_name" {
  description = "Name of the Elastic Beanstalk worker tier environment."
  value       = aws_elastic_beanstalk_environment.batch_worker.name
}

output "batch_job_queue_arn" {
  description = "ARN of the SQS queue that downstream batch producers should enqueue jobs into."
  value       = aws_sqs_queue.batch_job_queue.arn
}

output "batch_job_queue_url" {
  description = "URL of the SQS queue that downstream batch producers should enqueue jobs into."
  value       = aws_sqs_queue.batch_job_queue.url
}

output "application_version_label" {
  description = "Label of the currently deployed Elastic Beanstalk application version."
  value       = aws_elastic_beanstalk_application_version.version.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Value of the Environment tag applied consistently to all resources."
  type        = string
  default     = "dev"
}

variable "solution_stack_name" {
  description = "Currently supported Elastic Beanstalk platform solution stack."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.4.0 running Python 3.11"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment hosts."
  type        = string
  default     = "t3.micro"
}

locals {
  app_name   = "myapp"
  bundle_key = "myapp/eb_app.zip"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Self-contained application source bundle
# ---------------------------------------------------------------------------

resource "local_file" "wsgi_app" {
  filename        = "${path.module}/eb_app/application.py"
  file_permission = "0644"
  content         = <<EOT
import os


def application(environ, start_response):
    status = "200 OK"
    body = os.environ.get("APP_MESSAGE", "Hello from Elastic Beanstalk!").encode("utf-8")

    response_headers = [
        ("Content-Type", "text/plain; charset=utf-8"),
        ("Content-Length", str(len(body))),
    ]

    start_response(status, response_headers)

    return [body]
EOT
}

data "archive_file" "eb_bundle" {
  type             = "zip"
  source_dir       = "${path.module}/eb_app"
  output_path      = "${path.module}/myapp_eb_bundle.zip"
  output_file_mode = "0644"

  depends_on = [local_file.wsgi_app]
}

# ---------------------------------------------------------------------------
# S3 bucket for application version source bundles
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"

  tags = merge(local.common_tags, {
    Name = "sampleapril26426"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sampleapril26426" {
  bucket = aws_s3_bucket.sampleapril26426.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket       = aws_s3_bucket.sampleapril26426.id
  key          = local.bundle_key
  source       = data.archive_file.eb_bundle.output_path
  content_type = "application/zip"
  source_hash  = data.archive_file.eb_bundle.output_base64sha256

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# IAM: EC2 instance role for Beanstalk hosts
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb_ec2_role"
  description = "EC2 instance role assumed by Elastic Beanstalk hosts."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# ---------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name        = "eb_service_role"
  description = "Service role assumed by Elastic Beanstalk for environment management."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# ---------------------------------------------------------------------------
# Networking prerequisites (greenfield: created here, never referenced by ID)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "myapp-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "myapp-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "myapp-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "myapp-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = local.app_name
  description = "myapp Elastic Beanstalk application"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  description = "myapp source bundle version"
  bucket      = aws_s3_bucket.sampleapril26426.id
  key         = aws_s3_object.examplebucket_object.key

  depends_on = [aws_s3_object.examplebucket_object]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "myapp_env" {
  name                   = "myapp-env"
  application            = aws_elastic_beanstalk_application.myapp.name
  description            = "myapp web server environment"
  solution_stack_name    = var.solution_stack_name
  tier                   = "WebServer"
  version_label          = aws_elastic_beanstalk_application_version.version.name
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.common_tags, {
    Name = "myapp-env"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myapp_env.cname
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Registered domain name managed by the Route 53 hosted zone."
  type        = string
  default     = "example.com"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack used by the environment."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  eb_subnet_ids = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
}

# ---------------------------------------------------------------------------
# Route 53 public hosted zone
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Network foundation (greenfield)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "main-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "main-public-b"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "main-public"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security group for Beanstalk EC2 instances (HTTP from inside VPC only)
# ---------------------------------------------------------------------------

resource "aws_security_group" "eb_instance_sg" {
  name        = "eb-instance-sg"
  description = "Elastic Beanstalk EC2 instances - HTTP ingress from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-instance-sg"
  }
}

# ---------------------------------------------------------------------------
# S3 bucket for Elastic Beanstalk application source bundles
# ---------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 8
}

resource "aws_s3_bucket" "examplebucket" {
  bucket = "myapp-eb-${random_id.bucket_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "myapp-eb-source-bundles"
  }
}

resource "aws_s3_bucket_public_access_block" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "examplebucket" {
  bucket = aws_s3_bucket.examplebucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Application source bundle built entirely in-config
# ---------------------------------------------------------------------------

data "archive_file" "myapp" {
  type        = "zip"
  output_path = "${path.module}/myapp.zip"

  source {
    filename = "application.py"
    content  = <<-EOT
import os

from flask import Flask

application = Flask(__name__)


@application.route("/")
def index():
    return "Hello from myapp running on AWS Elastic Beanstalk!"


@application.route("/health")
def health():
    return "OK"


if __name__ == "__main__":
    application.run(host="0.0.0.0", port=int(os.environ.get("PORT", "8000")))
EOT
  }

  source {
    filename = "requirements.txt"
    content  = "flask==3.0.3\n"
  }
}

resource "aws_s3_object" "examplebucket_object" {
  bucket       = aws_s3_bucket.examplebucket.bucket
  key          = "myapp.zip"
  source       = data.archive_file.myapp.output_path
  etag         = data.archive_file.myapp.output_md5
  content_type = "application/zip"
}

# ---------------------------------------------------------------------------
# IAM role and instance profile for Beanstalk EC2 instances
# ---------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb_ec2_role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# ---------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# ---------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "myapp Elastic Beanstalk application"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.examplebucket.bucket
  key         = aws_s3_object.examplebucket_object.key
}

resource "aws_elastic_beanstalk_environment" "eb-env" {
  name                = "eb-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = var.solution_stack_name
  cname_prefix        = "eb-env"
  version_label       = aws_elastic_beanstalk_application_version.version.name

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instance_sg.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.eb_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.eb_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

# ---------------------------------------------------------------------------
# Route 53 record directing traffic to the Beanstalk environment
# ---------------------------------------------------------------------------

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${aws_route53_zone.main.name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_elastic_beanstalk_environment.eb-env.cname]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "eb_environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eb-env.cname
}

output "app_record_fqdn" {
  description = "FQDN of the Route 53 record that directs traffic to the Beanstalk environment."
  value       = aws_route53_record.app.fqdn
}

output "route53_name_servers" {
  description = "Name servers of the hosted zone; configure these at the domain registrar to delegate DNS."
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables - user-controlled, non-infrastructure values only (all with
# defaults so `terraform apply` runs unattended)
###############################################################################

variable "domain_name" {
  description = "Root domain for the public Route53 hosted zone that serves the weighted records (e.g. \"example.com\")."
  type        = string
  default     = "example.com"
}

variable "record_subdomain" {
  description = "Single DNS label for the weighted CNAME records. Records live at \"<record_subdomain>.<domain_name>\" (e.g. \"app\" -> \"app.example.com\")."
  type        = string
  default     = "app"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]*[a-z0-9])?$", var.record_subdomain))
    error_message = "record_subdomain must be a single lowercase DNS label (letters, digits, hyphens)."
  }
}

variable "blue_weight" {
  description = "Route53 weighted routing weight for the blue environment (0-255)."
  type        = number
  default     = 100

  validation {
    condition     = var.blue_weight >= 0 && var.blue_weight <= 255 && floor(var.blue_weight) == var.blue_weight
    error_message = "blue_weight must be an integer between 0 and 255."
  }
}

variable "green_weight" {
  description = "Route53 weighted routing weight for the green environment (0-255). Raise gradually (e.g. 10 -> 50 -> 100) while lowering blue_weight to shift traffic blue -> green."
  type        = number
  default     = 0

  validation {
    condition     = var.green_weight >= 0 && var.green_weight <= 255 && floor(var.green_weight) == var.green_weight
    error_message = "green_weight must be an integer between 0 and 255."
  }
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack used by both environments."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.5.0 running Python 3.11"
}

variable "instance_type" {
  description = "EC2 instance type for the Beanstalk auto scaling instances."
  type        = string
  default     = "t3.small"
}

variable "tags" {
  description = "Additional tags merged into every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources - static provider metadata only
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  record_fqdn = "${var.record_subdomain}.${var.domain_name}"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  shared_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "shared"
    },
  )

  blue_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "blue"
    },
  )

  green_tags = merge(
    var.tags,
    {
      ManagedBy   = "terraform"
      Environment = "green"
    },
  )
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.shared_tags, { Name = "bgapp-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.shared_tags, { Name = "bgapp-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.shared_tags, { Name = "bgapp-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.shared_tags, { Name = "bgapp-public-b" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.shared_tags, { Name = "bgapp-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group for the Beanstalk EC2 instances (public web tier)
#
# Ingress justification: these instances are the public web tier that directly
# serves end-user HTTP/HTTPS traffic (the Beanstalk load balancer forwards to
# them), so ports 80 and 443 must be reachable from the internet. All other
# inbound ports are deliberately closed. Egress is unrestricted so instances
# can reach AWS service endpoints and package repositories.
###############################################################################

resource "aws_security_group" "beanstalk_instances" {
  name        = "bgapp-beanstalk-instances"
  description = "Beanstalk EC2 web tier: ingress limited to HTTP (80) and HTTPS (443) only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Unrestricted outbound access"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.shared_tags, { Name = "bgapp-beanstalk-instances" })
}

###############################################################################
# IAM - Elastic Beanstalk service role
###############################################################################

resource "aws_iam_role" "beanstalk_service" {
  name = "bgapp-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(local.shared_tags, { Name = "bgapp-eb-service-role" })
}

resource "aws_iam_role_policy_attachment" "service_enhanced_health" {
  role       = aws_iam_role.beanstalk_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "service_managed_updates" {
  role       = aws_iam_role.beanstalk_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

###############################################################################
# IAM - EC2 instance role used by the Beanstalk instances
###############################################################################

resource "aws_iam_role" "beanstalk_ec2" {
  name = "bgapp-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.shared_tags, { Name = "bgapp-eb-ec2-role" })
}

resource "aws_iam_role_policy_attachment" "ec2_web_tier" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_worker_tier" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "ec2_multicontainer_docker" {
  role       = aws_iam_role.beanstalk_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "beanstalk_ec2" {
  name = "bgapp-eb-ec2-instance-profile"
  role = aws_iam_role.beanstalk_ec2.name

  tags = merge(local.shared_tags, { Name = "bgapp-eb-ec2-instance-profile" })
}

###############################################################################
# Elastic Beanstalk application + blue/green environments
# (version_label intentionally omitted so Beanstalk launches its built-in
# sample application - no S3 bundle or external artifacts required)
###############################################################################

resource "aws_elastic_beanstalk_application" "bgapp" {
  name        = "bgapp"
  description = "Blue/Green weighted-routing application"

  tags = merge(local.shared_tags, { Name = "bgapp" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.bgapp.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  wait_for_ready_timeout = "20m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.beanstalk_service.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.beanstalk_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:health_reporting"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.blue_tags, { Name = "bgapp-blue" })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.service_enhanced_health,
    aws_iam_role_policy_attachment.service_managed_updates,
    aws_iam_role_policy_attachment.ec2_web_tier,
    aws_iam_role_policy_attachment.ec2_worker_tier,
    aws_iam_role_policy_attachment.ec2_multicontainer_docker,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.bgapp.name
  solution_stack_name = var.solution_stack_name
  tier                = "WebServer"

  wait_for_ready_timeout = "20m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.beanstalk_service.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.beanstalk_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:health_reporting"
    name      = "SystemType"
    value     = "enhanced"
  }

  tags = merge(local.green_tags, { Name = "bgapp-green" })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.service_enhanced_health,
    aws_iam_role_policy_attachment.service_managed_updates,
    aws_iam_role_policy_attachment.ec2_web_tier,
    aws_iam_role_policy_attachment.ec2_worker_tier,
    aws_iam_role_policy_attachment.ec2_multicontainer_docker,
  ]
}

###############################################################################
# Route53 - public hosted zone, per-environment health checks, weighted records
#
# Weighted routing (provider v5 idiom): the routing policy is declared by the
# presence of the nested `weighted_routing_policy` block plus `set_identifier`
# on each record - there is no `routing_policy` argument in provider v5.
# Traffic shifting: change var.blue_weight / var.green_weight (e.g. blue 90 /
# green 10, then 50/50, then 0/100) and re-apply to gradually move traffic from
# blue to green. If an environment fails its health check, Route53 withholds
# its answers regardless of the configured weight, protecting end users during
# a failed deployment.
###############################################################################

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = merge(local.shared_tags, { Name = "bgapp-zone" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "blue" {
  fqdn              = aws_elastic_beanstalk_environment.blue.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.blue_tags, { Name = "bgapp-health-check-blue" })
}

resource "aws_route53_health_check" "green" {
  fqdn              = aws_elastic_beanstalk_environment.green.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.green_tags, { Name = "bgapp-health-check-green" })
}

resource "aws_route53_record" "blue" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.record_fqdn
  type    = "CNAME"
  ttl     = 60

  weighted_routing_policy {
    weight = var.blue_weight
  }

  set_identifier  = "blue"
  health_check_id = aws_route53_health_check.blue.id
  records         = [aws_elastic_beanstalk_environment.blue.cname]
}

resource "aws_route53_record" "green" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.record_fqdn
  type    = "CNAME"
  ttl     = 60

  weighted_routing_policy {
    weight = var.green_weight
  }

  set_identifier  = "green"
  health_check_id = aws_route53_health_check.green.id
  records         = [aws_elastic_beanstalk_environment.green.cname]
}

###############################################################################
# Outputs
###############################################################################

output "weighted_record_fqdn" {
  description = "Public FQDN served by the weighted blue/green CNAME records."
  value       = local.record_fqdn
}

output "hosted_zone_id" {
  description = "Route53 hosted zone ID (for external DNS delegation)."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Route53 name servers to delegate var.domain_name to."
  value       = aws_route53_zone.main.name_servers
}

output "blue_environment_id" {
  description = "Elastic Beanstalk environment ID for blue."
  value       = aws_elastic_beanstalk_environment.blue.id
}

output "blue_environment_cname" {
  description = "Elastic Beanstalk CNAME for blue."
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_id" {
  description = "Elastic Beanstalk environment ID for green."
  value       = aws_elastic_beanstalk_environment.green.id
}

output "green_environment_cname" {
  description = "Elastic Beanstalk CNAME for green."
  value       = aws_elastic_beanstalk_environment.green.cname
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

# Default provider serves the us_west stack (us-west-2).
provider "aws" {
  region = "us-west-2"
}

# Aliased provider serves the eu_central stack (eu-central-1).
provider "aws" {
  alias  = "eu_central"
  region = "eu-central-1"
}

variable "domain_name" {
  description = "Public domain for the Route53 hosted zone used for geolocation routing."
  type        = string
  default     = "example.com"
}

variable "solution_stack" {
  description = "Elastic Beanstalk solution stack (Python 3.12 runtime on Amazon Linux 2023)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk web servers."
  type        = string
  default     = "t3.micro"
}

data "aws_availability_zones" "us_west" {
  provider = aws
  state    = "available"
}

data "aws_availability_zones" "eu_central" {
  provider = aws.eu_central
  state    = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  us_west_region         = "us-west-2"
  eu_central_region      = "eu-central-1"

  us_west_env_name       = "us-west"
  eu_central_env_name    = "eu-central"

  us_west_app_version    = "us-west-v1"
  eu_central_app_version = "eu-central-v1"

  app_fqdn               = "app.${var.domain_name}"

  common_tags = {
    ManagedBy = "terraform"
  }

  geo_tags_us_west    = merge(local.common_tags, { Geo = "us-west" })
  geo_tags_eu_central = merge(local.common_tags, { Geo = "eu-central" })
  geo_tags_global     = merge(local.common_tags, { Geo = "global" })

  wsgi_requirements = "# No third-party dependencies are required; the application uses only the Python standard library.\n"
}

locals {
  us_west_wsgi_app = <<-EOT
    """Minimal WSGI application for the ${local.us_west_env_name} Elastic Beanstalk environment."""
    import os

    ENVIRONMENT_NAME = "${local.us_west_env_name}"
    REGION_NAME = os.environ.get("AWS_REGION", "${local.us_west_region}")

    def application(environ, start_response):
        status = "200 OK"
        headers = [("Content-Type", "text/plain; charset=utf-8")]
        body = "Hello from Elastic Beanstalk environment {} in {}!\n".format(
            ENVIRONMENT_NAME, REGION_NAME
        ).encode("utf-8")
        start_response(status, headers)
        return [body]
  EOT

  eu_central_wsgi_app = <<-EOT
    """Minimal WSGI application for the ${local.eu_central_env_name} Elastic Beanstalk environment."""
    import os

    ENVIRONMENT_NAME = "${local.eu_central_env_name}"
    REGION_NAME = os.environ.get("AWS_REGION", "${local.eu_central_region}")

    def application(environ, start_response):
        status = "200 OK"
        headers = [("Content-Type", "text/plain; charset=utf-8")]
        body = "Hello from Elastic Beanstalk environment {} in {}!\n".format(
            ENVIRONMENT_NAME, REGION_NAME
        ).encode("utf-8")
        start_response(status, headers)
        return [body]
  EOT
}

###############################################################################
# Networking: us-west-2
###############################################################################

resource "aws_vpc" "us_west" {
  provider             = aws
  cidr_block           = "10.10.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-vpc" })
}

resource "aws_internet_gateway" "us_west" {
  provider = aws
  vpc_id   = aws_vpc.us_west.id

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-igw" })
}

resource "aws_subnet" "us_west_a" {
  provider                = aws
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.10.0.0/20"
  availability_zone       = data.aws_availability_zones.us_west.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-a", Tier = "public" })
}

resource "aws_subnet" "us_west_b" {
  provider                = aws
  vpc_id                  = aws_vpc.us_west.id
  cidr_block              = "10.10.16.0/20"
  availability_zone       = data.aws_availability_zones.us_west.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-b", Tier = "public" })
}

resource "aws_route_table" "us_west" {
  provider = aws
  vpc_id   = aws_vpc.us_west.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us_west.id
  }

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-public-rt" })
}

resource "aws_route_table_association" "us_west_a" {
  provider       = aws
  subnet_id      = aws_subnet.us_west_a.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_route_table_association" "us_west_b" {
  provider       = aws
  subnet_id      = aws_subnet.us_west_b.id
  route_table_id = aws_route_table.us_west.id
}

resource "aws_security_group" "us_west" {
  provider    = aws
  name        = "eb-us-west-web-sg"
  description = "Public web tier security group for the us-west Elastic Beanstalk environment"
  vpc_id      = aws_vpc.us_west.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-web-sg" })
}

###############################################################################
# Networking: eu-central-1
###############################################################################

resource "aws_vpc" "eu_central" {
  provider             = aws.eu_central
  cidr_block           = "10.20.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-vpc" })
}

resource "aws_internet_gateway" "eu_central" {
  provider = aws.eu_central
  vpc_id   = aws_vpc.eu_central.id

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-igw" })
}

resource "aws_subnet" "eu_central_a" {
  provider                = aws.eu_central
  vpc_id                  = aws_vpc.eu_central.id
  cidr_block              = "10.20.0.0/20"
  availability_zone       = data.aws_availability_zones.eu_central.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-public-a", Tier = "public" })
}

resource "aws_subnet" "eu_central_b" {
  provider                = aws.eu_central
  vpc_id                  = aws_vpc.eu_central.id
  cidr_block              = "10.20.16.0/20"
  availability_zone       = data.aws_availability_zones.eu_central.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-public-b", Tier = "public" })
}

resource "aws_route_table" "eu_central" {
  provider = aws.eu_central
  vpc_id   = aws_vpc.eu_central.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eu_central.id
  }

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-public-rt" })
}

resource "aws_route_table_association" "eu_central_a" {
  provider       = aws.eu_central
  subnet_id      = aws_subnet.eu_central_a.id
  route_table_id = aws_route_table.eu_central.id
}

resource "aws_route_table_association" "eu_central_b" {
  provider       = aws.eu_central
  subnet_id      = aws_subnet.eu_central_b.id
  route_table_id = aws_route_table.eu_central.id
}

resource "aws_security_group" "eu_central" {
  provider    = aws.eu_central
  name        = "eb-eu-central-web-sg"
  description = "Public web tier security group for the eu-central Elastic Beanstalk environment"
  vpc_id      = aws_vpc.eu_central.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-web-sg" })
}

###############################################################################
# IAM (global resources, default provider)
###############################################################################

resource "aws_iam_role" "eb_service_role" {
  name        = "eb-geo-elasticbeanstalk-service-role"
  description = "Elastic Beanstalk service role for the geolocation-routed environments"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowElasticBeanstalkToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = merge(local.geo_tags_global, { Name = "eb-geo-elasticbeanstalk-service-role" })
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

resource "aws_iam_role" "eb_ec2_role" {
  name        = "eb-geo-ec2-role"
  description = "EC2 instance role for instances in the geolocation-routed environments"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEc2ToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.geo_tags_global, { Name = "eb-geo-ec2-role" })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_enhanced_health" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb-geo-ec2-instance-profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = merge(local.geo_tags_global, { Name = "eb-geo-ec2-instance-profile" })
}

###############################################################################
# Application source bundles (S3, per region)
###############################################################################

data "archive_file" "us_west_app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/us-west-app-bundle.zip"

  source {
    content  = local.us_west_wsgi_app
    filename = "application.py"
  }

  source {
    content  = local.wsgi_requirements
    filename = "requirements.txt"
  }
}

data "archive_file" "eu_central_app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/eu-central-app-bundle.zip"

  source {
    content  = local.eu_central_wsgi_app
    filename = "application.py"
  }

  source {
    content  = local.wsgi_requirements
    filename = "requirements.txt"
  }
}

resource "aws_s3_bucket" "us_west_app" {
  provider = aws
  bucket   = "elasticbeanstalk-${local.us_west_region}-${data.aws_caller_identity.current.account_id}-geo-app"

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-app-bundles" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "us_west_app" {
  provider = aws
  bucket   = aws_s3_bucket.us_west_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ElasticBeanstalkServiceRoleListBucket"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.us_west_app.arn
      },
      {
        Sid       = "ElasticBeanstalkServiceRoleGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.us_west_app.arn}/*"
      },
      {
        Sid       = "ElasticBeanstalkInstancesGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.us_west_app.arn}/*"
      }
    ]
  })
}

resource "aws_s3_object" "us_west_bundle" {
  provider     = aws
  bucket       = aws_s3_bucket.us_west_app.id
  key          = "bundles/${local.us_west_app_version}.zip"
  source       = data.archive_file.us_west_app_bundle.output_path
  source_hash  = data.archive_file.us_west_app_bundle.output_base64sha256
  content_type = "application/zip"

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-app-bundle" })
}

resource "aws_s3_bucket" "eu_central_app" {
  provider = aws.eu_central
  bucket   = "elasticbeanstalk-${local.eu_central_region}-${data.aws_caller_identity.current.account_id}-geo-app"

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-app-bundles" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "eu_central_app" {
  provider = aws.eu_central
  bucket   = aws_s3_bucket.eu_central_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ElasticBeanstalkServiceRoleListBucket"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = aws_s3_bucket.eu_central_app.arn
      },
      {
        Sid       = "ElasticBeanstalkServiceRoleGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eu_central_app.arn}/*"
      },
      {
        Sid       = "ElasticBeanstalkInstancesGetObjects"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eu_central_app.arn}/*"
      }
    ]
  })
}

resource "aws_s3_object" "eu_central_bundle" {
  provider     = aws.eu_central
  bucket       = aws_s3_bucket.eu_central_app.id
  key          = "bundles/${local.eu_central_app_version}.zip"
  source       = data.archive_file.eu_central_app_bundle.output_path
  source_hash  = data.archive_file.eu_central_app_bundle.output_base64sha256
  content_type = "application/zip"

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-app-bundle" })
}

###############################################################################
# Elastic Beanstalk applications, versions, environments
###############################################################################

resource "aws_elastic_beanstalk_application" "us_west" {
  provider    = aws
  name        = local.us_west_env_name
  description = "Geolocation-routed Elastic Beanstalk application in us-west-2"

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_env_name })
}

resource "aws_elastic_beanstalk_application_version" "us_west" {
  provider    = aws
  name        = local.us_west_app_version
  application = aws_elastic_beanstalk_application.us_west.name
  bucket      = aws_s3_bucket.us_west_app.id
  key         = aws_s3_object.us_west_bundle.key

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_app_version })
}

resource "aws_elastic_beanstalk_environment" "us_west" {
  provider               = aws
  name                   = local.us_west_env_name
  application            = aws_elastic_beanstalk_application.us_west.name
  cname_prefix           = local.us_west_env_name
  solution_stack_name    = var.solution_stack
  tier                   = "WebServer"
  version_label          = aws_elastic_beanstalk_application_version.us_west.name
  wait_for_ready_timeout = "45m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.us_west.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.us_west_a.id, aws_subnet.us_west_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.us_west_a.id, aws_subnet.us_west_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.us_west.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  tags = merge(local.geo_tags_us_west, { Name = local.us_west_env_name })

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_enhanced_health,
    aws_iam_instance_profile.eb_ec2_profile,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application" "eu_central" {
  provider    = aws.eu_central
  name        = local.eu_central_env_name
  description = "Geolocation-routed Elastic Beanstalk application in eu-central-1"

  tags = merge(local.geo_tags_eu_central, { Name = local.eu_central_env_name })
}

resource "aws_elastic_beanstalk_application_version" "eu_central" {
  provider    = aws.eu_central
  name        = local.eu_central_app_version
  application = aws_elastic_beanstalk_application.eu_central.name
  bucket      = aws_s3_bucket.eu_central_app.id
  key         = aws_s3_object.eu_central_bundle.key

  tags = merge(local.geo_tags_eu_central, { Name = local.eu_central_app_version })
}

resource "aws_elastic_beanstalk_environment" "eu_central" {
  provider               = aws.eu_central
  name                   = local.eu_central_env_name
  application            = aws_elastic_beanstalk_application.eu_central.name
  cname_prefix           = local.eu_central_env_name
  solution_stack_name    = var.solution_stack
  tier                   = "WebServer"
  version_label          = aws_elastic_beanstalk_application_version.eu_central.name
  wait_for_ready_timeout = "45m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.eu_central.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.eu_central_a.id, aws_subnet.eu_central_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.eu_central_a.id, aws_subnet.eu_central_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eu_central.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  tags = merge(local.geo_tags_eu_central, { Name = local.eu_central_env_name })

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_enhanced_health,
    aws_iam_instance_profile.eb_ec2_profile,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Route53: hosted zone, health checks, geolocation records
###############################################################################

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Public hosted zone for geolocation-routed Elastic Beanstalk traffic"

  tags = merge(local.geo_tags_global, { Name = var.domain_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "us_west" {
  fqdn              = aws_elastic_beanstalk_environment.us_west.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.geo_tags_us_west, { Name = "eb-us-west-health-check" })
}

resource "aws_route53_health_check" "eu_central" {
  fqdn              = aws_elastic_beanstalk_environment.eu_central.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.geo_tags_eu_central, { Name = "eb-eu-central-health-check" })
}

resource "aws_route53_record" "app_geo_na" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.us_west.cname]
  set_identifier = "us-west-north-america"

  geolocation_routing_policy {
    continent = "NA"
  }

  health_check_id = aws_route53_health_check.us_west.id
}

resource "aws_route53_record" "app_geo_eu" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.eu_central.cname]
  set_identifier = "eu-central-europe"

  geolocation_routing_policy {
    continent = "EU"
  }

  health_check_id = aws_route53_health_check.eu_central.id
}

resource "aws_route53_record" "app_geo_default" {
  zone_id        = aws_route53_zone.main.zone_id
  name           = local.app_fqdn
  type           = "CNAME"
  ttl            = 60
  records        = [aws_elastic_beanstalk_environment.us_west.cname]
  set_identifier = "rest-of-world-default"

  geolocation_routing_policy {
    country = "*"
  }
}

###############################################################################
# Outputs
###############################################################################

output "us_west_environment_id" {
  description = "ID of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.id
}

output "us_west_environment_name" {
  description = "Name of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.name
}

output "us_west_environment_cname" {
  description = "CNAME endpoint of the us-west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.us_west.cname
}

output "eu_central_environment_id" {
  description = "ID of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.id
}

output "eu_central_environment_name" {
  description = "Name of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.name
}

output "eu_central_environment_cname" {
  description = "CNAME endpoint of the eu-central Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.eu_central.cname
}

output "geo_routed_endpoint_fqdn" {
  description = "Fully-qualified domain name served via Route53 geolocation routing."
  value       = local.app_fqdn
}

output "hosted_zone_name_servers" {
  description = "Name servers of the public Route53 hosted zone."
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Static provider metadata (no infrastructure discovery)
# -----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# User-controlled naming variables (safe defaults)
# -----------------------------------------------------------------------------
variable "application_name" {
  description = "Name of the Elastic Beanstalk application"
  type        = string
  default     = "eb-rds-app"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Project     = "eb-rds"
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking foundation
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 11)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-private-${count.index + 1}"
  })
}

# Public route table: only these subnets get 0.0.0.0/0 via the IGW
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table: local traffic only, no internet route
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Database subnet group (private subnets only)
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "default" {
  name       = "${var.environment_name}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-db-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "eb_instances" {
  name        = "${var.environment_name}-eb-instances-sg"
  description = "Security group for Elastic Beanstalk EC2 instances (no ingress; egress allowed)"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-eb-instances-sg"
  })
}

resource "aws_security_group" "rds" {
  name        = "${var.environment_name}-rds-sg"
  description = "Security group for RDS PostgreSQL, reachable only from Beanstalk instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from Elastic Beanstalk EC2 instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-rds-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "elasticbeanstalk.amazonaws.com",
            "cloudformation.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL (password managed by Secrets Manager, no plaintext credentials)
# -----------------------------------------------------------------------------
resource "aws_db_instance" "default" {
  identifier     = "${var.environment_name}-eb-rds-default"
  engine         = "postgres"
  engine_version = "15.5"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  max_allocated_storage = 100
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "appdb"
  username = "dbadmin"

  # Master password is generated and rotated by RDS via Secrets Manager
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.default.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.environment_name}-eb-rds-default-final"

  copy_tags_to_snapshot = true

  tags = merge(local.common_tags, {
    Name = "${var.environment_name}-eb-rds-default"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege read access to the RDS-managed master secret for the app
resource "aws_iam_role_policy" "eb_ec2_rds_secret_read" {
  name = "eb-ec2-rds-secret-read"
  role = aws_iam_role.eb_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadRdsMasterSecret"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_db_instance.default.master_user_secret[0].secret_arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "app" {
  name        = var.application_name
  description = "Elastic Beanstalk application backed by RDS PostgreSQL"

  tags = merge(local.common_tags, {
    Name = var.application_name
  })
}

resource "aws_elastic_beanstalk_environment" "env" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.0 running Python 3.11"
  tier                = "WebServer"

  tags = merge(local.common_tags, {
    Name = var.environment_name
  })

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "HealthReportingSystemType"
    value     = "enhanced"
  }

  # Database connection details passed to the application; these references
  # make the environment depend on the RDS instance.
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.default.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.default.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.default.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_db_instance.default.master_user_secret[0].secret_arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy.eb_ec2_rds_secret_read
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "beanstalk_environment_url" {
  description = "URL of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.endpoint_url
}

output "beanstalk_environment_cname" {
  description = "CNAME of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.cname
}

output "database_endpoint" {
  description = "Connection endpoint of the RDS PostgreSQL instance"
  value       = aws_db_instance.default.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environments         = ["production", "staging"]
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
  db_username          = "ebadmin"
  db_name              = "ebdb"
  solution_stack       = "64bit Amazon Linux 2023 v4.0.0 running Python 3.11"
}

# -----------------------------------------------------------------------------
# Network layer
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "eb-vpc"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "eb-internet-gateway"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "public" {
  count                   = length(local.public_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name        = "eb-public-subnet-${count.index}"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.private_subnet_cidrs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "eb-private-subnet-${count.index}"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "eb-public-route-table"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance profile for Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb-ec2-role"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_docker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = {
    Name        = "eb_ec2_profile"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM: Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "eb-service-role"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealthMonitoring"
}

resource "aws_iam_role_policy_attachment" "eb_service_operations" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

# Ingress is limited to 80/443 because these instances are the public-facing
# web tier; all end-user traffic enters through HTTP/HTTPS only.
resource "aws_security_group" "eb_instances" {
  name        = "eb-instances-sg"
  description = "Elastic Beanstalk EC2 instances - ingress restricted to HTTP/HTTPS (public web tier), unrestricted egress for package downloads and outbound calls"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere - required for the public web tier"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere - required for the public web tier"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "eb-instances-sg"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "aws_security_group" "rds" {
  name        = "eb-rds-sg"
  description = "RDS Postgres instances - ingress limited to 5432 sourced from the Beanstalk instance security group only; the database tier is never exposed publicly"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from Beanstalk instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  tags = {
    Name        = "eb-rds-sg"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-app"
  description = "My application served by the production and staging Elastic Beanstalk environments"

  tags = {
    Name        = "my-app"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# RDS subnet group and database credentials
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "rds" {
  name       = "eb-rds-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name        = "eb-rds-subnet-group"
    Environment = "shared"
    ManagedBy   = "terraform"
  }
}

resource "random_password" "db_master" {
  for_each         = toset(local.environments)
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  for_each    = toset(local.environments)
  name        = "eb/${each.key}/db-master-credentials"
  description = "Master credentials for the ${each.key} RDS instance"

  tags = {
    Name        = "eb-${each.key}-db-master-credentials"
    Environment = each.key
    ManagedBy   = "terraform"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  for_each  = toset(local.environments)
  secret_id = aws_secretsmanager_secret.db_master[each.key].id

  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master[each.key].result
  })
}

# -----------------------------------------------------------------------------
# RDS instances
# -----------------------------------------------------------------------------

# NOTE: RDS identifiers cannot contain underscores, so the physical identifiers
# use hyphens while the Terraform resource names remain prod_db / staging_db.
resource "aws_db_instance" "prod_db" {
  identifier                = "prod-db"
  engine                    = "postgres"
  engine_version            = "16"
  instance_class            = "db.t3.medium"
  allocated_storage         = 20
  max_allocated_storage     = 100
  db_name                   = local.db_name
  username                  = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["username"]
  password                  = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["password"]
  db_subnet_group_name      = aws_db_subnet_group.rds.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  publicly_accessible       = false
  multi_az                  = true
  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "prod-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "prod_db"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_db_instance" "staging_db" {
  identifier                = "staging-db"
  engine                    = "postgres"
  engine_version            = "16"
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  db_name                   = local.db_name
  username                  = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["username"]
  password                  = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["password"]
  db_subnet_group_name      = aws_db_subnet_group.rds.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  publicly_accessible       = false
  multi_az                  = false
  storage_encrypted         = true
  backup_retention_period   = 3
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "staging-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "staging_db"
    Environment = "staging"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environments
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "production" {
  name                = "production"
  application         = aws_elastic_beanstalk_application.app.name
  cname_prefix        = "production"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.prod_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.prod_db.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.prod_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["username"]
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["production"].secret_string)["password"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_docker_tier,
    aws_iam_role_policy_attachment.eb_service_health,
    aws_iam_role_policy_attachment.eb_service_operations,
  ]

  tags = {
    Name        = "production"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_elastic_beanstalk_environment" "staging" {
  name                = "staging"
  application         = aws_elastic_beanstalk_application.app.name
  cname_prefix        = "staging"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "SingleInstance"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "1"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.staging_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.staging_db.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.staging_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["username"]
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = jsondecode(aws_secretsmanager_secret_version.db_master["staging"].secret_string)["password"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_docker_tier,
    aws_iam_role_policy_attachment.eb_service_health,
    aws_iam_role_policy_attachment.eb_service_operations,
  ]

  tags = {
    Name        = "staging"
    Environment = "staging"
    ManagedBy   = "terraform"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Locals (non-secret values only)
#------------------------------------------------------------------------------

locals {
  db_master_username = "dbadmin" # Non-secret master username
  db_name            = "my_db"
}

#------------------------------------------------------------------------------
# Availability zone lookup (static provider metadata)
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Networking: VPC, subnets, IGW, NAT gateway, routing
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "my-app-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "my-app-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name = "my-app-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "my-app-private-${count.index}"
  }
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "my-app-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "my-app-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "my-app-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "my-app-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

#------------------------------------------------------------------------------
# Security groups
#------------------------------------------------------------------------------

resource "aws_security_group" "eb_alb" {
  name        = "my-app-eb-alb-sg"
  description = "Elastic Beanstalk ALB security group - inbound HTTP/HTTPS only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-eb-alb-sg"
  }
}

resource "aws_security_group" "eb_instances" {
  name        = "my-app-eb-instances-sg"
  description = "Elastic Beanstalk EC2 instances - inbound only from the ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "All traffic from the ALB security group"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.eb_alb.id]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-eb-instances-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "my-app-rds-sg"
  description = "RDS security group - inbound PostgreSQL only from EB instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from EB instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instances.id]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "my-app-rds-sg"
  }
}

#------------------------------------------------------------------------------
# IAM: EC2 instance profile for Beanstalk instances and EB service role
#------------------------------------------------------------------------------

resource "aws_iam_role" "ec2_eb_role" {
  name = "ec2-eb-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "ec2-eb-instance-role"
  }
}

resource "aws_iam_role_policy_attachment" "ec2_eb_web_tier" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "ec2_eb_worker_tier" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "ec2_eb_multicontainer_docker" {
  role       = aws_iam_role.ec2_eb_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "ec2_eb_profile1" {
  name = "ec2_eb_profile1"
  role = aws_iam_role.ec2_eb_role.name

  depends_on = [
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
  ]
}

resource "aws_iam_role" "eb_service_role" {
  name = "eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "beanstalk.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_role_policy" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

#------------------------------------------------------------------------------
# Elastic Beanstalk application (shared by blue and green environments)
#------------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "my_app" {
  name        = "my_app"
  description = "Blue/green Elastic Beanstalk application backed by Amazon RDS"
}

#------------------------------------------------------------------------------
# RDS: subnet group, generated credentials, secret storage, instance, snapshot
#------------------------------------------------------------------------------

resource "aws_db_subnet_group" "my_db_subnets" {
  name       = "my_db_subnets"
  subnet_ids = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = {
    Name = "my_db_subnets"
  }
}

resource "random_password" "db_master" {
  length      = 24
  special     = false
  min_lower   = 1
  min_upper   = 1
  min_numeric = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "my-db-master-credentials"
  description             = "Master credentials for the my-db PostgreSQL instance"
  recovery_window_in_days = 7

  tags = {
    Name = "my-db-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "my_db" {
  identifier                = "my-db"
  engine                    = "postgres"
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  storage_encrypted         = true
  db_name                   = local.db_name
  username                  = local.db_master_username
  password                  = random_password.db_master.result
  port                      = 5432
  multi_az                  = true
  publicly_accessible       = false
  db_subnet_group_name      = aws_db_subnet_group.my_db_subnets.name
  vpc_security_group_ids    = [aws_security_group.rds.id]
  backup_retention_period   = 7
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "my-db-final"

  tags = {
    Name = "my_db"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Pre-deployment snapshot of the my_db instance
resource "aws_db_snapshot" "pre_deploy" {
  db_instance_identifier = aws_db_instance.my_db.identifier
  db_snapshot_identifier = "my-db-pre-deploy"

  tags = {
    Name = "my-db-pre-deploy"
  }

  depends_on = [aws_db_instance.my_db]
}

#------------------------------------------------------------------------------
# Blue/green Elastic Beanstalk environments
#
# Both environments belong to aws_elastic_beanstalk_application.my_app and
# carry an identical configuration (same instance profile, service role,
# network, security groups, and RDS_* properties). Promotion is performed by
# swapping the two cname_prefix values between
# aws_elastic_beanstalk_environment.blue and
# aws_elastic_beanstalk_environment.green in a subsequent apply, which shifts
# traffic without replacing the EC2 instances. Both environments depend on
# aws_db_snapshot.pre_deploy so the pre-deployment database snapshot always
# precedes the first deployment.
#------------------------------------------------------------------------------

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "my-app-blue"
  application         = aws_elastic_beanstalk_application.my_app.name
  cname_prefix        = "my-app-blue-bgpoc"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.ec2_eb_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.private[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  # ELB (ALB) security groups - restricted to the 80/443-only ALB SG
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_alb.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_master_username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Environment = "blue"
  }

  depends_on = [
    aws_db_snapshot.pre_deploy,
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_role_policy,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "my-app-green"
  application         = aws_elastic_beanstalk_application.my_app.name
  cname_prefix        = "my-app-green-bgpoc"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.ec2_eb_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.private[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  # ELB (ALB) security groups - restricted to the 80/443-only ALB SG
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_alb.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = local.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = local.db_master_username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Environment = "green"
  }

  depends_on = [
    aws_db_snapshot.pre_deploy,
    aws_iam_role_policy_attachment.ec2_eb_web_tier,
    aws_iam_role_policy_attachment.ec2_eb_worker_tier,
    aws_iam_role_policy_attachment.ec2_eb_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_role_policy,
  ]
}

#------------------------------------------------------------------------------
# Outputs (no secret values are ever exposed)
#------------------------------------------------------------------------------

output "blue_environment_cname" {
  description = "CNAME of the blue Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_cname" {
  description = "CNAME of the green Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.green.cname
}

output "rds_endpoint" {
  description = "Connection endpoint of the my-db RDS instance"
  value       = aws_db_instance.my_db.endpoint
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# Static, well-known provider metadata used for AZ placement.
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_name             = "my_db1"
  db_master_username  = "dbadmin"
  public_subnet_ids   = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  database_subnet_ids = [aws_subnet.database_1.id, aws_subnet.database_2.id]
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "eb-rds-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-internet-gateway"
  }
}

# Public subnets for the Beanstalk EC2 instances and the environment ALB.
resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-subnet-1"
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb-public-subnet-2"
  }
}

# Dedicated, isolated subnets for the RDS instance (no internet route).
resource "aws_subnet" "database_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "eb-database-subnet-1"
  }
}

resource "aws_subnet" "database_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "eb-database-subnet-2"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "eb-public-route-table"
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# Route table for the database subnets: local VPC traffic only, no public route.
resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "eb-database-route-table"
  }
}

resource "aws_route_table_association" "database_1" {
  subnet_id      = aws_subnet.database_1.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table_association" "database_2" {
  subnet_id      = aws_subnet.database_2.id
  route_table_id = aws_route_table.database.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "beanstalk_alb" {
  name        = "eb-alb-sg"
  description = "Elastic Beanstalk environment ALB: ingress restricted to HTTP/HTTPS from the internet"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic to the application instances"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-alb-sg"
  }
}

resource "aws_security_group" "beanstalk_ec2" {
  name        = "eb-ec2-sg"
  description = "Elastic Beanstalk EC2 instances: application port open only to the environment ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application traffic from the environment ALB only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.beanstalk_alb.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "eb-ec2-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "eb-rds-sg"
  description = "my_db1 RDS instance: database port open only to the Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL access from the Beanstalk EC2 instances only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.beanstalk_ec2.id]
  }

  tags = {
    Name = "eb-rds-sg"
  }
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role and instance profile
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb-ec2-role"
  description        = "EC2 instance role for the Elastic Beanstalk environment"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name = "eb-ec2-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = {
    Name = "eb_ec2_profile"
  }
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "eb_service_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["beanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_service_role" {
  name               = "eb-service-role"
  description        = "Service role assumed by Elastic Beanstalk to manage the environment"
  assume_role_policy = data.aws_iam_policy_document.eb_service_assume_role.json

  tags = {
    Name = "eb-service-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-eb-app"
  description = "Elastic Beanstalk application connected to the my_db1 RDS instance"

  tags = {
    Name = "my-eb-app"
  }
}

# -----------------------------------------------------------------------------
# RDS: subnet group, generated credentials, and instance
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "my_db1" {
  name        = "my-db1-subnet-group"
  description = "Database subnets for the my_db1 RDS instance"
  subnet_ids  = local.database_subnet_ids

  tags = {
    Name = "my-db1-subnet-group"
  }
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "my-db1-master-credentials"
  description = "Master credentials for the my_db1 RDS instance"

  tags = {
    Name = "my-db1-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "my_db1" {
  identifier                 = "my-db1"
  db_name                    = local.db_name
  engine                     = "postgres"
  engine_version             = "16.6"
  instance_class             = "db.t3.micro"
  allocated_storage          = 20
  storage_type               = "gp3"
  port                       = 5432
  username                   = local.db_master_username
  password                   = random_password.db_master.result
  db_subnet_group_name       = aws_db_subnet_group.my_db1.name
  vpc_security_group_ids     = [aws_security_group.rds.id]
  publicly_accessible        = false
  storage_encrypted          = true
  multi_az                   = false
  auto_minor_version_upgrade = false
  backup_retention_period    = 7
  deletion_protection        = true
  skip_final_snapshot        = true
  copy_tags_to_snapshot      = true

  tags = {
    Name = "my_db1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk environment (WebServer tier) wired to the VPC and RDS
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_environment" "env" {
  name                   = "my-eb-env"
  application            = aws_elastic_beanstalk_application.app.name
  solution_stack_name    = "64bit Amazon Linux 2023 v6.3.1 running Python 3.12"
  tier                   = "WebServer"
  wait_for_ready_timeout = "30m"

  # VPC wiring for the EC2 instances and the environment ALB.
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # Attach the locked-down security group to the environment ALB.
  setting {
    namespace = "aws:elbv2:loadbalancer"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_alb.id
  }

  # EC2 instance configuration: instance profile, size, and security group.
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.beanstalk_ec2.id
  }

  # Enhanced health reporting.
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  # Auto Scaling capacity.
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  # Auto Scaling trigger on average CPU utilization.
  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "MeasureName"
    value     = "CPUUtilization"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Statistic"
    value     = "Average"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "Unit"
    value     = "Percent"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperThreshold"
    value     = "70"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerThreshold"
    value     = "30"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "UpperBreachScaleIncrement"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:trigger"
    name      = "LowerBreachScaleIncrement"
    value     = "-1"
  }

  # Rolling deployments based on health.
  setting {
    namespace = "aws:autoscaling:updatepolicy:rollingupdate"
    name      = "RollingUpdateEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:updatepolicy:rollingupdate"
    name      = "RollingUpdateType"
    value     = "Health"
  }

  # Database connectivity injected into the application environment.
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.my_db1.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.my_db1.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.my_db1.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.my_db1.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PASSWORD"
    value     = random_password.db_master.result
  }

  tags = {
    Name = "my-eb-env"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "beanstalk_environment_url" {
  description = "Public URL (CNAME) of the Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.env.cname
}

output "rds_endpoint_address" {
  description = "Connection endpoint address of the my_db1 RDS instance"
  value       = aws_db_instance.my_db1.address
}

output "rds_endpoint_port" {
  description = "Connection endpoint port of the my_db1 RDS instance"
  value       = aws_db_instance.my_db1.port
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the my_db1 master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project            = "web-app"
  environment        = "production"
  db_master_username = "webappadmin"
  db_name            = "webappdb"

  common_tags = {
    Environment = local.environment
    Project     = local.project
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, Internet Gateway, public subnets, and routing
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "web-app-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "web-app-igw"
  })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "web-app-public-subnet-1"
  })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "web-app-public-subnet-2"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "web-app-public-route-table"
  })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "app" {
  name        = "web-app-eb-instance-sg"
  description = "Elastic Beanstalk EC2 instances: HTTP/HTTPS from the internet, unrestricted egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Unrestricted egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "web-app-eb-instance-sg"
  })
}

resource "aws_security_group" "rds" {
  name        = "web-app-rds-sg"
  description = "RDS PostgreSQL: access restricted to the Elastic Beanstalk instances only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from the application security group only"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  egress {
    description = "Unrestricted egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "web-app-rds-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM: Elastic Beanstalk service role and EC2 instance role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_service" {
  name = "web-app-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "web-app-eb-service-role"
  })
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

resource "aws_iam_role" "eb_ec2" {
  name = "web-app-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "web-app-eb-ec2-role"
  })
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer" {
  role       = aws_iam_role.eb_ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_role_policy" "eb_ec2_rds_secret" {
  name = "web-app-rds-secret-read"
  role = aws_iam_role.eb_ec2.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadRdsMasterCredentials"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = aws_secretsmanager_secret.rds.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2" {
  name = "web-app-eb-ec2-profile"
  role = aws_iam_role.eb_ec2.name

  tags = merge(local.common_tags, {
    Name = "web-app-eb-ec2-profile"
  })
}

# -----------------------------------------------------------------------------
# RDS master credentials (no plaintext secrets in configuration)
# -----------------------------------------------------------------------------

resource "random_password" "rds_master" {
  length  = 32
  special = false
}

resource "random_string" "cname_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_secretsmanager_secret" "rds" {
  name                    = "web-app/rds/master-credentials"
  description             = "Master credentials for the web-app RDS PostgreSQL instance"
  recovery_window_in_days = 0

  tags = merge(local.common_tags, {
    Name = "web-app-rds-secret"
  })
}

resource "aws_secretsmanager_secret_version" "rds" {
  secret_id = aws_secretsmanager_secret.rds.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.rds_master.result
  })
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "web-app-db-subnet-group"
  subnet_ids = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  tags = merge(local.common_tags, {
    Name = "web-app-db-subnet-group"
  })
}

resource "aws_db_instance" "main" {
  identifier     = "web-app-db"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.rds_master.result
  port     = 5432

  db_subnet_group_name       = aws_db_subnet_group.main.name
  vpc_security_group_ids     = [aws_security_group.rds.id]
  parameter_group_name       = "default.postgres16"
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  publicly_accessible = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "web-app-db-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "web-app-db"
  })
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "web" {
  name        = "web-app"
  description = "Web application deployed on AWS Elastic Beanstalk"

  tags = merge(local.common_tags, {
    Name = "web-app-eb-application"
  })
}

resource "aws_elastic_beanstalk_environment" "web" {
  name                = "web-app-env"
  application         = aws_elastic_beanstalk_application.web.name
  description         = "WebServer tier environment running Python 3.12 on Amazon Linux 2023"
  cname_prefix        = "web-app-env-${random_string.cname_suffix.result}"
  solution_stack_name = "64bit Amazon Linux 2023 v4.1.0 running Python 3.12"
  tier                = "WebServer"

  wait_for_ready_timeout = "45m"

  tags = merge(local.common_tags, {
    Name = "web-app-eb-environment"
  })

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceTypes"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_1.id, aws_subnet.public_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_1.id, aws_subnet.public_2.id])
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "TUE:02:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "InstanceRefreshEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.rds.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer,
    aws_iam_role_policy.eb_ec2_rds_secret,
    aws_secretsmanager_secret_version.rds,
    aws_db_instance.main,
    aws_internet_gateway.main,
    aws_route_table.public,
    aws_route_table_association.public_1,
    aws_route_table_association.public_2,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static provider metadata (permitted pure lookups)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  db_master_username = "dbadmin"
  public_subnet_ids  = [aws_subnet.eb_subnet_public_1.id, aws_subnet.eb_subnet_public_2.id]
}

###############################################################################
# Credential generation and uniqueness helpers
###############################################################################

resource "random_password" "shared_rds_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_string" "eb_env_1_suffix" {
  length  = 6
  special = false
  upper   = false
}

resource "random_string" "eb_env_2_suffix" {
  length  = 6
  special = false
  upper   = false
}

###############################################################################
# Networking: VPC, Internet Gateway, public subnets, routing
###############################################################################

resource "aws_vpc" "eb_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "eb_vpc"
  }
}

resource "aws_internet_gateway" "eb_igw" {
  vpc_id = aws_vpc.eb_vpc.id

  tags = {
    Name = "eb_igw"
  }
}

resource "aws_subnet" "eb_subnet_public_1" {
  vpc_id                  = aws_vpc.eb_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb_subnet_public_1"
  }
}

resource "aws_subnet" "eb_subnet_public_2" {
  vpc_id                  = aws_vpc.eb_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "eb_subnet_public_2"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.eb_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eb_igw.id
  }

  tags = {
    Name = "eb_public_route_table"
  }
}

resource "aws_route_table_association" "eb_subnet_public_1" {
  subnet_id      = aws_subnet.eb_subnet_public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "eb_subnet_public_2" {
  subnet_id      = aws_subnet.eb_subnet_public_2.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "eb_env_sg" {
  name        = "eb_env_sg"
  description = "Security group attached to both Elastic Beanstalk environments (web tier)"
  vpc_id      = aws_vpc.eb_vpc.id

  tags = {
    Name = "eb_env_sg"
  }
}

resource "aws_security_group_rule" "eb_env_sg_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group_rule" "eb_env_sg_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group_rule" "eb_env_sg_egress_all" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.eb_env_sg.id
}

resource "aws_security_group" "shared_rds_sg" {
  name        = "shared_rds_sg"
  description = "Security group for the shared_rds PostgreSQL database, ingress restricted to eb_env_sg"
  vpc_id      = aws_vpc.eb_vpc.id

  tags = {
    Name = "shared_rds_sg"
  }
}

resource "aws_security_group_rule" "shared_rds_sg_ingress_from_eb" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.eb_env_sg.id
  security_group_id        = aws_security_group.shared_rds_sg.id
}

###############################################################################
# Secrets Manager: RDS master credentials (never in plaintext/variables/locals)
###############################################################################

resource "aws_secretsmanager_secret" "shared_rds_master" {
  name        = "shared-rds-master-credentials"
  description = "Master credentials for the shared_rds PostgreSQL instance consumed by the Elastic Beanstalk environments"

  tags = {
    Name = "shared_rds_master_credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "shared_rds_master" {
  secret_id = aws_secretsmanager_secret.shared_rds_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.shared_rds_master_password.result
  })
}

###############################################################################
# Shared RDS database
###############################################################################

resource "aws_db_subnet_group" "shared_rds" {
  name        = "shared-rds-subnet-group"
  description = "DB subnet group spanning eb_subnet_public_1 and eb_subnet_public_2 across two AZs"
  subnet_ids  = local.public_subnet_ids

  tags = {
    Name = "shared_rds_subnet_group"
  }
}

resource "aws_db_instance" "shared_rds" {
  identifier     = "shared-rds"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "shared_rds"
  port     = 5432
  username = jsondecode(aws_secretsmanager_secret_version.shared_rds_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.shared_rds_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.shared_rds.name
  vpc_security_group_ids = [aws_security_group.shared_rds_sg.id]
  publicly_accessible    = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = true

  tags = {
    Name = "shared_rds"
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Elastic Beanstalk application and IAM prerequisites
###############################################################################

resource "aws_elastic_beanstalk_application" "eb_app" {
  name        = "shared-rds-app"
  description = "Parent application hosting the two Elastic Beanstalk environments backed by the shared_rds database"

  tags = {
    Name = "shared-rds-app"
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2AssumeRole"
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eb-ec2-role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "eb-instance-profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_service_linked_role" "eb_service_linked" {
  aws_service_name = "elasticbeanstalk.amazonaws.com"
  description      = "Service-linked role for Elastic Beanstalk"
}

###############################################################################
# Elastic Beanstalk environment 1
###############################################################################

resource "aws_elastic_beanstalk_environment" "eb_env_1" {
  name                = "eb-env-1-${random_string.eb_env_1_suffix.result}"
  description         = "Elastic Beanstalk environment 1 connected to the shared_rds PostgreSQL database"
  application         = aws_elastic_beanstalk_application.eb_app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.1 running Python 3.12"
  cname_prefix        = "eb-env-1-${random_string.eb_env_1_suffix.result}"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.eb_vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_env_sg.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.shared_rds.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.shared_rds.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.shared_rds.db_name
  }

  tags = {
    Name = "eb_env_1"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_service_linked_role.eb_service_linked,
  ]
}

###############################################################################
# Elastic Beanstalk environment 2
###############################################################################

resource "aws_elastic_beanstalk_environment" "eb_env_2" {
  name                = "eb-env-2-${random_string.eb_env_2_suffix.result}"
  description         = "Elastic Beanstalk environment 2 connected to the shared_rds PostgreSQL database"
  application         = aws_elastic_beanstalk_application.eb_app.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.0.1 running Python 3.12"
  cname_prefix        = "eb-env-2-${random_string.eb_env_2_suffix.result}"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VpcId"
    value     = aws_vpc.eb_vpc.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.eb_env_sg.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.shared_rds.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = aws_db_instance.shared_rds.port
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.shared_rds.db_name
  }

  tags = {
    Name = "eb_env_2"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_service_linked_role.eb_service_linked,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "eb_env_1_url" {
  description = "Public DNS name of Elastic Beanstalk environment 1"
  value       = aws_elastic_beanstalk_environment.eb_env_1.cname
}

output "eb_env_2_url" {
  description = "Public DNS name of Elastic Beanstalk environment 2"
  value       = aws_elastic_beanstalk_environment.eb_env_2.cname
}

output "shared_rds_endpoint" {
  description = "Connection endpoint of the shared_rds PostgreSQL instance"
  value       = aws_db_instance.shared_rds.address
}

output "shared_rds_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the shared_rds master credentials"
  value       = aws_secretsmanager_secret.shared_rds_master.arn
}

###############################################################################
# Terraform + Provider
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static, local-only lookups (no dependency on pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Input variables — the only user-controlled values in this configuration
###############################################################################

variable "record_fqdn" {
  description = "Fully qualified domain name that the A record maps to the target IPv4 address (e.g. app.example.com)."
  type        = string
  default     = "app.example.com"
}

variable "parent_domain" {
  description = "Parent domain for the public Route 53 hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

variable "ipv4_address" {
  description = "Target IPv4 address the record resolves to (e.g. 203.0.113.10)."
  type        = string
  default     = "203.0.113.10"

  validation {
    condition     = can(cidrnetmask("${var.ipv4_address}/32"))
    error_message = "ipv4_address must be a valid IPv4 address (e.g. 203.0.113.10)."
  }
}

variable "environment" {
  description = "Environment name used for the Environment tag."
  type        = string
  default     = "production"
}

###############################################################################
# Locals
###############################################################################

locals {
  parent_domain_normalized = trimsuffix(var.parent_domain, ".")

  common_tags = {
    Name        = local.parent_domain_normalized
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  # Route 53 KSK names may only contain letters, digits, and underscores.
  ksk_name = replace(local.parent_domain_normalized, ".", "_")

  # Customer-managed KMS key policy for Route 53 DNSSEC signing.
  # The key must be an asymmetric ECC_NIST_P256 SIGN_VERIFY key; asymmetric
  # keys do not support automatic rotation, so enable_key_rotation stays off.
  route53_dnssec_key_policy = jsonencode({
    Version = "2012-10-17"
    Id      = "route53-dnssec-key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:DescribeKey",
          "kms:DisableKey",
          "kms:EnableKey",
          "kms:GetKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:GetPublicKey",
          "kms:ListKeyPolicies",
          "kms:ListResourceTags",
          "kms:PutKeyPolicy",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:UpdateKeyDescription"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow Route 53 DNSSEC Service"
        Effect = "Allow"
        Principal = {
          Service = "dnssec-route53.amazonaws.com"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetPublicKey",
          "kms:Sign"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

###############################################################################
# Public hosted zone for the parent domain
###############################################################################

resource "aws_route53_zone" "main" {
  name = var.parent_domain

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# A record: <record_fqdn> -> <ipv4_address>
#
# Omitting any routing-policy block selects the SIMPLE routing policy.
# Note: AWS Route 53 does not support tagging individual DNS record sets
# (the TagResource API only accepts hosted zones and health checks), so the
# consistent tag set is applied to the hosted zone and KMS key resources.
###############################################################################

resource "aws_route53_record" "main" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.record_fqdn
  type    = "A"
  ttl     = 300
  records = [var.ipv4_address]
}

###############################################################################
# DNSSEC signing: customer-managed KMS key + key signing key + activation
###############################################################################

resource "aws_kms_key" "dnssec_signing" {
  description              = "Route 53 DNSSEC signing key for ${local.parent_domain_normalized}"
  customer_master_key_spec = "ECC_NIST_P256"
  key_usage                = "SIGN_VERIFY"
  deletion_window_in_days  = 30
  policy                   = local.route53_dnssec_key_policy

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_key_signing_key" "main" {
  hosted_zone_id             = aws_route53_zone.main.zone_id
  key_management_service_arn = aws_kms_key.dnssec_signing.arn
  name                       = local.ksk_name
  status                     = "ACTIVE"
}

resource "aws_route53_hosted_zone_dnssec" "main" {
  hosted_zone_id = aws_route53_zone.main.zone_id
  signing_status = "SIGNING"

  depends_on = [aws_route53_key_signing_key.main]
}

###############################################################################
# Outputs
###############################################################################

output "hosted_zone_name_servers" {
  description = "Name servers of the public hosted zone. Configure these as the NS records for the parent domain at the registrar after apply."
  value       = aws_route53_zone.main.name_servers
}

output "record_fqdn" {
  description = "Fully qualified domain name of the A record managed by this configuration."
  value       = aws_route53_record.main.fqdn
}

output "hosted_zone_dnssec_ds_record" {
  description = "DS record contents to register with the domain registrar to complete DNSSEC delegation."
  value       = aws_route53_key_signing_key.main.ds_record
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Root domain name for the public Route 53 hosted zone."
  type        = string
  default     = "example.com"

  validation {
    condition     = can(regex("^([a-z0-9]([a-z0-9-]*[a-z0-9])?\\.)+[a-z]{2,}$", var.domain_name))
    error_message = "domain_name must be a valid domain name, e.g. example.com."
  }
}

variable "ipv6_address" {
  description = "IPv6 address that the AAAA record maps the domain name to."
  type        = string
  default     = "2001:db8::1"

  validation {
    condition     = can(cidrhost("${var.ipv6_address}/128", 0))
    error_message = "ipv6_address must be a single valid IPv6 address, e.g. 2001:db8::1."
  }
}

variable "environment" {
  description = "Environment name applied as a tag for traceability."
  type        = string
  default     = "production"
}

locals {
  zone_name = lower(var.domain_name)
}

resource "aws_route53_zone" "main" {
  name = local.zone_name

  tags = {
    Name        = local.zone_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "ipv6_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.zone_name
  type    = "AAAA"
  ttl     = 300
  records = [var.ipv6_address]
}

output "hosted_zone_id" {
  description = "ID of the public hosted zone."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers to delegate the domain to at the registrar."
  value       = aws_route53_zone.main.name_servers
}

output "ipv6_record_fqdn" {
  description = "Fully qualified domain name of the AAAA record."
  value       = aws_route53_record.ipv6_aaaa.fqdn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  zone_domain      = "host.example53.com"
  ptr_pointer_name = "1"
  ptr_target_fqdn  = "host.example53.com."
  environment      = "production"
}

# Public hosted zone used for reverse DNS pointers.
# A public zone is used (no vpc block) because this greenfield account
# has no pre-existing VPC to associate with a private zone.
resource "aws_route53_zone" "reverse_zone" {
  name = local.zone_domain

  comment = "Reverse DNS hosted zone for ${local.zone_domain}"

  tags = {
    Name        = "reverse_zone"
    Environment = local.environment
    Purpose     = "reverse-dns"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# PTR (pointer) record following reverse-DNS conventions:
# the pointer name is the host octet ("1") under the zone domain,
# mapping back to the canonical FQDN host.example53.com.
resource "aws_route53_record" "reverse_ptr" {
  zone_id = aws_route53_zone.reverse_zone.zone_id
  name    = "${local.ptr_pointer_name}.${aws_route53_zone.reverse_zone.name}"
  type    = "PTR"
  ttl     = 300
  records = [local.ptr_target_fqdn]
}

output "reverse_zone_id" {
  description = "The zone ID of the reverse DNS hosted zone."
  value       = aws_route53_zone.reverse_zone.zone_id
}

output "reverse_zone_name_servers" {
  description = "The name servers of the reverse DNS hosted zone, for downstream NS delegation."
  value       = aws_route53_zone.reverse_zone.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Purpose   = "domain-ownership-verification"
      ManagedBy = "terraform"
    }
  }
}

variable "verification_string" {
  description = "Public TXT record value used for domain ownership verification. TXT records are publicly readable by design, so a plain-text default is compliant and this is not a secret."
  type        = string
  default     = "passwordpassword"
}

locals {
  # Route 53 TXT record values must be wrapped in embedded double quotes.
  domain_verification_txt = "\"${var.verification_string}\""
}

resource "aws_route53_zone" "example" {
  name = "example"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "domain_verification" {
  zone_id = aws_route53_zone.example.zone_id
  name    = aws_route53_zone.example.name
  type    = "TXT"
  ttl     = 300

  records = [local.domain_verification_txt]
}

output "hosted_zone_id" {
  description = "Zone ID of the example Route 53 hosted zone."
  value       = aws_route53_zone.example.zone_id
}

output "hosted_zone_name_servers" {
  description = "Delegation name servers assigned to the example hosted zone."
  value       = aws_route53_zone.example.name_servers
}

output "verification_record_fqdn" {
  description = "FQDN of the TXT record used for domain ownership verification."
  value       = aws_route53_record.domain_verification.fqdn
}

output "verification_record_value" {
  description = "TXT value that must be present at the zone apex for domain ownership verification."
  value       = local.domain_verification_txt
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables: non-infrastructure values only, all defaulted for unattended apply
# -----------------------------------------------------------------------------
variable "domain_name" {
  description = "Root domain name to manage in Route 53. The domain must be registered with an external registrar and delegated to the hosted zone."
  type        = string
  default     = "example.com"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "db_engine" {
  description = "Database engine for the RDS instance (postgres or mysql)."
  type        = string
  default     = "postgres"
}

variable "db_engine_version" {
  description = "Database engine version for the RDS instance."
  type        = string
  default     = "15.5"
}

# -----------------------------------------------------------------------------
# Locals and static provider metadata
# -----------------------------------------------------------------------------
locals {
  common_tags = {
    Environment = var.environment
    Project     = "myapp"
    ManagedBy   = "terraform"
  }

  # RDS listen port derived from the selected engine (never exposed publicly)
  db_port = var.db_engine == "mysql" ? 3306 : 5432

  public_subnets  = [aws_subnet.public_1.id, aws_subnet.public_2.id]
  private_subnets = [aws_subnet.private_1.id, aws_subnet.private_2.id]
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking foundation (greenfield - everything created in this file)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "myapp-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "myapp-igw" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "myapp-public-subnet-1", Tier = "public" })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "myapp-public-subnet-2", Tier = "public" })
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "myapp-private-subnet-1", Tier = "private" })
}

resource "aws_subnet" "private_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "myapp-private-subnet-2", Tier = "private" })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "myapp-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_1.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "myapp-nat-gateway" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "myapp-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "myapp-private-rt" })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Route 53: hosted zone and record routing traffic to the Beanstalk environment
# -----------------------------------------------------------------------------
resource "aws_route53_zone" "main" {
  name = var.domain_name

  # The domain must be registered externally (e.g. with a domain registrar).
  # Delegate the domain to the name servers of this hosted zone (see the
  # route53_name_servers output) so DNS traffic resolves through Route 53.
  comment = "Public hosted zone for ${var.domain_name}. The domain must be registered externally and its name servers delegated to this zone."

  tags = merge(local.common_tags, {
    Name        = var.domain_name
    Environment = var.environment
  })
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "app.${var.domain_name}"
  type    = "CNAME"
  ttl     = 300

  records = [aws_elastic_beanstalk_environment.myenv.cname]
}

# -----------------------------------------------------------------------------
# IAM execution stack for Beanstalk EC2 instances
# -----------------------------------------------------------------------------
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

# Least-privilege inline policy: instances may read ONLY the DB credentials secret.
# The secret is fetched at runtime by the application via the instance profile
# instead of embedding the password in environment variables.
resource "aws_iam_role_policy" "eb_secrets_read" {
  name = "eb-secrets-read"
  role = aws_iam_role.eb_ec2_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------
resource "aws_security_group" "eb_ec2" {
  name        = "myapp-eb-ec2-sg"
  description = "Elastic Beanstalk EC2 instances: public web traffic on 80/443 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (public web traffic)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (public web traffic)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "myapp-eb-ec2-sg" })
}

resource "aws_security_group" "rds" {
  name        = "myapp-rds-sg"
  description = "myapp_db database: reachable only from the Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Database port from Beanstalk EC2 instances only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_ec2.id]
  }

  tags = merge(local.common_tags, { Name = "myapp-rds-sg" })
}

# -----------------------------------------------------------------------------
# Database subnet group (private subnets across two AZs)
# -----------------------------------------------------------------------------
resource "aws_db_subnet_group" "myapp_db_subnets" {
  name        = "myapp-db-subnet-group"
  description = "Private subnets across two AZs for myapp_db"
  subnet_ids  = local.private_subnets

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Database credentials: generated, never hardcoded, stored in Secrets Manager
# -----------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "myapp/db/credentials"
  description             = "Master credentials for the myapp-db RDS instance"
  recovery_window_in_days = 7

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = "myappadmin"
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# RDS instance
# Naming rules differ for the two "name-like" attributes of an RDS instance:
#   - identifier: AWS resource name, permits ONLY lowercase alphanumeric
#     characters and hyphens (no underscores) -> "myapp-db".
#   - db_name: PostgreSQL database name, permits lowercase letters, digits,
#     and underscores -> "myapp_db" (satisfies the requested database name).
# Do NOT "fix" db_name to hyphen form, and do NOT regress identifier to
# underscore form when trying to satisfy the "myapp_db" naming requirement.
# -----------------------------------------------------------------------------
resource "aws_db_instance" "myapp_db" {
  identifier     = "myapp-db"
  db_name        = "myapp_db"
  engine         = var.db_engine
  engine_version = var.db_engine_version
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_encrypted     = true

  username = "myappadmin"
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.myapp_db_subnets.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "myapp-db-final-snapshot"

  tags = merge(local.common_tags, { Name = "myapp_db" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and environment
# -----------------------------------------------------------------------------
resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "Elastic Beanstalk application serving the myapp web tier, backed by myapp_db"

  tags = local.common_tags
}

resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.1 running Python 3.11"

  tags = merge(local.common_tags, { Name = "myenv" })

  # --- Launch configuration: instance profile and EC2 security groups ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile1.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.micro"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_ec2.id
  }

  # --- VPC placement: EC2 in private subnets, ALB in public subnets ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnets)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnets)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "internet-facing"
  }

  # --- Load-balanced environment with an internet-facing ALB ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  # --- Enhanced health reporting so Route 53 traffic only hits healthy hosts ---
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckPath"
    value     = "/"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckProtocol"
    value     = "HTTP"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckPort"
    value     = "80"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckInterval"
    value     = "15"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthCheckTimeout"
    value     = "5"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "HealthyThresholdCount"
    value     = "3"
  }

  setting {
    namespace = "aws:elbv2:healthcheck"
    name      = "UnhealthyThresholdCount"
    value     = "3"
  }

  # --- Auto Scaling bounds ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  # --- Application environment: database connectivity via attribute references.
  #     The password is NEVER injected here; instances fetch it at runtime from
  #     Secrets Manager (ARN below) using the instance profile's IAM policy. ---
  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.myapp_db.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.myapp_db.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.myapp_db.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_credentials.arn
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "route53_record_fqdn" {
  description = "FQDN of the Route 53 record routing traffic to the Elastic Beanstalk environment"
  value       = aws_route53_record.app.fqdn
}

output "beanstalk_environment_cname" {
  description = "CNAME endpoint of the myenv Elastic Beanstalk environment"
  value       = aws_elastic_beanstalk_environment.myenv.cname
}

output "rds_endpoint" {
  description = "Connection endpoint of the myapp-db RDS instance hosting the myapp_db database"
  value       = aws_db_instance.myapp_db.endpoint
}

output "route53_name_servers" {
  description = "Name servers to which the externally registered domain must be delegated for Route 53 to serve DNS"
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu-west-1"
  region = "eu-west-1"
}

########################################################################
# Variables / locals
########################################################################

variable "domain_name" {
  description = "Public domain managed by the Route 53 hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

locals {
  solution_stack = "64bit Amazon Linux 2023 running Python 3.12"
  db_username    = "dbadmin"
  db_name        = "maindb"
  db_port        = 5432
  instance_type  = "t3.small"
}

########################################################################
# Availability zone discovery (static provider metadata only)
########################################################################

data "aws_availability_zones" "us" {
  provider = aws
  state    = "available"
}

data "aws_availability_zones" "eu_west" {
  provider = aws.eu-west-1
  state    = "available"
}

########################################################################
# Shared IAM (global service): EC2 instance profile + EB service role
########################################################################

data "aws_iam_policy_document" "eb_ec2_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eb_service_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["elasticbeanstalk.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eb_ec2_role" {
  name               = "eb_ec2_role"
  description        = "Elastic Beanstalk EC2 instance role (shared by both regional environments)"
  assume_role_policy = data.aws_iam_policy_document.eb_ec2_trust.json
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile3" {
  name = "eb_ec2_profile3"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role" "eb_service_role" {
  name               = "eb_service_role"
  description        = "Elastic Beanstalk service role (enhanced health, managed updates)"
  assume_role_policy = data.aws_iam_policy_document.eb_service_trust.json
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

########################################################################
# Network foundation - us-east-1 (default provider)
########################################################################

resource "aws_vpc" "us" {
  provider             = aws
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "myapp-us-east-vpc" }
}

resource "aws_internet_gateway" "us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  tags = { Name = "myapp-us-east-igw" }
}

resource "aws_subnet" "public_us_1" {
  provider                = aws
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.us.names[0]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-us-east-public-a" }
}

resource "aws_subnet" "public_us_2" {
  provider                = aws
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.us.names[1]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-us-east-public-b" }
}

resource "aws_subnet" "private_db_us_1" {
  provider          = aws
  vpc_id            = aws_vpc.us.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = data.aws_availability_zones.us.names[0]

  tags = { Name = "myapp-us-east-private-db-a" }
}

resource "aws_subnet" "private_db_us_2" {
  provider          = aws
  vpc_id            = aws_vpc.us.id
  cidr_block        = "10.0.12.0/24"
  availability_zone = data.aws_availability_zones.us.names[1]

  tags = { Name = "myapp-us-east-private-db-b" }
}

resource "aws_route_table" "public_us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us.id
  }

  tags = { Name = "myapp-us-east-public-rt" }
}

resource "aws_route_table_association" "public_us_1" {
  provider       = aws
  subnet_id      = aws_subnet.public_us_1.id
  route_table_id = aws_route_table.public_us.id
}

resource "aws_route_table_association" "public_us_2" {
  provider       = aws
  subnet_id      = aws_subnet.public_us_2.id
  route_table_id = aws_route_table.public_us.id
}

# Isolated route table for the private database subnets (no internet routes).
resource "aws_route_table" "private_db_us" {
  provider = aws
  vpc_id   = aws_vpc.us.id

  tags = { Name = "myapp-us-east-private-db-rt" }
}

resource "aws_route_table_association" "private_db_us_1" {
  provider       = aws
  subnet_id      = aws_subnet.private_db_us_1.id
  route_table_id = aws_route_table.private_db_us.id
}

resource "aws_route_table_association" "private_db_us_2" {
  provider       = aws
  subnet_id      = aws_subnet.private_db_us_2.id
  route_table_id = aws_route_table.private_db_us.id
}

########################################################################
# Network foundation - eu-west-1 (aliased provider)
########################################################################

resource "aws_vpc" "eu" {
  provider             = aws.eu-west-1
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "myapp-eu-west-vpc" }
}

resource "aws_internet_gateway" "eu" {
  provider = aws.eu-west-1
  vpc_id   = aws_vpc.eu.id

  tags = { Name = "myapp-eu-west-igw" }
}

resource "aws_subnet" "public_eu_1" {
  provider                = aws.eu-west-1
  vpc_id                  = aws_vpc.eu.id
  cidr_block              = "10.1.1.0/24"
  availability_zone       = data.aws_availability_zones.eu_west.names[0]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-eu-west-public-a" }
}

resource "aws_subnet" "public_eu_2" {
  provider                = aws.eu-west-1
  vpc_id                  = aws_vpc.eu.id
  cidr_block              = "10.1.2.0/24"
  availability_zone       = data.aws_availability_zones.eu_west.names[1]
  map_public_ip_on_launch = true

  tags = { Name = "myapp-eu-west-public-b" }
}

resource "aws_subnet" "private_db_eu_1" {
  provider          = aws.eu-west-1
  vpc_id            = aws_vpc.eu.id
  cidr_block        = "10.1.11.0/24"
  availability_zone = data.aws_availability_zones.eu_west.names[0]

  tags = { Name = "myapp-eu-west-private-db-a" }
}

resource "aws_subnet" "private_db_eu_2" {
  provider          = aws.eu-west-1
  vpc_id            = aws_vpc.eu.id
  cidr_block        = "10.1.12.0/24"
  availability_zone = data.aws_availability_zones.eu_west.names[1]

  tags = { Name = "myapp-eu-west-private-db-b" }
}

resource "aws_route_table" "public_eu" {
  provider = aws.eu-west-1
  vpc_id   = aws_vpc.eu.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.eu.id
  }

  tags = { Name = "myapp-eu-west-public-rt" }
}

resource "aws_route_table_association" "public_eu_1" {
  provider       = aws.eu-west-1
  subnet_id      = aws_subnet.public_eu_1.id
  route_table_id = aws_route_table.public_eu.id
}

resource "aws_route_table_association" "public_eu_2" {
  provider       = aws.eu-west-1
  subnet_id      = aws_subnet.public_eu_2.id
  route_table_id = aws_route_table.public_eu.id
}

# Isolated route table for the private database subnets (no internet routes).
resource "aws_route_table" "private_db_eu" {
  provider = aws.eu-west-1
  vpc_id   = aws_vpc.eu.id

  tags = { Name = "myapp-eu-west-private-db-rt" }
}

resource "aws_route_table_association" "private_db_eu_1" {
  provider       = aws.eu-west-1
  subnet_id      = aws_subnet.private_db_eu_1.id
  route_table_id = aws_route_table.private_db_eu.id
}

resource "aws_route_table_association" "private_db_eu_2" {
  provider       = aws.eu-west-1
  subnet_id      = aws_subnet.private_db_eu_2.id
  route_table_id = aws_route_table.private_db_eu.id
}

########################################################################
# Security groups - us-east-1
########################################################################

resource "aws_security_group" "eb_instance_us" {
  provider    = aws
  name        = "myapp-eb-instance-us-east"
  description = "Elastic Beanstalk EC2 instances (us-east-1): web ports only"
  vpc_id      = aws_vpc.us.id

  ingress {
    description = "HTTP from anywhere (web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "myapp-eb-instance-us-east" }
}

resource "aws_security_group" "rds_us" {
  provider    = aws
  name        = "myapp-rds-us-east"
  description = "RDS PostgreSQL (us-east-1): reachable only from Beanstalk instances"
  vpc_id      = aws_vpc.us.id

  ingress {
    description     = "PostgreSQL from Beanstalk instances only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instance_us.id]
  }

  tags = { Name = "myapp-rds-us-east" }
}

########################################################################
# Security groups - eu-west-1
########################################################################

resource "aws_security_group" "eb_instance_eu" {
  provider    = aws.eu-west-1
  name        = "myapp-eb-instance-eu-west"
  description = "Elastic Beanstalk EC2 instances (eu-west-1): web ports only"
  vpc_id      = aws_vpc.eu.id

  ingress {
    description = "HTTP from anywhere (web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "myapp-eb-instance-eu-west" }
}

resource "aws_security_group" "rds_eu" {
  provider    = aws.eu-west-1
  name        = "myapp-rds-eu-west"
  description = "RDS PostgreSQL (eu-west-1): reachable only from Beanstalk instances"
  vpc_id      = aws_vpc.eu.id

  ingress {
    description     = "PostgreSQL from Beanstalk instances only"
    from_port       = local.db_port
    to_port         = local.db_port
    protocol        = "tcp"
    security_groups = [aws_security_group.eb_instance_eu.id]
  }

  tags = { Name = "myapp-rds-eu-west" }
}

########################################################################
# Database credentials in Secrets Manager (no plaintext passwords)
########################################################################

resource "random_password" "db_us" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_us" {
  provider                = aws
  name                    = "myapp/rds/main_db_us_east"
  description             = "Master credentials for main_db_us_east (us-east-1)"
  recovery_window_in_days = 0

  tags = { Name = "myapp-rds-main_db_us_east" }
}

resource "aws_secretsmanager_secret_version" "db_us" {
  provider  = aws
  secret_id = aws_secretsmanager_secret.db_us.arn

  secret_string = jsonencode({
    username = aws_db_instance.main_db_us_east.username
    password = random_password.db_us.result
    engine   = "postgres"
    host     = aws_db_instance.main_db_us_east.address
    port     = aws_db_instance.main_db_us_east.port
    dbname   = aws_db_instance.main_db_us_east.db_name
  })
}

resource "random_password" "db_eu_west" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "db_eu_west" {
  provider                = aws.eu-west-1
  name                    = "myapp/rds/main_db_eu_west"
  description             = "Master credentials for main_db_eu_west (eu-west-1)"
  recovery_window_in_days = 0

  tags = { Name = "myapp-rds-main_db_eu_west" }
}

resource "aws_secretsmanager_secret_version" "db_eu_west" {
  provider  = aws.eu-west-1
  secret_id = aws_secretsmanager_secret.db_eu_west.arn

  secret_string = jsonencode({
    username = aws_db_instance.main_db_eu_west.username
    password = random_password.db_eu_west.result
    engine   = "postgres"
    host     = aws_db_instance.main_db_eu_west.address
    port     = aws_db_instance.main_db_eu_west.port
    dbname   = aws_db_instance.main_db_eu_west.db_name
  })
}

########################################################################
# DB subnet groups (each spans two AZs using private subnets)
########################################################################

resource "aws_db_subnet_group" "db_us" {
  provider    = aws
  name        = "main-db-subnet-group-us-east"
  description = "Private subnets for main_db_us_east"
  subnet_ids  = [aws_subnet.private_db_us_1.id, aws_subnet.private_db_us_2.id]

  tags = { Name = "main-db-subnet-group-us-east" }
}

resource "aws_db_subnet_group" "db_eu_west" {
  provider    = aws.eu-west-1
  name        = "main-db-subnet-group-eu-west"
  description = "Private subnets for main_db_eu_west"
  subnet_ids  = [aws_subnet.private_db_eu_1.id, aws_subnet.private_db_eu_2.id]

  tags = { Name = "main-db-subnet-group-eu-west" }
}

########################################################################
# RDS PostgreSQL instances
########################################################################

resource "aws_db_instance" "main_db_us_east" {
  provider                   = aws
  identifier                 = "main-db-us-east"
  engine                     = "postgres"
  instance_class             = "db.t3.small"
  allocated_storage          = 20
  storage_type               = "gp3"
  max_allocated_storage      = 100
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db_us.result
  port                       = local.db_port
  db_subnet_group_name       = aws_db_subnet_group.db_us.name
  vpc_security_group_ids     = [aws_security_group.rds_us.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  deletion_protection        = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  skip_final_snapshot        = true

  tags = {
    Name   = "main_db_us_east"
    Region = "us-east-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "main_db_eu_west" {
  provider                   = aws.eu-west-1
  identifier                 = "main-db-eu-west"
  engine                     = "postgres"
  instance_class             = "db.t3.small"
  allocated_storage          = 20
  storage_type               = "gp3"
  max_allocated_storage      = 100
  storage_encrypted          = true
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db_eu_west.result
  port                       = local.db_port
  db_subnet_group_name       = aws_db_subnet_group.db_eu_west.name
  vpc_security_group_ids     = [aws_security_group.rds_eu.id]
  publicly_accessible        = false
  multi_az                   = false
  backup_retention_period    = 7
  deletion_protection        = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  skip_final_snapshot        = true

  tags = {
    Name   = "main_db_eu_west"
    Region = "eu-west-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

########################################################################
# Elastic Beanstalk applications
########################################################################

resource "aws_elastic_beanstalk_application" "myapp_us_east" {
  provider    = aws
  name        = "myapp_us_east"
  description = "Multi-region application - us-east-1"
}

resource "aws_elastic_beanstalk_application" "myapp_eu_west" {
  provider    = aws.eu-west-1
  name        = "myapp_eu_west"
  description = "Multi-region application - eu-west-1"
}

########################################################################
# Elastic Beanstalk environments
########################################################################

resource "aws_elastic_beanstalk_environment" "myenv_us_east" {
  provider            = aws
  name                = "myenv_us_east"
  application         = aws_elastic_beanstalk_application.myapp_us_east.name
  description         = "Web environment (us-east-1)"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile3.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_us.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = local.instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.us.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_us_1.id, aws_subnet.public_us_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_us_1.id, aws_subnet.public_us_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main_db_us_east.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main_db_us_east.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main_db_us_east.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.main_db_us_east.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_us.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_secretsmanager_secret_version.db_us,
  ]
}

resource "aws_elastic_beanstalk_environment" "myenv_eu_west" {
  provider            = aws.eu-west-1
  name                = "myenv_eu_west"
  application         = aws_elastic_beanstalk_application.myapp_eu_west.name
  description         = "Web environment (eu-west-1)"
  solution_stack_name = local.solution_stack
  tier                = "WebServer"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile3.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_eu.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = local.instance_type
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "2"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "4"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.eu.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.public_eu_1.id, aws_subnet.public_eu_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_eu_1.id, aws_subnet.public_eu_2.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_HOSTNAME"
    value     = aws_db_instance.main_db_eu_west.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_PORT"
    value     = tostring(aws_db_instance.main_db_eu_west.port)
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_DB_NAME"
    value     = aws_db_instance.main_db_eu_west.db_name
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_USERNAME"
    value     = aws_db_instance.main_db_eu_west.username
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "RDS_SECRET_ARN"
    value     = aws_secretsmanager_secret.db_eu_west.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
    aws_secretsmanager_secret_version.db_eu_west,
  ]
}

########################################################################
# Route 53: hosted zone, health checks, regional routing records
########################################################################

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = "${var.domain_name}-zone"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "us_east" {
  fqdn              = aws_elastic_beanstalk_environment.myenv_us_east.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true

  tags = {
    Name = "myapp-us-east-health-check"
  }
}

resource "aws_route53_health_check" "eu_west" {
  fqdn              = aws_elastic_beanstalk_environment.myenv_eu_west.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true

  tags = {
    Name = "myapp-eu-west-health-check"
  }
}

resource "aws_route53_record" "us_east" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "us-east-1.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  records         = [aws_elastic_beanstalk_environment.myenv_us_east.cname]
  set_identifier  = "us-east-1"
  health_check_id = aws_route53_health_check.us_east.id

  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_route53_record" "eu_west" {
  zone_id         = aws_route53_zone.main.zone_id
  name            = "eu-west-1.${var.domain_name}"
  type            = "CNAME"
  ttl             = 60
  records         = [aws_elastic_beanstalk_environment.myenv_eu_west.cname]
  set_identifier  = "eu-west-1"
  health_check_id = aws_route53_health_check.eu_west.id

  failover_routing_policy {
    type = "SECONDARY"
  }
}

########################################################################
# Outputs
########################################################################

output "hosted_zone_id" {
  description = "Route 53 hosted zone ID."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers for the Route 53 hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "us_east_environment_cname" {
  description = "Public CNAME of the myenv_us_east Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myenv_us_east.cname
}

output "eu_west_environment_cname" {
  description = "Public CNAME of the myenv_eu_west Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.myenv_eu_west.cname
}

output "us_east_rds_endpoint" {
  description = "Connection endpoint of main_db_us_east."
  value       = aws_db_instance.main_db_us_east.endpoint
}

output "eu_west_rds_endpoint" {
  description = "Connection endpoint of main_db_eu_west."
  value       = aws_db_instance.main_db_eu_west.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "User-controlled public domain name used for the Route 53 hosted zone and failover records."
  type        = string
  default     = "example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_username        = "myapp_admin"
  private_subnet_ids = [aws_subnet.private_az0.id, aws_subnet.private_az1.id]
  public_subnet_ids  = [aws_subnet.public_az0.id, aws_subnet.public_az1.id]
  app_record_name    = "app.${var.domain_name}"
}

# -----------------------------------------------------------------------------
# Database credentials (Secrets Manager)
# -----------------------------------------------------------------------------

resource "random_password" "db_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 8
}

resource "aws_secretsmanager_secret" "myapp_db_credentials" {
  name        = "myapp_db_credentials"
  description = "Master credentials for the shared myapp_db RDS instance used by the blue and green environments."
}

resource "aws_secretsmanager_secret_version" "myapp_db_credentials" {
  secret_id = aws_secretsmanager_secret.myapp_db_credentials.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_password.result
    engine   = "postgres"
    port     = 5432
  })
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "myapp-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "myapp-igw"
  }
}

resource "aws_subnet" "public_az0" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "myapp-public-az0"
  }
}

resource "aws_subnet" "public_az1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "myapp-public-az1"
  }
}

resource "aws_subnet" "private_az0" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[0]
  cidr_block        = "10.0.11.0/24"

  tags = {
    Name = "myapp-private-az0"
  }
}

resource "aws_subnet" "private_az1" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[1]
  cidr_block        = "10.0.12.0/24"

  tags = {
    Name = "myapp-private-az1"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "myapp-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_az0.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "myapp-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "myapp-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "myapp-private-rt"
  }
}

resource "aws_route_table_association" "public_az0" {
  subnet_id      = aws_subnet.public_az0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_az0" {
  subnet_id      = aws_subnet.private_az0.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_az1" {
  subnet_id      = aws_subnet.private_az1.id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "app" {
  name        = "myapp-app-sg"
  description = "Ingress for the blue and green Elastic Beanstalk EC2 instances (HTTP/HTTPS only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "myapp-app-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "myapp-rds-sg"
  description = "PostgreSQL access restricted to the application security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from app instances"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = {
    Name = "myapp-rds-sg"
  }
}

# -----------------------------------------------------------------------------
# Shared RDS instance
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "myapp_db" {
  name       = "myapp_db"
  subnet_ids = local.private_subnet_ids

  tags = {
    Name = "myapp-db-subnet-group"
  }
}

resource "aws_db_instance" "myapp_db" {
  identifier     = "myapp-db"
  engine         = "postgres"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_encrypted     = true
  multi_az              = true
  publicly_accessible   = false

  username = jsondecode(aws_secretsmanager_secret_version.myapp_db_credentials.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.myapp_db_credentials.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.myapp_db.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true
  skip_final_snapshot     = false
  final_snapshot_identifier = "myapp-db-final-${random_id.db_final_snapshot.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "myapp_db"
  }
}

# -----------------------------------------------------------------------------
# IAM for Elastic Beanstalk EC2 instances
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = ""
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "eb_ec2_role"
  }
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application and blue/green environments
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "MyApp Elastic Beanstalk application hosting the blue and green environments"
}

resource "aws_elastic_beanstalk_environment" "blue" {
  name                = "blue"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "WebServer"
  cname_prefix        = "myapp-blue"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DATABASE_HOST"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.myapp_db_credentials.arn
  }

  depends_on = [
    aws_db_instance.myapp_db,
    aws_secretsmanager_secret_version.myapp_db_credentials,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

resource "aws_elastic_beanstalk_environment" "green" {
  name                = "green"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2023 v4.3.0 running Python 3.12"
  tier                = "WebServer"
  cname_prefix        = "myapp-green"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", local.private_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", local.public_subnet_ids)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "false"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "SecurityGroups"
    value     = aws_security_group.app.id
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t3.small"
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DATABASE_HOST"
    value     = aws_db_instance.myapp_db.address
  }

  setting {
    namespace = "aws:elasticbeanstalk:application:environment"
    name      = "DB_SECRET_ARN"
    value     = aws_secretsmanager_secret.myapp_db_credentials.arn
  }

  depends_on = [
    aws_db_instance.myapp_db,
    aws_secretsmanager_secret_version.myapp_db_credentials,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
  ]
}

# -----------------------------------------------------------------------------
# Route 53: hosted zone, health checks, and failover records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = {
    Name = "myapp-zone"
  }
}

resource "aws_route53_health_check" "blue" {
  fqdn              = aws_elastic_beanstalk_environment.blue.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = {
    Name = "myapp-blue-health-check"
  }
}

resource "aws_route53_health_check" "green" {
  fqdn              = aws_elastic_beanstalk_environment.green.cname
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = {
    Name = "myapp-green-health-check"
  }
}

resource "aws_route53_record" "myapp_primary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.app_record_name
  type    = "CNAME"
  ttl     = 60

  set_identifier = "primary"

  failover_routing_policy {
    type = "PRIMARY"
  }

  health_check_id = aws_route53_health_check.blue.id

  records = [aws_elastic_beanstalk_environment.blue.cname]
}

resource "aws_route53_record" "myapp_failover" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.app_record_name
  type    = "CNAME"
  ttl     = 60

  set_identifier = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }

  health_check_id = aws_route53_health_check.green.id

  records = [aws_elastic_beanstalk_environment.green.cname]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "blue_environment_cname" {
  description = "CNAME of the blue Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.blue.cname
}

output "green_environment_cname" {
  description = "CNAME of the green Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.green.cname
}

output "route53_record_fqdn" {
  description = "FQDN of the failover-enabled Route 53 record serving production traffic."
  value       = aws_route53_record.myapp_primary.fqdn
}

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the shared RDS instance."
  value       = aws_db_instance.myapp_db.endpoint
}

output "rds_endpoint_address" {
  description = "Address of the shared RDS instance."
  value       = aws_db_instance.myapp_db.address
}

output "rds_endpoint_port" {
  description = "Port of the shared RDS instance."
  value       = aws_db_instance.myapp_db.port
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  type        = string
  default     = "my-environment"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk EC2 instances."
  type        = string
  default     = "t3.small"
}

variable "solution_stack_name" {
  description = "Elastic Beanstalk solution stack (Amazon Linux 2023 running Python 3.12)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.3.1 running Python 3.12"
}

variable "common_tags" {
  description = "Common tags applied to all tagged resources."
  type        = map(string)
  default = {
    Project   = "elastic-beanstalk-webserver"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  numeric = true
  special = false
}

locals {
  public_subnet_ids = join(",", aws_subnet.public[*].id)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.common_tags, { Name = "eb-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.common_tags, { Name = "eb-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.common_tags, { Name = "eb-public-subnet-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.common_tags, { Name = "eb-public-route-table" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "eb_instance_sg" {
  name        = "eb-instance-sg"
  description = "Allow inbound HTTP from within the VPC only, for Elastic Beanstalk EC2 instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.common_tags, { Name = "eb-instance-sg" })
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_iam_role" "eb_service_role" {
  name = "eb_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_role_policy" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my_application"
  description = "My Elastic Beanstalk application for a Python web server"

  tags = var.common_tags
}

resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = var.environment_name
  application         = aws_elastic_beanstalk_application.my_application.name
  tier                = "WebServer"
  solution_stack_name = var.solution_stack_name
  cname_prefix        = "my-app-${random_string.suffix.result}"

  tags = var.common_tags

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instance_sg.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = local.public_subnet_ids
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_service_role_policy,
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
  ]
}

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk environment."
  value       = "http://${aws_elastic_beanstalk_environment.my_environment.cname}"
}

###############################################################################
# Elastic Beanstalk application template
#
# Greenfield, self-contained configuration: creates the full network
# foundation, IAM roles, artifacts bucket, application version bundle and a
# WebServer-tier Elastic Beanstalk environment running a minimal WSGI app.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables (user-controlled, non-infrastructure values)
###############################################################################

variable "project_name" {
  description = "Short project identifier used as the naming prefix for all resources."
  type        = string
  default     = "ebapp"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{1,18}[a-zA-Z0-9]$", var.project_name))
    error_message = "project_name must be 3-20 alphanumeric characters or hyphens, and cannot start or end with a hyphen."
  }
}

variable "environment_name" {
  description = "Logical environment name, e.g. dev, staging, prod."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{1,13}[a-zA-Z0-9]$", var.environment_name))
    error_message = "environment_name must be 3-15 alphanumeric characters or hyphens, and cannot start or end with a hyphen."
  }
}

variable "environment_type" {
  description = "Elastic Beanstalk environment layout. Valid values: LoadBalanced, SingleInstance."
  type        = string
  default     = "LoadBalanced"

  validation {
    condition     = contains(["LoadBalanced", "SingleInstance"], var.environment_type)
    error_message = "environment_type must be either LoadBalanced or SingleInstance."
  }
}

variable "instance_type" {
  description = "EC2 instance type used by the Elastic Beanstalk environment."
  type        = string
  default     = "t3.small"
}

variable "solution_stack" {
  description = "Elastic Beanstalk platform (solution stack) for the environment."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.5.0 running Python 3.11"
}

variable "tags" {
  description = "Additional tags merged over the default tag set."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = lower(replace("${var.project_name}-${var.environment_name}", "/[^a-zA-Z0-9-]/", "-"))

  is_load_balanced = var.environment_type == "LoadBalanced"

  common_tags = merge(
    {
      environment  = var.environment_name
      project      = var.project_name
      "managed-by" = "terraform"
    },
    var.tags
  )
}

###############################################################################
# Availability zone discovery (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group dedicated to the EB EC2 instances (HTTP/HTTPS ingress only)
###############################################################################

resource "aws_security_group" "eb_instances" {
  name        = "${local.name_prefix}-eb-instances"
  description = "Elastic Beanstalk EC2 instances - inbound HTTP/HTTPS only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-eb-instances" })
}

###############################################################################
# Elastic Beanstalk service role
###############################################################################

resource "aws_iam_role" "eb_service_role" {
  name = "${local.name_prefix}-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "elasticbeanstalk.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_instances" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedInstancesCustomerPolicy"
}

resource "aws_iam_role_policy_attachment" "eb_service" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkService"
}

resource "aws_iam_role_policy" "eb_service_passrole" {
  name = "${local.name_prefix}-eb-pass-instance-role"
  role = aws_iam_role.eb_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PassInstanceProfileRoleToElasticBeanstalk"
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = aws_iam_role.eb_ec2_role.arn
      }
    ]
  })
}

###############################################################################
# EC2 instance profile for the EB instances
###############################################################################

resource "aws_iam_role" "eb_ec2_role" {
  name = "${local.name_prefix}-eb-ec2-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "eb_ec2_web_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_worker_tier" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_role_policy_attachment" "eb_ec2_multicontainer_docker" {
  role       = aws_iam_role.eb_ec2_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkMulticontainerDocker"
}

resource "aws_iam_instance_profile" "eb_profile" {
  name = "${local.name_prefix}-eb-instance-profile"
  role = aws_iam_role.eb_ec2_role.name

  tags = local.common_tags
}

###############################################################################
# Dedicated S3 bucket for Elastic Beanstalk application versions
###############################################################################

resource "random_string" "suffix" {
  length  = 6
  lower   = true
  upper   = false
  special = false
}

resource "aws_s3_bucket" "eb_versions" {
  bucket = "${local.name_prefix}-eb-versions-${random_string.suffix.result}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-eb-versions" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  depends_on = [aws_s3_bucket_versioning.eb_versions]

  rule {
    id     = "expire-noncurrent-artifacts"
    status = "Enabled"
    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

resource "aws_s3_bucket_policy" "eb_versions" {
  bucket = aws_s3_bucket.eb_versions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowElasticBeanstalkInstancesRead"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_ec2_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource  = "${aws_s3_bucket.eb_versions.arn}/*"
      },
      {
        Sid       = "AllowElasticBeanstalkServiceAccess"
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.eb_service_role.arn }
        Action    = ["s3:GetObject", "s3:GetObjectVersion", "s3:ListBucket", "s3:GetBucketLocation"]
        Resource  = [aws_s3_bucket.eb_versions.arn, "${aws_s3_bucket.eb_versions.arn}/*"]
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.eb_versions,
    aws_s3_bucket_server_side_encryption_configuration.eb_versions,
    aws_s3_bucket_versioning.eb_versions,
    aws_s3_bucket_ownership_controls.eb_versions,
  ]
}

###############################################################################
# Application source bundle (generated locally, zipped, uploaded)
###############################################################################

data "archive_file" "app_bundle" {
  type        = "zip"
  output_path = "${path.module}/build/eb-application-bundle.zip"

  source {
    filename = "application.py"
    content  = <<-EOT
      def application(environ, start_response):
          status = "200 OK"
          body = b"Hello from Elastic Beanstalk, deployed by Terraform!"
          headers = [
              ("Content-Type", "text/plain"),
              ("Content-Length", str(len(body))),
          ]
          start_response(status, headers)
          return [body]
    EOT
  }
}

resource "aws_s3_object" "app_bundle" {
  bucket       = aws_s3_bucket.eb_versions.id
  key          = "artifacts/${local.name_prefix}-application-bundle.zip"
  source       = data.archive_file.app_bundle.output_path
  etag         = data.archive_file.app_bundle.output_md5
  content_type = "application/zip"

  depends_on = [
    aws_s3_bucket_versioning.eb_versions,
    aws_s3_bucket_ownership_controls.eb_versions,
  ]
}

###############################################################################
# Elastic Beanstalk application and application version
###############################################################################

resource "aws_elastic_beanstalk_application" "main" {
  name        = "${local.name_prefix}-app"
  description = "Elastic Beanstalk application managed by Terraform"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_service_role.arn
    max_count             = 20
    delete_source_from_s3 = false
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-app" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elastic_beanstalk_application_version" "app" {
  name        = "v1.0.0"
  application = aws_elastic_beanstalk_application.main.name
  description = "Initial application version deployed by Terraform"
  bucket      = aws_s3_bucket.eb_versions.id
  key         = aws_s3_object.app_bundle.key

  depends_on = [aws_s3_bucket_policy.eb_versions]
}

###############################################################################
# Elastic Beanstalk WebServer environment
###############################################################################

resource "aws_elastic_beanstalk_environment" "web" {
  name                   = "${local.name_prefix}-web"
  application            = aws_elastic_beanstalk_application.main.name
  description            = "WebServer environment managed by Terraform"
  cname_prefix           = "${local.name_prefix}-web-${random_string.suffix.result}"
  solution_stack_name    = var.solution_stack
  version_label          = aws_elastic_beanstalk_application_version.app.name
  tier                   = "WebServer"
  wait_for_ready_timeout = "30m"

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = var.environment_type
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", aws_subnet.public[*].id)
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "EC2SecurityGroups"
    value     = aws_security_group.eb_instances.id
  }

  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "StreamLogs"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "RetentionInDays"
    value     = "7"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:logs"
    name      = "DeleteOnTerminate"
    value     = "false"
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:ec2:vpc"
      name      = "ELBSubnets"
      value     = join(",", aws_subnet.public[*].id)
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:elasticbeanstalk:environment"
      name      = "LoadBalancerType"
      value     = "application"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:elasticbeanstalk:environment:process:default"
      name      = "HealthCheckPath"
      value     = "/"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:autoscaling:asg"
      name      = "MinSize"
      value     = "1"
    }
  }

  dynamic "setting" {
    for_each = local.is_load_balanced ? [1] : []

    content {
      namespace = "aws:autoscaling:asg"
      name      = "MaxSize"
      value     = "3"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-web" })

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_managed_instances,
    aws_iam_role_policy_attachment.eb_service,
    aws_iam_role_policy.eb_service_passrole,
    aws_iam_role_policy_attachment.eb_ec2_web_tier,
    aws_iam_role_policy_attachment.eb_ec2_worker_tier,
    aws_iam_role_policy_attachment.eb_ec2_multicontainer_docker,
    aws_s3_bucket_policy.eb_versions,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "environment_url" {
  description = "Public URL of the Elastic Beanstalk web environment."
  value       = "http://${aws_elastic_beanstalk_environment.web.cname}"
}

output "environment_cname" {
  description = "CNAME (DNS hostname) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.web.cname
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.web.name
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application."
  value       = aws_elastic_beanstalk_application.main.name
}

output "artifacts_bucket_name" {
  description = "Name of the S3 bucket storing Elastic Beanstalk application versions."
  value       = aws_s3_bucket.eb_versions.id
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 bucket storing Elastic Beanstalk application versions."
  value       = aws_s3_bucket.eb_versions.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (all have safe defaults so apply runs unattended)
# -----------------------------------------------------------------------------

variable "application_name" {
  description = "Descriptive name of the Elastic Beanstalk application."
  type        = string
  default     = "go-sample-app"
}

variable "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  type        = string
  default     = "go-sample-env"
}

variable "cname_prefix" {
  description = "Unique CNAME prefix for the environment's public endpoint."
  type        = string
  default     = "go-sample-app-env"
}

variable "instance_type" {
  description = "EC2 instance type used by the environment's Auto Scaling group."
  type        = string
  default     = "t3.small"
}

variable "solution_stack_name" {
  description = "Pinned Elastic Beanstalk Go platform (public AWS platform identifier; re-pin when AWS retires this build)."
  type        = string
  default     = "64bit Amazon Linux 2023 v4.2.0 running Go 1.23"
}

variable "tags" {
  description = "Default tags applied to every managed resource."
  type        = map(string)
  default = {
    Name        = "go-sample-app"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  go_source_file  = "${path.module}/main.go"
  go_bundle_path  = "${path.module}/go-app.zip"
  go_bundle_key   = "bundles/go-app-${substr(data.archive_file.go_app_bundle.output_md5, 0, 16)}.zip"
  go_version_name = "go-app-${substr(data.archive_file.go_app_bundle.output_md5, 0, 16)}"
  version_bucket  = "go-sample-app-eb-versions-${data.aws_caller_identity.current.account_id}"
}

# -----------------------------------------------------------------------------
# Self-contained sample Go application (packaged locally, no external artifacts)
# -----------------------------------------------------------------------------

resource "local_file" "go_main" {
  filename        = local.go_source_file
  file_permission = "0644"

  content = <<-EOT
    package main

    import (
        "fmt"
        "log"
        "net/http"
        "os"
        "time"
    )

    func main() {
        port := os.Getenv("PORT")
        if port == "" {
            port = "8080"
        }

        mux := http.NewServeMux()

        mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
            w.WriteHeader(http.StatusOK)
            fmt.Fprintf(w, "Hello from the Terraform-managed Go app on Elastic Beanstalk! Time: %s\\n", time.Now().UTC().Format(time.RFC3339))
        })

        mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
            w.WriteHeader(http.StatusOK)
            fmt.Fprintln(w, "OK")
        })

        log.Printf("Go sample application listening on port %s", port)
        log.Fatal(http.ListenAndServe(":"+port, mux))
    }
  EOT
}

data "archive_file" "go_app_bundle" {
  type        = "zip"
  source_file = local.go_source_file
  output_path = local.go_bundle_path

  # Ensure the source file is written to disk before the bundle is built.
  depends_on = [local_file.go_main]
}

# -----------------------------------------------------------------------------
# Private, stateful S3 bucket for Elastic Beanstalk application versions
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "eb_app_versions" {
  bucket = local.version_bucket

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-versions"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

data "aws_iam_policy_document" "eb_app_versions_tls" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.eb_app_versions.arn,
      "${aws_s3_bucket.eb_app_versions.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "eb_app_versions" {
  bucket = aws_s3_bucket.eb_app_versions.id
  policy = data.aws_iam_policy_document.eb_app_versions_tls.json
}

resource "aws_s3_object" "go_app_bundle" {
  bucket = aws_s3_bucket.eb_app_versions.id
  key    = local.go_bundle_key
  source = data.archive_file.go_app_bundle.output_path
  etag   = data.archive_file.go_app_bundle.output_md5
}

# -----------------------------------------------------------------------------
# Greenfield networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-vpc"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-igw"
    },
  )
}

resource "aws_subnet" "app_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-a"
    },
  )
}

resource "aws_subnet" "app_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-b"
    },
  )
}

resource "aws_subnet" "public_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(
    var.tags,
    {
      Name = "go-sample-elb-a"
    },
  )
}

resource "aws_subnet" "public_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.102.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(
    var.tags,
    {
      Name = "go-sample-elb-b"
    },
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-public-rt"
    },
  )
}

resource "aws_route_table_association" "app_a" {
  subnet_id      = aws_subnet.app_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "app_b" {
  subnet_id      = aws_subnet.app_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# IAM: EC2 instance role/profile and Elastic Beanstalk service role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "eb_instance_role" {
  name = "go-sample-app-eb-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-instance-role"
    },
  )
}

resource "aws_iam_role_policy_attachment" "eb_instance_web_tier" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWebTier"
}

resource "aws_iam_role_policy_attachment" "eb_instance_worker_tier" {
  role       = aws_iam_role.eb_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkWorkerTier"
}

resource "aws_iam_instance_profile" "eb_instance_profile" {
  name = "go-sample-app-eb-instance-profile"
  role = aws_iam_role.eb_instance_role.name

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-instance-profile"
    },
  )

  depends_on = [
    aws_iam_role_policy_attachment.eb_instance_web_tier,
    aws_iam_role_policy_attachment.eb_instance_worker_tier,
  ]
}

resource "aws_iam_role" "eb_service_role" {
  name = "go-sample-app-eb-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticBeanstalkToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = "elasticbeanstalk"
          }
        }
      },
    ]
  })

  tags = merge(
    var.tags,
    {
      Name = "go-sample-app-eb-service-role"
    },
  )
}

resource "aws_iam_role_policy_attachment" "eb_service_enhanced_health" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkEnhancedHealth"
}

resource "aws_iam_role_policy_attachment" "eb_service_managed_updates" {
  role       = aws_iam_role.eb_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/AWSElasticBeanstalkManagedUpdatesCustomerRolePolicy"
}

# -----------------------------------------------------------------------------
# Elastic Beanstalk application, version, and environment
# -----------------------------------------------------------------------------

resource "aws_elastic_beanstalk_application" "go_app" {
  name        = var.application_name
  description = "Sample Go web application managed by Terraform."
  tags        = var.tags
}

resource "aws_elastic_beanstalk_application_version" "go_app" {
  name        = local.go_version_name
  application = aws_elastic_beanstalk_application.go_app.name
  description = "Sample Go application bundle built and uploaded by Terraform."
  bucket      = aws_s3_bucket.eb_app_versions.id
  key         = aws_s3_object.go_app_bundle.key
  tags        = var.tags

  # Ensure the bundle is fully uploaded before the version is registered.
  depends_on = [aws_s3_object.go_app_bundle]
}

resource "aws_elastic_beanstalk_environment" "go_app" {
  name                   = var.environment_name
  application            = aws_elastic_beanstalk_application.go_app.name
  description            = "Load-balanced Go web server environment."
  solution_stack_name    = var.solution_stack_name
  tier                   = "WebServer"
  cname_prefix           = var.cname_prefix
  version_label          = aws_elastic_beanstalk_application_version.go_app.name
  wait_for_ready_timeout = "30m"
  tags                   = var.tags

  # --- EC2 launch configuration ---
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_instance_profile.name
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = var.instance_type
  }

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "DisableIMDSv1"
    value     = "true"
  }

  # --- VPC wiring (greenfield VPC declared in this configuration) ---
  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = aws_vpc.main.id
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = join(",", [aws_subnet.app_a.id, aws_subnet.app_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBSubnets"
    value     = join(",", [aws_subnet.public_a.id, aws_subnet.public_b.id])
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "ELBScheme"
    value     = "public"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "AssociatePublicIpAddress"
    value     = "true"
  }

  # --- Capacity and autoscaling ---
  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "3"
  }

  # --- Environment and load balancer (public traffic enters here only) ---
  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "LoadBalancerType"
    value     = "application"
  }

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "ServiceRole"
    value     = aws_iam_role.eb_service_role.arn
  }

  # --- Operational health and CloudWatch integration ---
  setting {
    namespace = "aws:elasticbeanstalk:healthreporting:system"
    name      = "SystemType"
    value     = "enhanced"
  }

  setting {
    namespace = "aws:elasticbeanstalk:cloudwatch:ec2"
    name      = "HealthStreamingEnabled"
    value     = "true"
  }

  # --- Managed platform updates ---
  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "ManagedActionsEnabled"
    value     = "true"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions"
    name      = "PreferredStartTime"
    value     = "Tue:09:00"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "UpdateLevel"
    value     = "minor"
  }

  setting {
    namespace = "aws:elasticbeanstalk:managedactions:platformupdate"
    name      = "InstanceRefreshEnabled"
    value     = "true"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eb_service_enhanced_health,
    aws_iam_role_policy_attachment.eb_service_managed_updates,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "environment_endpoint" {
  description = "Public endpoint (CNAME) of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.go_app.cname
}

output "application_name" {
  description = "Name of the Elastic Beanstalk application."
  value       = aws_elastic_beanstalk_application.go_app.name
}

output "environment_name" {
  description = "Name of the Elastic Beanstalk environment."
  value       = aws_elastic_beanstalk_environment.go_app.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "app_image_identifier" {
  description = "User-controlled, non-infrastructure value: publicly accessible container image identifier deployed by App Runner (no external registry assets or account-specific IDs required)."
  type        = string
  default     = "public.ecr.aws/nginx/nginx:latest"
}

variable "tags" {
  description = "Consistent tags applied to every resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Secrets (no passwords, API keys, or credentials are hardcoded anywhere in
# this configuration; the runtime secret value is generated at apply time).
# ---------------------------------------------------------------------------

resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "web-app/example-secret"
  description = "Runtime secret for the App Runner web application."

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# ---------------------------------------------------------------------------
# IAM: explicit trust policy for apprunner.amazonaws.com, least-privilege
# permissions, bound with aws_iam_role_policy_attachment.
# ---------------------------------------------------------------------------

resource "aws_iam_role" "web_app_instance_role" {
  name = "web-app-apprunner-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "apprunner.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "web_app_instance_policy" {
  name        = "web-app-apprunner-instance-policy"
  description = "Least-privilege runtime permissions for the App Runner web application instance role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadAppSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [aws_secretsmanager_secret.example.arn]
      },
      {
        Sid    = "PublishXRayTraces"
        Effect = "Allow"
        Action = ["xray:PutTraceSegments", "xray:PutTelemetryRecords"]
        # X-Ray API actions do not support resource-level permissions;
        # Action is scoped to X-Ray write operations only (never "*" for both).
        Resource = ["*"]
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "web_app_instance_policy" {
  role       = aws_iam_role.web_app_instance_role.name
  policy_arn = aws_iam_policy.web_app_instance_policy.arn
}

# ---------------------------------------------------------------------------
# App Runner observability: W3C trace context propagation with AWS X-Ray.
# ---------------------------------------------------------------------------

resource "aws_apprunner_observability_configuration" "web_app_observability" {
  observability_configuration_name = "web-app-observability"

  trace_configuration {
    vendor = "AWSXRAY"
  }

  tags = var.tags
}

# ---------------------------------------------------------------------------
# App Runner service: deploys and scales the supported-language web
# application. Because no auto_scaling_configuration_arn is specified, App
# Runner automatically associates the latest revision of the platform default
# auto scaling configuration, which still provides concurrency-driven
# scale-out/in with a minimum of 1 instance — zero additional infrastructure.
#
# Networking (ingress, load balancing) and TLS termination are fully managed
# by App Runner — no security groups, load balancers, or ingress rules are
# created, and all traffic is served over HTTPS on the managed
# awsapprunner.com endpoint.
# ---------------------------------------------------------------------------

resource "aws_apprunner_service" "web_app" {
  service_name = "web-app"

  source_configuration {
    # ECR Public sources do not support App Runner auto deployments from the
    # registry; the App Runner platform performs deployment and rolling
    # updates whenever the service is created or updated (e.g. terraform apply).
    auto_deployments_enabled = false

    image_repository {
      image_identifier      = var.app_image_identifier
      image_repository_type = "ECR_PUBLIC"

      image_configuration {
        port = "80"

        # Map of environment variable name -> Secrets Manager secret ARN.
        # Only the ARN is referenced (never a secret value); App Runner
        # injects the decrypted value at runtime via the instance role's
        # secretsmanager:GetSecretValue permission.
        runtime_environment_secrets = {
          EXAMPLE_SECRET = aws_secretsmanager_secret.example.arn
        }
      }
    }
  }

  instance_configuration {
    instance_role_arn = aws_iam_role.web_app_instance_role.arn
  }

  health_check_configuration {
    path                = "/"
    protocol            = "HTTP"
    healthy_threshold   = 1
    unhealthy_threshold = 5
    interval            = 10
    timeout             = 5
  }

  observability_configuration {
    observability_enabled           = true
    observability_configuration_arn = aws_apprunner_observability_configuration.web_app_observability.arn
  }

  depends_on = [
    aws_iam_role_policy_attachment.web_app_instance_policy,
    aws_secretsmanager_secret_version.example,
  ]

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "service_url" {
  description = "HTTPS endpoint (App Runner managed TLS) of the deployed web application."
  value       = aws_apprunner_service.web_app.service_url
}

output "service_status" {
  description = "Current status of the App Runner service."
  value       = aws_apprunner_service.web_app.status
}

output "auto_scaling_configuration_arn" {
  description = "ARN of the auto scaling configuration associated with the web application (App Runner default configuration, providing concurrency-driven scaling with a minimum of 1 instance)."
  value       = aws_apprunner_service.web_app.auto_scaling_configuration_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_environment_name" {
  description = "User-controlled name applied only to resource tags and descriptions."
  type        = string
  default     = "eb-appversion-lifecycle-env"

  validation {
    condition     = length(var.application_environment_name) > 0
    error_message = "The application environment name must not be empty."
  }
}

data "aws_caller_identity" "current" {}

locals {
  environment_name        = var.application_environment_name
  app_version_bucket_name = "eb-app-versions-${data.aws_caller_identity.current.account_id}"
}

resource "aws_s3_bucket" "app_versions" {
  bucket = local.app_version_bucket_name

  tags = {
    Name        = local.app_version_bucket_name
    Environment = local.environment_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_iam_role" "eb_appversion_lifecycle" {
  name        = "eb-appversion-lifecycle-service-role"
  description = "Service role used by Elastic Beanstalk for application version lifecycle management"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Environment = local.environment_name
  }
}

resource "aws_iam_policy" "app_version_bucket_access" {
  name        = "eb-appversion-bucket-access"
  description = "Least-privilege S3 access for Elastic Beanstalk application version lifecycle management"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "VersionBucketObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.app_versions.arn}/*"
      },
      {
        Sid      = "VersionBucketListAction"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.app_versions.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "app_version_bucket_access" {
  role       = aws_iam_role.eb_appversion_lifecycle.name
  policy_arn = aws_iam_policy.app_version_bucket_access.arn
}

resource "aws_s3_bucket_policy" "app_versions" {
  bucket = aws_s3_bucket.app_versions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEBServiceRoleObjectActions"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eb_appversion_lifecycle.arn
        }
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.app_versions.arn}/*"
      },
      {
        Sid    = "AllowEBServiceRoleListBucket"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eb_appversion_lifecycle.arn
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.app_versions.arn
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.app_versions]
}

resource "aws_elastic_beanstalk_application" "main" {
  name        = "eb-appversion-lifecycle-app"
  description = "Elastic Beanstalk application with application version lifecycle for environment ${local.environment_name}"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_appversion_lifecycle.arn
    max_count             = 10
    delete_source_from_s3 = true
  }

  tags = {
    Name        = "eb-appversion-lifecycle-app"
    Environment = local.environment_name
  }

  depends_on = [aws_iam_role_policy_attachment.app_version_bucket_access]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_name" {
  description = "Name of the Elastic Beanstalk application."
  type        = string
  default     = "my-eb-application"
}

locals {
  environment = "production"
  owner       = "platform-team"
  purpose     = "elastic-beanstalk-appversion-lifecycle"

  common_tags = {
    Environment = local.environment
    Owner       = local.owner
    Purpose     = local.purpose
  }
}

resource "aws_iam_role" "eb_service_role" {
  name        = "eb-service-role-${var.application_name}"
  description = "Service role that allows Elastic Beanstalk to manage application version lifecycle"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid     = "AllowElasticBeanstalkServiceAssume"
        Effect  = "Allow"
        Action  = "sts:AssumeRole"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })

  max_session_duration = 3600
  path                 = "/service-role/"

  tags = merge(
    local.common_tags,
    {
      Name = "eb-service-role-${var.application_name}"
    }
  )
}

resource "aws_iam_role_policy" "eb_service_role_version_bucket" {
  name = "eb-service-role-version-bucket-access"
  role = aws_iam_role.eb_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListVersionBuckets"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:ListObjects"
        ]
        Resource = [
          "arn:aws:s3:::elasticbeanstalk-*"
        ]
      },
      {
        Sid    = "ManageVersionObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "arn:aws:s3:::elasticbeanstalk-*/*"
        ]
      }
    ]
  })
}

resource "aws_elastic_beanstalk_application" "main" {
  name        = var.application_name
  description = "Elastic Beanstalk application with a 5 day application version retention lifecycle"

  appversion_lifecycle {
    service_role          = aws_iam_role.eb_service_role.arn
    max_age_in_days       = 5
    delete_source_from_s3 = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.application_name
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "terraform-codebuild-example"
      Environment = "example"
      ManagedBy   = "terraform"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  codebuild_project_name = "terraform-example-codebuild"
  artifacts_bucket_name  = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}"
  log_group_name         = "/aws/codebuild/${local.codebuild_project_name}"
}

resource "aws_iam_role" "codebuild_service_role" {
  name = "codebuild-service-role-example"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "codebuild-service-role-example"
  }
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name = "codebuild-least-privilege-inline-policy"
  role = aws_iam_role.codebuild_service_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildArtifactBucket"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.codebuild_artifacts.arn,
          "${aws_s3_bucket.codebuild_artifacts.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = {
    Name = local.log_group_name
  }
}

resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = local.artifacts_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.artifacts_bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_codebuild_project" "example" {
  name         = local.codebuild_project_name
  description  = "Example CodeBuild project with public GitHub source, S3 artifacts, and CloudWatch logs"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type     = "GITHUB"
    location = "https://github.com/hashicorp/terraform-example-repo.git"

    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase - installing dependencies"
        build:
          commands:
            - echo "Build phase - build started on $(date)"
            - echo "Hello from CodeBuild managed by Terraform"
        post_build:
          commands:
            - echo "Post-build phase - build completed on $(date)"

      artifacts:
        files:
          - '**/*'
    EOT
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type                = "S3"
    location            = aws_s3_bucket.codebuild_artifacts.id
    name                = "example-build-output"
    packaging           = "ZIP"
    encryption_disabled = false
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = {
    Name = local.codebuild_project_name
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Pure local lookup of the current account ID, used only to guarantee a
# globally unique S3 bucket name in this greenfield account.
data "aws_caller_identity" "current" {}

variable "github_repo_url" {
  description = "HTTPS URL of the public GitHub repository that CodeBuild will build."
  type        = string
  default     = "https://github.com/example/hello-world.git"
}

variable "tags" {
  description = "Tags applied to all taggable resources for traceability."
  type        = map(string)
  default = {
    Environment = "example"
    Project     = "codebuild-example"
    ManagedBy   = "terraform"
  }
}

locals {
  project_name = "example-codebuild-project"
  cache_prefix = "cache"
}

# -----------------------------------------------------------------------------
# IAM role trusted exclusively by the CodeBuild service principal
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild" {
  name        = "codebuild-example-service-role"
  description = "Service role trusted only by the AWS CodeBuild service principal."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "codebuild.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# -----------------------------------------------------------------------------
# Least-privilege inline policy: project log group + cache bucket prefix only
# -----------------------------------------------------------------------------
resource "aws_iam_role_policy" "codebuild" {
  name = "codebuild-least-privilege"
  role = aws_iam_role.codebuild.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild.arn,
          "${aws_cloudwatch_log_group.codebuild.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildS3Cache"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.codebuild_cache.arn}/${local.cache_prefix}/*"
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch log group capturing build logs
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 14
  tags              = var.tags
}

# -----------------------------------------------------------------------------
# S3 bucket backing the CodeBuild build cache
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "codebuild_cache" {
  bucket = "codebuild-example-cache-${data.aws_caller_identity.current.account_id}"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "codebuild_cache" {
  bucket = aws_s3_bucket.codebuild_cache.id

  rule {
    id     = "expire-cache-objects"
    status = "Enabled"

    filter {
      prefix = "${local.cache_prefix}/"
    }

    expiration {
      days = 30
    }
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager secret backing the sensitive environment variable.
# The value is generated at apply time so that no plaintext secret ever
# appears in this configuration, in variable defaults, or in locals.
# -----------------------------------------------------------------------------
resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "codebuild/example/api-token"
  description = "Sensitive value injected into the CodeBuild build environment at runtime via a SECRETS_MANAGER environment variable."

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# -----------------------------------------------------------------------------
# CodeBuild project: GitHub source, environment variables, inline buildspec,
# and S3 cache. The default repository is a public example, so no
# aws_codebuild_source_credential resource is required; if you point
# var.github_repo_url at a private repository, add a source credential whose
# auth token is sourced from Secrets Manager.
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name         = local.project_name
  description  = "Example CodeBuild project with a GitHub source, environment variables, and an S3 build cache."
  service_role = aws_iam_role.codebuild.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  cache {
    type     = "S3"
    location = "${aws_s3_bucket.codebuild_cache.id}/${local.cache_prefix}"
  }

  environment {
    type                        = "LINUX_CONTAINER"
    image                       = "aws/codebuild/standard:7.0"
    compute_type                = "BUILD_GENERAL1_SMALL"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "APP_ENV"
      value = "example"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "LOG_LEVEL"
      value = "info"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "API_TOKEN"
      value = aws_secretsmanager_secret.example.arn
      type  = "SECRETS_MANAGER"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild.name
    }
  }

  source {
    type            = "GITHUB"
    location        = var.github_repo_url
    git_clone_depth = 1

    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase - no additional dependencies required for this example"
        pre_build:
          commands:
            - echo "Pre-build phase started on $(date)"
        build:
          commands:
            - echo "Build started on $(date)"
            - echo "APP_ENV=$APP_ENV"
            - echo "LOG_LEVEL=$LOG_LEVEL"
            - echo "Hello from CodeBuild!"
        post_build:
          commands:
            - echo "Build completed on $(date)"
    EOT
  }

  tags = var.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project_name        = "example-project"
  codebuild_role_name = "example-codebuild-role"
  log_group_name      = "/aws/codebuild/${local.project_name}"
}

resource "aws_iam_role" "codebuild_role" {
  name        = local.codebuild_role_name
  description = "IAM role assumed by the example CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodeBuildToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name      = local.codebuild_role_name
    ManagedBy = "terraform"
  }
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name      = local.log_group_name
    ManagedBy = "terraform"
  }
}

resource "aws_iam_role_policy" "codebuild_cloudwatch_logs" {
  name = "example-codebuild-cloudwatch-logs"
  role = aws_iam_role.codebuild_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_codebuild_project" "example_project" {
  name          = local.project_name
  description   = "Example CodeBuild project with no source and no artifacts"
  build_timeout = 10
  service_role  = aws_iam_role.codebuild_role.arn

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENVIRONMENT"
      value = "example"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "PROJECT_NAME"
      value = local.project_name
      type  = "PLAINTEXT"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name  = aws_cloudwatch_log_group.codebuild_logs.name
      stream_name = "example-build-logs"
      status      = "ENABLED"
    }
  }

  source {
    type      = "NO_SOURCE"
    buildspec = <<-EOT
      version: 0.2

      phases:
        build:
          commands:
            - echo "Running example CodeBuild project with NO_SOURCE"
            - echo "ENVIRONMENT=$ENVIRONMENT"
            - echo "PROJECT_NAME=$PROJECT_NAME"
    EOT
  }

  tags = {
    Name        = local.project_name
    Environment = "example"
    ManagedBy   = "terraform"
  }
}

# Terraform settings and provider (region pinned for this deployment)

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "github_repository_url" {
  description = "GitHub repository URL used as the source for the CodeBuild project."
  type        = string
  default     = "https://github.com/example/hello-world.git"
}

variable "github_personal_access_token" {
  description = "GitHub personal access token used for private repository access. Stored in AWS Secrets Manager and registered as a CodeBuild source credential. Replace the default with a real token for private repositories."
  type        = string
  default     = "REPLACE_ME_WITH_A_REAL_GITHUB_PAT"
  sensitive   = true
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  project_name         = "codebuild_example_project"
  artifact_bucket_name = lower("codebuild-example-artifacts-${data.aws_caller_identity.current.account_id}")

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "codebuild_example"
  }

  buildspec = yamlencode({
    version = "0.2"
    phases = {
      install = {
        commands = ["echo \"Installing dependencies\""]
      }
      build = {
        commands = ["echo \"Building the application\""]
      }
      post_build = {
        commands = [
          "echo \"Build completed on $(date)\"",
          "echo \"Packaging artifacts for upload to s3://${local.artifact_bucket_name}\"",
        ]
      }
    }
    artifacts = {
      files = ["**/*"]
    }
    cache = {
      paths = ["node_modules/**/*"]
    }
  })
}

###############################################################################
# S3 artifact bucket (build outputs + build cache)
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifact_bucket_name

  tags = merge(local.common_tags, { Name = local.artifact_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

###############################################################################
# IAM role and least-privilege policy for CodeBuild
###############################################################################

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild_example_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "codebuild_example_role" })
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "codebuild_example_policy"
  description = "least_privilege_policy_for_the_example_codebuild_project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
        ]
      },
      {
        Sid      = "ArtifactBucketList"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.artifacts.arn]
      },
      {
        Sid    = "ArtifactBucketReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = ["${aws_s3_bucket.artifacts.arn}/*"]
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "codebuild_example_policy" })
}

resource "aws_iam_role_policy_attachment" "codebuild_policy" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

###############################################################################
# CloudWatch log group for build logs
###############################################################################

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "codebuild_example_logs" })
}

###############################################################################
# GitHub source credential backed by Secrets Manager
###############################################################################

resource "aws_secretsmanager_secret" "github_pat" {
  name        = "codebuild/github_pat"
  description = "github_personal_access_token_used_by_the_codebuild_source_credential"

  tags = merge(local.common_tags, { Name = "codebuild_github_pat" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "github_pat" {
  secret_id     = aws_secretsmanager_secret.github_pat.id
  secret_string = var.github_personal_access_token
}

resource "aws_codebuild_source_credential" "github_pat" {
  auth_type   = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token       = aws_secretsmanager_secret_version.github_pat.secret_string
}

###############################################################################
# CodeBuild project
###############################################################################

resource "aws_codebuild_project" "codebuild_example" {
  name         = local.project_name
  description  = "example_codebuild_project_with_github_source_s3_artifacts_and_s3_cache"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type                = "GITHUB"
    location            = var.github_repository_url
    buildspec           = local.buildspec
    report_build_status = true
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.artifacts.id
    packaging      = "ZIP"
    name           = "build_output"
    namespace_type = "BUILD_ID"
    path           = "builds"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.artifacts.id
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
      status     = "ENABLED"
    }
  }

  tags = merge(local.common_tags, { Name = local.project_name })

  depends_on = [aws_iam_role_policy_attachment.codebuild_policy]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Data sources (pure, well-known static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Fixed project name string: the CloudWatch log group and the IAM policy
  # resource ARN reference this literal so no circular dependency arises
  # between the IAM policy, the log group, and the CodeBuild project.
  project_name = "example-project"

  tags = {
    Project   = "example-codebuild"
    ManagedBy = "terraform"
  }
}

###############################################################################
# IAM: CodeBuild service role and least-privilege logging policy
###############################################################################

resource "aws_iam_role" "codebuild_role" {
  name = "${local.project_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-role"
  })
}

resource "aws_iam_policy" "codebuild_logs_policy" {
  name        = "${local.project_name}-codebuild-logs-policy"
  description = "Least-privilege logging permissions for the ${local.project_name} CodeBuild project (CloudWatch Logs and S3 logs bucket)"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/codebuild/${local.project_name}:*"
      },
      {
        Sid    = "CodeBuildS3Logs"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.codebuild_logs.arn}/*"
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "codebuild_logs" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_logs_policy.arn
}

###############################################################################
# S3 bucket receiving CodeBuild S3 logs (stateful, protected from destroy)
###############################################################################

resource "aws_s3_bucket" "codebuild_logs" {
  bucket = "${local.project_name}-codebuild-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.tags, {
    Name = "${local.project_name}-codebuild-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "codebuild_logs" {
  bucket = aws_s3_bucket.codebuild_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.codebuild_logs.arn,
          "${aws_s3_bucket.codebuild_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.codebuild_logs]
}

###############################################################################
# CloudWatch Logs group for CodeBuild build logs
###############################################################################

resource "aws_cloudwatch_log_group" "example" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30

  tags = merge(local.tags, {
    Name = "/aws/codebuild/${local.project_name}"
  })
}

###############################################################################
# CodeBuild project
###############################################################################

# NOTE: This example builds from a public HTTPS GitHub repository URL and
# therefore requires no credentials. If private repository access is ever
# required, store the GitHub personal access token in
# aws_secretsmanager_secret / aws_secretsmanager_secret_version and reference
# only the secret ARN — never hardcode tokens or credentials in this file.

resource "aws_codebuild_project" "example" {
  name          = local.project_name
  description   = "Example CodeBuild project with GitHub source, CloudWatch Logs and S3 logging"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = 10

  source {
    type      = "GITHUB"
    location  = "https://github.com/octocat/Hello-World.git"
    buildspec = <<-EOT
      version: 0.2

      phases:
        install:
          commands:
            - echo "Install phase started on $(date)"
        build:
          commands:
            - echo "Build phase started on $(date)"
        post_build:
          commands:
            - echo "Build completed successfully on $(date)"
    EOT
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  logs_config {
    cloudwatch_logs {
      status      = "ENABLED"
      group_name  = aws_cloudwatch_log_group.example.name
      stream_name = "${local.project_name}-build-stream"
    }

    s3_logs {
      status              = "ENABLED"
      location            = "${aws_s3_bucket.codebuild_logs.bucket}/${local.project_name}/logs"
      encryption_disabled = false
    }
  }

  tags = merge(local.tags, {
    Name = local.project_name
  })

  depends_on = [aws_iam_role_policy_attachment.codebuild_logs]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    project     = "greenfield-codebuild-example"
    environment = "sandbox"
    managed_by  = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  project_name          = "greenfield_codebuild_example"
  artifacts_bucket_name = "greenfield-codebuild-example-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
  log_group_name        = "/aws/codebuild/${local.project_name}"

  buildspec = <<-BUILDSPEC
    version: 0.2

    env:
      variables:
        BUILD_STAGE: "combine-secondary-sources"

    phases:
      pre_build:
        commands:
          - echo "Build started on $(date)"
          - echo "Primary source checkout: $CODEBUILD_SRC_DIR"
          - echo "Secondary source shared_libs checkout: $CODEBUILD_SRC_DIR_shared_libs"
          - echo "Secondary source public_docs checkout: $CODEBUILD_SRC_DIR_public_docs"
      build:
        commands:
          - echo "Combining primary source with both secondary sources"
          - mkdir -p "$CODEBUILD_SRC_DIR/secondary-output"
          - if [ -d "$CODEBUILD_SRC_DIR_shared_libs" ]; then cp -r "$CODEBUILD_SRC_DIR_shared_libs"/. "$CODEBUILD_SRC_DIR/"; fi
          - if [ -d "$CODEBUILD_SRC_DIR_public_docs" ]; then cp -r "$CODEBUILD_SRC_DIR_public_docs"/. "$CODEBUILD_SRC_DIR/secondary-output/"; fi
      post_build:
        commands:
          - echo "Build completed on $(date)"

    artifacts:
      files:
        - '**/*'

    secondary-artifacts:
      secondary_bundle:
        base-directory: secondary-output
        files:
          - '**/*'
  BUILDSPEC
}

resource "aws_kms_key" "codebuild" {
  description             = "KMS key for the ${local.project_name} CodeBuild project"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_kms_key_policy" "codebuild" {
  key_id = aws_kms_key.codebuild.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootFullControl"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCodeBuildRoleUse"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.codebuild_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}*"
          }
        }
      },
    ]
  })
}

resource "aws_iam_role" "codebuild_role" {
  name = "${local.project_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeBuildServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "codebuild_policy" {
  name        = "${local.project_name}_policy"
  description = "Least-privilege permissions for the CodeBuild project"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.codebuild_logs.name}",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.codebuild_logs.name}:*",
        ]
      },
      {
        Sid    = "CodeBuildArtifactsObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Resource = "${aws_s3_bucket.artifacts.arn}/*"
      },
      {
        Sid    = "CodeBuildArtifactsBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = aws_s3_bucket.artifacts.arn
      },
      {
        Sid    = "CodeBuildKmsAccess"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt",
        ]
        Resource = aws_kms_key.codebuild.arn
      },
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "codebuild_policy_attachment" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.codebuild_policy.arn
}

resource "aws_s3_bucket" "artifacts" {
  bucket = local.artifacts_bucket_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.codebuild.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.codebuild.arn

  tags = var.tags

  depends_on = [aws_kms_key_policy.codebuild]
}

resource "aws_codebuild_project" "codebuild_project" {
  name           = local.project_name
  description    = "example_codebuild_project_with_secondary_sources"
  service_role   = aws_iam_role.codebuild_role.arn
  encryption_key = aws_kms_key.codebuild.arn
  build_timeout  = 15

  source {
    type      = "S3"
    location  = "${aws_s3_bucket.artifacts.bucket}/source.zip"
    buildspec = local.buildspec
  }

  secondary_sources {
    type              = "S3"
    source_identifier = "shared_libs"
    location          = "${aws_s3_bucket.artifacts.bucket}/secondary/shared-libs"
  }

  secondary_sources {
    type              = "GITHUB"
    source_identifier = "public_docs"
    location          = "https://github.com/hashicorp/go-cleanhttp.git"
  }

  artifacts {
    type      = "S3"
    location  = aws_s3_bucket.artifacts.bucket
    name      = "combined-build-output"
    packaging = "ZIP"
  }

  secondary_artifacts {
    artifact_identifier = "secondary_bundle"
    type                = "S3"
    location            = aws_s3_bucket.artifacts.bucket
    name                = "secondary-bundle-output"
    packaging           = "ZIP"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode             = false
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = var.tags

  depends_on = [aws_iam_role_policy_attachment.codebuild_policy_attachment]
}

output "codebuild_project_name" {
  description = "Name of the CodeBuild project."
  value       = aws_codebuild_project.codebuild_project.name
}

output "codebuild_project_arn" {
  description = "ARN of the CodeBuild project."
  value       = aws_codebuild_project.codebuild_project.arn
}

output "codebuild_role_arn" {
  description = "ARN of the CodeBuild IAM service role."
  value       = aws_iam_role.codebuild_role.arn
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 artifacts bucket."
  value       = aws_s3_bucket.artifacts.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Name of the CodeBuild project."
  type        = string
  default     = "example-codebuild-project"
}

variable "environment_tag" {
  description = "Environment tag applied to all resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

locals {
  project_slug          = lower(replace(var.project_name, "_", "-"))
  primary_bucket_name   = "${local.project_slug}-${data.aws_caller_identity.current.account_id}-primary-artifacts"
  secondary_bucket_name = "${local.project_slug}-${data.aws_caller_identity.current.account_id}-secondary-artifacts"
  log_group_name        = "/aws/codebuild/${var.project_name}"
  source_location       = "https://github.com/octocat/Hello-World.git"

  common_tags = {
    Environment = var.environment_tag
  }

  buildspec = <<-EOT
    version: 0.2

    phases:
      install:
        runtime-versions:
          python: 3.12
        commands:
          - echo "Install phase completed on $(date)"
      pre_build:
        commands:
          - echo "Pre-build phase completed on $(date)"
      build:
        commands:
          - mkdir -p output/primary output/secondary
          - echo "Primary artifact content" > output/primary/primary.txt
          - echo "Secondary artifact content" > output/secondary/secondary.txt
      post_build:
        commands:
          - echo "Build completed on $(date)"

    artifacts:
      files:
        - '**/*'
      base-directory: output/primary

    secondary-artifacts:
      secondary:
        files:
          - '**/*'
        base-directory: output/secondary
  EOT
}

# ------------------------------------------------------------------------------
# Primary build artifacts bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts_primary" {
  bucket = local.primary_bucket_name

  tags = merge(local.common_tags, {
    Name = local.primary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts_primary" {
  bucket = aws_s3_bucket.artifacts_primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Secondary build artifacts bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts_secondary" {
  bucket = local.secondary_bucket_name

  tags = merge(local.common_tags, {
    Name = local.secondary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts_secondary" {
  bucket = aws_s3_bucket.artifacts_secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# Build logs
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# ------------------------------------------------------------------------------
# CodeBuild IAM role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_role" {
  name = "${var.project_name}-codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-codebuild-role"
  })
}

resource "aws_iam_role_policy" "codebuild_policy" {
  name = "${var.project_name}-codebuild-policy"
  role = aws_iam_role.codebuild_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.artifacts_primary.arn,
          aws_s3_bucket.artifacts_secondary.arn,
          "${aws_s3_bucket.artifacts_primary.arn}/*",
          "${aws_s3_bucket.artifacts_secondary.arn}/*",
        ]
      },
      {
        Sid    = "CodeBuildLogAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
        ]
      },
    ]
  })
}

# ------------------------------------------------------------------------------
# CodeBuild project
# ------------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name         = var.project_name
  description  = "Example CodeBuild project with primary and secondary S3 artifacts."
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type            = "GITHUB"
    location        = local.source_location
    buildspec       = local.buildspec
    git_clone_depth = 1
  }

  environment {
    type                        = "LINUX_CONTAINER"
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux-x86_64-standard:5.0"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENVIRONMENT"
      value = var.environment_tag
    }
  }

  artifacts {
    type                = "S3"
    artifact_identifier = "primary"
    location            = aws_s3_bucket.artifacts_primary.bucket
    name                = "${var.project_name}-primary"
    encryption_disabled = false
  }

  secondary_artifacts {
    type                = "S3"
    artifact_identifier = "secondary"
    location            = aws_s3_bucket.artifacts_secondary.bucket
    name                = "${var.project_name}-secondary"
    encryption_disabled = false
  }

  logs_config {
    cloudwatch_logs {
      status     = "ENABLED"
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  tags = merge(local.common_tags, {
    Name = var.project_name
  })

  depends_on = [aws_iam_role_policy.codebuild_policy]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Permitted static metadata lookups (pure local, no pre-existing remote state)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  project_name          = "example-codebuild-project"
  artifacts_bucket_name = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

# -----------------------------------------------------------------------------
# S3 bucket for CodeBuild build artifacts
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "codebuild_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = {
    Name = local.artifacts_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "codebuild_artifacts_bucket_policy" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.codebuild_artifacts.arn,
      "${aws_s3_bucket.codebuild_artifacts.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "codebuild_artifacts" {
  bucket = aws_s3_bucket.codebuild_artifacts.id
  policy = data.aws_iam_policy_document.codebuild_artifacts_bucket_policy.json
}

# -----------------------------------------------------------------------------
# CloudWatch log group for build logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "codebuild_logs" {
  name              = "/aws/codebuild/${local.project_name}"
  retention_in_days = 30
}

# -----------------------------------------------------------------------------
# IAM trust policy shared by both CodeBuild roles
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "codebuild_assume_role" {
  statement {
    sid     = "AllowCodeBuildToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# CodeBuild project service role + least-privilege policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_service_role" {
  name               = "codebuild-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_service_policy" {
  statement {
    sid       = "ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.codebuild_artifacts.arn]
  }

  statement {
    sid    = "ReadWriteArtifactObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]
    resources = [
      aws_s3_bucket.codebuild_artifacts.arn,
      "${aws_s3_bucket.codebuild_artifacts.arn}/*",
    ]
  }

  statement {
    sid    = "WriteBuildLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.codebuild_logs.arn,
      "${aws_cloudwatch_log_group.codebuild_logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "codebuild_service_policy" {
  name        = "codebuild-service-policy"
  description = "Least-privilege permissions for the CodeBuild project service role"
  policy      = data.aws_iam_policy_document.codebuild_service_policy.json
}

resource "aws_iam_role_policy_attachment" "codebuild_service_policy_attach" {
  role       = aws_iam_role.codebuild_service_role.name
  policy_arn = aws_iam_policy.codebuild_service_policy.arn
}

# -----------------------------------------------------------------------------
# Dedicated batch service role + least-privilege policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "codebuild_batch_role" {
  name               = "codebuild-batch-service-role"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume_role.json
}

data "aws_iam_policy_document" "codebuild_batch_policy" {
  statement {
    sid    = "ManageProjectBuildsAndBuildBatches"
    effect = "Allow"
    actions = [
      "codebuild:StartBuildBatch",
      "codebuild:StopBuildBatch",
      "codebuild:RetryBuildBatch",
      "codebuild:StartBuild",
      "codebuild:StopBuild",
      "codebuild:RetryBuild",
    ]
    resources = [aws_codebuild_project.example.arn]
  }

  statement {
    sid    = "ManageCodeBuildEventBridgeRules"
    effect = "Allow"
    actions = [
      "events:PutTargets",
      "events:PutRule",
      "events:DescribeRule",
    ]
    resources = [
      "arn:${data.aws_partition.current.partition}:events:${data.aws_region.current.name}:*:rule/codebuild*",
    ]
  }
}

resource "aws_iam_policy" "codebuild_batch_policy" {
  name        = "codebuild-batch-policy"
  description = "Least-privilege permissions for the CodeBuild batch service role"
  policy      = data.aws_iam_policy_document.codebuild_batch_policy.json
}

resource "aws_iam_role_policy_attachment" "codebuild_batch_policy_attach" {
  role       = aws_iam_role.codebuild_batch_role.name
  policy_arn = aws_iam_policy.codebuild_batch_policy.arn
}

# -----------------------------------------------------------------------------
# CodeBuild project with batch build configuration
# -----------------------------------------------------------------------------

resource "aws_codebuild_project" "example" {
  name         = local.project_name
  description  = "Example CodeBuild project with batch build configuration"
  service_role = aws_iam_role.codebuild_service_role.arn

  source {
    type      = "NO_SOURCE"
    buildspec = <<BUILDSPEC
version: 0.2

phases:
  install:
    commands:
      - echo "Install phase started on `date`"
      - aws --version
  build:
    commands:
      - echo "Build phase started on `date`"
      - mkdir -p build_output
      - echo "hello from CodeBuild" > build_output/hello.txt
  post_build:
    commands:
      - echo "Build phase completed on `date`"

artifacts:
  files:
    - 'build_output/**/*'
BUILDSPEC
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  artifacts {
    type           = "S3"
    location       = aws_s3_bucket.codebuild_artifacts.id
    name           = "build-output"
    namespace_type = "BUILD_ID"
    packaging      = "ZIP"
    path           = "artifacts"
  }

  logs_config {
    cloudwatch_logs {
      group_name = aws_cloudwatch_log_group.codebuild_logs.name
    }
  }

  build_batch_config {
    service_role    = aws_iam_role.codebuild_batch_role.arn
    timeout_in_mins = 15

    restrictions {
      maximum_builds_allowed = 5
      compute_types_allowed  = ["BUILD_GENERAL1_SMALL"]
    }
  }

  tags = {
    Name = local.project_name
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  project_name          = "example-secondary-sources-project"
  artifacts_bucket_name = "codebuild-artifacts-${data.aws_caller_identity.current.account_id}"
  log_group_name        = "/aws/codebuild/${local.project_name}"
  log_stream_name       = "build-logs"

  common_tags = {
    Project     = "codebuild-example"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# S3 bucket for CodeBuild primary and secondary artifacts
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "build_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = merge(local.common_tags, {
    Name = "codebuild-build-artifacts"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "build_artifacts" {
  bucket = aws_s3_bucket.build_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch log group for CodeBuild build logs
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "codebuild_build_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = "codebuild-build-logs"
  })
}

# -----------------------------------------------------------------------------
# IAM role and least-privilege inline policy for CodeBuild
# -----------------------------------------------------------------------------
resource "aws_iam_role" "codebuild_service_role" {
  name        = "example-codebuild-service-role"
  description = "Service role assumed by the example CodeBuild project"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCodeBuildToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild_least_privilege" {
  name = "example-codebuild-least-privilege"
  role = aws_iam_role.codebuild_service_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CodeBuildCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.codebuild_build_logs.arn,
          "${aws_cloudwatch_log_group.codebuild_build_logs.arn}:*"
        ]
      },
      {
        Sid    = "CodeBuildArtifactObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Resource = "${aws_s3_bucket.build_artifacts.arn}/*"
      },
      {
        Sid      = "CodeBuildArtifactBucketList"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.build_artifacts.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Secrets Manager secret backing the SECRETS_MANAGER environment variable
# -----------------------------------------------------------------------------
resource "random_password" "example" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "example" {
  name        = "codebuild/example-app-secret"
  description = "Example secret referenced by the CodeBuild SECRETS_MANAGER environment variable"

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id     = aws_secretsmanager_secret.example.id
  secret_string = random_password.example.result
}

# -----------------------------------------------------------------------------
# CodeBuild project with primary/secondary sources and primary/secondary artifacts
# -----------------------------------------------------------------------------
resource "aws_codebuild_project" "example" {
  name          = local.project_name
  description   = "Example CodeBuild project with secondary sources and secondary artifacts"
  service_role  = aws_iam_role.codebuild_service_role.arn
  build_timeout = 20

  source {
    type     = "GITHUB"
    location = "https://github.com/example-org/primary-build-repo.git"
    buildspec = <<-EOF
      version: 0.2

      phases:
        install:
          runtime-versions:
            python: 3.11
          commands:
            - echo "Install phase for environment $ENV_NAME (log level: $LOG_LEVEL)"
            - python -m pip install --upgrade pip
        pre_build:
          commands:
            - echo "Pre-build phase started on $(date)"
        build:
          commands:
            - echo "Build phase started on $(date)"
            - mkdir -p build-output test-output
            - echo "Primary application build output" > build-output/app-output.txt
            - echo "Test suite output" > test-output/test-results.txt
        post_build:
          commands:
            - echo "Build completed on $(date)"

      artifacts:
        name: primary-artifact
        base-directory: build-output
        files:
          - '**/*'

      secondary-artifacts:
        secondary_artifact_1:
          name: secondary-artifact-1
          base-directory: build-output
          files:
            - '**/*'
        secondary_artifact_2:
          name: secondary-artifact-2
          base-directory: test-output
          files:
            - '**/*'
    EOF
  }

  secondary_sources {
    type              = "GITHUB"
    location          = "https://github.com/example-org/secondary-source-one.git"
    source_identifier = "secondary_src_1"
    buildspec         = "buildspecs/secondary-one.yml"
  }

  secondary_sources {
    type              = "GITHUB"
    location          = "https://github.com/example-org/secondary-source-two.git"
    source_identifier = "secondary_src_2"
    buildspec         = "buildspecs/secondary-two.yml"
  }

  artifacts {
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "primary-artifact"
    path                   = "primary-artifacts"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  secondary_artifacts {
    artifact_identifier    = "secondary_artifact_1"
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "secondary-artifact-1"
    path                   = "secondary-artifacts/build-output"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  secondary_artifacts {
    artifact_identifier    = "secondary_artifact_2"
    type                   = "S3"
    location               = aws_s3_bucket.build_artifacts.id
    name                   = "secondary-artifact-2"
    path                   = "secondary-artifacts/test-output"
    namespace_type         = "NONE"
    packaging              = "ZIP"
    override_artifact_name = true
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/standard:7.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"

    environment_variable {
      name  = "ENV_NAME"
      value = "dev"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "LOG_LEVEL"
      value = "info"
      type  = "PLAINTEXT"
    }

    environment_variable {
      name  = "APP_SECRET"
      value = aws_secretsmanager_secret.example.arn
      type  = "SECRETS_MANAGER"
    }
  }

  cache {
    type = "NO_CACHE"
  }

  logs_config {
    cloudwatch_logs {
      status      = "ENABLED"
      group_name  = aws_cloudwatch_log_group.codebuild_build_logs.name
      stream_name = local.log_stream_name
    }
  }

  tags = merge(local.common_tags, {
    Name = local.project_name
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all taggable resources"
  type        = string
  default     = "dev"
}

locals {
  tags = {
    Environment = var.environment
    Application = "greeting-lex-bot"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# IAM: execution role assumed by the Amazon Lex V2 service
# ------------------------------------------------------------------------------
resource "aws_iam_role" "lex_bot" {
  name        = "greeting-lex-bot-role"
  description = "Execution role assumed by lexv2.amazonaws.com for the greeting bot"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexV2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

# Least-privilege inline policy: the bot only needs Polly to synthesize voice replies
resource "aws_iam_role_policy" "lex_bot_polly" {
  name = "greeting-lex-bot-polly-synthesize"
  role = aws_iam_role.lex_bot.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowPollySynthesizeSpeech"
        Effect   = "Allow"
        Action   = ["polly:SynthesizeSpeech"]
        Resource = ["*"]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Amazon Lex V2 bot
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot" "lex_bot" {
  name                        = "greeting_bot"
  description                 = "Amazon Lex V2 bot that greets users and captures their name"
  role_arn                    = aws_iam_role.lex_bot.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Built en_US DRAFT locale with an Amazon Polly voice
resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.lex_bot.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "English (United States) locale"
  n_lu_intent_confidence_threshold = 0.70

  voice_settings {
    voice_id = "Joanna"
  }
}

# ------------------------------------------------------------------------------
# Custom slot type used by the greeting intent
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot_type" "user_name_type" {
  name        = "UserNameType"
  description = "Closed-list custom slot type used to capture the user's name"
  bot_id      = aws_lexv2models_bot.lex_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  slot_type_values {
    sample_value {
      value = "Alex"
    }
  }

  slot_type_values {
    sample_value {
      value = "Jordan"
    }
  }

  slot_type_values {
    sample_value {
      value = "Taylor"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }
}

# ------------------------------------------------------------------------------
# Greeting intent
# ------------------------------------------------------------------------------
resource "aws_lexv2models_intent" "greeting" {
  name        = "GreetingIntent"
  description = "Greets the user, elicits their name, and closes the conversation"
  bot_id      = aws_lexv2models_bot.lex_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "Hello"
  }

  sample_utterance {
    utterance = "Hi"
  }

  sample_utterance {
    utterance = "Good morning"
  }

  initial_response_setting {
    initial_response {
      message_group {
        message {
          plain_text_message {
            value = "Hello! I am your friendly greeting assistant."
          }
        }
      }
    }
  }

  closing_setting {
    active = true

    closing_response {
      message_group {
        message {
          plain_text_message {
            value = "Thanks for chatting with me. Goodbye!"
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Slot attached to the greeting intent to capture user input
# ------------------------------------------------------------------------------
resource "aws_lexv2models_slot" "user_name" {
  name         = "UserName"
  description  = "Captures the name of the user during the greeting flow"
  bot_id       = aws_lexv2models_bot.lex_bot.id
  bot_version  = "DRAFT"
  intent_id    = aws_lexv2models_intent.greeting.intent_id
  locale_id    = aws_lexv2models_bot_locale.en_us.locale_id
  slot_type_id = aws_lexv2models_slot_type.user_name_type.slot_type_id

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      allow_interrupt            = true
      max_retries                = 2
      message_selection_strategy = "Random"

      message_group {
        message {
          plain_text_message {
            value = "What is your name?"
          }
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Immutable numbered version created from the built DRAFT locale
# ------------------------------------------------------------------------------
resource "aws_lexv2models_bot_version" "initial" {
  bot_id      = aws_lexv2models_bot.lex_bot.id
  description = "Initial immutable version of the greeting bot"

  locale_specification = {
    "en_US" = {
      source_bot_version = "DRAFT"
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.user_name_type,
    aws_lexv2models_intent.greeting,
    aws_lexv2models_slot.user_name,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a user-controlled tag to every taggable resource."
  type        = string
  default     = "dev"
}

locals {
  bot_name = "ProductOrderingBot"

  common_tags = {
    Name        = local.bot_name
    Environment = var.environment
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "lex_trust" {
  statement {
    sid    = "AllowLexV2AssumeRole"
    effect = "Allow"

    actions = [
      "sts:AssumeRole",
    ]

    principals {
      type        = "Service"
      identifiers = ["lexv2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lex_execution_permissions" {
  statement {
    sid    = "LexCreateConversationLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/${local.bot_name}*",
    ]
  }

  statement {
    sid    = "LexWriteConversationLogStreams"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lex/${local.bot_name}*:log-stream:*",
    ]
  }

  statement {
    sid    = "LexDetectSentiment"
    effect = "Allow"

    actions = [
      "comprehend:DetectSentiment",
    ]

    # Comprehend does not support resource-level permissions for DetectSentiment;
    # the action itself is narrowly scoped to the single supported API operation.
    resources = ["*"]
  }
}

resource "aws_iam_role" "lex_execution" {
  name               = "${local.bot_name}-lex-execution-role"
  description        = "Execution role assumed by the Amazon Lex V2 service for the product ordering bot"
  assume_role_policy = data.aws_iam_policy_document.lex_trust.json

  tags = local.common_tags
}

resource "aws_iam_policy" "lex_execution" {
  name        = "${local.bot_name}-lex-execution-policy"
  description = "Least-privilege CloudWatch Logs and Comprehend permissions for the Lex V2 bot execution role"
  policy      = data.aws_iam_policy_document.lex_execution_permissions.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lex_execution" {
  role       = aws_iam_role.lex_execution.name
  policy_arn = aws_iam_policy.lex_execution.arn
}

resource "aws_lexv2models_bot" "main" {
  name        = local.bot_name
  description = "Product ordering bot that collects order details through multiple elicitation slots"
  role_arn    = aws_iam_role.lex_execution.arn

  data_privacy {
    child_directed = false
  }

  idle_session_ttl_in_seconds = 300

  # Aliases are declared inline as members of the bot resource. The member below
  # targets the first published version: Lex V2 assigns sequential numeric versions
  # starting at 1, and aws_lexv2models_bot_version.prod builds exactly that first
  # version from DRAFT. All member attributes are deterministic user-assigned
  # literals required by the schema — they must not reference any other resource,
  # and they must never change between plans, since the bot carries prevent_destroy.
  members {
    name       = "prod"
    alias_name = "prod"
    alias_id   = "prod"
    id         = "prod"
    version    = "1"
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.lex_execution]

  lifecycle {
    prevent_destroy = true
  }
}

# The en_US draft locale must exist before the slot type, intent, and slots can be
# created inside it. Per the Lex V2 API, locale creation is only permitted against
# the draft version, so bot_version is pinned to "DRAFT". The build that packages
# the complete configuration together is the bot version below, which is explicitly
# ordered after the locale, slot type, intent, and every slot via depends_on.
resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.main.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "English (US) locale for the product ordering bot"
  n_lu_intent_confidence_threshold = 0.7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot_type" "product_category" {
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  name        = "ProductCategory"
  description = "Closed enumeration of product categories that can be ordered"

  slot_type_values {
    sample_value {
      value = "Electronics"
    }
  }

  slot_type_values {
    sample_value {
      value = "Books"
    }
  }

  slot_type_values {
    sample_value {
      value = "HomeAndKitchen"
    }
  }

  slot_type_values {
    sample_value {
      value = "ToysAndGames"
    }
  }

  value_selection_setting {
    resolution_strategy = "OriginalValue"
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_intent" "order_product" {
  name        = "OrderProduct"
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  description = "Collects every detail required to place a product order"

  # Fulfillment intentionally has no Lambda code hook: the resolved intent and its
  # slot values are returned directly to the caller, keeping the bot self-contained.
  sample_utterance {
    utterance = "I would like to order a product"
  }

  sample_utterance {
    utterance = "I want to place an order"
  }

  sample_utterance {
    utterance = "Please help me order something"
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.product_category,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# Slots are declared in the intended elicitation order:
# OrderDate, Quantity, ProductCategory, ContactPhone.
resource "aws_lexv2models_slot" "order_date" {
  name         = "OrderDate"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.Date"
  description  = "The date the customer wants the order handled"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What date would you like your order for?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "quantity" {
  name         = "Quantity"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.Number"
  description  = "The number of units the customer wants to order"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "How many units would you like to order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "product_category" {
  name         = "ProductCategory"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = aws_lexv2models_slot_type.product_category.slot_type_id
  description  = "The category of the product the customer wants to order"

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What category of product would you like to order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_slot" "contact_phone" {
  name         = "ContactPhone"
  bot_id       = aws_lexv2models_bot.main.id
  bot_version  = "DRAFT"
  locale_id    = "en_US"
  intent_id    = aws_lexv2models_intent.order_product.intent_id
  slot_type_id = "AMAZON.PhoneNumber"
  description  = "The phone number used to contact the customer about the order"

  obfuscation_setting {
    obfuscation_setting_type = "DefaultObfuscation"
  }

  value_elicitation_setting {
    slot_constraint = "Required"

    prompt_specification {
      max_retries = 2

      message_group {
        message {
          plain_text_message {
            value = "What is the best phone number to reach you about this order?"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_version" "prod" {
  bot_id = aws_lexv2models_bot.main.id

  locale_specification = {
    en_US = {
      source_bot_version = "DRAFT"
    }
  }

  description = "Production version of the product ordering bot including all intents and slots"

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_slot_type.product_category,
    aws_lexv2models_intent.order_product,
    aws_lexv2models_slot.order_date,
    aws_lexv2models_slot.quantity,
    aws_lexv2models_slot.product_category,
    aws_lexv2models_slot.contact_phone,
  ]
}

output "bot_id" {
  description = "Identifier of the Amazon Lex V2 bot."
  value       = aws_lexv2models_bot.main.id
}

output "bot_locale_id" {
  description = "Identifier of the en_US bot locale."
  value       = aws_lexv2models_bot_locale.en_us.id
}

output "bot_alias_id" {
  description = "Provider-assigned identifier of the prod alias declared as a bot member."
  value       = one([for member in aws_lexv2models_bot.main.members : member.alias_id])
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "bot_name" {
  description = "Name of the Amazon Lex V2 pizza ordering bot."
  type        = string
  default     = "PizzaOrderingBot"
}

variable "environment" {
  description = "Environment label applied to the common tag set."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into the common tag set."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Project     = "pizza-ordering-bot"
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

# ---------------------------------------------------------------------------
# IAM: role assumed by the Lex bot, least-privilege inline policy for Polly
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lex_bot_assume_role" {
  statement {
    sid     = "AllowLexV2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lexv2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "lex_bot_polly" {
  statement {
    sid       = "AllowPollySpeechSynthesis"
    effect    = "Allow"
    actions   = ["polly:SynthesizeSpeech"]
    resources = ["*"]
  }
}

resource "aws_iam_role" "lex_bot_role" {
  name               = "${var.bot_name}-lex-role"
  description        = "Service role assumed by the pizza ordering Lex bot."
  assume_role_policy = data.aws_iam_policy_document.lex_bot_assume_role.json
}

resource "aws_iam_role_policy" "lex_bot_polly" {
  name   = "${var.bot_name}-polly-speech"
  role   = aws_iam_role.lex_bot_role.id
  policy = data.aws_iam_policy_document.lex_bot_polly.json
}

# ---------------------------------------------------------------------------
# Lex V2 bot and en_US locale (draft, with neural voice for spoken prompts)
# ---------------------------------------------------------------------------

resource "aws_lexv2models_bot" "pizza_ordering_bot" {
  name                        = var.bot_name
  description                 = "Conversational bot for ordering pizza with a drink or dessert followup."
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                           = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "US English locale for the pizza ordering bot."
  n_lu_intent_confidence_threshold = 0.7

  voice_settings {
    voice_id = "Joanna"
    engine   = "neural"
  }
}

