# ---------------------------------------------------------------------------
# Intents (slots are declared as standalone aws_lexv2models_slot resources)
# ---------------------------------------------------------------------------

resource "aws_lexv2models_intent" "order_pizza" {
  name        = "OrderPizza"
  description = "Captures a pizza order: kind, size, quantity, crust, and optional toppings."
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "I want to order a pizza"
  }

  sample_utterance {
    utterance = "I'd like to order a pizza"
  }

  sample_utterance {
    utterance = "pizza please"
  }

  sample_utterance {
    utterance = "order a pizza"
  }

  # Followup question: once the pizza is fully specified, ask about extras.
  confirmation_setting {
    prompt_specification {
      allow_interrupt = true
      max_retries     = 2

      message_group {
        message {
          plain_text_message {
            value = "Would you like to add a drink or dessert to your order?"
          }
        }
      }
    }

    confirmation_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Great! Let's get that added to your order."
          }
        }
      }
    }

    declination_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Okay, no problem."
          }
        }
      }
    }
  }

  closing_setting {
    active = true

    closing_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Awesome! Your pizza order is confirmed."
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

resource "aws_lexv2models_intent" "order_drink" {
  name        = "OrderDrink"
  description = "Followup intent that captures the drink added to the pizza order."
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "yes, add a drink"
  }

  sample_utterance {
    utterance = "a soda please"
  }

  sample_utterance {
    utterance = "I would like a drink"
  }

  sample_utterance {
    utterance = "add a drink to my order"
  }

  closing_setting {
    active = true

    closing_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Thanks! Your pizza and your drink are on the way. Enjoy!"
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

resource "aws_lexv2models_intent" "no_thanks" {
  name        = "NoThanks"
  description = "Declines the followup and closes out the pizza order."
  bot_id      = aws_lexv2models_bot.pizza_ordering_bot.id
  bot_version = "DRAFT"
  locale_id   = aws_lexv2models_bot_locale.en_us.locale_id

  sample_utterance {
    utterance = "no thanks"
  }

  sample_utterance {
    utterance = "no, that's all"
  }

  sample_utterance {
    utterance = "no thank you"
  }

  sample_utterance {
    utterance = "that will be all"
  }

  closing_setting {
    active = true

    closing_response {
      allow_interrupt = true

      message_group {
        message {
          plain_text_message {
            value = "Thanks! Your pizza is on its way."
          }
        }
      }
    }
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

