# ---------------------------------------------------------------------------
# OrderPizza intent
# ---------------------------------------------------------------------------

resource "aws_lex_intent" "pizza_order" {
  name           = "OrderPizza"
  description    = "Intent that collects pizza order details, confirms the order with the user, and concludes within the bot."
  create_version = true

  sample_utterances = [
    "I want to order a {Size} pizza",
    "I'd like {Quantity} pizzas with {Toppings}",
    "I want to order a {Size} pizza with {Crust} crust and {Toppings}",
    "I would like to order a pizza",
    "Can I get a pizza please"
  ]

  slot {
    name            = "Quantity"
    description     = "How many pizzas the customer wants to order."
    slot_type       = "AMAZON.NUMBER"
    slot_constraint = "Required"
    priority        = 1

    sample_utterances = [
      "I would like {Quantity} pizzas",
      "I want to order {Quantity} pizzas"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "How many pizzas would you like to order?"
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Size"
    description       = "Size of the pizza."
    slot_type         = aws_lex_slot_type.pizza_size.name
    slot_type_version = aws_lex_slot_type.pizza_size.version
    slot_constraint   = "Required"
    priority          = 2

    sample_utterances = [
      "I want a {Size} pizza",
      "Make it {Size}"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What size pizza would you like? You can choose small, medium, or large."
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Crust"
    description       = "Crust style of the pizza."
    slot_type         = aws_lex_slot_type.pizza_crust.name
    slot_type_version = aws_lex_slot_type.pizza_crust.version
    slot_constraint   = "Required"
    priority          = 3

    sample_utterances = [
      "I want {Crust} crust",
      "Make it {Crust} crust"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What kind of crust would you like? You can choose thin, regular, or deep dish."
        content_type = local.plain_text_content_type
      }
    }
  }

  slot {
    name              = "Toppings"
    description       = "Toppings for the pizza."
    slot_type         = aws_lex_slot_type.pizza_toppings.name
    slot_type_version = aws_lex_slot_type.pizza_toppings.version
    slot_constraint   = "Required"
    priority          = 4

    sample_utterances = [
      "with {Toppings}",
      "I want {Toppings} toppings"
    ]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content      = "What toppings would you like? You can choose pepperoni, mushroom, onion, sausage, or extra cheese."
        content_type = local.plain_text_content_type
      }
    }
  }

  confirmation_prompt {
    max_attempts = 3

    message {
      content      = "Just to confirm: you would like {Quantity} {Size} pizza(s) with {Crust} crust and {Toppings}. Is that correct?"
      content_type = local.plain_text_content_type
    }
  }

  rejection_statement {
    message {
      content      = "Okay, I have cancelled your pizza order. Is there anything else I can help you with?"
      content_type = local.plain_text_content_type
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  conclusion_statement {
    message {
      content      = "Thanks! Your order for {Quantity} {Size} pizza(s) with {Crust} crust and {Toppings} has been placed."
      content_type = local.plain_text_content_type
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Pizza ordering bot
# ---------------------------------------------------------------------------

resource "aws_lex_bot" "pizza_ordering_bot" {
  name        = "PizzaOrderingBot"
  description = "Conversational bot that takes pizza orders and concludes them within the bot."

  locale                      = "en-US"
  voice_id                    = "Joanna"
  child_directed              = false
  idle_session_ttl_in_seconds = 300
  process_behavior            = "BUILD"

  intent {
    intent_name    = aws_lex_intent.pizza_order.name
    intent_version = aws_lex_intent.pizza_order.version
  }

  clarification_prompt {
    max_attempts = 3

    message {
      content      = "Sorry, I did not understand that. You can say something like 'I want to order a large pizza with pepperoni'. What would you like to do?"
      content_type = local.plain_text_content_type
    }
  }

  abort_statement {
    message {
      content      = "I'm sorry, I was not able to complete your pizza order. Please try again later."
      content_type = local.plain_text_content_type
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_lex_intent" "book_trip" {
  name        = "BookTrip"
  description = "Intent for booking a trip"

  sample_utterances = [
    "Book a trip to {PickupCity} on {PickupDate}",
    "Book a trip from {PickupCity} to {ReturnCity}",
    "Schedule a trip for {PickupDate}",
    "I would like to book a trip from {PickupCity} to {ReturnCity} on {PickupDate}",
    "Book a trip with a driver age of {DriverAge}",
  ]

  confirmation_prompt {
    max_attempts = 1

    message {
      content_type = "PlainText"
      content      = "Just to confirm: a trip with pickup in {PickupCity} on {PickupDate}, drop-off in {ReturnCity}, and a driver age of {DriverAge}. Shall I book it?"
    }
  }

  rejection_statement {
    message {
      content_type = "PlainText"
      content      = "Okay, I will not book the trip. Let me know whenever you would like to try again."
    }
  }

  conclusion_statement {
    message {
      content_type = "PlainText"
      content      = "Your trip booking has been recorded. Thank you and have a great journey!"
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name              = "PickupCity"
    description       = "The city where the traveler will be picked up"
    priority          = 1
    slot_constraint   = "Required"
    slot_type         = "AMAZON.City"
    slot_type_version = "1"
    sample_utterances = ["Seattle"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "In which city would you like to be picked up?"
      }
    }
  }

  slot {
    name              = "PickupDate"
    description       = "The date on which the trip starts"
    priority          = 2
    slot_constraint   = "Required"
    slot_type         = "AMAZON.Date"
    slot_type_version = "1"
    sample_utterances = ["tomorrow"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "On which date would you like to start your trip?"
      }
    }
  }

  slot {
    name              = "ReturnCity"
    description       = "The destination city where the trip ends"
    priority          = 3
    slot_constraint   = "Required"
    slot_type         = "AMAZON.City"
    slot_type_version = "1"
    sample_utterances = ["Portland"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "In which city would you like your trip to end?"
      }
    }
  }

  slot {
    name              = "DriverAge"
    description       = "The age of the driver for the trip"
    priority          = 4
    slot_constraint   = "Required"
    slot_type         = "AMAZON.Number"
    slot_type_version = "1"
    sample_utterances = ["30"]

    value_elicitation_prompt {
      max_attempts = 3

      message {
        content_type = "PlainText"
        content      = "What is the age of the driver for this trip?"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot" "trip_booking_bot" {
  name        = "TripBookingBot"
  description = "Bot for booking trips"

  locale                          = "en-US"
  child_directed                  = false
  process_behavior                = "BUILD"
  create_version                  = true
  detect_sentiment                = true
  idle_session_ttl_in_seconds     = 300
  voice_id                        = "Joanna"
  enable_model_improvements       = true
  nlu_intent_confidence_threshold = 0.6

  intent {
    intent_name    = aws_lex_intent.book_trip.name
    intent_version = "$LATEST"
  }

  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Sorry, I am unable to book your trip at this time. Please try again later."
    }
  }

  clarification_prompt {
    max_attempts = 2

    message {
      content_type = "PlainText"
      content      = "Sorry, I did not understand that. Could you please rephrase your trip booking request?"
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "bot_name" {
  description = "Name of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.name
}

output "bot_arn" {
  description = "ARN of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.arn
}

output "bot_status" {
  description = "Build status of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.status
}

output "bot_version" {
  description = "Published version of the Lex trip booking bot"
  value       = aws_lex_bot.trip_booking_bot.version
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "User-controlled project name used as the naming prefix for all Lex, IAM, and CloudWatch resources."
  type        = string
  default     = "pizza-bot"
}

data "aws_caller_identity" "current" {}

locals {
  # Amazon Lex bot, alias, intent, and slot type names only accept letters and
  # underscores, so the project name is normalized to snake_case for Lex names.
  name_prefix    = lower(replace(var.project_name, "-", "_"))
  log_group_name = "/aws/lex/${local.name_prefix}"
  log_group_arn  = "arn:aws:logs:us-east-1:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}"

  tags = {
    Project   = var.project_name
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# IAM: execution role assumed by Amazon Lex for conversation logging
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lex_bot_role" {
  name        = "${local.name_prefix}_lex_bot_role"
  description = "Execution role assumed by Amazon Lex for the ${var.project_name} pizza ordering bot."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "lex_bot_policy" {
  name = "${local.name_prefix}_lex_bot_policy"
  role = aws_iam_role.lex_bot_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSpeechSynthesisAndSentimentDetection"
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech",
          "comprehend:DetectSentiment",
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowConversationLogWrites"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
        ]
        Resource = aws_cloudwatch_log_group.lex_conversation_logs.arn
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# KMS + CloudWatch Logs: encrypted, auditable conversation log storage
# -----------------------------------------------------------------------------

resource "aws_kms_key" "lex_conversation_logs" {
  description             = "Encrypts CloudWatch conversation logs for the ${var.project_name} Lex bot."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe",
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = local.log_group_arn
          }
        }
      },
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "lex_conversation_logs" {
  name          = "alias/${local.name_prefix}_lex_conversation_logs"
  target_key_id = aws_kms_key.lex_conversation_logs.key_id
}

resource "aws_cloudwatch_log_group" "lex_conversation_logs" {
  name              = local.log_group_name
  retention_in_days = 14
  kms_key_id        = aws_kms_key.lex_conversation_logs.arn

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Lex: custom slot types for the pizza domain
# -----------------------------------------------------------------------------

resource "aws_lex_slot_type" "pizza_size" {
