# -----------------------------------------------------------------------------
# Lex intent for ordering a pizza, fulfilled by Lambda
# -----------------------------------------------------------------------------
resource "aws_lex_intent" "order_pizza" {
  name           = "order_pizza"
  description    = "Collects a pizza order (size, crust, toppings, quantity) and fulfills it with Lambda"
  create_version = true

  sample_utterances = [
    "I would like to order a {pizza_size} pizza",
    "I want to order {quantity} {pizza_size} pizzas",
    "Order a {pizza_size} {pizza_crust} pizza with {pizza_toppings}",
    "I would like a {pizza_size} pizza with {pizza_crust} crust",
    "Please order me a {pizza_size} pizza",
    "Order pizza",
  ]

  slot {
    name              = "pizza_size"
    description       = "Size of the pizza"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_size_type.name
    slot_type_version = aws_lex_slot_type.pizza_size_type.version
    priority          = 1

    sample_utterances = [
      "I would like a {pizza_size} pizza",
      "Make it a {pizza_size} pizza",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What size pizza would you like - small, medium, or large?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "pizza_crust"
    description       = "Style of the pizza crust"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_crust_type.name
    slot_type_version = aws_lex_slot_type.pizza_crust_type.version
    priority          = 2

    sample_utterances = [
      "I would like a {pizza_size} pizza with {pizza_crust} crust",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "What kind of crust would you like - thin or thick?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name              = "pizza_toppings"
    description       = "Topping for the pizza"
    slot_constraint   = "Required"
    slot_type         = aws_lex_slot_type.pizza_toppings_type.name
    slot_type_version = aws_lex_slot_type.pizza_toppings_type.version
    priority          = 3

    sample_utterances = [
      "I would like a {pizza_size} pizza with {pizza_toppings}",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "Which topping would you like - pepperoni, mushroom, sausage, onion, olives, or bacon?"
        content_type = "PlainText"
      }
    }
  }

  slot {
    name            = "quantity"
    description     = "Number of pizzas to order"
    slot_constraint = "Required"
    slot_type       = "AMAZON.Number"
    priority        = 4

    sample_utterances = [
      "I would like {quantity} pizzas",
    ]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content      = "How many pizzas would you like?"
        content_type = "PlainText"
      }
    }
  }

  fulfillment_activity {
    type = "CodeHook"

    code_hook {
      uri             = aws_lambda_function.pizza_fulfillment.arn
      message_version = "1"
    }
  }
}

# -----------------------------------------------------------------------------
# Lex bot and stable production alias
# -----------------------------------------------------------------------------
resource "aws_lex_bot" "pizza_order_bot" {
  name                          = "PizzaOrderBot"
  description                   = "Takes pizza orders and fulfills them with Lambda"
  locale                        = "en-US"
  process_behavior              = "BUILD"
  child_directed                = false
  voice_id                      = "Joanna"
  create_version                = true
  enable_model_improvements     = true
  nlu_intent_confidence_threshold = 0.75
  idle_session_ttl_in_seconds   = 300

  intent {
    intent_name    = aws_lex_intent.order_pizza.name
    intent_version = aws_lex_intent.order_pizza.version
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Sorry, I did not catch that. Could you please repeat your pizza order?"
      content_type = "PlainText"
    }
  }

  abort_statement {
    message {
      content      = "Sorry, I could not process your pizza order. Please try again later."
      content_type = "PlainText"
    }
  }

  depends_on = [aws_iam_service_linked_role.lex]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lex_bot_alias" "pizza_bot_prod" {
  bot_name    = aws_lex_bot.pizza_order_bot.name
  bot_version = aws_lex_bot.pizza_order_bot.version
  name        = "pizza_bot_prod"
  description = "Production alias for the pizza ordering Lex bot"
}

# -----------------------------------------------------------------------------
# Outputs for downstream consumers
# -----------------------------------------------------------------------------
output "pizza_bot_name" {
  description = "Name of the pizza ordering Lex bot"
  value       = aws_lex_bot.pizza_order_bot.name
}

output "pizza_bot_arn" {
  description = "ARN of the pizza ordering Lex bot"
  value       = aws_lex_bot.pizza_order_bot.arn
}

output "pizza_bot_version" {
  description = "Published version of the pizza ordering Lex bot"
  value       = aws_lex_bot.pizza_order_bot.version
}

output "pizza_bot_alias_name" {
  description = "Name of the production alias for the pizza ordering Lex bot"
  value       = aws_lex_bot_alias.pizza_bot_prod.name
}

output "pizza_bot_alias_arn" {
  description = "ARN of the production alias for the pizza ordering Lex bot"
  value       = aws_lex_bot_alias.pizza_bot_prod.arn
}

output "pizza_fulfillment_lambda_name" {
  description = "Name of the pizza fulfillment Lambda function"
  value       = aws_lambda_function.pizza_fulfillment.function_name
}

output "pizza_fulfillment_lambda_arn" {
  description = "ARN of the pizza fulfillment Lambda function"
  value       = aws_lambda_function.pizza_fulfillment.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Project     = "lex-main-bot"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "polly_synthesize_speech" {
  name = "polly-synthesize-speech"
  role = aws_iam_role.lex_bot_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "polly:SynthesizeSpeech"
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "main" {
  name                        = "MainBot"
  description                 = "Main Lex V2 conversational bot managed by Terraform."
  role_arn                    = aws_iam_role.lex_bot_role.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_iam_role_policy.polly_synthesize_speech]
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id                            = aws_lexv2models_bot.main.id
  bot_version                       = "DRAFT"
  locale_id                         = "en_US"
  n_lu_intent_confidence_threshold  = 0.40
  description                       = "US English locale for MainBot."

  voice_settings {
    voice_id = "Joanna"
    engine   = "standard"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_intent" "greeting" {
  name        = "GreetingIntent"
  description = "Greets users in response to common greetings."
  bot_id      = aws_lexv2models_bot.main.id
  bot_version = "DRAFT"
  locale_id   = "en_US"

  sample_utterance {
    utterance = "hello"
  }

  sample_utterance {
    utterance = "hi"
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_lexv2models_bot_locale.en_us]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

variable "bot_name" {
  description = "User-controlled name of the child-friendly Lex V2 bot."
  type        = string
  default     = "children_assistant_bot"
}

variable "description" {
  description = "User-controlled description identifying the bot as a kid-friendly assistant."
  type        = string
  default     = "Kid-friendly assistant bot for children with age-appropriate conversation design and COPPA child-directed data handling."
}

variable "environment" {
  description = "User-controlled environment tag applied to tagged resources."
  type        = string
  default     = "dev"
}

resource "aws_iam_role" "lex_bot_runtime" {
  name        = "children-assistant-bot-runtime"
  description = "Runtime service role assumed by Amazon Lex V2 for the children assistant bot."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLexV2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name        = "children-assistant-bot-runtime"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy" "lex_bot_runtime" {
  name = "children-assistant-bot-runtime-policy"
  role = aws_iam_role.lex_bot_runtime.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LexRuntimeSpeechAndSentiment"
        Effect = "Allow"
        Action = [
          "polly:SynthesizeSpeech",
          "comprehend:DetectSentiment"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "children_bot" {
  name        = var.bot_name
  description = var.description
  role_arn    = aws_iam_role.lex_bot_runtime.arn

  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = true
  }

  tags = {
    Name        = var.bot_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lexv2models_bot_locale" "en_us" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = "en_US"

  description = "Child-friendly en_US locale using the Ivy neural voice."

  n_lu_intent_confidence_threshold = 0.40

  voice_settings {
    voice_id = "Ivy"
    engine   = "neural"
  }
}

resource "aws_lexv2models_intent" "greeting" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  bot_version = "DRAFT"
  locale_id   = "en_US"
  name        = "Greeting"

  description = "Age-appropriate greeting intent so children can say hi and hear what the bot can do."

  sample_utterance {
    utterance = "hi"
  }

  sample_utterance {
    utterance = "hello"
  }

  sample_utterance {
    utterance = "what can you do"
  }

  closing_setting {
    active = true

    closing_response {
      message_group {
        message {
          plain_text_message {
            value = "Hi friend! I am your buddy bot. You can say hi, hello, or ask me what I can do. See you soon!"
          }
        }
      }
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us
  ]
}

resource "aws_lexv2models_bot_version" "children_bot_v1" {
  bot_id      = aws_lexv2models_bot.children_bot.id
  description = "Stable numbered snapshot of the children assistant DRAFT bot for downstream consumers."

  locale_specification = {
    "en_US" = {
      source_bot_version = "DRAFT"
    }
  }

  depends_on = [
    aws_lexv2models_bot_locale.en_us,
    aws_lexv2models_intent.greeting
  ]
}

output "bot_id" {
  description = "Unique identifier of the children assistant Lex V2 bot."
  value       = aws_lexv2models_bot.children_bot.id
}

output "bot_arn" {
  description = "ARN of the children assistant Lex V2 bot."
  value       = aws_lexv2models_bot.children_bot.arn
}

output "bot_version" {
  description = "Stable numbered bot version created from the DRAFT locale snapshot."
  value       = aws_lexv2models_bot_version.children_bot_v1.bot_version
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and the Name tag."
  type        = string
  default     = "connect-lex-bot"
}

variable "environment" {
  description = "Environment name applied to the Environment tag."
  type        = string
  default     = "production"
}

locals {
  lex_bot_name      = replace(var.project_name, "-", "_")
  lex_bot_role_name = "${var.project_name}-lex-bot-role"

  common_tags = {
    Name        = var.project_name
    Environment = var.environment
  }
}

resource "aws_connect_instance" "main" {
  instance_alias            = var.project_name
  identity_management_type  = "SAML"
  inbound_calls_enabled     = true
  outbound_calls_enabled    = true
  contact_flow_logs_enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "lex_bot" {
  name = local.lex_bot_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "lex_bot" {
  name = "${local.lex_bot_role_name}-polly"
  role = aws_iam_role.lex_bot.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "polly:DescribeVoices",
          "polly:SynthesizeSpeech"
        ]
        # Amazon Polly does not support resource-level permissions,
        # so the resource scope must remain "*".
        Resource = "*"
      }
    ]
  })
}

resource "aws_lexv2models_bot" "main" {
  name                        = local.lex_bot_name
  description                 = "Lex V2 bot associated with the Amazon Connect instance."
  role_arn                    = aws_iam_role.lex_bot.arn
  idle_session_ttl_in_seconds = 300

  data_privacy {
    child_directed = false
  }

  depends_on = [aws_iam_role_policy.lex_bot]

  tags = local.common_tags
}

resource "aws_lexv2models_bot_locale" "main" {
  bot_id                           = aws_lexv2models_bot.main.id
  bot_version                      = "DRAFT"
  locale_id                        = "en_US"
  description                      = "US English locale for the Connect-associated Lex bot."
  n_lu_intent_confidence_threshold = 0.7

  voice_settings {
    voice_id = "Joanna"
    engine   = "standard"
  }
}

resource "aws_connect_bot_association" "main" {
  instance_id = aws_connect_instance.main.id

  lex_bot {
    name       = aws_lexv2models_bot.main.name
    lex_region = "us-east-1"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name for the kids assistant stack (non-sensitive)."
  type        = string
  default     = "dev"
}

# Amazon Connect instance for the kids telephony experience.
resource "aws_connect_instance" "kids_connect" {
  instance_alias           = "kids-connect"
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true

  lifecycle {
    prevent_destroy = true
  }
}

# Kid-friendly greeting intent, fulfilled without any Lambda hook.
resource "aws_lex_intent" "kids_greeting" {
  name        = "KidsGreeting"
  description = "Friendly greeting intent for the kids assistant bot"

  sample_utterances = [
    "hello",
    "hi",
    "hey there",
    "good morning",
    "can you help me",
  ]

  fulfillment_activity {
    type = "ReturnIntent"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Kid-friendly Lex bot, COPPA-compliant via child_directed.
resource "aws_lex_bot" "kids_assistant" {
  name                      = "kids_assistant_bot"
  description               = "Kid-friendly assistant bot for the ${var.environment} environment"
  child_directed            = true
  enable_model_improvements = true
  locale                    = "en-US"
  process_behavior          = "BUILD"

  abort_statement {
    message {
      content      = "Sorry, I did not understand that. Goodbye for now, friend!"
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content      = "Hmm, I did not quite catch that. Can you say it one more time?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name    = aws_lex_intent.kids_greeting.name
    intent_version = "$LATEST"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Associate the kid-friendly Lex bot with the kids Connect instance.
resource "aws_connect_bot_association" "kids_bot" {
  instance_id = aws_connect_instance.kids_connect.id

  lex_bot {
    name       = aws_lex_bot.kids_assistant.name
    lex_region = "us-east-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "connect_instance_id" {
  description = "The ID of the Amazon Connect instance."
  value       = aws_connect_instance.kids_connect.id
}

output "connect_instance_alias" {
  description = "The alias of the Amazon Connect instance."
  value       = aws_connect_instance.kids_connect.instance_alias
}

output "lex_bot_name" {
  description = "The name of the kid-friendly Lex bot associated with the Connect instance."
  value       = aws_lex_bot.kids_assistant.name
}

