terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "env" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  stream_name  = "${var.env}-data-stream"
  kms_key_name = "${var.env}-kinesis-data-stream-key"

  common_tags = {
    Environment = var.env
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "kinesis" {
  description             = "Customer managed KMS key used for server-side encryption of the ${local.stream_name} Kinesis data stream."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = local.kms_key_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream" "data_stream" {
  name             = local.stream_name
  shard_count      = 1
  retention_period = 24

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords",
    "WriteProvisionedThroughputExceeded",
    "ReadProvisionedThroughputExceeded",
    "IteratorAgeMilliseconds",
  ]

  tags = merge(local.common_tags, {
    Name = local.stream_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "data_stream_name" {
  description = "Name of the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.name
}

output "data_stream_arn" {
  description = "ARN of the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.arn
}

output "data_stream_shard_count" {
  description = "Number of shards in the Kinesis data stream."
  value       = aws_kinesis_stream.data_stream.shard_count
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for server-side encryption of the stream."
  value       = aws_kms_key.kinesis.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

# ----------------------------------------------------------------------------
# User-controlled variables (all defaults are set so `terraform apply` runs
# unattended; no variables are used as substitutes for resource attributes)
# ----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "stream_analytics"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "shard_count" {
  description = "Number of shards for the provisioned input Kinesis data stream."
  type        = number
  default     = 1

  validation {
    condition     = var.shard_count >= 1
    error_message = "The shard_count value must be at least 1."
  }
}

# ----------------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------------

locals {
  # Matches the provider's fixed region above; used for ARN construction in
  # the KMS key policy so region naming is not dependent on data source
  # attribute availability across provider versions.
  region = "us-east-1"

  common_tags = {
    project     = var.project_name
    environment = var.environment
    managed-by  = "terraform"
  }

  stream_name      = "${var.project_name}_input_stream"
  app_name         = "${var.project_name}_app"
  role_name        = "${var.project_name}_${var.environment}_kinesis_analytics_role"
  log_group_name   = "/aws/kinesis-analytics/${var.project_name}"
  log_stream_name  = "${var.project_name}_${var.environment}_app_logs"
  logs_policy_name = "${var.project_name}_${var.environment}_analytics_logs_write"
}

# ----------------------------------------------------------------------------
# Data sources (static provider metadata only, no pre-existing infrastructure)
# ----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ----------------------------------------------------------------------------
# Customer-managed KMS key for the Kinesis stream and CloudWatch log group
# ----------------------------------------------------------------------------

resource "aws_kms_key" "kinesis" {
  description             = "Customer managed key encrypting the ${var.project_name} Kinesis stream and its CloudWatch Logs."
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowKinesisServiceUse"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
          "kms:DescribeKey",
          "kms:GenerateDataKey*",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.${local.region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnEquals = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:aws:logs:${local.region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}"
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# Input Kinesis data stream (the sole data source for the analytics app)
# ----------------------------------------------------------------------------

resource "aws_kinesis_stream" "input_stream" {
  name        = local.stream_name
  shard_count = var.shard_count

  # Retention period is measured in hours (24 hours retention; maximum 168).
  # Do NOT rename this argument to `retention_period_hours` — that legacy
  # attribute name is unsupported in AWS provider v5 and fails validation.
  retention_period = 24

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  shard_level_metrics = [
    "IncomingBytes",
    "IncomingRecords",
    "OutgoingBytes",
    "OutgoingRecords",
    "WriteProvisionedThroughputExceeded",
    "ReadProvisionedThroughputExceeded",
    "IteratorAgeMilliseconds",
  ]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# CloudWatch Logs for Kinesis Analytics application diagnostics
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = 365
  kms_key_id        = aws_kms_key.kinesis.arn

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# ----------------------------------------------------------------------------
# Service execution role for the Kinesis Analytics application
# ----------------------------------------------------------------------------

resource "aws_iam_role" "kinesis_analytics" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# Inline policy: least-privilege read access scoped to the input stream only.
resource "aws_iam_role_policy" "kinesis_input_stream_read" {
  name = "kinesis_input_stream_read"
  role = aws_iam_role.kinesis_analytics.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadInputStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:ListShards",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords"
        ]
        Resource = aws_kinesis_stream.input_stream.arn
      }
    ]
  })
}

# Managed policy + attachment: minimal CloudWatch Logs write access scoped to
# the created log group and log stream only.
resource "aws_iam_policy" "analytics_logs_write" {
  name        = local.logs_policy_name
  description = "Least-privilege CloudWatch Logs write access for the ${var.project_name} Kinesis Analytics application."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteApplicationDiagnostics"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "analytics_logs_write" {
  role       = aws_iam_role.kinesis_analytics.name
  policy_arn = aws_iam_policy.analytics_logs_write.arn
}

# ----------------------------------------------------------------------------
# Kinesis Analytics application
#
# The classic SQL runtime is implied by the aws_kinesis_analytics_application
# resource type (vs. the Flink runtime resource). The service execution role
# is wired through the per-input kinesis_stream.role_arn and the
# cloudwatch_logging_options.role_arn, both referencing the least-privilege
# IAM role created above.
# ----------------------------------------------------------------------------

resource "aws_kinesis_analytics_application" "stream_analytics_app" {
  name        = local.app_name
  description = "Basic Kinesis Analytics (SQL) application consuming records from the ${local.stream_name} Kinesis stream."

  inputs {
    id          = "1.1"
    name_prefix = "INPUT"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics.arn
    }

    schema {
      record_columns {
        name     = "event_type"
        mapping  = "$.event_type"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "event_time"
        mapping  = "$.event_time"
        sql_type = "TIMESTAMP"
      }

      record_columns {
        name     = "payload"
        mapping  = "$.payload"
        sql_type = "VARCHAR(1024)"
      }

      record_format {
        # JSON records map source fields by record row path; column and row
        # delimiter mapping parameters apply only to the CSV record format.
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"
    }

    starting_position_configuration {
      starting_position = "LATEST"
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics.arn
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy.kinesis_input_stream_read,
    aws_iam_role_policy_attachment.analytics_logs_write,
  ]
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "kinesis_stream_name" {
  description = "Name of the input Kinesis data stream."
  value       = aws_kinesis_stream.input_stream.name
}

output "kinesis_stream_arn" {
  description = "ARN of the input Kinesis data stream."
  value       = aws_kinesis_stream.input_stream.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for encryption."
  value       = aws_kms_key.kinesis.arn
}

output "analytics_application_arn" {
  description = "ARN of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.stream_analytics_app.arn
}

output "analytics_application_id" {
  description = "ID of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.stream_analytics_app.id
}

output "analytics_service_role_arn" {
  description = "ARN of the Kinesis Analytics service execution IAM role."
  value       = aws_iam_role.kinesis_analytics.arn
}

output "cloudwatch_log_group_arn" {
  description = "ARN of the CloudWatch log group capturing application diagnostics."
  value       = aws_cloudwatch_log_group.kinesis_analytics.arn
}

output "cloudwatch_log_stream_arn" {
  description = "ARN of the CloudWatch log stream capturing application diagnostics."
  value       = aws_cloudwatch_log_stream.kinesis_analytics.arn
}

###############################################################################
# Terraform setup
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static provider metadata lookups (no dependency on pre-existing infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Variables (non-infrastructure values only, all defaulted for unattended apply)
###############################################################################

variable "application_name_suffix" {
  description = "Suffix used when constructing the application and resource names"
  type        = string
  default     = "flink-app"
}

variable "environment" {
  description = "Environment classification applied as a tag to every resource"
  type        = string
  default     = "dev"
}

variable "log_retention_days" {
  description = "CloudWatch Logs retention period (in days) for the application log group"
  type        = number
  default     = 14

  validation {
    condition = contains(
      [1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653],
      var.log_retention_days
    )
    error_message = "log_retention_days must be a value accepted by CloudWatch Logs (e.g. 1, 3, 5, 7, 14, 30, 365)."
  }
}

variable "flink_parallelism" {
  description = "Initial parallelism for the Flink application"
  type        = number
  default     = 1
}

variable "flink_parallelism_per_kpu" {
  description = "Flink parallelism per Kinesis Processing Unit (KPU)"
  type        = number
  default     = 1
}

variable "flink_application_properties" {
  description = "Runtime configuration properties passed to the Flink application"
  type        = map(string)
  default = {
    INPUT_STREAM_NAME     = "example-input-stream"
    OUTPUT_STREAM_NAME    = "example-output-stream"
    AGGREGATION_WINDOW_MS = "1000"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  application_name = "kda-${var.application_name_suffix}-${var.environment}"

  aws_region = data.aws_region.current.name

  code_bucket_name = "kda-${var.application_name_suffix}-${var.environment}-code-${data.aws_caller_identity.current.account_id}"

  # Constructed from static provider metadata (avoids a dependency cycle with
  # the log group resource, which consumes this KMS key). Log group ARNs as
  # reported by AWS carry a trailing ":*", so the wildcard pattern below
  # matches both forms under ArnLike.
  flink_log_group_arn_pattern = "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kinesisanalytics/${local.application_name}:*"

  common_tags = {
    Application = local.application_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# S3 code bucket hosting the Apache Flink application JAR
###############################################################################

resource "aws_s3_bucket" "code" {
  bucket = local.code_bucket_name

  tags = merge(local.common_tags, {
    Name = local.code_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "code" {
  bucket = aws_s3_bucket.code.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "code" {
  bucket = aws_s3_bucket.code.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "code" {
  bucket = aws_s3_bucket.code.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.flink_app.arn
    }
  }
}

resource "aws_s3_bucket_policy" "code" {
  bucket = aws_s3_bucket.code.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.code.arn,
          "${aws_s3_bucket.code.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.code]
}

resource "aws_s3_object" "flink_code" {
  bucket = aws_s3_bucket.code.id
  key    = "flink-app/code.jar"

  content      = "placeholder-flink-application-jar"
  content_type = "application/java-archive"

  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.flink_app.arn

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-code-artifact"
  })

  depends_on = [
    aws_s3_bucket_versioning.code,
    aws_s3_bucket_server_side_encryption_configuration.code,
  ]
}

###############################################################################
# Customer-managed KMS key enforcing at-rest encryption
###############################################################################

resource "aws_kms_key" "flink_app" {
  description             = "Customer-managed key encrypting the ${local.application_name} Flink application"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowFlinkServiceExecutionRoleApplicationEncryption"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.flink_app_exec.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsLogGroupEncryption"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${local.aws_region}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = local.flink_log_group_arn_pattern
          }
        }
      },
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "flink_app" {
  name          = "alias/${local.application_name}"
  target_key_id = aws_kms_key.flink_app.key_id
}

###############################################################################
# CloudWatch Logs for Flink operator/metrics logging (CMK-encrypted log group)
###############################################################################

resource "aws_cloudwatch_log_group" "flink_app" {
  name              = "/aws/kinesisanalytics/${local.application_name}"
  retention_in_days = var.log_retention_days
  kms_key_id        = aws_kms_key.flink_app.arn

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "flink_app" {
  name           = "${local.application_name}-operator-logs"
  log_group_name = aws_cloudwatch_log_group.flink_app.name
}

###############################################################################
# Service execution IAM role (trusted only by Kinesis Analytics)
###############################################################################

resource "aws_iam_role" "flink_app_exec" {
  name = "${local.application_name}-service-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowKinesisAnalyticsAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "flink_app_exec" {
  name        = "${local.application_name}-service-exec-policy"
  description = "Least-privilege permissions for the ${local.application_name} Flink application"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.flink_app.arn,
          aws_cloudwatch_log_stream.flink_app.arn,
          "${aws_cloudwatch_log_group.flink_app.arn}:log-stream:*",
        ]
      },
      {
        Sid    = "ReadApplicationCode"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
        ]
        Resource = [
          aws_s3_bucket.code.arn,
          "${aws_s3_bucket.code.arn}/*",
        ]
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "flink_app_exec" {
  role       = aws_iam_role.flink_app_exec.name
  policy_arn = aws_iam_policy.flink_app_exec.arn
}

###############################################################################
# Kinesis Analytics V2 (Managed Service for Apache Flink) application
# At-rest encryption is enforced through the customer-managed KMS key chain:
# the S3 code bucket (SSE-KMS) and the KMS-encrypted code artifact both
# reference aws_kms_key.flink_app, whose key policy grants the service
# execution role kms:Decrypt / kms:GenerateDataKey.
###############################################################################

resource "aws_kinesisanalyticsv2_application" "flink_app" {
  name                   = local.application_name
  description            = "Apache Flink streaming application provisioned and managed by Terraform"
  runtime_environment    = "FLINK-1_18"
  service_execution_role = aws_iam_role.flink_app_exec.arn

  application_configuration {
    application_code_configuration {
      code_content_type = "ZIPLINK_OR_JARLINK"

      code_content {
        s3_content_location {
          bucket_arn     = aws_s3_bucket.code.arn
          file_key       = aws_s3_object.flink_code.key
          object_version = aws_s3_object.flink_code.version_id
        }
      }
    }

    environment_properties {
      property_group {
        property_group_id = "FLINK_APPLICATION_PROPERTIES"
        property_map      = var.flink_application_properties
      }
    }

    flink_application_configuration {
      monitoring_configuration {
        configuration_type = "CUSTOM"
        metrics_level      = "APPLICATION"
        log_level          = "INFO"
      }

      parallelism_configuration {
        configuration_type   = "CUSTOM"
        auto_scaling_enabled = false
        parallelism          = var.flink_parallelism
        parallelism_per_kpu  = var.flink_parallelism_per_kpu
      }
    }

    run_configuration {
      flink_run_configuration {
        allow_non_restored_state = false
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.flink_app.arn
  }

  tags = merge(local.common_tags, {
    Name = local.application_name
  })

  depends_on = [
    aws_iam_role_policy_attachment.flink_app_exec,
    aws_s3_bucket_versioning.code,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs (non-sensitive identifiers only)
###############################################################################

output "application_arn" {
  description = "ARN of the Kinesis Analytics V2 (Apache Flink) application"
  value       = aws_kinesisanalyticsv2_application.flink_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Analytics V2 (Apache Flink) application"
  value       = aws_kinesisanalyticsv2_application.flink_app.name
}

output "service_execution_role_arn" {
  description = "ARN of the application service execution IAM role"
  value       = aws_iam_role.flink_app_exec.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the application"
  value       = aws_kms_key.flink_app.arn
}

output "code_bucket_name" {
  description = "Name of the S3 bucket hosting the Flink application JAR"
  value       = aws_s3_bucket.code.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  firehose_stream_name = "customer-events-delivery-stream"
  s3_bucket_name       = "firehose-dp-destination-${data.aws_caller_identity.current.account_id}"

  s3_prefix = "data/customerId=!{partitionKeyFromQuery:customerId}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"

  s3_error_prefix = "errors/!{firehose:error-output-type}/year=!{timestamp:yyyy}/month=!{timestamp:MM}/day=!{timestamp:dd}/"
}

variable "tags" {
  description = "Tags applied to the destination S3 bucket, the Firehose IAM role, and the delivery stream."
  type        = map(string)
  default = {
    Project     = "firehose-dynamic-partitioning"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_s3_bucket" "firehose_destination" {
  bucket = local.s3_bucket_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_cloudwatch_log_group" "firehose_delivery_errors" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_errors" {
  name           = "S3Delivery"
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_errors.name
}

resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "firehose_delivery_policy" {
  name = "firehose-delivery-least-privilege"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FirehoseS3BucketLevel"
        Effect   = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.firehose_destination.arn
      },
      {
        Sid      = "FirehoseS3ObjectLevel"
        Effect   = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.firehose_destination.arn}/*"
      },
      {
        Sid      = "FirehoseErrorLogging"
        Effect   = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.firehose_delivery_errors.arn}:*"
      }
    ]
  })
}

resource "aws_kinesis_firehose_delivery_stream" "customer_events" {
  name        = local.firehose_stream_name
  destination = "extended_s3"

  server_side_encryption {
    enabled  = true
    key_type = "AWS_OWNED_CMK"
  }

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery_role.arn
    bucket_arn          = aws_s3_bucket.firehose_destination.arn
    prefix              = local.s3_prefix
    error_output_prefix = local.s3_error_prefix
    compression_format  = "GZIP"
    buffering_size      = 64
    buffering_interval  = 60

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_errors.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_errors.name
    }

    dynamic_partitioning_configuration {
      enabled        = true
      retry_duration = 300
    }

    processing_configuration {
      enabled = true

      processors {
        type = "MetadataExtraction"

        parameters {
          parameter_name  = "metadataExtractionQuery"
          parameter_value = "{customerId:.customerId}"
        }

        parameters {
          parameter_name  = "jsonParsingEngine"
          parameter_value = "JQ-1.6"
        }
      }
    }
  }

  tags = var.tags

  depends_on = [aws_iam_role_policy.firehose_delivery_policy]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables: user-controlled, non-infrastructure values only (all defaulted so
# `terraform apply` runs unattended). No variable holds a secret or substitutes
# for a resource attribute.
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to merge onto every taggable resource."
  type        = map(string)
  default     = {}
}

variable "vpc_cidr" {
  description = "CIDR block for the greenfield VPC hosting the Redshift cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "admin_cidr" {
  description = "Private CIDR of the administrator network allowed to reach Redshift on TCP 5439."
  type        = string
  default     = "192.168.0.0/16"
}

variable "destination_table_name" {
  description = "Redshift destination table for the Firehose COPY command (table DDL is managed out-of-band)."
  type        = string
  default     = "firehose_events"
}

# -----------------------------------------------------------------------------
# Static provider metadata lookup only (no infrastructure discovery).
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix          = "firehose-redshift-${var.environment}"
  firehose_stream_name = "firehose_redshift_${var.environment}"
  database_name        = "firehose_db"
  master_username      = "admin"

  # The exported `endpoint` attribute is in `hostname:port` form, so the JDBC
  # URL needs no separate port segment. Declared once so the Firehose
  # destination and the output are guaranteed consistent.
  redshift_jdbc_url = "jdbc:redshift://${aws_redshift_cluster.main.endpoint}/${aws_redshift_cluster.main.database_name}"

  common_tags = merge(var.tags, {
    Environment = var.environment
    Purpose     = "kinesis-firehose-redshift-delivery"
    ManagedBy   = "terraform"
  })
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Customer managed KMS key: used for S3 staging (SSE-KMS) and Redshift
# cluster-at-rest encryption.
# -----------------------------------------------------------------------------

resource "aws_kms_key" "firehose_redshift" {
  description             = "Key for Firehose S3 staging encryption (SSE-KMS) and Redshift cluster encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-key" })
}

# -----------------------------------------------------------------------------
# Redshift master credentials: generated at apply time, stored in Secrets
# Manager. Never a plaintext literal or a variable default. The same
# apply-time-generated password is injected directly into the Redshift cluster
# (`master_password`) and stored in the secret; the Firehose delivery stream
# resolves credentials at delivery time via dynamic references to the secret.
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length      = 32
  special     = false
  min_upper   = 2
  min_lower   = 2
  min_numeric = 2
}

resource "aws_secretsmanager_secret" "redshift_master_credentials" {
  name                    = "${local.name_prefix}-master-credentials"
  description             = "Master credentials for the ${local.name_prefix} Redshift cluster"
  recovery_window_in_days = 0

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master_credentials" {
  secret_id = aws_secretsmanager_secret.redshift_master_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Firehose intermediate staging bucket (SSE-KMS, versioned, fully blocked
# from public access, protected from destruction).
# -----------------------------------------------------------------------------

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_s3_bucket" "staging" {
  bucket = "${local.name_prefix}-staging-${random_string.bucket_suffix.result}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-staging" })
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.firehose_redshift.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "staging" {
  bucket = aws_s3_bucket.staging.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Redshift security group.
#
# Justification (objective 4): Redshift ingress is restricted to TCP 5439 only,
# sourced from the VPC CIDR and the administrator CIDR. AWS Kinesis Data
# Firehose connects from AWS public space to the cluster's publicly accessible
# endpoint, so port 5439 must be reachable by the Firehose service; no other
# ports and no unnecessary 0.0.0.0/0 rules are permitted.
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift access on TCP 5439 only: VPC and admin CIDRs, plus AWS Kinesis Data Firehose via the cluster's public endpoint. No other ports or 0.0.0.0/0."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port 5439 from the VPC CIDR"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  ingress {
    description = "Redshift engine port 5439 from the administrator CIDR"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# -----------------------------------------------------------------------------
# Redshift subnet group and parameter group (require_ssl enforces TLS on all
# connections, including the Firehose COPY command).
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for the ${local.name_prefix} Redshift cluster"
  subnet_ids  = aws_subnet.public[*].id

  tags = local.common_tags
}

resource "aws_redshift_parameter_group" "main" {
  name        = "${local.name_prefix}-params"
  family      = "redshift-1.0"
  description = "Enforce TLS for all Redshift connections including the Firehose COPY command"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# CloudWatch log groups for Firehose S3-delivery and Redshift-delivery errors.
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose_s3_delivery" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}-s3"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "firehose_redshift_delivery" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}-redshift"
  retention_in_days = 30

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Firehose IAM role: least-privilege policy scoped to the staging bucket,
# the customer managed KMS key, the delivery error log groups, and read access
# to the single Redshift master credential secret (required so the
# `{{resolve:secretsmanager:...}}` dynamic references in the Redshift
# destination configuration resolve at delivery time).
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "${local.name_prefix}-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "firehose_delivery" {
  statement {
    sid    = "StagingBucketAccess"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
    ]

    resources = [
      aws_s3_bucket.staging.arn,
      "${aws_s3_bucket.staging.arn}/*",
    ]
  }

  statement {
    sid    = "StagingBucketKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.firehose_redshift.arn]
  }

  statement {
    sid    = "DeliveryErrorLogging"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "${aws_cloudwatch_log_group.firehose_s3_delivery.arn}:*",
      "${aws_cloudwatch_log_group.firehose_redshift_delivery.arn}:*",
    ]
  }

  statement {
    sid    = "ReadRedshiftCredentials"
    effect = "Allow"

    actions = [
      "secretsmanager:GetSecretValue",
    ]

    resources = [aws_secretsmanager_secret.redshift_master_credentials.arn]
  }
}

resource "aws_iam_policy" "firehose_delivery" {
  name        = "${local.name_prefix}-delivery-policy"
  description = "Least-privilege permissions for the Firehose delivery stream (S3 staging, KMS, CloudWatch Logs, credential secret)"
  policy      = data.aws_iam_policy_document.firehose_delivery.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "firehose_delivery" {
  role       = aws_iam_role.firehose_delivery.name
  policy_arn = aws_iam_policy.firehose_delivery.arn
}

# -----------------------------------------------------------------------------
# Redshift cluster (publicly accessible so the Firehose service can reach the
# cluster endpoint, encrypted with the customer managed KMS key, master
# password injected directly from the apply-time random_password that is also
# stored in Secrets Manager — no plaintext literal, no variable default, and
# `master_password_secret_arn` is a computed-only attribute and is never set).
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier  = "${local.name_prefix}-cluster"
  cluster_type        = "single-node"
  node_type           = "dc2.large"
  database_name       = local.database_name
  master_username     = jsondecode(aws_secretsmanager_secret_version.redshift_master_credentials.secret_string)["username"]
  master_password     = random_password.redshift_master.result

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]

  publicly_accessible = true
  encrypted           = true
  kms_key_id          = aws_kms_key.firehose_redshift.arn

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream: for the Redshift destination the
# intermediate S3 staging configuration is nested inside
# `redshift_configuration` (required by the provider schema). Staging uses
# GZIP compression, SSE-KMS with the customer managed key, and 128 MB / 300 s
# buffering (`buffering_size`/`buffering_interval`, the v5 schema names for the
# Redshift-destination nested S3 block); Redshift credentials are dynamic
# references to Secrets Manager, resolvable by the stream role's scoped
# `secretsmanager:GetSecretValue` grant. The `cluster_jdbcurl` is composed
# from the exported `endpoint` attribute (`hostname:port` form) plus the
# database name — no separate port segment, matching the provider's documented
# Redshift-destination example.
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "main" {
  name        = local.firehose_stream_name
  destination = "redshift"

  redshift_configuration {
    role_arn        = aws_iam_role.firehose_delivery.arn
    cluster_jdbcurl = local.redshift_jdbc_url

    username = "{{resolve:secretsmanager:${aws_secretsmanager_secret.redshift_master_credentials.arn}:SecretString:username}}"
    password = "{{resolve:secretsmanager:${aws_secretsmanager_secret.redshift_master_credentials.arn}:SecretString:password}}"

    data_table_name = var.destination_table_name
    copy_options    = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_redshift_delivery.name
      log_stream_name = "RedshiftDelivery"
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery.arn
      bucket_arn         = aws_s3_bucket.staging.arn
      prefix             = "staging/"
      buffering_size     = 128
      buffering_interval = 300

      compression_format = "GZIP"
      kms_key_arn        = aws_kms_key.firehose_redshift.arn

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_s3_delivery.name
        log_stream_name = "S3Delivery"
      }
    }
  }

  depends_on = [aws_secretsmanager_secret_version.redshift_master_credentials]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs (metadata only — never secret values).
# -----------------------------------------------------------------------------

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.main.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.main.arn
}

output "staging_bucket_name" {
  description = "Name of the intermediate S3 staging bucket."
  value       = aws_s3_bucket.staging.id
}

output "staging_bucket_arn" {
  description = "ARN of the intermediate S3 staging bucket."
  value       = aws_s3_bucket.staging.arn
}

output "redshift_cluster_endpoint" {
  description = "Public endpoint of the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_jdbc_url" {
  description = "JDBC URL of the Redshift cluster used by the Firehose COPY command."
  value       = local.redshift_jdbc_url
}

output "redshift_cluster_port" {
  description = "Port the Redshift cluster listens on."
  value       = aws_redshift_cluster.main.port
}

output "redshift_database_name" {
  description = "Name of the Redshift database."
  value       = aws_redshift_cluster.main.database_name
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master credentials."
  value       = aws_secretsmanager_secret.redshift_master_credentials.arn
}

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  delivery_stream_name = "firehose_delivery_stream"
  log_group_name       = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  es_domain_name       = "firehose-es-${var.environment}"
  es_domain_arn        = "arn:aws:es:us-east-1:${data.aws_caller_identity.current.account_id}:domain/${local.es_domain_name}"
  backup_bucket_name   = "firehose-backup-${var.environment}-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Component   = "kinesis-firehose-elasticsearch"
  }
}

###############################################################################
# S3 Backup Bucket (failed document backup destination for Firehose)
###############################################################################

resource "aws_s3_bucket" "firehose_backup" {
  bucket = local.backup_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket                  = aws_s3_bucket.firehose_backup.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# KMS Key (Elasticsearch encryption at rest)
###############################################################################

resource "aws_kms_key" "elasticsearch" {
  description             = "KMS key for Elasticsearch domain encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM Role for Firehose Delivery
###############################################################################

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    sid     = "AllowFirehoseAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "firehose-delivery-role-${var.environment}"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "firehose_delivery_permissions" {
  statement {
    sid    = "S3BackupBucketAccess"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:GetObject",
      "s3:PutObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.firehose_backup.arn,
      "${aws_s3_bucket.firehose_backup.arn}/*",
    ]
  }

  statement {
    sid    = "ElasticsearchDomainAccess"
    effect = "Allow"

    actions = [
      "es:ESHttpGet",
      "es:ESHttpPost",
      "es:ESHttpPut",
    ]

    resources = [
      aws_elasticsearch_domain.search.arn,
      "${aws_elasticsearch_domain.search.arn}/*",
    ]
  }

  statement {
    sid       = "FirehoseCloudWatchLogs"
    effect    = "Allow"
    actions   = ["logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.firehose.arn}:*"]
  }
}

resource "aws_iam_role_policy" "firehose_delivery" {
  name   = "firehose-delivery-policy"
  role   = aws_iam_role.firehose_delivery.name
  policy = data.aws_iam_policy_document.firehose_delivery_permissions.json
}

###############################################################################
# CloudWatch Logs for Firehose Delivery Errors
###############################################################################

resource "aws_cloudwatch_log_group" "firehose" {
  name              = local.log_group_name
  retention_in_days = 30
  tags              = local.common_tags
}

resource "aws_cloudwatch_log_stream" "elasticsearch_delivery" {
  name           = "elasticsearch_delivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

resource "aws_cloudwatch_log_stream" "s3_delivery" {
  name           = "s3_delivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

###############################################################################
# Elasticsearch Domain
###############################################################################

data "aws_iam_policy_document" "elasticsearch_domain_access" {
  statement {
    sid    = "AllowFirehoseDeliveryRole"
    effect = "Allow"

    actions = [
      "es:ESHttpGet",
      "es:ESHttpPost",
      "es:ESHttpPut",
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose_delivery.arn]
    }

    resources = ["${local.es_domain_arn}/*"]
  }
}

resource "aws_elasticsearch_domain" "search" {
  domain_name           = local.es_domain_name
  elasticsearch_version = "6.8"

  cluster_config {
    instance_type  = "t3.small.elasticsearch"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.elasticsearch.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = data.aws_iam_policy_document.elasticsearch_domain_access.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Kinesis Firehose Delivery Stream (Elasticsearch Destination)
###############################################################################

resource "aws_kinesis_firehose_delivery_stream" "to_elasticsearch" {
  name        = local.delivery_stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    role_arn              = aws_iam_role.firehose_delivery.arn
    cluster_endpoint      = "https://${aws_elasticsearch_domain.search.endpoint}"
    index_name            = "firehose-logs"
    type_name             = "_doc"
    index_rotation_period = "OneMonth"
    buffering_size        = 5
    buffering_interval    = 60
    retry_duration        = 300
    s3_backup_mode        = "FailedDocumentsOnly"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.elasticsearch_delivery.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_delivery.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      prefix             = "failed-documents/"
      buffering_size     = 5
      buffering_interval = 300
      compression_format = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose.name
        log_stream_name = aws_cloudwatch_log_stream.s3_delivery.name
      }
    }
  }

  depends_on = [
    aws_iam_role_policy.firehose_delivery,
    aws_elasticsearch_domain.search,
    aws_s3_bucket_public_access_block.firehose_backup,
    aws_s3_bucket_server_side_encryption_configuration.firehose_backup,
    aws_s3_bucket_versioning.firehose_backup,
  ]
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a consistent tag across resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  backup_bucket_name = "firehose-backup-${data.aws_region.current.name}-${data.aws_caller_identity.current.account_id}"

  tags = {
    Environment = var.environment
  }
}

# IAM role assumed by Kinesis Data Firehose to deliver to OpenSearch / S3 / CloudWatch Logs
resource "aws_iam_role" "firehose_opensearch" {
  name = "firehose-opensearch-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = local.tags
}

# S3 backup bucket for failed documents
resource "aws_s3_bucket" "firehose_backup" {
  bucket = local.backup_bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# CloudWatch log group for Firehose delivery errors
resource "aws_cloudwatch_log_group" "firehose_errors" {
  name              = "/aws/kinesisfirehose/to-opensearch"
  retention_in_days = 14

  tags = local.tags
}

# Firehose requires a pre-existing log stream when CloudWatch logging is enabled
resource "aws_cloudwatch_log_stream" "firehose_errors" {
  name           = "firehose-delivery-errors"
  log_group_name = aws_cloudwatch_log_group.firehose_errors.name
}

# OpenSearch domain
resource "aws_opensearch_domain" "main" {
  domain_name    = "firehose-logs-domain"
  engine_version = "OpenSearch_2.13"

  cluster_config {
    instance_type  = "t3.small.search"
    instance_count = 1
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp3"
    volume_size = 10
  }

  encrypt_at_rest {
    enabled = true
  }

  node_to_node_encryption {
    enabled = true
  }

  snapshot_options {
    automated_snapshot_start_hour = 23
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Resource-based domain policy: only the Firehose role may access the domain
resource "aws_opensearch_domain_policy" "firehose_access" {
  domain_name = aws_opensearch_domain.main.domain_name

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { AWS = aws_iam_role.firehose_opensearch.arn }
        Action = [
          "es:ESHttpGet",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpPatch",
          "es:ESHttpDelete"
        ]
        Resource = "${aws_opensearch_domain.main.arn}/*"
      }
    ]
  })
}

# Least-privilege inline policy for the Firehose role
resource "aws_iam_role_policy" "firehose_opensearch_access" {
  name = "firehose-opensearch-access"
  role = aws_iam_role.firehose_opensearch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "OpenSearchDomainAccess"
        Effect = "Allow"
        Action = [
          "es:ESHttpGet",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpPatch",
          "es:ESHttpDelete"
        ]
        Resource = [
          aws_opensearch_domain.main.arn
        ]
      },
      {
        Sid    = "S3BackupAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Sid    = "FirehoseErrorLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.firehose_errors.arn}:*",
          aws_cloudwatch_log_stream.firehose_errors.arn
        ]
      }
    ]
  })
}

# Kinesis Data Firehose delivery stream (DirectPut -> OpenSearch)
resource "aws_kinesis_firehose_delivery_stream" "to_opensearch" {
  name        = "to-opensearch"
  destination = "opensearch"

  opensearch_configuration {
    domain_arn = aws_opensearch_domain.main.arn
    role_arn   = aws_iam_role.firehose_opensearch.arn
    index_name = "firehose-logs"

    s3_backup_mode = "FailedDocumentsOnly"

    buffering_size     = 5
    buffering_interval = 60

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_errors.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_errors.name
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose_opensearch.arn
      bucket_arn         = aws_s3_bucket.firehose_backup.arn
      buffering_size     = 5
      buffering_interval = 60
      compression_format = "GZIP"
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_opensearch_domain_policy.firehose_access,
    aws_iam_role_policy.firehose_opensearch_access
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values only)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project/environment name used for resource naming and tags."
  type        = string
  default     = "acme-observability"
}

variable "splunk_hec_endpoint_url" {
  description = "HTTPS URL of the Splunk HEC endpoint that receives Firehose events."
  type        = string
  default     = "https://http-inputs-observability.splunkcloud.com:8088"

  validation {
    condition     = can(regex("^https://", var.splunk_hec_endpoint_url))
    error_message = "The Splunk HEC endpoint URL must use HTTPS."
  }
}

# -----------------------------------------------------------------------------
# Locals: naming, tag defaults, and the shared least-privilege policy document
# -----------------------------------------------------------------------------

locals {
  name_prefix          = replace(lower(var.project_name), "/[^a-z0-9-]/", "-")
  delivery_stream_name = "${local.name_prefix}-splunk-delivery"
  backup_bucket_name   = "${local.name_prefix}-splunk-failed-events"

  default_tags = {
    Project     = var.project_name
    Environment = var.project_name
    ManagedBy   = "Terraform"
  }

  firehose_permissions_policy = {
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3FailedEventObjectActions"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:GetObject",
        ]
        Resource = "${aws_s3_bucket.splunk_backup.arn}/*"
      },
      {
        Sid    = "S3FailedEventBucketActions"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
        ]
        Resource = aws_s3_bucket.splunk_backup.arn
      },
      {
        Sid    = "FirehoseCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose.arn,
          "${aws_cloudwatch_log_group.firehose.arn}:${aws_cloudwatch_log_stream.splunk_delivery.name}",
        ]
      },
      {
        Sid      = "FirehoseSplunkHecSecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue"]
        Resource = aws_secretsmanager_secret.splunk_hec_token.arn
      },
      {
        Sid    = "FirehoseStreamKmsEncryption"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = aws_kms_key.firehose.arn
      },
    ]
  }
}

# -----------------------------------------------------------------------------
# KMS key for delivery stream at-rest encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "firehose" {
  description         = "Customer managed key encrypting the ${local.delivery_stream_name} Firehose delivery stream at rest."
  enable_key_rotation = true

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-firehose-cmk" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "firehose" {
  name          = "alias/${local.name_prefix}-firehose-cmk"
  target_key_id = aws_kms_key.firehose.key_id
}

# -----------------------------------------------------------------------------
# S3 backup bucket for failed events
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "splunk_backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.default_tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "splunk_backup" {
  bucket = aws_s3_bucket.splunk_backup.id

  rule {
    id     = "cleanup-failed-event-backups"
    status = "Enabled"

    filter {
      prefix = "failed-events/"
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

# -----------------------------------------------------------------------------
# CloudWatch logging for Firehose delivery diagnostics
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  retention_in_days = 14

  tags = merge(local.default_tags, { Name = "/aws/kinesisfirehose/${local.delivery_stream_name}" })
}

resource "aws_cloudwatch_log_stream" "splunk_delivery" {
  name           = "SplunkDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

# -----------------------------------------------------------------------------
# Secrets Manager: Splunk HEC token (retrieved by Firehose at runtime)
#
# The secret value is machine-generated at apply time (random_password) and is
# referenced solely by its Terraform address — it never appears as a plaintext
# literal in configuration, defaults, or locals. Because Firehose reads the
# secret's CURRENT value at runtime via secrets_manager_configuration,
# operators must replace this deployment-generated placeholder with the real
# Splunk-issued HEC token out-of-band in AWS Secrets Manager after deployment;
# rotating the value requires no Terraform change and no redeploy of the stream.
# -----------------------------------------------------------------------------

resource "random_password" "hec_token_seed" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "splunk_hec_token" {
  name        = "${local.name_prefix}-splunk-hec-token"
  description = "Splunk HEC token used by the Firehose Splunk destination. Firehose reads this secret's current value at runtime. The initial value is a deployment-generated placeholder (random_password.hec_token_seed); operators must replace it with the Splunk-issued HEC token out-of-band in AWS Secrets Manager. Rotation requires no Terraform change and no redeploy of the delivery stream."

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-splunk-hec-token" })
}

resource "aws_secretsmanager_secret_version" "splunk_hec_token" {
  secret_id     = aws_secretsmanager_secret.splunk_hec_token.id
  secret_string = random_password.hec_token_seed.result
}

# -----------------------------------------------------------------------------
# IAM role for Firehose
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose" {
  name        = "${local.name_prefix}-firehose-role"
  description = "Assume role for the Kinesis Data Firehose Splunk delivery stream."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseServiceAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.default_tags, { Name = "${local.name_prefix}-firehose-role" })
}

resource "aws_iam_role_policy" "firehose_inline_policy" {
  name   = "${local.name_prefix}-firehose-inline"
  role   = aws_iam_role.firehose.name
  policy = jsonencode(local.firehose_permissions_policy)
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "${local.name_prefix}-firehose-policy"
  description = "Least-privilege permissions for the Firehose Splunk delivery stream."
  policy      = jsonencode(local.firehose_permissions_policy)
}

resource "aws_iam_role_policy_attachment" "firehose_policy_attachment" {
  role       = aws_iam_role.firehose.name
  policy_arn = aws_iam_policy.firehose_policy.arn
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream with Splunk destination
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "to_splunk" {
  name        = local.delivery_stream_name
  destination = "splunk"

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.firehose.arn
  }

  splunk_configuration {
    hec_endpoint               = var.splunk_hec_endpoint_url
    hec_endpoint_type          = "Raw"
    hec_acknowledgment_timeout = 300
    retry_duration             = 300
    s3_backup_mode             = "FailedEventsOnly"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.splunk_delivery.name
    }

    secrets_manager_configuration {
      enabled    = true
      secret_arn = aws_secretsmanager_secret.splunk_hec_token.arn
      role_arn   = aws_iam_role.firehose.arn
    }

    s3_configuration {
      role_arn           = aws_iam_role.firehose.arn
      bucket_arn         = aws_s3_bucket.splunk_backup.arn
      prefix             = "failed-events/"
      buffering_size     = 10
      buffering_interval = 300
      compression_format = "GZIP"
    }
  }

  depends_on = [
    aws_secretsmanager_secret_version.splunk_hec_token,
    aws_iam_role_policy.firehose_inline_policy,
    aws_iam_role_policy_attachment.firehose_policy_attachment,
  ]

  tags = merge(local.default_tags, { Name = local.delivery_stream_name })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.to_splunk.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.to_splunk.arn
}

output "backup_bucket_name" {
  description = "Name of the S3 bucket used for failed-event backups."
  value       = aws_s3_bucket.splunk_backup.id
}

output "firehose_iam_role_arn" {
  description = "ARN of the IAM role assumed by the Firehose delivery stream."
  value       = aws_iam_role.firehose.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Local, well-known lookup of the current account ID. Used only for the Firehose
# trust-policy external ID and to build a globally-unique S3 bucket name.
data "aws_caller_identity" "current" {}

locals {
  collection_name      = "firehose-aoss"
  index_name           = "firehose-events"
  delivery_stream_name = "firehose-aoss-delivery-stream"
  backup_bucket_name   = "firehose-aoss-backup-${data.aws_caller_identity.current.account_id}"
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources (e.g. environment, owner)."
  type        = map(string)

  default = {
    Environment = "dev"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }

  validation {
    condition     = length(var.common_tags) > 0
    error_message = "common_tags must contain at least one tag."
  }
}

# -----------------------------------------------------------------------------
# KMS: dedicated customer-managed key for the collection and backup bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  description             = "Dedicated key for the Firehose OpenSearch Serverless collection and S3 backup bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = var.common_tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/firehose-aoss"
  target_key_id = aws_kms_key.this.key_id
}

# -----------------------------------------------------------------------------
# OpenSearch Serverless: security policies (encryption + network), collection, data policy
# -----------------------------------------------------------------------------

resource "aws_opensearchserverless_security_policy" "encryption" {
  name = "firehose-aoss-encryption"
  type = "encryption"

  policy = jsonencode({
    Rules = [
      {
        ResourceType = "collection"
        Resource     = ["collection/${local.collection_name}"]
      }
    ]
    AWSOwnedKey = false
    KmsARN      = aws_kms_key.this.arn
  })
}

# Network policy for OpenSearch Serverless is managed through the
# aws_opensearchserverless_security_policy resource with type = "network".
# It is a JSON array of rule sets (unlike the encryption policy, which is a
# single JSON object) — do not merge the two policy documents into one resource.
resource "aws_opensearchserverless_security_policy" "network" {
  name = "firehose-aoss-network"
  type = "network"

  policy = jsonencode([
    {
      Description = "Public access to the collection endpoint; authorization is handled via IAM and the data access policy."
      Rules = [
        {
          ResourceType = "collection"
          Resource     = ["collection/${local.collection_name}"]
        }
      ]
      AllowFromPublic = true
    }
  ])
}

resource "aws_opensearchserverless_collection" "this" {
  name        = local.collection_name
  type        = "SEARCH"
  description = "OpenSearch Serverless collection fed by Kinesis Data Firehose."

  tags = var.common_tags

  depends_on = [
    aws_opensearchserverless_security_policy.encryption,
    aws_opensearchserverless_security_policy.network,
  ]
}

resource "aws_opensearchserverless_access_policy" "data" {
  name = "firehose-aoss-data-access"
  type = "data"

  policy = jsonencode([
    {
      Rules = [
        {
          ResourceType = "index"
          Resource     = ["index/${local.collection_name}/*"]
          Permission = [
            "aoss:CreateIndex",
            "aoss:DescribeIndex",
            "aoss:UpdateIndex",
            "aoss:WriteDocument"
          ]
        },
        {
          ResourceType = "collection"
          Resource     = ["collection/${local.collection_name}"]
          Permission = [
            "aoss:CreateCollectionItems",
            "aoss:DescribeCollectionItems",
            "aoss:UpdateCollectionItems"
          ]
        }
      ]
      Principal   = [aws_iam_role.firehose.arn]
      Description = "Grants the Firehose delivery role access to auto-create indexes and ingest documents."
    }
  ])
}

# -----------------------------------------------------------------------------
# IAM: Firehose delivery role with least-privilege inline policy
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose" {
  name = "firehose-aoss-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowFirehoseToAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy" "firehose" {
  name = "firehose-aoss-delivery-access"
  role = aws_iam_role.firehose.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "OpenSearchServerlessAPIAccess"
        Effect   = "Allow"
        Action   = ["aoss:APIAccessAll"]
        Resource = [aws_opensearchserverless_collection.this.arn]
      },
      {
        Sid    = "S3BackupBucket"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = [aws_s3_bucket.backup.arn]
      },
      {
        Sid    = "S3BackupObjects"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:GetObject"
        ]
        Resource = ["${aws_s3_bucket.backup.arn}/*"]
      },
      {
        Sid      = "KmsKeyUse"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.this.arn]
      },
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose.arn,
          "${aws_cloudwatch_log_group.firehose.arn}:*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3 backup bucket for failed/undeliverable documents
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "backup" {
  bucket = local.backup_bucket_name

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# CloudWatch Logs for Firehose delivery error logging
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose" {
  name              = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  retention_in_days = 30

  tags = var.common_tags
}

resource "aws_cloudwatch_log_stream" "firehose" {
  name           = "FirehoseDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose.name
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream -> OpenSearch Serverless
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "this" {
  name        = local.delivery_stream_name
  destination = "opensearch"

  opensearch_configuration {
    role_arn              = aws_iam_role.firehose.arn
    cluster_endpoint      = aws_opensearchserverless_collection.this.collection_endpoint
    index_name            = local.index_name
    index_rotation_period = "NoRotation"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 60
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = aws_cloudwatch_log_stream.firehose.name
    }

    # S3 backup configuration for failed/undeliverable documents must be nested
    # inside the destination block for the "opensearch" destination.
    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.backup.arn
      prefix              = "failed-documents/"
      error_output_prefix = "failed-documents-errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"
      kms_key_arn         = aws_kms_key.this.arn
    }
  }

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_opensearchserverless_access_policy.data,
    aws_iam_role_policy.firehose,
    aws_s3_bucket.backup,
    aws_s3_bucket_ownership_controls.backup,
    aws_s3_bucket_public_access_block.backup,
    aws_s3_bucket_server_side_encryption_configuration.backup,
    aws_s3_bucket_versioning.backup,
    aws_cloudwatch_log_group.firehose,
    aws_cloudwatch_log_stream.firehose,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "opensearch_serverless_collection_endpoint" {
  description = "OpenSearch Serverless collection endpoint used by the Firehose delivery stream."
  value       = aws_opensearchserverless_collection.this.collection_endpoint
}

output "delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.this.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.this.arn
}

output "backup_bucket_name" {
  description = "Name of the S3 backup bucket for failed documents."
  value       = aws_s3_bucket.backup.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "project_name" {
  description = "Prefix used for all resource names. Lowercase letters, numbers and hyphens only."
  type        = string
  default     = "firehose-opensearch"
}

variable "environment" {
  description = "Value applied to the Environment tag on every resource."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated Firehose / OpenSearch VPC."
  type        = string
  default     = "10.0.0.0/16"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = lower(replace(var.project_name, "_", "-"))

  domain_name        = substr("${local.name_prefix}-domain", 0, 28)
  index_name         = "${local.name_prefix}-logs"
  stream_name        = "${local.name_prefix}-to-opensearch"
  log_group_name     = "/aws/kinesisfirehose/${local.name_prefix}-elasticsearch"
  backup_bucket_name = "${local.name_prefix}-firehose-backup-${data.aws_caller_identity.current.account_id}"

  # Mirrors aws_opensearch_domain.main.arn. The domain resource cannot reference
  # its own ARN inside access_policies, so it is composed here from static
  # provider metadata and the domain name declared above.
  domain_arn = "arn:${data.aws_partition.current.partition}:es:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:domain/${local.domain_name}"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider / account metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Networking: VPC, subnets, IGW, NAT gateway, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-${count.index + 1}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, { Name = "${local.name_prefix}-nat" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
# Rules are declared as separate aws_security_group_rule resources so the
# Firehose and Elasticsearch groups can reference each other without creating
# a Terraform dependency cycle. No 0.0.0.0/0 ingress exists on any port.
###############################################################################

resource "aws_security_group" "elasticsearch" {
  name        = "${local.name_prefix}-opensearch-sg"
  description = "OpenSearch domain endpoints; accepts HTTPS only from the Firehose delivery ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-opensearch-sg" })
}

resource "aws_security_group" "firehose" {
  name        = "${local.name_prefix}-firehose-sg"
  description = "Kinesis Data Firehose VPC delivery ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-sg" })
}

resource "aws_security_group_rule" "opensearch_ingress_from_firehose" {
  description              = "TCP 443 from the Firehose VPC delivery ENIs only"
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.elasticsearch.id
  source_security_group_id = aws_security_group.firehose.id
}

resource "aws_security_group_rule" "opensearch_egress_https" {
  description       = "TCP 443 egress for domain service traffic (e.g. snapshots) via the NAT gateway"
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  security_group_id = aws_security_group.elasticsearch.id
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "firehose_egress_to_opensearch" {
  description              = "TCP 443 to the OpenSearch domain endpoints"
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.firehose.id
  source_security_group_id = aws_security_group.elasticsearch.id
}

resource "aws_security_group_rule" "firehose_egress_https" {
  description       = "TCP 443 outbound to S3 and CloudWatch via the NAT gateway"
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "firehose_egress_dns_tcp" {
  description       = "TCP 53 DNS resolution against the VPC resolver"
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

resource "aws_security_group_rule" "firehose_egress_dns_udp" {
  description       = "UDP 53 DNS resolution against the VPC resolver"
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  security_group_id = aws_security_group.firehose.id
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

###############################################################################
# IAM: OpenSearch service-linked role + Firehose execution role
###############################################################################

resource "aws_iam_service_linked_role" "opensearch" {
  aws_service_name = "opensearchservice.amazonaws.com"
}

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    sid     = "AllowFirehoseToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose" {
  name               = "${local.name_prefix}-firehose-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-role" })
}

data "aws_iam_policy_document" "firehose_permissions" {
  statement {
    sid    = "ElasticsearchDelivery"
    effect = "Allow"
    actions = ["es:ESHttp*"]

    resources = [
      aws_opensearch_domain.main.arn,
      "${aws_opensearch_domain.main.arn}/*",
    ]
  }

  statement {
    sid    = "VpcDeliveryNetworkInterfaceManagement"
    effect = "Allow"
    actions = [
      "ec2:CreateNetworkInterface",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DeleteNetworkInterface",
      "ec2:DescribeSubnets",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "DeliveryLogging"
    effect = "Allow"
    actions = [
      "logs:PutLogEvents",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
    ]
    resources = ["${aws_cloudwatch_log_group.firehose.arn}:*"]
  }

  statement {
    sid    = "BackupBucketListAndLocate"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]
    resources = [aws_s3_bucket.backup.arn]
  }

  statement {
    sid    = "BackupBucketObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]
    resources = ["${aws_s3_bucket.backup.arn}/*"]
  }
}

resource "aws_iam_role_policy" "firehose" {
  name   = "${local.name_prefix}-firehose-policy"
  role   = aws_iam_role.firehose.name
  policy = data.aws_iam_policy_document.firehose_permissions.json
}

###############################################################################
# KMS customer managed key (OpenSearch encryption at rest + S3 SSE-KMS)
###############################################################################

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowOpenSearchServiceLinkedRoleEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_service_linked_role.opensearch.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["ec2.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowOpenSearchServiceEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["opensearchservice.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["opensearch.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowFirehoseRoleS3ServerSideEncryption"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "main" {
  description             = "CMK for OpenSearch encryption at rest and Firehose S3 backup SSE-KMS"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms_key.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "main" {
  name          = "alias/${local.name_prefix}-kms"
  target_key_id = aws_kms_key.main.key_id
}

###############################################################################
# OpenSearch domain (inside the VPC, encrypted, least-privilege access policy)
###############################################################################

data "aws_iam_policy_document" "opensearch_access" {
  statement {
    sid     = "AllowFirehoseDeliveryRole"
    effect  = "Allow"
    actions = ["es:ESHttp*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.firehose.arn]
    }

    resources = [
      local.domain_arn,
      "${local.domain_arn}/*",
    ]
  }
}

resource "aws_opensearch_domain" "main" {
  domain_name    = local.domain_name
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type          = "t3.small.search"
    instance_count         = 2
    zone_awareness_enabled = true

    zone_awareness_config {
      availability_zone_count = 2
    }
  }

  vpc_options {
    subnet_ids         = [aws_subnet.private[0].id, aws_subnet.private[1].id]
    security_group_ids = [aws_security_group.elasticsearch.id]
  }

  ebs_options {
    ebs_enabled = true
    volume_type = "gp3"
    volume_size = 20
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.main.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  access_policies = data.aws_iam_policy_document.opensearch_access.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-opensearch" })

  depends_on = [
    aws_iam_service_linked_role.opensearch,
    aws_security_group_rule.opensearch_ingress_from_firehose,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 backup bucket for failed documents + Firehose delivery log group
###############################################################################

resource "aws_s3_bucket" "backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudwatch_log_group" "firehose" {
  name              = local.log_group_name
  retention_in_days = 365

  tags = merge(local.tags, { Name = "${local.name_prefix}-firehose-delivery-logs" })
}

###############################################################################
# Kinesis Data Firehose delivery stream (VPC delivery to OpenSearch)
# Per the provider schema, both s3_configuration and vpc_config are nested
# children of elasticsearch_configuration for the "elasticsearch" destination.
###############################################################################

resource "aws_kinesis_firehose_delivery_stream" "to_opensearch" {
  name        = local.stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    role_arn              = aws_iam_role.firehose.arn
    domain_arn            = aws_opensearch_domain.main.arn
    index_name            = local.index_name
    index_rotation_period = "OneDay"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 300
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose.name
      log_stream_name = "ElasticsearchDelivery"
    }

    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.backup.arn
      prefix              = "backup/failed-documents/"
      error_output_prefix = "backup/errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"
      kms_key_arn         = aws_kms_key.main.arn
    }

    vpc_config {
      vpc_id             = aws_vpc.main.id
      subnet_ids         = aws_subnet.private[*].id
      security_group_ids = [aws_security_group.firehose.id]
      role_arn           = aws_iam_role.firehose.arn
    }
  }

  tags = merge(local.tags, { Name = local.stream_name })

  depends_on = [
    aws_iam_role_policy.firehose,
    aws_security_group_rule.opensearch_ingress_from_firehose,
    aws_security_group_rule.firehose_egress_to_opensearch,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Environment = "production"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

variable "http_endpoint_url" {
  description = "URL of the HTTP endpoint destination (e.g., New Relic Firehose ingestion endpoint)."
  type        = string
  default     = "https://aws-api.newrelic.com/firehose/v1"
}

variable "http_endpoint_name" {
  description = "Human-readable name of the HTTP endpoint destination provider."
  type        = string
  default     = "New Relic"
}

# ------------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  firehose_stream_name = "http-endpoint-newrelic-delivery-stream"
}

# ------------------------------------------------------------------------------
# S3 backup/failed-records destination bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "firehose_backup" {
  bucket = "firehose-http-endpoint-backup-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_backup" {
  bucket = aws_s3_bucket.firehose_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Logs for delivery success/error logging
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "firehose_http_endpoint" {
  name              = "/aws/kinesisfirehose/${local.firehose_stream_name}"
  retention_in_days = 14

  tags = var.tags
}

resource "aws_cloudwatch_log_stream" "http_endpoint_delivery" {
  name           = "HttpEndpointDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose_http_endpoint.name
}

resource "aws_cloudwatch_log_stream" "s3_backup_delivery" {
  name           = "S3BackupDelivery"
  log_group_name = aws_cloudwatch_log_group.firehose_http_endpoint.name
}

# ------------------------------------------------------------------------------
# IAM role for the delivery stream
# ------------------------------------------------------------------------------

resource "aws_iam_role" "firehose_delivery_role" {
  name        = "firehose-http-endpoint-delivery-role"
  description = "IAM role assumed by Kinesis Data Firehose to deliver data to the HTTP endpoint and the S3 backup bucket."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

# Least-privilege inline policy granting the Firehose delivery stream access to
# the S3 backup bucket (failed records) and the Firehose CloudWatch log group only.
resource "aws_iam_role_policy" "firehose_delivery_policy" {
  name = "firehose-http-endpoint-delivery-policy"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FirehoseBackupBucketAccess"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.firehose_backup.arn,
          "${aws_s3_bucket.firehose_backup.arn}/*"
        ]
      },
      {
        Sid    = "FirehoseCloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogStream"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose_http_endpoint.arn,
          "${aws_cloudwatch_log_group.firehose_http_endpoint.arn}:log-stream:*"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# HTTP endpoint access key (e.g., New Relic license key)
#
# ROTATION HAND-OFF: The value stored below is a deployment-bootstrap value
# generated by Terraform (random_password) so that automated, unattended
# applies require zero root-module inputs. The operator MUST rotate the stored
# secret out-of-band (Secrets Manager console/CLI or CI/CD secret injection)
# to the real New Relic license key after deployment. Never rotate it by
# committing the value to this repository or reintroducing it as a variable
# default / required input.
# ------------------------------------------------------------------------------

resource "random_password" "http_endpoint_access_key" {
  length  = 40
  special = false

  upper   = true
  lower   = true
  numeric = true
}

resource "aws_secretsmanager_secret" "http_endpoint_access_key" {
  name        = "firehose/http-endpoint-access-key"
  description = "Access key used by the Firehose HTTP endpoint destination to authenticate with the endpoint provider. Currently holds a Terraform-generated bootstrap value; the operator must rotate this to the real provider license key out-of-band after deployment."

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "http_endpoint_access_key" {
  secret_id     = aws_secretsmanager_secret.http_endpoint_access_key.id
  secret_string = random_password.http_endpoint_access_key.result
}

# ------------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (DirectPut -> HTTP endpoint)
# ------------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "http_endpoint_stream" {
  name        = local.firehose_stream_name
  destination = "http_endpoint"

  server_side_encryption {
    enabled  = true
    key_type = "AWS_OWNED_CMK"
  }

  http_endpoint_configuration {
    url        = var.http_endpoint_url
    name       = var.http_endpoint_name
    access_key = aws_secretsmanager_secret_version.http_endpoint_access_key.secret_string
    role_arn   = aws_iam_role.firehose_delivery_role.arn

    # Near-real-time buffering hints: 1 MiB or 60 seconds.
    buffering_size     = 1
    buffering_interval = 60

    # Retry failed HTTP endpoint deliveries for up to 300 seconds.
    retry_duration = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_http_endpoint.name
      log_stream_name = aws_cloudwatch_log_stream.http_endpoint_delivery.name
    }

    request_configuration {
      content_encoding = "NONE"
    }

    # Controls which records are routed to the s3_configuration backup
    # destination below; must remain a direct attribute of this block.
    s3_backup_mode = "FailedDataOnly"

    s3_configuration {
      role_arn   = aws_iam_role.firehose_delivery_role.arn
      bucket_arn = aws_s3_bucket.firehose_backup.arn
      prefix     = "failed-records/"

      buffering_size     = 1
      buffering_interval = 60
      compression_format = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_http_endpoint.name
        log_stream_name = aws_cloudwatch_log_stream.s3_backup_delivery.name
      }
    }
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "firehose_delivery_stream_arn" {
  description = "ARN of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.http_endpoint_stream.arn
}

output "firehose_delivery_stream_name" {
  description = "Name of the Kinesis Data Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.http_endpoint_stream.name
}

output "firehose_backup_bucket_arn" {
  description = "ARN of the S3 backup bucket receiving failed records."
  value       = aws_s3_bucket.firehose_backup.arn
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables - only user-controlled values, with defaults for unattended apply
###############################################################################

variable "environment" {
  description = "Environment name used to prefix all resource names."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged onto every tagged resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources - static, well-known lookups only
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix          = "${var.environment}-firehose-os"
  opensearch_index     = "logs"
  backup_bucket_name   = "${local.name_prefix}-backup-${data.aws_caller_identity.current.account_id}"
  delivery_stream_name = "${local.name_prefix}-stream"
  log_group_name       = "/aws/kinesisfirehose/${local.name_prefix}"

  common_tags = merge(
    {
      Component   = "firehose-os"
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "firehose_os_private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a", Tier = "private" })
}

resource "aws_subnet" "firehose_os_private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b", Tier = "private" })
}

###############################################################################
# Security groups - the two groups reference each other, so the cross-referencing
# rules are declared as standalone rule resources to avoid a dependency cycle.
###############################################################################

resource "aws_security_group" "opensearch" {
  name        = "${local.name_prefix}-opensearch-sg"
  description = "OpenSearch domain nodes; accepts HTTPS only from Firehose ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-opensearch-sg" })
}

resource "aws_security_group" "firehose" {
  name        = "${local.name_prefix}-firehose-sg"
  description = "Firehose VPC ENIs; no ingress, egress limited to HTTPS toward OpenSearch"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-firehose-sg" })
}

# Inbound TCP 443 to OpenSearch is allowed ONLY from the Firehose security group
# (security-group-to-security-group reference; no CIDR ingress anywhere).
resource "aws_vpc_security_group_ingress_rule" "opensearch_from_firehose" {
  security_group_id            = aws_security_group.opensearch.id
  referenced_security_group_id = aws_security_group.firehose.id
  description                  = "HTTPS from Firehose delivery ENIs"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# Firehose ENIs may only send TCP 443 to the OpenSearch security group.
resource "aws_vpc_security_group_egress_rule" "firehose_to_opensearch" {
  security_group_id            = aws_security_group.firehose.id
  referenced_security_group_id = aws_security_group.opensearch.id
  description                  = "HTTPS to OpenSearch domain nodes"
  ip_protocol                  = "tcp"
  from_port                    = 443
  to_port                      = 443
}

# OpenSearch nodes require unrestricted egress for inter-node and AWS service traffic.
resource "aws_vpc_security_group_egress_rule" "opensearch_all" {
  security_group_id = aws_security_group.opensearch.id
  cidr_ipv4         = "0.0.0.0/0"
  description       = "Allow all egress from OpenSearch nodes"
  ip_protocol       = "-1"
  from_port         = 0
  to_port           = 0
}

###############################################################################
# KMS key for OpenSearch encryption at rest
###############################################################################

resource "aws_kms_key" "firehose_os" {
  description             = "Encryption at rest for the ${local.name_prefix} OpenSearch domain"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-opensearch-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "firehose_os" {
  name          = "alias/${local.name_prefix}-opensearch"
  target_key_id = aws_kms_key.firehose_os.key_id
}

###############################################################################
# S3 backup bucket for Firehose backup / failed documents
###############################################################################

resource "aws_s3_bucket" "firehose_os_backup" {
  bucket = local.backup_bucket_name

  tags = merge(local.common_tags, { Name = local.backup_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_os_backup" {
  bucket = aws_s3_bucket.firehose_os_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# CloudWatch log group for Firehose delivery error logging
###############################################################################

resource "aws_cloudwatch_log_group" "firehose_os_delivery" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = local.log_group_name })
}

###############################################################################
# IAM role assumed by Firehose, with least-privilege inline policies
###############################################################################

data "aws_iam_policy_document" "firehose_os_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose" {
  name               = "${local.name_prefix}-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_os_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-delivery-role" })
}

resource "aws_iam_role_policy" "firehose_os_opensearch_access" {
  name = "opensearch-http-access"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["es:ESHttp*"]
        Resource = [
          aws_opensearch_domain.firehose_os.arn,
          "${aws_opensearch_domain.firehose_os.arn}/*",
        ]
      },
    ]
  })
}

# These EC2 actions do not support resource-level permissions.
resource "aws_iam_role_policy" "firehose_os_vpc_eni" {
  name = "vpc-network-interface-management"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
        ]
        Resource = "*"
      },
    ]
  })
}

resource "aws_iam_role_policy" "firehose_os_s3_backup" {
  name = "s3-backup-access"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:AbortMultipartUpload", "s3:GetObject"]
        Resource = [
          aws_s3_bucket.firehose_os_backup.arn,
          "${aws_s3_bucket.firehose_os_backup.arn}/*",
        ]
      },
    ]
  })
}

resource "aws_iam_role_policy" "firehose_os_cloudwatch_logs" {
  name = "cloudwatch-delivery-logs"
  role = aws_iam_role.firehose.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.firehose_os_delivery.arn,
          "${aws_cloudwatch_log_group.firehose_os_delivery.arn}:*",
        ]
      },
    ]
  })
}

###############################################################################
# OpenSearch domain inside the VPC
###############################################################################

resource "aws_opensearch_domain" "firehose_os" {
  domain_name    = local.name_prefix
  engine_version = "OpenSearch_2.11"

  cluster_config {
    instance_type          = "t3.small.search"
    instance_count         = 2
    zone_awareness_enabled = true
  }

  vpc_options {
    subnet_ids         = [aws_subnet.firehose_os_private_a.id, aws_subnet.firehose_os_private_b.id]
    security_group_ids = [aws_security_group.opensearch.id]
  }

  encrypt_at_rest {
    enabled    = true
    kms_key_id = aws_kms_key.firehose_os.arn
  }

  node_to_node_encryption {
    enabled = true
  }

  domain_endpoint_options {
    enforce_https       = true
    tls_security_policy = "Policy-Min-TLS-1-2-2019-07"
  }

  # Fine-grained access control: the Firehose delivery role is the master user,
  # so no plaintext master password or out-of-band backend-role mapping is needed.
  advanced_security_options {
    enabled                        = true
    internal_user_database_enabled = false

    master_user_options {
      master_user_arn = aws_iam_role.firehose.arn
    }
  }

  tags = merge(local.common_tags, { Name = local.name_prefix })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Domain access policy: grants ONLY the Firehose role ESHttpPost/ESHttpPut
###############################################################################

resource "aws_opensearch_domain_policy" "firehose_os_access" {
  domain_name = aws_opensearch_domain.firehose_os.domain_name

  access_policies = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.firehose.arn
        }
        Action   = ["es:ESHttpPost", "es:ESHttpPut"]
        Resource = [
          aws_opensearch_domain.firehose_os.arn,
          "${aws_opensearch_domain.firehose_os.arn}/*",
        ]
      },
    ]
  })
}

###############################################################################
# Kinesis Firehose delivery stream with OpenSearch (VPC) destination
###############################################################################

# A stream with no kinesis_source_configuration block is a DirectPut stream.
resource "aws_kinesis_firehose_delivery_stream" "firehose_os" {
  name        = local.delivery_stream_name
  destination = "opensearch"

  opensearch_configuration {
    domain_arn            = aws_opensearch_domain.firehose_os.arn
    role_arn              = aws_iam_role.firehose.arn
    index_name            = local.opensearch_index
    index_rotation_period = "OneDay"
    s3_backup_mode        = "FailedDocumentsOnly"
    buffering_size        = 5
    buffering_interval    = 300
    retry_duration        = 300

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_os_delivery.name
      log_stream_name = "OpenSearch-Delivery"
    }

    s3_configuration {
      role_arn            = aws_iam_role.firehose.arn
      bucket_arn          = aws_s3_bucket.firehose_os_backup.arn
      prefix              = "backup/"
      error_output_prefix = "errors/!{firehose:error-output-type}/"
      buffering_size      = 5
      buffering_interval  = 300
      compression_format  = "GZIP"

      cloudwatch_logging_options {
        enabled         = true
        log_group_name  = aws_cloudwatch_log_group.firehose_os_delivery.name
        log_stream_name = "S3-Backup-Delivery"
      }
    }
  }

  tags = merge(local.common_tags, { Name = local.delivery_stream_name })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "opensearch_domain_endpoint" {
  description = "OpenSearch domain endpoint (VPC-internal)."
  value       = aws_opensearch_domain.firehose_os.endpoint
}

output "opensearch_domain_arn" {
  description = "ARN of the OpenSearch domain."
  value       = aws_opensearch_domain.firehose_os.arn
}

output "delivery_stream_name" {
  description = "Name of the Kinesis Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.firehose_os.name
}

output "delivery_stream_arn" {
  description = "ARN of the Kinesis Firehose delivery stream."
  value       = aws_kinesis_firehose_delivery_stream.firehose_os.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "stream_name_suffix" {
  description = "Unique suffix appended to the Kinesis Video Stream name to guarantee a unique stream name in the account/region."
  type        = string
  default     = "001"

  validation {
    condition     = can(regex("^[a-zA-Z0-9_-]+$", var.stream_name_suffix))
    error_message = "stream_name_suffix must contain only alphanumeric characters, hyphens, and underscores."
  }
}

variable "device_name" {
  description = "Name of the source device producing the media."
  type        = string
  default     = "default-camera-device"
}

variable "data_retention_in_hours" {
  description = "Number of hours the stream retains recorded media data (0-87600)."
  type        = number
  default     = 168

  validation {
    condition     = var.data_retention_in_hours >= 0 && var.data_retention_in_hours <= 87600
    error_message = "data_retention_in_hours must be between 0 and 87600."
  }
}

variable "environment" {
  description = "Environment tag value applied to the stream."
  type        = string
  default     = "dev"
}

locals {
  stream_name = "basic-video-stream-${var.stream_name_suffix}"
  media_type  = "video/h264"

  common_tags = {
    Name        = local.stream_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kinesis_video_stream" "main" {
  name                    = local.stream_name
  device_name             = var.device_name
  media_type              = local.media_type
  data_retention_in_hours = var.data_retention_in_hours

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "stream_name" {
  description = "Name of the Kinesis Video Stream."
  value       = aws_kinesis_video_stream.main.name
}

output "stream_arn" {
  description = "ARN of the Kinesis Video Stream."
  value       = aws_kinesis_video_stream.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging (cost allocation and compliance) and resource naming."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]{2,16}$", var.environment))
    error_message = "Environment must be 2-16 lowercase alphanumeric characters or hyphens."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# KMS: customer-managed key used to encrypt the Kinesis stream at rest
# -----------------------------------------------------------------------------
resource "aws_kms_key" "kinesis" {
  description             = "Customer-managed key for server-side encryption of the main Kinesis data stream"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "kinesis-stream-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "kinesis" {
  name          = "alias/kinesis-stream-${var.environment}"
  target_key_id = aws_kms_key.kinesis.key_id
}

# -----------------------------------------------------------------------------
# Kinesis Data Stream (prerequisite for the stream consumer)
# -----------------------------------------------------------------------------
resource "aws_kinesis_stream" "main" {
  name             = "kinesis-stream-${var.environment}"
  shard_count      = 1
  retention_period = 48

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = merge(local.common_tags, { Name = "kinesis-stream-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Kinesis Stream Consumer (enhanced fan-out)
# -----------------------------------------------------------------------------
resource "aws_kinesis_stream_consumer" "main" {
  name       = "main_stream_efo_consumer"
  stream_arn = aws_kinesis_stream.main.arn
}

# -----------------------------------------------------------------------------
# IAM: least-privilege access for consumers of the stream
# -----------------------------------------------------------------------------
resource "aws_iam_role" "stream_consumer" {
  name        = "kinesis-stream-consumer-role-${var.environment}"
  description = "Role assumed by consumers using enhanced fan-out on the main Kinesis stream"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowConsumerServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "kinesis-stream-consumer-role" })
}

resource "aws_iam_policy" "stream_consumer" {
  name        = "kinesis-stream-consumer-policy-${var.environment}"
  description = "Least-privilege permissions for enhanced fan-out consumption of the main Kinesis stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SubscribeToShardAndDescribeConsumer"
        Effect = "Allow"
        Action = [
          "kinesis:SubscribeToShard",
          "kinesis:DescribeStreamConsumer"
        ]
        Resource = [
          aws_kinesis_stream.main.arn,
          aws_kinesis_stream_consumer.main.arn
        ]
      },
      {
        Sid    = "ListStreamConsumers"
        Effect = "Allow"
        # kinesis:ListStreamConsumers does not support resource-level
        # permissions, so AWS requires Resource "*". The Action remains
        # tightly scoped, so this is not a wildcard Action/Resource pair.
        Action   = ["kinesis:ListStreamConsumers"]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "kinesis-stream-consumer-policy" })
}

resource "aws_iam_role_policy_attachment" "stream_consumer" {
  role       = aws_iam_role.stream_consumer.name
  policy_arn = aws_iam_policy.stream_consumer.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  delivery_stream_name = "firehose-s3-extended-destination"
  log_group_name       = "/aws/kinesisfirehose/${local.delivery_stream_name}"
  log_stream_name      = "s3-delivery-errors"
  s3_object_prefix     = "firehose-data/!{timestamp:yyyy/MM/dd}/"
  s3_error_prefix      = "processing-failed/!{firehose:error-output-type}/"
}

# ------------------------------------------------------------------------------
# S3 destination bucket for the Firehose delivery stream (stateful)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "firehose_destination" {
  # No explicit bucket name: Terraform assigns a globally unique name,
  # avoiding S3 namespace collisions in the target account.
  tags = {
    Name        = "firehose-destination"
    Purpose     = "kinesis-firehose-extended-s3-destination"
    Environment = "production"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "firehose_destination" {
  bucket = aws_s3_bucket.firehose_destination.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Logs for Firehose delivery error logging
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "firehose_delivery_logs" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = {
    Name = local.log_group_name
  }
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_errors" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_logs.name
}

# ------------------------------------------------------------------------------
# IAM role assumed by Firehose with least-privilege inline policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "firehose_delivery_role" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowFirehoseToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "firehose-delivery-role"
  }
}

resource "aws_iam_role_policy" "firehose_delivery_access" {
  name = "firehose-delivery-access"
  role = aws_iam_role.firehose_delivery_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "FirehoseS3ObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:AbortMultipartUpload"
        ]
        Resource = "${aws_s3_bucket.firehose_destination.arn}/*"
      },
      {
        Sid    = "FirehoseS3BucketActions"
        Effect = "Allow"
        Action = [
          "s3:GetBucketLocation",
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.firehose_destination.arn
      },
      {
        Sid      = "FirehosePutLogEvents"
        Effect   = "Allow"
        Action   = "logs:PutLogEvents"
        Resource = aws_cloudwatch_log_stream.firehose_delivery_errors.arn
      },
      {
        Sid    = "FirehoseLogGroupStreamManagement"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams"
        ]
        Resource = "${aws_cloudwatch_log_group.firehose_delivery_logs.arn}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Kinesis Firehose delivery stream -> extended S3 destination
# ------------------------------------------------------------------------------
resource "aws_kinesis_firehose_delivery_stream" "firehose_to_s3" {
  name        = local.delivery_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery_role.arn
    bucket_arn          = aws_s3_bucket.firehose_destination.arn
    prefix              = local.s3_object_prefix
    error_output_prefix = local.s3_error_prefix
    buffering_size      = 5
    buffering_interval  = 300
    compression_format  = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_logs.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_errors.name
    }
  }

  # Firehose validates the delivery role's permissions at stream creation
  # time, so the inline policy must exist before the stream is created.
  depends_on = [aws_iam_role_policy.firehose_delivery_access]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "application_name" {
  description = "Name of the Kinesis Data Analytics application; also used as the name prefix for related resources."
  type        = string
  default     = "basic-kinesis-analytics"
}

variable "shard_count" {
  description = "Number of provisioned shards for each Kinesis data stream."
  type        = number
  default     = 1
}

variable "environment" {
  description = "Environment name applied to the Environment tag on every resource."
  type        = string
  default     = "dev"
}

variable "additional_tags" {
  description = "Additional tags applied to every tagged resource."
  type        = map(string)
  default     = {}
}

locals {
  source_stream_name      = "${var.application_name}-source-stream"
  destination_stream_name = "${var.application_name}-destination-stream"
  log_group_name          = "/aws/kinesis-analytics/${var.application_name}"
  log_stream_name         = "${var.application_name}-application-logs"
  role_name               = "${var.application_name}-app-role"
  role_policy_name        = "${var.application_name}-app-policy"

  common_tags = merge(
    var.additional_tags,
    {
      Application = var.application_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  )
}

resource "aws_kinesis_stream" "source" {
  name             = local.source_stream_name
  shard_count      = var.shard_count
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kinesis_stream" "destination" {
  name             = local.destination_stream_name
  shard_count      = var.shard_count
  retention_period = 24
  encryption_type  = "KMS"
  kms_key_id       = "alias/aws/kinesis"

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

resource "aws_iam_role" "kinesis_analytics_app" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kinesis_analytics_app" {
  name = local.role_policy_name
  role = aws_iam_role.kinesis_analytics_app.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadFromSourceStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:GetShardIterator",
          "kinesis:GetRecords",
          "kinesis:ListShards"
        ]
        Resource = aws_kinesis_stream.source.arn
      },
      {
        Sid    = "WriteToDestinationStream"
        Effect = "Allow"
        Action = [
          "kinesis:PutRecord",
          "kinesis:PutRecordBatch"
        ]
        Resource = aws_kinesis_stream.destination.arn
      },
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      },
      {
        Sid      = "PublishApplicationMetrics"
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kinesis_analytics_application" "basic_app" {
  name        = var.application_name
  description = "Basic SQL application forwarding records from the source stream to the destination stream."

  code = <<-SQL
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
      "event_id"   VARCHAR(64),
      "event_type" VARCHAR(64),
      "payload"    VARCHAR(2048)
    );

    CREATE OR REPLACE PUMP "FORWARD_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM "event_id", "event_type", "payload"
      FROM "SOURCE_SQL_STREAM_001";
  SQL

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
    role_arn       = aws_iam_role.kinesis_analytics_app.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    parallelism {
      count = 1
    }

    kinesis_stream {
      resource_arn = aws_kinesis_stream.source.arn
      role_arn     = aws_iam_role.kinesis_analytics_app.arn
    }

    schema {
      record_encoding = "UTF-8"

      record_columns {
        name     = "event_id"
        mapping  = "$.event_id"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "event_type"
        mapping  = "$.event_type"
        sql_type = "VARCHAR(64)"
      }

      record_columns {
        name     = "payload"
        mapping  = "$.payload"
        sql_type = "VARCHAR(2048)"
      }

      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.destination.arn
      role_arn     = aws_iam_role.kinesis_analytics_app.arn
    }

    schema {
      record_format_type = "JSON"
    }
  }

  start_application = true

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kinesis_analytics_app]

  lifecycle {
    prevent_destroy = true
  }
}

output "application_arn" {
  description = "ARN of the Kinesis Data Analytics application."
  value       = aws_kinesis_analytics_application.basic_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Data Analytics application."
  value       = aws_kinesis_analytics_application.basic_app.name
}

output "source_stream_name" {
  description = "Name of the source Kinesis data stream consumed by the application."
  value       = aws_kinesis_stream.source.name
}

output "source_stream_arn" {
  description = "ARN of the source Kinesis data stream consumed by the application."
  value       = aws_kinesis_stream.source.arn
}

output "destination_stream_name" {
  description = "Name of the destination Kinesis data stream written to by the application."
  value       = aws_kinesis_stream.destination.name
}

output "destination_stream_arn" {
  description = "ARN of the destination Kinesis data stream written to by the application."
  value       = aws_kinesis_stream.destination.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "application_name" {
  description = "Name of the Kinesis Data Analytics SQL application."
  type        = string
  default     = "kinesis_analytics_sql_app"
}

variable "shard_count" {
  description = "Number of shards for each provisioned Kinesis stream."
  type        = number
  default     = 1
}

variable "retention_period_hours" {
  description = "Data retention period (in hours) for the Kinesis streams."
  type        = number
  default     = 24
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention period (in days) for the application log group."
  type        = number
  default     = 30
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the KMS key is deleted after destruction is requested."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "production"
    Application = "kinesis-analytics-sql"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  application_name   = var.application_name
  input_stream_name  = "${var.application_name}-input"
  output_stream_name = "${var.application_name}-output"
  log_group_name     = "/aws/kinesisanalytics/${var.application_name}"
  log_stream_name    = "${var.application_name}-application-logs"
  common_tags        = var.tags

  # Inline SQL transformation code executed by the SQL-1_0 runtime.
  # SOURCE_SQL_STREAM_001 is the in-application stream created from the
  # configured input name prefix; DESTINATION_SQL_STREAM is bound to the
  # configured output destination.
  sql_application_code = <<-EOT
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" (
        "TICKER_SYMBOL" VARCHAR(16),
        "SECTOR"        VARCHAR(16),
        "CHANGE"        REAL,
        "PRICE"         REAL
    );

    CREATE OR REPLACE PUMP "OUTPUT_PUMP" AS
        INSERT INTO "DESTINATION_SQL_STREAM"
        SELECT STREAM "TICKER_SYMBOL", "SECTOR", "CHANGE", "PRICE"
        FROM "SOURCE_SQL_STREAM_001"
        WHERE "CHANGE" > 0;
  EOT
}

# -----------------------------------------------------------------------------
# KMS key for encrypting streams, logs, and the analytics application
# -----------------------------------------------------------------------------

resource "aws_kms_key" "kinesis" {
  description             = "KMS key for the Kinesis Data Analytics SQL application, its Kinesis streams, and CloudWatch logs."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-kms-key"
  })
}

# -----------------------------------------------------------------------------
# Kinesis streams: SQL application source and destination
# -----------------------------------------------------------------------------

resource "aws_kinesis_stream" "input" {
  name             = local.input_stream_name
  shard_count      = var.shard_count
  retention_period = var.retention_period_hours

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.input_stream_name
  })
}

resource "aws_kinesis_stream" "output" {
  name             = local.output_stream_name
  shard_count      = var.shard_count
  retention_period = var.retention_period_hours

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"
  kms_key_id      = aws_kms_key.kinesis.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.output_stream_name
  })
}

# -----------------------------------------------------------------------------
# CloudWatch logging for the analytics application
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kinesis_analytics" {
  name              = local.log_group_name
  retention_in_days = var.log_retention_in_days
  kms_key_id        = aws_kms_key.kinesis.arn

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics" {
  name           = local.log_stream_name
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics.name
}

# -----------------------------------------------------------------------------
# Service execution role for the analytics application
# -----------------------------------------------------------------------------

resource "aws_iam_role" "kinesis_analytics" {
  name        = "${local.application_name}-role"
  description = "Service execution role for the Kinesis Data Analytics SQL application."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.application_name}-role"
  })
}

resource "aws_iam_role_policy" "kinesis_analytics" {
  name = "${local.application_name}-inline-policy"
  role = aws_iam_role.kinesis_analytics.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadInputStream"
        Effect   = "Allow"
        Action   = ["kinesis:DescribeStream", "kinesis:GetShardIterator", "kinesis:GetRecords", "kinesis:ListShards"]
        Resource = aws_kinesis_stream.input.arn
      },
      {
        Sid      = "WriteOutputStream"
        Effect   = "Allow"
        Action   = ["kinesis:PutRecord", "kinesis:PutRecords"]
        Resource = aws_kinesis_stream.output.arn
      },
      {
        Sid    = "ApplicationCloudWatchLogs"
        Effect = "Allow"
        Action = ["logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = [
          aws_cloudwatch_log_group.kinesis_analytics.arn,
          aws_cloudwatch_log_stream.kinesis_analytics.arn
        ]
      },
      {
        Sid      = "KmsAccessForStreamsAndLogs"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.kinesis.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Kinesis Data Analytics V2 SQL application
# -----------------------------------------------------------------------------

resource "aws_kinesisanalyticsv2_application" "sql_app" {
  name                  = local.application_name
  description           = "Kinesis Data Analytics SQL application that reads records from the input stream, filters on price change, and writes results to the output stream."
  runtime_environment   = "SQL-1_0"
  service_execution_role = aws_iam_role.kinesis_analytics.arn
  start_application     = true

  application_configuration {
    application_code_configuration {
      code_content {
        text_content = local.sql_application_code
      }

      code_content_type = "PLAINTEXT"
    }

    sql_application_configuration {
      input {
        name_prefix = "SOURCE_SQL_STREAM"

        input_schema {
          record_encoding = "UTF-8"

          record_column {
            name     = "TICKER_SYMBOL"
            mapping  = "$.ticker_symbol"
            sql_type = "VARCHAR(16)"
          }

          record_column {
            name     = "SECTOR"
            mapping  = "$.sector"
            sql_type = "VARCHAR(16)"
          }

          record_column {
            name     = "CHANGE"
            mapping  = "$.change"
            sql_type = "REAL"
          }

          record_column {
            name     = "PRICE"
            mapping  = "$.price"
            sql_type = "REAL"
          }

          record_format {
            record_format_type = "JSON"

            mapping_parameters {
              json_mapping_parameters {
                record_row_path = "$"
              }
            }
          }
        }

        input_parallelism {
          count = 1
        }

        input_starting_position_configuration {
          input_starting_position = "LAST_STOPPED_POINT"
        }

        kinesis_streams_input {
          resource_arn = aws_kinesis_stream.input.arn
        }
      }

      output {
        name = "DESTINATION_SQL_STREAM"

        destination_schema {
          record_format_type = "JSON"
        }

        kinesis_streams_output {
          resource_arn = aws_kinesis_stream.output.arn
        }
      }
    }
  }

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics.arn
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy.kinesis_analytics,
    aws_cloudwatch_log_stream.kinesis_analytics,
  ]

  tags = merge(local.common_tags, {
    Name = local.application_name
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment label used for resource tagging (non-infrastructure default)."
  type        = string
  default     = "dev"
}

locals {
  app_name    = "kinesis_analytics_app_${var.environment}"
  stream_name = "kinesis_analytics_input_stream_${var.environment}"
  role_name   = "kinesis_analytics_role_${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Application = "kinesis-analytics"
  }
}

# ------------------------------------------------------------------
# Input Kinesis stream (stateful - protected from destruction)
# ------------------------------------------------------------------
resource "aws_kinesis_stream" "input_stream" {
  name             = local.stream_name
  shard_count      = 1
  retention_period = 48

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  encryption_type = "KMS"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# CloudWatch Logs for the analytics application
# ------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "kinesis_analytics_logs" {
  name              = "/aws/kinesis-analytics/${local.app_name}"
  retention_in_days = 30

  tags = local.common_tags
}

resource "aws_cloudwatch_log_stream" "kinesis_analytics_log_stream" {
  name           = "${local.app_name}-log-stream"
  log_group_name = aws_cloudwatch_log_group.kinesis_analytics_logs.name
}

# ------------------------------------------------------------------
# IAM role and least-privilege policy for the analytics application
# ------------------------------------------------------------------
resource "aws_iam_role" "kinesis_analytics_role" {
  name = local.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKinesisAnalyticsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kinesis_analytics_policy" {
  name = "${local.role_name}_policy"
  role = aws_iam_role.kinesis_analytics_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadInputStream"
        Effect = "Allow"
        Action = [
          "kinesis:DescribeStream",
          "kinesis:DescribeStreamSummary",
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:ListShards"
        ]
        Resource = aws_kinesis_stream.input_stream.arn
      },
      {
        Sid    = "WriteApplicationLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          "${aws_cloudwatch_log_group.kinesis_analytics_logs.arn}:*",
          aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------
# Kinesis Analytics (SQL v1) application - SQL runtime is implicit in v1;
# the execution role is supplied per-integration via role_arn references.
# ------------------------------------------------------------------
resource "aws_kinesis_analytics_application" "analytics_app" {
  name        = local.app_name
  description = "Basic SQL Kinesis Analytics application consuming the input Kinesis stream"

  code = <<-SQL
    CREATE OR REPLACE STREAM "DESTINATION_SQL_STREAM" ("payload" VARCHAR(64));

    CREATE OR REPLACE PUMP "STREAM_PUMP" AS
      INSERT INTO "DESTINATION_SQL_STREAM"
      SELECT STREAM "payload" FROM "SOURCE_SQL_STREAM_001";
  SQL

  cloudwatch_logging_options {
    log_stream_arn = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
    role_arn       = aws_iam_role.kinesis_analytics_role.arn
  }

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"

    kinesis_stream {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    schema {
      record_columns {
        name     = "payload"
        sql_type = "VARCHAR(64)"
        mapping  = "$.payload"
      }

      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"
    }

    starting_position_configuration {
      starting_position = "LATEST"
    }
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kinesis_analytics_policy]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------
output "application_arn" {
  description = "ARN of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.analytics_app.arn
}

output "application_name" {
  description = "Name of the Kinesis Analytics application."
  value       = aws_kinesis_analytics_application.analytics_app.name
}

output "cloudwatch_log_stream_arn" {
  description = "ARN of the CloudWatch log stream receiving Kinesis Analytics application logs."
  value       = aws_cloudwatch_log_stream.kinesis_analytics_log_stream.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Input variables
###############################################################################

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

variable "confluence_server_url" {
  description = "Base URL of the Confluence Cloud instance to crawl."
  type        = string
  default     = "https://example.atlassian.net/wiki"
}

variable "proxy_host" {
  description = "Hostname of the outgoing web proxy used by the Confluence data source."
  type        = string
  default     = "proxy.example.com"
}

variable "proxy_port" {
  description = "Port of the outgoing web proxy used by the Confluence data source."
  type        = number
  default     = 3128
}

variable "proxy_username" {
  description = "Proxy server username. Supply the real value via tfvars or TF_VAR_proxy_username; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_PROXY_USERNAME"
}

variable "proxy_password" {
  description = "Proxy server password. Supply the real value via tfvars or TF_VAR_proxy_password; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_PROXY_PASSWORD"
}

variable "confluence_username" {
  description = "Confluence account username. Supply the real value via tfvars or TF_VAR_confluence_username; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_CONFLUENCE_USERNAME"
}

variable "confluence_api_key" {
  description = "Confluence Cloud API token stored as the connector password. Supply the real value via tfvars or TF_VAR_confluence_api_key; never hardcode it here."
  type        = string
  sensitive   = true
  default     = "REPLACE_WITH_CONFLUENCE_API_TOKEN"
}

###############################################################################
# Static metadata lookups (pure local, no pre-existing infrastructure required)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id               = data.aws_caller_identity.current.account_id
  partition                = data.aws_partition.current.partition
  kendra_service_principal = "kendra.amazonaws.com"
}

###############################################################################
# Customer managed KMS key used to encrypt the Kendra index
###############################################################################

resource "aws_kms_key" "kendra" {
  description             = "Customer managed KMS key used to encrypt the Kendra index."
  enable_key_rotation     = true
  deletion_window_in_days = 30

  # Least-privilege key policy:
  #   - the account root retains administrative control of the key
  #   - the Kendra service principal is granted only the kms: actions required
  #     to use the key, restricted to callers from this AWS account
  #   - the Kendra index IAM role is granted only kms:Decrypt/kms:GenerateDataKey
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdministration"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowKendraServiceToUseKey"
        Effect    = "Allow"
        Principal = {
          Service = local.kendra_service_principal
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      },
      {
        Sid       = "AllowKendraIndexRoleToUseKey"
        Effect    = "Allow"
        Principal = {
          AWS = aws_iam_role.kendra_index.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

###############################################################################
# IAM role assumed by Amazon Kendra for the index
###############################################################################

data "aws_iam_policy_document" "kendra_index_trust" {
  statement {
    sid     = "AllowKendraServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.kendra_service_principal]
    }
  }
}

resource "aws_iam_role" "kendra_index" {
  name               = "kendra-index-role"
  description        = "Role assumed by Amazon Kendra to create and manage the index."
  assume_role_policy = data.aws_iam_policy_document.kendra_index_trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "kendra_index" {
  name = "kendra-index-role-policy"
  role = aws_iam_role.kendra_index.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowDocumentOperationsOnIndex"
        Effect   = "Allow"
        Action   = ["kendra:BatchPutDocument", "kendra:BatchDeleteDocument"]
        Resource = [aws_kendra_index.main.arn]
      },
      {
        Sid      = "AllowKmsUsageForIndexEncryption"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [aws_kms_key.kendra.arn]
      }
    ]
  })
}

###############################################################################
# Kendra index (encrypted with the customer managed KMS key)
###############################################################################

resource "aws_kendra_index" "main" {
  name        = "kendra-enterprise-index"
  description = "Enterprise edition Kendra index encrypted with a customer managed KMS key."
  edition     = "ENTERPRISE_EDITION"

  # Per the hashicorp/aws ~> 5.0 schema, aws_kendra_index names the index role
  # attribute role_arn (the iam_role_arn naming belongs to other resources).
  role_arn = aws_iam_role.kendra_index.arn

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Secrets Manager: proxy server credentials
###############################################################################

resource "aws_secretsmanager_secret" "proxy_credentials" {
  name        = "kendra/proxy-credentials"
  description = "Proxy server credentials consumed by the Kendra data source web proxy settings."
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "proxy_credentials" {
  secret_id = aws_secretsmanager_secret.proxy_credentials.id
  secret_string = jsonencode({
    username = var.proxy_username
    password = var.proxy_password
  })
}

###############################################################################
# Secrets Manager: Confluence connector authentication credentials
###############################################################################

resource "aws_secretsmanager_secret" "confluence_credentials" {
  name        = "kendra/confluence-credentials"
  description = "Confluence Cloud connector authentication credentials consumed by the Kendra data source."
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "confluence_credentials" {
  secret_id = aws_secretsmanager_secret.confluence_credentials.id
  secret_string = jsonencode({
    username = var.confluence_username
    password = var.confluence_api_key
  })
}

###############################################################################
# IAM role assumed by Amazon Kendra for the data source
###############################################################################

data "aws_iam_policy_document" "kendra_data_source_trust" {
  statement {
    sid     = "AllowKendraServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = [local.kendra_service_principal]
    }
  }
}

resource "aws_iam_role" "kendra_data_source" {
  name               = "kendra-confluence-data-source-role"
  description        = "Role assumed by Amazon Kendra to crawl the Confluence data source."
  assume_role_policy = data.aws_iam_policy_document.kendra_data_source_trust.json
  tags               = var.tags
}

resource "aws_iam_role_policy" "kendra_data_source" {
  name = "kendra-confluence-data-source-role-policy"
  role = aws_iam_role.kendra_data_source.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowDocumentOperationsOnIndex"
        Effect   = "Allow"
        Action   = ["kendra:BatchPutDocument", "kendra:BatchDeleteDocument"]
        Resource = [aws_kendra_index.main.arn]
      },
      {
        Sid    = "AllowReadingConnectorAndProxySecrets"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          aws_secretsmanager_secret.confluence_credentials.arn,
          aws_secretsmanager_secret.proxy_credentials.arn
        ]
      }
    ]
  })
}

###############################################################################
# Kendra data source: Confluence Cloud via the template-connector pattern
#
# hashicorp/aws ~> 5.0 implements aws_kendra_data_source with only
# configuration.template_configuration for non-S3/web-crawler connectors, so the
# Confluence connector is declared here as type = "TEMPLATE" with a JSON
# template payload. The payload carries only the Confluence host, proxy
# endpoint, and Secrets Manager secret ARNs — never secret values.
###############################################################################

resource "aws_kendra_data_source" "confluence" {
  name        = "confluence-data-source"
  description = "Confluence Cloud data source crawled through a web proxy."
  index_id    = aws_kendra_index.main.id
  role_arn    = aws_iam_role.kendra_data_source.arn
  type        = "TEMPLATE"

  configuration {
    template_configuration {
      template = jsonencode({
        connectionConfiguration = {
          repositoryEndpointMetadata = {
            # Confluence Cloud host URL (cloud flavor expressed via the host URL)
            ConfluenceHostUrl = var.confluence_server_url
            # Connector authentication: Secrets Manager secret ARN only
            Credentials = aws_secretsmanager_secret.confluence_credentials.arn
            # Outgoing web proxy endpoint traversed by the crawler
            Host             = var.proxy_host
            Port             = tostring(var.proxy_port)
            ProxyCredentials = aws_secretsmanager_secret.proxy_credentials.arn
          }
        }
        repositoryConfigurations = {
          pages = {
            crawl         = true
            fieldMappings = []
          }
          blog = {
            crawl         = true
            fieldMappings = []
          }
          database = {
            crawl         = true
            fieldMappings = []
          }
          space = {
            crawl         = true
            fieldMappings = []
          }
          attachment = {
            crawl         = true
            fieldMappings = []
          }
        }
        additionalProperties = {
          isCrawlAcl       = true
          isCrawlChangelog = false
        }
        type     = "CONFLUENCE"
        version  = "1.0.0"
        syncMode = "FULL_CRAWL"
      })
    }
  }

  tags = var.tags
}

###############################################################################
# Outputs (non-sensitive only)
###############################################################################

output "kendra_index_id" {
  description = "ID of the Kendra index."
  value       = aws_kendra_index.main.id
}

output "kendra_index_arn" {
  description = "ARN of the Kendra index."
  value       = aws_kendra_index.main.arn
}

output "kendra_data_source_id" {
  description = "ID of the Confluence Kendra data source."
  value       = aws_kendra_data_source.confluence.id
}

output "kendra_data_source_arn" {
  description = "ARN of the Confluence Kendra data source."
  value       = aws_kendra_data_source.confluence.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  kendra_logs_arn_prefix = "arn:aws:logs:*:*:log-group:/aws/kendra*"
}

variable "seed_urls" {
  description = "Seed URLs where the Kendra web crawler starts crawling."
  type        = list(string)
  default     = ["https://docs.aws.amazon.com/kendra/"]

  validation {
    condition     = length(var.seed_urls) > 0
    error_message = "At least one seed URL must be provided."
  }
}

variable "web_crawler_mode" {
  description = "Scope of the web crawl. One of HOST_ONLY, SUBDOMAINS, or EVERYTHING."
  type        = string
  default     = "SUBDOMAINS"

  validation {
    condition     = contains(["HOST_ONLY", "SUBDOMAINS", "EVERYTHING"], var.web_crawler_mode)
    error_message = "web_crawler_mode must be one of: HOST_ONLY, SUBDOMAINS, EVERYTHING."
  }
}

variable "url_inclusion_patterns" {
  description = "Regular expressions restricting the crawl to desired content paths."
  type        = list(string)
  default     = ["^https://docs\\.aws\\.amazon\\.com/kendra/.*"]

  validation {
    condition     = length(var.url_inclusion_patterns) > 0
    error_message = "At least one URL inclusion pattern must be provided."
  }
}

variable "url_exclusion_patterns" {
  description = "Regular expressions excluding binary and static assets from the crawl."
  type        = list(string)
  default     = ["\\.(jpg|jpeg|png|gif|css|js|zip|mp4|pdf)$"]

  validation {
    condition     = length(var.url_exclusion_patterns) > 0
    error_message = "At least one URL exclusion pattern must be provided."
  }
}

variable "default_tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project     = "kendra-web-crawler"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "kendra" {
  description             = "Customer managed key encrypting the Amazon Kendra index at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = var.default_tags
}

resource "aws_iam_role" "kendra_index_role" {
  name        = "kendra-index-role"
  description = "Role assumed by Amazon Kendra to create and operate the index"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.default_tags
}

resource "aws_iam_role_policy" "kendra_index_policy" {
  name = "kendra-index-policy"
  role = aws_iam_role.kendra_index_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "KendraCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "KendraCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = local.kendra_logs_arn_prefix
      },
      {
        Sid    = "KendraKmsKey"
        Effect = "Allow"
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:ListGrants",
          "kms:RevokeGrant"
        ]
        Resource = aws_kms_key.kendra.arn
      }
    ]
  })
}

resource "aws_kendra_index" "kendra_index" {
  name        = "kendra_web_index"
  edition     = "DEVELOPER_EDITION"
  role_arn    = aws_iam_role.kendra_index_role.arn
  description = "Amazon Kendra index encrypted with a customer managed KMS key"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = var.default_tags

  depends_on = [aws_iam_role_policy.kendra_index_policy]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kendra_data_source_role" {
  name        = "kendra-web-crawler-role"
  description = "Role assumed by Amazon Kendra for the WEBCRAWLER data source"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.default_tags
}

resource "aws_iam_role_policy" "kendra_data_source_policy" {
  name = "kendra-web-crawler-policy"
  role = aws_iam_role.kendra_data_source_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "KendraWebCrawlerCloudWatchMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = "*"
      },
      {
        Sid    = "KendraWebCrawlerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = local.kendra_logs_arn_prefix
      }
    ]
  })
}

resource "aws_kendra_data_source" "web_crawler" {
  index_id      = aws_kendra_index.kendra_index.id
  name          = "web_crawler"
  type          = "WEBCRAWLER"
  role_arn      = aws_iam_role.kendra_data_source_role.arn
  description   = "Web crawler data source with URL inclusion and exclusion patterns"
  language_code = "en"
  tags          = var.default_tags

  configuration {
    web_crawler_configuration {
      url_inclusion_patterns = var.url_inclusion_patterns
      url_exclusion_patterns = var.url_exclusion_patterns

      crawl_depth                    = 2
      max_links_per_page             = 50
      max_urls_per_minute_crawl_rate = 30

      urls {
        seed_url_configuration {
          seed_urls        = var.seed_urls
          web_crawler_mode = var.web_crawler_mode
        }
      }
    }
  }

  depends_on = [aws_iam_role_policy.kendra_data_source_policy]

  lifecycle {
    prevent_destroy = true
  }
}

output "kendra_index_id" {
  description = "Identifier of the Amazon Kendra index."
  value       = aws_kendra_index.kendra_index.id
}

output "kendra_data_source_id" {
  description = "Identifier of the Kendra WEBCRAWLER data source."
  value       = aws_kendra_data_source.web_crawler.data_source_id
}

output "kendra_data_source_arn" {
  description = "ARN of the Kendra WEBCRAWLER data source."
  value       = aws_kendra_data_source.web_crawler.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a consistent tag across all resources."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  index_name = "kendra-index-${var.environment}"

  common_tags = {
    Name        = local.index_name
    Environment = var.environment
  }
}

resource "aws_kms_key" "kendra" {
  description             = "Customer managed KMS key used to encrypt the Kendra index and its CloudWatch log group"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kendra_kms_key.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kendra_kms_key" {
  statement {
    sid    = "EnableRootAccountFullControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowKendraServiceEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["kendra.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "kendra_index" {
  name               = "${local.index_name}-role"
  description        = "IAM role assumed by the Amazon Kendra service for index operations"
  assume_role_policy = data.aws_iam_policy_document.kendra_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "kendra_assume_role" {
  statement {
    sid    = "AllowKendraServiceAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kendra.amazonaws.com"]
    }
  }
}

resource "aws_cloudwatch_log_group" "kendra_index" {
  name              = "/aws/kendra/${local.index_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.kendra.arn
  tags              = local.common_tags
}

data "aws_iam_policy_document" "kendra_index_cloudwatch" {
  statement {
    sid       = "AllowKendraCreateLogGroups"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowKendraWriteIndexLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.kendra_index.arn,
      "${aws_cloudwatch_log_group.kendra_index.arn}:*",
    ]
  }

  statement {
    sid       = "AllowKendraPublishMetrics"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "kendra_index_cloudwatch" {
  name   = "${local.index_name}-cloudwatch"
  role   = aws_iam_role.kendra_index.name
  policy = data.aws_iam_policy_document.kendra_index_cloudwatch.json
}

resource "aws_kendra_index" "main" {
  name        = local.index_name
  description = "Main Kendra index using the default document metadata configuration"
  role_arn    = aws_iam_role.kendra_index.arn
  edition     = "DEVELOPER_EDITION"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_iam_role_policy.kendra_index_cloudwatch]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Project     = "kendra-enterprise-index"
    Environment = "production"
  }
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (no pre-existing infrastructure required)
# ---------------------------------------------------------------------------

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = merge(
    {
      ManagedBy = "terraform"
    },
    var.tags
  )

  kendra_log_group_arn_pattern = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/kendra/*"
}

# ---------------------------------------------------------------------------
# KMS: customer-managed key used to encrypt the Kendra index at rest
# ---------------------------------------------------------------------------

resource "aws_kms_key" "kendra_index" {
  description             = "Customer-managed KMS key used to encrypt the Amazon Kendra index at rest"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowKendraIndexRoleAndService"
        Effect = "Allow"
        Principal = {
          AWS     = aws_iam_role.kendra_index.arn
          Service = "kendra.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "kendra_index" {
  name          = "alias/kendra-index"
  target_key_id = aws_kms_key.kendra_index.key_id
}

# ---------------------------------------------------------------------------
# IAM: service role assumed by Amazon Kendra
# ---------------------------------------------------------------------------

resource "aws_iam_role" "kendra_index" {
  name        = "kendra-index-role"
  description = "Service role assumed by Amazon Kendra to access AWS resources on behalf of the index"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKendraToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kendra_index_logs" {
  name = "kendra-index-cloudwatch-logs"
  role = aws_iam_role.kendra_index.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KendraIndexCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = local.kendra_log_group_arn_pattern
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Kendra index: Enterprise Edition, CMK-encrypted, user group resolution via
# AWS SSO (IAM Identity Center)
# ---------------------------------------------------------------------------

resource "aws_kendra_index" "main" {
  name        = "enterprise-kendra-index"
  description = "Enterprise edition Amazon Kendra index with user group resolution backed by AWS SSO (IAM Identity Center) and customer-managed KMS encryption"
  role_arn    = aws_iam_role.kendra_index.arn
  edition     = "ENTERPRISE_EDITION"

  server_side_encryption_configuration {
    kms_key_id = aws_kms_key.kendra_index.arn
  }

  user_group_resolution_configuration {
    user_group_resolution_mode = "AWS_SSO"
  }

  tags = local.common_tags

  depends_on = [aws_iam_role_policy.kendra_index_logs]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Standard tags applied to the hosted zone for ownership and cost-allocation compliance."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags = var.tags
}

resource "aws_route53_zone" "example53" {
  name = "example53.com"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "zone_id" {
  description = "The ID of the example53.com public hosted zone."
  value       = aws_route53_zone.example53.zone_id
}

output "name_servers" {
  description = "The authoritative name servers for example53.com, to be configured at the domain registrar for delegation."
  value       = aws_route53_zone.example53.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag value applied to Route 53 resources."
  type        = string
  default     = "production"
}

variable "target_ipv4" {
  description = "IPv4 address the www A record points to (documentation IP by default)."
  type        = string
  default     = "203.0.113.10"

  validation {
    condition     = can(cidrnetmask("${var.target_ipv4}/32"))
    error_message = "target_ipv4 must be a valid IPv4 address."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_route53_zone" "example53_com" {
  name = "example53.com"

  tags = merge(
    local.common_tags,
    {
      Name = "example53.com"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "example_record" {
  zone_id = aws_route53_zone.example53_com.zone_id
  name    = "www.${aws_route53_zone.example53_com.name}"
  type    = "A"
  ttl     = 300
  records = [var.target_ipv4]
}

output "zone_name_servers" {
  description = "Name servers to configure at the registrar to delegate example53.com to this hosted zone."
  value       = aws_route53_zone.example53_com.name_servers
}

output "zone_id" {
  description = "ID of the example53.com hosted zone."
  value       = aws_route53_zone.example53_com.zone_id
}

output "record_fqdn" {
  description = "Fully qualified domain name of the www A record."
  value       = aws_route53_record.example_record.fqdn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main"
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "internal.example53.com"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = {
    Name = "internal.example53.com"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_record" "app" {
  zone_id = aws_route53_zone.private_zone.zone_id
  name    = "app.internal.example53.com"
  type    = "A"
  ttl     = 300
  records = ["10.0.1.10"]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "domain_name" {
  description = "Domain name for the public hosted zone"
  type        = string
  default     = "example.com"
}

variable "record_name" {
  description = "Subdomain for the failover alias records"
  type        = string
  default     = "www"
}

variable "environment" {
  description = "Environment tag value applied to all resources"
  type        = string
  default     = "production"
}

locals {
  name_prefix = "r53-failover"
  record_fqdn = "${var.record_name}.${var.domain_name}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Public web traffic (HTTP/HTTPS) to the failover ALBs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

# -----------------------------------------------------------------------------
# Failover endpoint targets (Active / Passive ALBs)
# -----------------------------------------------------------------------------

resource "aws_lb" "primary" {
  name               = "${local.name_prefix}-primary"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-alb"
  })
}

resource "aws_lb" "secondary" {
  name               = "${local.name_prefix}-secondary"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secondary-alb"
  })
}

resource "aws_lb_listener" "primary_http" {
  load_balancer_arn = aws_lb.primary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-listener"
  })
}

resource "aws_lb_listener" "secondary_http" {
  load_balancer_arn = aws_lb.secondary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secondary-listener"
  })
}

# -----------------------------------------------------------------------------
# DNS: hosted zone, health check, and failover records
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "primary" {
  name = var.domain_name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-zone"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = aws_lb.primary.dns_name
  type              = "HTTP"
  port              = 80
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary-health-check"
  })
}

resource "aws_route53_record" "failover_primary" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "primary"
  health_check_id = aws_route53_health_check.primary_health_check.id

  failover_routing_policy {
    type = "PRIMARY"
  }

  alias {
    name                   = aws_lb.primary.dns_name
    zone_id                = aws_lb.primary.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "failover_secondary" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier = "secondary"

  failover_routing_policy {
    type = "SECONDARY"
  }

  alias {
    name                   = aws_lb.secondary.dns_name
    zone_id                = aws_lb.secondary.zone_id
    evaluate_target_health = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  health_check_path = "/health"
  www_record_name   = "www.${aws_route53_zone.main.name}"
}

variable "domain_name" {
  description = "Domain name of the Route 53 hosted zone to create."
  type        = string
  default     = "example.com"
}

variable "tags" {
  description = "Tags applied to all Route 53 resources."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Purpose     = "active-active-failover"
  }
}

variable "endpoint_ips" {
  description = "Public IPv4 addresses of the primary and secondary application endpoints."
  type        = map(string)
  default = {
    primary   = "203.0.113.10"
    secondary = "203.0.113.20"
  }
}

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route53_health_check" "primary_health_check" {
  fqdn              = "primary.${aws_route53_zone.main.name}"
  type              = "HTTPS"
  port              = 443
  resource_path     = local.health_check_path
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true
  enable_sni        = true

  tags = var.tags
}

resource "aws_route53_health_check" "secondary_health_check" {
  fqdn              = "secondary.${aws_route53_zone.main.name}"
  type              = "HTTPS"
  port              = 443
  resource_path     = local.health_check_path
  request_interval  = 30
  failure_threshold = 3
  measure_latency   = true
  enable_sni        = true

  tags = var.tags
}

resource "aws_route53_record" "primary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.www_record_name
  type    = "A"
  ttl     = 60

  records        = [var.endpoint_ips["primary"]]
  set_identifier = "PRIMARY"
  health_check_id = aws_route53_health_check.primary_health_check.id

  failover_routing_policy {
    type = "PRIMARY"
  }
}

resource "aws_route53_record" "secondary" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.www_record_name
  type    = "A"
  ttl     = 60

  records        = [var.endpoint_ips["secondary"]]
  set_identifier = "SECONDARY"
  health_check_id = aws_route53_health_check.secondary_health_check.id

  failover_routing_policy {
    type = "SECONDARY"
  }
}

output "hosted_zone_id" {
  description = "ID of the main Route 53 hosted zone."
  value       = aws_route53_zone.main.zone_id
}

output "hosted_zone_name_servers" {
  description = "Delegated name servers for the main hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "primary_health_check_id" {
  description = "ID of the primary endpoint health check."
  value       = aws_route53_health_check.primary_health_check.id
}

output "secondary_health_check_id" {
  description = "ID of the secondary endpoint health check."
  value       = aws_route53_health_check.secondary_health_check.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name   = "foobar"
  region = "us-east-1"

  common_tags = {
    Name      = local.name
    ManagedBy = "terraform"
  }
}

resource "aws_cloudwatch_metric_alarm" "foobar" {
  alarm_name          = local.name
  alarm_description   = "Average EC2 CPU utilization at or above threshold"
  namespace           = "AWS/EC2"
  metric_name         = "CPUUtilization"
  statistic           = "Average"
  period              = 120
  evaluation_periods  = 2
  threshold           = 80
  comparison_operator = "GreaterThanOrEqualToThreshold"
  treat_missing_data  = "missing"

  tags = local.common_tags
}

resource "aws_route53_health_check" "foobar" {
  type = "CLOUDWATCH_METRIC"

  cloudwatch_alarm_name           = aws_cloudwatch_metric_alarm.foobar.alarm_name
  cloudwatch_alarm_region         = local.region
  insufficient_data_health_status = "Healthy"

  tags = local.common_tags
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "eu"
  region = "eu-central-1"
}

variable "zone_name" {
  description = "Domain name for the primary public hosted zone."
  type        = string
  default     = "primary.example.com"
}

data "aws_availability_zones" "us" {
  state = "available"
}

data "aws_availability_zones" "eu" {
  provider = aws.eu
  state    = "available"
}

locals {
  record_name = "app"
  record_fqdn = "${local.record_name}.${aws_route53_zone.primary.name}"
}

resource "aws_route53_zone" "primary" {
  name = var.zone_name

  tags = {
    Name = "primary"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# us-east-1 networking (default provider)
# -----------------------------------------------------------------------------
resource "aws_vpc" "us" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = "primary-us-east-1"
    Region = "us-east-1"
  }
}

resource "aws_subnet" "us_a" {
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.us.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-us-east-1-public-a"
    Region = "us-east-1"
  }
}

resource "aws_subnet" "us_b" {
  vpc_id                  = aws_vpc.us.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.us.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name   = "primary-us-east-1-public-b"
    Region = "us-east-1"
  }
}

resource "aws_internet_gateway" "us" {
  vpc_id = aws_vpc.us.id

  tags = {
    Name   = "primary-us-east-1-igw"
    Region = "us-east-1"
  }
}

resource "aws_route_table" "us" {
  vpc_id = aws_vpc.us.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.us.id
  }

  tags = {
    Name   = "primary-us-east-1-rt"
    Region = "us-east-1"
  }
}

resource "aws_route_table_association" "us_a" {
  subnet_id      = aws_subnet.us_a.id
  route_table_id = aws_route_table.us.id
}

resource "aws_route_table_association" "us_b" {
  subnet_id      = aws_subnet.us_b.id
  route_table_id = aws_route_table.us.id
}

resource "aws_security_group" "us" {
  name        = "primary-us-east-1-alb-sg"
  description = "Allow HTTP and HTTPS ingress to the us-east-1 routing-policy endpoint"
  vpc_id      = aws_vpc.us.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name   = "primary-us-east-1-alb-sg"
    Region = "us-east-1"
  }
}

resource "aws_lb" "us" {
  name               = "primary-us-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.us.id]
  subnets            = [aws_subnet.us_a.id, aws_subnet.us_b.id]

  depends_on = [
    aws_route_table_association.us_a,
    aws_route_table_association.us_b,
  ]

  tags = {
    Name   = "primary-us-east-1-alb"
    Region = "us-east-1"
  }
}

resource "aws_lb_target_group" "us" {
  name     = "primary-us-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.us.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name   = "primary-us-east-1-tg"
    Region = "us-east-1"
  }
}

resource "aws_lb_listener" "us" {
  load_balancer_arn = aws_lb.us.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# -----------------------------------------------------------------------------
# eu-central-1 networking (aliased provider aws.eu)
# -----------------------------------------------------------------------------
resource "aws_vpc" "eu" {
  provider             = aws.eu
  cidr_block           = "10.1.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = "primary-eu-central-1"
