}

resource "aws_route_table_association" "eu_b" {
  provider       = aws.eu
  subnet_id      = aws_subnet.eu_b.id
  route_table_id = aws_route_table.eu.id
}

resource "aws_security_group" "eu" {
  provider    = aws.eu
  name        = "primary-eu-central-1-alb-sg"
  description = "Allow HTTP and HTTPS ingress to the eu-central-1 routing-policy endpoint"
  vpc_id      = aws_vpc.eu.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name   = "primary-eu-central-1-alb-sg"
    Region = "eu-central-1"
  }
}

resource "aws_lb" "eu" {
  provider           = aws.eu
  name               = "primary-eu-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.eu.id]
  subnets            = [aws_subnet.eu_a.id, aws_subnet.eu_b.id]

  depends_on = [
    aws_route_table_association.eu_a,
    aws_route_table_association.eu_b,
  ]

  tags = {
    Name   = "primary-eu-central-1-alb"
    Region = "eu-central-1"
  }
}

resource "aws_lb_target_group" "eu" {
  provider = aws.eu
  name     = "primary-eu-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.eu.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name   = "primary-eu-central-1-tg"
    Region = "eu-central-1"
  }
}

resource "aws_lb_listener" "eu" {
  provider          = aws.eu
  load_balancer_arn = aws_lb.eu.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# -----------------------------------------------------------------------------
# Route 53 health checks and latency-based routing records
# -----------------------------------------------------------------------------
resource "aws_route53_health_check" "us_east_1" {
  fqdn              = aws_lb.us.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 10
  measure_latency   = true

  tags = {
    Name   = "primary-us-east-1-health-check"
    Region = "us-east-1"
  }
}

resource "aws_route53_health_check" "eu_central_1" {
  fqdn              = aws_lb.eu.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  failure_threshold = 3
  request_interval  = 10
  measure_latency   = true

  tags = {
    Name   = "primary-eu-central-1-health-check"
    Region = "eu-central-1"
  }
}

resource "aws_route53_record" "primary_us_east_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "us-east-1"
  health_check_id = aws_route53_health_check.us_east_1.id

  latency_routing_policy {
    region = "us-east-1"
  }

  alias {
    name                   = aws_lb.us.dns_name
    zone_id                = aws_lb.us.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "primary_eu_central_1" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = local.record_fqdn
  type    = "A"

  set_identifier  = "eu-central-1"
  health_check_id = aws_route53_health_check.eu_central_1.id

  latency_routing_policy {
    region = "eu-central-1"
  }

  alias {
    name                   = aws_lb.eu.dns_name
    zone_id                = aws_lb.eu.zone_id
    evaluate_target_health = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "hosted_zone_name_servers" {
  description = "Name servers for the primary hosted zone (use these for registrar delegation)."
  value       = aws_route53_zone.primary.name_servers
}

output "record_fqdn" {
  description = "Fully qualified name of the latency-routed record."
  value       = local.record_fqdn
}

output "us_east_1_endpoint_dns_name" {
  description = "DNS name of the us-east-1 ALB endpoint."
  value       = aws_lb.us.dns_name
}

output "eu_central_1_endpoint_dns_name" {
  description = "DNS name of the eu-central-1 ALB endpoint."
  value       = aws_lb.eu.dns_name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "parent_domain" {
  description = "Parent domain name used for the Route 53 public hosted zone (e.g. example.com)."
  type        = string
  default     = "example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  common_tags = {
    Project   = "route53-geolocation-routing"
    ManagedBy = "terraform"
  }
}

resource "aws_route53_zone" "primary" {
  name = var.parent_domain

  tags = merge(local.common_tags, {
    Name = "primary"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "geo-routing-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "geo-routing-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "geo-routing-public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "geo-routing-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "endpoints" {
  name        = "geo-routing-endpoints"
  description = "Web tier security group for the Route 53 geolocation endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (web tier)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere (web tier)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "geo-routing-endpoints"
  })
}

resource "aws_instance" "us_endpoint" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.endpoints.id]
  associate_public_ip_address = true

  user_data = <<-EOF
#!/bin/bash
dnf install -y httpd
echo "<h1>US geolocation endpoint</h1>" > /var/www/html/index.html
systemctl enable --now httpd
EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, {
    Name        = "us-endpoint"
    GeoLocation = "US"
  })
}

resource "aws_instance" "eu_endpoint" {
  ami                         = data.aws_ami.amazon_linux.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.endpoints.id]
  associate_public_ip_address = true

  user_data = <<-EOF
#!/bin/bash
dnf install -y httpd
echo "<h1>EU geolocation endpoint</h1>" > /var/www/html/index.html
systemctl enable --now httpd
EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, {
    Name        = "eu-endpoint"
    GeoLocation = "EU"
  })
}

resource "aws_eip" "us_endpoint" {
  domain   = "vpc"
  instance = aws_instance.us_endpoint.id

  tags = merge(local.common_tags, {
    Name = "us-endpoint-eip"
  })
}

resource "aws_eip" "eu_endpoint" {
  domain   = "vpc"
  instance = aws_instance.eu_endpoint.id

  tags = merge(local.common_tags, {
    Name = "eu-endpoint-eip"
  })
}

resource "aws_route53_health_check" "us" {
  ip_address        = aws_eip.us_endpoint.public_ip
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "us-endpoint-health-check"
  })
}

resource "aws_route53_health_check" "eu" {
  ip_address        = aws_eip.eu_endpoint.public_ip
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = merge(local.common_tags, {
    Name = "eu-endpoint-health-check"
  })
}

resource "aws_route53_record" "us" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.us_endpoint.public_ip]
  set_identifier  = "us"
  health_check_id = aws_route53_health_check.us.id

  geolocation_routing_policy {
    continent = "US"
  }
}

resource "aws_route53_record" "eu" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.eu_endpoint.public_ip]
  set_identifier  = "eu"
  health_check_id = aws_route53_health_check.eu.id

  geolocation_routing_policy {
    continent = "EU"
  }
}

resource "aws_route53_record" "default" {
  zone_id = aws_route53_zone.primary.zone_id
  name    = aws_route53_zone.primary.name
  type    = "A"
  ttl     = 60

  records         = [aws_eip.us_endpoint.public_ip]
  set_identifier  = "default"
  health_check_id = aws_route53_health_check.us.id

  geolocation_routing_policy {
    country = "*"
  }
}

output "hosted_zone_id" {
  description = "Hosted zone ID of the primary Route 53 public hosted zone."
  value       = aws_route53_zone.primary.zone_id
}

output "hosted_zone_name_servers" {
  description = "Name servers assigned to the primary hosted zone."
  value       = aws_route53_zone.primary.name_servers
}

output "us_record_fqdn" {
  description = "FQDN of the US geolocation A record."
  value       = aws_route53_record.us.name
}

output "eu_record_fqdn" {
  description = "FQDN of the EU geolocation A record."
  value       = aws_route53_record.eu.name
}

output "default_record_fqdn" {
  description = "FQDN of the default (catch-all) geolocation A record."
  value       = aws_route53_record.default.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "domain_name" {
  description = "The DNS zone name used for the Route 53 public hosted zone."
  type        = string
  default     = "example.com"
}

variable "tags" {
  description = "Tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "greenfield"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Pure metadata lookups (static provider data only, no pre-existing infrastructure)
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = var.tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = var.tags
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = var.tags
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = var.tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = var.tags
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# Security groups
# ------------------------------------------------------------------------------

resource "aws_security_group" "alb_sg" {
  name        = "web-alb-sg"
  description = "Public ALB security group: inbound HTTP/HTTPS from the internet only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

resource "aws_security_group" "instance_sg" {
  name        = "web-instance-sg"
  description = "Web server security group: inbound HTTP from the ALB security group only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Web servers (one per ALB target group)
# ------------------------------------------------------------------------------

resource "aws_instance" "primary" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_a.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo '<h1>Primary endpoint</h1>' > /var/www/html/index.html
  EOF

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

resource "aws_instance" "secondary" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_b.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.instance_sg.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo '<h1>Secondary endpoint</h1>' > /var/www/html/index.html
  EOF

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Load balancers (primary and secondary failover endpoints)
# ------------------------------------------------------------------------------

resource "aws_lb_target_group" "primary" {
  name                 = "primary-web-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = var.tags
}

resource "aws_lb_target_group" "secondary" {
  name                 = "secondary-web-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = var.tags
}

resource "aws_lb_target_group_attachment" "primary" {
  target_group_arn = aws_lb_target_group.primary.arn
  target_id        = aws_instance.primary.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "secondary" {
  target_group_arn = aws_lb_target_group.secondary.arn
  target_id        = aws_instance.secondary.id
  port             = 80
}

resource "aws_lb" "primary" {
  name                       = "primary-web-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = var.tags
}

resource "aws_lb" "secondary" {
  name                       = "secondary-web-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = var.tags
}

resource "aws_lb_listener" "primary" {
  load_balancer_arn = aws_lb.primary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.primary.arn
  }

  tags = var.tags
}

resource "aws_lb_listener" "secondary" {
  load_balancer_arn = aws_lb.secondary.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.secondary.arn
  }

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Route 53 hosted zone and health checks
# ------------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }

  tags = var.tags
}

resource "aws_route53_health_check" "primary" {
  fqdn              = aws_lb.primary.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = var.tags
}

resource "aws_route53_health_check" "secondary" {
  fqdn              = aws_lb.secondary.dns_name
  port              = 80
  type              = "HTTP"
  resource_path     = "/"
  request_interval  = 30
  failure_threshold = 3

  tags = var.tags
}

# ------------------------------------------------------------------------------
# Route 53 traffic policy: failover from the primary ALB to the secondary ALB
# ------------------------------------------------------------------------------

resource "aws_route53_traffic_policy" "failover" {
  name = "www-failover-policy"

  document = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Resources = {
      failover_rule_block = {
        Type = "AWS::Route53::TrafficPolicyVersion"
        Properties = {
          RecordType = "A"
          StartRule = {
            RuleName = "primary_secondary_failover"
          }
          Rules = {
            primary_secondary_failover = {
              Type = "failover"
              Primary = {
                EndpointName = "primary_alb_endpoint"
              }
              Secondary = {
                EndpointName = "secondary_alb_endpoint"
              }
            }
          }
          Endpoints = {
            primary_alb_endpoint = {
              Type        = "endpoint"
              Value       = aws_lb.primary.dns_name
              HealthCheck = aws_route53_health_check.primary.id
            }
            secondary_alb_endpoint = {
              Type        = "endpoint"
              Value       = aws_lb.secondary.dns_name
              HealthCheck = aws_route53_health_check.secondary.id
            }
          }
        }
      }
    }
  })
}

resource "aws_route53_traffic_policy_instance" "www_failover" {
  name                   = "www.${var.domain_name}"
  hosted_zone_id         = aws_route53_zone.main.zone_id
  traffic_policy_id      = aws_route53_traffic_policy.failover.id
  traffic_policy_version = aws_route53_traffic_policy.failover.version
  ttl                    = 60

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "zone_name_servers" {
  description = "The authoritative name servers assigned to the public hosted zone."
  value       = aws_route53_zone.main.name_servers
}

output "www_failover_record_name" {
  description = "The DNS name of the traffic policy instance record (www.<domain_name>)."
  value       = aws_route53_traffic_policy_instance.www_failover.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster and base name for all related resources"
  type        = string
  default     = "greenfield-eks-cluster"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Name        = var.cluster_name
    Environment = "greenfield"
    ManagedBy   = "terraform"
  }

  eks_subnet_tags = {
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                    = "1"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-igw"
    }
  )
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    local.eks_subnet_tags,
    {
      Name = "${var.cluster_name}-public-${count.index + 1}"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_iam_role" "eks_cluster" {
  name = "${var.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.cluster_name}-cluster-role"
    }
  )
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.public[*].id
    endpoint_public_access  = true
    endpoint_private_access = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_service_policy,
  ]

  provisioner "local-exec" {
    command = "aws eks update-kubeconfig --region us-east-1 --name ${var.cluster_name}"
  }

  provisioner "local-exec" {
    when = destroy
    command = <<-EOT
      kubectl config delete-cluster ${self.name} || true
      kubectl config delete-context ${self.name} || true
    EOT
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.cluster_name
    }
  )
}

output "cluster_name" {
  description = "Name of the EKS cluster"
  value       = aws_eks_cluster.main.name
}

output "cluster_endpoint" {
  description = "API server endpoint of the EKS cluster"
  value       = aws_eks_cluster.main.endpoint
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "Name of the EKS cluster."
  type        = string
  default     = "eks-cluster-1"

  validation {
    condition     = length(trimspace(var.cluster_name)) > 0
    error_message = "cluster_name must not be empty."
  }
}

variable "kubernetes_version" {
  description = "Kubernetes version for the EKS cluster control plane."
  type        = string
  default     = "1.30"

  validation {
    condition     = can(regex("^1\\.[0-9]{2}$", var.kubernetes_version))
    error_message = "kubernetes_version must be a valid Kubernetes minor version, e.g. \"1.30\"."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the EKS VPC."
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
}

# ------------------------------------------------------------------------------
# Networking foundation
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                                        = "${var.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/role/elb"                    = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                        = "${var.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb"           = "1"
    "kubernetes.io/cluster/${var.cluster_name}" = "shared"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.cluster_name}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.cluster_name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-public-rt"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${var.cluster_name}-private-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Cluster endpoint security group
# ------------------------------------------------------------------------------

resource "aws_security_group" "cluster_endpoint" {
  name        = "${var.cluster_name}-cluster-endpoint-sg"
  description = "Restrict HTTPS (443) access to the ${var.cluster_name} EKS cluster endpoint to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound so the control plane can respond"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${var.cluster_name}-cluster-endpoint-sg"
  }
}

# ------------------------------------------------------------------------------
# IAM
# ------------------------------------------------------------------------------

resource "aws_iam_role" "eks_cluster_1" {
  name = "eks-cluster-1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eks-cluster-1"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_1.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

# ------------------------------------------------------------------------------
# EKS cluster
# ------------------------------------------------------------------------------

resource "aws_eks_cluster" "main" {
  name     = var.cluster_name
  version  = var.kubernetes_version
  role_arn = aws_iam_role.eks_cluster_1.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.private[*].id, aws_subnet.public[*].id)
    security_group_ids      = [aws_security_group.cluster_endpoint.id]
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  tags = {
    Name = var.cluster_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = aws_eks_cluster.main.name
}

output "cluster_endpoint" {
  description = "Endpoint for the EKS Kubernetes API server."
  value       = aws_eks_cluster.main.endpoint
}

output "cluster_certificate_authority_data" {
  description = "Base64-encoded certificate authority data for the EKS cluster."
  value       = aws_eks_cluster.main.certificate_authority[0].data
}

###############################################################################
# Terraform + Providers
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    helm = {
      source  = "hashicorp/helm"
      version = "~> 2.12"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = "~> 2.30"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

###############################################################################
# Variables
###############################################################################

variable "enable_ecr_image_lookup" {
  description = "Whether to look up the image tagged 'stable' in the application ECR repository. Disabled by default because a freshly created greenfield repository contains no images yet."
  type        = bool
  default     = false
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster."
  type        = string
  default     = "1.31"
}

variable "node_instance_types" {
  description = "EC2 instance types used by the EKS managed node group."
  type        = list(string)
  default     = ["t3.medium"]
}

variable "node_group_desired_size" {
  description = "Desired number of worker nodes."
  type        = number
  default     = 2

  validation {
    condition     = var.node_group_desired_size >= 1
    error_message = "The node group desired size must be at least 1."
  }
}

variable "node_group_min_size" {
  description = "Minimum number of worker nodes."
  type        = number
  default     = 2

  validation {
    condition     = var.node_group_min_size >= 1
    error_message = "The node group minimum size must be at least 1."
  }
}

variable "node_group_max_size" {
  description = "Maximum number of worker nodes."
  type        = number
  default     = 4

  validation {
    condition     = var.node_group_max_size >= 1
    error_message = "The node group maximum size must be at least 1."
  }
}

variable "eks_endpoint_public_access_cidrs" {
  description = "CIDR blocks allowed to reach the public EKS API endpoint. Must be restricted; 0.0.0.0/0 is deliberately rejected."
  type        = list(string)
  default     = ["10.0.0.0/8"]

  validation {
    condition     = !contains(var.eks_endpoint_public_access_cidrs, "0.0.0.0/0")
    error_message = "The EKS public endpoint must not be open to 0.0.0.0/0; provide a restricted CIDR list."
  }
}

###############################################################################
# Static lookups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  workspace_name = terraform.workspace
  cluster_name   = "eks-${local.workspace_name}"

  # The ECR lookup is keyed strictly by the "stable" tag (tags map to exactly
  # one image digest), so the resolved tag is deterministically "stable" in
  # both branches. The lookup's real value is confirming the image exists and
  # exposing its digest/URI via the app_image_digest output.
  image_tag = "stable"

  common_tags = {
    Project     = "eks-platform"
    Environment = local.workspace_name
    ManagedBy   = "terraform"
  }

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.11.0/24", "10.0.12.0/24"]
  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]
}

###############################################################################
# KMS keys (cluster secrets encryption + ECR image encryption)
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "EKS ${local.cluster_name} Kubernetes secrets envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-secrets" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/${local.cluster_name}-secrets"
  target_key_id = aws_kms_key.eks.key_id
}

resource "aws_kms_key" "ecr" {
  description             = "ECR image encryption for the ${local.cluster_name} application repository"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-ecr" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ecr" {
  name          = "alias/${local.cluster_name}-ecr"
  target_key_id = aws_kms_key.ecr.key_id
}

###############################################################################
# ECR repository (created here — greenfield) + optional image lookup
###############################################################################

resource "aws_ecr_repository" "app" {
  name                 = "${local.cluster_name}-app"
  image_tag_mutability = "MUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
    kms_key         = aws_kms_key.ecr.arn
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-app" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "app" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

data "aws_ecr_image" "stable" {
  count = var.enable_ecr_image_lookup ? 1 : 0

  repository_name = aws_ecr_repository.app.name
  image_tag       = "stable"

  depends_on = [aws_ecr_repository.app]
}

###############################################################################
# Networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-vpc"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    },
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-igw" })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-public-${format("%02d", count.index + 1)}"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/elb"                      = "1"
    },
  )
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    {
      Name                                          = "${local.cluster_name}-private-${format("%02d", count.index + 1)}"
      "kubernetes.io/cluster/${local.cluster_name}" = "shared"
      "kubernetes.io/role/internal-elb"             = "1"
    },
  )
}

resource "aws_eip" "nat" {
  count = length(local.private_subnet_cidrs)

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-nat-${format("%02d", count.index + 1)}" })
}

resource "aws_nat_gateway" "main" {
  count = length(local.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-nat-${format("%02d", count.index + 1)}" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-public" })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, { Name = "${local.cluster_name}-private-${format("%02d", count.index + 1)}" })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# IAM — cluster role, node role, least-privilege ECR pull policy
###############################################################################

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEKSToAssumeClusterRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "${local.cluster_name}-cluster-role"
  description        = "IAM role assumed by the ${local.cluster_name} EKS control plane"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeNodeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = "${local.cluster_name}-node-role"
  description        = "IAM role assumed by ${local.cluster_name} managed worker nodes"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "node_worker_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_node.name
}

data "aws_iam_policy_document" "node_ecr_pull" {
  statement {
    sid       = "GetECRAuthorizationToken"
    effect    = "Allow"
    actions   = ["ecr:GetAuthorizationToken"]
    resources = ["*"]
  }

  statement {
    sid    = "PullImagesFromApplicationRepository"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
    ]
    resources = [aws_ecr_repository.app.arn]
  }

  statement {
    sid       = "DecryptKmsEncryptedImages"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.ecr.arn]
  }
}

resource "aws_iam_policy" "node_ecr_pull" {
  name        = "${local.cluster_name}-ecr-pull"
  description = "Least-privilege image pull access scoped to the ${local.cluster_name} application repository"
  policy      = data.aws_iam_policy_document.node_ecr_pull.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "node_ecr_pull" {
  policy_arn = aws_iam_policy.node_ecr_pull.arn
  role       = aws_iam_role.eks_node.name
}

###############################################################################
# EKS cluster
###############################################################################

module "eks" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 20.0"

  cluster_name    = local.cluster_name
  cluster_version = var.cluster_version

  vpc_id                   = aws_vpc.main.id
  subnet_ids               = aws_subnet.private[*].id
  control_plane_subnet_ids = aws_subnet.private[*].id

  cluster_endpoint_private_access      = true
  cluster_endpoint_public_access       = true
  cluster_endpoint_public_access_cidrs = var.eks_endpoint_public_access_cidrs

  enable_irsa = true

  authentication_mode                      = "API_AND_CONFIG_MAP"
  enable_cluster_creator_admin_permissions = true

  create_kms_key = false

  cluster_encryption_config = {
    provider_key_arn = aws_kms_key.eks.arn
    resources        = ["secrets"]
  }

  cluster_enabled_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  create_iam_role = false
  iam_role_arn    = aws_iam_role.eks_cluster.arn

  cluster_addons = {
    vpc-cni = {
      most_recent    = true
      before_compute = true
    }
    coredns = {
      most_recent = true
    }
    kube-proxy = {
      most_recent = true
    }
  }

  eks_managed_node_group_defaults = {
    create_iam_role = false
    iam_role_arn    = aws_iam_role.eks_node.arn
    instance_types  = var.node_instance_types

    metadata_options = {
      http_endpoint = "enabled"
      http_tokens   = "required"
    }

    block_device_mappings = {
      xvda = {
        device_name = "/dev/xvda"
        ebs = {
          volume_size           = 50
          volume_type           = "gp3"
          encrypted             = true
          delete_on_termination = true
        }
      }
    }
  }

  eks_managed_node_groups = {
    general = {
      name         = "${local.cluster_name}-general"
      desired_size = var.node_group_desired_size
      min_size     = var.node_group_min_size
      max_size     = var.node_group_max_size
      subnet_ids   = aws_subnet.private[*].id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.node_worker_policy,
    aws_iam_role_policy_attachment.node_cni_policy,
    aws_iam_role_policy_attachment.node_ecr_pull,
    aws_route_table_association.public,
    aws_route_table_association.private,
  ]
}

###############################################################################
# Post-provision cluster data sources (explicit depends_on avoids the
# authentication-token race on first apply)
###############################################################################

data "aws_eks_cluster" "main" {
  name = module.eks.cluster_name

  depends_on = [module.eks]
}

data "aws_eks_cluster_auth" "main" {
  name = module.eks.cluster_name

  depends_on = [module.eks]
}

###############################################################################
# Kubernetes + Helm providers for cluster communication
###############################################################################

provider "kubernetes" {
  host                   = data.aws_eks_cluster.main.endpoint
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.main.certificate_authority[0].data)
  token                  = data.aws_eks_cluster_auth.main.token
}

provider "helm" {
  load_config_file = false

  kubernetes {
    host                   = data.aws_eks_cluster.main.endpoint
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.main.certificate_authority[0].data)
    token                  = data.aws_eks_cluster_auth.main.token
  }
}

###############################################################################
# Outputs
###############################################################################

output "cluster_name" {
  description = "Name of the EKS cluster."
  value       = module.eks.cluster_name
}

output "cluster_endpoint" {
  description = "Endpoint of the EKS Kubernetes API server."
  value       = module.eks.cluster_endpoint
}

output "app_image_tag" {
  description = "Application image tag deployed from the ECR repository."
  value       = local.image_tag
}

output "app_image_digest" {
  description = "Digest of the fetched 'stable' image, or null when the image lookup is disabled."
  value       = var.enable_ecr_image_lookup ? data.aws_ecr_image.stable[0].image_digest : null
}

output "ecr_repository_url" {
  description = "URL of the application ECR repository."
  value       = aws_ecr_repository.app.repository_url
}

output "ecr_registry_url" {
  description = "ECR registry endpoint for the current AWS account."
  value       = "${data.aws_caller_identity.current.account_id}.dkr.ecr.${data.aws_region.current.name}.amazonaws.com"
}

output "configure_kubectl" {
  description = "Command to configure kubectl for this cluster."
  value       = "aws eks update-kubeconfig --region ${data.aws_region.current.name} --name ${module.eks.cluster_name}"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_name    = "eks-fargate-cluster"
  vpc_cidr        = "10.0.0.0/16"
  public_subnets  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnets = ["10.0.11.0/24", "10.0.12.0/24"]
  az_count        = 2
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.cluster_name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.cluster_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = {
    Name                                          = "${local.cluster_name}-public-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"                      = "1"
  }
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name                                          = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb"             = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.cluster_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = local.az_count
  domain = "vpc"

  tags = {
    Name = "${local.cluster_name}-nat-eip-${count.index + 1}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = local.az_count
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${local.cluster_name}-nat-${count.index + 1}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count  = local.az_count
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = {
    Name = "${local.cluster_name}-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_iam_role" "eks_cluster" {
  name = "${local.cluster_name}-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEKSToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-cluster-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role" "eks_fargate_pod_execution" {
  name = "${local.cluster_name}-fargate-pod-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEksFargatePodsToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "eks-fargate-pods.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "${local.cluster_name}-fargate-pod-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "eks_fargate_pod_execution_policy" {
  role       = aws_iam_role.eks_fargate_pod_execution.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSFargatePodExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_fargate_pod_execution_ecr_readonly" {
  role       = aws_iam_role.eks_fargate_pod_execution.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = concat(aws_subnet.private[*].id, aws_subnet.public[*].id)
    endpoint_private_access = true
    endpoint_public_access  = true
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.cluster_name
  }
}

resource "aws_eks_fargate_profile" "kube_system" {
  cluster_name           = aws_eks_cluster.main.name
  fargate_profile_name   = "kube-system"
  pod_execution_role_arn = aws_iam_role.eks_fargate_pod_execution.arn
  subnet_ids             = aws_subnet.private[*].id

  selector {
    namespace = "kube-system"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_fargate_pod_execution_policy,
    aws_iam_role_policy_attachment.eks_fargate_pod_execution_ecr_readonly,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_eks_cluster_auth" "main" {
  name = aws_eks_cluster.main.name
}

resource "null_resource" "coredns_fargate_patch" {
  triggers = {
    cluster_endpoint = aws_eks_cluster.main.endpoint
    cluster_ca       = aws_eks_cluster.main.certificate_authority[0].data
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]

    command = <<-EOT
      kubectl \
        --server ${aws_eks_cluster.main.endpoint} \
        --certificate-authority <(echo '${aws_eks_cluster.main.certificate_authority[0].data}' | base64 --decode) \
        --token ${data.aws_eks_cluster_auth.main.token} \
        patch deployment coredns \
        --namespace kube-system \
        --type json \
        --patch='[{"op": "remove", "path": "/metadata/annotations/eks.amazonaws.com~1compute-type"}]'
    EOT
  }

  depends_on = [aws_eks_fargate_profile.kube_system]
}

terraform {
  required_version = ">= 1.5"

