terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix for the S3 bucket name. The AWS account ID is appended to guarantee a globally unique bucket name so terraform apply runs unattended."
  type        = string
  default     = "terraform-s3-kms-sse-encrypted-bucket"
}

data "aws_caller_identity" "current" {}

locals {
  bucket_name = "${var.bucket_name_prefix}-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    ManagedBy   = "terraform"
    Project     = "s3-kms-server-side-encryption"
    Environment = "production"
  }
}

# KMS key used for S3 server-side encryption
resource "aws_kms_key" "s3_bucket_encryption_key" {
  description             = "S3 bucket server-side encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "s3-bucket-server-side-encryption-key"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Friendly alias for the KMS key
resource "aws_kms_alias" "s3_bucket_encryption_key" {
  name          = "alias/s3-bucket-server-side-encryption-key"
  target_key_id = aws_kms_key.s3_bucket_encryption_key.key_id
}

# S3 bucket protected by the KMS key
resource "aws_s3_bucket" "encrypted_bucket" {
  bucket = local.bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.bucket_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Block all public access to the bucket
resource "aws_s3_bucket_public_access_block" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Disable ACLs in favor of object ownership enforcement
resource "aws_s3_bucket_ownership_controls" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Enable versioning for the stateful bucket
resource "aws_s3_bucket_versioning" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption using the KMS key with the aws:kms algorithm
resource "aws_s3_bucket_server_side_encryption_configuration" "encrypted_bucket" {
  bucket = aws_s3_bucket.encrypted_bucket.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_bucket_encryption_key.arn
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique, lowercase, DNS-compliant name for the private S3 bucket."
  type        = string
  default     = "terraform-private-s3-bucket-example-001"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_owner_principal_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowBucketOwnerListBucket"
        Effect    = "Allow"
        Principal = {
          AWS = local.bucket_owner_principal_arn
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.this.arn
      },
      {
        Sid       = "AllowBucketOwnerGetObject"
        Effect    = "Allow"
        Principal = {
          AWS = local.bucket_owner_principal_arn
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.this.arn}/*"
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [
    aws_s3_bucket_ownership_controls.this
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name_prefix" {
  description = "Prefix used to derive the globally unique names of the S3 buckets."
  type        = string
  default     = "tf-s3-access-logs"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,48}[a-z0-9]$", var.bucket_name_prefix))
    error_message = "Prefix must be 3-50 lowercase alphanumeric characters or hyphens, starting and ending with an alphanumeric character."
  }
}

locals {
  app_bucket_name = "${var.bucket_name_prefix}-app-${random_string.bucket_suffix.result}"
  log_bucket_name = "${var.bucket_name_prefix}-logs-${random_string.bucket_suffix.result}"
  log_file_prefix = "app-logs/"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
  upper   = false
  lower   = true
  numeric = true
}

# -----------------------------------------------------------------------------
# Source bucket (private) - the bucket whose server access logs are delivered
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "app_bucket" {
  bucket = local.app_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

# "Private" ACL requirement implemented via BucketOwnerEnforced ownership
# controls: ACLs are disabled entirely, so no ACL grants (public or otherwise)
# can exist. Combined with the public access block below, the bucket is fully
# private without the deprecated aws_s3_bucket_acl resource.
resource "aws_s3_bucket_ownership_controls" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# Destination bucket (log-delivery-write) - receives the app bucket's logs
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "log_bucket" {
  bucket = local.log_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# "Log-delivery-write" ACL requirement implemented as a least-privilege bucket
# policy granting the S3 log delivery service principal only the permissions
# it needs, constrained to writes originating from the app bucket and carrying
# the bucket-owner-full-control canned ACL.
resource "aws_s3_bucket_policy" "log_bucket" {
  bucket = aws_s3_bucket.log_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3LogDeliveryAclCheck"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.log_bucket.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.app_bucket.arn
          }
        }
      },
      {
        Sid       = "S3LogDeliveryWrite"
        Effect    = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.app_bucket.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Server access logging: app_bucket delivers its logs into log_bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket_logging" "app_bucket" {
  bucket = aws_s3_bucket.app_bucket.id

  target_bucket = aws_s3_bucket.log_bucket.id
  target_prefix = local.log_file_prefix

  depends_on = [
    aws_s3_bucket_policy.log_bucket,
    aws_s3_bucket_ownership_controls.app_bucket,
    aws_s3_bucket_ownership_controls.log_bucket,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Globally-unique bucket name
# S3 bucket names allow only lowercase letters, digits, and hyphens
# (underscores are illegal), so "your_bucket_name" becomes "your-bucket-name"
# with a random suffix to guarantee global uniqueness.
# ---------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  bucket_name = "your-bucket-name-${random_id.bucket_suffix.hex}"
}

# ---------------------------------------------------------------------------
# S3 bucket (stateful resource — protected from destruction)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket = local.bucket_name

  tags = {
    Name      = local.bucket_name
    ManagedBy = "terraform"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# ---------------------------------------------------------------------------
# Object upload
# NOTE: "path/to/file" must exist on disk (relative to the configuration
# directory) before plan/apply runs; contents are never inlined as plaintext.
# ---------------------------------------------------------------------------
resource "aws_s3_object" "object" {
  bucket = aws_s3_bucket.main.id
  key    = "new_object_key"
  source = "path/to/file"

  depends_on = [
    aws_s3_bucket_public_access_block.main,
    aws_s3_bucket_server_side_encryption_configuration.main,
    aws_s3_bucket_versioning.main,
    aws_s3_bucket_ownership_controls.main,
  ]
}

