provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  fleet_instance_name = "${var.environment}-fleet-instance"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.environment}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-igw" })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${var.environment}-public-subnet" })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${var.environment}-private-subnet" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${var.environment}-nat-eip" })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, { Name = "${var.environment}-nat-gw" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-private-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_iam_role" "ec2_fleet_role" {
  name_prefix = "ec2-fleet-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet-role" })
}

resource "aws_iam_role_policy_attachment" "ec2_fleet_ssm" {
  role       = aws_iam_role.ec2_fleet_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2_fleet_profile" {
  name_prefix = "ec2-fleet-profile-"
  role        = aws_iam_role.ec2_fleet_role.name

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet-profile" })

  depends_on = [aws_iam_role_policy_attachment.ec2_fleet_ssm]
}

resource "aws_security_group" "fleet_sg" {
  name_prefix = "ec2-fleet-sg-"
  description = "Security group for the EC2 Fleet instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-fleet-sg" })
}

resource "aws_launch_template" "on_demand" {
  name_prefix   = "fleet-on-demand-"
  description   = "On-Demand launch template for the EC2 Fleet"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.medium"
  ebs_optimized = true

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  network_interfaces {
    associate_public_ip_address = false
    security_groups             = [aws_security_group.fleet_sg.id]
    device_index                = 0
    delete_on_termination       = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, { Name = local.fleet_instance_name })
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-on-demand-launch-template" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_launch_template" "spot" {
  name_prefix   = "fleet-spot-"
  description   = "Spot launch template for the EC2 Fleet"
  image_id      = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.medium"
  ebs_optimized = true

  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_profile.name
  }

  network_interfaces {
    associate_public_ip_address = false
    security_groups             = [aws_security_group.fleet_sg.id]
    device_index                = 0
    delete_on_termination       = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  instance_market_options {
    market_type = "spot"
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, { Name = local.fleet_instance_name })
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-spot-launch-template" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_ec2_fleet" "main" {
  type = "maintain"

  target_capacity_specification {
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
    default_target_capacity_type = "on-demand"
  }

  on_demand_options {
    allocation_strategy = "prioritized"
  }

  spot_options {
    allocation_strategy         = "capacity-optimized"
    instance_pools_to_use_count = 2
  }

  replace_unhealthy_instances         = true
  terminate_instances                 = true
  terminate_instances_with_expiration = true

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.on_demand.id
      version            = aws_launch_template.on_demand.latest_version
    }

    override {
      instance_type = "t3.medium"
      priority      = 1
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3.large"
      priority      = 2
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.medium"
      priority      = 3
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.large"
      priority      = 4
      subnet_id     = aws_subnet.private.id
    }
  }

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.spot.id
      version            = aws_launch_template.spot.latest_version
    }

    override {
      instance_type = "t3.medium"
      priority      = 5
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3.large"
      priority      = 6
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.medium"
      priority      = 7
      subnet_id     = aws_subnet.private.id
    }

    override {
      instance_type = "t3a.large"
      priority      = 8
      subnet_id     = aws_subnet.private.id
    }
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-ec2-fleet" })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (no dependency on pre-existing resources)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking: VPC, internet gateway, subnets, NAT, routing
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "three-tier-web-vpc"
    Tier = "web"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "three-tier-web-igw"
    Tier = "web"
  })
}

# Public subnet (web tier) in the first available AZ
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "three-tier-web-public-subnet"
    Tier = "web"
  })
}

# Private subnet (application tier) in the first available AZ
resource "aws_subnet" "app" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.11.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "three-tier-app-private-subnet"
    Tier = "app"
  })
}

# Private subnet (database tier) in the second available AZ
resource "aws_subnet" "db" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.12.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "three-tier-db-private-subnet"
    Tier = "database"
  })
}

# EIP + NAT gateway so private tiers can reach the internet for
# patches/updates with zero inbound exposure
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "three-tier-web-nat-eip"
    Tier = "web"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "three-tier-web-nat-gateway"
    Tier = "web"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-public-rt"
    Tier = "web"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-private-rt"
    Tier = "app"
  })
}

resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups (least privilege, tier-to-tier references only)
# ---------------------------------------------------------------------------
resource "aws_security_group" "web" {
  name        = "three-tier-web-sg"
  description = "Web tier: HTTP and HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-sg"
    Tier = "web"
  })
}

resource "aws_security_group" "app" {
  name        = "three-tier-app-sg"
  description = "Application tier: port 8080 from the web tier only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from web tier only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-sg"
    Tier = "app"
  })
}

resource "aws_security_group" "rds" {
  name        = "three-tier-db-sg"
  description = "Database tier: MySQL from the application tier only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from app tier only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-db-sg"
    Tier = "database"
  })
}

# ---------------------------------------------------------------------------
# IAM: SSM Session Manager access (no SSH key pairs required)
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2_ssm" {
  name = "three-tier-ec2-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "three-tier-ec2-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "three-tier-ec2-instance-profile"
  role = aws_iam_role.ec2_ssm.name
}

# ---------------------------------------------------------------------------
# Web tier EC2 (public subnet, nginx)
# ---------------------------------------------------------------------------
resource "aws_instance" "web" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.web.id]
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  depends_on = [aws_iam_role_policy_attachment.ec2_ssm]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y nginx
    systemctl enable nginx
    systemctl start nginx
    echo "<h1>three-tier-web: nginx is running</h1>" > /usr/share/nginx/html/index.html
  EOF

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-web-server"
    Tier = "web"
  })
}

# ---------------------------------------------------------------------------
# Application tier EC2 (private subnet, application on port 8080)
# ---------------------------------------------------------------------------
resource "aws_instance" "app" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.app.id
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.app.id]
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  depends_on = [aws_iam_role_policy_attachment.ec2_ssm]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y python3
    mkdir -p /opt/three-tier-app
    cat > /opt/three-tier-app/server.py <<'PYEOF'
    from http.server import BaseHTTPRequestHandler, HTTPServer
    import json

    class AppHandler(BaseHTTPRequestHandler):
        def do_GET(self):
            body = json.dumps({"service": "three-tier-app", "status": "healthy"}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

    HTTPServer(("0.0.0.0", 8080), AppHandler).serve_forever()
    PYEOF
    cat > /etc/systemd/system/three-tier-app.service <<'SVCEOF'
    [Unit]
    Description=Three-tier application server
    After=network-online.target

    [Service]
    Type=simple
    ExecStart=/usr/bin/python3 /opt/three-tier-app/server.py
    Restart=always
    User=ec2-user

    [Install]
    WantedBy=multi-user.target
    SVCEOF
    systemctl daemon-reload
    systemctl enable --now three-tier-app
  EOF

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "three-tier-app-server"
    Tier = "app"
  })
}

# ---------------------------------------------------------------------------
# Database tier: credentials, subnet group, RDS MySQL
# ---------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 4
}

# AWS requires subnets in at least two AZs for RDS; the database tier is
# logically hosted in the second private subnet (aws_subnet.db).
resource "aws_db_subnet_group" "main" {
  name       = "three-tier-db-subnet-group"
  subnet_ids = [aws_subnet.app.id, aws_subnet.db.id]

  tags = merge(local.common_tags, {
    Name = "three-tier-db-subnet-group"
    Tier = "database"
  })
}

resource "aws_db_instance" "main" {
  identifier     = "three-tier-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "threetierdb"
  username = "dbadmin"
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "three-tier-db-final-${random_id.db_final_snapshot.hex}"
  deletion_protection       = true

  tags = merge(local.common_tags, {
    Name = "three-tier-db"
    Tier = "database"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "three-tier-db-master-credentials"
  description = "Master credentials for the three-tier RDS MySQL database"

  tags = merge(local.common_tags, {
    Name = "three-tier-db-master-credentials"
    Tier = "database"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = aws_db_instance.main.username
    password = random_password.db_master.result
    engine   = aws_db_instance.main.engine
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all defaulted so `terraform apply` runs unattended)
###############################################################################

variable "project" {
  description = "Project name used as the prefix for resource names and tags."
  type        = string
  default     = "shared_storage"
}

variable "environment" {
  description = "Environment tag applied to every resource."
  type        = string
  default     = "dev"
}

variable "instance_type" {
  description = "EC2 instance type for the private application nodes."
  type        = string
  default     = "t3.micro"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

###############################################################################
# Data sources (pure static/well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  efs_mount_user_data = <<-EOT
    #!/bin/bash
    set -eux

    EFS_DNS_NAME="${aws_efs_file_system.shared.dns_name}"

    # Install the NFS client utilities required to mount EFS
    yum install -y nfs-utils

    # Create the shared EFS mount point
    mkdir -p /mnt/efs

    # Persist the EFS mount across reboots
    echo "$EFS_DNS_NAME:/ /mnt/efs nfs4 nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport,_netdev 0 0" >> /etc/fstab

    # Mount immediately, retrying while the mount target finishes provisioning
    attempt=1
    until mount -t nfs4 -o nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport "$EFS_DNS_NAME:/" /mnt/efs; do
      if [ "$attempt" -ge 30 ]; then
        echo "ERROR: failed to mount EFS after $attempt attempts" >&2
        exit 1
      fi
      attempt=$((attempt + 1))
      sleep 10
    done

    echo "EFS mounted successfully at /mnt/efs"
  EOT
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-igw"
  })
}

# Public subnet in the first AZ, hosting the NAT gateway only
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-a"
  })
}

# Private subnets, one per AZ, no auto-assign public IPs
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-b"
  })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.project}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.project}-main-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Private route table: outbound-only internet access through the NAT gateway
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups (standalone rules to avoid SG-to-SG reference cycles)
###############################################################################

# EC2 instances: no 0.0.0.0/0 ingress; private-only access via SSM
resource "aws_security_group" "ec2" {
  name        = "${var.project}-ec2-sg"
  description = "Security group for the private EC2 instances"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-ec2-sg"
  })
}

# EFS mount targets
resource "aws_security_group" "efs" {
  name        = "${var.project}-efs-sg"
  description = "Security group for the EFS mount targets"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-efs-sg"
  })
}

resource "aws_security_group_rule" "ec2_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.ec2.id
  description       = "Allow outbound HTTPS for package updates and SSM"
}

resource "aws_security_group_rule" "ec2_egress_http" {
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.ec2.id
  description       = "Allow outbound HTTP for package updates"
}

resource "aws_security_group_rule" "ec2_egress_nfs" {
  type                     = "egress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.efs.id
  security_group_id        = aws_security_group.ec2.id
  description              = "Allow NFS traffic to the EFS mount targets only"
}

# NFS 2049 ingress restricted to the EC2 instances' security group only
resource "aws_security_group_rule" "efs_ingress_nfs" {
  type                     = "ingress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.ec2.id
  security_group_id        = aws_security_group.efs.id
  description              = "Allow NFS from the EC2 instances only"
}

###############################################################################
# EFS shared storage
###############################################################################

resource "aws_efs_file_system" "shared" {
  creation_token   = "${var.project}-shared-efs"
  encrypted        = true
  performance_mode = "generalPurpose"

  tags = merge(local.common_tags, {
    Name = "${var.project}-shared-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# One mount target per private subnet so every instance has an in-AZ target
resource "aws_efs_mount_target" "private_a" {
  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = aws_subnet.private_a.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_mount_target" "private_b" {
  file_system_id  = aws_efs_file_system.shared.id
  subnet_id       = aws_subnet.private_b.id
  security_groups = [aws_security_group.efs.id]
}

###############################################################################
# IAM: keyless SSM management via instance profile
###############################################################################

resource "aws_iam_role" "ec2_ssm" {
  name = "${var.project}-ec2-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.project}-ec2-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ec2_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${var.project}-ec2-instance-profile"
  role = aws_iam_role.ec2_ssm.name

  depends_on = [aws_iam_role_policy_attachment.ssm_managed_instance_core]
}

###############################################################################
# EC2 instances (exactly 2, private subnets, one per AZ)
###############################################################################

resource "aws_instance" "node_a" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private_a.id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  user_data                   = base64encode(local.efs_mount_user_data)
  user_data_replace_on_change = true

  root_block_device {
    volume_type = "gp3"
    volume_size = 20
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-node-a"
  })

  depends_on = [aws_efs_mount_target.private_a]
}

resource "aws_instance" "node_b" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private_b.id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  user_data                   = base64encode(local.efs_mount_user_data)
  user_data_replace_on_change = true

  root_block_device {
    volume_type = "gp3"
    volume_size = 20
    encrypted   = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-node-b"
  })

  depends_on = [aws_efs_mount_target.private_b]
}

###############################################################################
# Outputs
###############################################################################

output "efs_file_system_id" {
  description = "ID of the shared EFS file system."
  value       = aws_efs_file_system.shared.id
}

output "efs_dns_name" {
  description = "DNS name of the shared EFS file system."
  value       = aws_efs_file_system.shared.dns_name
}

output "node_a_private_ip" {
  description = "Private IP address of the first EC2 instance."
  value       = aws_instance.node_a.private_ip
}

output "node_b_private_ip" {
  description = "Private IP address of the second EC2 instance."
  value       = aws_instance.node_b.private_ip
}

output "instance_private_ips" {
  description = "Private IP addresses of both EC2 instances."
  value       = [aws_instance.node_a.private_ip, aws_instance.node_b.private_ip]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the cluster nodes (must support cluster placement groups)."
  type        = string
  default     = "c5.large"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  name_prefix = "cluster_workload"

  public_subnet_cidrs  = [cidrsubnet(var.vpc_cidr, 8, 1), cidrsubnet(var.vpc_cidr, 8, 2)]
  private_subnet_cidrs = [cidrsubnet(var.vpc_cidr, 8, 101), cidrsubnet(var.vpc_cidr, 8, 102)]

  common_tags = {
    Project   = local.name_prefix
    ManagedBy = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_subnet_${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_subnet_${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_nat_eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_nat_gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_route_table"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_route_table"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_placement_group" "cluster" {
  name     = "${local.name_prefix}_placement_group"
  strategy = "cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_placement_group"
  })
}

resource "aws_security_group" "cluster_nodes" {
  name        = "${local.name_prefix}_cluster_nodes_sg"
  description = "Security group for clustered EC2 nodes: HTTP/HTTPS from anywhere, unrestricted intra-cluster traffic."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_cluster_nodes_sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443
}

resource "aws_vpc_security_group_ingress_rule" "cluster_internal" {
  security_group_id            = aws_security_group.cluster_nodes.id
  referenced_security_group_id = aws_security_group.cluster_nodes.id
  ip_protocol                  = "-1"
}

resource "aws_vpc_security_group_egress_rule" "allow_all_egress" {
  security_group_id = aws_security_group.cluster_nodes.id
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_instance" "cluster_node" {
  count = 3

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public[0].id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.cluster_nodes.id]
  placement_group             = aws_placement_group.cluster.id
  monitoring                  = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted             = true
    volume_size           = 20
    volume_type           = "gp3"
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name    = "${local.name_prefix}_cluster_node_${count.index + 1}"
    Cluster = local.name_prefix
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (all non-sensitive defaults)
# ------------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and the Name tag convention."
  type        = string
  default     = "memcached-cluster"
}

variable "environment" {
  description = "Deployment environment used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC hosting the Memcached cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "num_cache_nodes" {
  description = "Number of Memcached cache nodes. A value of 2 or more enables multi-node auto-discovery."
  type        = number
  default     = 2

  validation {
    condition     = var.num_cache_nodes >= 1 && var.num_cache_nodes <= 40
    error_message = "num_cache_nodes must be between 1 and 40."
  }
}

variable "node_type" {
  description = "ElastiCache node type for the Memcached cluster."
  type        = string
  default     = "cache.t3.small"
}

variable "engine_version" {
  description = "Supported Memcached engine version (1.6.x series)."
  type        = string
  default     = "1.6.22"
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  name = var.project_name

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-subnet-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------------------
# Security group (Memcached TCP 11211 from the VPC CIDR only)
# ------------------------------------------------------------------------------

resource "aws_security_group" "memcached" {
  name        = "${local.name}-sg"
  description = "Allow inbound Memcached traffic on TCP 11211 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Memcached client traffic from within the VPC"
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# ------------------------------------------------------------------------------
# ElastiCache Memcached cluster
# ------------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "memcached" {
  name       = "${local.name}-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-group"
  })
}

resource "aws_elasticache_cluster" "memcached" {
  cluster_id = "${local.name}-${var.environment}"
  engine     = "memcached"

  engine_version       = var.engine_version
  node_type            = var.node_type
  num_cache_nodes      = var.num_cache_nodes
  parameter_group_name = "default.memcached1.6"
  port                 = 11211

  subnet_group_name  = aws_elasticache_subnet_group.memcached.name
  security_group_ids = [aws_security_group.memcached.id]

  # Spread nodes across AZs when running more than one node for high availability.
  az_mode = var.num_cache_nodes > 1 ? "cross-az" : "single-az"

  # Maintenance best practices. Memcached does not support snapshots, so no
  # snapshot settings apply; automatic minor version upgrades keep the 1.6.x
  # engine current. notification_topic_arn is intentionally omitted because no
  # SNS topic is created in this configuration.
  maintenance_window         = "sun:05:00-sun:07:00"
  auto_minor_version_upgrade = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "memcached_configuration_endpoint" {
  description = "Configuration endpoint (address and port) for Memcached client auto-discovery."
  value       = aws_elasticache_cluster.memcached.configuration_endpoint
}

output "memcached_port" {
  description = "Port that the Memcached cluster listens on."
  value       = aws_elasticache_cluster.memcached.port
}

# Redis (ElastiCache) — single-node cluster, encrypted in transit (TLS) and at rest.
#
# Client connectivity notes:
#   * Connect to the primary endpoint on port 6379 using TLS (rediss://).
#   * Authenticate with the AUTH token stored in Secrets Manager
#     (see the redis_auth_secret_arn output). The token value is never
#     hardcoded in this configuration or exposed in its outputs.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (defaults keep `terraform apply` fully non-interactive)
###############################################################################

variable "project_name" {
  description = "Base name used to derive resource names and the Name tag."
  type        = string
  default     = "redis"
}

variable "environment" {
  description = "Value applied to the Environment tag on every resource."
  type        = string
  default     = "production"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Networking — Redis network foundation
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

# Two private subnets across distinct AZs — ElastiCache subnet groups require
# subnets in at least two availability zones.
resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-private-${count.index + 1}"
  })
}

###############################################################################
# Security group — ingress limited to Redis (TCP 6379) sourced from the VPC
# CIDR only. No 0.0.0.0/0 ingress rule is declared for port 6379 (or any
# other port). Egress is unrestricted.
###############################################################################

resource "aws_security_group" "redis" {
  name        = "${var.project_name}-cache-sg"
  description = "Permits inbound Redis traffic (TCP 6379) only from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from the VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Unrestricted outbound access"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-sg"
  })
}

resource "aws_elasticache_subnet_group" "redis" {
  name        = "${var.project_name}-cache-subnets"
  description = "Private subnets spanning two AZs for the ${var.project_name} Redis cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-subnets"
  })
}

###############################################################################
# Encryption at rest — dedicated customer-managed KMS key with rotation.
# NOTE: KMS aliases are not taggable at the AWS API level, so the
# aws_kms_alias resource below intentionally carries no tags argument.
# Tag coverage for this encryption component is provided by aws_kms_key.redis.
###############################################################################

resource "aws_kms_key" "redis" {
  description             = "Customer-managed key for Redis (ElastiCache) encryption at rest and Secrets Manager encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-key"
  })
}

resource "aws_kms_alias" "redis" {
  name          = "alias/${var.project_name}"
  target_key_id = aws_kms_key.redis.key_id
}

###############################################################################
# Redis AUTH token — randomly generated and stored in Secrets Manager.
# The token value is never hardcoded in this configuration.
###############################################################################

resource "random_password" "redis_auth" {
  length  = 48
  special = false

  min_upper   = 8
  min_lower   = 8
  min_numeric = 8
}

resource "aws_secretsmanager_secret" "redis_auth" {
  name                    = "${var.project_name}/cache/auth-token"
  description             = "AUTH token for the ${var.project_name} Redis cluster. Clients must connect over TLS (rediss://) and authenticate with this token."
  recovery_window_in_days = 7
  kms_key_id              = aws_kms_key.redis.arn

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache-auth-token"
  })
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  secret_id     = aws_secretsmanager_secret.redis_auth.id
  secret_string = random_password.redis_auth.result
}

###############################################################################
# Redis replication group (single node)
###############################################################################

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = "${var.project_name}-cache"
  description          = "Single-node Redis cluster; clients must connect over TLS (rediss://) using the AUTH token stored in Secrets Manager"

  engine               = "redis"
  engine_version       = "7.1"
  parameter_group_name = "default.redis7"
  node_type            = "cache.t4g.small"
  num_cache_clusters   = 1
  port                 = 6379

  automatic_failover_enabled = false
  multi_az_enabled           = false

  subnet_group_name  = aws_elasticache_subnet_group.redis.name
  security_group_ids = [aws_security_group.redis.id]

  # Encryption at rest, backed by the dedicated customer-managed KMS key
  at_rest_encryption_enabled = true
  kms_key_id                 = aws_kms_key.redis.arn

  # Encryption in transit (TLS enforced) plus AUTH token from Secrets Manager
  transit_encryption_enabled = true
  auth_token                 = aws_secretsmanager_secret_version.redis_auth.secret_string

  # Automated backups: 7-day retention; snapshot and maintenance windows are
  # both outside business hours (all times UTC)
  snapshot_retention_limit = 7
  snapshot_window          = "02:00-04:00"
  maintenance_window       = "sun:04:30-sun:06:00"

  apply_immediately = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cache"
  })
}

###############################################################################
# Outputs
###############################################################################

output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis cluster. Connect over TLS (rediss://) using the AUTH token stored in Secrets Manager."
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Port the Redis cluster listens on."
  value       = aws_elasticache_replication_group.redis.port
}

output "redis_auth_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redis AUTH token. Retrieve the value with the AWS CLI/SDK; the token is never exposed here. Clients must connect over TLS (rediss://) with AUTH."
  value       = aws_secretsmanager_secret.redis_auth.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Name        = "app-redis-rbac"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  redis_user_id       = "app_redis_user"
  redis_user_name     = "app_redis_user"
  redis_user_group_id = "app-redis-user-group"
}

# Customer-managed KMS key used to encrypt the Redis user password secret.
resource "aws_kms_key" "redis_user_secret" {
  description             = "KMS key for the ElastiCache Redis user password secret"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Credential for the Redis user. Never a literal value; referenced by the
# ElastiCache user and by Secrets Manager only.
resource "random_password" "redis_user_password" {
  length           = 32
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}:?"
  special          = true
}

# ElastiCache (Redis) RBAC user with least-privilege key scoping and command
# categories. The user is enabled only on the app:* key pattern, with read and
# write command groups, while dangerous and administrative command categories
# are explicitly denied.
resource "aws_elasticache_user" "redis_user" {
  user_id       = local.redis_user_id
  user_name     = local.redis_user_name
  engine        = "redis"
  access_string = "on ~app:* +@read +@write -@dangerous -@admin"

  # Password-based authentication: providing `passwords` with
  # `no_password_required = false` provisions this user with the ElastiCache
  # authentication type "password".
  no_password_required = false
  passwords            = [random_password.redis_user_password.result]

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# The generated credential is stored in AWS Secrets Manager, encrypted with
# the customer-managed KMS key above. Only the secret ARN is ever referenced
# by other resources; the secret value itself is never exposed.
resource "aws_secretsmanager_secret" "redis_user_password" {
  name        = "elasticache/redis-user/${local.redis_user_id}"
  description = "Password for the ElastiCache Redis user ${local.redis_user_name}"
  kms_key_id  = aws_kms_key.redis_user_secret.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redis_user_password" {
  secret_id = aws_secretsmanager_secret.redis_user_password.id
  secret_string = jsonencode({
    username = aws_elasticache_user.redis_user.user_name
    password = random_password.redis_user_password.result
  })
}

# User group that attaches the Redis user so it can be associated with
# replication groups and used by clients.
resource "aws_elasticache_user_group" "redis_user_group" {
  user_group_id = local.redis_user_group_id
  engine        = "redis"
  user_ids      = [aws_elasticache_user.redis_user.user_id]
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "redis_user_id" {
  description = "The ID of the ElastiCache Redis user."
  value       = aws_elasticache_user.redis_user.id
}

output "redis_user_arn" {
  description = "The ARN of the ElastiCache Redis user."
  value       = aws_elasticache_user.redis_user.arn
}

output "redis_user_group_id" {
  description = "The ID of the ElastiCache Redis user group."
  value       = aws_elasticache_user_group.redis_user_group.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)

  default = {
    Project     = "elasticache-iam-auth"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  elasticache_user_id       = "app_cache_iam_user"
  elasticache_user_name     = "app_cache_iam_user"
  cache_client_role_name    = "elasticache-iam-auth-client"
  cache_connect_policy_name = "elasticache-connect-app-cache-user"
}

# ------------------------------------------------------------------------------
# ElastiCache user authenticated via IAM (SigV4), no password material managed.
# Descriptive context is carried via tags because aws_elasticache_user has no
# description argument in the provider schema.
# ------------------------------------------------------------------------------
resource "aws_elasticache_user" "app_cache" {
  user_id       = local.elasticache_user_id
  user_name     = local.elasticache_user_name
  engine        = "redis"
  access_string = "on ~app:* -@all +@read +@write +@slow"

  authentication_mode {
    type = "iam"
  }

  tags = merge(
    var.common_tags,
    {
      Description = "Application cache user authenticated via IAM (SigV4)"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM role assumed by client workloads (EC2 service principal only)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "cache_client_trust" {
  statement {
    sid    = "AllowEC2ToAssumeCacheClientRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cache_client" {
  name               = local.cache_client_role_name
  description        = "Role assumed by client workloads to connect to ElastiCache with IAM authentication."
  assume_role_policy = data.aws_iam_policy_document.cache_client_trust.json

  tags = var.common_tags
}

# ------------------------------------------------------------------------------
# IAM policy granting only elasticache:Connect on the ElastiCache user ARN
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "cache_connect" {
  statement {
    sid       = "AllowElastiCacheConnect"
    effect    = "Allow"
    actions   = ["elasticache:Connect"]
    resources = [aws_elasticache_user.app_cache.arn]
  }
}

resource "aws_iam_policy" "cache_connect" {
  name        = local.cache_connect_policy_name
  description = "Permits elasticache:Connect only against the application ElastiCache user."
  policy      = data.aws_iam_policy_document.cache_connect.json

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "cache_connect" {
  role       = aws_iam_role.cache_client.name
  policy_arn = aws_iam_policy.cache_connect.arn
}

# ------------------------------------------------------------------------------
# Outputs for client workloads
# ------------------------------------------------------------------------------
output "elasticache_user_id" {
  description = "ID of the ElastiCache user used for IAM-authenticated cache connections."
  value       = aws_elasticache_user.app_cache.id
}

output "elasticache_user_arn" {
  description = "ARN of the ElastiCache user."
  value       = aws_elasticache_user.app_cache.arn
}

output "cache_client_role_arn" {
  description = "ARN of the IAM role that client workloads assume for IAM-authenticated cache access."
  value       = aws_iam_role.cache_client.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to the tags of all resources."
  type        = string
  default     = "production"
}

locals {
  elasticache_user_name = "cache_app_user"

  tags = {
    Name        = "elasticache-user-${local.elasticache_user_name}"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_password" "elasticache_user_password" {
  length           = 32
  lower            = true
  upper            = true
  numeric          = true
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "elasticache_user_credential" {
  name        = "elasticache/${local.elasticache_user_name}"
  description = "Credential for the ElastiCache Redis ACL user ${local.elasticache_user_name}."
  tags        = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "elasticache_user_credential" {
  secret_id = aws_secretsmanager_secret.elasticache_user_credential.id
  secret_string = jsonencode({
    username = local.elasticache_user_name
    password = random_password.elasticache_user_password.result
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "cache_app_user" {
  user_id       = local.elasticache_user_name
  user_name     = local.elasticache_user_name
  engine        = "REDIS"
  access_string = "on ~app:* -@all +@read +@write -@dangerous"

  authentication_mode {
    type      = "password"
    passwords = [random_password.elasticache_user_password.result]
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all ElastiCache resources."
  type        = string
  default     = "dev"
}

variable "owner" {
  description = "Team or individual responsible for these resources."
  type        = string
  default     = "platform-team"
}

locals {
  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }
}

# Every ElastiCache user group must include the "default" user.
# It is declared with a deny-by-default access string ("off") so the
# default user cannot authenticate or execute any commands.
resource "aws_elasticache_user" "default" {
  user_id              = "default"
  user_name            = "default"
  engine               = "REDIS"
  access_string        = "off"
  no_password_required = true

  tags = local.common_tags
}

# Least-privilege application user:
#   - restricted to keys matching app:*
#   - granted only read/write/connection command categories
#   - dangerous commands (flushall, flushdb, config, etc.) explicitly denied
# IAM-based authentication (no passwords, secrets, or API keys are stored).
resource "aws_elasticache_user" "app_user" {
  user_id              = "app_user"
  user_name            = "app_user"
  engine               = "REDIS"
  access_string        = "on ~app:* +@read +@write +@connection -@dangerous"
  no_password_required = true

  tags = local.common_tags
}

resource "aws_elasticache_user_group" "app" {
  user_group_id = "app-redis-user-group"
  engine        = "REDIS"

  user_ids = [
    aws_elasticache_user.default.user_id,
    aws_elasticache_user.app_user.user_id,
  ]

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

output "user_group_id" {
  description = "The ID of the ElastiCache user group."
  value       = aws_elasticache_user_group.app.user_group_id
}

output "user_group_arn" {
  description = "The ARN of the ElastiCache user group."
  value       = aws_elasticache_user_group.app.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  engine        = "redis"
  user_id       = "app-user-001"
  user_name     = "app-user-001"
  user_group_id = "app-user-group-001"

  secret_name = "elasticache/${local.user_id}/password"

  # Least-privilege Redis ACL:
  #   * enabled user ("on")
  #   * key access limited to the "cache:*" key pattern
  #   * pub/sub limited to the "cache-events:*" channel pattern
  #   * all commands revoked first ("-@all"), then only the required command
  #     categories are granted; "@dangerous" is revoked last so commands such
  #     as FLUSHALL, KEYS and CONFIG can never be executed.
  access_string = "on ~cache:* -@all +@read +@write +@connection +@pubsub -@dangerous &cache-events:*"

  common_tags = {
    Component = "cache"
    ManagedBy = "terraform"
  }
}

# The password is generated, never hardcoded. ElastiCache requires 16-128
# printable characters and rejects double quotes, slashes, "@" and spaces,
# all of which are excluded from the special-character set below.
resource "random_password" "elasticache_user_password" {
  length           = 32
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_kms_key" "elasticache_secrets" {
  description             = "Encrypts the ElastiCache user password secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "elasticache-user-secrets"
  })
}

resource "aws_secretsmanager_secret" "elasticache_user_password_secret" {
  name                    = local.secret_name
  description             = "Password for the ElastiCache (Redis) user ${local.user_id}"
  kms_key_id              = aws_kms_key.elasticache_secrets.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = local.secret_name
  })
}

resource "aws_secretsmanager_secret_version" "elasticache_user_password_secret_version" {
  secret_id     = aws_secretsmanager_secret.elasticache_user_password_secret.id
  secret_string = random_password.elasticache_user_password.result
}

resource "aws_elasticache_user" "app_user" {
  user_id   = local.user_id
  user_name = local.user_name
  engine    = local.engine

  access_string        = local.access_string
  no_password_required = false
  passwords = [
    aws_secretsmanager_secret_version.elasticache_user_password_secret_version.secret_string,
  ]

  tags = merge(local.common_tags, {
    Name = local.user_id
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Membership is owned exclusively by aws_elasticache_user_group_association
# below; user_ids is intentionally omitted to avoid dual management of the
# same ModifyUserGroup API state. The group is created empty, which the AWS
# CreateUserGroup API accepts.
resource "aws_elasticache_user_group" "main" {
  engine        = local.engine
  user_group_id = local.user_group_id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user_group_association" "app_user_membership" {
  user_group_id = aws_elasticache_user_group.main.user_group_id
  user_id       = aws_elasticache_user.app_user.user_id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  aws_region_name            = "us-east-1"
  master_username            = "redshiftadmin"
  data_bucket_name           = "redshift-analytics-data-${random_id.bucket_suffix.hex}"
  s3_gateway_service_name    = "com.amazonaws.${local.aws_region_name}.s3"
  kms_interface_service_name = "com.amazonaws.${local.aws_region_name}.kms"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Project     = "redshift-analytics"
    },
    var.tags,
  )
}

# -----------------------------------------------------------------------------
# Network foundation (private-only: no internet gateway, no public subnets)
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "redshift-analytics-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "redshift-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "redshift-private-b" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "redshift-private-route-table" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# VPC endpoints so the enhanced-vpc-routed cluster can reach S3 and KMS
# without any internet gateway.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = local.s3_gateway_service_name
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "redshift-s3-gateway-endpoint" })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "redshift-vpc-endpoints-sg"
  description = "Allow HTTPS from the VPC to interface VPC endpoints."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "redshift-vpc-endpoints-sg" })
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = local.kms_interface_service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, { Name = "redshift-kms-interface-endpoint" })
}

# -----------------------------------------------------------------------------
# Cluster security group
# -----------------------------------------------------------------------------
resource "aws_security_group" "redshift" {
  name        = "redshift-analytics-cluster-sg"
  description = "Restrict access to the Redshift cluster to TCP 5439 from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS egress for AWS service access through VPC endpoints"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "redshift-analytics-cluster-sg" })
}

# -----------------------------------------------------------------------------
# Master credentials (no plaintext values)
# -----------------------------------------------------------------------------
resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift/${var.environment}/redshift-analytics-cluster/master"
  description = "Master credentials for the redshift-analytics-cluster Redshift cluster."

  tags = merge(local.common_tags, { Name = "redshift-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# S3 data bucket for COPY/UNLOAD
# -----------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "redshift_data" {
  bucket = local.data_bucket_name

  tags = merge(local.common_tags, { Name = local.data_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "redshift_data" {
  bucket                  = aws_s3_bucket.redshift_data.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "redshift_data" {
  bucket = aws_s3_bucket.redshift_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "redshift_data" {
  bucket = aws_s3_bucket.redshift_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM role for the cluster (least-privilege read access to the data prefix)
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    sid     = "AllowRedshiftAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "redshift_s3_copy" {
  name               = "redshift-analytics-s3-copy-role"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = merge(local.common_tags, { Name = "redshift-analytics-s3-copy-role" })
}

data "aws_iam_policy_document" "redshift_s3_read" {
  statement {
    sid       = "ListDataPrefix"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.redshift_data.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["data/*"]
    }
  }

  statement {
    sid       = "ReadDataObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.redshift_data.arn}/data/*"]
  }
}

resource "aws_iam_policy" "redshift_s3_read" {
  name        = "redshift-analytics-s3-read-policy"
  description = "Read-only access to the redshift data bucket prefix for COPY operations."
  policy      = data.aws_iam_policy_document.redshift_s3_read.json

  tags = merge(local.common_tags, { Name = "redshift-analytics-s3-read-policy" })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_read" {
  role       = aws_iam_role.redshift_s3_copy.name
  policy_arn = aws_iam_policy.redshift_s3_read.arn
}

# -----------------------------------------------------------------------------
# Redshift subnet group and parameter group
# -----------------------------------------------------------------------------
resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-analytics-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "redshift-analytics-subnet-group" })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "redshift-analytics-parameters"
  family = "redshift-2.0"

  parameter {
    name  = "ssl"
    value = "true"
  }

  tags = merge(local.common_tags, { Name = "redshift-analytics-parameters" })
}

# -----------------------------------------------------------------------------
# Single-node Redshift cluster
# -----------------------------------------------------------------------------
resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-analytics-cluster"
  database_name      = "analyticsdb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  master_username = jsondecode(aws_secretsmanager_secret_version.redshift_master.secret_string)["username"]
  master_password = jsondecode(aws_secretsmanager_secret_version.redshift_master.secret_string)["password"]

  encrypted            = true
  publicly_accessible  = false
  enhanced_vpc_routing = true

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  iam_roles                    = [aws_iam_role.redshift_s3_copy.arn]

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-analytics-cluster-final-snapshot"

  tags = merge(local.common_tags, { Name = "redshift-analytics-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "cluster_endpoint" {
  description = "Connection endpoint for the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "cluster_database_name" {
  description = "Default database created on the Redshift cluster."
  value       = aws_redshift_cluster.main.database_name
}

output "data_bucket_name" {
  description = "S3 bucket used for Redshift COPY and UNLOAD data."
  value       = aws_s3_bucket.redshift_data.bucket
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.redshift_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "common_tags" {
  description = "Additional common tags applied to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix     = "redshift-${var.environment}"
  master_username = "redshiftadmin"
  database_name   = "analyticsdb"

  common_tags = merge(
    var.common_tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Restrict Redshift access to the VPC CIDR on the Redshift port"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

resource "aws_kms_key" "redshift" {
  description             = "Customer managed KMS key used to encrypt the Redshift cluster"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "wlm_json_configuration"
    value = jsonencode([
      {
        auto_wlm            = true
        concurrency_scaling = "auto"
      },
    ])
  }

  parameter {
    name  = "max_concurrency_scaling_clusters"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-parameter-group"
  })
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = "${local.name_prefix}-cluster"
  database_name                       = local.database_name
  cluster_type                        = "multi-node"
  node_type                           = "ra3.xlplus"
  number_of_nodes                     = 2
  master_username                     = local.master_username
  master_password                     = random_password.redshift_master.result
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name        = aws_redshift_parameter_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  port                                = 5439
  publicly_accessible                 = false
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  cluster_version                     = "1.0"
  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "sun:04:30-sun:05:30"
  allow_version_upgrade               = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

resource "aws_redshift_usage_limit" "concurrency_scaling_daily" {
  cluster_identifier = aws_redshift_cluster.main.cluster_identifier
  feature_type       = "concurrency-scaling"
  limit_type         = "time"
  amount             = 60
  period             = "daily"
  breach_action      = "disable"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-concurrency-scaling-limit"
  })
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "authorized_aws_account_id" {
  description = "AWS account ID of the external account that is authorized to access the Redshift cluster endpoint."
  type        = string
  default     = "012345678910"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.authorized_aws_account_id))
    error_message = "authorized_aws_account_id must be a 12-digit AWS account ID."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  cluster_identifier = "redshift-main-cluster"

  common_tags = {
    ManagedBy = "terraform"
    Component = "analytics"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "redshift-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "redshift-cluster-sg"
  description = "Allows Redshift client access from within the VPC on port 5439"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "redshift-cluster-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "redshift-subnet-group"
  description = "Subnet group spanning two Availability Zones for the Redshift cluster"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, {
    Name = "redshift-subnet-group"
  })
}

resource "random_password" "master" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master_password" {
  name        = "redshift/${local.cluster_identifier}/master-password"
  description = "Master password for the ${local.cluster_identifier} Amazon Redshift cluster"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id     = aws_secretsmanager_secret.redshift_master_password.id
  secret_string = random_password.master.result
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = local.cluster_identifier
  database_name                       = "maindb"
  master_username                     = "redshiftadmin"
  master_password                     = aws_secretsmanager_secret_version.db.secret_string
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  encrypted                           = true
  publicly_accessible                 = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = true

  tags = merge(local.common_tags, {
    Name = local.cluster_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_redshift_endpoint_authorization" "main" {
  account            = var.authorized_aws_account_id
  cluster_identifier = aws_redshift_cluster.main.id
}

output "cluster_endpoint" {
  description = "Connection endpoint (address:port) of the Redshift cluster."
  value       = aws_redshift_cluster.main.endpoint
}

output "cluster_port" {
  description = "Port on which the Redshift cluster accepts client connections."
  value       = aws_redshift_cluster.main.port
}

output "endpoint_authorization_grantee" {
  description = "AWS account ID of the grantee for which the cross-account Redshift endpoint authorization was created; confirms the authorization exists for var.authorized_aws_account_id."
  value       = aws_redshift_endpoint_authorization.main.grantee
}

output "endpoint_authorization_endpoint_count" {
  description = "Number of Redshift-managed VPC endpoints created under the endpoint authorization (0 until the grantee consumes the authorization)."
  value       = aws_redshift_endpoint_authorization.main.endpoint_count
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging"
  type        = string
  default     = "redshift-analytics"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

locals {
  name_prefix = lower("${var.project_name}-${var.environment}")

  common_tags = {
    project     = var.project_name
    environment = var.environment
    managed_by  = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-a" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-b" })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Allow Redshift connections on TCP 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-sg" })
}

resource "aws_redshift_subnet_group" "main" {
  name       = "${local.name_prefix}-redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-subnet-group" })
}

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for Redshift cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}-redshift-kms" })
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = "analyticsdb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  master_username                   = "admin"
  manage_master_password            = true
  master_password_secret_kms_key_id = aws_kms_key.redshift.key_id

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]

  publicly_accessible = false
  encrypted           = true
  kms_key_id          = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = 7
  preferred_maintenance_window        = "sun:04:30-sun:05:30"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, { name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_redshift_snapshot_schedule" "every_12_hours" {
  identifier  = "${local.name_prefix}-snapshot-schedule-12h"
  description = "Automated snapshot schedule firing every 12 hours"
  definitions = ["rate(12 hours)"]

  tags = merge(local.common_tags, { name = "${local.name_prefix}-snapshot-schedule-12h" })
}

resource "aws_redshift_snapshot_schedule_association" "main" {
  cluster_identifier  = aws_redshift_cluster.main.cluster_identifier
  schedule_identifier = aws_redshift_snapshot_schedule.every_12_hours.identifier
}

output "redshift_cluster_endpoint" {
  description = "Connection endpoint (address and port) of the Redshift cluster"
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the Redshift admin credentials"
  value       = aws_redshift_cluster.main.master_password_secret_arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    }
  )
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc-private-a"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc-private-b"
    }
  )
}

resource "aws_redshift_subnet_group" "main" {
  name        = "main-redshift-subnet-group"
  description = "Redshift subnet group spanning two availability zones for high availability"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "main-redshift-subnet-group"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources (pure static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Variables (non-infrastructure values only; all defaulted for unattended apply)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "redshift-ha"
}

variable "environment" {
  description = "Value used for the Environment tag."
  type        = string
  default     = "production"
}

variable "managed_by" {
  description = "Value used for the ManagedBy tag."
  type        = string
  default     = "terraform"
}

variable "master_username" {
  description = "Admin username for the Redshift cluster. The password is generated by random_password and stored in Secrets Manager."
  type        = string
  default     = "redshiftadmin"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix   = var.project_name
  database_name = "analytics_db"
  log_prefix    = "audit-logs/"

  common_tags = {
    Environment = var.environment
    ManagedBy   = var.managed_by
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Network foundation: VPC + one subnet per AZ (us-east-1a / us-east-1b)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "redshift_a" {
  subnet_id      = aws_subnet.redshift_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "redshift_b" {
  subnet_id      = aws_subnet.redshift_b.id
  route_table_id = aws_route_table.main.id
}

# S3 gateway endpoint so COPY/UNLOAD and audit log delivery work without internet access.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  })
}

# -----------------------------------------------------------------------------
# Security group: ingress on 5439 restricted to the VPC CIDR only
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-cluster-sg"
  description = "Restrict Redshift access to the VPC CIDR; S3 access via gateway endpoint"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift SQL connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Cluster-internal leader/compute node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Cluster-internal leader/compute node communication"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description     = "HTTPS to Amazon S3 through the gateway endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.s3.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster-sg"
  })
}

# -----------------------------------------------------------------------------
# KMS encryption key and alias for the cluster and audit log bucket
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Key for Redshift cluster encryption and audit log bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableAccountAdmin"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowRedshiftLogDelivery"
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift-key"
  target_key_id = aws_kms_key.redshift.key_id
}

# -----------------------------------------------------------------------------
# Master credentials: generated, stored in Secrets Manager, never plaintext
# -----------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%*+-_="
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.redshift_master.result
    engine   = "redshift"
    port     = 5439
    dbname   = local.database_name
  })
}

# -----------------------------------------------------------------------------
# S3 audit log bucket (private, KMS-encrypted, versioned)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "audit_logs" {
  bucket = "${local.name_prefix}-audit-logs-${random_id.suffix.hex}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-audit-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.redshift.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "audit_logs_bucket" {
  statement {
    sid       = "RedshiftLogDeliveryAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.audit_logs.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }

  statement {
    sid       = "RedshiftLogDeliveryPutObject"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.audit_logs.arn}/${local.log_prefix}*"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id
  policy = data.aws_iam_policy_document.audit_logs_bucket.json
}

# -----------------------------------------------------------------------------
# IAM role assumed by Redshift (least privilege, scoped to the audit log bucket)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "redshift_s3_access" {
  statement {
    sid       = "ListAuditLogBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.audit_logs.arn]
  }

  statement {
    sid       = "ReadWriteAuditLogBucketObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${aws_s3_bucket.audit_logs.arn}/*"]
  }

  statement {
    sid       = "UseRedshiftKmsKey"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:Encrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_key.redshift.arn]
  }
}

resource "aws_iam_role" "redshift_s3" {
  name               = "${local.name_prefix}-s3-role"
  description        = "Role assumed by the Redshift cluster for S3 access"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-role"
  })
}

resource "aws_iam_policy" "redshift_s3_access" {
  name        = "${local.name_prefix}-s3-access"
  description = "Least-privilege S3 and KMS access for the Redshift cluster"
  policy      = data.aws_iam_policy_document.redshift_s3_access.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-access"
  })
}

resource "aws_iam_role_policy_attachment" "redshift_s3_access" {
  role       = aws_iam_role.redshift_s3.name
  policy_arn = aws_iam_policy.redshift_s3_access.arn
}

# -----------------------------------------------------------------------------
# Redshift prerequisites: multi-AZ subnet group and hardened parameter group
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Multi-AZ subnet group spanning us-east-1a and us-east-1b"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-group"
  })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-params"
  })
}

# -----------------------------------------------------------------------------
# Highly available Redshift cluster (multi-AZ across two subnets)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  # AWS cluster identifiers permit lowercase letters and hyphens only (no underscores)
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = local.database_name

  master_username = var.master_username

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2
  multi_az        = true

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false
  port                         = 5439

  encrypted            = true
  kms_key_id           = aws_kms_key.redshift.arn
  enhanced_vpc_routing = true

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final-${random_id.suffix.hex}"

  preferred_maintenance_window = "sun:01:00-sun:03:00"
  allow_version_upgrade        = true

  iam_roles = [aws_iam_role.redshift_s3.arn]

  logging {
    enable        = true
    bucket_name   = aws_s3_bucket.audit_logs.id
    s3_key_prefix = local.log_prefix
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  # Ensure the secret payload (containing the password key) exists before
  # Redshift consumes the secret during cluster creation.
  depends_on = [aws_secretsmanager_secret_version.redshift_master]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs (no master password or secret value exposed)
# -----------------------------------------------------------------------------

output "redshift_cluster_endpoint" {
  description = "Connection endpoint of the Redshift cluster (host:port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_port" {
  description = "Port on which the Redshift cluster accepts connections."
  value       = aws_redshift_cluster.main.port
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Destination region used for cross-region snapshot replication.
provider "aws" {
  alias  = "dr"
  region = "us-east-2"
}

variable "project" {
  description = "Project name used as a consistent prefix for resource names and Name tags."
  type        = string
  default     = "analytics"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix        = var.project
  cluster_identifier = "${var.project}-redshift-cluster"
  database_name      = replace(lower(var.project), "-", "_")
  master_username    = "admin"

  common_tags = {
    Project   = var.project
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking foundation (us-east-1)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-az1"
  })
}

resource "aws_subnet" "redshift_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-az2"
  })
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift cluster access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift protocol (TCP 5439) from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to AWS service endpoints only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-sg"
  })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-redshift-subnet-group"
  description = "Redshift subnet group spanning two availability zones"
  subnet_ids  = [aws_subnet.redshift_az1.id, aws_subnet.redshift_az2.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Master credentials (no plain-text secret values in configuration)
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 32
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}/redshift/master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.primary.key_id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Encryption keys
# -----------------------------------------------------------------------------

resource "aws_kms_key" "primary" {
  description             = "KMS key for the ${local.name_prefix} Redshift cluster in us-east-1"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-kms-us-east-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.name_prefix}-redshift-us-east-1"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "dr" {
  provider                = aws.dr
  description             = "KMS key for ${local.name_prefix} Redshift cross-region snapshot copies in us-east-2"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-kms-us-east-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dr" {
  provider      = aws.dr
  name          = "alias/${local.name_prefix}-redshift-us-east-2"
  target_key_id = aws_kms_key.dr.key_id
}

# -----------------------------------------------------------------------------
# Cross-region snapshot replication target (us-east-2)
# -----------------------------------------------------------------------------

resource "aws_redshift_snapshot_copy_grant" "dr" {
  provider                 = aws.dr
  snapshot_copy_grant_name = "${local.name_prefix}-redshift-copy-grant"
  kms_key_id               = aws_kms_key.dr.arn
}

# -----------------------------------------------------------------------------
# Redshift cluster (us-east-1, snapshots replicated to us-east-2)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier                  = local.cluster_identifier
  database_name                       = local.database_name
  master_username                     = local.master_username
  master_password                     = random_password.redshift_master.result
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  port                                = 5439
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  encrypted                           = true
  kms_key_id                          = aws_kms_key.primary.arn
  publicly_accessible                 = false
  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-redshift-final-snapshot"
  preferred_maintenance_window        = "sun:04:30-sun:05:00"

  snapshot_copy {
    destination_region = "us-east-2"
    grant_name         = aws_redshift_snapshot_copy_grant.dr.snapshot_copy_grant_name
    retention_period   = 7
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-redshift-cluster"
  })

  depends_on = [aws_secretsmanager_secret_version.redshift_master]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Non-infrastructure environment name used for resource tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  name_prefix          = "redshift-${var.environment}"
  vpc_cidr             = "10.0.0.0/16"
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.20.0/24"]
  master_username      = "redshiftadmin"
  database_name        = "analyticsdb"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "redshift-data-platform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-subnet-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-route-table" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# S3 gateway endpoint so the cluster in the private subnets can reach the
# staging bucket for COPY/UNLOAD without a NAT gateway or internet gateway.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-gateway-endpoint" })
}

# -----------------------------------------------------------------------------
# KMS customer managed key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for Redshift encryption at rest, S3 staging data, and secret encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# S3 staging bucket for COPY/UNLOAD
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "staging" {
  bucket = "${local.name_prefix}-data-staging-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-data-staging" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket = aws_s3_bucket.staging.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
  bucket = aws_s3_bucket.staging.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.redshift.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "staging" {
  bucket = aws_s3_bucket.staging.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM role for the Redshift cluster
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "redshift" {
  name               = "${local.name_prefix}-cluster-role"
  description        = "Role assumed by the Redshift cluster for S3 COPY/UNLOAD access"
  assume_role_policy = data.aws_iam_policy_document.redshift_assume_role.json

  tags = local.common_tags
}

# Least-privilege inline policy: read-only access scoped to the staging bucket.
data "aws_iam_policy_document" "redshift_s3_access" {
  statement {
    sid       = "ListStagingBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.staging.arn]
  }

  statement {
    sid       = "ReadStagingObjects"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.staging.arn}/*"]
  }
}

resource "aws_iam_role_policy" "redshift_s3_access" {
  name   = "${local.name_prefix}-s3-access"
  role   = aws_iam_role.redshift.name
  policy = data.aws_iam_policy_document.redshift_s3_access.json
}

# Managed policy (attached via aws_iam_role_policy_attachment) granting the KMS
# permissions required to read/write SSE-KMS encrypted objects in the staging
# bucket from the cluster.
data "aws_iam_policy_document" "redshift_kms_access" {
  statement {
    sid    = "UseRedshiftKmsKeyForStaging"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.redshift.arn]
  }
}

resource "aws_iam_policy" "redshift_kms_access" {
  name        = "${local.name_prefix}-kms-access"
  description = "KMS decrypt and generate-data-key on the Redshift KMS key for SSE-KMS staging data"
  policy      = data.aws_iam_policy_document.redshift_kms_access.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "redshift_kms_access" {
  role       = aws_iam_role.redshift.name
  policy_arn = aws_iam_policy.redshift_kms_access.arn
}

# -----------------------------------------------------------------------------
# Redshift master credentials
# -----------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}-master-credentials"
  description = "Master credentials for the Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.key_id

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# -----------------------------------------------------------------------------
# Redshift cluster
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Restrict access to the Redshift cluster to the VPC on the Redshift port"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound access for S3 via the gateway VPC endpoint"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-sg" })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Redshift cluster"
  subnet_ids  = [aws_subnet.private[0].id, aws_subnet.private[1].id]

  tags = local.common_tags
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = local.database_name
  master_username    = local.master_username
  master_password    = random_password.redshift_master.result

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  enhanced_vpc_routing      = true

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  # Associate the IAM role with the cluster so it can COPY/UNLOAD from S3.
  iam_roles = [aws_iam_role.redshift.arn]

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })

  depends_on = [
    aws_secretsmanager_secret_version.redshift_master,
    aws_iam_role_policy.redshift_s3_access,
    aws_iam_role_policy_attachment.redshift_kms_access,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      ManagedBy = "terraform"
      Project   = "redshift-analytics"
    }
  }
}

# ------------------------------------------------------------------
# Networking (greenfield - created here, never looked up)
# ------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-main-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "redshift-private-b"
  }
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-main-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "redshift-main-subnet-group"
  }
}

# ------------------------------------------------------------------
# Security group - ingress restricted to Redshift port from VPC CIDR only
# ------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "redshift-main-sg"
  description = "Restrict Redshift access to TCP 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift access from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "redshift-main-sg"
  }
}

# ------------------------------------------------------------------
# Encryption - KMS key with rotation enabled
# ------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "KMS key for Redshift cluster encryption and master credentials secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = {
    Name = "redshift-main-kms"
  }
}

# ------------------------------------------------------------------
# Master credentials - generated, never plaintext in configuration
# ------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%^*()-_=+[]{}<>?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift-main-master-credentials"
  description = "Master credentials for the redshift-main Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = {
    Name = "redshift-main-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = "redshift_admin"
    password = random_password.redshift_master.result
  })
}

# ------------------------------------------------------------------
# IAM role - trusts only the Redshift service principal
# ------------------------------------------------------------------

resource "aws_iam_role" "redshift_access" {
  name = "redshift-main-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRedshiftServiceToAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "redshift-main-access-role"
  }
}

# ------------------------------------------------------------------
# Redshift cluster - private, encrypted, 2-node
# ------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "redshift-main"
  database_name      = "analytics"
  cluster_type       = "multi-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 2

  master_username = "redshift_admin"
  master_password = random_password.redshift_master.result

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]

  encrypted = true
  kms_key_id = aws_kms_key.redshift.arn

  publicly_accessible = false
  port                = 5439

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "redshift-main-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "redshift-main"
  }
}

# ------------------------------------------------------------------
# Resource policy - grants the IAM role explicit access to this cluster,
# scoped to the cluster's namespace ARN (computed attribute)
# ------------------------------------------------------------------

resource "aws_redshift_resource_policy" "main" {
  resource_arn = aws_redshift_cluster.main.cluster_namespace_arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGetClusterCredentialsFromAccessRole"
        Effect = "Allow"
        Principal = {
          AWS = [aws_iam_role.redshift_access.arn]
        }
        Action = [
          "redshift:GetClusterCredentials"
        ]
        Resource = [
          aws_redshift_cluster.main.cluster_namespace_arn
        ]
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  cluster_identifier = "redshift-main"
  database_name      = "dev"
  master_username    = "adminuser"
  redshift_port      = 5439

  common_tags = {
    Project   = "redshift-main"
    ManagedBy = "terraform"
  }
}

variable "admin_cidr" {
  description = "Optional additional CIDR block (besides the VPC CIDR) allowed to reach the Redshift endpoint on TCP 5439. Must never be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = var.admin_cidr != "0.0.0.0/0" && can(cidrnetmask(var.admin_cidr))
    error_message = "admin_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

###############################################################################
# Network foundation (greenfield): VPC, public subnets, IGW and routing so the
# Redshift cluster can be exposed through a publicly accessible endpoint.
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-vpc"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "redshift-main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "redshift-main-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_redshift_subnet_group" "main" {
  name       = "redshift-main-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "redshift-main-subnet-group"
  })
}

###############################################################################
# Security group for the cluster. TCP 5439 is the Redshift wire-protocol port,
# so ingress on that port is required for any client to reach the publicly
# accessible cluster endpoint requested for this deployment.
###############################################################################

resource "aws_security_group" "redshift" {
  name        = "redshift-main-sg"
  description = "Access to the redshift-main Redshift cluster endpoint (TCP 5439)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift wire protocol (TCP 5439) from within the VPC"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Redshift wire protocol (TCP 5439) from the admin CIDR"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Allow all outbound traffic (cluster maintenance, S3 and KMS access)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "redshift-main-sg"
  })
}

###############################################################################
# Customer-managed encryption key used for cluster encryption at rest.
###############################################################################

resource "aws_kms_key" "redshift" {
  description             = "Customer-managed key used to encrypt the redshift-main Redshift cluster at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "redshift-main-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Master credentials: the password is generated at apply time, satisfies the
# Redshift password policy, and is stored only in Secrets Manager. The value is
# never written into the configuration, locals, or variable defaults.
###############################################################################

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  # Redshift forbids '/', '"', "'", '@' and spaces in master passwords
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "redshift-main-master-credentials"
  description = "Master credentials for the redshift-main Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, {
    Name = "redshift-main-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id = aws_secretsmanager_secret.redshift_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

###############################################################################
# Redshift cluster: 2 x ra3.xlplus multi-node cluster with a publicly
# accessible endpoint, encrypted at rest with the customer-managed KMS key.
# With skip_final_snapshot = false the provider always takes a final snapshot
# named by final_snapshot_identifier on destroy.
###############################################################################

resource "aws_redshift_cluster" "redshift_main" {
  cluster_identifier = local.cluster_identifier
  database_name      = local.database_name
  master_username    = local.master_username
  master_password    = random_password.redshift_master.result

  node_type       = "ra3.xlplus"
  cluster_type    = "multi-node"
  number_of_nodes = 2
  port            = local.redshift_port

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = true

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.cluster_identifier}-final-snapshot"

  automated_snapshot_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "redshift-main"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs: connection details for clients. Only the secret ARN is exposed,
# never the secret value itself.
###############################################################################

output "redshift_endpoint_address" {
  description = "Full Redshift connection endpoint string for the redshift-main cluster (host:port/database) — this is the canonical endpoint attribute, not just the hostname"
  value       = aws_redshift_cluster.redshift_main.endpoint
}

output "redshift_endpoint_port" {
  description = "Port of the redshift-main Redshift cluster endpoint"
  value       = aws_redshift_cluster.redshift_main.port
}

output "redshift_database_name" {
  description = "Initial database name on the redshift-main Redshift cluster"
  value       = aws_redshift_cluster.redshift_main.database_name
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (secret value is never exposed)"
  value       = aws_secretsmanager_secret.redshift_master.arn
}

