provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as user-controlled tagging metadata only. Has a default so terraform apply runs unattended."
  type        = string
  default     = "dev"
}

locals {
  function_name      = "hello-app"
  handler            = "index.lambda_handler"
  runtime            = "python3.12"
  memory_size        = 256
  timeout            = 30
  log_retention_days = 14

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda execution role (least privilege: basic execution policy only)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "${local.function_name}-execution-role"
  description        = "Execution role for the ${local.function_name} Lambda function"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.function_name}-execution-role"
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# Handler source code and self-contained deployment package
# -----------------------------------------------------------------------------

resource "local_file" "handler" {
  filename = "${path.module}/src/index.py"
  content  = <<-EOF
    import json


    def lambda_handler(event, context):
        return {
            "statusCode": 200,
            "headers": {"Content-Type": "application/json"},
            "body": json.dumps({"message": "Hello from ${local.function_name}!"}),
        }
  EOF

  file_permission = "0644"
}

data "archive_file" "package" {
  type        = "zip"
  source_file = local_file.handler.filename
  output_path = "${path.module}/build/${local.function_name}.zip"
}

# -----------------------------------------------------------------------------
# Lambda function with published versions and a live alias
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "app" {
  function_name = local.function_name
  description   = "Application Lambda function managed by Terraform"

  role    = aws_iam_role.lambda_exec.arn
  runtime = local.runtime
  handler = local.handler

  filename         = data.archive_file.package.output_path
  source_code_hash = data.archive_file.package.output_base64sha256

  memory_size = local.memory_size
  timeout     = local.timeout

  architectures = ["arm64"]

  # publish = true emits a numbered, immutable version on every deploy.
  # Aliases cannot point at $LATEST, so publishing is required for the alias below.
  publish = true

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_cloudwatch_log_group.app,
  ]

  tags = merge(local.common_tags, {
    Name = local.function_name
  })
}

resource "aws_lambda_alias" "live" {
  name             = "live"
  description      = "Points at the latest published version of the ${local.function_name} function"
  function_name    = aws_lambda_function.app.function_name
  function_version = aws_lambda_function.app.version
}

# -----------------------------------------------------------------------------
# CloudWatch log group with enforced retention for the function's logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "app" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = local.log_retention_days

  tags = merge(local.common_tags, {
    Name = "/aws/lambda/${local.function_name}"
  })
}

# -----------------------------------------------------------------------------
# Outputs for downstream consumers
# -----------------------------------------------------------------------------

output "lambda_function_arn" {
  description = "Unqualified ARN of the Lambda function."
  value       = aws_lambda_function.app.arn
}

output "lambda_function_qualified_arn" {
  description = "Qualified ARN (pinned to the latest published version) of the Lambda function."
  value       = aws_lambda_function.app.qualified_arn
}

output "lambda_alias_arn" {
  description = "ARN of the live alias pointing at the latest published version."
  value       = aws_lambda_alias.live.arn
}

###############################################################################
# Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# User-controlled inputs (all defaulted so apply runs unattended)
###############################################################################

variable "project_name" {
  description = "Short project identifier used for resource naming."
  type        = string
  default     = "ddbevents"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of: dev, staging, prod."
  }
}

variable "lambda_timeout" {
  description = "Lambda function timeout in seconds."
  type        = number
  default     = 30

  validation {
    condition     = var.lambda_timeout >= 1 && var.lambda_timeout <= 900
    error_message = "lambda_timeout must be between 1 and 900 seconds."
  }
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention period for Lambda execution logs."
  type        = number
  default     = 14
}

variable "max_retry_attempts" {
  description = "Maximum retry attempts before a failed batch is sent to the dead-letter queue."
  type        = number
  default     = 2
}

###############################################################################
# Locals
###############################################################################

locals {
  function_name = "${var.project_name}-${var.environment}-processor"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# DynamoDB table with stream enabled
###############################################################################

resource "aws_dynamodb_table" "events_table" {
  name         = "${var.project_name}-${var.environment}-events"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SQS dead-letter queue for failed stream batches
###############################################################################

resource "aws_sqs_queue" "stream_dlq" {
  name                      = "${var.project_name}-${var.environment}-dlq"
  message_retention_seconds = 1209600

  sqs_managed_sse_enabled = true

  tags = local.common_tags
}

###############################################################################
# Lambda execution role and policies
###############################################################################

resource "aws_iam_role" "lambda_exec" {
  name = "${var.project_name}-${var.environment}-lambda-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "lambda_stream_read" {
  name = "${var.project_name}-${var.environment}-stream-read"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadEventStream"
        Effect = "Allow"
        Action = [
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:DescribeStream",
          "dynamodb:ListShards"
        ]
        Resource = aws_dynamodb_table.events_table.stream_arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_dlq_send" {
  name = "${var.project_name}-${var.environment}-dlq-send"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SendFailedBatchesToDlq"
        Effect   = "Allow"
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.stream_dlq.arn
      }
    ]
  })
}

###############################################################################
# CloudWatch log group for Lambda execution logs
###############################################################################

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = var.log_retention_in_days

  tags = local.common_tags
}

###############################################################################
# Lambda function (packaged locally via archive_file, no VPC required)
###############################################################################

data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/build/${var.project_name}-${var.environment}-lambda.zip"

  source {
    filename = "lambda_handler.py"
    content  = <<-HANDLER
import json


def handler(event, context):
    for record in event.get("Records", []):
        print(json.dumps(record, default=str))
    return {"statusCode": 200}
HANDLER
  }
}

resource "aws_lambda_function" "stream_processor" {
  function_name = local.function_name
  description   = "Processes item change records from the DynamoDB events table stream."

  role          = aws_iam_role.lambda_exec.arn
  runtime       = "python3.12"
  handler       = "lambda_handler.handler"
  timeout       = var.lambda_timeout
  memory_size   = 256
  architectures = ["arm64"]

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.lambda_stream_read,
    aws_iam_role_policy.lambda_dlq_send,
    aws_cloudwatch_log_group.lambda_logs
  ]

  tags = local.common_tags
}

###############################################################################
# Event source mapping: DynamoDB stream -> Lambda, DLQ on failure
###############################################################################

resource "aws_lambda_event_source_mapping" "dynamodb_stream" {
  event_source_arn  = aws_dynamodb_table.events_table.stream_arn
  function_name     = aws_lambda_function.stream_processor.function_name
  starting_position = "LATEST"
  batch_size        = 100
  enabled           = true

  bisect_batch_on_function_error = true
  maximum_retry_attempts         = var.max_retry_attempts

  destination_config {
    on_failure {
      destination_arn = aws_sqs_queue.stream_dlq.arn
    }
  }

  depends_on = [
    aws_iam_role_policy.lambda_stream_read,
    aws_iam_role_policy.lambda_dlq_send
  ]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  layer_name = "payload_layer"
}

resource "aws_lambda_layer_version" "payload_layer" {
  filename                 = "lambda_layer_payload.zip"
  layer_name               = local.layer_name
  description              = "Shared runtime dependencies for Python 3.12 Lambda functions, packaged from lambda_layer_payload.zip."
  compatible_runtimes      = ["python3.12"]
  compatible_architectures = ["x86_64"]
  source_code_hash         = try(filebase64sha256("lambda_layer_payload.zip"), null)
  license_info             = "MIT"

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource tagging."
  type        = string
  default     = "scheduled-job"
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  function_name = "scheduled-job"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda source code: write the Python handler to disk, then package it as a zip
# -----------------------------------------------------------------------------

resource "local_file" "lambda_handler" {
  filename = "${path.module}/src/main.py"
  content = <<-EOT
    import json


    def lambda_handler(event, context):
        print("Scheduled job invoked with event: " + json.dumps(event))

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "scheduled job executed successfully"}),
        }
  EOT
  file_permission = "0644"
}

data "archive_file" "lambda_zip" {
  type        = "zip"
  source_dir  = "${path.module}/src"
  output_path = "${path.module}/scheduled_job.zip"

  depends_on = [local_file.lambda_handler]
}

# -----------------------------------------------------------------------------
# IAM execution role trusting only the Lambda service principal
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lambda_exec" {
  name = "${local.function_name}-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Pre-provisioned CloudWatch log group with explicit retention (cost control)
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Least-privilege inline logging policy scoped to the function's log group
# -----------------------------------------------------------------------------

resource "aws_iam_role_policy" "lambda_logs" {
  name = "${local.function_name}-logs"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          trimsuffix(aws_cloudwatch_log_group.lambda_logs.arn, ":*"),
          aws_cloudwatch_log_group.lambda_logs.arn,
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Lambda function
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "scheduled_job" {
  function_name = local.function_name
  description   = "Job invoked by EventBridge every 15 minutes."

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  runtime          = "python3.12"
  handler          = "main.lambda_handler"

  memory_size = 128
  timeout     = 30

  role = aws_iam_role.lambda_exec.arn

  tags = merge(local.common_tags, {
    Name = local.function_name
  })

  depends_on = [
    aws_cloudwatch_log_group.lambda_logs,
    aws_iam_role_policy.lambda_logs,
  ]
}

# -----------------------------------------------------------------------------
# EventBridge schedule: rate(15 minutes) -> Lambda target
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "every_15_minutes" {
  name                = "${local.function_name}-every-15-minutes"
  description         = "Invokes the ${local.function_name} Lambda every 15 minutes."
  schedule_expression = "rate(15 minutes)"

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "scheduled_job" {
  rule      = aws_cloudwatch_event_rule.every_15_minutes.name
  target_id = "${local.function_name}-target"
  arn       = aws_lambda_function.scheduled_job.arn

  depends_on = [aws_lambda_permission.allow_eventbridge]
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.scheduled_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.every_15_minutes.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  name           = "test_lambda"
  log_group_name = "/aws/lambda/${local.name}"

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  log_group_arn = "arn:aws:logs:${local.region}:${local.account_id}:log-group:${local.log_group_name}"

  lambda_handler_source = <<-PY
import json
import logging

LOGGER = logging.getLogger()
LOGGER.setLevel(logging.INFO)


def lambda_handler(event, context):
    LOGGER.info("Received EventBridge event: %s", json.dumps(event, default=str))

    detail = event.get("detail", {}) or {}
    image_id = detail.get("image-id", "unknown")
    state = detail.get("state", "unknown")
    region = event.get("region", "unknown")

    LOGGER.info("AMI %s in region %s transitioned to state %s", image_id, region, state)

    return {
        "statusCode": 200,
        "body": json.dumps(
            {
                "message": f"AMI {image_id} is {state}",
                "imageId": image_id,
                "state": state,
                "region": region,
            }
        ),
    }
PY

  common_tags = {
    Name        = local.name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_role" "test_lambda_exec" {
  name        = "test_lambda_exec_role"
  description = "Execution role for the test_lambda function."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "test_lambda_logging" {
  name        = "test_lambda_logging"
  description = "Least-privilege CloudWatch Logs access for the test_lambda function."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "CreateFunctionLogGroup"
        Effect   = "Allow"
        Action   = "logs:CreateLogGroup"
        Resource = local.log_group_arn
      },
      {
        Sid    = "WriteFunctionLogStreams"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${local.log_group_arn}:*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "test_lambda_logging" {
  role       = aws_iam_role.test_lambda_exec.name
  policy_arn = aws_iam_policy.test_lambda_logging.arn
}

resource "aws_cloudwatch_log_group" "test_lambda" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = local.common_tags
}

data "archive_file" "test_lambda_payload" {
  type        = "zip"
  output_path = "${path.module}/test_lambda_payload.zip"

  source {
    content  = local.lambda_handler_source
    filename = "lambda_function.py"
  }
}

resource "aws_lambda_function" "test_lambda" {
  function_name = local.name
  description   = "Invoked by EventBridge when a new EC2 AMI becomes available."
  role          = aws_iam_role.test_lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"
  filename      = data.archive_file.test_lambda_payload.output_path
  source_code_hash = data.archive_file.test_lambda_payload.output_base64sha256
  timeout       = 30
  memory_size   = 256

  depends_on = [
    aws_cloudwatch_log_group.test_lambda,
    aws_iam_role_policy_attachment.test_lambda_logging
  ]

  tags = local.common_tags
}

resource "aws_cloudwatch_event_rule" "ec2_ami_available" {
  name        = "ec2-ami-available-${local.name}"
  description = "Matches EC2 AMI state change events and triggers ${local.name} when a new AMI becomes available."

  event_pattern = jsonencode({
    source        = ["aws.ec2"]
    "detail-type" = ["EC2 AMI State Change"]
    detail = {
      state = ["available"]
    }
  })

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "test_lambda" {
  rule      = aws_cloudwatch_event_rule.ec2_ami_available.name
  target_id = local.name
  arn       = aws_lambda_function.test_lambda.arn
}

resource "aws_lambda_permission" "test_lambda_from_eventbridge" {
  statement_id  = "AllowEventBridgeRuleInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.ec2_ami_available.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
