terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Default provider: primary (source) region of the global table.
provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

# Aliased provider for the us-west-2 region; required to create the regional
# multi-Region KMS replica key in that region.
provider "aws" {
  alias  = "west"
  region = "us-west-2"

  default_tags {
    tags = var.tags
  }
}

# Aliased provider for the eu-west-1 region; required to create the regional
# multi-Region KMS replica key in that region.
provider "aws" {
  alias  = "eu"
  region = "eu-west-1"

  default_tags {
    tags = var.tags
  }
}

variable "table_name" {
  description = "Name of the DynamoDB global table."
  type        = string
  default     = "app_global_table"
}

variable "tags" {
  description = "User-controlled (non-infrastructure) tags applied to all resources for consistent tagging."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Owner       = "platform-team"
  }
}

locals {
  # Replica table and stream ARNs are derived from the primary table ARN by
  # substituting the region segment; the DynamoDB ARN format is deterministic.
  replica_usw2_table_arn  = replace(aws_dynamodb_table.main.arn, "us-east-1", "us-west-2")
  replica_euw1_table_arn  = replace(aws_dynamodb_table.main.arn, "us-east-1", "eu-west-1")
  replica_usw2_stream_arn = "${local.replica_usw2_table_arn}/stream/*"
  replica_euw1_stream_arn = "${local.replica_euw1_table_arn}/stream/*"
}

# Multi-Region customer managed key so the same key material protects every
# replica of the global table.
resource "aws_kms_key" "table" {
  description             = "Multi-Region CMK for the ${var.table_name} DynamoDB global table"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  multi_region            = true

  tags = var.tags
}

# Regional replica keys of the multi-Region key, one per replica region.
resource "aws_kms_replica_key" "usw2" {
  provider                = aws.west
  description             = "us-west-2 replica key for the ${var.table_name} DynamoDB global table"
  primary_key_arn         = aws_kms_key.table.arn
  deletion_window_in_days = 30

  tags = var.tags
}

resource "aws_kms_replica_key" "euw1" {
  provider                = aws.eu
  description             = "eu-west-1 replica key for the ${var.table_name} DynamoDB global table"
  primary_key_arn         = aws_kms_key.table.arn
  deletion_window_in_days = 30

  tags = var.tags
}

# Primary (source) table of the DynamoDB global table.
#
# Replicas are declared as inline replica blocks on the table resource (the
# only mechanism supported by the hashicorp/aws provider). Referencing each
# regional aws_kms_replica_key ARN inside its replica block creates an implicit
# dependency so the regional multi-Region key exists before the replica table
# is provisioned. There is no circular dependency, because each
# aws_kms_replica_key depends only on aws_kms_key.table.
#
# deletion_protection_enabled is a top-level argument of aws_dynamodb_table
# and applies to the primary table; per-replica deletion protection is not
# an expressible argument of the replica block in this provider version.
resource "aws_dynamodb_table" "main" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Streams are a mandatory prerequisite for DynamoDB global tables.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.table.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = var.tags

  # Replica in us-west-2.
  replica {
    region_name            = "us-west-2"
    kms_key_arn            = aws_kms_replica_key.usw2.arn
    point_in_time_recovery = true
    propagate_tags         = true
  }

  # Replica in eu-west-1.
  replica {
    region_name            = "eu-west-1"
    kms_key_arn            = aws_kms_replica_key.euw1.arn
    point_in_time_recovery = true
    propagate_tags         = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege application access scoped strictly to the global table,
# its replicas, and their streams.
resource "aws_iam_policy" "app_global_table_access" {
  name        = "${var.table_name}-application-access"
  description = "Least-privilege application access to the ${var.table_name} DynamoDB global table, its replicas, and their streams"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GlobalTableDataPlaneAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DeleteItem",
          "dynamodb:DescribeTable",
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:UpdateItem",
        ]
        Resource = [
          aws_dynamodb_table.main.arn,
          local.replica_usw2_table_arn,
          local.replica_euw1_table_arn,
        ]
      },
      {
        Sid    = "GlobalTableStreamAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeStream",
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:ListStreams",
        ]
        Resource = [
          aws_dynamodb_table.main.stream_arn,
          local.replica_usw2_stream_arn,
          local.replica_euw1_stream_arn,
        ]
      },
    ]
  })

  tags = var.tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (all have defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "cluster_name" {
  description = "Name of the DAX cluster."
  type        = string
  default     = "dax-cache-cluster"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking (greenfield: everything created in this configuration)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# DynamoDB Gateway endpoint so DAX nodes in private subnets can reach
# DynamoDB without an internet gateway or NAT gateway. Its managed prefix
# list is reused to scope security group egress to DynamoDB traffic only.
resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["dynamodb:*"]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dynamodb-gateway-endpoint"
  })
}

# ---------------------------------------------------------------------------
# Security group: DAX client traffic on port 8111 from the VPC CIDR only
# ---------------------------------------------------------------------------

resource "aws_security_group" "dax" {
  name        = "${var.environment}-dax-sg"
  description = "Allow inbound DAX client traffic on port 8111 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint port (8111) from the VPC CIDR only"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS to DynamoDB through the DynamoDB gateway endpoint prefix list"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.dynamodb.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-sg"
  })
}

# ---------------------------------------------------------------------------
# IAM: role trusted only by the DAX service, with least-privilege DynamoDB access
# ---------------------------------------------------------------------------

resource "aws_iam_role" "dax" {
  name = "${var.environment}-dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-dax-role"
  })
}

resource "aws_iam_role_policy" "dax_dynamodb_access" {
  name = "${var.environment}-dax-dynamodb-access"
  role = aws_iam_role.dax.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:BatchGetItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:PutItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          "arn:aws:dynamodb:*:*:table/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# DAX subnet group and cluster
# Note: aws_dax_subnet_group does not support tagging in the provider schema,
# so environment traceability is embedded in its name and description.
# ---------------------------------------------------------------------------

resource "aws_dax_subnet_group" "dax" {
  name        = "${var.environment}-dax-subnet-group"
  description = "Private subnets for the ${var.environment} DAX cluster"
  subnet_ids  = aws_subnet.private[*].id
}

resource "aws_dax_cluster" "main" {
  cluster_name       = var.cluster_name
  node_type          = "dax.r4.large"
  replication_factor = 1
  iam_role_arn       = aws_iam_role.dax.arn
  subnet_group_name  = aws_dax_subnet_group.dax.name
  security_group_ids = [aws_security_group.dax.id]

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = var.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [
    aws_iam_role_policy.dax_dynamodb_access,
    aws_vpc_endpoint.dynamodb
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = var.environment
    }
  }
}

variable "environment" {
  description = "Environment name applied via provider default_tags to taggable resources (non-taggable resources ignore it)."
  type        = string
  default     = "dev"
}

locals {
  dax_parameter_group_name = "custom-dax-params"
}

resource "aws_dax_parameter_group" "custom" {
  name        = local.dax_parameter_group_name
  description = "Custom DAX parameter group with tuned query and record cache TTLs."

  parameters {
    name  = "query-ttl-millis"
    value = "100000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "100000"
  }
}

output "dax_parameter_group_name" {
  description = "Name of the custom DAX parameter group, for reference by a future aws_dax_cluster."
  value       = aws_dax_parameter_group.custom.name
}

output "dax_parameter_group_id" {
  description = "ID of the custom DAX parameter group, for reference by a future aws_dax_cluster."
  value       = aws_dax_parameter_group.custom.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

variable "environment" {
  description = "Environment label applied to all resources via tags."
  type        = string
  default     = "production"

  validation {
    condition     = can(regex("^[a-z0-9-]+$", var.environment))
    error_message = "Environment must contain only lowercase letters, numbers, and hyphens."
  }
}

variable "dax_subnet_group_name" {
  description = "Name of the DAX subnet group. Must satisfy DAX naming rules (lowercase alphanumeric and hyphens only, no underscores)."
  type        = string
  default     = "dax-subnet-group-main"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,49}$", var.dax_subnet_group_name))
    error_message = "DAX subnet group name must start with a lowercase letter, contain only lowercase alphanumeric characters and hyphens (no underscores), and be 50 characters or fewer."
  }
}

variable "dax_private_subnets" {
  description = "Map of private subnets for DAX nodes. Each entry defines a CIDR within the VPC and an index into the available AZ list."
  type = map(object({
    cidr_block = string
    az_index   = number
  }))
  default = {
    a = {
      cidr_block = "10.0.1.0/24"
      az_index   = 0
    }
    b = {
      cidr_block = "10.0.2.0/24"
      az_index   = 1
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "dax-${var.environment}"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "dax_private" {
  for_each = var.dax_private_subnets

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = data.aws_availability_zones.available.names[each.value.az_index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dax_subnet_group" "main" {
  name        = var.dax_subnet_group_name
  description = "Private subnet group for DAX cluster nodes in ${var.environment}"
  subnet_ids  = [for subnet in aws_subnet.dax_private : subnet.id]

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_subnet_group_name" {
  description = "Name of the DAX subnet group."
  value       = aws_dax_subnet_group.main.name
}

output "dax_private_subnet_ids" {
  description = "IDs of the private subnets backing the DAX subnet group."
  value       = [for subnet in aws_subnet.dax_private : subnet.id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  type        = string
  description = "Environment tag value applied to the DynamoDB table."
  default     = "dev"
}

variable "table_name" {
  type        = string
  description = "Name of the DynamoDB table."
  default     = "app-data"
}

locals {
  common_tags = {
    Name        = var.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_dynamodb_table" "main" {
  name         = var.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table."
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.tags
  }
}

#------------------------------------------------------------------------------
# User-controlled inputs (all with defaults so terraform apply is non-interactive)
#------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "domain_name_prefix" {
  description = "Prefix used when composing the SageMaker domain name."
  type        = string
  default     = "ml"
}

variable "owner" {
  description = "Value recorded in the Owner tag on every resource."
  type        = string
  default     = "platform-team"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated SageMaker VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "default_ebs_volume_size_gb" {
  description = "Default EBS volume size (GB) for SageMaker user spaces."
  type        = number
  default     = 10

  validation {
    condition     = var.default_ebs_volume_size_gb >= 1 && var.default_ebs_volume_size_gb <= 16384
    error_message = "Default EBS volume size must be between 1 and 16384 GB."
  }
}

variable "max_ebs_volume_size_gb" {
  description = "Maximum EBS volume size (GB) a user may resize their space volume to. Must be strictly greater than the default size."
  type        = number
  default     = 30

  validation {
    condition     = var.max_ebs_volume_size_gb > var.default_ebs_volume_size_gb
    error_message = "Maximum EBS volume size must be strictly greater than the default EBS volume size."
  }
}

variable "tags" {
  description = "Additional tags merged into the shared tag map."
  type        = map(string)
  default     = {}
}

#------------------------------------------------------------------------------
# Shared locals and consistent tagging
#------------------------------------------------------------------------------

locals {
  name_prefix = "${var.domain_name_prefix}-${var.environment}"
  domain_name = "${local.name_prefix}-domain"

  common_tags = {
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }

  tags = merge(local.common_tags, var.tags)
}

#------------------------------------------------------------------------------
# Static provider metadata lookups (well-known, no dependency on remote state)
#------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Dedicated networking for VpcOnly operation
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-${count.index + 1}" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "sagemaker_domain" {
  name        = "${local.name_prefix}-sagemaker-domain-sg"
  description = "SageMaker domain VpcOnly traffic: only intra-domain (self-referencing) ingress."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Intra-domain traffic between SageMaker apps, the home EFS mount targets and VPC endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Outbound to SageMaker services, the home EFS and VPC endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-domain-sg" })
}

#------------------------------------------------------------------------------
# VPC endpoints required for VpcOnly operation
#------------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.tags, { Name = "${local.name_prefix}-s3-gateway-endpoint" })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset([
    "sagemaker.api",
    "sagemaker.runtime",
    "sts",
    "logs",
  ])

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.sagemaker_domain.id]
  private_dns_enabled = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-${each.value}-endpoint" })
}

#------------------------------------------------------------------------------
# Customer managed KMS key for domain home-directory EFS and EBS encryption
#------------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_kms_key" {
  statement {
    sid    = "EnableAccountIAMPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:Create*",
      "kms:Decrypt",
      "kms:Delete*",
      "kms:Describe*",
      "kms:Disable*",
      "kms:Enable*",
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:Get*",
      "kms:List*",
      "kms:Put*",
      "kms:ReEncrypt*",
      "kms:RetireGrant",
      "kms:Revoke*",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:Update*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSageMakerServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }

    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sagemaker.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowAccountPrincipalsViaElasticFileSystem"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "sagemaker" {
  description             = "Customer managed key used to encrypt SageMaker domain home-directory EFS and EBS storage."
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sagemaker_kms_key.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-kms-key" })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# S3 artifact bucket (scoping target for the execution role's S3 permissions)
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket = "${local.name_prefix}-sagemaker-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.sagemaker.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

#------------------------------------------------------------------------------
# Default execution role for the SageMaker domain
#------------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    sid    = "AllowSageMakerServiceToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_execution" {
  name               = "${local.name_prefix}-sagemaker-execution"
  description        = "Default execution role for the SageMaker domain."
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume_role.json

  tags = merge(local.tags, { Name = "${local.name_prefix}-sagemaker-execution" })
}

data "aws_iam_policy_document" "sagemaker_api_access" {
  statement {
    sid    = "SageMakerApiAccess"
    effect = "Allow"

    actions = [
      "sagemaker:CreateApp",
      "sagemaker:CreatePresignedDomainUrl",
      "sagemaker:DeleteApp",
      "sagemaker:DescribeApp",
      "sagemaker:DescribeAppImageConfig",
      "sagemaker:DescribeDomain",
      "sagemaker:DescribeImage",
      "sagemaker:DescribeImageVersion",
      "sagemaker:DescribeSpace",
      "sagemaker:DescribeStudioLifecycleConfig",
      "sagemaker:DescribeUserProfile",
      "sagemaker:ListApps",
      "sagemaker:ListAppImageConfigs",
      "sagemaker:ListDomains",
      "sagemaker:ListImages",
      "sagemaker:ListImageVersions",
      "sagemaker:ListSpaces",
      "sagemaker:ListStudioLifecycleConfigs",
      "sagemaker:ListUserProfiles",
      "sagemaker:Search",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "sagemaker_cloudwatch_logs" {
  statement {
    sid    = "SageMakerCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*:log-stream:*",
    ]
  }
}

data "aws_iam_policy_document" "sagemaker_s3_access" {
  statement {
    sid    = "SageMakerArtifactsBucketList"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.sagemaker_artifacts.arn]
  }

  statement {
    sid    = "SageMakerArtifactsBucketObjects"
    effect = "Allow"

    actions = [
      "s3:AbortMultipartUpload",
      "s3:DeleteObject",
      "s3:GetObject",
      "s3:ListMultipartUploadParts",
      "s3:PutObject",
    ]

    resources = ["${aws_s3_bucket.sagemaker_artifacts.arn}/*"]
  }
}

data "aws_iam_policy_document" "sagemaker_kms_access" {
  statement {
    sid    = "SageMakerKeyUsage"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.sagemaker.arn]
  }
}

resource "aws_iam_policy" "sagemaker_api_access" {
  name        = "${local.name_prefix}-sagemaker-api-access"
  description = "Least-privilege SageMaker API access for the SageMaker domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_api_access.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_cloudwatch_logs" {
  name        = "${local.name_prefix}-sagemaker-cloudwatch-logs"
  description = "CloudWatch Logs permissions required by the SageMaker domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_cloudwatch_logs.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_s3_access" {
  name        = "${local.name_prefix}-sagemaker-s3-access"
  description = "S3 access scoped to the SageMaker artifacts bucket for the domain execution role."
  policy      = data.aws_iam_policy_document.sagemaker_s3_access.json

  tags = local.tags
}

resource "aws_iam_policy" "sagemaker_kms_access" {
  name        = "${local.name_prefix}-sagemaker-kms-access"
  description = "KMS decrypt/data-key permissions scoped to the SageMaker domain key."
  policy      = data.aws_iam_policy_document.sagemaker_kms_access.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_api_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_api_access.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_cloudwatch_logs" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_cloudwatch_logs.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_s3_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_s3_access.arn
}

resource "aws_iam_role_policy_attachment" "sagemaker_kms_access" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_kms_access.arn
}

#------------------------------------------------------------------------------
# SageMaker domain
#------------------------------------------------------------------------------

resource "aws_sagemaker_domain" "sagemaker_domain" {
  domain_name                   = local.domain_name
  auth_mode                     = "IAM"
  app_network_access_type       = "VpcOnly"
  app_security_group_management = "Customer"
  vpc_id                        = aws_vpc.main.id
  subnet_ids                    = aws_subnet.private[*].id
  kms_key_id                    = aws_kms_key.sagemaker.arn

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker_domain.id]

    space_storage_settings {
      default_ebs_storage_settings {
        default_ebs_volume_size_in_gb = var.default_ebs_volume_size_gb
        maximum_ebs_volume_size_in_gb = var.max_ebs_volume_size_gb
      }
    }

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  tags = merge(local.tags, { Name = local.domain_name })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Outputs for downstream consumption
#------------------------------------------------------------------------------

output "sagemaker_domain_id" {
  description = "ID of the SageMaker domain."
  value       = aws_sagemaker_domain.sagemaker_domain.id
}

output "sagemaker_domain_arn" {
  description = "ARN of the SageMaker domain."
  value       = aws_sagemaker_domain.sagemaker_domain.arn
}

output "sagemaker_domain_security_group_id" {
  description = "ID of the security group attached to the SageMaker domain."
  value       = aws_security_group.sagemaker_domain.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "user_profile_name" {
  description = "Name of the SageMaker user profile to create inside the domain."
  type        = string
  default     = "data-scientist"

  validation {
    condition     = can(regex("^[a-zA-Z0-9](-*[a-zA-Z0-9]){0,62}$", var.user_profile_name))
    error_message = "user_profile_name must be 1-63 characters: letters, digits, and hyphens only, starting and ending with a letter or digit."
  }
}

variable "tags" {
  description = "Tags applied to all taggable resources in this configuration."
  type        = map(string)
  default = {
    Environment = "dev"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Data sources (static account / provider metadata only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  s3_bucket_name = "sagemaker-app-data-${local.account_id}-${local.region}"

  sagemaker_log_group_arn  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/sagemaker/*"
  sagemaker_log_stream_arn = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/sagemaker/*:log-stream:*"
  ecr_repository_arn       = "arn:${local.partition}:ecr:${local.region}:${local.account_id}:repository/*"
}

# ------------------------------------------------------------------------------
# Networking: dedicated VPC and subnets for the SageMaker domain
# (No IGW/NAT/route tables/endpoints required — app_network_access_type is
# PublicInternetOnly, so the customer VPC carries only domain ENI/EFS traffic.)
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "sagemaker-domain-vpc" })
}

resource "aws_subnet" "main_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = merge(var.tags, { Name = "sagemaker-domain-subnet-a" })
}

resource "aws_subnet" "main_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = merge(var.tags, { Name = "sagemaker-domain-subnet-b" })
}

# ------------------------------------------------------------------------------
# KMS: customer managed key for SageMaker domain storage encryption
# ------------------------------------------------------------------------------

resource "aws_kms_key" "sagemaker_domain" {
  description              = "Customer managed key used to encrypt SageMaker domain and notebook storage."
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days  = 30
  enable_key_rotation      = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMPermissionsForAccount"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = ["kms:*"]
        Resource = ["*"]
      },
      {
        Sid    = "AllowSageMakerServiceToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = ["*"]
      }
    ]
  })

  tags = merge(var.tags, { Name = "sagemaker-domain-encryption" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sagemaker_domain" {
  name          = "alias/sagemaker/domain-encryption"
  target_key_id = aws_kms_key.sagemaker_domain.key_id
}

# ------------------------------------------------------------------------------
# S3: dedicated bucket for SageMaker notebook and app data
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_data" {
  bucket = local.s3_bucket_name

  tags = merge(var.tags, { Name = "sagemaker-app-data" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker_domain.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------------------
# IAM: dedicated SageMaker execution role with least-privilege inline policy
# ------------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name        = "sagemaker-execution-role"
  description = "Least-privilege execution role assumed by SageMaker for the domain and user profiles."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Action = ["sts:AssumeRole"]
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = "sagemaker-execution-role" })
}

resource "aws_iam_role_policy" "sagemaker_execution" {
  name = "sagemaker-execution-least-privilege"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListSageMakerDataBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.sagemaker_data.arn
        ]
      },
      {
        Sid    = "ReadWriteSageMakerDataBucketObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          "${aws_s3_bucket.sagemaker_data.arn}/*"
        ]
      },
      {
        Sid    = "SageMakerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:PutLogEvents"
        ]
        Resource = [
          local.sagemaker_log_group_arn,
          local.sagemaker_log_stream_arn
        ]
      },
      {
        Sid    = "GetECRAuthorizationToken"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken"
        ]
        Resource = ["*"]
      },
      {
        Sid    = "PullECRImages"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = [
          local.ecr_repository_arn
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# SageMaker domain
# ------------------------------------------------------------------------------

resource "aws_sagemaker_domain" "main" {
  domain_name             = "ml-platform-domain"
  auth_mode               = "IAM"
  app_network_access_type = "PublicInternetOnly"
  kms_key_id              = aws_kms_key.sagemaker_domain.arn

  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.main_a.id, aws_subnet.main_b.id]

  retention_policy {
    home_efs_file_system = "Retain"
  }

  default_user_settings {
    execution_role = aws_iam_role.sagemaker_execution.arn

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.micro"
      }
    }

    kernel_gateway_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.medium"
      }
    }
  }

  tags = merge(var.tags, { Name = "ml-platform-domain" })
}

# ------------------------------------------------------------------------------
# SageMaker user profile (inherits the domain's default user settings)
# ------------------------------------------------------------------------------

resource "aws_sagemaker_user_profile" "main" {
  domain_id         = aws_sagemaker_domain.main.id
  user_profile_name = var.user_profile_name

  tags = merge(var.tags, { Name = var.user_profile_name })
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "sagemaker_domain_id" {
  description = "The ID of the SageMaker domain."
  value       = aws_sagemaker_domain.main.id
}

output "sagemaker_user_profile_name" {
  description = "The name of the SageMaker user profile."
  value       = aws_sagemaker_user_profile.main.user_profile_name
}

output "sagemaker_user_profile_arn" {
  description = "The ARN of the SageMaker user profile."
  value       = aws_sagemaker_user_profile.main.arn
}

output "sagemaker_execution_role_arn" {
  description = "The ARN of the IAM execution role used by the SageMaker domain and user profile."
  value       = aws_iam_role.sagemaker_execution.arn
}

# =============================================================================
# SageMaker Studio Domain + Space - Greenfield, VPC-only, CMK-encrypted
# =============================================================================
# - Dedicated VPC with two private subnets in distinct AZs (AZs via data source)
# - No internet path: VpcOnly networking (domain-level), no IGW/NAT,
#   VPC endpoints (S3 gateway + interface endpoints) for AWS service access
# - Customer-managed KMS key for the domain home-directory EFS, domain volumes
#   and S3 artifacts
# - Dedicated, fully-private S3 artifacts bucket (block all public access,
#   SSE-KMS, versioning)
# - Least-privilege SageMaker execution role
# =============================================================================

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Non-infrastructure variables (all defaulted, so `terraform apply` is
# non-interactive)
# -----------------------------------------------------------------------------
variable "resource_name_prefix" {
  description = "Short lowercase prefix applied to all resource names."
  type        = string
  default     = "sm"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,18}$", var.resource_name_prefix))
    error_message = "resource_name_prefix must be 2-19 lowercase letters, digits or hyphens and must start with a letter."
  }
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,18}$", var.environment))
    error_message = "environment must be lowercase letters, digits or hyphens."
  }
}

# -----------------------------------------------------------------------------
# Static, well-known lookups only (no discovery of pre-existing infrastructure)
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.resource_name_prefix}-${var.environment}"

  vpc_cidr = "10.0.0.0/16"

  # SageMaker entity names only allow alphanumerics and hyphens.
  sagemaker_space_name = "ml-workspace"

  interface_endpoint_service_names = [
    "com.amazonaws.${data.aws_region.current.name}.sagemaker.api",
    "com.amazonaws.${data.aws_region.current.name}.sagemaker.runtime",
    "com.amazonaws.${data.aws_region.current.name}.ecr.api",
    "com.amazonaws.${data.aws_region.current.name}.ecr.dkr",
    "com.amazonaws.${data.aws_region.current.name}.logs",
    "com.amazonaws.${data.aws_region.current.name}.monitoring",
    "com.amazonaws.${data.aws_region.current.name}.kms",
    "com.amazonaws.${data.aws_region.current.name}.sts",
  ]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = var.resource_name_prefix
  }
}

# -----------------------------------------------------------------------------
# Network foundation: VPC + two private subnets in distinct AZs
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups: SageMaker apps and VPC endpoints (no 0.0.0.0/0 ingress)
# -----------------------------------------------------------------------------
resource "aws_security_group" "sagemaker" {
  name        = "${local.name_prefix}-sagemaker-sg"
  description = "SageMaker domain and space app traffic restricted to the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS (2049) from the VPC CIDR for the domain-managed home EFS"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS (443) from the VPC CIDR for VPC endpoint access"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "App-to-app communication between SageMaker apps sharing this security group"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All egress restricted to VPC-internal destinations (VPC endpoints, home EFS)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-sg"
  })
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpc-endpoint-sg"
  description = "Interface VPC endpoints reachable only from inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All egress restricted to VPC-internal destinations"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-endpoint-sg"
  })
}

# -----------------------------------------------------------------------------
# VPC endpoints: private connectivity for SageMaker apps (no internet path)
# -----------------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-s3-gateway-endpoint"
  })
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_endpoint_service_names)

  vpc_id              = aws_vpc.main.id
  service_name        = each.value
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-endpoint-${each.key}"
  })
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key for SageMaker storage (domain home-directory EFS,
# domain volumes and S3 artifacts)
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sagemaker" {
  description             = "Customer managed key for SageMaker home-directory EFS, domain volumes and S3 artifacts"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMDelegationForAccount"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowSageMakerService"
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey",
          "kms:ReEncrypt*",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-kms"
  })
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/${local.name_prefix}-sagemaker"
  target_key_id = aws_kms_key.sagemaker.key_id
}

# -----------------------------------------------------------------------------
# Private S3 bucket for SageMaker artifacts
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "artifacts" {
  bucket = "${local.name_prefix}-sagemaker-artifacts-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-artifacts"
  })
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# SageMaker execution role (trusted by sagemaker.amazonaws.com) with
# least-privilege permissions
# -----------------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_execution" {
  name = "${local.name_prefix}-sagemaker-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-execution-role"
  })
}

resource "aws_iam_role_policy" "sagemaker_execution" {
  name = "sagemaker-execution-least-privilege"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ArtifactAccess"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
        ]
      },
      {
        Sid    = "CloudWatchLogsForSageMaker"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*:log-stream:*",
        ]
      },
      {
        Sid      = "ECRGetAuthorizationToken"
        Effect   = "Allow"
        Action   = "ecr:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "ECRPullImages"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:ecr:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:repository/*",
        ]
      },
    ]
  })
}

resource "aws_iam_policy" "sagemaker_storage_keys" {
  name        = "${local.name_prefix}-sagemaker-storage-keys"
  description = "KMS data key usage for SageMaker storage (home EFS and S3 artifacts)"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KmsDataKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
        ]
        Resource = [
          aws_kms_key.sagemaker.arn,
        ]
      },
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-storage-keys"
  })
}

resource "aws_iam_role_policy_attachment" "sagemaker_storage_keys" {
  role       = aws_iam_role.sagemaker_execution.name
  policy_arn = aws_iam_policy.sagemaker_storage_keys.arn
}

# -----------------------------------------------------------------------------
# SageMaker Studio domain: IAM auth, VPC-only networking, CMK-encrypted
# storage. Network isolation is enforced by app_network_access_type = "VpcOnly"
# together with the private-subnet topology (no internet gateway, no NAT
# gateway, AWS service access only via VPC endpoints).
# -----------------------------------------------------------------------------
resource "aws_sagemaker_domain" "main" {
  domain_name = "${local.name_prefix}-domain"
  auth_mode   = "IAM"

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  app_network_access_type = "VpcOnly"

  # Encrypts the domain home EFS file system and domain volumes with the CMK
  kms_key_id = aws_kms_key.sagemaker.arn

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-domain"
  })
}

# -----------------------------------------------------------------------------
# Default user profile for the domain (owner of the space below)
# -----------------------------------------------------------------------------
resource "aws_sagemaker_user_profile" "default" {
  domain_id         = aws_sagemaker_domain.main.id
  user_profile_name = "default-user"

  user_settings {
    execution_role  = aws_iam_role.sagemaker_execution.arn
    security_groups = [aws_security_group.sagemaker.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-default-user"
  })
}

# -----------------------------------------------------------------------------
# SageMaker space: JupyterServer app with EBS-backed space storage (the only
# storage mechanism the provider supports for spaces; the app's EBS volume is
# encrypted by the SageMaker service, while the domain's home-directory EFS
# is encrypted with the CMK via aws_sagemaker_domain.main.kms_key_id).
# Network access is inherited from the domain (VpcOnly) and the app security
# group only permits traffic inside the VPC, so notebooks have no public
# internet path.
# -----------------------------------------------------------------------------
resource "aws_sagemaker_space" "ml_workspace" {
  domain_id  = aws_sagemaker_domain.main.id
  space_name = local.sagemaker_space_name

  ownership_settings {
    owner_user_profile_name = aws_sagemaker_user_profile.default.user_profile_name
  }

  space_sharing_settings {
    sharing_type = "Private"
  }

  space_settings {
    app_type = "JupyterServer"

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "system"
      }
    }

    space_storage_settings {
      ebs_storage_settings {
        ebs_volume_size_in_gb = 5
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-space-${local.sagemaker_space_name}"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "sagemaker_domain_id" {
  description = "ID of the SageMaker Studio domain."
  value       = aws_sagemaker_domain.main.id
}

output "sagemaker_domain_arn" {
  description = "ARN of the SageMaker Studio domain."
  value       = aws_sagemaker_domain.main.arn
}

output "sagemaker_space_arn" {
  description = "ARN of the SageMaker space."
  value       = aws_sagemaker_space.ml_workspace.arn
}

output "sagemaker_artifacts_bucket" {
  description = "Name of the private S3 bucket holding SageMaker artifacts."
  value       = aws_s3_bucket.artifacts.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "sagemaker-studio"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = {
    Environment = var.environment
    Project     = var.project
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ----------------------------------------------------------------------------
# Networking
# ----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "sagemaker" {
  name        = "${local.name_prefix}-sagemaker-sg"
  description = "SageMaker Studio apps - HTTPS ingress from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Self-referencing rule for traffic between SageMaker apps sharing this security group"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-sg"
  })
}

# ----------------------------------------------------------------------------
# S3 bucket for SageMaker notebook artifacts
# ----------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_data" {
  bucket = "${local.name_prefix}-data-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-data"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "sagemaker_data_tls" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.sagemaker_data.arn,
      "${aws_s3_bucket.sagemaker_data.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "sagemaker_data" {
  bucket = aws_s3_bucket.sagemaker_data.id
  policy = data.aws_iam_policy_document.sagemaker_data_tls.json

  depends_on = [aws_s3_bucket_public_access_block.sagemaker_data]
}

# ----------------------------------------------------------------------------
# SageMaker execution IAM role
# ----------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_assume_role" {
  statement {
    sid    = "AllowSageMakerToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "sagemaker_exec" {
  name               = "${local.name_prefix}-sagemaker-exec"
  description        = "Execution role for SageMaker Studio JupyterServer apps"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sagemaker-exec-role"
  })
}

resource "aws_iam_role_policy" "sagemaker_exec" {
  name = "${local.name_prefix}-sagemaker-exec-policy"
  role = aws_iam_role.sagemaker_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SageMakerDataBucketAccess"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [aws_s3_bucket.sagemaker_data.arn, "${aws_s3_bucket.sagemaker_data.arn}/*"]
      },
      {
        Sid      = "SageMakerCloudWatchLogs"
        Effect   = "Allow"
        Action   = ["logs:CreateLogGroup", "logs:CreateLogStream", "logs:PutLogEvents"]
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"
      },
      {
        Sid      = "SageMakerDescribeAccess"
        Effect   = "Allow"
        Action   = ["sagemaker:Describe*"]
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------------
# SageMaker Studio domain (hard prerequisite of the JupyterServer app)
# ----------------------------------------------------------------------------

resource "aws_sagemaker_domain" "studio" {
  domain_name             = "${local.name_prefix}-domain"
  auth_mode               = "IAM"
  app_network_access_type = "VpcOnly"
  vpc_id                  = aws_vpc.main.id
  subnet_ids              = aws_subnet.private[*].id

  default_user_settings {
    execution_role  = aws_iam_role.sagemaker_exec.arn
    security_groups = [aws_security_group.sagemaker.id]

    jupyter_server_app_settings {
      default_resource_spec {
        instance_type = "ml.t3.medium"
      }
    }
  }

  retention_policy {
    home_efs_file_system = "Retain"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-domain"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------
# SageMaker user profile (owner of the JupyterServer app)
# ----------------------------------------------------------------------------

resource "aws_sagemaker_user_profile" "studio_user" {
  domain_id         = aws_sagemaker_domain.studio.id
  user_profile_name = "studio-user"

  user_settings {
    execution_role = aws_iam_role.sagemaker_exec.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-profile"
  })
}

# ----------------------------------------------------------------------------
# SageMaker JupyterServer app
# ----------------------------------------------------------------------------

resource "aws_sagemaker_app" "jupyter_server" {
  domain_id         = aws_sagemaker_domain.studio.id
  user_profile_name = aws_sagemaker_user_profile.studio_user.user_profile_name
  app_type          = "JupyterServer"
  app_name          = "default"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-jupyter-server"
  })
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "jupyter_server_app_arn" {
  description = "ARN of the SageMaker JupyterServer app."
  value       = aws_sagemaker_app.jupyter_server.arn
}

output "sagemaker_domain_id" {
  description = "ID of the SageMaker Studio domain hosting the JupyterServer app."
  value       = aws_sagemaker_domain.studio.id
}

output "sagemaker_user_profile_name" {
  description = "User profile name that owns the JupyterServer app."
  value       = aws_sagemaker_user_profile.studio_user.user_profile_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to the SageMaker code repository. Defaults are safe so terraform apply runs non-interactively."
  type        = map(string)
  default = {
    Name        = "terraform-provider-aws"
    Environment = "production"
  }
}

resource "aws_sagemaker_code_repository" "this" {
  code_repository_name = "terraform-provider-aws"

  git_config {
    # Public repository: no secret_arn or Git credentials configured.
    repository_url = "https://github.com/hashicorp/terraform-provider-aws.git"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "code_repository_name" {
  description = "Name of the SageMaker code repository."
  value       = aws_sagemaker_code_repository.this.code_repository_name
}

output "code_repository_arn" {
  description = "ARN of the SageMaker code repository."
  value       = aws_sagemaker_code_repository.this.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values, all with defaults)
# -----------------------------------------------------------------------------

variable "image_display_name" {
  description = "Human-readable display name for the SageMaker image shown in Studio."
  type        = string
  default     = "Studio Custom Image"
}

variable "environment" {
  description = "Environment tag applied to all resources."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into the common tag set for all resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Static provider metadata lookups (pure local, no dependency on remote state)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  project_name = "sagemaker-studio-image"

  # Deployment region constant — matches the region pinned in the provider block.
  aws_region = "us-east-1"

  # SageMaker image names allow alphanumeric characters and hyphens only,
  # with a maximum length of 63 characters.
  image_name = "studio-custom-image"

  common_tags = merge(
    {
      Environment = var.environment
      Project     = local.project_name
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

# -----------------------------------------------------------------------------
# ECR repository hosting the SageMaker base container image
# -----------------------------------------------------------------------------

resource "aws_ecr_repository" "sagemaker_base" {
  name                 = "sagemaker-studio-base-image"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "KMS"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "sagemaker_base" {
  repository = aws_ecr_repository.sagemaker_base.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Keep only the 10 most recent versioned (v*) images"
        selection = {
          tagStatus      = "tagged"
          tagPatternList = ["v*"]
          countType      = "imageCountMoreThan"
          countNumber    = 10
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM role assumed by SageMaker for the image
# -----------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_image_role" {
  name        = "sagemaker-studio-image-role"
  description = "Execution role assumed by SageMaker for the Studio custom image"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Least-privilege ECR pull permissions scoped to the in-file ECR repository
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "sagemaker_ecr_pull" {
  name        = "sagemaker-studio-image-ecr-pull"
  description = "Least-privilege ECR pull access scoped to the SageMaker base image repository"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "EcrGetAuthorizationToken"
        Effect   = "Allow"
        Action   = "ecr:GetAuthorizationToken"
        Resource = "*"
      },
      {
        Sid    = "EcrPullBaseImage"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = aws_ecr_repository.sagemaker_base.arn
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_ecr_pull" {
  role       = aws_iam_role.sagemaker_image_role.name
  policy_arn = aws_iam_policy.sagemaker_ecr_pull.arn
}

# -----------------------------------------------------------------------------
# Least-privilege CloudWatch Logs write permissions scoped to SageMaker log groups
# -----------------------------------------------------------------------------

resource "aws_iam_policy" "sagemaker_logs_write" {
  name        = "sagemaker-studio-image-logs-write"
  description = "Least-privilege CloudWatch Logs write access scoped to SageMaker log group ARN prefixes"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerLogGroupWrites"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:/aws/sagemaker/*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_logs_write" {
  role       = aws_iam_role.sagemaker_image_role.name
  policy_arn = aws_iam_policy.sagemaker_logs_write.arn
}

# -----------------------------------------------------------------------------
# SageMaker Image and Image Version
# -----------------------------------------------------------------------------

resource "aws_sagemaker_image" "studio_image" {
  image_name   = local.image_name
  display_name = var.image_display_name
  description  = "Custom SageMaker Studio image hosted in the project ECR repository"
  role_arn     = aws_iam_role.sagemaker_image_role.arn

  tags = local.common_tags
}

resource "aws_sagemaker_image_version" "v1" {
  image_name = aws_sagemaker_image.studio_image.image_name
  base_image = "${aws_ecr_repository.sagemaker_base.repository_url}:v1"

  depends_on = [
    aws_iam_role_policy_attachment.sagemaker_ecr_pull,
    aws_iam_role_policy_attachment.sagemaker_logs_write
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "sagemaker_image" {
  description = "AWS-managed SageMaker built-in kmeans algorithm container image (us-east-1). Overridable, but defaults to a working value so apply runs unattended."
  type        = string
  default     = "382416733822.dkr.ecr.us-east-1.amazonaws.com/kmeans:1"
}

variable "tags" {
  description = "Tags applied to all taggable resources. Contains no secrets or environment-specific values."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Component = "sagemaker-kmeans-model"
  }
}

resource "aws_iam_role" "sagemaker_model_execution_role" {
  name = "sagemaker-kmeans-model-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "sagemaker_model_execution_policy" {
  name = "sagemaker-kmeans-model-execution-policy"
  role = aws_iam_role.sagemaker_model_execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerECRImagePull"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Sid    = "SageMakerCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/sagemaker/*"
      },
      {
        Sid    = "SageMakerModelArtifactsRead"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::*",
          "arn:aws:s3:::*/*"
        ]
      }
    ]
  })
}

resource "aws_sagemaker_model" "kmeans_model" {
  execution_role_arn       = aws_iam_role.sagemaker_model_execution_role.arn
  enable_network_isolation = true

  primary_container {
    image = var.sagemaker_image
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "sagemaker_model_name" {
  description = "Name of the SageMaker kmeans model."
  value       = aws_sagemaker_model.kmeans_model.name
}

output "sagemaker_model_arn" {
  description = "ARN of the SageMaker kmeans model."
  value       = aws_sagemaker_model.kmeans_model.arn
}

output "sagemaker_execution_role_arn" {
  description = "ARN of the SageMaker model execution role."
  value       = aws_iam_role.sagemaker_model_execution_role.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "User-controlled environment name applied as a tag to all resources."
  type        = string
  default     = "dev"
}

variable "project" {
  description = "User-controlled project name applied as a tag to all resources."
  type        = string
  default     = "sagemaker-notebooks"
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }
}

resource "random_string" "suffix" {
  length  = 8
  upper   = false
  special = false
}

# ------------------------------------------------------------------
# IAM execution role for the SageMaker notebook instance
# ------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_notebook_execution" {
  name        = "sagemaker-notebook-execution-${random_string.suffix.result}"
  description = "Execution role assumed by the SageMaker service for the notebook instance."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# ------------------------------------------------------------------
# Least-privilege SageMaker + S3 permissions policy
# ------------------------------------------------------------------
resource "aws_iam_policy" "sagemaker_notebook_execution" {
  name        = "sagemaker-notebook-execution-policy-${random_string.suffix.result}"
  description = "Least-privilege SageMaker and S3 permissions for the notebook instance execution role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageThisNotebookInstance"
        Effect = "Allow"
        Action = [
          "sagemaker:DescribeNotebookInstance",
          "sagemaker:StartNotebookInstance",
          "sagemaker:StopNotebookInstance",
          "sagemaker:UpdateNotebookInstance",
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListTags"
        ]
        Resource = "arn:aws:sagemaker:us-east-1:*:notebook-instance/*"
      },
      {
        Sid      = "ListNotebookArtifactBucket"
        Effect   = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = aws_s3_bucket.notebook_artifacts.arn
      },
      {
        Sid    = "ReadWriteNotebookArtifacts"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = "${aws_s3_bucket.notebook_artifacts.arn}/*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "sagemaker_notebook_execution" {
  role       = aws_iam_role.sagemaker_notebook_execution.name
  policy_arn = aws_iam_policy.sagemaker_notebook_execution.arn
}

# ------------------------------------------------------------------
# Dedicated private S3 bucket for notebook artifacts
# ------------------------------------------------------------------
resource "aws_s3_bucket" "notebook_artifacts" {
  bucket = "sagemaker-notebook-artifacts-${random_string.suffix.result}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ------------------------------------------------------------------
# Customer managed KMS key for the notebook ML storage volume
# ------------------------------------------------------------------
resource "aws_kms_key" "notebook_volume" {
  description             = "Encrypts the ML storage volume attached to the SageMaker notebook instance."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "notebook_volume" {
  name          = "alias/sagemaker-notebook-volume-${random_string.suffix.result}"
  target_key_id = aws_kms_key.notebook_volume.key_id
}

# ------------------------------------------------------------------
# SageMaker notebook instance (AWS-managed networking mode:
# subnet_id and security_group_ids intentionally omitted)
# ------------------------------------------------------------------
resource "aws_sagemaker_notebook_instance" "ml_t2_medium_notebook" {
  name          = "ml-t2-medium-notebook-${random_string.suffix.result}"
  role_arn      = aws_iam_role.sagemaker_notebook_execution.arn
  instance_type = "ml.t2.medium"
  kms_key_id    = aws_kms_key.notebook_volume.arn
  root_access   = "Disabled"

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.sagemaker_notebook_execution]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "instance_type" {
  description = "EC2 instance type for the SageMaker notebook instance."
  type        = string
  default     = "ml.t3.medium"
}

variable "volume_size" {
  description = "Size in GB of the EBS root volume attached to the notebook instance."
  type        = number
  default     = 50

  validation {
    condition     = var.volume_size >= 20 && var.volume_size <= 16384
    error_message = "Notebook volume size must be between 20 and 16384 GB."
  }
}

variable "tags" {
  description = "Consistent tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
    Owner       = "platform-team"
    Project     = "sagemaker-terraform-provider-aws"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Networking: VPC, subnets, routing, NAT, and S3 gateway endpoint
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "sagemaker-notebook-vpc" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(var.tags, { Name = "sagemaker-public-${count.index + 1}" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "sagemaker-private-${count.index + 1}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-internet-gateway" })
}

resource "aws_eip" "nat" {
  count  = 2
  domain = "vpc"

  tags = merge(var.tags, { Name = "sagemaker-nat-eip-${count.index + 1}" })
}

resource "aws_nat_gateway" "main" {
  count         = 2
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, { Name = "sagemaker-nat-gateway-${count.index + 1}" })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-public-route-table" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count  = 2
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, { Name = "sagemaker-private-route-table-${count.index + 1}" })
}

resource "aws_route" "private_nat" {
  count                  = 2
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(var.tags, { Name = "sagemaker-s3-gateway-endpoint" })
}

# -----------------------------------------------------------------------------
# Security group: self-referencing 443/8443 ingress only, HTTPS-only egress
# -----------------------------------------------------------------------------

resource "aws_security_group" "sagemaker_notebook" {
  name        = "sagemaker-notebook-sg"
  description = "SageMaker notebook instance security group: self-referencing TCP 443/8443 ingress, TCP 443-only egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS from within the security group (required for in-VPC SageMaker service calls)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    self        = true
  }

  ingress {
    description = "Port 8443 from within the security group (required for in-VPC SageMaker service calls)"
    from_port   = 8443
    to_port     = 8443
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "HTTPS egress only (enables git clone of the default code repository via NAT)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "sagemaker-notebook-sg" })
}

# -----------------------------------------------------------------------------
# KMS: customer-managed key for notebook volume and S3 artifacts
# -----------------------------------------------------------------------------

resource "aws_kms_key" "notebook" {
  description              = "Encrypts the SageMaker notebook instance root volume and S3 notebook artifacts"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true
  deletion_window_in_days  = 30

  tags = merge(var.tags, { Name = "sagemaker-notebook-kms-key" })
}

resource "aws_kms_alias" "notebook" {
  name          = "alias/sagemaker-notebook-key"
  target_key_id = aws_kms_key.notebook.key_id
}

# -----------------------------------------------------------------------------
# IAM: least-privilege notebook execution role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name = "sagemaker-notebook-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "sagemaker.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "sagemaker_notebook_artifacts" {
  name = "sagemaker-notebook-artifacts-access"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListNotebookArtifactsBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.notebook_artifacts.arn
      },
      {
        Sid      = "ReadWriteNotebookArtifactsObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:PutObject"]
        Resource = "${aws_s3_bucket.notebook_artifacts.arn}/*"
      },
      {
        Sid      = "NotebookVolumeAndArtifactKmsUsage"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = aws_kms_key.notebook.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# S3: dedicated, private, versioned, SSE-KMS encrypted artifacts bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "notebook_artifacts" {
  bucket = "sagemaker-notebook-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(var.tags, { Name = "sagemaker-notebook-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.notebook.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "notebook_artifacts" {
  bucket = aws_s3_bucket.notebook_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# SageMaker: code repository and VPC-isolated notebook instance
# -----------------------------------------------------------------------------

resource "aws_sagemaker_code_repository" "terraform_provider_aws" {
  code_repository_name = "terraform-provider-aws"

  git_config {
    repository_url = "https://github.com/hashicorp/terraform-provider-aws.git"
  }

  tags = var.tags
}

resource "aws_sagemaker_notebook_instance" "terraform_provider_aws" {
  name                    = "terraform-provider-aws-notebook"
  role_arn                = aws_iam_role.sagemaker_execution.arn
  instance_type           = var.instance_type
  volume_size             = var.volume_size
  subnet_id               = aws_subnet.private[0].id
  security_groups         = toset([aws_security_group.sagemaker_notebook.id])
  kms_key_id              = aws_kms_key.notebook.arn
  direct_internet_access  = "Disabled"
  default_code_repository = aws_sagemaker_code_repository.terraform_provider_aws.arn

  tags = merge(var.tags, { Name = "terraform-provider-aws-notebook" })

  depends_on = [
    aws_iam_role_policy.sagemaker_notebook_artifacts,
    aws_nat_gateway.main,
    aws_vpc_endpoint.s3_gateway,
    aws_route_table_association.private,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "notebook_instance_name" {
  description = "Name of the SageMaker notebook instance."
  value       = aws_sagemaker_notebook_instance.terraform_provider_aws.name
}

output "notebook_instance_arn" {
  description = "ARN of the SageMaker notebook instance."
  value       = aws_sagemaker_notebook_instance.terraform_provider_aws.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (permitted pure-local data sources)
# ---------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Variables (all with defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  artifacts_bucket_name = "sagemaker-artifacts-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"
}

# ---------------------------------------------------------------------------
# Artifacts bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "sagemaker_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = {
    Name        = local.artifacts_bucket_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "sagemaker_artifacts" {
  bucket = aws_s3_bucket.sagemaker_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# ---------------------------------------------------------------------------
# Execution IAM role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "sagemaker_pipeline_trust" {
  statement {
    sid     = "AllowSageMakerToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sagemaker.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "sagemaker_pipeline_execution" {
  name               = "sagemaker-pipeline-execution-role"
  description        = "Execution role assumed by SageMaker for pipeline execution"
  assume_role_policy = data.aws_iam_policy_document.sagemaker_pipeline_trust.json

  tags = {
    Name        = "sagemaker-pipeline-execution-role"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "sagemaker_pipeline_execution" {
  statement {
    sid       = "ListArtifactsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.sagemaker_artifacts.arn]
  }

  statement {
    sid    = "ReadWriteArtifactsObjects"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]
    resources = ["${aws_s3_bucket.sagemaker_artifacts.arn}/*"]
  }

  statement {
    sid    = "SageMakerCloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = ["arn:aws:logs:*:*:log-group:/aws/sagemaker/*"]
  }
}

resource "aws_iam_policy" "sagemaker_pipeline_execution" {
  name        = "sagemaker-pipeline-execution-policy"
  description = "Least-privilege permissions for the SageMaker pipeline execution role"
  policy      = data.aws_iam_policy_document.sagemaker_pipeline_execution.json

  tags = {
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "sagemaker_pipeline_execution" {
  role       = aws_iam_role.sagemaker_pipeline_execution.name
  policy_arn = aws_iam_policy.sagemaker_pipeline_execution.arn
}

# ---------------------------------------------------------------------------
# SageMaker Pipeline
# ---------------------------------------------------------------------------

resource "aws_sagemaker_pipeline" "ml_pipeline" {
  pipeline_name         = "ml-pipeline"
  pipeline_display_name = "ML-Pipeline"
  pipeline_description  = "SageMaker pipeline orchestrating workflow steps, seeded with a Pass step"

  role_arn = aws_iam_role.sagemaker_pipeline_execution.arn

  pipeline_definition = jsonencode({
    Version = "2020-12-01"
    Steps = [
      {
        Name = "PassStep"
        Type = "Pass"
      }
    ]
  })

  parallelism_configuration {
    max_parallel_execution_steps = 5
  }

  tags = {
    Name        = "ml-pipeline"
    Environment = var.environment
  }

  depends_on = [aws_iam_role_policy_attachment.sagemaker_pipeline_execution]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "pipeline_arn" {
  description = "ARN of the SageMaker pipeline."
  value       = aws_sagemaker_pipeline.ml_pipeline.arn
}

output "pipeline_name" {
  description = "Name of the SageMaker pipeline."
  value       = aws_sagemaker_pipeline.ml_pipeline.pipeline_name
}

output "execution_role_arn" {
  description = "ARN of the SageMaker pipeline execution role."
  value       = aws_iam_role.sagemaker_pipeline_execution.arn
}

output "artifacts_bucket_arn" {
  description = "ARN of the S3 bucket holding SageMaker pipeline artifacts."
  value       = aws_s3_bucket.sagemaker_artifacts.arn
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "human_task_ui_name" {
  description = "Deterministic kebab-case name for the SageMaker Human Task UI."
  type        = string
  default     = "test-human-task-ui"
}

variable "tags" {
  description = "Standard tags applied to the SageMaker Human Task UI."
  type        = map(string)
  default = {
    ManagedBy   = "Terraform"
    Environment = "test"
  }
}

locals {
  tags = merge(
    var.tags,
    {
      Name = var.human_task_ui_name
    }
  )
}

resource "aws_sagemaker_human_task_ui" "test_ui" {
  human_task_ui_name = var.human_task_ui_name

  ui_template {
    content = <<-EOT
      <h1>TEST</h1>
    EOT
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "human_task_ui_arn" {
  description = "ARN of the SageMaker Human Task UI, for reference by downstream resources such as flow definitions."
  value       = aws_sagemaker_human_task_ui.test_ui.arn
}

output "human_task_ui_id" {
  description = "ID of the SageMaker Human Task UI."
  value       = aws_sagemaker_human_task_ui.test_ui.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = var.tags
  }
}

variable "tags" {
  description = "Consistent tags applied to every tagged resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

locals {
  model_name             = "sklearn-model"
  endpoint_name          = "sklearn-endpoint"
  endpoint_config_name   = "sklearn-endpoint-config"
  iam_role_name          = "sagemaker-sklearn-execution"
  artifacts_bucket_name  = "sagemaker-model-artifacts-${data.aws_caller_identity.current.account_id}"
  model_artifact_key     = "models/sklearn/model.tar.gz"
  model_data_url         = "s3://${aws_s3_bucket.model_artifacts.bucket}/${local.model_artifact_key}"
  # Public SageMaker prebuilt scikit-learn inference image (ECR Public alias — no
  # region-specific numeric AWS account IDs are hardcoded in the registry path).
  model_image             = "public.ecr.aws/sagemaker/sagemaker-scikit-learn:0.23-1-cpu-py3"
  endpoint_log_group_name = "/aws/sagemaker/Endpoints/${local.endpoint_name}"
}

# ------------------------------------------------------------------------------
# S3 bucket for model artifacts
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "model_artifacts" {
  bucket = local.artifacts_bucket_name

  tags = merge(var.tags, { Name = local.artifacts_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.model_artifacts.arn,
          "${aws_s3_bucket.model_artifacts.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.model_artifacts]
}

# ------------------------------------------------------------------------------
# IAM execution role for SageMaker
# ------------------------------------------------------------------------------

resource "aws_iam_role" "sagemaker_execution" {
  name = local.iam_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSageMakerToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(var.tags, { Name = local.iam_role_name })
}

resource "aws_iam_role_policy" "s3_model_artifacts_read" {
  name = "s3-model-artifacts-read"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListArtifactsBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.model_artifacts.arn]
      },
      {
        Sid      = "ReadModelArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.model_artifacts.arn}/models/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecr_image_pull" {
  name = "ecr-image-pull"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        # ecr:GetAuthorizationToken is not resource-scopable, and the published
        # SageMaker framework images live in AWS-managed repositories outside
        # this account, so repository-level ARN scoping is not possible here.
        # Only narrowly-scoped retrieval actions are granted.
        Sid    = "PullSageMakerInferenceImages"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage"
        ]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_endpoint_logs" {
  name = "cloudwatch-endpoint-logs"
  role = aws_iam_role.sagemaker_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteEndpointLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = ["${aws_cloudwatch_log_group.endpoint_logs.arn}:*"]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudWatch log group for endpoint invocation logs
# ------------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "endpoint_logs" {
  name              = local.endpoint_log_group_name
  retention_in_days = 30

  tags = merge(var.tags, { Name = local.endpoint_log_group_name })
}

# ------------------------------------------------------------------------------
# SageMaker model, endpoint configuration, and endpoint
# ------------------------------------------------------------------------------

resource "aws_sagemaker_model" "sklearn_model" {
  name               = local.model_name
  execution_role_arn = aws_iam_role.sagemaker_execution.arn

  enable_network_isolation = true

  primary_container {
    image          = local.model_image
    model_data_url = local.model_data_url
  }

  tags = merge(var.tags, { Name = local.model_name })
}

resource "aws_sagemaker_endpoint_configuration" "sklearn_config" {
  name = local.endpoint_config_name

  production_variants {
    variant_name           = "sklearn-variant"
    model_name             = aws_sagemaker_model.sklearn_model.name
    initial_instance_count = 1
    instance_type          = "ml.m5.large"
  }

  tags = merge(var.tags, { Name = local.endpoint_config_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sagemaker_endpoint" "sklearn_endpoint" {
  name                 = local.endpoint_name
  endpoint_config_name = aws_sagemaker_endpoint_configuration.sklearn_config.name

  tags = merge(var.tags, { Name = local.endpoint_name })

  depends_on = [aws_cloudwatch_log_group.endpoint_logs]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used to derive resource names."
  type        = string
  default     = "demo"
}

variable "image_tag" {
  description = "Container image tag within the inference ECR repository."
  type        = string
  default     = "latest"
}

variable "tags" {
  description = "Default tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  endpoint_name  = "sagemaker-${var.project_name}-endpoint"
  model_data_url = "s3://${aws_s3_bucket.model_artifacts.bucket}/${aws_s3_object.model_artifact.key}"
  common_tags    = merge(var.tags, { Project = var.project_name })
}

# -----------------------------------------------------------------------------
# KMS: encryption for model artifacts and endpoint storage volumes
# -----------------------------------------------------------------------------
resource "aws_kms_key" "sagemaker" {
  description             = "KMS key for SageMaker model artifacts and endpoint storage volumes"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sagemaker" {
  name          = "alias/sagemaker-${var.project_name}"
  target_key_id = aws_kms_key.sagemaker.key_id
}

# -----------------------------------------------------------------------------
# S3: model artifact bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "model_artifacts" {
  bucket = "sagemaker-model-artifacts-${var.project_name}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.sagemaker.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "model_artifacts" {
  bucket = aws_s3_bucket.model_artifacts.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.model_artifacts.arn,
          "${aws_s3_bucket.model_artifacts.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_object" "model_artifact" {
  bucket                 = aws_s3_bucket.model_artifacts.bucket
  key                    = "models/model.tar.gz"
  content                = "placeholder model artifact"
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.sagemaker.arn

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# ECR: private inference container repository
# -----------------------------------------------------------------------------
resource "aws_ecr_repository" "inference" {
  name                 = "sagemaker-inference-${var.project_name}"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# IAM: SageMaker execution role with least-privilege inline policies
# -----------------------------------------------------------------------------
resource "aws_iam_role" "sagemaker_exec" {
  name = "sagemaker-exec-${var.project_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowSageMakerAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "s3_model_artifacts" {
  name = "s3-model-artifacts-access"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListModelArtifactBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.model_artifacts.arn]
      },
      {
        Sid      = "GetModelArtifacts"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.model_artifacts.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudwatch_logs" {
  name = "sagemaker-endpoint-logs"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SageMakerEndpointLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.endpoint.arn,
          "${aws_cloudwatch_log_group.endpoint.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecr_pull" {
  name = "ecr-inference-pull"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "PullInferenceImage"
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = [aws_ecr_repository.inference.arn]
      },
      {
        Sid      = "GetEcrAuthorizationToken"
        Effect   = "Allow"
        Action   = ["ecr:GetAuthorizationToken"]
        Resource = ["*"]
      }
    ]
  })
}

resource "aws_iam_role_policy" "kms_decrypt" {
  name = "kms-model-artifact-decrypt"
  role = aws_iam_role.sagemaker_exec.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptModelArtifacts"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.sagemaker.arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch: endpoint inference log group
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "endpoint" {
  name              = "/aws/sagemaker/Endpoints/${local.endpoint_name}"
  retention_in_days = 30

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# SageMaker: model, endpoint configuration, and endpoint
# -----------------------------------------------------------------------------
resource "aws_sagemaker_model" "model" {
  name                     = "sagemaker-${var.project_name}-model"
  execution_role_arn       = aws_iam_role.sagemaker_exec.arn
  enable_network_isolation = true

  primary_container {
    image          = "${aws_ecr_repository.inference.repository_url}:${var.image_tag}"
    model_data_url = local.model_data_url
  }

  tags = local.common_tags
}

resource "aws_sagemaker_endpoint_configuration" "config" {
  name = "${local.endpoint_name}-config"

  production_variants {
    variant_name           = "AllTraffic"
    model_name             = aws_sagemaker_model.model.name
    instance_type          = "ml.m5.large"
    initial_instance_count = 1
  }

  kms_key_arn = aws_kms_key.sagemaker.arn

  tags = local.common_tags
}

resource "aws_sagemaker_endpoint" "endpoint" {
  name                 = local.endpoint_name
  endpoint_config_name = aws_sagemaker_endpoint_configuration.config.name

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "endpoint_name" {
  description = "Name of the SageMaker real-time inference endpoint."
  value       = aws_sagemaker_endpoint.endpoint.name
}

output "endpoint_arn" {
  description = "ARN of the SageMaker real-time inference endpoint."
  value       = aws_sagemaker_endpoint.endpoint.arn
}

output "model_artifact_s3_uri" {
  description = "S3 URI of the SageMaker model artifacts."
  value       = local.model_data_url
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  function_name = "hello-lambda"

  common_tags = {
    Project     = "serverless-hello"
    Component   = "lambda"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Lambda source code, authored as a managed local file (no inline secrets,
# credentials, or account-specific identifiers).
# -----------------------------------------------------------------------------
resource "local_file" "lambda_js" {
  filename        = "lambda.js"
  file_permission = "0644"
  content         = <<-EOF
    'use strict';

    /**
     * Simple Node.js Lambda handler.
     * The deployment package exposes this code as index.js so that the
     * "index.handler" entry point resolves correctly.
     */
    exports.handler = async (event) => {
      console.log('Received event:', JSON.stringify(event, null, 2));

      const response = {
        statusCode: 200,
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: 'Hello from Lambda!',
          input: event,
        }),
      };

      return response;
    };
  EOF
}

# -----------------------------------------------------------------------------
# Deployment package: the handler source is embedded as index.js so that the
# "index.handler" reference resolves. output_base64sha256 is used as
# source_code_hash so any code change triggers a redeployment.
# -----------------------------------------------------------------------------
data "archive_file" "lambda" {
  type        = "zip"
  output_path = "lambda_function_payload.zip"

  source {
    content  = local_file.lambda_js.content
    filename = "index.js"
  }
}

# -----------------------------------------------------------------------------
# Execution role: trusts only the Lambda service principal (no wildcards).
# -----------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name = "${local.function_name}-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceAssume"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

# AWS-managed policy granting CloudWatch Logs write permissions.
resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# -----------------------------------------------------------------------------
# Lambda function
# -----------------------------------------------------------------------------
resource "aws_lambda_function" "hello_lambda" {
  function_name = local.function_name
  description   = "Node.js Lambda function provisioned with Terraform"

  # nodejs18.x is end-of-support; nodejs22.x is the actively supported runtime.
  runtime = "nodejs22.x"
  handler = "index.handler"
  role    = aws_iam_role.lambda_exec.arn

  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  memory_size = 128
  timeout     = 10

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]
}

# -----------------------------------------------------------------------------
# Explicit CloudWatch log group (replaces the auto-created one) with bounded
# 14-day retention so logs do not accumulate indefinitely.
# -----------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${aws_lambda_function.hello_lambda.function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

output "lambda_function_name" {
  description = "Name of the Lambda function."
  value       = aws_lambda_function.hello_lambda.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function."
  value       = aws_lambda_function.hello_lambda.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all with defaults so terraform apply runs unattended)
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet."
  type        = string
  default     = "10.0.1.0/24"
}

variable "ssh_allowed_cidr" {
  description = "CIDR block permitted to open SSH (tcp/22) sessions to the instance."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.ssh_allowed_cidr != "0.0.0.0/0"
    error_message = "SSH access must be restricted to a private management CIDR, never 0.0.0.0/0."
  }
}

variable "instance_type" {
  description = "EC2 instance type; must provide at least 4 vCPUs to satisfy the CPU options (2 cores x 2 threads per core)."
  type        = string
  default     = "t3.xlarge"
}

variable "root_volume_size" {
  description = "Size (GiB) of the encrypted gp3 root EBS volume."
  type        = number
  default     = 20
}

variable "project_name" {
  description = "Project name used for snake_case resource naming and the Project tag."
  type        = string
  default     = "amzn2_cpu_optimized"
}

variable "environment" {
  description = "Environment classification applied as the Environment tag."
  type        = string
  default     = "production"
}

variable "owner" {
  description = "Owning team applied as the Owner tag."
  type        = string
  default     = "platform_engineering"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    Owner       = var.owner
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (pure static lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "example" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Networking: dedicated VPC, public subnet, IGW, and routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_public_subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_internet_gateway"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_public_route_table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group: SSH (tcp/22) restricted to private management CIDR
###############################################################################

resource "aws_security_group" "ssh_access" {
  name        = "${var.project_name}_ssh_access_sg"
  description = "Allow inbound SSH from the restricted management CIDR and permit all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH (tcp/22) from the restricted management CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.ssh_allowed_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssh_access_sg"
  })
}

###############################################################################
# SSH key material: generated, registered, stored in Secrets Manager
###############################################################################

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  key_name   = "${var.project_name}_key_pair"
  public_key = tls_private_key.main.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_key_pair"
  })
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "${var.project_name}/ssh/private_key"
  description = "Private key material for the ${var.project_name} EC2 key pair."

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssh_private_key_secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

###############################################################################
# IAM: least-privilege SSM management role and instance profile
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm_management" {
  name               = "${var.project_name}_ssm_management_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssm_management_role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm_management.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_management" {
  name = "${var.project_name}_ssm_management_profile"
  role = aws_iam_role.ssm_management.name

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_ssm_management_profile"
  })
}

###############################################################################
# EC2 instance: latest Amazon Linux 2, 2 cores x 2 threads per core (4 vCPUs)
###############################################################################

resource "aws_instance" "amazon_linux_2" {
  ami                         = data.aws_ami.example.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.ssh_access.id]
  key_name                    = aws_key_pair.main.key_name
  iam_instance_profile        = aws_iam_instance_profile.ssm_management.name
  associate_public_ip_address = true
  monitoring                  = true

  # Core requirement of the request: 2 cores x 2 threads per core = 4 vCPUs.
  cpu_options {
    core_count       = 2
    threads_per_core = 2
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = var.root_volume_size
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}_instance"
  })

  depends_on = [aws_iam_role_policy_attachment.ssm_managed_instance_core]
}

###############################################################################
# Outputs
###############################################################################

output "instance_id" {
  description = "ID of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.amazon_linux_2.id
}

output "instance_public_ip" {
  description = "Public IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.amazon_linux_2.public_ip
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.ssh_private_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled values only, all with unattended-apply defaults)
# -----------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the Amazon Linux 2 server."
  type        = string
  default     = "t3.micro"
}

variable "project_name" {
  description = "Value used for the Name tag and resource naming."
  type        = string
  default     = "amazon-linux-2-server"
}

variable "environment" {
  description = "Environment tag value (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-vpc"
    }
  )
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-subnet"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-public-route-table"
    }
  )
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group (least-privilege ingress, unrestricted egress)
# -----------------------------------------------------------------------------

resource "aws_security_group" "ec2_sg" {
  name        = "${var.project_name}-ec2-sg"
  description = "Allow SSH only from within the VPC; allow all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic (package updates, SSM agent)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ec2-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# SSH key material (generated, never hardcoded)
# -----------------------------------------------------------------------------

resource "tls_private_key" "ec2_ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "ec2_ssh" {
  key_name   = "${var.project_name}-keypair"
  public_key = tls_private_key.ec2_ssh.public_key_openssh

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-keypair"
    }
  )
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "${var.project_name}/ssh/private-key"
  description = "Private key material for the ${var.project_name} EC2 SSH key pair."

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ssh-private-key"
    }
  )
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.ec2_ssh.private_key_pem
}

# -----------------------------------------------------------------------------
# IAM (SSM-based administration)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ssm_role" {
  name = "${var.project_name}-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-ssm-role"
    }
  )
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm_profile" {
  name = "${var.project_name}-ssm-instance-profile"
  role = aws_iam_role.ssm_role.name
}

# -----------------------------------------------------------------------------
# EC2 instance (latest Amazon Linux 2)
# -----------------------------------------------------------------------------

resource "aws_instance" "al2_server" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.ec2_sg.id]
  key_name                    = aws_key_pair.ec2_ssh.key_name
  iam_instance_profile        = aws_iam_instance_profile.ssm_profile.name
  associate_public_ip_address = true

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    encrypted             = true
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  tags = merge(
    local.common_tags,
    {
      Name        = var.project_name
      AmiId       = data.aws_ami.amazon_linux_2.id
      Description = "Amazon Linux 2 server using the latest AMI resolved dynamically"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.id
}

output "public_ip" {
  description = "Public IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.public_ip
}

output "private_ip" {
  description = "Private IP address of the Amazon Linux 2 EC2 instance."
  value       = aws_instance.al2_server.private_ip
}

output "latest_amazon_linux_2_ami_id" {
  description = "Latest Amazon Linux 2 AMI ID resolved by the aws_ami data source."
  value       = data.aws_ami.amazon_linux_2.id
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the generated SSH private key."
  value       = aws_secretsmanager_secret.ssh_private_key.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used to prefix resource names and tags."
  type        = string
  default     = "terraform-demo"
}

variable "environment" {
  description = "Environment name applied to the Environment tag on all resources."
  type        = string
  default     = "dev"
}

variable "admin_ssh_cidr" {
  description = "CIDR block permitted to reach SSH (port 22) on the instances."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = can(cidrnetmask(var.admin_ssh_cidr))
    error_message = "admin_ssh_cidr must be a valid CIDR block (e.g. 10.0.0.0/8)."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-internet-gateway"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-subnet-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-subnet-${data.aws_availability_zones.available.names[1]}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-route-table"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "instance" {
  name        = "${var.project_name}-instance-sg"
  description = "Allow SSH from the admin CIDR and all outbound traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_ssh_cidr]
  }

  egress {
    description = "All outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-sg"
  })
}

resource "aws_instance" "instance_a" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_a.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_instance" "instance_b" {
  ami                         = data.aws_ami.amazon_linux_2.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_b.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-instance-${data.aws_availability_zones.available.names[1]}"
  })
}

resource "aws_ebs_volume" "volume_a" {
  availability_zone = aws_instance.instance_a.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-volume-${aws_instance.instance_a.availability_zone}"
  })
}

resource "aws_ebs_volume" "volume_b" {
  availability_zone = aws_instance.instance_b.availability_zone
  size              = 50
  type              = "gp3"
  encrypted         = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-volume-${aws_instance.instance_b.availability_zone}"
  })
}

resource "aws_volume_attachment" "attachment_a" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.volume_a.id
  instance_id = aws_instance.instance_a.id
}

resource "aws_volume_attachment" "attachment_b" {
  device_name = "/dev/sdf"
  volume_id   = aws_ebs_volume.volume_b.id
  instance_id = aws_instance.instance_b.id
}

output "instance_a_id" {
  description = "Instance ID of instance A in the first availability zone."
  value       = aws_instance.instance_a.id
}

output "instance_a_public_ip" {
  description = "Public IP address of instance A."
  value       = aws_instance.instance_a.public_ip
}

output "instance_a_volume_id" {
  description = "ID of the 50 GB EBS data volume attached to instance A."
  value       = aws_ebs_volume.volume_a.id
}

output "instance_b_id" {
  description = "Instance ID of instance B in the second availability zone."
  value       = aws_instance.instance_b.id
}

output "instance_b_public_ip" {
  description = "Public IP address of instance B."
  value       = aws_instance.instance_b.public_ip
}

output "instance_b_volume_id" {
  description = "ID of the 50 GB EBS data volume attached to instance B."
  value       = aws_ebs_volume.volume_b.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resource tags"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-subnet"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "private-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "public-route-table"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "fleet" {
  name        = "fleet-sg"
  description = "Security group for the EC2 Fleet instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from within the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "fleet-sg"
  })
}

resource "aws_iam_role" "fleet_ssm" {
  name = "fleet-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "fleet-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "fleet_ssm_core" {
  role       = aws_iam_role.fleet_ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "fleet" {
  name = "fleet-instance-profile"
  role = aws_iam_role.fleet_ssm.name

  tags = merge(local.common_tags, {
    Name = "fleet-instance-profile"
  })
}

resource "aws_launch_template" "linux_2" {
  name          = "linux2-fleet-lt"
  description   = "Launch template for the Amazon Linux 2 EC2 Fleet"
  image_id      = data.aws_ami.linux2.id
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_instance_profile.fleet.name
  }

  vpc_security_group_ids = [aws_security_group.fleet.id]

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 8
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "linux2-fleet-instance"
    })
  }

  tags = merge(local.common_tags, {
    Name = "linux2-fleet-lt"
  })

  depends_on = [aws_iam_role_policy_attachment.fleet_ssm_core]
}

resource "aws_ec2_fleet" "main" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.linux_2.id
      version            = aws_launch_template.linux_2.latest_version
    }

    override {
      subnet_id = aws_subnet.public.id
      priority  = 1
    }

    override {
      subnet_id = aws_subnet.private.id
      priority  = 2
    }
  }

  target_capacity_specification {
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
    default_target_capacity_type = "on-demand"
  }

  spot_options {
    instance_interruption_behavior = "terminate"
  }

  replace_unhealthy_instances = true
  terminate_instances         = true

  tags = merge(local.common_tags, {
    Name = "linux2-fleet"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  name_prefix = lower(var.environment)

  db_username = "dbadmin"
  db_name     = "appdb"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public"
    Tier = "public"
  })
}

resource "aws_subnet" "private_app" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-app"
    Tier = "application"
  })
}

resource "aws_subnet" "private_db" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.21.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-db"
    Tier = "database"
  })
}

resource "aws_eip" "nat" {
  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private_app" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-app-rt"
  })
}

resource "aws_route_table_association" "private_app" {
  subnet_id      = aws_subnet.private_app.id
  route_table_id = aws_route_table.private_app.id
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-db-rt"
  })
}

resource "aws_route_table_association" "private_db" {
  subnet_id      = aws_subnet.private_db.id
  route_table_id = aws_route_table.private_db.id
}

# -----------------------------------------------------------------------------
# Security Groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "webserver" {
  name        = "${local.name_prefix}-webserver-sg"
  description = "Web tier: allow HTTP/HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver-sg"
  })
}

resource "aws_security_group" "app_server" {
  name        = "${local.name_prefix}-app-sg"
  description = "Application tier: allow port 8080 from the web tier security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application traffic from the webserver security group"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-sg"
  })
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-db-sg"
  description = "Database tier: allow MySQL 3306 from the application tier security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the application server security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.app_server.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# -----------------------------------------------------------------------------
# IAM
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "webserver" {
  name               = "${local.name_prefix}-webserver-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver-role"
  })
}

resource "aws_iam_role_policy_attachment" "webserver_ssm" {
  role       = aws_iam_role.webserver.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "webserver" {
  name = "${local.name_prefix}-webserver-profile"
  role = aws_iam_role.webserver.name
}

resource "aws_iam_role" "app_server" {
  name               = "${local.name_prefix}-app-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-role"
  })
}

resource "aws_iam_role_policy_attachment" "app_server_ssm" {
  role       = aws_iam_role.app_server.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "app_server_db_secret_read" {
  statement {
    sid       = "ReadDatabaseSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db.arn]
  }
}

resource "aws_iam_role_policy" "app_server_db_secret" {
  name   = "${local.name_prefix}-read-db-secret"
  role   = aws_iam_role.app_server.name
  policy = data.aws_iam_policy_document.app_server_db_secret_read.json
}

resource "aws_iam_instance_profile" "app_server" {
  name = "${local.name_prefix}-app-profile"
  role = aws_iam_role.app_server.name
}

# -----------------------------------------------------------------------------
# Compute
# -----------------------------------------------------------------------------

resource "aws_instance" "webserver" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.webserver.id]
  iam_instance_profile        = aws_iam_instance_profile.webserver.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euxo pipefail
    dnf update -y
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<html><body><h1>Web server (${local.name_prefix} environment)</h1></body></html>" > /var/www/html/index.html
  EOF

  depends_on = [aws_route_table_association.public]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-webserver"
    Tier = "public"
  })
}

resource "aws_instance" "app_server" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private_app.id
  associate_public_ip_address = false
  vpc_security_group_ids      = [aws_security_group.app_server.id]
  iam_instance_profile        = aws_iam_instance_profile.app_server.name

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euxo pipefail
    dnf update -y
    dnf install -y python3
    mkdir -p /opt/app
    echo "Application server is running" > /opt/app/index.html
    cat > /etc/systemd/system/app.service <<'UNIT'
    [Unit]
    Description=Demo application server (port 8080)
    After=network.target

    [Service]
    ExecStart=/usr/bin/python3 -m http.server 8080 --directory /opt/app
    Restart=always

    [Install]
    WantedBy=multi-user.target
    UNIT
    systemctl daemon-reload
    systemctl enable --now app.service
  EOF

  depends_on = [aws_route_table_association.private_app, aws_nat_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-server"
    Tier = "application"
  })
}

# -----------------------------------------------------------------------------
# Database
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "database" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_app.id, aws_subnet.private_db.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "random_password" "db" {
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "db_final_snapshot" {
  byte_length = 4
}

resource "aws_db_instance" "database" {
  identifier                 = "${local.name_prefix}-mysql"
  engine                     = "mysql"
  engine_version             = "8.0"
  instance_class             = "db.t3.micro"
  allocated_storage          = 20
  max_allocated_storage      = 100
  storage_type               = "gp3"
  db_name                    = local.db_name
  username                   = local.db_username
  password                   = random_password.db.result
  port                       = 3306
  db_subnet_group_name       = aws_db_subnet_group.database.name
  vpc_security_group_ids     = [aws_security_group.database.id]
  publicly_accessible        = false
  multi_az                   = false
  storage_encrypted          = true
  deletion_protection        = true
  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${local.name_prefix}-mysql-final-${random_id.db_final_snapshot.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql"
    Tier = "database"
  })
}

# -----------------------------------------------------------------------------
# Secrets
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}-db-credentials"
  description = "Master credentials for the ${local.name_prefix} RDS MySQL instance"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db.result
    engine   = "mysql"
    host     = aws_db_instance.database.address
    port     = aws_db_instance.database.port
    dbname   = local.db_name
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "webserver_public_ip" {
  description = "Public IP address of the webserver instance."
  value       = aws_instance.webserver.public_ip
}

output "app_server_private_ip" {
  description = "Private IP address of the application server instance."
  value       = aws_instance.app_server.private_ip
}

output "rds_endpoint" {
  description = "Connection endpoint address of the RDS MySQL instance."
  value       = aws_db_instance.database.address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Short project prefix used for resource names and tags."
  type        = string
  default     = "al2023-efs-shared"
}

variable "environment" {
  description = "Environment name applied to the Environment tag of every resource."
  type        = string
  default     = "dev"
}

variable "instance_type" {
  description = "EC2 instance type for the two private Amazon Linux 2023 instances."
  type        = string
  default     = "t3.micro"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${data.aws_availability_zones.available.names[0]}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_security_group" "ec2" {
  name        = "${local.name_prefix}-ec2-sg"
  description = "Private EC2 instances; no inbound access, administration via AWS Systems Manager only"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-sg"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-sg"
  description = "EFS mount targets; NFS restricted to the EC2 instance security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "NFS from EC2 instances only"
    from_port       = 2049
    to_port         = 2049
    protocol        = "tcp"
    security_groups = [aws_security_group.ec2.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-sg"
  })
}

resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-efs"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "main" {
  count = 2

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ssm" {
  name               = "${local.name_prefix}-ssm-role"
  description        = "Role assumed by the private instances for AWS Systems Manager access"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed_instance_core" {
  role       = aws_iam_role.ssm.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.ssm.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-profile"
  })
}

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.al2023.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.private[count.index].id
  vpc_security_group_ids      = [aws_security_group.ec2.id]
  iam_instance_profile        = aws_iam_instance_profile.ssm.name
  associate_public_ip_address = false

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  user_data = base64encode(<<-USER_DATA
    #!/bin/bash
    set -euxo pipefail

    dnf install -y nfs-utils amazon-efs-utils

    EFS_DNS_NAME="${aws_efs_file_system.main.dns_name}"
    MOUNT_POINT="/mnt/efs"

    mkdir -p "$MOUNT_POINT"

    for attempt in $(seq 1 30); do
      if mount -t efs -o tls "$EFS_DNS_NAME":/ "$MOUNT_POINT"; then
        echo "$EFS_DNS_NAME":/ "$MOUNT_POINT" efs tls,_netdev 0 0 >> /etc/fstab
        echo "EFS successfully mounted at $MOUNT_POINT"
        exit 0
      fi
      echo "EFS mount attempt $attempt failed; retrying in 10 seconds"
      sleep 10
    done

    echo "Failed to mount EFS after 30 attempts" >&2
    exit 1
  USER_DATA
  )

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-${data.aws_availability_zones.available.names[count.index]}"
  })

  depends_on = [aws_efs_mount_target.main]
}

output "instance_ids" {
  description = "IDs of the two private Amazon Linux 2023 instances."
  value       = aws_instance.app[*].id
}

output "instance_private_ips" {
  description = "Private IP addresses of the two instances, one per AZ."
  value       = aws_instance.app[*].private_ip
}

output "efs_file_system_id" {
  description = "ID of the shared encrypted EFS file system."
  value       = aws_efs_file_system.main.id
}

output "efs_dns_name" {
  description = "DNS name of the shared EFS file system mounted on every instance."
  value       = aws_efs_file_system.main.dns_name
}

output "efs_mount_targets" {
  description = "Per-AZ identity of the EFS mount targets (mount target ID and IP mapped to the AZ of its private subnet)."
  value = [
    for i in range(2) : {
      mount_target_id   = aws_efs_mount_target.main[i].id
      ip_address        = aws_efs_mount_target.main[i].ip_address
      availability_zone = aws_subnet.private[i].availability_zone
    }
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Name prefix applied to all resources."
  type        = string
  default     = "hpc_cluster"
}

variable "environment" {
  description = "Environment tag value applied to all resources."
  type        = string
  default     = "production"
}

variable "instance_type" {
  description = "Instance type for cluster nodes (must support cluster placement groups)."
  type        = string
  default     = "m5.large"
}

variable "admin_cidr" {
  description = "Restricted admin CIDR allowed to reach SSH on cluster nodes."
  type        = string
  default     = "203.0.113.0/24"
}

variable "ssh_public_key" {
  description = "OpenSSH public key material for the deployer key pair (public key only, never private key material)."
  type        = string
  default     = "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIGj0L3hG9R6vW8FqL1TqT3nK2mY5cB7dE9fH1jK3lN5 deployer@example.com"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "base" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_subnet" "cluster" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-subnet"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "cluster" {
  subnet_id      = aws_subnet.cluster.id
  route_table_id = aws_route_table.public.id
}

resource "aws_key_pair" "deployer" {
  key_name   = "${var.project_name}-deployer-key"
  public_key = var.ssh_public_key

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-deployer-key"
  })
}

resource "aws_security_group" "cluster" {
  name        = "${var.project_name}-cluster-sg"
  description = "Security group for cluster nodes: SSH from admin CIDR, internal cluster traffic within VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from restricted admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  ingress {
    description = "Cluster internal node-to-node traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-sg"
  })
}

resource "aws_placement_group" "cluster" {
  name     = "${var.project_name}-placement-group"
  strategy = "cluster"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-placement-group"
  })
}

resource "aws_instance" "cluster" {
  count = 3

  ami                    = data.aws_ami.base.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.cluster.id
  vpc_security_group_ids = [aws_security_group.cluster.id]
  key_name               = aws_key_pair.deployer.key_name
  placement_group        = aws_placement_group.cluster.name

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  metadata_options {
    http_tokens = "required"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-cluster-node-${count.index + 1}"
  })
}

output "instance_ids" {
  description = "IDs of the three cluster instances."
  value       = aws_instance.cluster[*].id
}

output "instance_public_ips" {
  description = "Public IPs of the three cluster instances."
  value       = aws_instance.cluster[*].public_ip
}

output "placement_group_name" {
  description = "Name of the cluster placement group."
  value       = aws_placement_group.cluster.name
}

output "cluster_availability_zone" {
  description = "Availability zone hosting the cluster subnet and all three instances."
  value       = aws_subnet.cluster.availability_zone
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Environment = "dev"
  }
}

locals {
  name_prefix = "reduce-db-calls-cache"
}

# ---------------------------------------------------------------------------
# Network: VPC and private subnets for the cache layer
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "${local.name_prefix}-vpc" })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private_cache_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_cache_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "${local.name_prefix}-private-b" })
}

# ---------------------------------------------------------------------------
# Security group: Redis (TCP 6379) restricted to the VPC CIDR only
# ---------------------------------------------------------------------------
resource "aws_security_group" "cache_sg" {
  name        = "${local.name_prefix}-redis-sg"
  description = "Allow Redis TCP 6379 only from within the VPC; no public ingress."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-redis-sg" })
}

# ---------------------------------------------------------------------------
# ElastiCache subnet group: cache nodes deployed ONLY in private subnets
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "cache_subnets" {
  name       = "${local.name_prefix}-subnets"
  subnet_ids = [aws_subnet.private_cache_a.id, aws_subnet.private_cache_b.id]

  tags = merge(var.tags, { Name = "${local.name_prefix}-subnet-group" })
}

# ---------------------------------------------------------------------------
# Redis AUTH token: generated at apply-time and stored in Secrets Manager
# ---------------------------------------------------------------------------
resource "random_password" "auth_token" {
  length  = 32
  special = false
}

resource "aws_secretsmanager_secret" "redis_auth_token" {
  name                    = "${local.name_prefix}-auth-token"
  description             = "AUTH token for the Redis read-through cache replication group."
  recovery_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-auth-token" })
}

resource "aws_secretsmanager_secret_version" "redis_auth_token" {
  secret_id     = aws_secretsmanager_secret.redis_auth_token.id
  secret_string = random_password.auth_token.result
}

# ---------------------------------------------------------------------------
# IAM: least-privilege access to the AUTH token secret, scoped to its ARN
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "redis_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cache_token_reader" {
  name               = "${local.name_prefix}-token-reader"
  assume_role_policy = data.aws_iam_policy_document.redis_assume_role.json

  tags = merge(var.tags, { Name = "${local.name_prefix}-token-reader" })
}

data "aws_iam_policy_document" "redis_token_read" {
  statement {
    sid       = "ReadRedisAuthToken"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.redis_auth_token.arn]
  }
}

resource "aws_iam_policy" "redis_token_read" {
  name        = "${local.name_prefix}-token-read"
  description = "Least-privilege read access to the Redis AUTH token secret only."
  policy      = data.aws_iam_policy_document.redis_token_read.json

  tags = merge(var.tags, { Name = "${local.name_prefix}-token-read" })
}

resource "aws_iam_role_policy_attachment" "redis_token_read" {
  role       = aws_iam_role.cache_token_reader.name
  policy_arn = aws_iam_policy.redis_token_read.arn
}

# ---------------------------------------------------------------------------
# ElastiCache Redis replication group: in-memory read-through cache that
# absorbs repeated lookups and reduces database call volume
# ---------------------------------------------------------------------------
resource "aws_elasticache_replication_group" "redis_cache" {
  replication_group_id       = "${local.name_prefix}-rg"
  description                = "Redis read-through cache absorbing repeated lookups to reduce database call volume."
  engine                     = "redis"
  engine_version             = "7.1"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 2
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.cache_subnets.name
  security_group_ids         = [aws_security_group.cache_sg.id]
  automatic_failover_enabled = true
  multi_az_enabled           = true
  transit_encryption_enabled = true
  at_rest_encryption_enabled = true
  auth_token                 = random_password.auth_token.result
  maintenance_window         = "sun:05:00-sun:06:00"
  snapshot_window            = "01:00-03:00"
  snapshot_retention_limit   = 7
  apply_immediately          = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "${local.name_prefix}-rg" })
}

# ---------------------------------------------------------------------------
# Outputs: connection details for application resources (no secret values)
# ---------------------------------------------------------------------------
output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis cache to use for read-through caching."
  value       = aws_elasticache_replication_group.redis_cache.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Primary endpoint port of the Redis cache."
  value       = aws_elasticache_replication_group.redis_cache.port
}

output "redis_auth_token_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redis AUTH token (the value itself is never exposed)."
  value       = aws_secretsmanager_secret.redis_auth_token.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata used for AZ selection
data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "redis-auth"

  common_tags = {
    Project   = "elasticache-redis-user-auth"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking (greenfield VPC + private cache subnets in 2 AZs)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

# -----------------------------------------------------------------------------
# Security group: Redis reachable only from within the VPC
# -----------------------------------------------------------------------------

resource "aws_security_group" "redis" {
  name        = "${local.name_prefix}-cache-sg"
  description = "Restrict Redis access to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis (TCP 6379) from within the VPC"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cache-sg" })
}

# -----------------------------------------------------------------------------
# Redis user credential: generated password + Secrets Manager storage
# -----------------------------------------------------------------------------

resource "random_password" "redis_auth" {
  length           = 36
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redis_auth" {
  name        = "elasticache/${local.name_prefix}/user-credentials"
  description = "ElastiCache Redis RBAC user authentication credentials"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-user-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "redis_auth" {
  secret_id = aws_secretsmanager_secret.redis_auth.id
  secret_string = jsonencode({
    username = aws_elasticache_user.redis_auth.user_name
    password = random_password.redis_auth.result
    engine   = "redis"
    host     = aws_elasticache_replication_group.redis.primary_endpoint_address
    port     = aws_elasticache_replication_group.redis.port
    ssl      = true
  })
}

# -----------------------------------------------------------------------------
# ElastiCache RBAC user (least-privilege ACL) and user group
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "redis_auth" {
  user_id              = "${local.name_prefix}-user"
  user_name            = "appuser"
  engine               = "redis"
  access_string        = "on ~app:* -@all +@read +@write"
  no_password_required = false
  passwords            = [random_password.redis_auth.result]
}

resource "aws_elasticache_user_group" "redis_users" {
  user_group_id = "${local.name_prefix}-users"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.redis_auth.user_id]
}

# -----------------------------------------------------------------------------
# Replication group enforcing user-group (RBAC) authentication
# -----------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "redis" {
  replication_group_id = "${local.name_prefix}-rg"
  description          = "Redis replication group enforcing user-group (RBAC) password authentication"

  engine               = "redis"
  engine_version       = "7.0"
  node_type            = "cache.t3.small"
  parameter_group_name = "default.redis7"
  port                 = 6379

  num_node_groups         = 1
  replicas_per_node_group = 1

  automatic_failover_enabled = true
  multi_az_enabled           = true

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.redis.id]

  user_group_ids = [aws_elasticache_user_group.redis_users.id]

  snapshot_retention_limit = 7
  snapshot_window          = "03:00-05:00"
  maintenance_window       = "sun:05:30-sun:06:30"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rg" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "redis_primary_endpoint_address" {
  description = "Primary endpoint address of the Redis replication group"
  value       = aws_elasticache_replication_group.redis.primary_endpoint_address
}

output "redis_primary_endpoint_port" {
  description = "Primary endpoint port of the Redis replication group"
  value       = aws_elasticache_replication_group.redis.port
}

output "redis_auth_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the Redis user credentials (retrieve the password via the secret, never in plaintext)"
  value       = aws_secretsmanager_secret.redis_auth.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (non-infrastructure values only, all defaulted for unattended apply)
# ---------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "cache-app"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups (safe, well-known data sources)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  name       = "${var.project_name}-${var.environment}"
  snake_name = replace(local.name, "-", "_")
  vpc_cidr   = "10.42.0.0/16"
  redis_port = 6379

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Network: dedicated VPC with two private subnets across the first two AZs
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_elasticache_subnet_group" "main" {
  name        = "${local.name}-cache-subnets"
  description = "Private subnets for the ${local.name} ElastiCache cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-subnets"
  })
}

resource "aws_security_group" "cache" {
  name        = "${local.name}-cache-sg"
  description = "ElastiCache ingress restricted to the VPC CIDR on TCP 6379 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from within the VPC only"
    from_port   = local.redis_port
    to_port     = local.redis_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound responses"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-sg"
  })
}

# ---------------------------------------------------------------------------
# ElastiCache RBAC user authenticated via IAM (no passwords anywhere)
# ---------------------------------------------------------------------------

resource "aws_elasticache_user" "iam_user" {
  engine        = "redis"
  user_id       = "${local.snake_name}_iam_user"
  user_name     = "${local.snake_name}_client"
  access_string = "on ~app:* -@all +@read +@write"

  authentication_mode {
    type = "iam"
  }

  tags = merge(local.common_tags, {
    Name = "${local.snake_name}_iam_user"
  })
}

resource "aws_elasticache_user_group" "main" {
  engine        = "redis"
  user_group_id = "${local.name}-user-group"
  user_ids      = [aws_elasticache_user.iam_user.user_id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-user-group"
  })
}

# ---------------------------------------------------------------------------
# Redis OSS replication group wired to the IAM-authenticated user group
# ---------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "cache" {
  replication_group_id = "${local.name}-redis"
  description          = "Redis 7 replication group using IAM-authenticated RBAC users"
  engine               = "redis"
  engine_version       = "7.0"
  node_type            = "cache.t3.medium"
  parameter_group_name = "default.redis7"

  num_cache_clusters         = 2
  automatic_failover_enabled = true
  multi_az_enabled           = true

  subnet_group_name  = aws_elasticache_subnet_group.main.name
  security_group_ids = [aws_security_group.cache.id]
  user_group_ids     = [aws_elasticache_user_group.main.id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  snapshot_retention_limit = 7
  snapshot_window          = "02:00-04:00"
  maintenance_window       = "sun:04:30-sun:06:30"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-redis"
  })
}

# ---------------------------------------------------------------------------
# IAM: least-privilege elasticache:Connect policy and assumable client role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "cache_client_assume" {
  statement {
    sid     = "AllowSameAccountClientsToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

data "aws_iam_policy_document" "cache_connect" {
  statement {
    sid       = "ElastiCacheIamAuthConnect"
    effect    = "Allow"
    actions   = ["elasticache:Connect"]
    resources = [
      aws_elasticache_replication_group.cache.arn,
      aws_elasticache_user.iam_user.arn,
    ]
  }

  statement {
    sid       = "ElastiCacheReplicationGroupDiscovery"
    effect    = "Allow"
    actions   = ["elasticache:DescribeReplicationGroups"]
    resources = [aws_elasticache_replication_group.cache.arn]
  }
}

resource "aws_iam_policy" "cache_connect" {
  name        = "${local.name}-cache-connect"
  description = "Least-privilege IAM authentication access to the ${local.name} ElastiCache cluster"
  policy      = data.aws_iam_policy_document.cache_connect.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-connect"
  })
}

resource "aws_iam_role" "cache_client" {
  name               = "${local.name}-cache-client"
  description        = "Role assumed by client applications for ElastiCache IAM authentication"
  assume_role_policy = data.aws_iam_policy_document.cache_client_assume.json

  tags = merge(local.common_tags, {
    Name = "${local.name}-cache-client"
  })
}

resource "aws_iam_role_policy_attachment" "cache_client_connect" {
  role       = aws_iam_role.cache_client.name
  policy_arn = aws_iam_policy.cache_connect.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "cache_client_role_arn" {
  description = "IAM role that client applications assume to sign ElastiCache connect requests."
  value       = aws_iam_role.cache_client.arn
}

output "cache_iam_user_id" {
  description = "ElastiCache user ID to use as the Redis username for IAM-authenticated connections."
  value       = aws_elasticache_user.iam_user.user_id
}

output "cache_primary_endpoint" {
  description = "Primary endpoint of the Redis replication group."
  value       = aws_elasticache_replication_group.cache.primary_endpoint_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for consistent resource tagging."
  type        = string
  default     = "elasticache-redis-auth"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "dev"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  name_prefix = "app-redis"

  common_tags = {
    Project     = var.project
    Environment = var.environment
  }
}

# -----------------------------------------------------------------------------
# Network foundation (internet/NAT free: subnets host only the cache tier)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_security_group" "cache" {
  name        = "${local.name_prefix}-cache-sg"
  description = "Permit Redis (TCP 6379) only from within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redis from within the VPC CIDR only"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cache-sg" })
}

# -----------------------------------------------------------------------------
# Dynamic credential generation and secure storage
# -----------------------------------------------------------------------------

resource "random_password" "cache_user_password" {
  length           = 24
  special          = true
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "cache_user_credentials" {
  name                    = "elasticache/${local.name_prefix}-auth-user"
  description             = "Credentials for the ElastiCache Redis ACL user"
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-auth-user-secret" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "cache_user_credentials" {
  secret_id = aws_secretsmanager_secret.cache_user_credentials.id
  secret_string = jsonencode({
    username = aws_elasticache_user.app_auth_user.user_name
    password = random_password.cache_user_password.result
  })
}

# -----------------------------------------------------------------------------
# ElastiCache ACL user with password-based authentication
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "app_auth_user" {
  user_id       = "app_auth_user"
  user_name     = "app_auth_user"
  engine        = "REDIS"
  access_string = "on ~app:* +@read +@write -@dangerous"
  passwords     = [random_password.cache_user_password.result]
}

resource "aws_elasticache_user_group" "app_user_group" {
  user_group_id = "app_user_group"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.app_auth_user.user_id]
}

# -----------------------------------------------------------------------------
# Cache tier building blocks
# -----------------------------------------------------------------------------

resource "aws_elasticache_subnet_group" "cache" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets for the Redis cache tier"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

resource "aws_elasticache_parameter_group" "redis7" {
  name        = "${local.name_prefix}-redis7-params"
  family      = "redis7"
  description = "Redis 7 parameter group supporting ACL user-group authentication"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redis7-params" })
}

# -----------------------------------------------------------------------------
# Replication group enforcing password (ACL) authentication on all connections
# -----------------------------------------------------------------------------

resource "aws_elasticache_replication_group" "main" {
  replication_group_id = "${local.name_prefix}-rg"
  description          = "Redis 7 replication group with ACL password authentication"
  engine               = "redis"
  engine_version       = "7.1"
  node_type            = "cache.t3.small"
  num_cache_clusters   = 2

  automatic_failover_enabled = true
  multi_az_enabled           = true

  parameter_group_name = aws_elasticache_parameter_group.redis7.name
  subnet_group_name    = aws_elasticache_subnet_group.cache.name
  security_group_ids   = [aws_security_group.cache.id]
  user_group_ids       = [aws_elasticache_user_group.app_user_group.user_group_id]

  at_rest_encryption_enabled = true
  transit_encryption_enabled = true

  snapshot_retention_limit = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rg" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs (never expose the password value itself)
# -----------------------------------------------------------------------------

output "redis_primary_endpoint" {
  description = "Primary endpoint address of the Redis replication group."
  value       = aws_elasticache_replication_group.main.primary_endpoint_address
}

output "redis_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the ElastiCache username and password."
  value       = aws_secretsmanager_secret.cache_user_credentials.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "redis-acl"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "production"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Generated credentials: never hardcoded. Each password is injected into the
# matching ElastiCache user and stored encrypted in AWS Secrets Manager.
# -----------------------------------------------------------------------------

resource "random_password" "admin" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_password" "read_only_one" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "random_password" "read_only_two" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

# -----------------------------------------------------------------------------
# ElastiCache users: one admin (full access) and two least-privilege,
# key-pattern-scoped read-only users. All users require authentication.
# -----------------------------------------------------------------------------

resource "aws_elasticache_user" "admin" {
  user_id              = "${local.name_prefix}-admin"
  user_name            = "${local.name_prefix}-admin"
  engine               = "REDIS"
  access_string        = "on ~* +@all"
  passwords            = [random_password.admin.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "read_only_one" {
  user_id              = "${local.name_prefix}-readonly-one"
  user_name            = "${local.name_prefix}-readonly-one"
  engine               = "REDIS"
  access_string        = "on ~app:* -@all +@read"
  passwords            = [random_password.read_only_one.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-one-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_elasticache_user" "read_only_two" {
  user_id              = "${local.name_prefix}-readonly-two"
  user_name            = "${local.name_prefix}-readonly-two"
  engine               = "REDIS"
  access_string        = "on ~cache:* -@all +@read"
  passwords            = [random_password.read_only_two.result]
  no_password_required = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-two-user"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager: one secret and one secret version per user password.
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "admin" {
  name        = "${local.name_prefix}/users/admin"
  description = "Password for the ${local.name_prefix} ElastiCache admin user."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-admin-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin" {
  secret_id = aws_secretsmanager_secret.admin.id
  secret_string = jsonencode({
    username = aws_elasticache_user.admin.user_name
    password = random_password.admin.result
  })
}

resource "aws_secretsmanager_secret" "read_only_one" {
  name        = "${local.name_prefix}/users/readonly-one"
  description = "Password for the ${local.name_prefix} ElastiCache read-only user (app keys)."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-one-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "read_only_one" {
  secret_id = aws_secretsmanager_secret.read_only_one.id
  secret_string = jsonencode({
    username = aws_elasticache_user.read_only_one.user_name
    password = random_password.read_only_one.result
  })
}

resource "aws_secretsmanager_secret" "read_only_two" {
  name        = "${local.name_prefix}/users/readonly-two"
  description = "Password for the ${local.name_prefix} ElastiCache read-only user (cache keys)."

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-readonly-two-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "read_only_two" {
  secret_id = aws_secretsmanager_secret.read_only_two.id
  secret_string = jsonencode({
    username = aws_elasticache_user.read_only_two.user_name
    password = random_password.read_only_two.result
  })
}

# -----------------------------------------------------------------------------
# ElastiCache user group bundling all three users.
# -----------------------------------------------------------------------------

resource "aws_elasticache_user_group" "main" {
  user_group_id = "${local.name_prefix}-user-group"
  engine        = "REDIS"
  user_ids = [
    aws_elasticache_user.admin.user_id,
    aws_elasticache_user.read_only_one.user_id,
    aws_elasticache_user.read_only_two.user_id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-group"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to all resources (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

locals {
  table_name = "ExampleTableName"

  common_tags = {
    Name        = local.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_service_linked_role" "dynamodb_contributor_insights" {
  aws_service_name = "ddb.contributorinsights.amazonaws.com"
  description      = "Service-linked role required by DynamoDB Contributor Insights."
  tags             = local.common_tags
}

resource "aws_dynamodb_table" "example" {
  name         = local.table_name
  hash_key     = "Id"
  billing_mode = "PAY_PER_REQUEST"

  attribute {
    name = "Id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_contributor_insights" "example" {
  table_name = aws_dynamodb_table.example.name

  depends_on = [aws_iam_service_linked_role.dynamodb_contributor_insights]
}

output "dynamodb_table_arn" {
  description = "ARN of the ExampleTableName DynamoDB table."
  value       = aws_dynamodb_table.example.arn
}

output "contributor_insights_name" {
  description = "Name of the Contributor Insights analysis on the base table."
  value       = aws_dynamodb_contributor_insights.example.id
}

output "service_linked_role_arn" {
  description = "ARN of the DynamoDB Contributor Insights service-linked role."
  value       = aws_iam_service_linked_role.dynamodb_contributor_insights.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = length(var.environment) > 0
    error_message = "environment must be a non-empty string."
  }

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]{0,14}[a-z0-9])?$", var.environment)) && !can(regex("--", var.environment))
    error_message = "environment may contain only lowercase letters, digits, and single hyphens (1-16 characters), starting and ending with a letter or digit."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "dax-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_security_group" "dax" {
  name        = "${local.name_prefix}-dax-sg"
  description = "DAX cluster endpoint access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint (TCP 8111) from within the VPC"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Controlled egress limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-dax-sg"
  })
}

resource "aws_dynamodb_table" "main" {
  name         = "${local.name_prefix}-table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-table"
  })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "dax_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["dax.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "dax" {
  name               = "${local.name_prefix}-role"
  assume_role_policy = data.aws_iam_policy_document.dax_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-role"
  })
}

data "aws_iam_policy_document" "dax_dynamodb" {
  statement {
    sid    = "DaxDynamoDBTableAccess"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:BatchGetItem",
      "dynamodb:Query",
      "dynamodb:Scan",
      "dynamodb:PutItem",
      "dynamodb:BatchWriteItem",
      "dynamodb:DescribeTable",
      "dynamodb:ConditionCheckItem",
    ]

    resources = [
      aws_dynamodb_table.main.arn,
      "${aws_dynamodb_table.main.arn}/index/*",
    ]
  }
}

resource "aws_iam_role_policy" "dax_dynamodb" {
  name   = "${local.name_prefix}-dynamodb-access"
  role   = aws_iam_role.dax.name
  policy = data.aws_iam_policy_document.dax_dynamodb.json
}

resource "aws_dax_subnet_group" "main" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = aws_subnet.private[*].id
}

resource "aws_dax_cluster" "main" {
  cluster_name       = substr(local.name_prefix, 0, 20)
  iam_role_arn       = aws_iam_role.dax.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  availability_zones = [data.aws_availability_zones.available.names[0]]
  subnet_group_name  = aws_dax_subnet_group.main.name
  security_group_ids = [aws_security_group.dax.id]

  server_side_encryption {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.name_prefix
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_cluster_arn" {
  description = "ARN of the DAX cluster."
  value       = aws_dax_cluster.main.arn
}

output "dax_configuration_endpoint" {
  description = "Configuration endpoint (host:port) of the DAX cluster."
  value       = aws_dax_cluster.main.configuration_endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (standard tagging — non-empty defaults, no secrets, no resource attrs)
# ---------------------------------------------------------------------------

variable "project" {
  description = "Project identifier used in resource names and tags."
  type        = string
  default     = "kafka-platform"
}

variable "environment" {
  description = "Environment identifier used in resource tags."
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata lookups only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  msk_cluster_name = "${var.project}-msk-cluster"

  msk_topic_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:topic/${local.msk_cluster_name}/*"

  msk_group_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:group/${local.msk_cluster_name}/*"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking: dedicated VPC and one subnet per broker across distinct AZs
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-vpc"
  })
}

resource "aws_subnet" "msk" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-subnet-${count.index + 1}"
    AZ   = data.aws_availability_zones.available.names[count.index]
  })
}

# ---------------------------------------------------------------------------
# Security group: Kafka TLS (9094) and SASL/IAM (9096) listeners, VPC-internal only
# ---------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "${var.project}-msk-brokers-sg"
  description = "MSK brokers - ingress restricted to Kafka TLS (9094) and SASL/IAM (9096) listeners from the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka TLS listener (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka SASL/IAM listener (9096) from within the VPC"
    from_port   = 9096
    to_port     = 9096
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-brokers-sg"
  })
}

# ---------------------------------------------------------------------------
# KMS key for encryption at rest
# ---------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${var.project}-msk"
  target_key_id = aws_kms_key.msk.key_id
}

# ---------------------------------------------------------------------------
# CloudWatch log group for broker logs
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${var.project}-cluster/broker-logs"
  retention_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-broker-logs"
  })
}

# ---------------------------------------------------------------------------
# MSK cluster: 3 brokers, TLS-only client-broker encryption, IAM + TLS auth
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = local.msk_cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }

    # TLS client authentication is enabled by the presence of this block
    # itself in provider ~> 5.0 (no `enabled` argument exists).
    tls {}
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.msk_cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM: least-privilege role and policy for IAM access control to the cluster
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_client_assume_role" {
  statement {
    sid     = "AllowKafkaClientsToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_client" {
  name               = "${var.project}-msk-client-role"
  description        = "Role assumed by Kafka clients for IAM access control to the MSK cluster"
  assume_role_policy = data.aws_iam_policy_document.msk_client_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-client-role"
  })
}

data "aws_iam_policy_document" "msk_access" {
  statement {
    sid       = "MSKClusterAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [aws_msk_cluster.main.arn]
  }

  statement {
    sid       = "MSKTopicAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [local.msk_topic_arn_pattern]
  }

  statement {
    sid       = "MSKConsumerGroupAccess"
    effect    = "Allow"
    actions   = ["kafka-cluster:*"]
    resources = [local.msk_group_arn_pattern]
  }

  statement {
    sid       = "MSKGetBootstrapBrokers"
    effect    = "Allow"
    actions   = ["kafka:GetBootstrapBrokers"]
    resources = [aws_msk_cluster.main.arn]
  }
}

resource "aws_iam_policy" "msk_access" {
  name        = "${var.project}-msk-access-policy"
  description = "Least-privilege Kafka access scoped to the MSK cluster, its topics, and its consumer groups"
  policy      = data.aws_iam_policy_document.msk_access.json

  tags = merge(local.common_tags, {
    Name = "${var.project}-msk-access-policy"
  })
}

resource "aws_iam_role_policy_attachment" "msk_access" {
  role       = aws_iam_role.msk_client.name
  policy_arn = aws_iam_policy.msk_access.arn
}

# ---------------------------------------------------------------------------
# Outputs: cluster connection information
# ---------------------------------------------------------------------------

output "bootstrap_brokers_tls" {
  description = "Comma-separated list of broker endpoints for TLS connections (port 9094)."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM connections (port 9096)."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "zookeeper_connect_string_tls" {
  description = "TLS-secured ZooKeeper connection string for the MSK cluster."
  value       = aws_msk_cluster.main.zookeeper_connect_string_tls
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used as the prefix for all resource names and the Name tag."
  type        = string
  default     = "kafka"

  validation {
    condition     = length(var.project_name) > 0 && can(regex("^[a-zA-Z0-9-]+$", var.project_name))
    error_message = "project_name must be a non-empty string containing only alphanumeric characters and hyphens."
  }
}

variable "environment" {
  description = "Environment name applied as the Environment tag to every resource."
  type        = string
  default     = "production"

  validation {
    condition     = length(var.environment) > 0 && can(regex("^[a-zA-Z0-9-]+$", var.environment))
    error_message = "environment must be a non-empty string containing only alphanumeric characters and hyphens."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix          = "${var.project_name}-${var.environment}"
  private_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
  })
}

resource "aws_security_group" "kafka_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Client access to MSK Kafka brokers (TLS 9094 and IAM SASL 9098 only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client-broker access over TLS"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client-broker access over IAM SASL"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

resource "aws_kms_key" "msk" {
  description             = "Customer-managed KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.name_prefix}-msk-key-policy"
    Statement = [
      {
        Sid    = "AllowAccountLeastPrivilegeMskAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-msk-key"
  })
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-msk"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}"
  retention_in_days = 365

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

resource "aws_msk_cluster" "main" {
  cluster_name           = local.name_prefix
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.kafka_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM authenticated clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "bootstrap_brokers_tls" {
  description = "Comma-separated list of broker endpoints for TLS authenticated clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "zookeeper_connect_string" {
  description = "Comma-separated list of ZooKeeper connection string endpoints."
  value       = aws_msk_cluster.main.zookeeper_connect_string
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

locals {
  name_prefix = "msk-greenfield"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "msk_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-0"
  }
}

resource "aws_subnet" "msk_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-1"
  }
}

resource "aws_subnet" "msk_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-subnet-2"
  }
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-broker-sg"
  description = "Restrict access to Kafka broker ports for the MSK cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client access over TLS"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client access via SASL/IAM"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper access"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${local.name_prefix}-broker-sg"
  }
}

resource "aws_kms_key" "msk" {
  description             = "KMS key for MSK broker storage encryption at rest"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = {
    Name = "${local.name_prefix}-key"
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-greenfield"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}-cluster"
  retention_in_days = 30

  tags = {
    Name = "${local.name_prefix}-broker-logs"
  }
}

resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-greenfield-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    az_distribution = "DEFAULT"

    client_subnets = [
      aws_subnet.msk_0.id,
      aws_subnet.msk_1.id,
      aws_subnet.msk_2.id,
    ]

    instance_type = "kafka.m5.large"

    security_groups = [
      aws_security_group.msk_brokers.id,
    ]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }

    unauthenticated = false
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = {
    Name = "msk-greenfield-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }

  depends_on = [aws_cloudwatch_log_group.msk_broker_logs]
}

output "msk_cluster_arn" {
  description = "The ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "SASL/IAM bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_zookeeper_connect_string" {
  description = "ZooKeeper connection string for the MSK cluster."
  value       = aws_msk_cluster.main.zookeeper_connect_string
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "msk-${var.environment}"

  common_tags = {
    Project     = "msk-kafka"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "broker" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route_table_association" "broker" {
  count = 3

  subnet_id      = aws_subnet.broker[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "MSK broker ingress: TLS 9094 and IAM SASL 9098 from VPC CIDR only, inter-broker 9092 from within this group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS client traffic on 9094 from within the VPC only"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "IAM-authenticated SASL client traffic on 9098 from within the VPC only"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Inter-broker traffic on 9092 restricted to this security group only"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.name_prefix}/brokers"
  retention_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_resource_policy" "msk_log_delivery" {
  policy_name = "${local.name_prefix}-msk-log-delivery"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "MskCloudWatchLogDelivery"
        Effect    = "Allow"
        Principal = {
          Service = "delivery.logs.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_broker_logs.arn,
          "${aws_cloudwatch_log_group.msk_broker_logs.arn}:log-stream:*"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-msk-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-key"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.7.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.broker[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of broker endpoints for SASL/IAM clients (port 9098)."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cloudwatch_log_group_name" {
  description = "CloudWatch log group receiving MSK broker logs."
  value       = aws_cloudwatch_log_group.msk_broker_logs.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources"
  type        = string
  default     = "production"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC"
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  name_prefix = "msk-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "msk-broker-logging"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_security_group" "msk" {
  name        = "${local.name_prefix}-brokers"
  description = "Inbound Kafka broker and ZooKeeper ports restricted to the MSK VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client plaintext (9092) from within the VPC"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka client TLS (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper (2181) from within the VPC"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers"
  })
}

# -----------------------------------------------------------------------------
# S3 log destination
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = "${local.name_prefix}-broker-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# -----------------------------------------------------------------------------
# Encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-encryption"
  })
}

# -----------------------------------------------------------------------------
# MSK cluster
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "logs/"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string for connecting clients"
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "msk-firehose-broker-logging"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  kafka_ports = {
    zookeeper     = 2181
    client_tls    = 9092
    client_tls2   = 9094
    iam_auth      = 9096
    iam_auth_tls  = 9098
  }
  log_prefix                  = "msk-broker-logs"
  auxiliary_endpoint_services = ["kms", "monitoring"]
}

# ---------------------------------------------------------------------------
# Network: dedicated VPC, one subnet per AZ, MSK security group
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, { Name = "msk-logging-vpc" })
}

resource "aws_subnet" "msk" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(var.tags, { Name = "msk-broker-subnet-${count.index + 1}" })
}

resource "aws_security_group" "msk" {
  name        = "msk-broker-security-group"
  description = "Kafka client/broker traffic for the MSK cluster and HTTPS access to in-VPC AWS service endpoints. No public ingress."
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, { Name = "msk-broker-security-group" })
}

resource "aws_security_group_rule" "msk_ingress_kafka" {
  for_each = local.kafka_ports

  type              = "ingress"
  from_port         = each.value
  to_port           = each.value
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "Kafka ${each.key} port ${each.value} from within the VPC only"
}

# This security group is also attached to the in-VPC AWS service endpoint ENIs
# (Firehose, KMS, CloudWatch), so HTTPS ingress sourced from the VPC CIDR is
# required to allow brokers to reach those endpoints.
resource "aws_security_group_rule" "msk_ingress_https" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "HTTPS from within the VPC to the AWS service endpoint ENIs"
}

resource "aws_security_group_rule" "msk_egress_https" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.msk.id
  description       = "HTTPS toward AWS service endpoints"
}

resource "aws_security_group_rule" "msk_egress_kafka" {
  for_each = local.kafka_ports

  type              = "egress"
  from_port         = each.value
  to_port           = each.value
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk.id
  description       = "Intra-VPC Kafka ${each.key} traffic on port ${each.value}"
}

# ---------------------------------------------------------------------------
# Encryption: customer managed KMS key for MSK broker storage, the Firehose
# stream (at rest), and encrypted broker log delivery to S3
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_kms_key_policy" {
  statement {
    sid       = "EnableIAMPermissions"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowFirehoseStreamEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["firehose.us-east-1.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK broker storage encryption and encrypted broker log delivery"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.msk_kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "msk-broker-storage-key" })
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-broker-storage"
  target_key_id = aws_kms_key.msk.key_id
}

# ---------------------------------------------------------------------------
# In-VPC AWS service endpoints so brokers need no public internet path
# ---------------------------------------------------------------------------

resource "aws_vpc_endpoint" "firehose" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.firehose"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.msk[*].id
  security_group_ids  = [aws_security_group.msk.id]
  private_dns_enabled = true

  tags = merge(var.tags, { Name = "firehose-interface-endpoint" })
}

resource "aws_vpc_endpoint" "auxiliary" {
  for_each = toset(local.auxiliary_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.msk[*].id
  security_group_ids  = [aws_security_group.msk.id]
  private_dns_enabled = true

  tags = merge(var.tags, { Name = "${each.value}-interface-endpoint" })
}

# ---------------------------------------------------------------------------
# S3 destination for Firehose-delivered broker logs
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = "msk-broker-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(var.tags, { Name = "msk-broker-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.msk.arn
    }
  }
}

# ---------------------------------------------------------------------------
# IAM: Firehose delivery role (stream -> S3) and MSK broker log delivery role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_delivery" {
  name               = "msk-firehose-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.firehose_assume_role.json

  tags = merge(var.tags, { Name = "msk-firehose-delivery-role" })
}

data "aws_iam_policy_document" "firehose_s3_access" {
  statement {
    sid    = "WriteBrokerLogObjects"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:AbortMultipartUpload",
    ]

    resources = ["${aws_s3_bucket.msk_logs.arn}/${local.log_prefix}/*"]
  }

  statement {
    sid    = "BucketLevelAccess"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.msk_logs.arn]
  }

  statement {
    sid    = "EncryptDeliveredLogObjects"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_policy" "firehose_delivery" {
  name        = "msk-firehose-delivery-policy"
  description = "Least-privilege S3 and KMS access for the MSK broker log Firehose delivery stream"
  policy      = data.aws_iam_policy_document.firehose_s3_access.json
}

resource "aws_iam_role_policy_attachment" "firehose_delivery" {
  role       = aws_iam_role.firehose_delivery.name
  policy_arn = aws_iam_policy.firehose_delivery.arn
}

data "aws_iam_policy_document" "msk_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kafka.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_log_delivery" {
  name               = "msk-broker-log-delivery-role"
  assume_role_policy = data.aws_iam_policy_document.msk_assume_role.json

  tags = merge(var.tags, { Name = "msk-broker-log-delivery-role" })
}

data "aws_iam_policy_document" "msk_firehose_delivery" {
  statement {
    sid    = "PutBrokerLogsToFirehoseStream"
    effect = "Allow"

    actions = [
      "firehose:PutRecord",
      "firehose:PutRecordBatch",
    ]

    resources = [aws_kinesis_firehose_delivery_stream.msk_logs.arn]
  }

  statement {
    sid    = "UseCustomerManagedKeyForStreamEncryption"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_policy" "msk_log_delivery" {
  name        = "msk-broker-log-delivery-policy"
  description = "Least-privilege Firehose and KMS access for Amazon MSK broker log delivery"
  policy      = data.aws_iam_policy_document.msk_firehose_delivery.json
}

resource "aws_iam_role_policy_attachment" "msk_log_delivery" {
  role       = aws_iam_role.msk_log_delivery.name
  policy_arn = aws_iam_policy.msk_log_delivery.arn
}

# ---------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (direct put -> date-prefixed S3)
# ---------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_logs" {
  name        = "msk-broker-logs"
  destination = "extended_s3"

  server_side_encryption {
    enabled  = true
    key_type = "CUSTOMER_MANAGED_CMK"
    key_arn  = aws_kms_key.msk.arn
  }

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_delivery.arn
    bucket_arn         = aws_s3_bucket.msk_logs.arn
    prefix             = "${local.log_prefix}/!{timestamp:yyyy/MM/dd}/"
    buffering_size     = 5
    buffering_interval = 60
    compression_format = "GZIP"
    kms_key_arn        = aws_kms_key.msk.arn
  }

  tags = merge(var.tags, { Name = "msk-broker-logs" })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Amazon MSK cluster streaming broker logs to the Firehose delivery stream
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "main" {
  cluster_name           = "msk-logging-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3
  enhanced_monitoring    = "PER_BROKER"

  broker_node_group_info {
    az_distribution = "DEFAULT"
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk[*].id
    security_groups = [aws_security_group.msk.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      # MSK's Firehose broker-log destination expects the delivery stream name;
      # the delivery stream ARN is granted to the msk_log_delivery IAM role.
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs.name
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, { Name = "msk-logging-cluster" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the Amazon MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string for Kafka clients."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "firehose_delivery_stream_name" {
  description = "Name of the Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_logs.name
}

output "firehose_delivery_stream_arn" {
  description = "ARN of the Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_logs.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name applied to all resource tags."
  type        = string
  default     = "kafka-platform"
}

variable "environment" {
  description = "Environment name applied to all resource tags."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC hosting the MSK cluster."
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# MSK requires VPC DNS resolution and hostnames for bootstrap broker discovery.
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-vpc"
    }
  )
}

# Three private subnets across three distinct AZs; broker count (3) is a
# multiple of the subnet count (3).
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-private-${count.index + 1}"
      Tier = "private"
    }
  )
}

# Dedicated security group for MSK broker nodes: ingress only on Kafka TLS
# port 9094 from the VPC CIDR, with explicit egress rules.
resource "aws_security_group" "msk_brokers" {
  name        = "${var.project_name}-${var.environment}-msk-brokers-sg"
  description = "Kafka broker nodes - TLS client ingress (9094) from VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client TLS connections from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to AWS service endpoints"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All protocols to resources within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project_name}-${var.environment}-msk-brokers-sg"
    }
  )
}

# Customer-managed KMS key used for MSK encryption at rest.
resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK encryption at rest"
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowAccountRootToAdministerKey"
        Effect    = "Allow"
        Principal = { AWS = local.root_arn }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowAccountRootToUseKey"
        Effect    = "Allow"
        Principal = { AWS = local.root_arn }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid       = "AllowMSKServiceToUseKey"
        Effect    = "Allow"
        Principal = { Service = "msk.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey",
          "kms:ReEncrypt*",
          "kms:CreateGrant"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/msk-encryption-at-rest"
  target_key_id = aws_kms_key.msk.key_id
}

# Managed streaming cluster: 3 brokers across 3 subnets in 3 AZs, encrypted
# at rest with the customer-managed key and in transit with TLS.
resource "aws_msk_cluster" "encrypted_kafka" {
  cluster_name           = "${var.project_name}-${var.environment}-kafka"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.private[0].id,
      aws_subnet.private[1].id,
      aws_subnet.private[2].id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.encrypted_kafka.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated list of TLS bootstrap broker endpoints for clients."
  value       = aws_msk_cluster.encrypted_kafka.bootstrap_brokers_tls
}

output "msk_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the cluster at rest."
  value       = aws_kms_key.msk.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "environment" {
  description = "Environment name used for naming and tagging (non-infrastructure metadata only)."
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional metadata tags applied to all resources (non-infrastructure metadata only)."
  type        = map(string)
  default = {
    Project   = "msk-open-monitoring"
    ManagedBy = "terraform"
  }
}

locals {
  name_prefix = "msk-${var.environment}"
  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers"
  description = "Restrict access to MSK broker ports from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka client/broker port 9092"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka TLS client/broker port 9094"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka IAM client/broker port 9098"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "ZooKeeper port 2181"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All egress within the VPC for Kafka inter-broker traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers"
  })
}

resource "aws_kms_key" "msk" {
  description             = "At-rest encryption key for MSK broker storage"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "msk" {
  name          = "alias/${local.name_prefix}-kafka"
  target_key_id = aws_kms_key.msk.key_id
}

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${var.environment}"
  retention_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_msk_cluster" "kafka" {
  cluster_name           = "${local.name_prefix}-kafka"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.private[0].id,
      aws_subnet.private[1].id,
      aws_subnet.private[2].id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  enhanced_monitoring = "PER_BROKER"

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

locals {
  broker_hosts = [
    for endpoint in split(",", aws_msk_cluster.kafka.bootstrap_brokers_tls) : split(":", endpoint)[0]
  ]

  jmx_scrape_targets  = [for host in local.broker_hosts : "${host}:11001"]
  node_scrape_targets = [for host in local.broker_hosts : "${host}:11002"]
}

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.kafka.arn
}

output "bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints (host:9094, comma separated)."
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
}

output "zookeeper_connect_string" {
  description = "ZooKeeper connect string for the MSK cluster."
  value       = aws_msk_cluster.kafka.zookeeper_connect_string
}

output "prometheus_scrape_endpoints" {
  description = "Prometheus open-monitoring discovery info: JMX exporter on port 11001 and node exporter on port 11002 for each broker host."
  value = {
    jmx_exporter_port   = 11001
    node_exporter_port  = 11002
    jmx_scrape_targets  = local.jmx_scrape_targets
    node_scrape_targets = local.node_scrape_targets
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_count" {
  description = "Number of private subnets (one per AZ) spanning the MSK Serverless cluster."
  type        = number
  default     = 3

  validation {
    condition     = var.subnet_count >= 2
    error_message = "MSK Serverless requires at least two subnets in distinct Availability Zones."
  }
}

variable "cluster_name" {
  description = "Name of the MSK Serverless cluster."
  type        = string
  default     = "msk-serverless-cluster"

  validation {
    condition     = can(regex("^[a-zA-Z0-9-]+$", var.cluster_name))
    error_message = "MSK cluster names may only contain alphanumeric characters and hyphens."
  }
}

variable "project" {
  description = "Project tag applied to all taggable resources."
  type        = string
  default     = "serverless-msk"
}

variable "environment" {
  description = "Environment tag applied to all taggable resources."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  cluster_arn      = aws_msk_serverless_cluster.main.arn
  topic_arn_prefix = "${replace(local.cluster_arn, "cluster/${var.cluster_name}", "topic/${var.cluster_name}")}/*"
  group_arn_prefix = "${replace(local.cluster_arn, "cluster/${var.cluster_name}", "group/${var.cluster_name}")}/*"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-vpc"
    },
  )
}

resource "aws_subnet" "private" {
  count = var.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-private-${format("%02d", count.index + 1)}"
    },
  )
}

resource "aws_security_group" "kafka_clients" {
  name        = "${var.project}-kafka-clients"
  description = "Kafka client access to the MSK Serverless cluster over IAM-authenticated SASL/TLS (TCP 9098)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "IAM-authenticated SASL/TLS traffic from within the VPC only"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Egress restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.project}-kafka-clients"
    },
  )
}

resource "aws_msk_serverless_cluster" "main" {
  cluster_name = var.cluster_name

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids         = aws_subnet.private[*].id
    security_group_ids = [aws_security_group.kafka_clients.id]
  }

  tags = merge(
    local.common_tags,
    {
      Name = var.cluster_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kafka_client" {
  name        = "${var.project}-kafka-client-role"
  description = "IAM role assumed by Kafka client workloads (EC2) connecting to the MSK Serverless cluster"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_instance_profile" "kafka_client" {
  name = "${var.project}-kafka-client-profile"
  role = aws_iam_role.kafka_client.name

  tags = local.common_tags
}

resource "aws_iam_policy" "kafka_client" {
  name        = "${var.project}-kafka-client-policy"
  description = "Least-privilege Kafka client access to the MSK Serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ConnectToCluster"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
        ]
        Resource = [
          aws_msk_serverless_cluster.main.arn,
        ]
      },
      {
        Sid    = "TopicDataAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData",
        ]
        Resource = [
          local.topic_arn_prefix,
        ]
      },
      {
        Sid    = "ConsumerGroupAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:DescribeGroup",
        ]
        Resource = [
          local.group_arn_prefix,
        ]
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "kafka_client" {
  role       = aws_iam_role.kafka_client.name
  policy_arn = aws_iam_policy.kafka_client.arn
}

output "cluster_arn" {
  description = "ARN of the MSK Serverless cluster."
  value       = aws_msk_serverless_cluster.main.arn
}

output "bootstrap_servers_string" {
  description = "Comma-separated bootstrap broker endpoints (hostname:port) for IAM/SASL (TLS) access to the MSK Serverless cluster on port 9098."
  value       = aws_msk_serverless_cluster.main.bootstrap_brokers_sasl_iam
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Input variable: used for resource naming and tags ONLY (never as a substitute
# for a resource attribute), with a default so `terraform apply` runs unattended.
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and tagging only."
  type        = string
  default     = "dev"
}

locals {
  name_prefix  = "msk-${var.environment}"
  cluster_name = "${local.name_prefix}-kafka"

  common_tags = {
    Application = "kafka"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static, well-known provider metadata lookups (no dependency on pre-existing
# infrastructure)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Greenfield networking: VPC, internet gateway, three subnets (one per AZ),
# routing, and the MSK broker security group
# -----------------------------------------------------------------------------

resource "aws_vpc" "kafka_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "kafka_igw" {
  vpc_id = aws_vpc.kafka_vpc.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# MSK requires each broker subnet to be in a distinct Availability Zone:
# 3 brokers => 3 subnets in 3 AZs.
resource "aws_subnet" "kafka_subnet_az1" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az1"
  })
}

resource "aws_subnet" "kafka_subnet_az2" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az2"
  })
}

resource "aws_subnet" "kafka_subnet_az3" {
  vpc_id            = aws_vpc.kafka_vpc.id
  cidr_block        = "10.0.3.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az3"
  })
}

resource "aws_route_table" "kafka_route_table" {
  vpc_id = aws_vpc.kafka_vpc.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-route-table"
  })
}

resource "aws_route" "kafka_default_route" {
  route_table_id         = aws_route_table.kafka_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.kafka_igw.id
}

resource "aws_route_table_association" "kafka_rta_az1" {
  subnet_id      = aws_subnet.kafka_subnet_az1.id
  route_table_id = aws_route_table.kafka_route_table.id
}

resource "aws_route_table_association" "kafka_rta_az2" {
  subnet_id      = aws_subnet.kafka_subnet_az2.id
  route_table_id = aws_route_table.kafka_route_table.id
}

resource "aws_route_table_association" "kafka_rta_az3" {
  subnet_id      = aws_subnet.kafka_subnet_az3.id
  route_table_id = aws_route_table.kafka_route_table.id
}

# Broker security group: ingress restricted to TLS (9094), SASL/IAM (9098) and
# ZooKeeper (2181) from within the VPC only, plus a self-referencing rule for
# broker-to-broker traffic. No 0.0.0.0/0 ingress is permitted.
resource "aws_security_group" "kafka_broker_sg" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Security group for the MSK broker nodes (TLS 9094, SASL/IAM 9098, ZooKeeper 2181, broker-to-broker)"
  vpc_id      = aws_vpc.kafka_vpc.id

  ingress {
    description = "TLS client-broker connections"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "SASL/IAM client-broker connections"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "ZooKeeper client connections"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.kafka_vpc.cidr_block]
  }

  ingress {
    description = "Broker-to-broker traffic from the security group itself"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "Allow broker outbound access to AWS service endpoints"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

# -----------------------------------------------------------------------------
# Customer managed KMS key for encryption at rest and broker log encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "kafka_kms_key" {
  description             = "Customer managed key for MSK cluster encryption at rest and CloudWatch broker log encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMUserPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowCloudWatchLogsToEncryptLogs"
        Effect    = "Allow"
        Principal = {
          Service = "logs.${data.aws_region.current.name}.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "kafka_kms_alias" {
  name          = "alias/${local.name_prefix}-kafka"
  target_key_id = aws_kms_key.kafka_kms_key.key_id
}

# -----------------------------------------------------------------------------
# CloudWatch log group for MSK broker logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "kafka_broker_logs" {
  name              = "/aws/msk/${local.cluster_name}"
  retention_in_days = 30
  kms_key_id        = aws_kms_key.kafka_kms_key.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-broker-logs"
  })
}

# -----------------------------------------------------------------------------
# Provisioned MSK cluster with exactly 3 broker nodes (serverless MSK does not
# support broker nodes, so a provisioned cluster is used). Broker EBS storage
# size uses the provider v5 nested form:
#   broker_node_group_info.storage_info.ebs_storage_info.volume_size
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka_cluster" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3
  enhanced_monitoring    = "DEFAULT"

  broker_node_group_info {
    instance_type  = "kafka.m5.large"
    client_subnets = [
      aws_subnet.kafka_subnet_az1.id,
      aws_subnet.kafka_subnet_az2.id,
      aws_subnet.kafka_subnet_az3.id,
    ]
    security_groups = [aws_security_group.kafka_broker_sg.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.kafka_kms_key.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.kafka_broker_logs.name
      }
    }
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# IAM: least-privilege client role for IAM access control on the cluster.
# Only kafka-cluster actions, scoped to this cluster's ARN and its
# topic/group ARNs. No wildcard Action/Resource statements.
# -----------------------------------------------------------------------------

resource "aws_iam_role" "kafka_client_role" {
  name = "${local.name_prefix}-kafka-client-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2ClientAssume"
        Effect    = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kafka-client-role"
  })
}

resource "aws_iam_role_policy" "kafka_client_policy" {
  name = "${local.name_prefix}-kafka-client-access"
  role = aws_iam_role.kafka_client_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KafkaClusterConnect"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
        ]
        Resource = [
          aws_msk_cluster.kafka_cluster.arn,
        ]
      },
      {
        Sid    = "KafkaTopicOperations"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:ReadData",
          "kafka-cluster:WriteData",
        ]
        Resource = [
          aws_msk_cluster.kafka_cluster.arn,
          "${aws_msk_cluster.kafka_cluster.arn}/topic/*",
        ]
      },
      {
        Sid    = "KafkaConsumerGroupOperations"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
        ]
        Resource = [
          "${aws_msk_cluster.kafka_cluster.arn}/group/*",
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs for client onboarding
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the provisioned MSK cluster (3 broker nodes)."
  value       = aws_msk_cluster.kafka_cluster.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated list of bootstrap broker endpoints for TLS clients (port 9094)."
  value       = aws_msk_cluster.kafka_cluster.bootstrap_brokers_tls
}

output "msk_bootstrap_brokers_sasl_iam" {
  description = "Comma-separated list of bootstrap broker endpoints for SASL/IAM authenticated clients (port 9098)."
  value       = aws_msk_cluster.kafka_cluster.bootstrap_brokers_sasl_iam
}

output "kafka_client_role_arn" {
  description = "ARN of the least-privilege IAM role clients assume for IAM-authenticated access to the cluster."
  value       = aws_iam_role.kafka_client_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource in this configuration."
  type        = string
  default     = "dev"
}

locals {
  name_prefix  = "msk_${var.environment}"
  cluster_name = "msk-${var.environment}"

  common_tags = {
    environment = var.environment
    component   = "msk"
    managed_by  = "terraform"
  }

  # Least-privilege resource patterns derived from the cluster ARN.
  # MSK IAM resource format:
  #   arn:aws:kafka:<region>:<account>:topic/<cluster-name>/<topic-pattern>/<cluster-uuid>
  #   arn:aws:kafka:<region>:<account>:group/<cluster-name>/<group-pattern>/<cluster-uuid>
  msk_topic_arn_pattern = replace(aws_msk_cluster.msk.arn, ":cluster/${local.cluster_name}/", ":topic/${local.cluster_name}/*/")
  msk_group_arn_pattern = replace(aws_msk_cluster.msk.arn, ":cluster/${local.cluster_name}/", ":group/${local.cluster_name}/*/")
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}_vpc" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "msk_private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { name = "${local.name_prefix}_private_subnet_${count.index + 1}" })
}

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}_brokers_sg"
  description = "MSK broker access restricted to the VPC: IAM listener (9098), TLS listener (9094), and inter-broker traffic from itself"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka clients over the IAM-authenticated listener (port 9098)"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka clients over the TLS listener (port 9094)"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "MSK inter-broker communication on the in-cluster listener (required between broker ENIs sharing this security group)"
    from_port   = 9093
    to_port     = 9093
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all outbound traffic from brokers"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { name = "${local.name_prefix}_brokers_sg" })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer-managed key used for encryption at rest of the MSK cluster"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { name = "${local.name_prefix}_kms_key" })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Observability
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.cluster_name}/broker_logs"
  retention_in_days = 30

  tags = merge(local.common_tags, { name = "${local.name_prefix}_broker_logs" })
}

# ---------------------------------------------------------------------------
# MSK cluster (provisioned, 3 brokers across 3 AZs)
# ---------------------------------------------------------------------------

resource "aws_msk_cluster" "msk" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.msk_private[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    connectivity_info {
      public_access {
        type = "DISABLED"
      }
    }

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  client_authentication {
    sasl {
      iam   = true
      scram = false
    }

    tls {}

    unauthenticated = false
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  tags = merge(local.common_tags, { name = local.cluster_name })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM: least-privilege Kafka client access policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_client_access" {
  statement {
    sid       = "MSKClusterConnect"
    effect    = "Allow"
    actions   = ["kafka-cluster:Connect"]
    resources = [aws_msk_cluster.msk.arn]
  }

  statement {
    sid    = "MSKTopicReadWrite"
    effect = "Allow"
    actions = [
      "kafka-cluster:CreateTopic",
      "kafka-cluster:DescribeTopic",
      "kafka-cluster:AlterTopic",
      "kafka-cluster:WriteData",
      "kafka-cluster:ReadData",
    ]
    resources = [local.msk_topic_arn_pattern]
  }

  statement {
    sid    = "MSKConsumerGroupManage"
    effect = "Allow"
    actions = [
      "kafka-cluster:AlterGroup",
      "kafka-cluster:DescribeGroup",
    ]
    resources = [local.msk_group_arn_pattern]
  }
}

resource "aws_iam_policy" "msk_client_access" {
  name        = "${local.name_prefix}_client_access"
  description = "Least-privilege Kafka client access to the ${local.cluster_name} MSK cluster over IAM authentication"
  policy      = data.aws_iam_policy_document.msk_client_access.json

  tags = merge(local.common_tags, { name = "${local.name_prefix}_client_access" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.msk.arn
}

output "msk_bootstrap_brokers_iam" {
  description = "Comma-separated bootstrap broker endpoints for IAM-authenticated clients (port 9098)."
  value       = aws_msk_cluster.msk.bootstrap_brokers_sasl_iam
}

output "msk_bootstrap_brokers_tls" {
  description = "Comma-separated bootstrap broker endpoints for TLS clients (port 9094)."
  value       = aws_msk_cluster.msk.bootstrap_brokers_tls
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-2"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC"
  type        = string
  default     = "10.0.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  kafka_topic_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:topic/${aws_msk_serverless_cluster.main.cluster_name}/*"

  kafka_group_arn_pattern = "arn:${data.aws_partition.current.partition}:kafka:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:group/${aws_msk_serverless_cluster.main.cluster_name}/*"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "msk-serverless-vpc-${var.environment}"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "msk-serverless-private-a-${var.environment}"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "msk-serverless-private-b-${var.environment}"
  })
}

resource "aws_security_group" "msk_clients" {
  name        = "msk-serverless-clients-${var.environment}"
  description = "Restrict ingress to IAM-authenticated Kafka traffic (TCP 9098) from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Kafka SASL/IAM bootstrap and broker traffic from within the VPC"
    from_port   = 9098
    to_port     = 9098
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "msk-serverless-clients-${var.environment}"
  })
}

resource "aws_msk_serverless_cluster" "main" {
  cluster_name = "msk-serverless-${var.environment}"

  client_authentication {
    sasl {
      iam {
        enabled = true
      }
    }
  }

  vpc_config {
    subnet_ids = [
      aws_subnet.private_a.id,
      aws_subnet.private_b.id,
    ]
    security_group_ids = [aws_security_group.msk_clients.id]
  }

  tags = merge(local.common_tags, {
    Name = "msk-serverless-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "kafka_client" {
  name        = "msk-serverless-kafka-client-${var.environment}"
  description = "Assumed by Kafka client workloads to authenticate to the MSK Serverless cluster via AWS IAM"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "ec2.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "kafka_client_cluster" {
  name = "msk-serverless-cluster-access"
  role = aws_iam_role.kafka_client.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "MSKServerlessClusterAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:DescribeCluster",
          "kafka-cluster:DescribeClusterV2"
        ]
        Resource = [aws_msk_serverless_cluster.main.arn]
      }
    ]
  })
}

resource "aws_iam_policy" "kafka_client_data" {
  name        = "msk-serverless-kafka-data-${var.environment}"
  description = "Least-privilege Kafka topic and consumer group access scoped to the MSK Serverless cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "KafkaTopicAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:CreateTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:AlterTopic",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData"
        ]
        Resource = [local.kafka_topic_arn_pattern]
      },
      {
        Sid    = "KafkaConsumerGroupAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = [local.kafka_group_arn_pattern]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "kafka_client_data" {
  role       = aws_iam_role.kafka_client.name
  policy_arn = aws_iam_policy.kafka_client_data.arn
}

output "bootstrap_brokers_sasl_iam" {
  description = "IAM-authenticated (SASL over TLS, port 9098) bootstrap broker endpoints for the MSK Serverless cluster"
  value       = aws_msk_serverless_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_cluster_arn" {
  description = "ARN of the MSK Serverless cluster"
  value       = aws_msk_serverless_cluster.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = local.aws_region
}

# -----------------------------------------------------------------------------
# User-controlled metadata
# -----------------------------------------------------------------------------

variable "tags" {
  description = "Optional user-defined tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Static / well-known lookups only (no pre-existing infrastructure is discovered)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Naming and tagging
# -----------------------------------------------------------------------------

resource "random_id" "log_bucket_suffix" {
  byte_length = 4
}

locals {
  # Static deployment parameter, declared once and shared by the provider
  # block and all policy ARN construction. The deployment targets us-east-1
  # per the grounded objectives; no region data source is required.
  aws_region = "us-east-1"

  name_prefix          = "kafka-broker-logs"
  environment          = "production"
  cluster_name         = "${local.name_prefix}-cluster"
  log_group_name       = "/aws/msk/${local.name_prefix}"
  bucket_name          = "${local.name_prefix}-${random_id.log_bucket_suffix.hex}"
  firehose_stream_name = "amazon-msk-${local.name_prefix}"
  s3_log_prefix        = "broker-logs"

  common_tags = merge(var.tags, {
    Name        = local.name_prefix
    Environment = local.environment
    ManagedBy   = "terraform"
  })
}

# -----------------------------------------------------------------------------
# Networking foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-1"
  })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-2"
  })
}

resource "aws_subnet" "public_3" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-3"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "public_3" {
  subnet_id      = aws_subnet.public_3.id
  route_table_id = aws_route_table.main.id
}

# -----------------------------------------------------------------------------
# MSK broker security group (VPC-only ingress, all egress allowed)
# -----------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "${local.name_prefix}-brokers-sg"
  description = "Kafka broker and ZooKeeper access restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "ZooKeeper (2181) from within the VPC"
    from_port   = 2181
    to_port     = 2181
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka broker listener (9092) from within the VPC"
    from_port   = 9092
    to_port     = 9092
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka TLS listener (9094) from within the VPC"
    from_port   = 9094
    to_port     = 9094
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Kafka SASL/IAM listener (9096) from within the VPC"
    from_port   = 9096
    to_port     = 9096
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-brokers-sg"
  })
}

# -----------------------------------------------------------------------------
# KMS key: MSK encryption at rest + CloudWatch Logs encryption
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_kms_key" {
  statement {
    sid    = "EnableIAMPermissionsForAccountRoot"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAmazonMSKEncryptionAtRest"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["msk.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsBrokerLogEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.aws_region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]

    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values = [
        "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}",
        "arn:${data.aws_partition.current.partition}:logs:${local.aws_region}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}:*",
      ]
    }
  }
}

resource "aws_kms_key" "msk" {
  description             = "MSK encryption at rest and broker log encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.msk_kms_key.json

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# CloudWatch Logs destination
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = local.log_group_name
  retention_in_days = 30
  kms_key_id        = aws_kms_key.msk.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.log_group_name
  })
}

# -----------------------------------------------------------------------------
# S3 destination bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_broker_logs" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })
}

resource "aws_s3_bucket_public_access_block" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.msk.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "msk_broker_logs" {
  bucket = aws_s3_bucket.msk_broker_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.msk_broker_logs.arn,
          "${aws_s3_bucket.msk_broker_logs.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.msk_broker_logs]
}

# -----------------------------------------------------------------------------
# IAM: MSK -> CloudWatch Logs
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_cloudwatch_logs_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_cloudwatch_logs" {
  name               = "${local.name_prefix}-cw-logs-role"
  description        = "Allows Amazon MSK to export broker logs to CloudWatch Logs"
  assume_role_policy = data.aws_iam_policy_document.msk_cloudwatch_logs_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_cloudwatch_logs_write" {
  statement {
    sid    = "MSKBrokerLogsToCloudWatch"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.msk_broker_logs.arn,
      "${aws_cloudwatch_log_group.msk_broker_logs.arn}:*",
    ]
  }
}

resource "aws_iam_role_policy" "msk_cloudwatch_logs_write" {
  name   = "${local.name_prefix}-cw-logs-write"
  role   = aws_iam_role.msk_cloudwatch_logs.name
  policy = data.aws_iam_policy_document.msk_cloudwatch_logs_write.json
}

# -----------------------------------------------------------------------------
# IAM: MSK -> Kinesis Data Firehose (producer)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_firehose_producer_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_firehose_producer" {
  name               = "${local.name_prefix}-firehose-producer-role"
  description        = "Allows Amazon MSK to export broker logs to Kinesis Data Firehose"
  assume_role_policy = data.aws_iam_policy_document.msk_firehose_producer_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_firehose_producer_write" {
  statement {
    sid    = "MSKBrokerLogsToFirehose"
    effect = "Allow"

    actions = [
      "firehose:PutRecord",
      "firehose:PutRecordBatch",
      "firehose:CheckIfProducerIsDisabled",
      "firehose:DescribeDeliveryStream",
      "firehose:ListDeliveryStreams",
    ]

    resources = [aws_kinesis_firehose_delivery_stream.msk_broker_logs.arn]
  }
}

resource "aws_iam_role_policy" "msk_firehose_producer_write" {
  name   = "${local.name_prefix}-firehose-producer-write"
  role   = aws_iam_role.msk_firehose_producer.name
  policy = data.aws_iam_policy_document.msk_firehose_producer_write.json
}

# -----------------------------------------------------------------------------
# IAM: MSK -> S3 (direct broker log delivery)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "msk_s3_logs_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_s3_logs" {
  name               = "${local.name_prefix}-s3-logs-role"
  description        = "Allows Amazon MSK to export broker logs directly to S3"
  assume_role_policy = data.aws_iam_policy_document.msk_s3_logs_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "msk_s3_logs_write" {
  statement {
    sid    = "MSKBrokerLogsToS3"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.msk_broker_logs.arn,
      "${aws_s3_bucket.msk_broker_logs.arn}/${local.s3_log_prefix}/*",
    ]
  }

  statement {
    sid    = "MSKBrokerLogsS3KMS"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_role_policy" "msk_s3_logs_write" {
  name   = "${local.name_prefix}-s3-logs-write"
  role   = aws_iam_role.msk_s3_logs.name
  policy = data.aws_iam_policy_document.msk_s3_logs_write.json
}

# -----------------------------------------------------------------------------
# IAM: Firehose -> S3 (delivery role)
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "firehose_s3_delivery_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["firehose.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "firehose_s3_delivery" {
  name               = "${local.name_prefix}-firehose-s3-role"
  description        = "Allows Kinesis Data Firehose to deliver broker logs to S3"
  assume_role_policy = data.aws_iam_policy_document.firehose_s3_delivery_assume.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "firehose_s3_delivery_write" {
  statement {
    sid    = "FirehoseBrokerLogsToS3"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:AbortMultipartUpload",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.msk_broker_logs.arn,
      "${aws_s3_bucket.msk_broker_logs.arn}/${local.s3_log_prefix}/*",
    ]
  }

  statement {
    sid    = "FirehoseBrokerLogsS3KMS"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
    ]

    resources = [aws_kms_key.msk.arn]
  }
}

resource "aws_iam_role_policy" "firehose_s3_delivery_write" {
  name   = "${local.name_prefix}-firehose-s3-write"
  role   = aws_iam_role.firehose_s3_delivery.name
  policy = data.aws_iam_policy_document.firehose_s3_delivery_write.json
}

# -----------------------------------------------------------------------------
# Kinesis Data Firehose delivery stream (name MUST begin with "amazon-msk-")
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_broker_logs" {
  name        = local.firehose_stream_name
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_s3_delivery.arn
    bucket_arn         = aws_s3_bucket.msk_broker_logs.arn
    prefix             = "${local.s3_log_prefix}/"
    buffering_size     = 5
    buffering_interval = 300
    compression_format = "GZIP"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.firehose_stream_name
  })

  depends_on = [aws_iam_role_policy.firehose_s3_delivery_write]
}

# -----------------------------------------------------------------------------
# Amazon MSK cluster (3 brokers, encryption at rest + TLS in transit, open monitoring)
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka" {
  cluster_name           = local.cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets = [
      aws_subnet.public_1.id,
      aws_subnet.public_2.id,
      aws_subnet.public_3.id,
    ]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }

    connectivity_info {
      public_access {
        type = "DISABLED"
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }

      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
      }

      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_broker_logs.bucket
        prefix  = local.s3_log_prefix
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.cluster_name
  })

  depends_on = [
    aws_iam_role_policy.msk_cloudwatch_logs_write,
    aws_iam_role_policy.msk_firehose_producer_write,
    aws_iam_role_policy.msk_s3_logs_write,
  ]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the Amazon MSK cluster."
  value       = aws_msk_cluster.kafka.arn
}

output "msk_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for Kafka client configuration."
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
  sensitive   = true
}

output "cloudwatch_log_group_name" {
  description = "CloudWatch Logs log group receiving MSK broker logs."
  value       = aws_cloudwatch_log_group.msk_broker_logs.name
}

output "firehose_delivery_stream_name" {
  description = "Kinesis Data Firehose delivery stream receiving MSK broker logs."
  value       = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
}

output "s3_bucket_name" {
  description = "S3 bucket receiving MSK broker logs."
  value       = aws_s3_bucket.msk_broker_logs.bucket
}

###############################################################################
# Terraform + provider configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated MSK VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "debezium_plugin_zip_path" {
  description = "Local path to the Debezium plugin archive (debezium.zip) uploaded to S3."
  type        = string
  default     = "debezium.zip"
}

variable "db_username" {
  description = "Username of the Debezium source database (non-secret identifier)."
  type        = string
  default     = "debezium"
}

variable "db_password" {
  description = "Password of the Debezium source database. Supply via a sensitive input in real deployments; when omitted, a deterministic value is generated and persisted only in Secrets Manager."
  type        = string
  sensitive   = true
  default     = null
}

variable "db_hostname" {
  description = "Hostname of the Debezium source database."
  type        = string
  default     = "source-database.internal"
}

variable "db_port" {
  description = "Port of the Debezium source database."
  type        = string
  default     = "3306"
}

###############################################################################
# Data sources (static / provider metadata lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "msk-debezium-${lower(var.environment)}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "msk-connect-debezium"
  }

  # The source database password is never stored as plaintext in this
  # configuration: it is either supplied as a sensitive variable or derived
  # deterministically from non-secret infrastructure identifiers and then
  # persisted in AWS Secrets Manager.
  source_db_password = coalesce(var.db_password, sha256("debezium-source-db-seed-${aws_vpc.main.id}"))
}

###############################################################################
# Networking: VPC, subnets, routing, service endpoints
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Public subnets (one per AZ) host the NAT gateways that provide the private
# MSK / MSK Connect subnets with outbound connectivity to AWS service endpoints.
resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-0" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-1" })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-2" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat_0" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-0" })
}

resource "aws_eip" "nat_1" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-1" })
}

resource "aws_eip" "nat_2" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-eip-2" })
}

resource "aws_nat_gateway" "nat_0" {
  allocation_id = aws_eip.nat_0.id
  subnet_id     = aws_subnet.public_0.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-0" })
}

resource "aws_nat_gateway" "nat_1" {
  allocation_id = aws_eip.nat_1.id
  subnet_id     = aws_subnet.public_1.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-1" })
}

resource "aws_nat_gateway" "nat_2" {
  allocation_id = aws_eip.nat_2.id
  subnet_id     = aws_subnet.public_2.id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nat-2" })
}

# Private subnets (one per distinct AZ) host the 3 MSK broker nodes and the
# MSK Connect workers.
resource "aws_subnet" "private_0" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 10)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-0" })
}

resource "aws_subnet" "private_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 11)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-1" })
}

resource "aws_subnet" "private_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, 12)
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-2" })
}

resource "aws_route_table" "private_0" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_0.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-0" })
}

resource "aws_route_table" "private_1" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_1.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-1" })
}

resource "aws_route_table" "private_2" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat_2.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt-2" })
}

resource "aws_route_table_association" "private_0" {
  subnet_id      = aws_subnet.private_0.id
  route_table_id = aws_route_table.private_0.id
}

resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private_1.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private_2.id
}

# S3 gateway endpoint keeps custom-plugin artifact traffic on the AWS backbone.
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private_0.id, aws_route_table.private_1.id, aws_route_table.private_2.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-s3-endpoint" })
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "msk_connect_workers" {
  name_prefix = "${local.name_prefix}-workers-"
  description = "MSK Connect worker nodes. Outbound access to MSK brokers (9094/9098), S3, CloudWatch Logs and Secrets Manager."
  vpc_id      = aws_vpc.main.id

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-msk-connect-workers" })
}

resource "aws_security_group" "msk_brokers" {
  name_prefix = "${local.name_prefix}-brokers-"
  description = "MSK broker nodes. TLS client traffic (9094) and SASL/IAM traffic (9098) only from MSK Connect workers, plus self-referencing inter-broker traffic."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "TLS client traffic (9094) from MSK Connect workers"
    from_port       = 9094
    to_port         = 9094
    protocol        = "tcp"
    security_groups = [aws_security_group.msk_connect_workers.id]
  }

  ingress {
    description     = "SASL/IAM client traffic (9098) from MSK Connect workers"
    from_port       = 9098
    to_port         = 9098
    protocol        = "tcp"
    security_groups = [aws_security_group.msk_connect_workers.id]
  }

  ingress {
    description = "Inter-broker communication (self-referencing security group)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  egress {
    description = "All outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-msk-brokers" })
}

###############################################################################
# MSK cluster (3 brokers, TLS + SASL/IAM auth, KMS-managed encryption at rest)
###############################################################################

resource "aws_msk_cluster" "main" {
  cluster_name           = "${local.name_prefix}-cluster"
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = [aws_subnet.private_0.id, aws_subnet.private_1.id, aws_subnet.private_2.id]
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  # TLS client authentication with AWS-signed certificates and SASL/IAM
  # (SigV4) authentication for MSK Connect; unauthenticated client access
  # is explicitly disabled.
  client_authentication {
    tls {}

    sasl {
      iam = true
    }

    unauthenticated = false
  }

  # Encryption at rest is KMS-managed (AWS managed key aws/msk by default);
  # client-broker traffic is encrypted in transit with TLS only.
  encryption_info {
    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 bucket for the custom plugin artifact
###############################################################################

resource "aws_s3_bucket" "plugin_artifacts" {
  bucket = "${local.name_prefix}-plugin-artifacts-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-plugin-artifacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "plugin_artifacts" {
  bucket                  = aws_s3_bucket.plugin_artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "plugin_artifacts" {
  bucket = aws_s3_bucket.plugin_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "plugin_artifacts" {
  bucket = aws_s3_bucket.plugin_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_object" "debezium_plugin" {
  bucket       = aws_s3_bucket.plugin_artifacts.id
  key          = "plugins/debezium.zip"
  source       = var.debezium_plugin_zip_path
  content_type = "application/zip"

  depends_on = [aws_s3_bucket_versioning.plugin_artifacts]
}

###############################################################################
# MSK Connect custom plugin (Debezium)
###############################################################################

resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "${local.name_prefix}-debezium-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn     = aws_s3_bucket.plugin_artifacts.arn
      file_key       = aws_s3_object.debezium_plugin.key
      object_version = aws_s3_object.debezium_plugin.version_id
    }
  }

  tags = local.common_tags
}

###############################################################################
# CloudWatch Logs for connector worker logs
###############################################################################

resource "aws_cloudwatch_log_group" "msk_connect_worker" {
  name              = "/aws/msk-connect/${local.name_prefix}/workers"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-worker-logs" })
}

###############################################################################
# Source database credentials in Secrets Manager (no plaintext secrets here)
###############################################################################

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "${local.name_prefix}-debezium-db-credentials"
  description             = "Credentials of the source database consumed by the Debezium MSK Connect connector."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = var.db_username
    password = local.source_db_password
  })
}

###############################################################################
# MSK Connect service execution role (least privilege, inline policies)
###############################################################################

data "aws_iam_policy_document" "msk_connect_assume_role" {
  statement {
    sid     = "AllowMSKConnectToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["kafkaconnect.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "msk_connect_execution" {
  name               = "${local.name_prefix}-connector-execution"
  description        = "Service execution role assumed by MSK Connect connector workers."
  assume_role_policy = data.aws_iam_policy_document.msk_connect_assume_role.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-connector-execution" })
}

data "aws_iam_policy_document" "plugin_artifact_read" {
  statement {
    sid       = "ReadCustomPluginArtifact"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.plugin_artifacts.arn}/plugins/*"]
  }
}

data "aws_iam_policy_document" "msk_cluster_access" {
  statement {
    sid    = "ConnectAndDescribeMSKCluster"
    effect = "Allow"
    actions = [
      "kafka:Connect",
      "kafka:CreateVpcConnection",
      "kafka:DescribeCluster",
      "kafka:DescribeClusterV2",
      "kafka:GetBootstrapBrokers",
    ]
    resources = [aws_msk_cluster.main.arn]
  }

  # Data-plane permissions enforced by the cluster's SASL/IAM access control.
  statement {
    sid    = "IAMAuthClusterDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:Connect",
      "kafka-cluster:DescribeCluster",
    ]
    resources = [aws_msk_cluster.main.arn]
  }

  statement {
    sid    = "IAMAuthTopicDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:CreateTopic",
      "kafka-cluster:DescribeTopic",
      "kafka-cluster:AlterTopic",
      "kafka-cluster:WriteData",
      "kafka-cluster:ReadData",
    ]
    resources = ["${aws_msk_cluster.main.arn}/topic/*"]
  }

  statement {
    sid    = "IAMAuthGroupDataPlane"
    effect = "Allow"
    actions = [
      "kafka-cluster:DescribeGroup",
      "kafka-cluster:AlterGroup",
    ]
    resources = ["${aws_msk_cluster.main.arn}/group/*"]
  }
}

data "aws_iam_policy_document" "worker_log_delivery" {
  statement {
    sid       = "DeliverWorkerLogsToCloudWatch"
    effect    = "Allow"
    actions   = ["logs:CreateLogStream", "logs:PutLogEvents"]
    resources = ["${aws_cloudwatch_log_group.msk_connect_worker.arn}:*"]
  }
}

data "aws_iam_policy_document" "db_credentials_read" {
  statement {
    sid       = "ReadSourceDatabaseCredentials"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }
}

resource "aws_iam_role_policy" "plugin_artifact_read" {
  name   = "custom-plugin-artifact-read"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.plugin_artifact_read.json
}

resource "aws_iam_role_policy" "msk_cluster_access" {
  name   = "msk-cluster-access"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.msk_cluster_access.json
}

resource "aws_iam_role_policy" "worker_log_delivery" {
  name   = "worker-log-delivery"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.worker_log_delivery.json
}

resource "aws_iam_role_policy" "db_credentials_read" {
  name   = "source-db-credentials-read"
  role   = aws_iam_role.msk_connect_execution.name
  policy = data.aws_iam_policy_document.db_credentials_read.json
}

###############################################################################
# MSK Connect connector (Debezium, SASL/IAM over TLS to the MSK cluster)
###############################################################################

resource "aws_mskconnect_connector" "debezium_source" {
  name        = "${local.name_prefix}-debezium-connector"
  description = "Debezium source connector streaming change data events from the source database into the MSK cluster."

  kafkaconnect_version = "3.6.0"

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.main.bootstrap_brokers_sasl_iam

      vpc {
        security_groups = [aws_security_group.msk_connect_workers.id]
        subnets         = [aws_subnet.private_0.id, aws_subnet.private_1.id, aws_subnet.private_2.id]
      }
    }
  }

  kafka_cluster_client_authentication {
    authentication_type = "IAM"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  capacity {
    provisioned_capacity {
      worker_count = 1
      mcu_count    = 1
    }
  }

  connector_configuration = {
    "bootstrap.servers"                               = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
    "connector.class"                                 = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max"                                       = "1"
    "database.hostname"                               = var.db_hostname
    "database.port"                                   = var.db_port
    "database.user"                                   = "$${secretsManager:${aws_secretsmanager_secret.db_credentials.arn}:username}"
    "database.password"                               = "$${secretsManager:${aws_secretsmanager_secret.db_credentials.arn}:password}"
    "database.server.id"                              = "184054"
    "database.include.list"                           = "inventory"
    "topic.prefix"                                    = "debezium-source"
    "schema.history.internal.kafka.bootstrap.servers" = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
    "schema.history.internal.kafka.topic"             = "debezium-source.schema-changes"
    "schema.history.internal.kafka.security.protocol" = "SASL_SSL"
    "key.converter"                                   = "org.apache.kafka.connect.json.JsonConverter"
    "value.converter"                                 = "org.apache.kafka.connect.json.JsonConverter"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  service_execution_role_arn = aws_iam_role.msk_connect_execution.arn

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_connect_worker.name
      }
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-debezium-connector" })

  depends_on = [
    aws_iam_role_policy.plugin_artifact_read,
    aws_iam_role_policy.msk_cluster_access,
    aws_iam_role_policy.worker_log_delivery,
    aws_iam_role_policy.db_credentials_read,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster."
  value       = aws_msk_cluster.main.arn
}

output "msk_cluster_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker string of the MSK cluster."
  value       = aws_msk_cluster.main.bootstrap_brokers_tls
}

output "msk_cluster_bootstrap_brokers_sasl_iam" {
  description = "SASL/IAM bootstrap broker string of the MSK cluster."
  value       = aws_msk_cluster.main.bootstrap_brokers_sasl_iam
}

output "msk_connect_custom_plugin_arn" {
  description = "ARN of the Debezium MSK Connect custom plugin."
  value       = aws_mskconnect_custom_plugin.debezium.arn
}

output "msk_connect_connector_arn" {
  description = "ARN of the Debezium MSK Connect connector."
  value       = aws_mskconnect_connector.debezium_source.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources (pure local / static lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  region               = "us-east-1"
  account_id           = data.aws_caller_identity.current.account_id
  partition            = data.aws_partition.current.partition
  kafka_cluster_name   = "msk-kafka"
  msk_logs_bucket_name = "msk-logs-${local.account_id}"
  plugin_bucket_name   = "msk-connect-plugins-${local.account_id}"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "msk-vpc"
  }
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)

  tags = {
    Name = "msk-private-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "msk-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# Security groups
# -----------------------------------------------------------------------------

resource "aws_security_group" "msk_brokers" {
  name        = "msk-broker-sg"
  description = "Security group for MSK Kafka brokers"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "msk-broker-sg"
  }
}

resource "aws_security_group" "msk_connect_workers" {
  name        = "msk-connect-worker-sg"
  description = "Security group for MSK Connect worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "msk-connect-worker-sg"
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "msk-vpc-endpoint-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "msk-vpc-endpoint-sg"
  }
}

# Broker ingress: Kafka TLS (9094) restricted to the VPC CIDR
resource "aws_security_group_rule" "msk_brokers_ingress_from_vpc" {
  type              = "ingress"
  from_port         = 9094
  to_port           = 9094
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_brokers.id
  description       = "Kafka TLS from within the VPC"
}

# Broker ingress: Kafka TLS (9094) sourced from the MSK Connect worker SG
resource "aws_security_group_rule" "msk_brokers_ingress_from_connect" {
  type                     = "ingress"
  from_port                = 9094
  to_port                  = 9094
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_brokers.id
  source_security_group_id = aws_security_group.msk_connect_workers.id
  description              = "Kafka TLS from MSK Connect workers"
}

resource "aws_security_group_rule" "msk_brokers_egress_all" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.msk_brokers.id
  description       = "Outbound to AWS service endpoints (CloudWatch, Firehose, S3)"
}

# Connect worker egress: Kafka TLS (9094) to the broker security group
resource "aws_security_group_rule" "msk_connect_egress_to_brokers" {
  type                     = "egress"
  from_port                = 9094
  to_port                  = 9094
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_connect_workers.id
  source_security_group_id = aws_security_group.msk_brokers.id
  description              = "Kafka TLS to MSK brokers"
}

resource "aws_security_group_rule" "msk_connect_egress_to_endpoints" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.msk_connect_workers.id
  source_security_group_id = aws_security_group.vpc_endpoints.id
  description              = "HTTPS to VPC interface endpoints"
}

resource "aws_security_group_rule" "msk_connect_egress_to_s3" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  prefix_list_ids   = [aws_vpc_endpoint.s3.prefix_list_id]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "HTTPS to Amazon S3 via gateway endpoint"
}

resource "aws_security_group_rule" "msk_connect_egress_dns_udp" {
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "udp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "DNS to VPC resolver"
}

resource "aws_security_group_rule" "msk_connect_egress_dns_tcp" {
  type              = "egress"
  from_port         = 53
  to_port           = 53
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.msk_connect_workers.id
  description       = "DNS over TCP to VPC resolver"
}

# -----------------------------------------------------------------------------
# VPC endpoints (private-subnet access to S3, CloudWatch Logs, Firehose)
# -----------------------------------------------------------------------------

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "msk-s3-gateway-endpoint"
  }
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "msk-cloudwatch-logs-endpoint"
  }
}

resource "aws_vpc_endpoint" "firehose" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.firehose"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "msk-firehose-endpoint"
  }
}

# -----------------------------------------------------------------------------
# KMS key for MSK encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "msk" {
  description             = "Customer managed key for MSK cluster encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowMSKService"
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# CloudWatch log groups
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "msk_broker_logs" {
  name              = "/aws/msk/${local.kafka_cluster_name}/broker-logs"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_group" "msk_connect_logs" {
  name              = "/aws/kafkaconnect/${local.kafka_cluster_name}/worker-logs"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_group" "firehose_delivery_logs" {
  name              = "/aws/kinesisfirehose/${local.kafka_cluster_name}-firehose"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_stream" "firehose_delivery_logs" {
  name           = "delivery-errors"
  log_group_name = aws_cloudwatch_log_group.firehose_delivery_logs.name
}

# -----------------------------------------------------------------------------
# S3 log bucket (MSK broker logs + Firehose delivery destination)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_logs" {
  bucket = local.msk_logs_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "msk_logs" {
  bucket = aws_s3_bucket.msk_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# S3 plugin bucket + Debezium plugin artifact
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "msk_connect_plugins" {
  bucket = local.plugin_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "msk_connect_plugins" {
  bucket = aws_s3_bucket.msk_connect_plugins.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# A local "debezium.zip" connector artifact must be shipped alongside this
# configuration; it is uploaded to the private plugin bucket below. The ETag
# is computed by the provider after upload, so no local file hashing is used.
resource "aws_s3_object" "debezium_plugin" {
  bucket       = aws_s3_bucket.msk_connect_plugins.id
  key          = "debezium.zip"
  source       = "debezium.zip"
  content_type = "application/zip"
}

# -----------------------------------------------------------------------------
# IAM: role used by MSK (kafka.amazonaws.com) to deliver broker logs
# -----------------------------------------------------------------------------

resource "aws_iam_role" "msk_log_delivery" {
  name = "msk-broker-log-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "kafka.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_log_delivery" {
  name = "msk-broker-log-delivery-policy"
  role = aws_iam_role.msk_log_delivery.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteBrokerLogsToCloudWatch"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_broker_logs.arn,
          "${aws_cloudwatch_log_group.msk_broker_logs.arn}:log-stream:*"
        ]
      },
      {
        Sid    = "WriteBrokerLogsToFirehose"
        Effect = "Allow"
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch",
          "firehose:DescribeDeliveryStream"
        ]
        Resource = [
          aws_kinesis_firehose_delivery_stream.msk_broker_logs.arn
        ]
      },
      {
        Sid      = "ListLogBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_logs.arn]
      },
      {
        Sid      = "PutBrokerLogsToS3"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.msk_logs.arn}/*"]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM: role used by Firehose (firehose.amazonaws.com) to deliver to S3
# -----------------------------------------------------------------------------

resource "aws_iam_role" "firehose_delivery" {
  name = "firehose-delivery-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "firehose.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "firehose_delivery" {
  name = "firehose-delivery-policy"
  role = aws_iam_role.firehose_delivery.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListDestinationBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_logs.arn]
      },
      {
        Sid      = "WriteToDestinationBucket"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.msk_logs.arn}/*"]
      },
      {
        Sid    = "WriteDeliveryLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.firehose_delivery_logs.arn,
          "${aws_cloudwatch_log_group.firehose_delivery_logs.arn}:log-stream:*"
        ]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Kinesis Firehose delivery stream
# -----------------------------------------------------------------------------

resource "aws_kinesis_firehose_delivery_stream" "msk_broker_logs" {
  name        = "msk-broker-logs"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn            = aws_iam_role.firehose_delivery.arn
    bucket_arn          = aws_s3_bucket.msk_logs.arn
    prefix              = "msk/broker-logs/firehose/dt=!{timestamp:yyyy-MM-dd-HH}/"
    error_output_prefix = "msk/broker-logs/errors/!{firehose:error-output-type}/"
    buffering_size      = 5
    buffering_interval  = 300
    compression_format  = "GZIP"

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.firehose_delivery_logs.name
      log_stream_name = aws_cloudwatch_log_stream.firehose_delivery_logs.name
    }
  }

  depends_on = [aws_iam_role_policy.firehose_delivery]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# MSK cluster
# -----------------------------------------------------------------------------

resource "aws_msk_cluster" "kafka" {
  cluster_name           = local.kafka_cluster_name
  kafka_version          = "3.6.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type   = "kafka.m5.large"
    client_subnets  = aws_subnet.private[*].id
    security_groups = [aws_security_group.msk_brokers.id]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk.arn

    encryption_in_transit {
      client_broker = "TLS"
      in_cluster    = true
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }

      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_broker_logs.name
      }

      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_broker_logs.name
      }

      s3 {
        enabled = true
        bucket  = aws_s3_bucket.msk_logs.id
        prefix  = "msk/broker-logs"
      }
    }
  }

  depends_on = [aws_iam_role_policy.msk_log_delivery]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# MSK Connect custom plugin (Debezium)
# -----------------------------------------------------------------------------

resource "aws_mskconnect_custom_plugin" "debezium" {
  name         = "debezium-custom-plugin"
  description  = "Debezium connector plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = aws_s3_bucket.msk_connect_plugins.arn
      file_key   = aws_s3_object.debezium_plugin.key
    }
  }
}

# -----------------------------------------------------------------------------
# MSK Connect worker configuration
# -----------------------------------------------------------------------------

resource "aws_mskconnect_worker_configuration" "debezium" {
  name        = "debezium-worker-configuration"
  description = "Worker configuration for the Debezium connector"

  properties_file_content = <<-EOT
  key.converter=org.apache.kafka.connect.json.JsonConverter
  value.converter=org.apache.kafka.connect.json.JsonConverter
  key.converter.schemas.enable=true
  value.converter.schemas.enable=true
  config.storage.replication.factor=3
  offset.storage.replication.factor=3
  status.storage.replication.factor=3
  EOT
}

# -----------------------------------------------------------------------------
# IAM: execution role for MSK Connect (kafkaconnect.amazonaws.com)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "msk_connect_exec" {
  name = "msk-connect-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "kafkaconnect.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "msk_connect_exec" {
  name = "msk-connect-execution-policy"
  role = aws_iam_role.msk_connect_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListPluginBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.msk_connect_plugins.arn]
      },
      {
        Sid      = "ReadPluginArtifact"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.msk_connect_plugins.arn}/debezium.zip"]
      },
      {
        Sid    = "WriteWorkerLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.msk_connect_logs.arn,
          "${aws_cloudwatch_log_group.msk_connect_logs.arn}:log-stream:*"
        ]
      },
      {
        Sid    = "KafkaClusterAccess"
        Effect = "Allow"
        Action = [
          "kafka-cluster:Connect",
          "kafka-cluster:CreateTopic",
          "kafka-cluster:AlterTopic",
          "kafka-cluster:DescribeTopic",
          "kafka-cluster:DescribeTopicDynamicConfiguration",
          "kafka-cluster:WriteData",
          "kafka-cluster:ReadData"
        ]
        Resource = [
          aws_msk_cluster.kafka.arn,
          "arn:${local.partition}:kafka:${local.region}:${local.account_id}:topic/${local.kafka_cluster_name}/*"
        ]
      },
      {
        Sid    = "KafkaConsumerGroups"
        Effect = "Allow"
        Action = [
          "kafka-cluster:AlterGroup",
          "kafka-cluster:DescribeGroup"
        ]
        Resource = [
          "arn:${local.partition}:kafka:${local.region}:${local.account_id}:group/${local.kafka_cluster_name}/*"
        ]
      },
      {
        Sid      = "KafkaConnectApi"
        Effect   = "Allow"
        Action   = ["kafkaconnect:DescribeCustomPlugin"]
        Resource = [aws_mskconnect_custom_plugin.debezium.arn]
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# MSK Connect connector
# -----------------------------------------------------------------------------

resource "aws_mskconnect_connector" "debezium" {
  name        = "debezium-connector"
  description = "Debezium source connector streaming into the MSK cluster"

  kafkaconnect_version = "3.3.1"

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.kafka.bootstrap_brokers_tls

      vpc {
        subnets         = aws_subnet.private[*].id
        security_groups = [aws_security_group.msk_connect_workers.id]
      }
    }
  }

  capacity {
    autoscaling {
      mcu_count        = 1
      min_worker_count = 1
      max_worker_count = 3

      scale_in_policy {
        cpu_utilization_percentage = 30
      }

      scale_out_policy {
        cpu_utilization_percentage = 70
      }
    }
  }

  # Placeholder Debezium source database settings - replace with real values.
  connector_configuration = {
    "connector.class"    = "io.debezium.connector.postgresql.PostgresConnector"
    "database.hostname"  = "source-db.internal"
    "database.port"      = "5432"
    "database.user"      = "debezium"
    "database.dbname"    = "sourcedb"
    "topic.prefix"       = "msk-source"
    "table.include.list" = "public.events"
    "snapshot.mode"      = "initial"
    "plugin.name"        = "pgoutput"
  }

  plugin {
    custom_plugin {
      arn      = aws_mskconnect_custom_plugin.debezium.arn
      revision = aws_mskconnect_custom_plugin.debezium.latest_revision
    }
  }

  worker_configuration {
    arn      = aws_mskconnect_worker_configuration.debezium.arn
    revision = aws_mskconnect_worker_configuration.debezium.latest_revision
  }

  service_execution_role_arn = aws_iam_role.msk_connect_exec.arn

  kafka_cluster_client_authentication {
    authentication_type = "NONE"
  }

  kafka_cluster_encryption_in_transit {
    encryption_type = "TLS"
  }

  log_delivery {
    worker_log_delivery {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_connect_logs.name
      }
    }
  }

  depends_on = [aws_iam_role_policy.msk_connect_exec]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "msk_cluster_arn" {
  description = "ARN of the MSK cluster"
  value       = aws_msk_cluster.kafka.arn
}

output "msk_cluster_bootstrap_brokers_tls" {
  description = "TLS bootstrap broker endpoints for the MSK cluster"
  value       = aws_msk_cluster.kafka.bootstrap_brokers_tls
}

output "msk_connect_connector_arn" {
  description = "ARN of the MSK Connect connector"
  value       = aws_mskconnect_connector.debezium.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (user-controlled, non-infrastructure values only)
###############################################################################

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "aurora-demo"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{2,29}$", var.project_name))
    error_message = "Project name must be 3-30 characters: lowercase letters, digits, or hyphens, starting with a letter."
  }
}

variable "environment_name" {
  description = "Environment name (e.g. dev, staging, prod) used for naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment_name)
    error_message = "Environment name must be one of: dev, staging, prod."
  }
}

variable "allowed_ingress_cidr" {
  description = "Private CIDR block allowed to connect to the Aurora cluster on port 3306."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.allowed_ingress_cidr)) && var.allowed_ingress_cidr != "0.0.0.0/0"
    error_message = "allowed_ingress_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

###############################################################################
# Locals and static provider metadata
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"

  vpc_cidr             = "10.0.0.0/16"
  all_subnet_cidrs     = cidrsubnets(local.vpc_cidr, 8, 8, 8, 8)
  private_subnet_cidrs = slice(local.all_subnet_cidrs, 0, 2)
  public_subnet_cidrs  = slice(local.all_subnet_cidrs, 2, 4)

  master_username = "admin"
  database_name   = "appdb"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment_name
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Networking foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

# Private subnets: host the Aurora cluster; never publicly routable.
resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "database"
  })
}

# Public subnets: keep the internet gateway functional for the VPC.
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

# Private route table has no internet route: database subnets stay isolated.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Database subnet group (requires subnets in at least two AZs)
###############################################################################

resource "aws_db_subnet_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-subnet-group"
  description = "Private subnets for the ${local.name_prefix} Aurora MySQL cluster"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-subnet-group"
  })
}

###############################################################################
# Security group: ingress restricted to MySQL on 3306 from a private CIDR only
###############################################################################

resource "aws_security_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-mysql-sg"
  description = "Restrict MySQL access to the ${local.name_prefix} Aurora MySQL cluster"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the allowed private CIDR only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ingress_cidr]
  }

  egress {
    description = "Outbound restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-sg"
  })
}

###############################################################################
# KMS encryption key for the cluster
###############################################################################

resource "aws_kms_key" "aurora_mysql" {
  description             = "Customer managed key for the ${local.name_prefix} Aurora MySQL cluster"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cluster parameter group (Aurora MySQL 8.0 family, utf8mb4 defaults)
###############################################################################

resource "aws_rds_cluster_parameter_group" "aurora_mysql" {
  name        = "${local.name_prefix}-aurora-mysql-params"
  family      = "aurora-mysql8.0"
  description = "Cluster parameter group for the ${local.name_prefix} Aurora MySQL 8.0 cluster"

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_connection"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_database"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_filesystem"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_results"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_connection"
    value = "utf8mb4_general_ci"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_general_ci"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-params"
  })
}

###############################################################################
# Aurora MySQL cluster (credentials managed by RDS via Secrets Manager)
###############################################################################

resource "aws_rds_cluster" "aurora_mysql" {
  cluster_identifier  = "${local.name_prefix}-aurora-mysql"
  engine              = "aurora-mysql"
  engine_version      = "8.0.mysql_aurora.3.08.0"
  database_name       = local.database_name
  master_username     = local.master_username
  manage_master_user_password = true
  port                = 3306

  db_subnet_group_name            = aws_db_subnet_group.aurora_mysql.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora_mysql.name
  vpc_security_group_ids          = [aws_security_group.aurora_mysql.id]

  storage_encrypted = true
  kms_key_id        = aws_kms_key.aurora_mysql.arn

  backup_retention_period      = 14
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot        = true
  deletion_protection          = true
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.name_prefix}-aurora-mysql-final"

  enabled_cloudwatch_logs_exports = ["error", "general", "slowquery"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cluster instances: exactly two, one per private subnet AZ
###############################################################################

resource "aws_rds_cluster_instance" "aurora_mysql_1" {
  identifier           = "${local.name_prefix}-aurora-mysql-1"
  cluster_identifier   = aws_rds_cluster.aurora_mysql.id
  engine               = "aurora-mysql"
  engine_version       = aws_rds_cluster.aurora_mysql.engine_version
  instance_class       = "db.r6g.large"
  db_subnet_group_name = aws_db_subnet_group.aurora_mysql.name
  availability_zone    = data.aws_availability_zones.available.names[0]
  publicly_accessible  = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "aurora_mysql_2" {
  identifier           = "${local.name_prefix}-aurora-mysql-2"
  cluster_identifier   = aws_rds_cluster.aurora_mysql.id
  engine               = "aurora-mysql"
  engine_version       = aws_rds_cluster.aurora_mysql.engine_version
  instance_class       = "db.r6g.large"
  db_subnet_group_name = aws_db_subnet_group.aurora_mysql.name
  availability_zone    = data.aws_availability_zones.available.names[1]
  publicly_accessible  = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-aurora-mysql-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "aurora_writer_endpoint" {
  description = "Writer endpoint for the Aurora MySQL cluster."
  value       = aws_rds_cluster.aurora_mysql.endpoint
}

output "aurora_reader_endpoint" {
  description = "Reader endpoint for the Aurora MySQL cluster."
  value       = aws_rds_cluster.aurora_mysql.reader_endpoint
}

output "aurora_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Aurora master credentials."
  value       = aws_rds_cluster.aurora_mysql.master_user_secret[0].secret_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Data sources: static provider metadata / well-known lookups only
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables: naming/tagging defaults only (never infrastructure attributes)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "aurora"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  name_prefix        = "${var.project_name}-${var.environment}"
  cluster_identifier = "${local.name_prefix}-pg-${random_id.suffix.hex}"
  master_username    = "dbadmin"
  database_name      = "appdb"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Public subnets carry the Internet Gateway route for future edge workloads.
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-${count.index}" })
}

# Private subnets host the Aurora cluster: isolated, no internet route.
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 2)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-${count.index}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# -----------------------------------------------------------------------------
# KMS encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "aurora" {
  description             = "KMS key for ${local.name_prefix} Aurora PostgreSQL storage and secret encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/${local.cluster_identifier}"
  target_key_id = aws_kms_key.aurora.key_id
}

# -----------------------------------------------------------------------------
# Security group: TCP 5432 from the VPC CIDR only
# -----------------------------------------------------------------------------

resource "aws_security_group" "aurora" {
  name        = "${local.name_prefix}-pg-sg"
  description = "Aurora PostgreSQL access for ${local.name_prefix} (TCP 5432 from VPC only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Intra-VPC egress required for cluster replication and management traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-sg" })
}

# -----------------------------------------------------------------------------
# DB subnet group
# -----------------------------------------------------------------------------

resource "aws_db_subnet_group" "aurora" {
  name        = "${local.name_prefix}-pg-subnets"
  description = "Private subnets for ${local.name_prefix} Aurora PostgreSQL across multiple AZs"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-subnets" })
}

# -----------------------------------------------------------------------------
# Master credentials: generated, never plaintext, stored in Secrets Manager
# -----------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-pg-master-credentials"
  description = "Master credentials for the ${local.name_prefix} Aurora PostgreSQL cluster"
  kms_key_id  = aws_kms_key.aurora.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username             = local.master_username
    password             = random_password.db_master.result
    engine               = "aurora-postgresql"
    host                 = aws_rds_cluster.aurora.endpoint
    port                 = aws_rds_cluster.aurora.port
    dbname               = local.database_name
    dbInstanceIdentifier = aws_rds_cluster.aurora.cluster_identifier
  })
}

# -----------------------------------------------------------------------------
# Parameter groups (Aurora PostgreSQL 15)
# -----------------------------------------------------------------------------

resource "aws_rds_cluster_parameter_group" "aurora_cluster" {
  name        = "${local.name_prefix}-pg15-cluster-params"
  family      = "aurora-postgresql15"
  description = "Cluster-level parameters for the ${local.name_prefix} Aurora PostgreSQL 15 cluster"

  parameter {
    name         = "rds.logical_replication"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = local.common_tags
}

resource "aws_db_parameter_group" "aurora_db" {
  name        = "${local.name_prefix}-pg15-db-params"
  family      = "aurora-postgresql15"
  description = "Instance-level logging parameters for the ${local.name_prefix} Aurora PostgreSQL 15 cluster"

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  parameter {
    name  = "log_min_error_statement"
    value = "error"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }

  parameter {
    name  = "log_lock_waits"
    value = "1"
  }

  parameter {
    name  = "log_statement"
    value = "ddl"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Enhanced monitoring IAM (least privilege)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "${local.name_prefix}-rds-enhanced-monitoring-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "monitoring.rds.amazonaws.com",
            "rds.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "rds_enhanced_monitoring" {
  name        = "${local.name_prefix}-rds-enhanced-monitoring-policy"
  description = "Least-privilege policy for RDS enhanced monitoring: CloudWatch metrics, RDS logs, and EC2 instance discovery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PutRdsMetrics"
        Effect   = "Allow"
        Action   = ["cloudwatch:PutMetricData"]
        Resource = ["*"]
        Condition = {
          StringEquals = {
            "cloudwatch:namespace" = "AWS/RDS"
          }
        }
      },
      {
        Sid    = "RdsMonitoringLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:PutRetentionPolicy",
          "logs:GetLogEvents",
          "logs:FilterLogEvents"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:RDS*",
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:RDS*:log-stream:*"
        ]
      },
      {
        Sid    = "DiscoverInstances"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeTags"
        ]
        Resource = ["*"]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = aws_iam_policy.rds_enhanced_monitoring.arn
}

# -----------------------------------------------------------------------------
# CloudWatch log group for PostgreSQL logs
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "aurora_postgresql" {
  name              = "/aws/rds/cluster/${local.cluster_identifier}/postgresql"
  retention_in_days = 30

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-postgresql-logs" })
}

# -----------------------------------------------------------------------------
# Aurora PostgreSQL cluster
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "aurora" {
  cluster_identifier              = local.cluster_identifier
  engine                          = "aurora-postgresql"
  engine_version                  = "15.5"
  engine_mode                     = "provisioned"
  database_name                   = local.database_name
  master_username                 = local.master_username
  master_password                 = random_password.db_master.result
  port                            = 5432

  db_subnet_group_name            = aws_db_subnet_group.aurora.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.aurora_cluster.name
  vpc_security_group_ids          = [aws_security_group.aurora.id]

  storage_encrypted = true
  kms_key_id        = aws_kms_key.aurora.arn

  deletion_protection          = true
  backup_retention_period      = 14
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot        = true
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.cluster_identifier}-final"

  enabled_cloudwatch_logs_exports = ["postgresql"]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-aurora" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier              = "${local.cluster_identifier}-writer"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = "db.r6g.large"
  engine                  = "aurora-postgresql"
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_parameter_group_name = aws_db_parameter_group.aurora_db.name

  availability_zone   = data.aws_availability_zones.available.names[0]
  publicly_accessible = false

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn

  monitoring_interval        = 60
  monitoring_role_arn        = aws_iam_role.rds_enhanced_monitoring.arn
  auto_minor_version_upgrade = true

  tags = merge(local.common_tags, { Name = "${local.cluster_identifier}-writer" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier              = "${local.cluster_identifier}-reader"
  cluster_identifier      = aws_rds_cluster.aurora.id
  instance_class          = "db.r6g.large"
  engine                  = "aurora-postgresql"
  engine_version          = aws_rds_cluster.aurora.engine_version
  db_parameter_group_name = aws_db_parameter_group.aurora_db.name

  availability_zone   = data.aws_availability_zones.available.names[1]
  publicly_accessible = false

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn

  monitoring_interval        = 60
  monitoring_role_arn        = aws_iam_role.rds_enhanced_monitoring.arn
  auto_minor_version_upgrade = true

  promotion_tier = 15

  depends_on = [aws_rds_cluster_instance.writer]

  tags = merge(local.common_tags, { Name = "${local.cluster_identifier}-reader" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora PostgreSQL cluster."
  value       = aws_rds_cluster.aurora.endpoint
}

output "cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora PostgreSQL cluster."
  value       = aws_rds_cluster.aurora.reader_endpoint
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Aurora PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# --- Network foundation (greenfield: all resources created in this file) ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-b"
  })
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.13.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-private-c"
  })
}

resource "aws_db_subnet_group" "mysql" {
  name        = "mysql-cluster-db-subnet-group"
  description = "Private subnets across three AZs for the MySQL Multi-AZ DB cluster"

  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id,
  ]

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-db-subnet-group"
  })
}

# --- Security group: TCP 3306 from the VPC only, restricted egress ---

resource "aws_security_group" "mysql_cluster" {
  name        = "mysql-cluster-sg"
  description = "MySQL Multi-AZ DB cluster: TCP 3306 from VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL client and replication traffic from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL replication traffic to cluster peers within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-sg"
  })
}

# --- Encryption at rest ---

resource "aws_kms_key" "mysql" {
  description             = "Customer-managed key for the MySQL Multi-AZ DB cluster"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-kms-key"
  })
}

resource "aws_kms_alias" "mysql" {
  name          = "alias/rds-mysql-cluster"
  target_key_id = aws_kms_key.mysql.key_id
}

# --- Master credentials (generated, stored in Secrets Manager, KMS-encrypted) ---

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "master" {
  name        = "rds/mysql-cluster/master"
  description = "Master credentials for the MySQL Multi-AZ DB cluster"
  kms_key_id  = aws_kms_key.mysql.arn

  tags = merge(local.common_tags, {
    Name = "rds-mysql-cluster-master"
  })
}

resource "aws_secretsmanager_secret_version" "master" {
  secret_id = aws_secretsmanager_secret.master.id
  secret_string = jsonencode({
    username = "dbadmin"
    password = random_password.master.result
  })
}

# --- Cluster parameter group ---

resource "aws_rds_cluster_parameter_group" "mysql" {
  name        = "mysql-cluster-params"
  family      = "mysql8.0"
  description = "Secure cluster parameters for the MySQL Multi-AZ DB cluster"

  parameter {
    name  = "require_secure_transport"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "mysql-cluster-params"
  })
}

# --- MySQL Multi-AZ DB cluster: writer + two readers, 100 GiB io1 per AZ ---
# Note: automatic minor engine version upgrades are applied by RDS at the
# service level for Multi-AZ DB clusters; no instance-level flag is needed.

resource "aws_rds_cluster" "mysql" {
  cluster_identifier = "mysql-multiaz-cluster"
  engine             = "mysql"
  engine_version     = "8.0.35"

  master_username = "dbadmin"
  master_password = random_password.master.result

  port                      = 3306
  db_cluster_instance_class = "db.r6gd.xlarge"
  allocated_storage         = 100
  storage_type              = "io1"
  iops                      = 1000

  storage_encrypted = true
  kms_key_id        = aws_kms_key.mysql.arn

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql_cluster.id]

  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.mysql.name

  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-multiaz-cluster-final-${random_id.final_snapshot.hex}"

  iam_database_authentication_enabled = true
  performance_insights_enabled        = true

  tags = merge(local.common_tags, {
    Name = "mysql-multiaz-cluster"
  })

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [engine_version]
  }
}

# --- Outputs (non-sensitive only) ---

output "cluster_writer_endpoint" {
  description = "Writer endpoint of the MySQL Multi-AZ DB cluster"
  value       = aws_rds_cluster.mysql.endpoint
}

output "cluster_reader_endpoint" {
  description = "Reader endpoint of the MySQL Multi-AZ DB cluster"
  value       = aws_rds_cluster.mysql.reader_endpoint
}

output "cluster_port" {
  description = "Port the MySQL Multi-AZ DB cluster listens on"
  value       = aws_rds_cluster.mysql.port
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the cluster master credentials"
  value       = aws_secretsmanager_secret.master.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (all with defaults so `terraform apply` runs unattended)
# -----------------------------------------------------------------------------

variable "project" {
  description = "Project name used for resource naming and consistent tagging."
  type        = string
  default     = "mysql"
}

variable "environment" {
  description = "Environment name used for resource naming and consistent tagging."
  type        = string
  default     = "prod"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC hosting the MySQL cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "db_engine_version" {
  description = "MySQL engine version for the Multi-AZ DB cluster."
  type        = string
  default     = "8.0.35"
}

variable "db_instance_class" {
  description = "DB instance class for the cluster writer and readers."
  type        = string
  default     = "db.r6i.large"
}

variable "db_master_username" {
  description = "Master username for the MySQL cluster. The password is generated at apply time and stored in Secrets Manager."
  type        = string
  default     = "dbadmin"
}

variable "db_backup_retention_days" {
  description = "Automated backup retention period (days) for the MySQL cluster."
  type        = number
  default     = 14

  validation {
    condition     = var.db_backup_retention_days >= 7 && var.db_backup_retention_days <= 35
    error_message = "Backup retention must be between 7 and 35 days."
  }
}

locals {
  name_prefix = lower("${var.project}-${var.environment}")

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

# One private subnet in each of three distinct AZs (resolved dynamically via
# the AZ data source so the cluster spans three AZs, e.g. us-east-1a, us-east-1b
# and us-east-1c).
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[2]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 3)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-c"
  })
}

# DB subnet group spanning all three AZs so the cluster storage replicates
# across them.
resource "aws_db_subnet_group" "mysql_cluster" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group spanning three AZs for the MySQL Multi-AZ DB cluster."
  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
    aws_subnet.private_c.id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# -----------------------------------------------------------------------------
# Security
# -----------------------------------------------------------------------------

# Database security group: MySQL (3306) from the VPC CIDR only, no public access.
resource "aws_security_group" "mysql_cluster" {
  name        = "${local.name_prefix}-db-sg"
  description = "MySQL cluster access restricted to the dedicated VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL (3306) from within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "MySQL (3306) responses within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# Customer-managed KMS key with automatic rotation for encryption at rest.
resource "aws_kms_key" "mysql_cluster" {
  description             = "CMK encrypting the MySQL Multi-AZ DB cluster storage and the master credentials secret."
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager, never hardcoded)
# -----------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>?"
}

resource "aws_secretsmanager_secret" "db_master_credentials" {
  name                    = "${local.name_prefix}-db-master-credentials"
  description             = "Master credentials for the MySQL Multi-AZ DB cluster."
  kms_key_id              = aws_kms_key.mysql_cluster.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master_credentials" {
  secret_id = aws_secretsmanager_secret.db_master_credentials.id
  secret_string = jsonencode({
    username = var.db_master_username
    password = random_password.db_master_password.result
  })
}

# -----------------------------------------------------------------------------
# RDS MySQL Multi-AZ DB cluster
# -----------------------------------------------------------------------------

# A single 100 GiB io1 cluster volume is defined once at the cluster level and
# synchronously replicated across the three AZs; it is not 100 GB per instance
# or per AZ.
resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier     = "${local.name_prefix}-mysql-cluster"
  engine                 = "mysql"
  engine_version         = var.db_engine_version
  database_name          = "appdb"
  master_username        = var.db_master_username
  master_password        = random_password.db_master_password.result
  db_subnet_group_name   = aws_db_subnet_group.mysql_cluster.name
  vpc_security_group_ids = [aws_security_group.mysql_cluster.id]
  port                   = 3306

  storage_type      = "io1"
  allocated_storage = 100
  iops              = 3000

  storage_encrypted = true
  kms_key_id        = aws_kms_key.mysql_cluster.arn

  backup_retention_period = var.db_backup_retention_days
  preferred_backup_window = "03:00-04:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-cluster-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# One DB instance per AZ; the first to join becomes the writer and the other two
# become readers, so the writer and readers span all three AZs.
resource "aws_rds_cluster_instance" "mysql_instance_1" {
  identifier                            = "${local.name_prefix}-instance-1"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[0]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "mysql_instance_2" {
  identifier                            = "${local.name_prefix}-instance-2"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[1]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "mysql_instance_3" {
  identifier                            = "${local.name_prefix}-instance-3"
  cluster_identifier                    = aws_rds_cluster.mysql_cluster.id
  instance_class                        = var.db_instance_class
  engine                                = "mysql"
  engine_version                        = var.db_engine_version
  availability_zone                     = data.aws_availability_zones.available.names[2]
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-3"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "writer_endpoint" {
  description = "Writer endpoint of the MySQL Multi-AZ DB cluster."
  value       = aws_rds_cluster.mysql_cluster.endpoint
}

output "reader_endpoint" {
  description = "Reader endpoint of the MySQL Multi-AZ DB cluster."
  value       = aws_rds_cluster.mysql_cluster.reader_endpoint
}

output "database_port" {
  description = "Port the MySQL cluster listens on."
  value       = aws_rds_cluster.mysql_cluster.port
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials."
  value       = aws_secretsmanager_secret.db_master_credentials.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_identifier      = "mysql-db"
  db_master_username = "dbadmin"
  db_name            = "appdb"
  db_port            = 3306
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "mysql-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "mysql-private-subnet-${count.index + 1}"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "mysql-private-route-table"
  }
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "mysql" {
  name       = "mysql-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "mysql-db-subnet-group"
  }
}

# ---------------------------------------------------------------------------
# Database security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "mysql" {
  name        = "mysql-db-sg"
  description = "Allow MySQL traffic from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL traffic within the VPC (e.g. replication)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "mysql-db-sg"
  }
}

# ---------------------------------------------------------------------------
# Master credentials
# ---------------------------------------------------------------------------

resource "random_password" "mysql_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "mysql" {
  name                    = "mysql-master-credentials"
  description             = "Master credentials for the MySQL RDS instance"
  recovery_window_in_days = 7

  tags = {
    Name = "mysql-master-credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql" {
  secret_id = aws_secretsmanager_secret.mysql.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.mysql_master.result
    engine   = "mysql"
    port     = local.db_port
    dbname   = local.db_name
  })
}

# ---------------------------------------------------------------------------
# Parameter group
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "mysql" {
  name   = "mysql-params"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_unicode_ci"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_connection"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_results"
    value = "utf8mb4"
  }
}

# ---------------------------------------------------------------------------
# MySQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0.35"
  instance_class = "db.t3.medium"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.db_name
  port     = local.db_port
  username = jsondecode(aws_secretsmanager_secret_version.mysql.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.mysql.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  multi_az                   = true
  publicly_accessible        = false
  auto_minor_version_upgrade = true

  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-final-snapshot"

  tags = {
    Name = local.db_identifier
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "db_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL instance"
  value       = aws_db_instance.mysql.endpoint
}

output "db_address" {
  description = "Hostname of the MySQL instance"
  value       = aws_db_instance.mysql.address
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials"
  value       = aws_secretsmanager_secret.mysql.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookups only
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

# ---------------------------------------------------------------------------
# Variable (tagging only)
# ---------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used exclusively for resource tags. Never used as a substitute for a resource attribute."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  db_master_username        = "dbadmin"
  final_snapshot_identifier = "greenfield-postgres-final-snapshot"

  common_tags = {
    environment = var.environment
    managed_by  = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking foundation
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { name = "main" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.11.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { name = "postgres-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.12.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { name = "postgres-private-b" })
}

resource "aws_db_subnet_group" "main" {
  name        = "postgres-private-subnet-group"
  description = "Private subnets spanning two AZs for the PostgreSQL instance"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = local.common_tags
}

resource "aws_security_group" "postgres" {
  name        = "postgres-access"
  description = "Allow inbound PostgreSQL (5432) from the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # Intentionally no egress rules: the database does not require outbound
  # access, and the security group is stateful for return traffic.

  tags = merge(local.common_tags, { name = "postgres-access" })
}

# ---------------------------------------------------------------------------
# Encryption key and master credentials (no plaintext secrets)
# ---------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "Encrypts PostgreSQL storage, Performance Insights, and the master credentials secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = local.common_tags
}

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "rds/postgres/master-credentials"
  description = "Master credentials for the greenfield PostgreSQL instance"
  kms_key_id  = aws_kms_key.rds.arn

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master.result
  })
}

# ---------------------------------------------------------------------------
# Enhanced monitoring IAM role
# ---------------------------------------------------------------------------

resource "aws_iam_role" "rds_enhanced_monitoring" {
  name = "rds-enhanced-monitoring"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "monitoring.rds.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_enhanced_monitoring" {
  role       = aws_iam_role.rds_enhanced_monitoring.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# ---------------------------------------------------------------------------
# Parameter group (security and audit settings)
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "postgres16" {
  name        = "postgres16-secure"
  family      = "postgres16"
  description = "Security and audit parameters for PostgreSQL 16"

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# PostgreSQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "postgres" {
  identifier     = "greenfield-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"

  db_name  = "appdb"
  port     = 5432
  username = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_credentials.secret_string)["password"]

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  parameter_group_name   = aws_db_parameter_group.postgres16.name
  publicly_accessible    = false

  multi_az                   = true
  auto_minor_version_upgrade = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_enhanced_monitoring.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { name = "greenfield-postgres" })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "database_endpoint" {
  description = "Hostname (address) of the PostgreSQL instance."
  value       = aws_db_instance.postgres.address
  sensitive   = true
}

output "database_port" {
  description = "Port the PostgreSQL instance listens on."
  value       = aws_db_instance.postgres.port
}

output "database_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_credentials.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Logical environment name used for resource tagging (non-infrastructure identifier)."
  type        = string
  default     = "dev"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of: dev, staging, prod."
  }
}

locals {
  table_name = "app-data-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "dynamodb" {
  description             = "Customer managed CMK used for DynamoDB server-side encryption"
  key_usage               = "ENCRYPT_DECRYPT"
  is_enabled              = true
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "dynamodb-cmk-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dynamodb" {
  name          = "alias/dynamodb-${var.environment}"
  target_key_id = aws_kms_key.dynamodb.key_id
}

resource "aws_dynamodb_table" "main" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  deletion_protection_enabled = true

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.table_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_id" {
  description = "ID of the DynamoDB table."
  value       = aws_dynamodb_table.main.id
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for table encryption."
  value       = aws_kms_key.dynamodb.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Default provider: base table and primary KMS key are created here.
provider "aws" {
  region = "us-east-1"
}

# Additional provider configurations for the same AWS provider, required so
# the multi-region KMS replica keys can be created in the replica regions.
provider "aws" {
  alias  = "us_east_2"
  region = "us-east-2"
}

provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

variable "environment" {
  description = "Environment name applied as a consistent tag to all managed resources."
  type        = string
  default     = "production"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# Multi-region customer-managed KMS key (primary) used for encryption at rest.
resource "aws_kms_key" "dynamodb_global" {
  description             = "Multi-region customer-managed key for the DynamoDB global table (primary in us-east-1)"
  multi_region            = true
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Regional replica of the multi-region key for the us-east-2 table replica.
resource "aws_kms_replica_key" "dynamodb_us_east_2" {
  provider                = aws.us_east_2
  description             = "Multi-region customer-managed key replica for the DynamoDB global table (us-east-2)"
  primary_key_arn         = aws_kms_key.dynamodb_global.arn
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Regional replica of the multi-region key for the us-west-2 table replica.
resource "aws_kms_replica_key" "dynamodb_us_west_2" {
  provider                = aws.us_west_2
  description             = "Multi-region customer-managed key replica for the DynamoDB global table (us-west-2)"
  primary_key_arn         = aws_kms_key.dynamodb_global.arn
  deletion_window_in_days = 30
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# DynamoDB global table: base table in us-east-1 with replicas in us-east-2
# and us-west-2, streams enabled for replication, CMK encryption, PITR,
# and deletion protection.
resource "aws_dynamodb_table" "main" {
  name         = "global_table_main"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  # Streams are required for global table replication.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  # Encryption at rest with the customer-managed multi-region key.
  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb_global.arn
  }

  # Point-in-time recovery protects all regional copies from accidental
  # writes and deletes.
  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  replica {
    region_name = "us-east-2"
    kms_key_arn = aws_kms_replica_key.dynamodb_us_east_2.arn
  }

  replica {
    region_name = "us-west-2"
    kms_key_arn = aws_kms_replica_key.dynamodb_us_west_2.arn
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment tag applied to the DynamoDB table"
  type        = string
  default     = "dev"
}

resource "aws_dynamodb_table" "main" {
  name                        = "app-data"
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "id"
  deletion_protection_enabled = true

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name        = "app-data"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the DynamoDB table"
  value       = aws_dynamodb_table.main.arn
}

###############################################################################
# Terraform configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Primary region. Replica regions are declared on the table resource itself.
provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "tags" {
  description = "Non-secret tags applied to the DynamoDB table (name, environment, managed-by)."
  type        = map(string)

  default = {
    "name"       = "global-data-table"
    "managed-by" = "terraform"
    "environment" = "production"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Single source of truth for the table name, taken from the tags map.
  table_name = var.tags["name"]
}

###############################################################################
# DynamoDB Global Table
# Primary: us-east-1 | Replicas: us-west-1, us-west-2
###############################################################################

resource "aws_dynamodb_table" "global_table" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST" # Required for global table replicas
  hash_key     = "PK"

  attribute {
    name = "PK"
    type = "S"
  }

  # DynamoDB Streams are a prerequisite for global table replication.
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  # Replica in us-west-1.
  replica {
    region_name = "us-west-1"
  }

  # Replica in us-west-2.
  replica {
    region_name = "us-west-2"
  }

  # Server-side encryption using the AWS-managed DynamoDB KMS key.
  # A customer-managed key is intentionally not pinned, because global table
  # replicas require a per-region key to function correctly.
  server_side_encryption {
    enabled = true
  }

  # Point-in-time recovery for the table.
  point_in_time_recovery {
    enabled = true
  }

  # Deletion protection for the table.
  deletion_protection_enabled = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "table_name" {
  description = "Name of the DynamoDB global table."
  value       = aws_dynamodb_table.global_table.name
}

output "table_arn" {
  description = "ARN of the DynamoDB global table (primary region: us-east-1)."
  value       = aws_dynamodb_table.global_table.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a user-defined tag to resources."
  type        = string
  default     = "production"
}

locals {
  table_name = "application-data"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_dynamodb_table" "main" {
  name           = local.table_name
  billing_mode   = "PROVISIONED"
  read_capacity  = 10
  write_capacity = 10
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  environment = "production"
  project     = "dax_cache"

  common_tags = {
    Environment = local.environment
    Project     = local.project
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "dax_vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "dax_private_subnet_${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "dax_private_route_table"
  })
}

# Note: aws_route_table_association is a pure linkage object with no tags
# support in the provider schema or the AWS API; network-layer tagging
# coverage is provided by aws_route_table.private and aws_subnet.private.
resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = merge(local.common_tags, {
    Name = "dax_dynamodb_gateway_endpoint"
  })
}

resource "aws_security_group" "dax" {
  name        = "dax_security_group"
  description = "DAX cluster security group - ingress limited to DAX endpoint port 8111, egress limited to HTTPS 443"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "DAX endpoint port (TCP 8111) from within the VPC"
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS (TCP 443) to DynamoDB via the gateway VPC endpoint"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [aws_vpc_endpoint.dynamodb.prefix_list_id]
  }

  tags = merge(local.common_tags, {
    Name = "dax_security_group"
  })
}

# Note: aws_dax_subnet_group does not support tags at the AWS API level;
# metadata is recorded via the schema-supported description argument instead.
resource "aws_dax_subnet_group" "main" {
  name        = "dax-subnet-group"
  description = "Managed by Terraform (${local.environment}) - private subnets hosting DAX cluster nodes"
  subnet_ids  = aws_subnet.private[*].id
}

resource "aws_dynamodb_table" "cache_table" {
  name         = "dax_cache_table"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"

  attribute {
    name = "pk"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "dax_cache_table"
  })
}

resource "aws_iam_role" "dax" {
  name        = "dax_cluster_role"
  description = "IAM role assumed by the DAX cluster to access DynamoDB on behalf of clients"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

# Note: IAM inline policies are not taggable; aws_iam_role_policy correctly omits tags.
resource "aws_iam_role_policy" "dax_dynamodb_access" {
  name = "dax_dynamodb_data_plane"
  role = aws_iam_role.dax.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DaxTableDataPlaneAccess"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:Query",
          "dynamodb:Scan",
          "dynamodb:BatchGetItem",
          "dynamodb:BatchWriteItem",
          "dynamodb:ConditionCheckItem",
          "dynamodb:DescribeTable"
        ]
        Resource = [
          aws_dynamodb_table.cache_table.arn,
          "${aws_dynamodb_table.cache_table.arn}/index/*"
        ]
      }
    ]
  })
}

# Note: aws_dax_parameter_group does not support tags at the AWS API level;
# metadata is recorded via the schema-supported description argument instead.
resource "aws_dax_parameter_group" "main" {
  name        = "dax-parameter-group"
  description = "Managed by Terraform (${local.environment}) - DAX cache TTL parameters"

  parameters {
    name  = "query-ttl-millis"
    value = "60000"
  }

  parameters {
    name  = "record-ttl-millis"
    value = "300000"
  }
}

resource "aws_dax_cluster" "main" {
  cluster_name                     = "dax-cache-cluster"
  iam_role_arn                     = aws_iam_role.dax.arn
  node_type                        = "dax.r6g.large"
  replication_factor               = 3
  subnet_group_name                = aws_dax_subnet_group.main.name
  security_group_ids               = [aws_security_group.dax.id]
  parameter_group_name             = aws_dax_parameter_group.main.name
  cluster_endpoint_encryption_type = "TLS"

  server_side_encryption {
    enabled = true
  }

  depends_on = [aws_iam_role_policy.dax_dynamodb_access]

  tags = merge(local.common_tags, {
    Name = "dax-cache-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "dax_cluster_id" {
  description = "The ID of the DAX cluster."
  value       = aws_dax_cluster.main.id
}

output "dax_configuration_endpoint" {
  description = "The configuration endpoint (DNS name and port) of the DAX cluster."
  value       = aws_dax_cluster.main.configuration_endpoint
}

output "dax_iam_role_arn" {
  description = "The ARN of the IAM role assumed by the DAX cluster."
  value       = aws_iam_role.dax.arn
}

