terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment label used solely for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  table_name         = "data-with-ttl"
  ttl_attribute_name = "expires_at"
}

resource "aws_dynamodb_table" "data_with_ttl" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  # Only the key-schema attribute is declared here. The TTL attribute
  # (expires_at) is intentionally NOT part of the schema per DynamoDB
  # TTL semantics.
  attribute {
    name = "id"
    type = "S"
  }

  ttl {
    enabled        = true
    attribute_name = local.ttl_attribute_name
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = {
    Name        = local.table_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Demonstration item used to validate TTL expiration behavior.
# "expires_at" is stored as a DynamoDB Number (N) whose stringified value
# is the Unix epoch seconds timestamp 4102444800 (2100-01-01T00:00:00Z),
# a future time at which DynamoDB will automatically purge the item.
resource "aws_dynamodb_table_item" "sample" {
  table_name = aws_dynamodb_table.data_with_ttl.name
  hash_key   = aws_dynamodb_table.data_with_ttl.hash_key

  item = jsonencode({
    id = {
      S = "sample-record-001"
    }
    expires_at = {
      N = "4102444800"
    }
    payload = {
      S = "Demonstration record used to validate custom TTL expiration behavior."
    }
  })
}

output "table_name" {
  description = "Name of the DynamoDB table with custom TTL expiration enabled."
  value       = aws_dynamodb_table.data_with_ttl.name
}

output "ttl_attribute_name" {
  description = "Name of the DynamoDB attribute driving TTL expiration (Number type holding Unix epoch seconds)."
  value       = aws_dynamodb_table.data_with_ttl.ttl[0].attribute_name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "environment" {
  description = "Deployment environment name (e.g. dev, staging, prod) used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]*[a-z0-9])?$", var.environment))
    error_message = "Environment must be lowercase alphanumeric, optionally separated by hyphens."
  }
}

variable "additional_tags" {
  description = "Additional tags merged into the default tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  region     = "us-east-1"
  table_name = "dynamodb-table-${var.environment}"

  default_tags = {
    Name        = local.table_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  tags = merge(local.default_tags, var.additional_tags)
}

resource "aws_kms_key" "dynamodb" {
  description             = "Customer-managed KMS key used to encrypt the ${local.table_name} DynamoDB table at rest."
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissionsForAccount"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowDynamoDBViaService"
        Effect    = "Allow"
        Principal = {
          Service = "dynamodb.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "dynamodb.${local.region}.amazonaws.com"
          }
        }
      }
    ]
  })

  tags = merge(local.tags, { Name = "kms-dynamodb-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "dynamodb" {
  name          = "alias/dynamodb-table-encryption"
  target_key_id = aws_kms_key.dynamodb.key_id
}

resource "aws_dynamodb_table" "main" {
  name         = local.table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "id"

  attribute {
    name = "id"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.dynamodb.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

output "dynamodb_table_name" {
  description = "Name of the encrypted DynamoDB table."
  value       = aws_dynamodb_table.main.name
}

output "dynamodb_table_arn" {
  description = "ARN of the encrypted DynamoDB table."
  value       = aws_dynamodb_table.main.arn
}

output "dynamodb_kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the DynamoDB table."
  value       = aws_kms_key.dynamodb.arn
}

