locals {
  name_prefix = "neptune-demo"

  common_tags = {
    Project     = local.name_prefix
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# ----------------------------------------------------------------------------
# Networking: dedicated VPC with DNS enabled, two private subnets in two AZs
# ----------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "neptune_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "neptune_subnet_a" {
  vpc_id                  = aws_vpc.neptune_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.neptune_vpc.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "neptune_subnet_b" {
  vpc_id                  = aws_vpc.neptune_vpc.id
  cidr_block              = cidrsubnet(aws_vpc.neptune_vpc.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

# ----------------------------------------------------------------------------
# Security group: ingress restricted to TCP 8182 from the two private subnets
# ----------------------------------------------------------------------------
resource "aws_security_group" "neptune_sg" {
  name        = "${local.name_prefix}-sg"
  description = "Allow Neptune engine traffic (TCP 8182) only from the two private subnets"
  vpc_id      = aws_vpc.neptune_vpc.id

  ingress {
    description = "Neptune engine port from private subnet A"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.neptune_subnet_a.cidr_block]
  }

  ingress {
    description = "Neptune engine port from private subnet B"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.neptune_subnet_b.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-sg"
  })
}

# ----------------------------------------------------------------------------
# Custom parameter groups (neptune1.3 family) - no default groups used
# ----------------------------------------------------------------------------
resource "aws_neptune_cluster_parameter_group" "neptune_cluster_params" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-cluster-params"
  description = "Custom cluster parameter group for the ${local.name_prefix} Neptune cluster"

  parameter {
    name  = "neptune_enable_audit_logs"
    value = "0"
  }
}

resource "aws_neptune_parameter_group" "neptune_instance_params" {
  family      = "neptune1.3"
  name        = "${local.name_prefix}-instance-params"
  description = "Custom instance parameter group for the ${local.name_prefix} Neptune cluster"

  parameter {
    name  = "neptune_query_timeout"
    value = "120000"
  }
}

# ----------------------------------------------------------------------------
# Neptune subnet group spanning exactly the two private subnets (two AZs)
# ----------------------------------------------------------------------------
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group spanning two AZs for the ${local.name_prefix} Neptune cluster"
  subnet_ids  = [aws_subnet.neptune_subnet_a.id, aws_subnet.neptune_subnet_b.id]

  tags = local.common_tags
}

# ----------------------------------------------------------------------------
# Neptune cluster (encrypted, deletion protected) and single writer instance
# ----------------------------------------------------------------------------
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                   = "${local.name_prefix}-cluster"
  engine                               = "neptune"
  engine_version                       = "1.3.2.0"
  port                                 = 8182
  neptune_subnet_group_name            = aws_neptune_subnet_group.neptune_subnet_group.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_params.name
  vpc_security_group_ids               = [aws_security_group.neptune_sg.id]

  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  preferred_backup_window   = "03:00-04:00"
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "neptune_writer" {
  identifier                   = "${local.name_prefix}-writer"
  cluster_identifier           = aws_neptune_cluster.neptune_cluster.cluster_identifier
  engine                       = "neptune"
  instance_class               = "db.r6g.large"
  neptune_parameter_group_name = aws_neptune_parameter_group.neptune_instance_params.name
  neptune_subnet_group_name    = aws_neptune_subnet_group.neptune_subnet_group.name
  promotion_tier               = 1
  auto_minor_version_upgrade   = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Neptune deployment: dedicated VPC, multi-AZ subnets, custom cluster and
# instance parameter groups, KMS-encrypted cluster with one writer instance.
# -----------------------------------------------------------------------------

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (single variable for common tagging)
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used for resource naming and applied as a common tag to all resources."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,18}$", var.environment))
    error_message = "Environment name must start with a lowercase letter and contain only lowercase letters, digits, and hyphens (max 19 characters), since it is embedded in AWS resource identifiers."
  }
}

locals {
  name = "neptune-${var.environment}"

  common_tags = {
    Environment = var.environment
    Component   = "neptune"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "neptune_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-a"
  })
}

resource "aws_subnet" "neptune_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-b"
  })
}

resource "aws_neptune_subnet_group" "main" {
  name       = "${local.name}-subnet-group"
  subnet_ids = [aws_subnet.neptune_a.id, aws_subnet.neptune_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnet-group"
  })
}

resource "aws_security_group" "neptune" {
  name        = "${local.name}-sg"
  description = "Permit Neptune engine traffic on TCP 8182 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Neptune engine access from VPC CIDR only"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# -----------------------------------------------------------------------------
# Encryption key
# -----------------------------------------------------------------------------

resource "aws_kms_key" "neptune" {
  description             = "Customer-managed key for Neptune cluster storage encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.name}-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Parameter groups
# -----------------------------------------------------------------------------

resource "aws_neptune_cluster_parameter_group" "main" {
  family = "neptune1.3"
  name   = "${local.name}-cluster-pg"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  parameter {
    name  = "neptune_lab_mode"
    value = "disabled"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster-pg"
  })
}

resource "aws_neptune_parameter_group" "writer" {
  family = "neptune1.3"
  name   = "${local.name}-instance-pg"

  parameter {
    name  = "neptune_query_timeout"
    value = "120000"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-instance-pg"
  })
}

# -----------------------------------------------------------------------------
# Neptune cluster and writer instance
# -----------------------------------------------------------------------------

resource "aws_neptune_cluster" "main" {
  cluster_identifier                   = "${local.name}-cluster"
  engine                               = "neptune"
  engine_version                       = "1.3.2.1"
  port                                 = 8182
  neptune_subnet_group_name            = aws_neptune_subnet_group.main.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.main.id
  vpc_security_group_ids               = [aws_security_group.neptune.id]

  storage_encrypted               = true
  kms_key_arn                     = aws_kms_key.neptune.arn
  enable_cloudwatch_logs_exports  = ["audit"]

  deletion_protection          = true
  backup_retention_period      = 7
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${local.name}-cluster-final"

  tags = merge(local.common_tags, {
    Name = "${local.name}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "writer" {
  identifier                   = "${local.name}-writer"
  cluster_identifier           = aws_neptune_cluster.main.id
  engine                       = "neptune"
  engine_version               = "1.3.2.1"
  instance_class               = "db.r5.large"
  neptune_parameter_group_name = aws_neptune_parameter_group.writer.id

  # Tier 0 = highest failover priority; this single member is the cluster writer.
  promotion_tier = 0

  tags = merge(local.common_tags, {
    Name = "${local.name}-writer"
    Role = "writer"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (all have defaults so `terraform apply` runs unattended)
# ------------------------------------------------------------------------------

variable "name_prefix" {
  description = "Name prefix assigned to every created resource."
  type        = string
  default     = "neptune"
}

variable "vpc_cidr" {
  description = "Private (RFC 1918) CIDR block for the VPC hosting the Neptune cluster."
  type        = string
  default     = "10.0.0.0/16"
}

variable "example_subnet_cidr" {
  description = "CIDR block of the example subnet that is allowed to reach Neptune."
  type        = string
  default     = "10.0.1.0/24"
}

variable "secondary_subnet_cidr" {
  description = "CIDR block of the additional subnet in a second AZ (required by Neptune subnet groups)."
  type        = string
  default     = "10.0.2.0/24"
}

variable "neptune_instance_class" {
  description = "Instance class of the Neptune cluster instance."
  type        = string
  default     = "db.r5.large"
}

variable "backup_retention_period" {
  description = "Number of days automated Neptune backups are retained."
  type        = number
  default     = 7
}

variable "tags" {
  description = "Tags applied to every created resource."
  type        = map(string)
  default = {
    Environment = "example"
    ManagedBy   = "terraform"
    Project     = "neptune-example"
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  common_tags = merge(var.tags, {
    Terraform = "true"
  })
}

# ------------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
# ------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Networking
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

# The "example" subnet - the only network allowed to reach the Neptune cluster.
resource "aws_subnet" "example" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.example_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-example-subnet"
  })
}

# Neptune subnet groups require subnets spanning at least two AZs.
resource "aws_subnet" "neptune_secondary" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.secondary_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-secondary-subnet"
  })
}

# ------------------------------------------------------------------------------
# Security group - the only connection path attached to the cluster
# ------------------------------------------------------------------------------

resource "aws_security_group" "neptune" {
  name        = "${var.name_prefix}-cluster-sg"
  description = "Allow Neptune (TCP 8182) from the example subnet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Neptune traffic from the example subnet only"
    from_port   = 8182
    to_port     = 8182
    protocol    = "tcp"
    cidr_blocks = [aws_subnet.example.cidr_block]
  }

  egress {
    description = "Responses restricted to the example subnet"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_subnet.example.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-cluster-sg"
  })
}

# ------------------------------------------------------------------------------
# Neptune subnet group
# ------------------------------------------------------------------------------

resource "aws_neptune_subnet_group" "main" {
  name        = "${var.name_prefix}-subnet-group"
  description = "Subnets the Neptune cluster is deployed into (two AZs)"
  subnet_ids  = [aws_subnet.example.id, aws_subnet.neptune_secondary.id]

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-subnet-group"
  })
}

# ------------------------------------------------------------------------------
# Custom parameter groups (neptune1.3 family)
# ------------------------------------------------------------------------------

resource "aws_neptune_cluster_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${var.name_prefix}-cluster-param-group"
  description = "Custom cluster level parameters"

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }

  parameter {
    name  = "neptune_enforce_ssl"
    value = "1"
  }

  tags = local.common_tags
}

resource "aws_neptune_parameter_group" "main" {
  family      = "neptune1.3"
  name        = "${var.name_prefix}-instance-param-group"
  description = "Custom instance level parameters"

  parameter {
    name  = "neptune_query_timeout"
    value = "25000"
  }

  tags = local.common_tags
}

# ------------------------------------------------------------------------------
# IAM - least privilege support for IAM database authentication
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "neptune_assume_role" {
  statement {
    sid     = "AllowAssumeByExplicitlyTrustedPrincipals"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

data "aws_iam_policy_document" "neptune_db_connect" {
  statement {
    sid       = "AllowNeptuneDbConnect"
    effect    = "Allow"
    actions   = ["neptune-db:connect"]
    resources = [aws_neptune_cluster.main.arn]
  }
}

resource "aws_iam_role" "neptune_db_auth" {
  name               = "${var.name_prefix}-db-auth-role"
  description        = "Assumable only by explicitly trusted principals for Neptune IAM database authentication"
  assume_role_policy = data.aws_iam_policy_document.neptune_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_policy" "neptune_db_connect" {
  name        = "${var.name_prefix}-db-connect-policy"
  description = "Allow neptune-db:connect against the Neptune cluster only"
  policy      = data.aws_iam_policy_document.neptune_db_connect.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "neptune_db_connect" {
  role       = aws_iam_role.neptune_db_auth.name
  policy_arn = aws_iam_policy.neptune_db_connect.arn
}

# ------------------------------------------------------------------------------
# Neptune cluster
# ------------------------------------------------------------------------------

# Neptune identifiers only accept letters, digits and hyphens (they build the
# cluster DNS name), so a lowercase hyphenated identifier is used.
resource "aws_neptune_cluster" "main" {
  cluster_identifier                   = "${var.name_prefix}-cluster"
  engine                               = "neptune"
  port                                 = 8182
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.main.name
  neptune_subnet_group_name            = aws_neptune_subnet_group.main.name
  vpc_security_group_ids               = [aws_security_group.neptune.id]

  storage_encrypted                   = true
  iam_database_authentication_enabled = true
  deletion_protection                 = true

  backup_retention_period   = var.backup_retention_period
  preferred_backup_window   = "07:00-09:00"
  skip_final_snapshot       = false
  final_snapshot_identifier = "${var.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_neptune_cluster_instance" "main" {
  identifier                   = "${var.name_prefix}-instance-1"
  cluster_identifier           = aws_neptune_cluster.main.id
  instance_class               = var.neptune_instance_class
  neptune_parameter_group_name = aws_neptune_parameter_group.main.name

  tags = merge(local.common_tags, {
    Name = "${var.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "neptune_cluster_endpoint" {
  description = "Writer endpoint of the Neptune cluster."
  value       = aws_neptune_cluster.main.endpoint
}

output "neptune_cluster_reader_endpoint" {
  description = "Reader endpoint of the Neptune cluster."
  value       = aws_neptune_cluster.main.reader_endpoint
}

output "neptune_security_group_id" {
  description = "Security group attached to the Neptune cluster, for consumers inside the example subnet."
  value       = aws_security_group.neptune.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Common tags applied to all Chime Voice Connector resources."
  type        = map(string)
  default = {
    Project     = "chime-voice-connectors"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  primary_voice_connector_name   = "primary_voice_connector"
  secondary_voice_connector_name = "secondary_voice_connector"
  voice_connector_group_name     = "main_voice_connector_group"
}

resource "aws_chime_voice_connector" "primary" {
  name               = local.primary_voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector" "secondary" {
  name               = local.secondary_voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_chime_voice_connector_group" "main" {
  name = local.voice_connector_group_name

  connector {
    voice_connector_id = aws_chime_voice_connector.primary.id
    priority           = 1
  }

  connector {
    voice_connector_id = aws_chime_voice_connector.secondary.id
    priority           = 2
  }
}

output "voice_connector_group_id" {
  description = "The ID of the Chime Voice Connector group."
  value       = aws_chime_voice_connector_group.main.id
}

output "primary_voice_connector_id" {
  description = "The ID of the primary Chime Voice Connector."
  value       = aws_chime_voice_connector.primary.id
}

output "secondary_voice_connector_id" {
  description = "The ID of the secondary Chime Voice Connector."
  value       = aws_chime_voice_connector.secondary.id
}

output "primary_voice_connector_arn" {
  description = "The ARN of the primary Chime Voice Connector."
  value       = aws_chime_voice_connector.primary.arn
}

output "secondary_voice_connector_arn" {
  description = "The ARN of the secondary Chime Voice Connector."
  value       = aws_chime_voice_connector.secondary.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  voice_connector_region = "us-east-1"

  common_tags = {
    ManagedBy   = "terraform"
    Application = "chime-voice"
  }
