terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known metadata lookups (no pre-existing infrastructure required).
# Used to build the KMS key policy without hardcoding account IDs or partitions.
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  voice_connector_name  = "media_connector"
  media_stream_name     = "chime_media_stream"
  media_retention_hours = 24

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Amazon Chime Voice Connector - anchor resource for live call traffic.
# require_encryption = true enforces TLS signaling and SRTP media, the correct
# security posture for call audio streamed to Kinesis Video Streams.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector" "media_connector" {
  name               = local.voice_connector_name
  aws_region         = "us-east-1"
  require_encryption = true

  tags = merge(local.common_tags, {
    Name = local.voice_connector_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Enable SIP signaling logs and media metric logs for observability
# in CloudWatch Logs. Wired via the connector's `id` attribute, which holds
# the Voice Connector ID.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector_logging" "media_connector_logging" {
  voice_connector_id       = aws_chime_voice_connector.media_connector.id
  enable_sip_logs          = true
  enable_media_metric_logs = true
}

# -----------------------------------------------------------------------------
# KMS key used for encryption at rest on the Kinesis Video Stream.
# The first statement enables IAM policy delegation for the owning account
# (required to administer the key); the second grants the Kinesis Video
# Streams service principal only the encryption actions it needs.
# -----------------------------------------------------------------------------
resource "aws_kms_key" "media_stream" {
  description             = "Encrypts Chime Voice Connector call media streamed to Kinesis Video Streams"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountIAMPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CancelKeyDeletion",
          "kms:Create*",
          "kms:Decrypt",
          "kms:Delete*",
          "kms:Describe*",
          "kms:Disable*",
          "kms:Enable*",
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:Get*",
          "kms:List*",
          "kms:Put*",
          "kms:ReEncrypt*",
          "kms:RetireGrant",
          "kms:Revoke*",
          "kms:ScheduleKeyDeletion",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:Update*"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowKinesisVideoStreamsServiceEncryption"
        Effect = "Allow"
        Principal = {
          Service = "kinesisvideo.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "chime-media-stream-key"
  })
}

resource "aws_kms_alias" "media_stream" {
  name          = "alias/chime-media-stream"
  target_key_id = aws_kms_key.media_stream.key_id
}

# -----------------------------------------------------------------------------
# Kinesis Video Stream that receives the streamed Voice Connector call audio.
# Its data retention period must match the Voice Connector streaming
# configuration retention period.
# -----------------------------------------------------------------------------
resource "aws_kinesis_video_stream" "media_stream" {
  name                    = local.media_stream_name
  data_retention_in_hours = local.media_retention_hours
  kms_key_id              = aws_kms_key.media_stream.arn

  tags = merge(local.common_tags, {
    Name = local.media_stream_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Streaming configuration: sends Voice Connector call audio to the Kinesis
# Video Stream. Retention matches the stream; streaming is enabled.
# -----------------------------------------------------------------------------
resource "aws_chime_voice_connector_streaming" "media_connector_streaming" {
  voice_connector_id = aws_chime_voice_connector.media_connector.id
  data_retention     = local.media_retention_hours
  disabled           = false

  depends_on = [aws_kinesis_video_stream.media_stream]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "redshift-example"

  tags = {
    Project   = local.name_prefix
    ManagedBy = "terraform"
  }
}

###############################################################################
# Static provider metadata: Availability Zone selection (never hardcoded)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation: VPC with DNS enabled + one subnet per AZ
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-subnet-a"
  })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-subnet-b"
  })
}

###############################################################################
# Redshift subnet group spanning both Availability Zones
###############################################################################

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group for the Redshift cluster and managed endpoint access"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = local.tags
}

###############################################################################
# Security group: Redshift port reachable only from inside the VPC
###############################################################################

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-sg"
  description = "Allows Redshift (5439) only from within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-sg"
  })
}

resource "aws_vpc_security_group_ingress_rule" "redshift" {
  security_group_id = aws_security_group.redshift.id
  description       = "Redshift port 5439 from the VPC CIDR only"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 5439
  to_port           = 5439
}

resource "aws_vpc_security_group_egress_rule" "redshift" {
  security_group_id = aws_security_group.redshift.id
  description       = "Outbound traffic restricted to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

###############################################################################
# Redshift cluster (single-node RA3, credentials managed by Secrets Manager)
###############################################################################

resource "aws_redshift_cluster" "main" {
  cluster_identifier = "${local.name_prefix}-cluster"
  database_name      = "exampledb"
  cluster_type       = "single-node"
  node_type          = "ra3.xlplus"
  number_of_nodes    = 1
  port               = 5439

  # Master credentials are generated and stored by Amazon Redshift in AWS
  # Secrets Manager; no plaintext password exists anywhere in this configuration.
  master_username        = "admin"
  manage_master_password = true

  cluster_subnet_group_name = aws_redshift_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  enhanced_vpc_routing      = true

  encrypted = true

  automated_snapshot_retention_period = 7

  skip_final_snapshot = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Redshift-managed VPC endpoint access bound to the cluster
###############################################################################

resource "aws_redshift_endpoint_access" "main" {
  endpoint_name          = "${local.name_prefix}-endpoint"
  cluster_identifier     = aws_redshift_cluster.main.id
  subnet_group_name      = aws_redshift_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.redshift.id]
}

###############################################################################
# Greenfield Amazon Redshift deployment:
#   - Dedicated VPC with two subnets across two Availability Zones
#   - Redshift subnet group spanning both AZs (two-subnet endpoint access)
#   - Cluster encryption at rest with a customer-managed KMS key
#   - Master credentials managed natively by Redshift in Secrets Manager
#   - Audit logging to a private, encrypted, versioned S3 bucket
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

# -----------------------------------------------------------------------------
# Static, well-known lookups only (no pre-existing infrastructure discovered)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used as the naming prefix and Project tag."
  type        = string
  default     = "data-platform"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated Redshift VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block."
  }
}

variable "subnet_a_cidr" {
  description = "CIDR block for the first Redshift subnet (AZ 1)."
  type        = string
  default     = "10.0.1.0/24"

  validation {
    condition     = can(cidrnetmask(var.subnet_a_cidr))
    error_message = "subnet_a_cidr must be a valid IPv4 CIDR block."
  }
}

variable "subnet_b_cidr" {
  description = "CIDR block for the second Redshift subnet (AZ 2)."
  type        = string
  default     = "10.0.2.0/24"

  validation {
    condition     = can(cidrnetmask(var.subnet_b_cidr))
    error_message = "subnet_b_cidr must be a valid IPv4 CIDR block."
  }
}

variable "admin_cidr_blocks" {
  description = "Optional, tightly scoped admin CIDR blocks allowed to reach the Redshift port from outside the VPC. Must never include 0.0.0.0/0."
  type        = list(string)
  default     = []

  validation {
    condition     = length([for c in var.admin_cidr_blocks : c if c == "0.0.0.0/0" || c == "::/0"]) == 0
    error_message = "admin_cidr_blocks must not include 0.0.0.0/0 or ::/0."
  }
}

variable "database_name" {
  description = "Name of the initial database created in the cluster."
  type        = string
  default     = "analyticsdb"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,63}$", var.database_name))
    error_message = "database_name must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 64)."
  }
}

variable "master_username" {
  description = "Master username for the cluster (non-sensitive). The password itself is generated and rotated by Redshift in Secrets Manager."
  type        = string
  default     = "redshiftadmin"

  validation {
    condition     = can(regex("^[A-Za-z][A-Za-z0-9_]{0,127}$", var.master_username))
    error_message = "master_username must start with a letter and contain only letters, digits, and underscores (max 128)."
  }
}

variable "node_type" {
  description = "Redshift node type."
  type        = string
  default     = "ra3.xlplus"
}

variable "cluster_type" {
  description = "Redshift cluster type: single-node or multi-node."
  type        = string
  default     = "multi-node"

  validation {
    condition     = contains(["single-node", "multi-node"], var.cluster_type)
    error_message = "cluster_type must be 'single-node' or 'multi-node'."
  }
}

variable "number_of_nodes" {
  description = "Number of compute nodes (automatically forced to 1 when cluster_type is single-node)."
  type        = number
  default     = 2

  validation {
    condition     = var.number_of_nodes >= 1 && var.number_of_nodes <= 128
    error_message = "number_of_nodes must be between 1 and 128."
  }
}

variable "automated_snapshot_retention_period" {
  description = "Automated snapshot retention period in days (minimum 7)."
  type        = number
  default     = 7

  validation {
    condition     = var.automated_snapshot_retention_period >= 7 && var.automated_snapshot_retention_period <= 35
    error_message = "automated_snapshot_retention_period must be between 7 and 35 days."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  name_prefix        = var.project_name
  common_tags        = merge(var.tags, { Project = var.project_name })
  cluster_identifier = "${var.project_name}-redshift-cluster"
  subnet_group_name  = "${var.project_name}-redshift-subnet-group"
  audit_bucket_name  = "${var.project_name}-redshift-audit-logs-${random_id.bucket_suffix.hex}"
  final_snapshot_id  = "${var.project_name}-redshift-final-${random_id.bucket_suffix.hex}"
  redshift_port      = 5439
  number_of_nodes    = var.cluster_type == "single-node" ? 1 : var.number_of_nodes
}

# -----------------------------------------------------------------------------
# Networking: dedicated VPC, two subnets across AZs, IGW + routing
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-az1" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-az2" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rt" })
}

resource "aws_route_table_association" "redshift_a" {
  subnet_id      = aws_subnet.redshift_a.id
  route_table_id = aws_route_table.main.id
}

resource "aws_route_table_association" "redshift_b" {
  subnet_id      = aws_subnet.redshift_b.id
  route_table_id = aws_route_table.main.id
}

# -----------------------------------------------------------------------------
# Security group: engine port reachable only from the VPC CIDR and
# (optionally) tightly scoped admin CIDRs. Never 0.0.0.0/0 on 5439.
# -----------------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift engine access restricted to the VPC CIDR and approved admin CIDRs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port from within the VPC"
    from_port   = local.redshift_port
    to_port     = local.redshift_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  dynamic "ingress" {
    for_each = var.admin_cidr_blocks

    content {
      description = "Redshift engine port from approved admin CIDR"
      from_port   = local.redshift_port
      to_port     = local.redshift_port
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# -----------------------------------------------------------------------------
# Redshift subnet group spanning both Availability Zones
# -----------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = local.subnet_group_name
  description = "Redshift subnet group spanning two AZs for ${local.cluster_identifier}"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# KMS key for encryption at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Customer managed key for ${local.cluster_identifier} encryption at rest"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

# -----------------------------------------------------------------------------
# Parameter group: enforce TLS for all connections
# -----------------------------------------------------------------------------

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-redshift-params"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# S3 bucket for Redshift audit logs (private, encrypted, versioned)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "redshift_audit_logs" {
  bucket = local.audit_bucket_name

  tags = merge(local.common_tags, { Name = local.audit_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "redshift_audit_logs" {
  bucket = aws_s3_bucket.redshift_audit_logs.id

  depends_on = [aws_s3_bucket_public_access_block.redshift_audit_logs]

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "RedshiftAuditLogAclCheck"
        Effect    = "Allow"
        Principal = { Service = "redshift.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.redshift_audit_logs.arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "RedshiftAuditLogWrite"
        Effect    = "Allow"
        Principal = { Service = "redshift.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.redshift_audit_logs.arn}/audit/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Redshift cluster (private endpoint, encrypted, secret-managed credentials)
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = local.cluster_identifier
  database_name      = var.database_name
  master_username    = var.master_username

  # Master password is generated, rotated, and stored in Secrets Manager by
  # Redshift itself. No secret value ever appears in this configuration.
  manage_master_password = true

  node_type       = var.node_type
  cluster_type    = var.cluster_type
  number_of_nodes = local.number_of_nodes
  port            = local.redshift_port

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = var.automated_snapshot_retention_period
  skip_final_snapshot                 = false
  final_snapshot_identifier           = local.final_snapshot_id

  logging {
    enable               = true
    log_destination_type = "s3"
    bucket_name          = aws_s3_bucket.redshift_audit_logs.id
    s3_key_prefix        = "audit/"
  }

  tags = merge(local.common_tags, { Name = local.cluster_identifier })

  depends_on = [aws_s3_bucket_policy.redshift_audit_logs]

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "redshift_cluster_address" {
  description = "Hostname of the Redshift cluster endpoint."
  value       = aws_redshift_cluster.main.dns_name
}

output "redshift_cluster_port" {
  description = "Port on which the Redshift cluster accepts connections."
  value       = aws_redshift_cluster.main.port
}

output "redshift_cluster_endpoint" {
  description = "Full Redshift connection endpoint (address:port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_cluster_database_name" {
  description = "Initial database created on the cluster."
  value       = aws_redshift_cluster.main.database_name
}

output "redshift_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (created and rotated by Redshift)."
  value       = aws_redshift_cluster.main.master_password_secret_arn
}

output "redshift_cluster_subnet_group" {
  description = "Name of the Redshift subnet group providing endpoint access from two subnets."
  value       = aws_redshift_subnet_group.main.name
}

output "redshift_cluster_subnet_ids" {
  description = "IDs of the two subnets (one per Availability Zone) that provide cluster endpoint access."
  value       = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "analytics-platform"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.project_name))
    error_message = "project_name must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.environment))
    error_message = "environment must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "alert_email" {
  description = "Email endpoint subscribed to the Redshift event notification topic."
  type        = string
  default     = "ops-team@example.com"

  validation {
    condition     = can(regex("@", var.alert_email))
    error_message = "alert_email must be a valid email address."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "redshiftadmin"
  database_name   = "analytics_db"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}

# ------------------------------------------------------------------
# Network foundation
# ------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-route-table" })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# ------------------------------------------------------------------
# Cluster security group
# ------------------------------------------------------------------

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Redshift cluster access restricted to the VPC on port 5439"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift engine port from the VPC CIDR only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-sg" })
}

# ------------------------------------------------------------------
# KMS encryption
# ------------------------------------------------------------------

data "aws_iam_policy_document" "redshift_kms_key" {
  statement {
    sid    = "KeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KeyUsageByAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KeyUsageByRedshiftService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:RetireGrant",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values = [
        "redshift.${data.aws_region.current.name}.amazonaws.com",
        "sns.${data.aws_region.current.name}.amazonaws.com",
      ]
    }
  }

  statement {
    sid    = "KeyUsageBySnsService"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sns.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "redshift" {
  description             = "Encrypts the Redshift cluster, its snapshots, and the event notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.redshift_kms_key.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-key" })
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

# ------------------------------------------------------------------
# Master credentials
# ------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "redshift" {
  name        = "${local.name_prefix}/redshift/master-credentials"
  description = "Master credentials for the ${local.name_prefix} Redshift cluster"
  kms_key_id  = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-credentials" })
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id = aws_secretsmanager_secret.redshift.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
    engine   = "redshift"
    db_name  = local.database_name
  })
}

# ------------------------------------------------------------------
# Redshift cluster
# ------------------------------------------------------------------

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-redshift-subnet-group"
  description = "Private subnets hosting the Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-subnet-group" })
}

resource "aws_redshift_parameter_group" "main" {
  name   = "${local.name_prefix}-redshift-parameter-group"
  family = "redshift-1.0"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-parameter-group" })
}

resource "aws_redshift_cluster" "main" {
  cluster_identifier  = "${local.name_prefix}-redshift-cluster"
  database_name       = local.database_name
  master_username     = local.master_username
  master_password     = jsondecode(aws_secretsmanager_secret_version.redshift.secret_string)["password"]
  node_type           = "ra3.xlplus"
  cluster_type        = "single-node"
  number_of_nodes     = 1

  cluster_subnet_group_name    = aws_redshift_subnet_group.main.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  cluster_parameter_group_name = aws_redshift_parameter_group.main.name

  encrypted           = true
  kms_key_id          = aws_kms_key.redshift.arn
  publicly_accessible = false

  automated_snapshot_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-redshift-cluster-final"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------
# Event notifications
# ------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name              = "${local.name_prefix}-redshift-events"
  kms_master_key_id = aws_kms_key.redshift.arn

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-redshift-events" })
}

data "aws_iam_policy_document" "redshift_events_topic" {
  statement {
    sid       = "AllowRedshiftServicePublish"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events_topic.json
}

resource "aws_sns_topic_subscription" "redshift_events_email" {
  topic_arn = aws_sns_topic.redshift_events.arn
  protocol  = "email"
  endpoint  = var.alert_email
}

resource "aws_redshift_event_subscription" "main" {
  name          = "${local.name_prefix}-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster"
  source_ids    = [aws_redshift_cluster.main.cluster_identifier]
  severity      = "INFO"

  event_categories = [
    "configuration",
    "management",
    "monitoring",
    "security",
  ]

  depends_on = [aws_sns_topic_policy.redshift_events]
}

# ------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------

output "redshift_cluster_endpoint" {
  description = "Full connection endpoint of the Redshift cluster in host:port form (includes the port)."
  value       = aws_redshift_cluster.main.endpoint
}

output "redshift_event_topic_arn" {
  description = "ARN of the SNS topic that receives Redshift event notifications."
  value       = aws_sns_topic.redshift_events.arn
}

output "redshift_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master credentials. The secret value itself is never exposed."
  value       = aws_secretsmanager_secret.redshift.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "default_tags" {
  description = "Default tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Project     = "redshift-event-notifications"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

locals {
  cluster_identifier        = "redshift-events-cluster"
  database_name             = "eventsdb"
  master_username           = "redshiftadmin"
  final_snapshot_identifier = "${local.cluster_identifier}-final-snapshot"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.default_tags, { Name = "redshift-events-vpc" })
}

resource "aws_subnet" "redshift_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.default_tags, { Name = "redshift-events-subnet-a" })
}

resource "aws_subnet" "redshift_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(var.default_tags, { Name = "redshift-events-subnet-b" })
}

resource "aws_redshift_subnet_group" "redshift" {
  name        = "redshift-events-subnet-group"
  description = "Subnet group for the Redshift events cluster spanning multiple availability zones"
  subnet_ids  = [aws_subnet.redshift_a.id, aws_subnet.redshift_b.id]

  tags = var.default_tags
}

resource "aws_security_group" "redshift" {
  name        = "redshift-events-sg"
  description = "Restricts ingress to the Redshift engine port (5439) from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC only"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic limited to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.default_tags, { Name = "redshift-events-sg" })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Encrypts the Redshift cluster, the SNS event topic, and the master password secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = var.default_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/redshift-events-key"
  target_key_id = aws_kms_key.redshift.key_id
}

# ---------------------------------------------------------------------------
# Master credentials (runtime-generated, persisted in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name                    = "redshift-events-cluster-master-password"
  description             = "Master password for the ${local.cluster_identifier} Redshift cluster"
  kms_key_id              = aws_kms_key.redshift.arn
  recovery_window_in_days = 7

  tags = var.default_tags
}

resource "aws_secretsmanager_secret_version" "redshift_master" {
  secret_id     = aws_secretsmanager_secret.redshift_master.id
  secret_string = random_password.redshift_master.result
}

# ---------------------------------------------------------------------------
# Event delivery topic
# ---------------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name              = "redshift-cluster-events"
  kms_master_key_id = aws_kms_key.redshift.arn

  tags = var.default_tags
}

data "aws_iam_policy_document" "redshift_events_topic" {
  policy_id = "RedshiftEventsTopicPolicy"

  statement {
    sid       = "AllowRedshiftEventPublishing"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.redshift_events.arn]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events_topic.json
}

# ---------------------------------------------------------------------------
# Redshift cluster
# ---------------------------------------------------------------------------

resource "aws_redshift_cluster" "main" {
  cluster_identifier = local.cluster_identifier
  database_name      = local.database_name
  cluster_type       = "single-node"
  node_type          = "dc2.large"
  master_username    = local.master_username
  master_password    = aws_secretsmanager_secret_version.redshift_master.secret_string

  cluster_subnet_group_name = aws_redshift_subnet_group.redshift.name
  vpc_security_group_ids    = [aws_security_group.redshift.id]
  publicly_accessible       = false
  port                      = 5439

  encrypted  = true
  kms_key_id = aws_kms_key.redshift.arn

  automated_snapshot_retention_period = 7
  skip_final_snapshot                 = false
  final_snapshot_identifier           = local.final_snapshot_identifier

  tags = merge(var.default_tags, { Name = local.cluster_identifier })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Event subscription (cluster lifecycle events -> SNS)
# ---------------------------------------------------------------------------

resource "aws_redshift_event_subscription" "cluster_events" {
  name             = "redshift-cluster-events-subscription"
  sns_topic_arn    = aws_sns_topic.redshift_events.arn
  source_type      = "cluster"
  source_ids       = [aws_redshift_cluster.main.cluster_identifier]
  severity         = "INFO"
  event_categories = ["management"]
  enabled          = true

  tags = var.default_tags

  depends_on = [aws_sns_topic_policy.redshift_events]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# User-controlled values (all defaulted so terraform apply runs non-interactively)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "example"
}

variable "environment" {
  description = "Environment name (e.g. dev, staging, prod) used for naming and tagging."
  type        = string
  default     = "dev"
}

variable "master_username" {
  description = "Master username for the Redshift cluster (non-secret)."
  type        = string
  default     = "admin"
}

variable "number_of_nodes" {
  description = "Number of compute nodes in the multi-node Redshift cluster."
  type        = number
  default     = 2

  validation {
    condition     = var.number_of_nodes >= 2 && var.number_of_nodes <= 128
    error_message = "A multi-node Redshift cluster requires between 2 and 128 compute nodes."
  }
}

variable "common_tags" {
  description = "Common tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Team      = "data-platform"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata (AZ selection) and locals
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  tags = merge(
    var.common_tags,
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "redshift_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-az1" })
}

resource "aws_subnet" "redshift_az2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-az2" })
}

resource "aws_redshift_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Subnet group spanning two distinct AZs for the example Redshift cluster."
  subnet_ids  = [aws_subnet.redshift_az1.id, aws_subnet.redshift_az2.id]

  tags = local.tags
}

resource "aws_security_group" "redshift" {
  name        = "${local.name_prefix}-redshift-sg"
  description = "Allows Redshift engine access on TCP 5439 from within the VPC only."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.tags, { Name = "${local.name_prefix}-redshift-sg" })
}

resource "aws_security_group_rule" "redshift_ingress_5439" {
  type              = "ingress"
  from_port         = 5439
  to_port           = 5439
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.redshift.id
}

# -----------------------------------------------------------------------------
# Encryption and master password
# -----------------------------------------------------------------------------

resource "aws_kms_key" "redshift" {
  description             = "Dedicated KMS key for at-rest encryption of the example Redshift cluster."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags
}

resource "aws_kms_alias" "redshift" {
  name          = "alias/${local.name_prefix}-redshift"
  target_key_id = aws_kms_key.redshift.key_id
}

resource "random_password" "redshift_master" {
  length      = 32
  special     = false
  min_upper   = 1
  min_lower   = 1
  min_numeric = 1
}

resource "aws_secretsmanager_secret" "redshift_master" {
  name        = "${local.name_prefix}/redshift/master-password"
  description = "Master password for the example Redshift cluster."
  kms_key_id  = aws_kms_key.redshift.arn

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id     = aws_secretsmanager_secret.redshift_master.id
  secret_string = random_password.redshift_master.result
}

# -----------------------------------------------------------------------------
# Example parameter group
# -----------------------------------------------------------------------------

resource "aws_redshift_parameter_group" "example" {
  name        = "${local.name_prefix}-param-group"
  family      = "redshift-1.0"
  description = "Example Redshift parameter group with hardened and demonstration settings."

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "enable_user_activity_logging"
    value = "true"
  }

  parameter {
    name  = "statement_timeout"
    value = "7200000"
  }

  parameter {
    name = "wlm_json_configuration"
    value = jsonencode([
      {
        query_concurrency = 5
        user_group        = ["etl_users"]
      },
      {
        query_concurrency = 15
        query_group       = ["reporting"]
      },
      {
        auto_wlm = true
      }
    ])
  }

  tags = local.tags
}

# -----------------------------------------------------------------------------
# Redshift cluster
# -----------------------------------------------------------------------------

resource "aws_redshift_cluster" "example" {
  cluster_identifier                  = "${local.name_prefix}-cluster"
  database_name                       = "exampledb"
  master_username                     = var.master_username
  master_password                     = aws_secretsmanager_secret_version.redshift.secret_string
  node_type                           = "ra3.xlplus"
  cluster_type                        = "multi-node"
  number_of_nodes                     = var.number_of_nodes
  port                                = 5439
  cluster_subnet_group_name           = aws_redshift_subnet_group.main.name
  cluster_parameter_group_name        = aws_redshift_parameter_group.example.name
  vpc_security_group_ids              = [aws_security_group.redshift.id]
  publicly_accessible                 = false
  encrypted                           = true
  kms_key_id                          = aws_kms_key.redshift.arn
  automated_snapshot_retention_period = 7
  allow_version_upgrade               = true
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "${local.name_prefix}-cluster-final"

  tags = merge(local.tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Event notifications for the parameter group
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "redshift_events" {
  name = "${local.name_prefix}-redshift-events"

  tags = local.tags
}

data "aws_iam_policy_document" "redshift_events" {
  statement {
    sid     = "AllowRedshiftServiceToPublish"
    effect  = "Allow"
    actions = ["SNS:Publish"]

    principals {
      type        = "Service"
      identifiers = ["redshift.amazonaws.com"]
    }

    resources = [aws_sns_topic.redshift_events.arn]
  }
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn    = aws_sns_topic.redshift_events.arn
  policy = data.aws_iam_policy_document.redshift_events.json
}

resource "aws_redshift_event_subscription" "parameter_group_events" {
  name          = "${local.name_prefix}-parameter-group-events"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster-parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]
  severity      = "INFO"
  enabled       = true

  tags = local.tags

  depends_on = [aws_sns_topic_policy.redshift_events]
}

# -----------------------------------------------------------------------------
# Outputs (non-sensitive only)
# -----------------------------------------------------------------------------

output "cluster_endpoint_address" {
  description = "Connection endpoint address (hostname) of the Redshift cluster, derived from the combined host:port endpoint."
  value       = split(":", aws_redshift_cluster.example.endpoint)[0]
}

output "cluster_endpoint_port" {
  description = "Connection endpoint port of the Redshift cluster."
  value       = aws_redshift_cluster.example.port
}

output "parameter_group_name" {
  description = "Name of the Redshift parameter group attached to the cluster."
  value       = aws_redshift_parameter_group.example.name
}

output "redshift_events_sns_topic_arn" {
  description = "ARN of the SNS topic receiving Redshift parameter group event notifications."
  value       = aws_sns_topic.redshift_events.arn
}

output "redshift_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Redshift master password (the secret value itself is never exposed)."
  value       = aws_secretsmanager_secret.redshift_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for consistent resource tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  master_username = "exampleadmin"

  tags = {
    Environment = var.environment
    Project     = "redshift-example"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Greenfield network
# ------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "redshift-example-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.tags, {
    Name = "redshift-example-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.tags, {
    Name = "redshift-example-private-b"
  })
}

resource "aws_security_group" "redshift" {
  name        = "example-redshift-sg"
  description = "Restrict Redshift access to port 5439 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Redshift connections from within the VPC"
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, {
    Name = "example-redshift-sg"
  })
}

# ------------------------------------------------------------------------------
# Redshift subnet group and example parameter group
# ------------------------------------------------------------------------------

resource "aws_redshift_subnet_group" "example" {
  name        = "example-redshift-subnet-group"
  description = "Subnet group for the example Redshift cluster"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = local.tags
}

resource "aws_redshift_parameter_group" "example" {
  name        = "example-redshift-parameter-group"
  family      = "redshift-1.0"
  description = "Example parameter group attached to the example Redshift cluster"

  parameter {
    name  = "require_ssl"
    value = "true"
  }

  parameter {
    name  = "wlm_json_configuration"
    value = "[{\"user_group\":[\"example_user_group\"],\"query_concurrency\":5}]"
  }

  tags = local.tags
}

# ------------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager)
# ------------------------------------------------------------------------------

resource "random_password" "redshift_master" {
  length           = 24
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "redshift" {
  name        = "example/${var.environment}/redshift/master-password"
  description = "Master credentials for the example Redshift cluster"

  tags = local.tags
}

resource "aws_secretsmanager_secret_version" "redshift" {
  secret_id = aws_secretsmanager_secret.redshift.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.redshift_master.result
  })
}

# ------------------------------------------------------------------------------
# Redshift cluster
# ------------------------------------------------------------------------------

resource "aws_redshift_cluster" "example" {
  cluster_identifier           = "example-redshift-cluster"
  database_name                = "exampledb"
  cluster_type                 = "single-node"
  node_type                    = "ra3.xlplus"
  master_username              = local.master_username
  master_password              = random_password.redshift_master.result
  cluster_subnet_group_name    = aws_redshift_subnet_group.example.name
  cluster_parameter_group_name = aws_redshift_parameter_group.example.name
  vpc_security_group_ids       = [aws_security_group.redshift.id]
  publicly_accessible          = false
  encrypted                    = true
  skip_final_snapshot          = true

  tags = merge(local.tags, {
    Name            = "example-redshift-cluster"
    MasterSecretArn = aws_secretsmanager_secret.redshift.arn
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Event notifications: KMS-encrypted SNS topic wired to the parameter group
# ------------------------------------------------------------------------------

resource "aws_kms_key" "redshift_events" {
  description             = "KMS key used to encrypt the Redshift event notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMUserPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowRedshiftToPublishEncryptedEvents"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "redshift_events" {
  name          = "alias/example-redshift-events"
  target_key_id = aws_kms_key.redshift_events.key_id
}

resource "aws_sns_topic" "redshift_events" {
  name              = "example-redshift-events"
  kms_master_key_id = aws_kms_key.redshift_events.arn

  tags = merge(local.tags, {
    Name = "example-redshift-events"
  })
}

resource "aws_sns_topic_policy" "redshift_events" {
  arn = aws_sns_topic.redshift_events.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRedshiftEventPublish"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.redshift_events.arn
      }
    ]
  })
}

resource "aws_redshift_event_subscription" "redshift_events" {
  name          = "example-redshift-event-subscription"
  sns_topic_arn = aws_sns_topic.redshift_events.arn
  source_type   = "cluster-parameter-group"
  source_ids    = [aws_redshift_parameter_group.example.name]
  severity      = "INFO"
  enabled       = true

  depends_on = [aws_sns_topic_policy.redshift_events]

  tags = local.tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_group_name" {
  description = "Name of the IAM group that both users will belong to."
  type        = string
  default     = "app-developers"
}

variable "iam_usernames" {
  description = "Exactly two IAM usernames to create."
  type        = set(string)
  default     = ["alice", "bob"]

  validation {
    condition     = length(var.iam_usernames) == 2
    error_message = "Exactly two IAM usernames must be provided."
  }
}

variable "tags" {
  description = "Tags applied to all taggable IAM resources."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  s3_readonly_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowS3ReadOnlyListing"
        Effect   = "Allow"
        Action   = ["s3:ListAllMyBuckets", "s3:GetBucketLocation"]
        Resource = "arn:aws:s3:::*"
      }
    ]
  })
}

resource "aws_iam_group" "developers" {
  name = var.iam_group_name
  path = "/"
}

resource "aws_iam_user" "app_users" {
  for_each = var.iam_usernames

  name = each.value
  path = "/"
  tags = var.tags
}

resource "aws_iam_user_group_membership" "app_users_developers" {
  for_each = var.iam_usernames

  user   = aws_iam_user.app_users[each.key].name
  groups = [aws_iam_group.developers.name]
}

resource "aws_iam_policy" "developer_s3_readonly" {
  name        = "${var.iam_group_name}-s3-readonly"
  description = "Least-privilege read-only S3 listing permissions for the ${var.iam_group_name} group."
  path        = "/"
  policy      = local.s3_readonly_policy
  tags        = var.tags
}

resource "aws_iam_group_policy_attachment" "developers_s3_readonly" {
  group      = aws_iam_group.developers.name
  policy_arn = aws_iam_policy.developer_s3_readonly.arn
}

output "iam_group_name" {
  description = "Name of the IAM group that both users belong to."
  value       = aws_iam_group.developers.name
}

output "iam_usernames" {
  description = "Usernames of the two created IAM users."
  value       = [for user in aws_iam_user.app_users : user.name]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_group" "example" {
  name = "example_group"
  path = "/"
}

resource "aws_iam_policy" "example" {
  name        = "example_group_policy"
  path        = "/"
  description = "Least-privilege policy allowing members of the example group to inspect the group itself and its attached policies"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GroupSelfInspection"
        Effect = "Allow"
        Action = [
          "iam:GetGroup",
          "iam:GetGroupPolicy",
          "iam:ListAttachedGroupPolicies",
          "iam:ListGroupPolicies"
        ]
        Resource = aws_iam_group.example.arn
      }
    ]
  })

  tags = {
    Name        = "example_group_policy"
    Environment = "example"
  }
}

resource "aws_iam_group_policy_attachment" "example" {
  group      = aws_iam_group.example.name
  policy_arn = aws_iam_policy.example.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

variable "additional_tags" {
  description = "Additional tags applied to all tagged resources."
  type        = map(string)
  default     = {}
}

locals {
  username    = "terraform-ssh-user"
  secret_name = "iam/${local.username}/ssh-private-key"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Purpose     = "ssh-authentication"
    },
    var.additional_tags
  )
}

# Generate the SSH key pair in-configuration so no key material is hardcoded.
resource "tls_private_key" "ssh_user_key" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_iam_user" "ssh_user" {
  name = local.username
  path = "/"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# The SSH public key is the sole credential for this IAM user.
resource "aws_iam_user_ssh_key" "ssh_user_key" {
  username   = aws_iam_user.ssh_user.name
  encoding   = "SSH"
  public_key = tls_private_key.ssh_user_key.public_key_openssh
}

resource "aws_secretsmanager_secret" "ssh_user_private_key" {
  name        = local.secret_name
  description = "Private SSH key for IAM user ${local.username}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_user_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_user_private_key.id
  secret_string = tls_private_key.ssh_user_key.private_key_pem
}

# Least-privilege inline policy: the user may read only its own private key
# from Secrets Manager. No wildcard Action/Resource combinations.
resource "aws_iam_user_policy" "ssh_user_read_own_key" {
  name = "read-own-ssh-private-key"
  user = aws_iam_user.ssh_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadOwnSshPrivateKey"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.ssh_user_private_key.arn
      }
    ]
  })
}

output "iam_user_name" {
  description = "Name of the IAM user."
  value       = aws_iam_user.ssh_user.name
}

output "iam_user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.ssh_user.arn
}

output "ssh_key_fingerprint" {
  description = "MD5 fingerprint of the SSH public key uploaded to the IAM user."
  value       = aws_iam_user_ssh_key.ssh_user_key.fingerprint
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the SSH private key."
  value       = aws_secretsmanager_secret.ssh_user_private_key.arn
  sensitive   = true
}

# Basic AWS IAM group example.
#
# Creates:
#   - An IAM group (name configurable via variable with a default value)
#   - A least-privilege customer-managed policy scoped to a team S3 bucket
#     created in this same configuration, attached via aws_iam_group_policy_attachment
#   - A sample IAM user and group membership
#   - Outputs for downstream verification of the group name and ARN

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (all defaults set so `terraform apply` runs unattended)
# -----------------------------------------------------------------------------

variable "iam_group_name" {
  description = "Name of the IAM group to create."
  type        = string
  default     = "developers"
}

variable "sample_user_name" {
  description = "Name of the sample IAM user added to the group."
  type        = string
  default     = "sample-developer"
}

variable "artifact_bucket_name_prefix" {
  description = "Name prefix for the S3 bucket the developers group is granted access to."
  type        = string
  default     = "developers-team-artifacts"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  artifact_bucket_name = "${var.artifact_bucket_name_prefix}-${random_id.bucket_suffix.hex}"

  common_tags = {
    ManagedBy   = "terraform"
    Component   = "iam-group-example"
    Environment = "sandbox"
  }
}

# -----------------------------------------------------------------------------
# Random suffix keeps the globally-unique S3 bucket name collision-free
# -----------------------------------------------------------------------------

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Team artifacts bucket that anchors the least-privilege policy scope
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "team_artifacts" {
  bucket = local.artifact_bucket_name

  tags = merge(local.common_tags, {
    Name = local.artifact_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "team_artifacts" {
  bucket = aws_s3_bucket.team_artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

# -----------------------------------------------------------------------------
# IAM group (IAM groups are not a taggable IAM resource type; no tags argument)
# -----------------------------------------------------------------------------

resource "aws_iam_group" "developers" {
  name = var.iam_group_name
  path = "/teams/"
}

# -----------------------------------------------------------------------------
# Least-privilege policy: explicit, scoped actions and resources only
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "developers_artifacts_access" {
  statement {
    sid     = "ListTeamArtifactsBucket"
    effect  = "Allow"
    actions = ["s3:ListBucket", "s3:GetBucketLocation"]

    resources = [
      aws_s3_bucket.team_artifacts.arn,
    ]
  }

  statement {
    sid     = "ManageTeamArtifactsObjects"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]

    resources = [
      "${aws_s3_bucket.team_artifacts.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "developers_artifacts_access" {
  name        = "developers-artifacts-access"
  description = "Least-privilege S3 access to the developers team artifacts bucket"
  policy      = data.aws_iam_policy_document.developers_artifacts_access.json

  tags = local.common_tags
}

resource "aws_iam_group_policy_attachment" "developers_artifacts_access" {
  group      = aws_iam_group.developers.name
  policy_arn = aws_iam_policy.developers_artifacts_access.arn
}

# -----------------------------------------------------------------------------
# Sample user and group membership
# -----------------------------------------------------------------------------

resource "aws_iam_user" "sample_developer" {
  name          = var.sample_user_name
  path          = "/teams/"
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = var.sample_user_name
  })
}

resource "aws_iam_group_membership" "developers" {
  name  = "developers-team-membership"
  group = aws_iam_group.developers.name
  users = [aws_iam_user.sample_developer.name]
}

# -----------------------------------------------------------------------------
# Outputs for downstream verification
# -----------------------------------------------------------------------------

output "iam_group_name" {
  description = "Name of the developers IAM group."
  value       = aws_iam_group.developers.name
}

output "iam_group_arn" {
  description = "ARN of the developers IAM group."
  value       = aws_iam_group.developers.arn
}

output "iam_group_policy_arn" {
  description = "ARN of the customer-managed policy attached to the group."
  value       = aws_iam_policy.developers_artifacts_access.arn
}

output "sample_iam_user_name" {
  description = "Name of the sample IAM user belonging to the group."
  value       = aws_iam_user.sample_developer.name
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "iam_user_name" {
  description = "Name of the IAM user to create."
  type        = string
  default     = "example-user"

  validation {
    condition     = can(regex("^[A-Za-z0-9+=,.@_-]{1,64}$", var.iam_user_name))
    error_message = "IAM user name must be 1-64 characters consisting of letters, digits, or the symbols plus (+), equal (=), comma (,), period (.), at (@), underscore (_), and hyphen (-)."
  }
}

variable "environment" {
  description = "Value applied to the Environment tag on all resources."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  policy_name        = "${var.iam_user_name}-s3-read-only"
  secret_name        = "${var.iam_user_name}-access-keys"
  data_bucket_prefix = "${var.iam_user_name}-data"
}

resource "aws_iam_user" "example" {
  name = var.iam_user_name

  tags = merge(
    local.common_tags,
    {
      Name = var.iam_user_name
    },
  )
}

resource "aws_iam_policy" "example" {
  name        = local.policy_name
  description = "Least-privilege read-only access to the ${local.data_bucket_prefix} S3 location."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListDataBucket"
        Effect   = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = "arn:aws:s3:::${local.data_bucket_prefix}"
      },
      {
        Sid    = "ReadDataObjects"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "arn:aws:s3:::${local.data_bucket_prefix}/*"
      }
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.policy_name
    },
  )
}

resource "aws_iam_user_policy_attachment" "example" {
  user       = aws_iam_user.example.name
  policy_arn = aws_iam_policy.example.arn
}

resource "aws_iam_access_key" "example" {
  user = aws_iam_user.example.name
}

resource "aws_secretsmanager_secret" "example" {
  name        = local.secret_name
  description = "Programmatic access credentials for the ${var.iam_user_name} IAM user."

  tags = merge(
    local.common_tags,
    {
      Name = local.secret_name
    },
  )
}

resource "aws_secretsmanager_secret_version" "example" {
  secret_id = aws_secretsmanager_secret.example.arn

  secret_string = jsonencode({
    username          = aws_iam_user.example.name
    access_key_id     = aws_iam_access_key.example.id
    secret_access_key = aws_iam_access_key.example.secret
  })
}

output "iam_user_name" {
  description = "Name of the IAM user."
  value       = aws_iam_user.example.name
}

output "iam_user_arn" {
  description = "ARN of the IAM user."
  value       = aws_iam_user.example.arn
}

output "iam_user_unique_id" {
  description = "Unique ID assigned by AWS to the IAM user."
  value       = aws_iam_user.example.unique_id
}

output "iam_access_key_id" {
  description = "Access key ID for the IAM user. The secret access key is stored in AWS Secrets Manager."
  value       = aws_iam_access_key.example.id
}

output "iam_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the IAM user's access credentials."
  value       = aws_secretsmanager_secret.example.arn
}

