provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "prod"
}

variable "managed_by" {
  description = "Value applied to the ManagedBy tag on all taggable resources"
  type        = string
  default     = "terraform"
}

locals {
  bucket_name = "owner-pays-${var.environment}-${random_id.bucket_suffix.hex}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = var.managed_by
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_s3_bucket" "owner_pays_bucket" {
  bucket = local.bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_request_payment_configuration" "owner_pays" {
  bucket = aws_s3_bucket.owner_pays_bucket.id

  payer = "BucketOwner"
}

resource "aws_s3_bucket_public_access_block" "owner_pays" {
  bucket = aws_s3_bucket.owner_pays_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "owner_pays" {
  bucket = aws_s3_bucket.owner_pays_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "owner_pays" {
  bucket = aws_s3_bucket.owner_pays_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "owner_pays" {
  bucket = aws_s3_bucket.owner_pays_bucket.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

output "bucket_id" {
  description = "ID (globally unique name) of the S3 bucket"
  value       = aws_s3_bucket.owner_pays_bucket.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket"
  value       = aws_s3_bucket.owner_pays_bucket.arn
}

terraform {
