      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Globally unique S3 bucket name. Must contain only lowercase letters and digits (hyphens are stripped automatically)."
  type        = string
  default     = "exampleversioningbucket001"
}

variable "tags" {
  description = "Tags applied to the S3 bucket for cost allocation and ownership tracking."
  type        = map(string)
  default     = {}
}

locals {
  bucket_name = replace(lower(var.bucket_name), "-", "")
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = local.bucket_name
  tags   = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "example_bucket" {
