# HTTP API: the single public entry point for the service.
resource "aws_apigatewayv2_api" "cats_api" {
  name          = "cats-api"
  protocol_type = "HTTP"
  description   = "Public entry point for uploading and fetching cat pictures."

  cors_configuration {
    allow_origins = ["*"]
    allow_methods = ["*"]
    allow_headers = ["*"]
    max_age       = 300
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "upload_cat_picture" {
  api_id                 = aws_apigatewayv2_api.cats_api.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.upload_cat_picture.invoke_arn
  integration_method     = "POST"
  payload_format_version = "2.0"
  timeout_milliseconds   = 12000
}

resource "aws_apigatewayv2_integration" "random_cat_picture" {
  api_id                 = aws_apigatewayv2_api.cats_api.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.random_cat_picture.invoke_arn
  integration_method     = "POST"
  payload_format_version = "2.0"
  timeout_milliseconds   = 12000
}

resource "aws_apigatewayv2_integration" "index_page" {
  api_id                 = aws_apigatewayv2_api.cats_api.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.index_page.invoke_arn
  integration_method     = "POST"
  payload_format_version = "2.0"
  timeout_milliseconds   = 6000
}

resource "aws_apigatewayv2_route" "upload_cat_picture" {
