resource "aws_apigatewayv2_stage" "default" {
  api_id      = aws_apigatewayv2_api.cats_api.id
  name        = "$default"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_access_logs.arn
    format = jsonencode({
      requestId        = "$context.requestId"
      requestTime      = "$context.requestTime"
      httpMethod       = "$context.httpMethod"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
      sourceIp         = "$context.identity.sourceIp"
      integrationError = "$context.integration.error"
    })
  }

  default_route_settings {
    detailed_metrics_enabled = true
    throttling_burst_limit   = 50
    throttling_rate_limit    = 100
  }

  tags = local.common_tags
}

output "api_endpoint" {
  description = "Base invoke endpoint URL of the cat picture HTTP API."
  value       = aws_apigatewayv2_api.cats_api.api_endpoint
}

output "upload_cat_url" {
  description = "POST /cats endpoint for uploading cat pictures (base64-encoded image body)."
  value       = "${aws_apigatewayv2_api.cats_api.api_endpoint}/cats"
}

output "random_cat_url" {
  description = "GET /cats/random endpoint returning a presigned URL for a random cat picture."
  value       = "${aws_apigatewayv2_api.cats_api.api_endpoint}/cats/random"
}

output "cat_pictures_bucket_name" {
  description = "Name of the private S3 bucket storing cat pictures."
  value       = aws_s3_bucket.cat_pictures.bucket
}

terraform {
