# ---------------------------------------------------------------------------
# Lambda functions
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "upload" {
  function_name = local.upload_function_name
  description   = "Returns short-lived presigned PUT URLs for uploading cat pictures."
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"

  filename         = data.archive_file.upload.output_path
  source_code_hash = data.archive_file.upload.output_base64sha256

  timeout     = 10
  memory_size = 256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic,
    aws_iam_role_policy.lambda_s3_access,
    aws_cloudwatch_log_group.upload,
  ]
}

resource "aws_lambda_function" "random_fetch" {
  function_name = local.random_function_name
  description   = "Returns a presigned GET URL for a randomly selected cat picture."
  role          = aws_iam_role.lambda_exec.arn
  handler       = "lambda_function.lambda_handler"
  runtime       = "python3.12"

  filename         = data.archive_file.random_fetch.output_path
  source_code_hash = data.archive_file.random_fetch.output_base64sha256

  timeout     = 10
  memory_size = 256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
    }
  }

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic,
    aws_iam_role_policy.lambda_s3_access,
    aws_cloudwatch_log_group.random_fetch,
  ]
}

# ---------------------------------------------------------------------------
# API Gateway (HTTP API) routing to the Lambda functions
# ---------------------------------------------------------------------------

resource "aws_apigatewayv2_api" "cats" {
  name          = "${var.project}-api"
  protocol_type = "HTTP"

  cors_configuration {
    allow_origins     = ["*"]
    allow_methods     = ["POST", "GET", "OPTIONS"]
    allow_headers     = ["content-type"]
    allow_credentials = false
    max_age           = 300
  }

  tags = local.common_tags
}

resource "aws_apigatewayv2_integration" "upload" {
  api_id                 = aws_apigatewayv2_api.cats.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.upload.invoke_arn
  payload_format_version = "2.0"
  timeout_milliseconds   = 10000
}

resource "aws_apigatewayv2_integration" "random_fetch" {
  api_id                 = aws_apigatewayv2_api.cats.id
  integration_type       = "AWS_PROXY"
  integration_uri        = aws_lambda_function.random_fetch.invoke_arn
  payload_format_version = "2.0"
  timeout_milliseconds   = 10000
}

resource "aws_apigatewayv2_route" "upload" {
  api_id    = aws_apigatewayv2_api.cats.id
  route_key = "POST /cats"
  target    = "integrations/${aws_apigatewayv2_integration.upload.id}"
}

resource "aws_apigatewayv2_route" "random_fetch" {
  api_id    = aws_apigatewayv2_api.cats.id
  route_key = "GET /cats/random"
  target    = "integrations/${aws_apigatewayv2_integration.random_fetch.id}"
}

resource "aws_apigatewayv2_stage" "default" {
  api_id      = aws_apigatewayv2_api.cats.id
  name        = "$default"
  auto_deploy = true

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Invoke permissions scoped to the API execution ARN
# ---------------------------------------------------------------------------

resource "aws_lambda_permission" "upload" {
  statement_id  = "AllowApiGatewayInvokeUpload"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload.function_name
  principal     = "apigatewayv2.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.cats.execution_arn}/*/POST/cats"
}

resource "aws_lambda_permission" "random_fetch" {
  statement_id  = "AllowApiGatewayInvokeRandomFetch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.random_fetch.function_name
  principal     = "apigatewayv2.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.cats.execution_arn}/*/GET/cats/random"
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "api_invoke_url" {
  description = "Invoke URL of the cat pictures API. POST /cats with an image/* Content-Type returns a presigned upload URL; GET /cats/random returns a presigned URL for a random cat picture."
  value       = aws_apigatewayv2_stage.default.invoke_url
}

output "s3_bucket_name" {
  description = "Name of the private S3 bucket that stores the uploaded cat pictures."
  value       = aws_s3_bucket.cat_pictures.id
}

###############################################################################
# Cat Picture Service
#
# Serverless web service behind a public HTTPS API:
#   POST /cats        -> upload a base64-encoded cat picture (S3 + DynamoDB)
#   GET  /cats/random -> fetch a random cat picture (presigned URL via Lambda)
#
# Architecture: API Gateway (REST) -> Lambda -> S3 (images) + DynamoDB (metadata)
# No VPC / security groups required; all traffic flows through API Gateway.
###############################################################################

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known provider metadata lookups only (no pre-existing infra).
data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Project   = "cat-picture-service"
    ManagedBy = "terraform"
  }

  lambda_zip_path = "${path.module}/cat_service_lambda.zip"

  # Inline Lambda source. The handler routes on the API Gateway proxy event's
  # httpMethod + path to serve both upload (POST /cats) and random-fetch
  # (GET /cats/random) operations.
  lambda_code = <<-PYTHON
    import base64
    import json
    import os
    import random
    import time
    import uuid

    import boto3

    BUCKET_NAME = os.environ["CAT_PICTURES_BUCKET"]
    TABLE_NAME = os.environ["CAT_METADATA_TABLE"]

    s3_client = boto3.client("s3")
    cat_table = boto3.resource("dynamodb").Table(TABLE_NAME)


    def build_response(status_code, body, headers=None, is_base64_encoded=False):
        return {
            "statusCode": status_code,
            "headers": headers or {"Content-Type": "application/json"},
            "isBase64Encoded": is_base64_encoded,
            "body": body,
        }


    def json_response(status_code, payload):
        return build_response(status_code, json.dumps(payload))


    def request_content_type(event):
        headers = event.get("headers") or {}
        for name, value in headers.items():
            if str(name).lower() == "content-type" and value:
                candidate = str(value)
                if candidate.lower().startswith("image/"):
                    return candidate
        return "image/jpeg"


    def extract_image_bytes(event):
        body = event.get("body") or ""
        if not body:
            raise ValueError("empty request body")
        if event.get("isBase64Encoded"):
            decoded = base64.b64decode(body)
            try:
                body = decoded.decode("utf-8")
            except UnicodeDecodeError:
                return decoded
        return base64.b64decode(body)


    def upload_cat(event):
        try:
            image_bytes = extract_image_bytes(event)
        except (ValueError, TypeError):
            return json_response(
                400,
                {"message": "Request body must contain a base64-encoded cat picture."},
            )
        if not image_bytes:
            return json_response(400, {"message": "Request body must not be empty."})

        image_id = str(uuid.uuid4())
        s3_key = f"cat-pictures/{image_id}"
        content_type = request_content_type(event)

        s3_client.put_object(
            Bucket=BUCKET_NAME,
            Key=s3_key,
            Body=image_bytes,
            ContentType=content_type,
        )
        cat_table.put_item(
            Item={
                "ImageId": image_id,
                "S3Key": s3_key,
                "ContentType": content_type,
                "UploadedAt": int(time.time()),
            }
        )
        return json_response(201, {"imageId": image_id, "s3Key": s3_key})


    def random_cat(event):
        items = []
        scan_kwargs = {"ProjectionExpression": "ImageId, S3Key, ContentType"}
        while True:
            result = cat_table.scan(**scan_kwargs)
            items.extend(result.get("Items", []))
            last_evaluated_key = result.get("LastEvaluatedKey")
            if not last_evaluated_key:
                break
            scan_kwargs["ExclusiveStartKey"] = last_evaluated_key

        if not items:
            return json_response(
                404,
                {"message": "No cat pictures available yet. Upload one with POST /cats."},
            )

        chosen = random.choice(items)
        presigned_url = s3_client.generate_presigned_url(
            "get_object",
            Params={"Bucket": BUCKET_NAME, "Key": chosen["S3Key"]},
            ExpiresIn=300,
        )
        return json_response(
            200,
            {
                "imageId": chosen["ImageId"],
                "s3Key": chosen["S3Key"],
                "contentType": chosen.get("ContentType", "image/jpeg"),
                "imageUrl": presigned_url,
            },
        )


    def handler(event, context):
        http_method = (event.get("httpMethod") or "").upper()
        path = event.get("path") or ""
        route = f"{http_method} {path}"

        if route == "POST /cats":
            return upload_cat(event)
        if route == "GET /cats/random":
            return random_cat(event)
        return json_response(404, {"message": f"Unsupported route: {route}"})
  PYTHON
}

###############################################################################
# Lambda deployment package (built locally from the inline source above)
###############################################################################

data "archive_file" "cat_service" {
  type        = "zip"
  output_path = local.lambda_zip_path

  source {
    content  = local.lambda_code
    filename = "main.py"
  }
}

###############################################################################
# IAM: Lambda execution role (trust policy + managed + inline least-privilege)
###############################################################################

resource "aws_iam_role" "cat_service_exec" {
  name = "cat-service-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "cat-service-exec" })
}

resource "aws_iam_role_policy_attachment" "cat_service_basic_execution" {
  role       = aws_iam_role.cat_service_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "cat_service_s3_dynamodb" {
  name = "cat-service-s3-dynamodb"
  role = aws_iam_role.cat_service_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadAndWriteCatPictureObjects"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*",
        ]
      },
      {
        Sid    = "ReadWriteCatMetadata"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Scan",
        ]
        Resource = aws_dynamodb_table.cat_metadata.arn
      }
    ]
  })
}

###############################################################################
# IAM + account setting: allow API Gateway to publish metrics/logs to CloudWatch
###############################################################################

resource "aws_iam_role" "api_gateway_cloudwatch" {
  name = "cat-api-cloudwatch"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "cat-api-cloudwatch" })
}

resource "aws_iam_role_policy_attachment" "api_gateway_cloudwatch_push" {
  role       = aws_iam_role.api_gateway_cloudwatch.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonAPIGatewayPushToCloudWatchLogs"
}

resource "aws_api_gateway_account" "cat_api" {
  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch.arn

  depends_on = [aws_iam_role_policy_attachment.api_gateway_cloudwatch_push]
}

###############################################################################
# S3: cat picture storage (private, encrypted, versioned, TLS-only)
###############################################################################

resource "aws_s3_bucket" "cat_pictures" {
  bucket = "${data.aws_caller_identity.current.account_id}-cat-pictures"

  tags = merge(local.common_tags, { Name = "cat-pictures" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# Images are only ever served through the Lambda function (presigned URLs);
# this policy additionally denies any request not made over TLS.
resource "aws_s3_bucket_policy" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.cat_pictures]
}

###############################################################################
# DynamoDB: cat image metadata (ImageId -> S3 key) for random selection
###############################################################################

resource "aws_dynamodb_table" "cat_metadata" {
  name         = "cat-metadata"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "ImageId"

  attribute {
    name = "ImageId"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "cat-metadata" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Lambda: cat picture service (upload + random retrieval)
###############################################################################

resource "aws_lambda_function" "cat_service" {
  function_name = "cat-service"
  description   = "Handles cat picture uploads (POST /cats) and random retrieval (GET /cats/random)."
  role          = aws_iam_role.cat_service_exec.arn
  runtime       = "python3.12"
  handler       = "main.handler"
  timeout       = 30
  memory_size   = 256

  filename         = data.archive_file.cat_service.output_path
  source_code_hash = data.archive_file.cat_service.output_base64sha256

  environment {
    variables = {
      CAT_PICTURES_BUCKET = aws_s3_bucket.cat_pictures.bucket
      CAT_METADATA_TABLE  = aws_dynamodb_table.cat_metadata.name
    }
  }

  tags = merge(local.common_tags, { Name = "cat-service" })

  depends_on = [
    aws_iam_role_policy_attachment.cat_service_basic_execution,
    aws_iam_role_policy.cat_service_s3_dynamodb,
  ]
}

resource "aws_lambda_permission" "apigw_invoke" {
  statement_id  = "AllowExecutionFromAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cat_service.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_api.execution_arn}/*/*/cats*"
}

###############################################################################
# API Gateway: public REST API (/cats POST, /cats/random GET)
###############################################################################

resource "aws_api_gateway_rest_api" "cat_api" {
  name        = "cat-api"
  description = "Public HTTPS entrypoint for uploading cat pictures and fetching random cat pictures."

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = merge(local.common_tags, { Name = "cat-api" })
}

resource "aws_api_gateway_resource" "cats" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  parent_id   = aws_api_gateway_rest_api.cat_api.root_resource_id
  path_part   = "cats"
}

resource "aws_api_gateway_resource" "random" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  parent_id   = aws_api_gateway_resource.cats.id
  path_part   = "random"
}

resource "aws_api_gateway_method" "cats_post" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  resource_id   = aws_api_gateway_resource.cats.id
  http_method   = "POST"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "random_get" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  resource_id   = aws_api_gateway_resource.random.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "cats_post" {
  rest_api_id             = aws_api_gateway_rest_api.cat_api.id
  resource_id             = aws_api_gateway_resource.cats.id
  http_method             = aws_api_gateway_method.cats_post.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_service.arn}/invocations"
}

resource "aws_api_gateway_integration" "random_get" {
  rest_api_id             = aws_api_gateway_rest_api.cat_api.id
  resource_id             = aws_api_gateway_resource.random.id
  http_method             = aws_api_gateway_method.random_get.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.name}:lambda:path/2015-03-31/functions/${aws_lambda_function.cat_service.arn}/invocations"
}

resource "aws_api_gateway_deployment" "prod" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_method.cats_post,
      aws_api_gateway_integration.cats_post,
      aws_api_gateway_method.random_get,
      aws_api_gateway_integration.random_get,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.cats_post,
    aws_api_gateway_integration.cats_post,
    aws_api_gateway_method.random_get,
    aws_api_gateway_integration.random_get,
    aws_lambda_permission.apigw_invoke,
  ]
}

resource "aws_api_gateway_stage" "prod" {
  rest_api_id   = aws_api_gateway_rest_api.cat_api.id
  deployment_id = aws_api_gateway_deployment.prod.id
  stage_name    = "prod"
  description   = "Production stage for the cat picture service."

  tags = merge(local.common_tags, { Name = "cat-api-prod" })
}

# Stage-level metrics and throttling (applies to every method on the stage) to
# limit abuse of this public API.
resource "aws_api_gateway_method_settings" "prod_all" {
  rest_api_id = aws_api_gateway_rest_api.cat_api.id
  stage_name  = aws_api_gateway_stage.prod.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    throttling_burst_limit = 100
    throttling_rate_limit  = 50
  }

  depends_on = [aws_api_gateway_account.cat_api]
}

###############################################################################
# Outputs
###############################################################################

output "api_invoke_url" {
  description = "Base invoke URL of the prod stage of the cat picture API."
  value       = aws_api_gateway_stage.prod.invoke_url
}

output "upload_cat_picture_url" {
  description = "Full URL for uploading a base64-encoded cat picture (POST)."
  value       = "${aws_api_gateway_stage.prod.invoke_url}/cats"
}

output "random_cat_picture_url" {
  description = "Full URL for retrieving a random cat picture (GET)."
  value       = "${aws_api_gateway_stage.prod.invoke_url}/cats/random"
}

output "cat_pictures_bucket_name" {
  description = "Name of the S3 bucket storing cat pictures."
  value       = aws_s3_bucket.cat_pictures.bucket
}

output "cat_metadata_table_name" {
  description = "Name of the DynamoDB table storing cat picture metadata."
  value       = aws_dynamodb_table.cat_metadata.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lambda_runtime = "python3.12"
  lambda_handler = "lambda_function.lambda_handler"
  common_tags = {
    Project   = "caas"
    ManagedBy = "terraform"
  }
}

resource "random_id" "cat_pictures_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# Lambda deployment packages (built inline, no pre-existing artifacts)
# -----------------------------------------------------------------------------

data "archive_file" "caas_get_zip" {
  type        = "zip"
  output_path = "${path.module}/build/caas_get_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<PYTHON
import base64
import json
import os

import boto3

s3 = boto3.client("s3")
dynamodb = boto3.resource("dynamodb")

bucket_name = os.environ["BUCKET_NAME"]
table_name = os.environ["TABLE_NAME"]


def _response(status_code, payload):
    return {
        "statusCode": status_code,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(payload),
    }


def lambda_handler(event, context):
    try:
        params = event.get("queryStringParameters") or {}
        name = params.get("name")
        if not name:
            return _response(400, {"error": "Query parameter 'name' is required."})

        item = dynamodb.Table(table_name).get_item(Key={"name": name}).get("Item")
        if item is None:
            return _response(404, {"error": "Cat '%s' not found." % name})

        image_key = item.get("image_key", "%s.jpg" % name)
        image = s3.get_object(Bucket=bucket_name, Key=image_key)
        image_body = image["Body"].read()

        return {
            "statusCode": 200,
            "headers": {"Content-Type": image.get("ContentType", "application/octet-stream")},
            "isBase64Encoded": True,
            "body": base64.b64encode(image_body).decode("utf-8"),
        }
    except Exception as exc:
        return _response(500, {"error": str(exc)})
PYTHON
  }
}

data "archive_file" "caas_put_zip" {
  type        = "zip"
  output_path = "${path.module}/build/caas_put_lambda.zip"

  source {
    filename = "lambda_function.py"
    content  = <<PYTHON
import base64
import json
import os

import boto3

s3 = boto3.client("s3")
dynamodb = boto3.resource("dynamodb")

bucket_name = os.environ["BUCKET_NAME"]
table_name = os.environ["TABLE_NAME"]


def _response(status_code, payload):
    return {
        "statusCode": status_code,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(payload),
    }


def lambda_handler(event, context):
    try:
        raw_body = event.get("body") or "{}"
        if event.get("isBase64Encoded"):
            raw_body = base64.b64decode(raw_body).decode("utf-8")
        payload = json.loads(raw_body)

        name = payload.get("name")
        if not name:
            return _response(400, {"error": "Request body must include a 'name' attribute."})

        image_key = "%s.jpg" % name
        image_base64 = payload.get("image_base64")
        if image_base64:
            s3.put_object(
                Bucket=bucket_name,
                Key=image_key,
                Body=base64.b64decode(image_base64),
                ContentType=payload.get("content_type", "image/jpeg"),
            )

        dynamodb.Table(table_name).put_item(
            Item={
                "name": name,
                "image_key": image_key,
                "description": payload.get("description", ""),
            }
        )

        return _response(
            200,
            {"message": "Cat '%s' stored successfully." % name, "image_key": image_key},
        )
    except Exception as exc:
        return _response(500, {"error": str(exc)})
PYTHON
  }
}

# -----------------------------------------------------------------------------
# IAM (shared Lambda execution role + least-privilege inline policies)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "lambda_execution_role" {
  name = "caas-lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "caas_get_lambda_access" {
  name = "caas-get-lambda-least-privilege"
  role = aws_iam_role.lambda_execution_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadCatPictures"
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      },
      {
        Sid    = "ReadCatRecord"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem"
        ]
        Resource = aws_dynamodb_table.cats.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "caas_put_lambda_access" {
  name = "caas-put-lambda-least-privilege"
  role = aws_iam_role.lambda_execution_role.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "WriteCatPictures"
        Effect = "Allow"
        Action = [
          "s3:PutObject"
        ]
        Resource = [
          aws_s3_bucket.cat_pictures.arn,
          "${aws_s3_bucket.cat_pictures.arn}/*"
        ]
      },
      {
        Sid    = "WriteCatRecord"
        Effect = "Allow"
        Action = [
          "dynamodb:PutItem"
        ]
        Resource = aws_dynamodb_table.cats.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Storage: S3 bucket for cat pictures
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cat_pictures" {
  bucket = "caas-cat-pictures-${random_id.cat_pictures_suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_versioning" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "cat_pictures" {
  bucket = aws_s3_bucket.cat_pictures.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Storage: DynamoDB table for cat records
# -----------------------------------------------------------------------------

resource "aws_dynamodb_table" "cats" {
  name         = "caas_cats"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "name"

  attribute {
    name = "name"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Lambda functions
# -----------------------------------------------------------------------------

resource "aws_lambda_function" "caas_get_lambda" {
  function_name = "caas-get-cat"
  description   = "Returns a cat picture and its record from S3 and DynamoDB."
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = local.lambda_handler
  runtime       = local.lambda_runtime
  timeout       = 10

  filename         = data.archive_file.caas_get_zip.output_path
  source_code_hash = data.archive_file.caas_get_zip.output_base64sha256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
      TABLE_NAME  = aws_dynamodb_table.cats.name
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.caas_get_lambda_access
  ]

  tags = local.common_tags
}

resource "aws_lambda_function" "caas_put_lambda" {
  function_name = "caas-put-cat"
  description   = "Stores a cat picture in S3 and its record in DynamoDB."
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = local.lambda_handler
  runtime       = local.lambda_runtime
  timeout       = 10

  filename         = data.archive_file.caas_put_zip.output_path
  source_code_hash = data.archive_file.caas_put_zip.output_base64sha256

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures.id
      TABLE_NAME  = aws_dynamodb_table.cats.name
    }
  }

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
    aws_iam_role_policy.caas_put_lambda_access
  ]

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# API Gateway REST API
# -----------------------------------------------------------------------------

resource "aws_api_gateway_rest_api" "caas" {
  name = "caas"

  binary_media_types = ["image/jpeg"]

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "caas_cat" {
  rest_api_id = aws_api_gateway_rest_api.caas.id
  parent_id   = aws_api_gateway_rest_api.caas.root_resource_id
  path_part   = "cat"
}

resource "aws_api_gateway_method" "caas_get" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_method" "caas_put" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  resource_id   = aws_api_gateway_resource.caas_cat.id
  http_method   = "PUT"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "caas_get_integration" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_get.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.caas_get_lambda.invoke_arn
}

resource "aws_api_gateway_integration" "caas_put_integration" {
  rest_api_id             = aws_api_gateway_rest_api.caas.id
  resource_id             = aws_api_gateway_resource.caas_cat.id
  http_method             = aws_api_gateway_method.caas_put.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.caas_put_lambda.invoke_arn
}

resource "aws_lambda_permission" "caas_get_lambda_permission" {
  statement_id  = "AllowAPIGatewayInvokeGetCat"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.caas_get_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.caas.execution_arn}/*/GET/cat"
}

resource "aws_lambda_permission" "caas_put_lambda_permission" {
  statement_id  = "AllowAPIGatewayInvokePutCat"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.caas_put_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.caas.execution_arn}/*/PUT/cat"
}

resource "aws_api_gateway_deployment" "caas_deployment" {
  rest_api_id = aws_api_gateway_rest_api.caas.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.caas_cat.id,
      aws_api_gateway_method.caas_get.id,
      aws_api_gateway_method.caas_put.id,
      aws_api_gateway_integration.caas_get_integration.id,
      aws_api_gateway_integration.caas_put_integration.id
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.caas_get_integration,
    aws_api_gateway_integration.caas_put_integration
  ]
}

resource "aws_api_gateway_stage" "caas_stage" {
  rest_api_id   = aws_api_gateway_rest_api.caas.id
  deployment_id = aws_api_gateway_deployment.caas_deployment.id
  stage_name    = "prod"

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

data "aws_region" "current" {}

output "caas_invoke_url" {
  description = "Invoke URL for the /cat resource on the deployed prod stage."
  value       = "https://${aws_api_gateway_rest_api.caas.id}.execute-api.${data.aws_region.current.name}.amazonaws.com/${aws_api_gateway_stage.caas_stage.stage_name}/cat"
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "daily-backup"
  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ec2" {
  name        = "${local.name_prefix}-ec2-sg"
  description = "Security group for the backup target EC2 instance (outbound traffic only)"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-sg"
  })
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_instance" "web" {
  ami                    = data.aws_ami.al2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.ec2.id]

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "backup-target-web-instance"
  })
}

resource "aws_iam_role" "backup_role" {
  name = "${local.name_prefix}-backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-role"
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

resource "aws_kms_key" "backup_key" {
  description             = "KMS key encrypting the daily-backup AWS Backup vault"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-key"
  })
}

resource "aws_backup_vault" "backup_vault" {
  name        = "${local.name_prefix}-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vault"
  })
}

resource "aws_backup_plan" "daily_midnight" {
  name = "${local.name_prefix}-plan"

  rule {
    rule_name         = "daily-midnight"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)"
    start_window      = 60
    completion_window = 360

    lifecycle {
      delete_after = 30
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-plan"
  })
}

resource "aws_backup_selection" "ec2_daily_backup" {
  name         = "${local.name_prefix}-ec2-selection"
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.daily_midnight.id

  resources = [
    aws_instance.web.arn
  ]

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restore
  ]
}

output "instance_id" {
  description = "ID of the EC2 instance registered as the daily backup target"
  value       = aws_instance.web.id
}

output "backup_vault_arn" {
  description = "ARN of the encrypted AWS Backup vault receiving the daily backups"
  value       = aws_backup_vault.backup_vault.arn
}

output "backup_plan_id" {
  description = "ID of the daily-midnight AWS Backup plan"
  value       = aws_backup_plan.daily_midnight.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "ec2-daily-backup"
  environment = "dev"

  common_tags = {
    Project     = local.name_prefix
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Data sources (pure static lookups only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security group (egress-only; no inbound ports required for backup workflow)
# ---------------------------------------------------------------------------

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Egress-only security group for the backup-managed EC2 instance"
  vpc_id      = aws_vpc.main.id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

# ---------------------------------------------------------------------------
# EC2 instance
# ---------------------------------------------------------------------------

resource "aws_instance" "app" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_type           = "gp3"
    volume_size           = 20
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name        = "${local.name_prefix}-app"
    Environment = local.environment
    Backup      = "daily"
  })
}

# ---------------------------------------------------------------------------
# KMS key and encrypted backup vault
# ---------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the daily EC2 backup vault"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-key"
  })
}

resource "aws_kms_alias" "backup" {
  name          = "alias/${local.name_prefix}-backup"
  target_key_id = aws_kms_key.backup.key_id
}

resource "aws_backup_vault" "main" {
  name        = "${local.name_prefix}-vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vault"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role for AWS Backup
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "backup" {
  name               = "${local.name_prefix}-backup-role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backup-role"
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# ---------------------------------------------------------------------------
# AWS Backup plan and selection
# ---------------------------------------------------------------------------

resource "aws_backup_plan" "daily" {
  name = "${local.name_prefix}-daily-plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"
    start_window      = 60
    completion_window = 360

    lifecycle {
      delete_after = 35
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-daily-plan"
  })
}

resource "aws_backup_selection" "ec2_daily" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "ec2_daily"
  plan_id      = aws_backup_plan.daily.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "daily"
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the EC2 instance protected by the daily backup plan"
  value       = aws_instance.app.id
}

output "backup_vault_arn" {
  description = "ARN of the encrypted backup vault"
  value       = aws_backup_vault.main.arn
}

output "backup_plan_id" {
  description = "ID of the daily midnight backup plan"
  value       = aws_backup_plan.daily.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resources as a tag."
  type        = string
  default     = "production"
}

variable "management_cidr" {
  description = "Single management CIDR permitted to reach the EC2 instance on TCP/22."
  type        = string
  default     = "10.0.0.0/8"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "backup_vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "backup_internet_gateway"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name        = "backup_public_subnet"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "backup_public_route_table"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "main" {
  key_name   = "backup_ec2_key_pair"
  public_key = tls_private_key.main.public_key_openssh

  tags = {
    Name        = "backup_ec2_key_pair"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name        = "backup/ec2/ssh-private-key"
  description = "SSH private key material for the backup EC2 instance key pair."

  tags = {
    Name        = "backup_ssh_private_key"
    Environment = var.environment
  }
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

resource "aws_security_group" "instance" {
  name        = "backup_instance_sg"
  description = "Restricts inbound access to the backed-up EC2 instance."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the management CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.management_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "backup_instance_security_group"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2" {
  name               = "backup_ec2_instance_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = {
    Name        = "backup_ec2_instance_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "backup_ec2_instance_profile"
  role = aws_iam_role.ec2.name
}

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the AWS Backup vault."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = {
    Name        = "backup_vault_kms_key"
    Environment = var.environment
  }
}

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = "backup_service_role"
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = {
    Name        = "backup_service_role"
    Environment = var.environment
  }
}

resource "aws_iam_role_policy_attachment" "backup_backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

data "aws_iam_policy_document" "backup_kms_access" {
  statement {
    sid    = "AllowBackupKmsOperationsOnVaultKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey"
    ]

    resources = [aws_kms_key.backup.arn]
  }
}

resource "aws_iam_role_policy" "backup_kms_access" {
  name   = "backup_kms_access"
  role   = aws_iam_role.backup.name
  policy = data.aws_iam_policy_document.backup_kms_access.json
}

resource "aws_backup_vault" "main" {
  name        = "backup_vault_daily"
  kms_key_arn = aws_kms_key.backup.arn

  tags = {
    Name        = "backup_vault_daily"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "daily" {
  name = "daily_midnight_backup_plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"
    start_window      = 60
    completion_window = 120

    lifecycle {
      delete_after = 7
    }
  }

  tags = {
    Name        = "daily_midnight_backup_plan"
    Environment = var.environment
  }
}

resource "aws_backup_selection" "backup_enabled" {
  iam_role_arn = aws_iam_role.backup.arn
  name         = "backup_enabled_selection"
  plan_id      = aws_backup_plan.daily.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "BackupEnabled"
    value = "true"
  }
}

resource "aws_instance" "backup_instance" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  key_name                    = aws_key_pair.main.key_name
  associate_public_ip_address = true
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 20
    volume_type = "gp3"
    encrypted   = true
  }

  tags = {
    Name          = "backup_ec2_instance"
    Environment   = var.environment
    BackupEnabled = "true"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "trusted_ssh_cidr" {
  description = "CIDR block permitted to reach TCP/22 (SSH) on the EC2 instance. Must be a restricted, trusted range."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.trusted_ssh_cidr != "0.0.0.0/0"
    error_message = "SSH ingress must be restricted to a trusted CIDR; 0.0.0.0/0 is not allowed."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  common_tags = {
    Project     = "ec2-backup"
    Environment = "sandbox"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (pure static / well-known lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023_x86_64" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# -----------------------------------------------------------------------------
# Networking (greenfield: all prerequisites created here)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "main-public-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "main-public-route-table"
  })
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# SSH key pair: apply-time generation (no file dependency)
# -----------------------------------------------------------------------------

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "main" {
  key_name   = "main_ec2_key"
  public_key = tls_private_key.main.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "main-ec2-key-pair"
  })
}

# -----------------------------------------------------------------------------
# EC2 instance and security group
# -----------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "main-ec2-ssh-sg"
  description = "Restrict ingress to SSH from a trusted CIDR; allow all egress"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from trusted CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.trusted_ssh_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "main-ec2-ssh-sg"
  })
}

resource "aws_instance" "main" {
  ami                    = data.aws_ami.al2023_x86_64.id
  instance_type          = "t2.micro"
  key_name               = aws_key_pair.main.key_name
  subnet_id              = aws_subnet.main.id
  vpc_security_group_ids = [aws_security_group.main.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  tags = merge(local.common_tags, {
    Name = "backup-ec2-instance"
  })
}

# -----------------------------------------------------------------------------
# AWS Backup: KMS key, vault, plan, selection IAM role
# -----------------------------------------------------------------------------

resource "aws_kms_key" "backup" {
  description             = "KMS key used to encrypt the AWS Backup vault and SSH key secret"
  deletion_window_in_days = 7
  is_enabled              = true
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_backup_vault" "main" {
  name        = "main_backup_vault"
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_plan" "daily" {
  name = "daily_midnight_backup_plan"

  rule {
    rule_name         = "daily_midnight"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 0 * * ? *)"

    lifecycle {
      delete_after = 7
    }
  }

  advanced_backup_setting {
    backup_options = {
      resource_type = "EC2"
    }
    resource_type = "EC2"
  }

  tags = local.common_tags
}

resource "aws_iam_role" "backup_selection" {
  name = "backup_selection_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "backup_kms_access" {
  name = "backup-kms-access"
  role = aws_iam_role.backup_selection.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowBackupVaultKmsUsage"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.backup.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_selection" {
  role       = aws_iam_role.backup_selection.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# NOTE: aws_backup_selection does not support tagging at the provider/API level,
# so no tags argument is applied to this resource.

resource "aws_backup_selection" "ec2" {
  name         = "ec2_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup_selection.arn
  resources    = [aws_instance.main.arn]
}

# -----------------------------------------------------------------------------
# SSH private key persistence (Secrets Manager, encrypted with the CMK)
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "ssh_private_key" {
  name                    = "ec2/main-ssh-private-key"
  description             = "Private key for the main EC2 key pair (apply-time generated)"
  kms_key_id              = aws_kms_key.backup.arn
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "ssh_private_key" {
  secret_id     = aws_secretsmanager_secret.ssh_private_key.id
  secret_string = tls_private_key.main.private_key_pem
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

locals {
  common_tags = {
    Project     = "daily-task-scheduler"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Lambda function code - packaged inline, no external S3 artifact required
# ---------------------------------------------------------------------------
data "archive_file" "daily_task" {
  type        = "zip"
  output_path = "${path.module}/build/daily_task_lambda.zip"

  source {
    filename = "main.py"
    content  = <<-EOF
      import json
      import logging

      logger = logging.getLogger()
      logger.setLevel(logging.INFO)


      def handler(event, context):
          logger.info("Daily task invoked by EventBridge schedule")
          logger.info("Received event: %s", json.dumps(event))

          # Replace the body of this handler with the real daily workload.
          result = {"message": "daily task executed successfully"}

          logger.info("Daily task result: %s", json.dumps(result))
          return {"statusCode": 200, "body": json.dumps(result)}
    EOF
  }
}

# ---------------------------------------------------------------------------
# IAM: Lambda execution role trusting only the Lambda service principal
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "daily-task-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Dedicated, explicitly managed log group with bounded retention
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "daily_task" {
  name              = "/aws/lambda/daily-task"
  retention_in_days = 14

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Least-privilege inline logging policy scoped to the dedicated log group
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "lambda_logs" {
  statement {
    sid    = "WriteLambdaLogsToDedicatedLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.daily_task.arn}:*"]
  }
}

resource "aws_iam_role_policy" "lambda_logs" {
  name   = "daily-task-lambda-logs"
  role   = aws_iam_role.lambda_exec.id
  policy = data.aws_iam_policy_document.lambda_logs.json
}

# ---------------------------------------------------------------------------
# Lambda function
# ---------------------------------------------------------------------------
resource "aws_lambda_function" "daily_task" {
  function_name = "daily-task"
  description   = "Runs the daily scheduled task triggered by EventBridge at 07:00 UTC."
  role          = aws_iam_role.lambda_exec.arn

  filename         = data.archive_file.daily_task.output_path
  source_code_hash = data.archive_file.daily_task.output_base64sha256

  runtime     = "python3.12"
  handler     = "main.handler"
  timeout     = 30
  memory_size = 128

  tags = local.common_tags

  depends_on = [
    aws_iam_role_policy.lambda_logs,
    aws_cloudwatch_log_group.daily_task,
  ]
}

# ---------------------------------------------------------------------------
# Permit EventBridge to invoke the Lambda (scoped to the schedule rule ARN)
# ---------------------------------------------------------------------------
resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowEventBridgeDailyScheduleInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_task.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_code_run.arn
}

# ---------------------------------------------------------------------------
# EventBridge schedule: fires once every day at 07:00 UTC
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_event_rule" "daily_code_run" {
  name                = "daily-code-run-0700-utc"
  description         = "Triggers the daily task Lambda once every day at 07:00 UTC."
  state               = "ENABLED"
  schedule_expression = "cron(0 7 * * ? *)"

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Dead-letter queue for EventBridge delivery failures
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "daily_task_dlq" {
  name                      = "daily-task-dlq"
  message_retention_seconds = 1209600
  sqs_managed_sse_enabled   = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "daily_task_dlq" {
  statement {
    sid       = "AllowEventBridgeToSendFailedEvents"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.daily_task_dlq.arn]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }

    condition {
      test     = "ArnEquals"
      variable = "aws:SourceArn"
      values   = [aws_cloudwatch_event_rule.daily_code_run.arn]
    }
  }
}

resource "aws_sqs_queue_policy" "daily_task_dlq" {
  queue_url = aws_sqs_queue.daily_task_dlq.id
  policy    = data.aws_iam_policy_document.daily_task_dlq.json
}

# ---------------------------------------------------------------------------
# EventBridge target wiring with retry and dead-letter handling
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_event_target" "daily_code_run_lambda" {
  rule      = aws_cloudwatch_event_rule.daily_code_run.name
  target_id = "daily-code-run-lambda"
  arn       = aws_lambda_function.daily_task.arn

  retry_policy {
    maximum_event_age_in_seconds = 3600
    maximum_retry_attempts       = 2
  }

  dead_letter_config {
    arn = aws_sqs_queue.daily_task_dlq.arn
  }

  depends_on = [aws_lambda_permission.allow_eventbridge]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags applied to every taggable resource in this configuration."
  type        = map(string)
  default = {
    Environment = "prod"
    ManagedBy   = "terraform"
  }
}

locals {
  function_name  = "daily-job-7am-utc"
  rule_name      = "daily-job-7am-utc-schedule"
  target_id      = "daily-job-7am-utc-target"
  log_group_name = "/aws/lambda/${local.function_name}"
}

# Static provider/account metadata used to build least-privilege IAM resource ARNs.
data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Lambda source code and deployment package
# ---------------------------------------------------------------------------

resource "local_file" "lambda_handler" {
  filename = "${path.module}/src/main.py"
  content = <<-EOT
    """Daily scheduled job invoked by EventBridge every day at 07:00 UTC."""
    import json
    import logging
    import os

    LOG_LEVEL = os.environ.get("LOG_LEVEL", "INFO")
    logging.basicConfig(level=LOG_LEVEL)
    logger = logging.getLogger(__name__)


    def lambda_handler(event, context):
        """Entry point executed once per day at 07:00 UTC."""
        logger.info(
            "Daily job started (job_name=%s)",
            os.environ.get("JOB_NAME", "daily-job"),
        )
        logger.info("Received event: %s", json.dumps(event, default=str))

        # Placeholder for the actual daily workload.
        logger.info("Daily job finished successfully")

        return {
            "statusCode": 200,
            "body": json.dumps({"message": "daily job completed"}),
        }
    EOT
  file_permission = "0644"
}

resource "archive_file" "daily_job_zip" {
  type        = "zip"
  source_file = local_file.lambda_handler.filename
  output_path = "${path.module}/build/${local.function_name}.zip"
}

# ---------------------------------------------------------------------------
# IAM: execution role with least-privilege CloudWatch Logs permissions
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "daily_job_exec" {
  name               = "${local.function_name}-exec"
  description        = "Execution role for the ${local.function_name} Lambda function."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = merge(var.tags, { Name = "${local.function_name}-exec" })
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}",
      "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:${local.log_group_name}:*",
    ]
  }
}

resource "aws_iam_role_policy" "daily_job_logging_inline" {
  name   = "${local.function_name}-inline-logging"
  role   = aws_iam_role.daily_job_exec.id
  policy = data.aws_iam_policy_document.lambda_logging.json
}

resource "aws_iam_policy" "daily_job_logging" {
  name        = "${local.function_name}-logging"
  description = "Least-privilege CloudWatch Logs permissions for the daily job Lambda."
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = merge(var.tags, { Name = "${local.function_name}-logging" })
}

resource "aws_iam_role_policy_attachment" "daily_job_logging" {
  role       = aws_iam_role.daily_job_exec.name
  policy_arn = aws_iam_policy.daily_job_logging.arn
}

# ---------------------------------------------------------------------------
# CloudWatch Logs group created ahead of the function so Lambda never
# auto-creates an unmanaged log group.
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "daily_job" {
  name              = local.log_group_name
  retention_in_days = 14

  tags = merge(var.tags, { Name = local.log_group_name })
}

# ---------------------------------------------------------------------------
# Lambda function
# ---------------------------------------------------------------------------

resource "aws_lambda_function" "daily_job" {
  function_name    = local.function_name
  description      = "Daily job triggered by EventBridge every day at 07:00 UTC."
  role             = aws_iam_role.daily_job_exec.arn
  handler          = "main.lambda_handler"
  runtime          = "python3.12"
  filename         = archive_file.daily_job_zip.output_path
  source_code_hash = archive_file.daily_job_zip.output_base64sha256
  memory_size      = 128
  timeout          = 60

  environment {
    variables = {
      LOG_LEVEL = "INFO"
      JOB_NAME  = "daily-7am-utc-job"
    }
  }

  depends_on = [
    aws_cloudwatch_log_group.daily_job,
    aws_iam_role_policy.daily_job_logging_inline,
    aws_iam_role_policy_attachment.daily_job_logging,
  ]

  tags = merge(var.tags, { Name = local.function_name })
}

# ---------------------------------------------------------------------------
# EventBridge daily 07:00 UTC schedule
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "daily_schedule" {
  name                = local.rule_name
  description         = "Fires the daily job every day at 07:00 UTC."
  schedule_expression = "cron(0 7 * * ? *)"
  state               = "ENABLED"

  tags = merge(var.tags, { Name = local.rule_name })
}

resource "aws_cloudwatch_event_target" "daily_job" {
  rule      = aws_cloudwatch_event_rule.daily_schedule.name
  target_id = local.target_id
  arn       = aws_lambda_function.daily_job.arn
}

resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowEventBridgeInvokeDailyJob"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "environment must be a non-empty string."
  }
}

locals {
  # Single source of truth for the Lambda function name so the function and
  # its pre-created CloudWatch log group always share the same name.
  lambda_function_name = "daily-scheduled-job-${var.environment}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Purpose     = "daily-scheduled-job"
  }
}

data "aws_partition" "current" {}

# Self-contained function code: a minimal python3.12 handler that logs the
# incoming event so every daily run is verifiable in CloudWatch Logs.
data "archive_file" "lambda_zip" {
  type        = "zip"
  output_path = "${path.module}/daily_job_lambda.zip"

  source_content = <<-EOT
    import json


    def lambda_handler(event, context):
        """Daily scheduled job handler, triggered every day at 07:00 UTC by EventBridge."""
        print("Daily job started: triggered by EventBridge schedule cron(0 7 * * ? *).")
        print("Received event: " + json.dumps(event, default=str))
        print("Daily job finished successfully.")
        return {
            "statusCode": 200,
            "body": json.dumps({"message": "daily job completed successfully"}),
        }
    EOT

  source_content_filename = "lambda_function.py"
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  name               = "daily-job-lambda-exec-${var.environment}"
  description        = "Execution role for the daily scheduled job Lambda function."
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Pre-created log group matching the Lambda function's default log location
# ("/aws/lambda/<function_name>") with a 14 day retention window.
resource "aws_cloudwatch_log_group" "lambda_logs" {
  name              = "/aws/lambda/${local.lambda_function_name}"
  retention_in_days = 14

  tags = local.common_tags
}

resource "aws_lambda_function" "daily_job" {
  function_name    = local.lambda_function_name
  description      = "Runs the daily scheduled job, triggered by EventBridge at 07:00 UTC every day."
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256
  memory_size      = 128
  timeout          = 30

  depends_on = [
    aws_cloudwatch_log_group.lambda_logs,
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]

  tags = local.common_tags
}

# Least-privilege invoke authorization, scoped to this specific rule only.
resource "aws_lambda_permission" "allow_eventbridge" {
  statement_id  = "AllowExecutionFromDailyScheduleRule"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_job.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_0700_utc.arn
}

resource "aws_cloudwatch_event_rule" "daily_0700_utc" {
  name                = "daily-0700-utc-${var.environment}"
  description         = "Triggers the daily job Lambda function every day at 07:00 UTC."
  schedule_expression = "cron(0 7 * * ? *)"
  state               = "ENABLED"

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "lambda_daily_job" {
  rule      = aws_cloudwatch_event_rule.daily_0700_utc.name
  arn       = aws_lambda_function.daily_job.arn
  target_id = "daily-job-lambda"
}

output "lambda_function_name" {
  description = "Name of the Lambda function invoked daily by the EventBridge schedule."
  value       = aws_lambda_function.daily_job.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function invoked daily by the EventBridge schedule."
  value       = aws_lambda_function.daily_job.arn
}

output "eventbridge_rule_arn" {
  description = "ARN of the EventBridge rule that schedules the daily 07:00 UTC run."
  value       = aws_cloudwatch_event_rule.daily_0700_utc.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  lambda_zip_path = "./supplement/lambda_func.zip"
}

resource "aws_iam_role" "lambda_exec" {
  name = "cron-lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "cron_target" {
  function_name    = "cron-target"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = local.lambda_zip_path
  source_code_hash = fileexists(local.lambda_zip_path) ? filebase64sha256(local.lambda_zip_path) : null
  timeout          = 10
  memory_size      = 128

  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]
}

resource "aws_cloudwatch_event_rule" "cron" {
  name                = "cron"
  description         = "Triggers the cron target Lambda every day at 07:00 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
}

resource "aws_cloudwatch_event_target" "cron_lambda" {
  rule      = aws_cloudwatch_event_rule.cron.arn
  target_id = "cron-lambda-target"
  arn       = aws_lambda_function.cron_target.arn
}

resource "aws_lambda_permission" "allow_eventbridge_cron" {
  statement_id  = "AllowExecutionFromEventBridgeCronRule"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron_target.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ----------------------------------------------------------------------------
# IAM: Lambda execution role
# ----------------------------------------------------------------------------

data "aws_iam_policy_document" "cron_lambda_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cron_lambda_exec" {
  name               = "cron-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.cron_lambda_assume_role.json
}

resource "aws_iam_role_policy" "cron_lambda_exec_logs" {
  name = "cron-lambda-logs"
  role = aws_iam_role.cron_lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CronLambdaCloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = "arn:aws:logs:*:*:log-group:/aws/lambda/cron-lambda-function:*"
      },
    ]
  })
}

# ----------------------------------------------------------------------------
# CloudWatch Logs: managed log group for the Lambda function
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "cron_lambda_logs" {
  name              = "/aws/lambda/cron-lambda-function"
  retention_in_days = 14
}

# ----------------------------------------------------------------------------
# EventBridge: schedule rule firing every day at 07:00 UTC
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "cron" {
  name                = "cron"
  description         = "Fires every day at 07:00 UTC"
  schedule_expression = "cron(0 7 * * ? *)"
}

# ----------------------------------------------------------------------------
# Lambda: scheduled function
# ----------------------------------------------------------------------------

resource "aws_lambda_function" "cron" {
  function_name = "cron-lambda-function"
  filename      = "./supplement/lambda_func.zip"
  handler       = "lambda_func.lambda_handler"
  runtime       = "python3.12"
  role          = aws_iam_role.cron_lambda_exec.arn
  timeout       = 30

  depends_on = [
    aws_iam_role_policy.cron_lambda_exec_logs,
    aws_cloudwatch_log_group.cron_lambda_logs,
  ]
}

# ----------------------------------------------------------------------------
# EventBridge target linking the schedule rule to the Lambda function,
# plus the permission allowing only this rule to invoke it
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_event_target" "cron" {
  rule      = aws_cloudwatch_event_rule.cron.id
  target_id = "cron-lambda-target"
  arn       = aws_lambda_function.cron.arn
}

resource "aws_lambda_permission" "cron" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron.arn
}

