terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources"
  type        = map(string)
  default     = {}
}

variable "geo_restriction_type" {
  description = "CloudFront geo restriction type. One of: none, whitelist, blacklist"
  type        = string
  default     = "none"

  validation {
    condition     = contains(["none", "whitelist", "blacklist"], var.geo_restriction_type)
    error_message = "geo_restriction_type must be one of: none, whitelist, blacklist."
  }
}

variable "geo_restriction_countries" {
  description = "ISO 3166-1 alpha-2 country codes for whitelisting/blacklisting. Ignored when geo_restriction_type is none."
  type        = list(string)
  default     = []
}

locals {
  s3_origin_id = "s3-video-content-origin"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

# -----------------------------------------------------------------------------
# S3 Origin Bucket (private video content)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "video_content" {
  tags = merge(local.common_tags, { Name = "video-content-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    id     = "video-media-cost-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "INTELLIGENT_TIERING"
    }

    noncurrent_version_expiration {
      noncurrent_days = 180
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

# -----------------------------------------------------------------------------
# S3 Log Bucket (CloudFront standard access logs)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudfront_logs" {
  tags = merge(local.common_tags, { Name = "cloudfront-logs-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }

  depends_on = [aws_s3_bucket_public_access_block.cloudfront_logs]
}

# -----------------------------------------------------------------------------
# CloudFront Origin Access Control (OAC)
# -----------------------------------------------------------------------------

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name                              = "video-content-oac-${var.environment}"
  description                       = "Origin Access Control for the private video content S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# -----------------------------------------------------------------------------
# CloudFront Cache Policy tuned for large video media
# -----------------------------------------------------------------------------

resource "aws_cloudfront_cache_policy" "video_streaming" {
  name        = "video-streaming-cache-${var.environment}"
  comment     = "Long-TTL cache policy for pre-compressed video media; forwards Origin header for CORS and all query strings for cache-busting/versioned URLs"
  min_ttl     = 0
  default_ttl = 86400
  max_ttl     = 31536000

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "whitelist"
      headers {
        items = ["Origin"]
      }
    }

    query_strings_config {
      query_string_behavior = "all"
    }
  }
}

# -----------------------------------------------------------------------------
# CloudFront Distribution
# -----------------------------------------------------------------------------

resource "aws_cloudfront_distribution" "video_cdn" {
  enabled         = true
  is_ipv6_enabled = true
  http_version    = "http2and3"
  comment         = "Global video streaming CDN (${var.environment})"
  price_class     = "PriceClass_All"

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id

    origin_shield {
      enabled = false
    }
  }

  default_cache_behavior {
    target_origin_id       = local.s3_origin_id
    viewer_protocol_policy = "redirect-to-https"

    allowed_methods = ["GET", "HEAD"]
    cached_methods  = ["GET", "HEAD"]

    cache_policy_id = aws_cloudfront_cache_policy.video_streaming.id

    # Video payloads are pre-compressed; no edge compression needed.
    compress = false
  }

  restrictions {
    geo_restriction {
      restriction_type = var.geo_restriction_type
      locations        = var.geo_restriction_countries
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  logging_config {
    include_cookies = false
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_regional_domain_name
    prefix          = "cloudfront-logs/"
  }

  tags = merge(local.common_tags, { Name = "video-cdn-${var.environment}" })

  depends_on = [aws_s3_bucket_ownership_controls.cloudfront_logs]
}

# -----------------------------------------------------------------------------
# Bucket Policies (least privilege, scoped to this distribution only)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "video_content_policy" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOACGetObject"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_cdn.arn
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_policy" "cloudfront_logs_policy" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontLogDelivery"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudfront_logs.arn}/cloudfront-logs/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_cdn.arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cloudfront_domain_name" {
  description = "CloudFront distribution domain name to use for video playback URLs"
  value       = aws_cloudfront_distribution.video_cdn.domain_name
}

output "cloudfront_distribution_arn" {
  description = "ARN of the CloudFront video distribution"
  value       = aws_cloudfront_distribution.video_cdn.arn
}

output "video_content_bucket_name" {
  description = "Name of the private S3 origin bucket for video assets"
  value       = aws_s3_bucket.video_content.bucket
}

output "video_content_bucket_id" {
  description = "ID of the private S3 origin bucket for video assets"
  value       = aws_s3_bucket.video_content.id
}

###############################################################################
# Video streaming platform
# Global video delivery: CloudFront (CDN) -> S3 (SSE-KMS origin, OAC) with
# Route 53 (DNS + ACM DNS validation) and KMS (media encryption).
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# us-east-1 is the only region from which an ACM certificate can be attached
# to CloudFront, so the whole stack is deployed there.
provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = "video-streaming"
      Environment = var.environment
    }
  }
}

###############################################################################
# Variables (user-controlled, all with defaults for unattended apply)
###############################################################################

variable "domain_name" {
  description = "Public domain name for the video streaming site (e.g. stream.example.com). The domain itself is assumed to be registered outside of Terraform."
  type        = string
  default     = "stream.example.com"
}

variable "environment" {
  description = "Deployment environment name applied via provider default_tags."
  type        = string
  default     = "production"
}

###############################################################################
# Data sources (pure static lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  sanitized_domain  = replace(lower(var.domain_name), ".", "-")
  video_bucket_name = "video-content-${local.sanitized_domain}"
  logs_bucket_name  = "video-content-logs-${local.sanitized_domain}"
  log_prefix        = "cloudfront-logs/${var.domain_name}"
  s3_origin_id      = "s3-video-content-origin"
}

###############################################################################
# Route 53 public hosted zone (domain registered outside Terraform)
###############################################################################

resource "aws_route53_zone" "main" {
  name    = var.domain_name
  comment = "Public hosted zone for the video streaming site"

  tags = {
    Name = "${var.domain_name}-zone"
  }
}

###############################################################################
# ACM certificate (must live in us-east-1 for CloudFront) + DNS validation
###############################################################################

resource "aws_acm_certificate" "streaming" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = {
    Name = "${var.domain_name}-certificate"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.streaming.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      type   = dvo.resource_record_type
      record = dvo.resource_record_value
    }
  }

  allow_overwrite = true
  name            = each.value.name
  records         = [each.value.record]
  ttl             = 300
  type            = each.value.type
  zone_id         = aws_route53_zone.main.zone_id
}

resource "aws_acm_certificate_validation" "streaming" {
  certificate_arn         = aws_acm_certificate.streaming.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

###############################################################################
# KMS key + alias for SSE-KMS encryption of video content
###############################################################################

resource "aws_kms_key" "video_content" {
  description             = "SSE-KMS key for the ${local.video_bucket_name} video content bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.video_content_kms.json

  tags = {
    Name = "video-content-kms-key"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "video_content" {
  name          = "alias/video-content-${local.sanitized_domain}"
  target_key_id = aws_kms_key.video_content.key_id
}

data "aws_iam_policy_document" "video_content_kms" {
  statement {
    sid    = "EnableAccountRootPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudFrontDecryptForVideoContent"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["kms:Decrypt"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:s3:arn"
      values = [
        aws_s3_bucket.video_content.arn,
        "${aws_s3_bucket.video_content.arn}/*",
      ]
    }
  }
}

###############################################################################
# Video content bucket (CloudFront origin)
###############################################################################

resource "aws_s3_bucket" "video_content" {
  bucket = local.video_bucket_name

  tags = {
    Name = local.video_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.video_content.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = 30
    }
  }

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.video_content]
}

data "aws_iam_policy_document" "video_content_bucket" {
  statement {
    sid    = "AllowCloudFrontOACGetObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["s3:GetObject"]
    resources = ["${aws_s3_bucket.video_content.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.video_content.arn,
      "${aws_s3_bucket.video_content.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id
  policy = data.aws_iam_policy_document.video_content_bucket.json
}

###############################################################################
# CloudFront access log bucket
# Note: CloudFront standard log delivery requires SSE-S3 (not SSE-KMS), so
# this bucket uses AES256, and BucketOwnerPreferred so the log delivery
# PUTs (bucket-owner-full-control) succeed.
###############################################################################

resource "aws_s3_bucket" "cloudfront_logs" {
  bucket = local.logs_bucket_name

  tags = {
    Name = local.logs_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    id     = "expire-access-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = 365
    }
  }
}

data "aws_iam_policy_document" "cloudfront_logs_bucket" {
  statement {
    sid    = "AllowCloudFrontLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudfront.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudfront_logs.arn}/${local.log_prefix}/*"]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceArn"
      values   = [aws_cloudfront_distribution.streaming.arn]
    }
  }

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.cloudfront_logs.arn,
      "${aws_s3_bucket.cloudfront_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id
  policy = data.aws_iam_policy_document.cloudfront_logs_bucket.json
}

###############################################################################
# CloudFront: OAC, custom cache policy, custom security headers policy
###############################################################################

resource "aws_cloudfront_origin_access_control" "video_content" {
  name                              = "video-content-origin-access-control"
  description                       = "SigV4-signed origin access control for the video content S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_cache_policy" "video_media" {
  name        = "video-streaming-media-cache-${var.environment}"
  comment     = "GET/HEAD caching for video media with long TTLs and selected query-string keys forwarded"
  default_ttl = 86400
  max_ttl     = 31536000
  min_ttl     = 0

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "none"
    }

    query_strings_config {
      query_string_behavior = "whitelist"

      query_strings {
        items = ["v", "version", "quality", "resolution", "bitrate"]
      }
    }

    enable_accept_encoding_gzip   = true
    enable_accept_encoding_brotli = true
  }
}

resource "aws_cloudfront_response_headers_policy" "video_security" {
  name    = "video-streaming-security-headers-${var.environment}"
  comment = "Injects HSTS, nosniff, and a strict referrer policy on all viewer responses"

  security_headers_config {
    strict_transport_security {
      override                   = true
      include_subdomains         = true
      preload                    = true
      access_control_max_age_sec = 63072000
    }

    content_type_options {
      override = true
    }

    referrer_policy {
      override        = true
      referrer_policy = "strict-origin-when-cross-origin"
    }
  }
}

###############################################################################
# CloudFront distribution
###############################################################################

resource "aws_cloudfront_distribution" "streaming" {
  enabled         = true
  is_ipv6_enabled = true
  http_version    = "http2and3"
  comment         = "Global video streaming distribution for ${var.domain_name}"
  price_class     = "PriceClass_All"
  aliases         = [var.domain_name]

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_id                = local.s3_origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content.id
  }

  default_cache_behavior {
    target_origin_id           = local.s3_origin_id
    viewer_protocol_policy     = "redirect-to-https"
    allowed_methods            = ["GET", "HEAD"]
    cached_methods             = ["GET", "HEAD"]
    cache_policy_id            = aws_cloudfront_cache_policy.video_media.id
    response_headers_policy_id = aws_cloudfront_response_headers_policy.video_security.id
    compress                   = true
  }

  logging_config {
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_regional_domain_name
    prefix          = "${local.log_prefix}/"
    include_cookies = false
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.streaming.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  tags = {
    Name = "video-streaming-distribution"
  }

  depends_on = [aws_acm_certificate_validation.streaming]
}

###############################################################################
# Route 53 alias records (A + AAAA) pointing the domain at CloudFront
###############################################################################

resource "aws_route53_record" "streaming_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.streaming.domain_name
    zone_id                = aws_cloudfront_distribution.streaming.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "streaming_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_cloudfront_distribution.streaming.domain_name
    zone_id                = aws_cloudfront_distribution.streaming.hosted_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Outputs
###############################################################################

output "cloudfront_distribution_domain_name" {
  description = "CloudFront distribution domain name serving the video content."
  value       = aws_cloudfront_distribution.streaming.domain_name
}

output "content_bucket_name" {
  description = "Name of the S3 bucket holding the video content (CloudFront origin)."
  value       = aws_s3_bucket.video_content.id
}

output "hosted_zone_name_servers" {
  description = "Name servers to configure at the domain registrar to delegate DNS for the streaming domain."
  value       = aws_route53_zone.main.name_servers
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values only)
# -----------------------------------------------------------------------------

variable "domain_name" {
  description = "Custom domain name for the video streaming site (e.g. stream.example.com)."
  type        = string
  default     = "stream.example.com"

  validation {
    condition     = length(var.domain_name) >= 4 && length(var.domain_name) <= 36
    error_message = "The domain name must be between 4 and 36 characters so derived S3 bucket names stay within the 63-character S3 limit."
  }
}

variable "environment" {
  description = "Environment label applied to every taggable resource."
  type        = string
  default     = "production"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Data sources (pure local/static lookups only)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      Project     = "video-streaming"
      ManagedBy   = "terraform"
    },
  )

  domain_slug         = lower(replace(var.domain_name, ".", "-"))
  content_bucket_name = "${local.domain_slug}-video-content-${data.aws_caller_identity.current.account_id}"
  logs_bucket_name    = "${local.domain_slug}-video-logs-${data.aws_caller_identity.current.account_id}"
  log_prefix          = "cloudfront-logs"
  origin_id           = "s3-video-content-origin"
  cloudfront_zone_id  = "Z2FDTNDATAQYW2"
}

# -----------------------------------------------------------------------------
# Video content origin bucket (private, accessed only via CloudFront OAC)
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "video_content" {
  bucket = local.content_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_object" "index_html" {
  bucket        = aws_s3_bucket.video_content.id
  key           = "index.html"
  content_type  = "text/html"
  cache_control = "public, max-age=300"

  content = <<-EOT
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <title>Video Streaming</title>
      </head>
      <body>
        <h1>Video streaming site</h1>
        <p>Video content is delivered globally through CloudFront.</p>
      </body>
    </html>
  EOT
}

# -----------------------------------------------------------------------------
# Dedicated private S3 bucket for CloudFront standard logs
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudfront_logs" {
  bucket = local.logs_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  rule {
    id     = "expire-cloudfront-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = 90
    }
  }
}

# -----------------------------------------------------------------------------
# Route53 hosted zone for the streaming domain
# -----------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# ACM certificate (must be in us-east-1 for CloudFront) with DNS validation
# -----------------------------------------------------------------------------

resource "aws_acm_certificate" "main" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "certificate_validation" {
  for_each = {
    for dvo in aws_acm_certificate.main.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      type   = dvo.resource_record_type
      record = dvo.resource_record_value
    }
  }

  allow_overwrite = true
  zone_id         = aws_route53_zone.main.zone_id
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
}

resource "aws_acm_certificate_validation" "main" {
  certificate_arn         = aws_acm_certificate.main.arn
  validation_record_fqdns = [for record in aws_route53_record.certificate_validation : record.fqdn]
}

# -----------------------------------------------------------------------------
# CloudFront: cache policy, origin access control, and distribution
# -----------------------------------------------------------------------------

resource "aws_cloudfront_cache_policy" "video_streaming" {
  name        = "${local.domain_slug}-video-cache-policy"
  comment     = "Long-TTL cache policy tuned for video content"
  min_ttl     = 0
  default_ttl = 86400
  max_ttl     = 31536000

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }
    headers_config {
      header_behavior = "none"
    }
    query_strings_config {
      query_string_behavior = "none"
    }

    enable_accept_encoding_gzip   = true
    enable_accept_encoding_brotli = true
  }
}

resource "aws_cloudfront_origin_access_control" "video_content_oac" {
  name                              = "${local.domain_slug}-video-content-oac"
  description                       = "SigV4 origin access control for the private video content S3 origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  is_ipv6_enabled     = true
  comment             = "Global video streaming distribution for ${var.domain_name}"
  price_class         = "PriceClass_All"
  http_version        = "http2and3"
  default_root_object = "index.html"

  aliases = [var.domain_name]

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_id                = local.origin_id
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content_oac.id
  }

  logging_config {
    bucket          = aws_s3_bucket.cloudfront_logs.bucket_domain_name
    include_cookies = false
    prefix          = local.log_prefix
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.origin_id
    viewer_protocol_policy = "redirect-to-https"
    compress               = true
    cache_policy_id        = aws_cloudfront_cache_policy.video_streaming.id
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    acm_certificate_arn      = aws_acm_certificate.main.arn
    ssl_support_method       = "sni-only"
    minimum_protocol_version = "TLSv1.2_2021"
  }

  tags = local.common_tags

  depends_on = [aws_acm_certificate_validation.main]
}

# -----------------------------------------------------------------------------
# S3 bucket policies
# -----------------------------------------------------------------------------

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontOACGetObject"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:GetObject"
        Resource  = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.video_content]
}

resource "aws_s3_bucket_policy" "cloudfront_logs" {
  bucket = aws_s3_bucket.cloudfront_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontLogDelivery"
        Effect    = "Allow"
        Principal = { Service = "cloudfront.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudfront_logs.arn}/${local.log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.cloudfront_logs]
}

# -----------------------------------------------------------------------------
# Alias records (A and AAAA) pointing the domain at the CloudFront distribution
# -----------------------------------------------------------------------------

resource "aws_route53_record" "streaming_site_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = local.cloudfront_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "streaming_site_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = var.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = local.cloudfront_zone_id
    evaluate_target_health = false
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "cloudfront_distribution_domain_name" {
  description = "CloudFront distribution domain name (useful for verification before DNS cutover)."
  value       = aws_cloudfront_distribution.main.domain_name
}

output "cloudfront_distribution_hosted_zone_id" {
  description = "Hosted zone ID of the CloudFront distribution (for additional alias records)."
  value       = aws_cloudfront_distribution.main.hosted_zone_id
}

output "route53_zone_name_servers" {
  description = "Name servers for the Route53 hosted zone; point the domain registrar delegation at these."
  value       = aws_route53_zone.main.name_servers
}

output "video_content_bucket_name" {
  description = "Name of the private S3 bucket that stores the video content."
  value       = aws_s3_bucket.video_content.bucket
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  s3_origin_id = "s3_video_content_origin"
}

resource "aws_s3_bucket" "video_content" {
  bucket = "netflix-video-content-s3-origin"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name                              = "s3-video-content-origin-oac"
  description                       = "Origin access control for the S3 video content origin"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_cache_policy" "caching_optimized" {
  name        = "video-content-caching-optimized"
  comment     = "Caching policy for S3 video content (GET/HEAD)"
  min_ttl     = 1
  default_ttl = 86400
  max_ttl     = 31536000

  parameters_in_cache_key_and_forwarded_to_origin {
    cookies_config {
      cookie_behavior = "none"
    }

    headers_config {
      header_behavior = "none"
    }

    query_strings_config {
      query_string_behavior = "none"
    }

    enable_accept_encoding_brotli = true
    enable_accept_encoding_gzip   = true
  }
}

resource "aws_cloudfront_distribution" "s3_distribution" {
  enabled     = true
  price_class = "PriceClass_200"
  comment     = "CloudFront distribution serving video content from S3"

  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id
    origin_id                = local.s3_origin_id
  }

  default_cache_behavior {
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    target_origin_id       = local.s3_origin_id
    cache_policy_id        = aws_cloudfront_cache_policy.caching_optimized.id
    viewer_protocol_policy = "allow-all"
    compress               = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  tags = {
    Name = "s3-video-content-distribution"
  }
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudFrontServicePrincipalRead"
        Effect    = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.s3_distribution.arn
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.video_content]
}

resource "aws_route53_zone" "main" {
  name = "netflix.com"
}

resource "aws_route53_record" "apex" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.s3_distribution.domain_name
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "www" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.s3_distribution.domain_name
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "prod"

  validation {
    condition     = length(trimspace(var.environment)) > 0
    error_message = "environment must be a non-empty string."
  }
}

locals {
  common_tags = {
    Environment = var.environment
    Project     = "video-streaming"
    ManagedBy   = "terraform"
  }

  asg_tags = merge(local.common_tags, {
    Name = "${var.environment}-video-server"
  })

  video_server_user_data = <<-EOS
    #!/bin/bash
    set -euo pipefail

    dnf install -y nginx

    cat > /usr/share/nginx/html/index.html <<'HTML'
    <!DOCTYPE html>
    <html>
      <head>
        <title>Video Streaming Service</title>
      </head>
      <body>
        <h1>Video Streaming Service</h1>
        <video controls width="960">
          <source src="/media/sample.mp4" type="video/mp4" />
          Your browser does not support HTML5 video.
        </video>
      </body>
    </html>
    HTML

    mkdir -p /usr/share/nginx/html/media
    aws s3 sync "s3://${aws_s3_bucket.video_content.bucket}/media/" /usr/share/nginx/html/media/ || true

    systemctl enable --now nginx
  EOS
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_elb_service_account" "main" {}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-streaming-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.environment}-streaming-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 10)

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-public-route-table"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-nat-gateway"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${var.environment}-alb-sg"
  description = "Internet-facing ALB. Ingress limited to HTTP/HTTPS from the internet."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-alb-sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "alb_to_video_servers" {
  security_group_id            = aws_security_group.alb.id
  referenced_security_group_id = aws_security_group.video_servers.id
  ip_protocol                  = "tcp"
  from_port                    = 80
  to_port                      = 80
  description                  = "ALB egress limited to the streaming-server security group"
}

resource "aws_security_group" "video_servers" {
  name        = "${var.environment}-video-servers-sg"
  description = "Streaming server tier. Ingress only from the ALB on the streaming port."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Streaming traffic from the ALB only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "HTTPS to the internet through the NAT gateway for package retrieval"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP to the internet through the NAT gateway for package retrieval"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-servers-sg"
  })
}

resource "aws_s3_bucket" "video_content" {
  bucket = "${var.environment}-video-content-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-content"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "video_content" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.video_content.arn,
          "${aws_s3_bucket.video_content.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.video_content]
}

resource "aws_s3_bucket" "alb_logs" {
  bucket = "${var.environment}-alb-logs-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${var.environment}-alb-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryPutObject"
        Effect    = "Allow"
        Principal = { AWS = data.aws_elb_service_account.main.arn }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.alb_logs.arn}/alb-logs/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
      },
      {
        Sid       = "ELBLogDeliveryBucketCheck"
        Effect    = "Allow"
        Principal = { AWS = data.aws_elb_service_account.main.arn }
        Action    = "s3:GetBucketLocation"
        Resource  = aws_s3_bucket.alb_logs.arn
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.alb_logs.arn,
          "${aws_s3_bucket.alb_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

resource "aws_iam_role" "video_server_role" {
  name = "${var.environment}-video-server-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowEC2ToAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-server-role"
  })
}

resource "aws_iam_policy" "video_content_read" {
  name        = "${var.environment}-video-content-read"
  description = "Least-privilege read access to the video content bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVideoContentBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = aws_s3_bucket.video_content.arn
      },
      {
        Sid      = "ReadVideoContentObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = "${aws_s3_bucket.video_content.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "video_server_video_content_read" {
  role       = aws_iam_role.video_server_role.name
  policy_arn = aws_iam_policy.video_content_read.arn
}

resource "aws_iam_instance_profile" "video_server_profile" {
  name = "${var.environment}-video-server-profile"
  role = aws_iam_role.video_server_role.name
}

resource "aws_launch_template" "video_server" {
  name_prefix   = "${var.environment}-video-server-"
  description   = "Launch template for nginx-based video streaming servers"
  image_id      = data.aws_ami.al2023.id
  instance_type = "t3.medium"

  iam_instance_profile {
    name = aws_iam_instance_profile.video_server_profile.name
  }

  vpc_security_group_ids = [aws_security_group.video_servers.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  monitoring {
    enabled = true
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 20
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  user_data = base64encode(local.video_server_user_data)

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "${var.environment}-video-server"
    })
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group" "video_tg" {
  name        = "${var.environment}-video-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-tg"
  })
}

resource "aws_lb" "video_streaming" {
  name               = "${var.environment}-video-streaming-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = "alb-logs"
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  tags = merge(local.common_tags, {
    Name = "${var.environment}-video-streaming-alb"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.video_streaming.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_tg.arn
  }
}

resource "aws_autoscaling_group" "video_servers" {
  name                = "${var.environment}-video-servers-asg"
  vpc_zone_identifier = aws_subnet.private[*].id
  target_group_arns   = [aws_lb_target_group.video_tg.arn]
  health_check_type   = "ELB"

  min_size         = 2
  desired_capacity = 2
  max_size         = 6

  health_check_grace_period = 300

  launch_template {
    id      = aws_launch_template.video_server.id
    version = "$Latest"
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 50
    }
  }

  dynamic "tag" {
    for_each = local.asg_tags

    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }
}

resource "aws_autoscaling_policy" "video_servers_cpu_target" {
  name                   = "${var.environment}-video-servers-cpu-target"
  autoscaling_group_name = aws_autoscaling_group.video_servers.name
  policy_type            = "TargetTrackingScaling"

  target_tracking_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ASGAverageCPUUtilization"
    }

    target_value = 60
  }
}

output "streaming_endpoint" {
  description = "Public DNS name of the video streaming Application Load Balancer."
  value       = aws_lb.video_streaming.dns_name
}

###############################################################################
# Video Streaming Platform
# VPC (multi-AZ) + ALB + EC2 Auto Scaling + Route 53 + ACM + S3 + IAM + CloudWatch
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables
#------------------------------------------------------------------------------

variable "domain_name" {
  description = "Public domain name for the streaming site."
  type        = string
  default     = "example-streaming.com"
}

variable "vpc_cidr" {
  description = "CIDR block for the streaming VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "app_port" {
  description = "Port the streaming application listens on behind the ALB."
  type        = number
  default     = 8080
}

variable "instance_type" {
  description = "EC2 instance type for the streaming servers."
  type        = string
  default     = "t3.medium"
}

variable "environment" {
  description = "Environment tag value applied to all resources."
  type        = string
  default     = "production"
}

variable "project" {
  description = "Project tag value applied to all resources."
  type        = string
  default     = "video-streaming"
}

variable "alarm_email" {
  description = "Email endpoint for CloudWatch alarm notifications."
  type        = string
  default     = "ops@example-streaming.com"
}

#------------------------------------------------------------------------------
# Data sources (static/well-known lookups only)
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

#------------------------------------------------------------------------------
# Locals
#------------------------------------------------------------------------------

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "terraform"
  }

  video_assets_bucket_name = "${var.project}-video-assets-${data.aws_caller_identity.current.account_id}"
  alb_logs_bucket_name     = "${var.project}-alb-logs-${data.aws_caller_identity.current.account_id}"

  user_data = <<-USER_DATA
    #!/bin/bash
    set -euo pipefail

    dnf install -y nginx aws-cli

    mkdir -p /usr/share/nginx/html/videos
    aws s3 sync "s3://${aws_s3_bucket.video_assets.bucket}/videos/" /usr/share/nginx/html/videos/ || true

    cat >/etc/nginx/conf.d/streaming.conf <<'NGINX_CONF'
    server {
        listen ${var.app_port};
        server_name _;

        location = /health {
            access_log off;
            add_header Content-Type text/plain;
            return 200 "healthy";
        }

        location /videos/ {
            alias /usr/share/nginx/html/videos/;
            autoindex on;
            add_header Accept-Ranges bytes;
            types {
                text/html html;
                video/mp4 mp4;
                video/webm webm;
                video/ogg ogg;
            }
        }
    }
    NGINX_CONF

    systemctl enable nginx
    systemctl restart nginx
  USER_DATA
}

#------------------------------------------------------------------------------
# Networking foundation
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "streaming-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "streaming-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "streaming-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "streaming-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  count = 2

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "streaming-nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 2

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, {
    Name = "streaming-nat-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "streaming-public-rt"
  })
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, {
    Name = "streaming-private-rt-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [for rt in aws_route_table.private : rt.id]

  tags = merge(local.common_tags, {
    Name = "streaming-s3-gateway-endpoint"
  })
}

#------------------------------------------------------------------------------
# Security groups
#------------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "streaming-alb-sg"
  description = "Public entry point for the streaming ALB (HTTP/HTTPS only)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward traffic to the app tier on the streaming app port only"
    from_port   = var.app_port
    to_port     = var.app_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "streaming-alb-sg"
  })
}

resource "aws_security_group" "app" {
  name        = "streaming-app-sg"
  description = "Streaming app servers; app port reachable only from the ALB."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Streaming app port from the ALB only"
    from_port       = var.app_port
    to_port         = var.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All outbound (package downloads, S3 via NAT/endpoint)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "streaming-app-sg"
  })
}

#------------------------------------------------------------------------------
# Content storage (video assets)
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "video_assets" {
  bucket = local.video_assets_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "video-assets"
  })
}

resource "aws_s3_bucket_versioning" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "video_assets" {
  bucket = aws_s3_bucket.video_assets.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = {
          AWS = "*"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.video_assets.arn,
          "${aws_s3_bucket.video_assets.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

#------------------------------------------------------------------------------
# ALB access log storage
#------------------------------------------------------------------------------

resource "aws_s3_bucket" "alb_logs" {
  bucket = local.alb_logs_bucket_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "alb-access-logs"
  })
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryWrite"
        Effect    = "Allow"
        Principal = {
          Service = "logdelivery.elasticloadbalancing.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/alb-logs/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = {
          AWS = "*"
        }
        Action = "s3:*"
        Resource = [
          aws_s3_bucket.alb_logs.arn,
          "${aws_s3_bucket.alb_logs.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    id     = "expire-alb-access-logs"
    status = "Enabled"

    filter {
      prefix = "alb-logs/"
    }

    expiration {
      days = 90
    }
  }
}

#------------------------------------------------------------------------------
# IAM for the EC2 fleet (least privilege)
#------------------------------------------------------------------------------

resource "aws_iam_role" "video_server" {
  name = "streaming-video-server-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "video_assets_readonly" {
  name        = "streaming-video-assets-readonly"
  description = "Read-only access to the video assets bucket for the streaming fleet."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVideoAssets"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.video_assets.arn]
      },
      {
        Sid      = "GetVideoAssets"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.video_assets.arn}/*"]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "video_assets_readonly" {
  role       = aws_iam_role.video_server.name
  policy_arn = aws_iam_policy.video_assets_readonly.arn
}

resource "aws_iam_instance_profile" "video_server" {
  name = "streaming-video-server-profile"
  role = aws_iam_role.video_server.name

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Backend fleet (launch template with IMDSv2 enforced)
#------------------------------------------------------------------------------

resource "aws_launch_template" "video_server" {
  name_prefix            = "streaming-video-server-"
  description            = "Video streaming server fleet template"
  image_id               = data.aws_ami.al2023.id
  instance_type          = var.instance_type
  update_default_version = true

  iam_instance_profile {
    name = aws_iam_instance_profile.video_server.name
  }

  vpc_security_group_ids = [aws_security_group.app.id]

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      encrypted             = true
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "disabled"
  }

  user_data = base64encode(local.user_data)

  tag_specifications {
    resource_type = "instance"
    tags = merge(local.common_tags, {
      Name = "streaming-video-server"
    })
  }

  tag_specifications {
    resource_type = "volume"
    tags = merge(local.common_tags, {
      Name = "streaming-video-server"
    })
  }

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Load balancing
#------------------------------------------------------------------------------

resource "aws_lb_target_group" "video" {
  name                 = "video"
  port                 = var.app_port
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 600

  health_check {
    enabled             = true
    path                = "/health"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "video-targets"
  })
}

resource "aws_lb" "streaming" {
  name                       = "streaming"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = "alb-logs"
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  tags = merge(local.common_tags, {
    Name = "streaming-alb"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.streaming.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.site.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video.arn
  }

  depends_on = [aws_acm_certificate_validation.site]

  tags = local.common_tags
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.streaming.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# DNS (Route 53) and TLS certificate (ACM)
#------------------------------------------------------------------------------

resource "aws_route53_zone" "streaming" {
  name = var.domain_name

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "streaming-hosted-zone"
  })
}

resource "aws_acm_certificate" "site" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "streaming-site-cert"
  })
}

resource "aws_route53_record" "cert_validation" {
  for_each = {
    for dvo in aws_acm_certificate.site.domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      record = dvo.resource_record_value
      type   = dvo.resource_record_type
    }
  }

  allow_overwrite = true
  zone_id         = aws_route53_zone.streaming.zone_id
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
}

resource "aws_acm_certificate_validation" "site" {
  certificate_arn         = aws_acm_certificate.site.arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_route53_record" "site_a" {
  zone_id = aws_route53_zone.streaming.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.streaming.dns_name
    zone_id                = aws_lb.streaming.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "site_aaaa" {
  zone_id = aws_route53_zone.streaming.zone_id
  name    = var.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_lb.streaming.dns_name
    zone_id                = aws_lb.streaming.zone_id
    evaluate_target_health = true
  }
}

#------------------------------------------------------------------------------
# Auto Scaling
#------------------------------------------------------------------------------

resource "aws_autoscaling_group" "video_fleet" {
  name                      = "streaming-video-fleet"
  vpc_zone_identifier       = aws_subnet.private[*].id
  min_size                  = 2
  max_size                  = 6
  desired_capacity          = 2
  health_check_type         = "ELB"
  health_check_grace_period = 300
  target_group_arns         = [aws_lb_target_group.video.arn]

  launch_template {
    name    = aws_launch_template.video_server.name
    version = "$Latest"
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 50
    }
  }

  tag {
    key                 = "Environment"
    value               = var.environment
    propagate_at_launch = true
  }

  tag {
    key                 = "Project"
    value               = var.project
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "streaming-video-server"
    propagate_at_launch = true
  }
}

resource "aws_autoscaling_policy" "video_fleet_cpu" {
  name                   = "streaming-video-fleet-cpu-target-60"
  autoscaling_group_name = aws_autoscaling_group.video_fleet.name
  policy_type            = "TargetTrackingScaling"

  target_tracking_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ASGAverageCPUUtilization"
    }

    target_value = 60
  }
}

#------------------------------------------------------------------------------
# Observability
#------------------------------------------------------------------------------

resource "aws_sns_topic" "alerts" {
  name = "streaming-alarm-alerts"

  tags = merge(local.common_tags, {
    Name = "streaming-alerts"
  })
}

resource "aws_sns_topic_subscription" "alerts_email" {
  topic_arn = aws_sns_topic.alerts.arn
  protocol  = "email"
  endpoint  = var.alarm_email
}

resource "aws_cloudwatch_metric_alarm" "alb_5xx" {
  alarm_name          = "streaming-alb-5xx"
  alarm_description   = "Alerts when the streaming ALB returns elevated 5xx error counts."
  namespace           = "AWS/ApplicationELB"
  metric_name         = "HTTPCode_ELB_5XX_Count"
  comparison_operator = "GreaterThanThreshold"
  statistic           = "Sum"
  threshold           = 10
  period              = 60
  evaluation_periods  = 2
  treat_missing_data  = "notBreaching"

  dimensions = {
    LoadBalancer = aws_lb.streaming.arn_suffix
  }

  alarm_actions = [aws_sns_topic.alerts.arn]

  tags = local.common_tags
}

resource "aws_cloudwatch_metric_alarm" "target_response_time" {
  alarm_name          = "streaming-target-response-time"
  alarm_description   = "Alerts when average target response time for the video target group exceeds 2 seconds."
  namespace           = "AWS/ApplicationELB"
  metric_name         = "TargetResponseTime"
  comparison_operator = "GreaterThanThreshold"
  statistic           = "Average"
  threshold           = 2
  period              = 60
  evaluation_periods  = 3
  treat_missing_data  = "notBreaching"

  dimensions = {
    LoadBalancer = aws_lb.streaming.arn_suffix
    TargetGroup  = aws_lb_target_group.video.arn_suffix
  }

  alarm_actions = [aws_sns_topic.alerts.arn]

  tags = local.common_tags
}

#------------------------------------------------------------------------------
# Outputs
#------------------------------------------------------------------------------

output "streaming_site_url" {
  description = "HTTPS URL of the streaming site."
  value       = "https://${var.domain_name}"
}

output "alb_dns_name" {
  description = "Public DNS name of the streaming ALB."
  value       = aws_lb.streaming.dns_name
}

output "video_assets_bucket_name" {
  description = "Name of the S3 bucket holding video assets."
  value       = aws_s3_bucket.video_assets.bucket
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name applied to all resource tags."
  type        = string
  default     = "production"
}

variable "domain_name" {
  description = "Public DNS domain for the streaming site's Route53 hosted zone."
  type        = string
  default     = "streaming.example.com"
}

variable "video_bucket_base_name" {
  description = "Lowercase base name for the video content S3 bucket. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "video-streaming-content"
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix       = "streaming"
  video_bucket_name = lower("${var.video_bucket_base_name}-${data.aws_caller_identity.current.account_id}")

  common_tags = {
    Project     = "video-streaming"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Networking: VPC, Internet Gateway, Subnets, Routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Streaming ALB: allow inbound HTTP/HTTPS from the internet only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

resource "aws_security_group" "streaming_instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Streaming web servers: allow inbound HTTP from the ALB only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow all outbound traffic for packages and bootstrap"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

###############################################################################
# IAM: role, inline least-privilege S3 policy, instance profile
###############################################################################

resource "aws_iam_role" "streaming_instance" {
  name = "${local.name_prefix}-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-role"
  })
}

resource "aws_iam_role_policy" "streaming_s3_read" {
  name = "${local.name_prefix}-s3-read"
  role = aws_iam_role.streaming_instance.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListVideosInBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.video.arn]
      },
      {
        Sid      = "ReadVideoObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject"]
        Resource = ["${aws_s3_bucket.video.arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "streaming_ssm" {
  role       = aws_iam_role.streaming_instance.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "streaming" {
  name = "${local.name_prefix}-instance-profile"
  role = aws_iam_role.streaming_instance.name
}

###############################################################################
# S3: video content bucket
###############################################################################

resource "aws_s3_bucket" "video" {
  bucket = local.video_bucket_name

  tags = merge(local.common_tags, {
    Name = local.video_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "video" {
  bucket = aws_s3_bucket.video.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "video" {
  bucket = aws_s3_bucket.video.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "video" {
  bucket = aws_s3_bucket.video.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Load balancing
###############################################################################

resource "aws_lb" "streaming" {
  name                             = "${local.name_prefix}-alb"
  internal                         = false
  load_balancer_type               = "application"
  security_groups                  = [aws_security_group.alb.id]
  subnets                          = aws_subnet.public[*].id
  drop_invalid_header_fields       = true
  enable_cross_zone_load_balancing = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_target_group" "streaming" {
  name                 = "${local.name_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.streaming.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.streaming.arn
  }

  tags = local.common_tags
}

###############################################################################
# Streaming web servers
###############################################################################

resource "aws_instance" "streaming" {
  count = 2

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public[count.index].id
  vpc_security_group_ids      = [aws_security_group.streaming_instance.id]
  iam_instance_profile        = aws_iam_instance_profile.streaming.name
  user_data_replace_on_change = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf -y install nginx
    TOKEN=$(curl -s -X PUT "http://169.254.169.254/latest/api/token" -H "X-aws-ec2-metadata-token-ttl-seconds: 300")
    INSTANCE_ID=$(curl -s -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/instance-id)
    cat > /usr/share/nginx/html/index.html <<HTML
    <html>
      <head><title>Video Streaming Service</title></head>
      <body>
        <h1>Video Streaming Node: $INSTANCE_ID</h1>
        <p>Streaming traffic is load balanced across the fleet.</p>
      </body>
    </html>
    HTML
    systemctl enable --now nginx
  EOF

  depends_on = [
    aws_internet_gateway.main,
    aws_route_table_association.public,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-server-${count.index + 1}"
    Role = "streaming-web"
  })
}

resource "aws_lb_target_group_attachment" "streaming" {
  count = length(aws_instance.streaming)

  target_group_arn = aws_lb_target_group.streaming.id
  target_id        = aws_instance.streaming[count.index].id
  port             = 80
}

###############################################################################
# DNS: Route53 public zone and apex alias record
###############################################################################

resource "aws_route53_zone" "main" {
  name = var.domain_name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-zone"
  })
}

resource "aws_route53_record" "apex_alias" {
  zone_id = aws_route53_zone.main.zone_id
  name    = aws_route53_zone.main.name
  type    = "A"

  alias {
    name                   = aws_lb.streaming.dns_name
    zone_id                = aws_lb.streaming.zone_id
    evaluate_target_health = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "alb_dns_name" {
  description = "Public DNS name of the streaming Application Load Balancer."
  value       = aws_lb.streaming.dns_name
}

output "streaming_record_fqdn" {
  description = "FQDN of the Route53 apex alias record pointing at the ALB."
  value       = aws_route53_record.apex_alias.fqdn
}

output "target_group_arn" {
  description = "ARN of the streaming target group."
  value       = aws_lb_target_group.streaming.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  domain_name = "test-video-stream.com"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-video-stream-vpc"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.5.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-b"
  }
}

resource "aws_subnet" "public_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.6.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-video-stream-public-c"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-video-stream-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "test-video-stream-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_c" {
  subnet_id      = aws_subnet.public_c.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security
# ---------------------------------------------------------------------------

resource "aws_security_group" "main" {
  name        = "test-video-stream-sg"
  description = "Shared security group for the ALB and EC2 instance"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "test-video-stream-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "http_from_vpc" {
  security_group_id = aws_security_group.main.id
  description       = "Allow HTTP from the VPC CIDR range"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

resource "aws_vpc_security_group_egress_rule" "http_to_all" {
  security_group_id = aws_security_group.main.id
  description       = "Allow HTTP to any destination"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80
}

# ---------------------------------------------------------------------------
# Compute
# ---------------------------------------------------------------------------

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

resource "aws_instance" "app" {
  ami                    = data.aws_ami.ubuntu.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_a.id
  vpc_security_group_ids = [aws_security_group.main.id]

  user_data = <<-EOF
    #!/bin/bash
    apt-get update -y
    apt-get install -y nginx
    systemctl enable nginx
    systemctl start nginx
  EOF

  tags = {
    Name = "test-video-stream-app"
  }
}

# ---------------------------------------------------------------------------
# Load balancing
# ---------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = "test-video-stream-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.main.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id, aws_subnet.public_c.id]

  tags = {
    Name = "test-video-stream-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name     = "test-video-stream-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    protocol = "HTTP"
    port     = "80"
    path     = "/"
    matcher  = "200"
  }

  tags = {
    Name = "test-video-stream-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_target_group_attachment" "app" {
  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.app.id
  port             = 80
}

# ---------------------------------------------------------------------------
# DNS
# ---------------------------------------------------------------------------

resource "aws_route53_zone" "main" {
  name = local.domain_name

  tags = {
    Name = "test-video-stream-zone"
  }
}

resource "aws_route53_record" "lb_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "lb.${local.domain_name}"
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "lb_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "lb.${local.domain_name}"
  type    = "AAAA"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "apex_alias_a" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.domain_name
  type    = "A"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "apex_alias_aaaa" {
  zone_id = aws_route53_zone.main.zone_id
  name    = local.domain_name
  type    = "AAAA"

  alias {
    name                   = aws_lb.main.dns_name
    zone_id                = aws_lb.main.zone_id
    evaluate_target_health = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_username = "dbadmin"

  common_tags = {
    ManagedBy = "terraform"
    Component = "rds-postgres"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Generated unique suffix for the database identifier
resource "random_id" "db" {
  byte_length = 8
}

# Generated master password (never hardcoded, never output)
resource "random_password" "master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  numeric          = true
  upper            = true
  lower            = true

  min_special = 1
  min_numeric = 1
  min_upper   = 1
  min_lower   = 1
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    { Name = "rds-vpc" },
  )
}

resource "aws_subnet" "db" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    local.common_tags,
    { Name = "rds-subnet-${count.index + 1}" },
  )
}

resource "aws_db_subnet_group" "db" {
  name       = "rds-db-subnet-group"
  subnet_ids = aws_subnet.db[*].id

  tags = local.common_tags
}

resource "aws_security_group" "db" {
  name        = "rds-db-sg"
  description = "Allow PostgreSQL access from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    { Name = "rds-db-sg" },
  )
}

resource "aws_secretsmanager_secret" "db" {
  name        = "rds/master-${random_id.db.hex}"
  description = "Master credentials for the rds-${random_id.db.hex} PostgreSQL instance"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.master.result
  })
}

resource "aws_db_instance" "db" {
  identifier     = "rds-${random_id.db.hex}"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_encrypted = true

  db_name  = "appdb"
  username = local.db_username
  password = random_password.master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.db.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "rds-${random_id.db.hex}-final"

  tags = merge(
    local.common_tags,
    { Name = "rds-${random_id.db.hex}" },
  )

  lifecycle {
    prevent_destroy = true
  }
}

output "rds_endpoint_address" {
  description = "Connection address of the RDS PostgreSQL instance"
  value       = aws_db_instance.db.address
}

output "secrets_manager_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the master credentials"
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  db_username = random_string.db_username.result

  common_tags = {
    Project   = "mysql-database"
    ManagedBy = "terraform"
  }
}

# Randomly generated master username: alphanumeric (lowercase letters only),
# guaranteed to start with a letter, and <= 16 characters for MySQL/RDS constraints.
resource "random_string" "db_username" {
  length  = 12
  special = false
  upper   = false
  lower   = true
  numeric = false
}

# Randomly generated master password: length >= 16 with special characters,
# restricted to characters valid for RDS MySQL (excludes /, @, ", and space).
resource "random_password" "db_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

# Random suffix for unique naming of globally named resources.
resource "random_id" "db_suffix" {
  byte_length = 4
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "mysql-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "mysql-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "mysql-private-b" })
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "mysql-private-a-rt" })
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "mysql-private-b-rt" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_db_subnet_group" "main" {
  name       = "mysql-db-subnet-group-${random_id.db_suffix.hex}"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "mysql-db-subnet-group" })
}

resource "aws_security_group" "db" {
  name        = "mysql-db-sg-${random_id.db_suffix.hex}"
  description = "Restrict MySQL access to the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "mysql-db-sg" })
}

resource "aws_db_parameter_group" "mysql8" {
  name   = "mysql8-params-${random_id.db_suffix.hex}"
  family = "mysql8.0"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  tags = merge(local.common_tags, { Name = "mysql8-parameter-group" })
}

resource "aws_db_instance" "mysql" {
  identifier     = "mysql-db-${random_id.db_suffix.hex}"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "appdb"
  username = local.db_username
  password = random_password.db_password.result

  port                   = 3306
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  parameter_group_name   = aws_db_parameter_group.mysql8.name

  publicly_accessible = false
  multi_az            = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "mysql-db-${random_id.db_suffix.hex}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "mysql-db" })
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "mysql/db-credentials-${random_id.db_suffix.hex}"
  description = "Master credentials for the MySQL RDS instance"

  tags = merge(local.common_tags, { Name = "mysql-db-credentials" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = local.db_username
    password = random_password.db_password.result
  })
}

