# ------------------------------------------------------------------
# Security Group for Database Access
# ------------------------------------------------------------------

resource "aws_security_group" "db" {
  name        = "dolphinscheduler-db-sg"
  description = "Security group for the Dolphinscheduler PostgreSQL database - restricts access to TCP 5432 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic back to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-sg"
    }
  )
}

# ------------------------------------------------------------------
# Master Credentials in Secrets Manager
# ------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "dolphinscheduler-db-master-credentials"
  description = "Master credentials for the Dolphinscheduler PostgreSQL database"

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-master-credentials"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

# ------------------------------------------------------------------
# RDS Subnet Group (requires subnets in at least two AZs)
# ------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "dolphinscheduler-db-subnet-group"
  description = "Subnet group for the Dolphinscheduler PostgreSQL database"

  subnet_ids = [
    aws_subnet.public_a.id,
    aws_subnet.public_b.id,
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler-db-subnet-group"
    }
  )
}

# ------------------------------------------------------------------
# PostgreSQL Database Instance
# ------------------------------------------------------------------

resource "aws_db_instance" "dolphinscheduler" {
  identifier     = "dolphinscheduler"
  engine         = "postgres"
  engine_version = "17.1"
  instance_class = "db.t3.micro"

  allocated_storage = 5
  storage_encrypted = true

  db_name  = "dolphinscheduler"
  username = jsondecode(aws_secretsmanager_secret_version.db.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = false

  auto_minor_version_upgrade = false
  backup_retention_period    = 7

  skip_final_snapshot = true

  tags = merge(
    local.common_tags,
    {
      Name = "dolphinscheduler"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Deployment environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, 1)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-database-sg"
  description = "Designated database access security group: permits MySQL (TCP 3306) from the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-database-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "RDS subnet group spanning public subnets in two Availability Zones"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_db_parameter_group" "mysql" {
  name        = "${local.name_prefix}-mysql-8-4-params"
  family      = "mysql8.4"
  description = "MySQL 8.4 parameter group for ${local.name_prefix}"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "collation_server"
    value = "utf8mb4_unicode_ci"
  }

  tags = local.common_tags
}

resource "random_password" "db_master" {
  length  = 24
  special = true
  # Excludes "/", "@", double quote, and space, which are not permitted in RDS
  # master passwords and are problematic in connection strings.
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}/rds/mysql/master"
  description = "Master credentials for the ${local.name_prefix} MySQL RDS instance"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    engine   = aws_db_instance.mysql.engine
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = aws_db_instance.mysql.username
    password = random_password.db_master.result
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "mysql" {
  identifier     = "${local.name_prefix}-mysql"
  engine         = "mysql"
  engine_version = "8.4.3"
  instance_class = "db.t3.micro"

  # RDS enforces a 20 GiB minimum for MySQL; the requested 5 GB is below the
  # enforced floor, so the compliant minimum of 20 GiB is used.
  allocated_storage = 20
  storage_encrypted = true

  db_name  = "appdb"
  username = "appadmin"
  password = random_password.db_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  parameter_group_name   = aws_db_parameter_group.mysql.name

  publicly_accessible = true
  multi_az            = false

  # Keep the engine pinned to 8.4.3 instead of drifting via minor upgrades.
  auto_minor_version_upgrade = false

  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_endpoint_address" {
  description = "Hostname endpoint of the MySQL RDS instance."
  value       = aws_db_instance.mysql.address
  sensitive   = true
}

output "db_endpoint_port" {
  description = "Port on which the MySQL RDS instance listens."
  value       = aws_db_instance.mysql.port
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used exclusively for resource tagging."
  type        = string
  default     = "production"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "secure-postgres"
  vpc_cidr    = "10.0.0.0/16"
  db_port     = 5432
  azs         = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[0]
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "database"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[1]
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, 11)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "database"
  })
}

resource "aws_route_table" "private_a" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a-rt"
  })
}

resource "aws_route_table" "private_b" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_a.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_b.id
}

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for RDS PostgreSQL storage and master user credential encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms-key"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_subnet_group" "postgres" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_db_parameter_group" "postgres16" {
  name   = "${local.name_prefix}-pg16-params"
  family = "postgres16"

  parameter {
    name         = "max_connections"
    value        = "200"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_preload_libraries"
    value        = "pg_stat_statements"
    apply_method = "pending-reboot"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  parameter {
    name  = "log_disconnections"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pg16-params"
  })
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Restrict PostgreSQL (TCP 5432) access to the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"

  allocated_storage     = 100
  max_allocated_storage = 500
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = "app_db"
  username = "dbadmin"
  port     = local.db_port

  manage_master_user_password   = true
  master_user_secret_kms_key_id = aws_kms_key.rds.arn

  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  parameter_group_name   = aws_db_parameter_group.postgres16.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  multi_az                   = true
  publicly_accessible        = false
  auto_minor_version_upgrade = true

  backup_retention_period = 14
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-db-final-snapshot"

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------
locals {
  db_master_username = "dbadmin"

  common_tags = {
    Environment = "production"
    Project     = "secure-postgres"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC and private database subnets across two AZs
# -----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-vpc"
    }
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "db_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-subnet-a"
      Tier = "database"
    }
  )
}

resource "aws_subnet" "db_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-subnet-b"
      Tier = "database"
    }
  )
}

resource "aws_db_subnet_group" "main" {
  name        = "postgres-prod-db-subnet-group"
  description = "Private subnets for the production PostgreSQL instance"

  subnet_ids = [
    aws_subnet.db_a.id,
    aws_subnet.db_b.id,
  ]

  tags = merge(
    local.common_tags,
    {
      Name = "postgres-prod-db-subnet-group"
    }
  )
}

# -----------------------------------------------------------------------------
# KMS encryption for the database storage and credentials secret
# -----------------------------------------------------------------------------
resource "aws_kms_key" "rds_key" {
  description             = "Customer managed key for RDS PostgreSQL storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-kms-key"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds_key" {
  name          = "alias/rds-postgres"
  target_key_id = aws_kms_key.rds_key.key_id
}

# -----------------------------------------------------------------------------
# Database security group (PostgreSQL access restricted to the VPC)
# -----------------------------------------------------------------------------
resource "aws_security_group" "rds" {
  name        = "rds-postgres-sg"
  description = "Allow PostgreSQL traffic only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-sg"
    }
  )
}

# -----------------------------------------------------------------------------
# Custom PostgreSQL 15 parameter group
# -----------------------------------------------------------------------------
resource "aws_db_parameter_group" "postgres" {
  name        = "postgres15-secure-parameters"
  family      = "postgres15"
  description = "Secure PostgreSQL 15 parameter settings"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = merge(
    local.common_tags,
    {
      Name = "postgres15-secure-parameters"
    }
  )
}

# -----------------------------------------------------------------------------
# Master credentials: generated, never plain-text, stored in Secrets Manager
# -----------------------------------------------------------------------------
resource "random_password" "master_password" {
  length           = 24
  special          = true
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_creds" {
  name        = "rds/postgres/prod/master-credentials"
  description = "Master credentials for the production PostgreSQL RDS instance"
  kms_key_id  = aws_kms_key.rds_key.arn

  tags = merge(
    local.common_tags,
    {
      Name = "rds-postgres-master-credentials"
    }
  )
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL instance
# -----------------------------------------------------------------------------
resource "aws_db_instance" "postgres" {
  identifier     = "postgres-prod-db"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"

  db_name  = "appdb"
  username = local.db_master_username
  password = random_password.master_password.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.postgres.name

  multi_az            = true
  storage_encrypted   = true
  kms_key_id          = aws_kms_key.rds_key.arn
  publicly_accessible = false

  deletion_protection        = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "postgres-prod-db-final"
  backup_retention_period    = 14
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  tags = merge(
    local.common_tags,
    {
      Name = "postgres-prod-db"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# JSON credential payload in Secrets Manager (created after the instance so
# connection details can be included; the password is never plain-text)
# -----------------------------------------------------------------------------
resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id = aws_secretsmanager_secret.db_creds.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.master_password.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = aws_db_instance.postgres.db_name
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------
output "db_endpoint" {
  description = "Connection endpoint (host:port) of the PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

output "db_address" {
  description = "Hostname of the PostgreSQL instance."
  value       = aws_db_instance.postgres.address
}

output "db_instance_arn" {
  description = "ARN of the PostgreSQL RDS instance."
  value       = aws_db_instance.postgres.arn
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_creds.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_identifier   = "secure-postgres-db"
  db_name         = "appdb"
  master_username = "postgresadmin"

  common_tags = {
    Project     = "secure-postgres"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "postgres-vpc"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "postgres-private"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "postgres-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "postgres-private-b"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "postgres" {
  name        = "secure-postgres-sg"
  description = "Allow PostgreSQL (TCP 5432) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All outbound traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "secure-postgres-sg"
  })
}

# ---------------------------------------------------------------------------
# Encryption
# ---------------------------------------------------------------------------

resource "aws_kms_key" "postgres" {
  description             = "KMS key for PostgreSQL RDS storage and Secrets Manager encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "postgres-db-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "postgres" {
  name          = "alias/postgres-db"
  target_key_id = aws_kms_key.postgres.arn
}

# ---------------------------------------------------------------------------
# Master credentials (generated, stored in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "postgres_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "postgres_master" {
  name                    = "rds/${local.db_identifier}/master"
  description             = "Master credentials for the ${local.db_identifier} PostgreSQL instance"
  kms_key_id              = aws_kms_key.postgres.arn
  recovery_window_in_days = 30

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-master-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "postgres_master" {
  secret_id = aws_secretsmanager_secret.postgres_master.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = local.db_name
    username = local.master_username
    password = random_password.postgres_master.result
  })
}

# ---------------------------------------------------------------------------
# RDS
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "postgres" {
  name_prefix = "secure-postgres15-"
  family      = "postgres15"
  description = "Custom parameters for PostgreSQL 15"

  parameter {
    name         = "max_connections"
    value        = "100"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "shared_buffers"
    value        = "32768"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_db_subnet_group" "main" {
  name        = "secure-postgres-subnets"
  description = "Private subnets for the secure PostgreSQL RDS instance"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "secure-postgres-subnets"
  })
}

resource "random_id" "snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "postgres" {
  identifier     = local.db_identifier
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  db_name               = local.db_name
  username              = local.master_username
  password              = random_password.postgres_master.result
  port                  = 5432

  multi_az               = true
  publicly_accessible    = false
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.postgres.arn
  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.postgres.name
  vpc_security_group_ids = [aws_security_group.postgres.id]

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-${random_id.snapshot_suffix.hex}"

  auto_minor_version_upgrade      = true
  enabled_cloudwatch_logs_exports = ["postgresql", "upgrade"]

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "pg-secure"
}

variable "environment" {
  description = "Environment name applied to resources and tags."
  type        = string
  default     = "production"
}

variable "common_tags" {
  description = "Additional user-defined tags applied to every tagged resource."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
  }
}

locals {
  name_prefix        = lower(replace("${var.project_name}-${var.environment}", "/[^a-zA-Z0-9-]/", "-"))
  db_master_username = "pgadmin"
  db_name            = "appdb"
  tags = merge(
    var.common_tags,
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "database"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 12)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "database"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_kms_key" "rds" {
  description             = "Customer-managed KMS key for RDS PostgreSQL storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, { Name = "${local.name_prefix}-rds-key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds_postgres" {
  name          = "alias/rds-postgres"
  target_key_id = aws_kms_key.rds.key_id
}

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}/rds-postgres/master"
  description             = "Master credentials for the ${local.name_prefix} RDS PostgreSQL instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  tags = merge(local.tags, { Name = "${local.name_prefix}-rds-master-secret" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
    engine   = "postgres"
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = local.db_name
  })
}

resource "aws_db_parameter_group" "postgres16" {
  name        = "${local.name_prefix}-postgres16-params"
  family      = "postgres16"
  description = "Custom parameters for the PostgreSQL 16 RDS instance"

  parameter {
    name         = "max_connections"
    value        = "200"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "5000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "rds.force_ssl"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "shared_preload_libraries"
    value        = "pg_stat_statements"
    apply_method = "pending-reboot"
  }

  tags = local.tags
}

resource "aws_security_group" "postgres" {
  name        = "${local.name_prefix}-postgres-sg"
  description = "Restrict access to the RDS PostgreSQL instance to VPC traffic on port 5432"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound TLS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${local.name_prefix}-postgres-sg" })
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 500
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.db_master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.postgres16.name
  vpc_security_group_ids = [aws_security_group.postgres.id]

  publicly_accessible = false
  multi_az            = true

  backup_retention_period  = 14
  backup_window            = "03:00-04:00"
  maintenance_window       = "sun:05:00-sun:06:00"
  delete_automated_backups = false

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  skip_final_snapshot       = false
  final_snapshot_identifier = "pgsnapshot"

  tags = merge(local.tags, { Name = "${local.name_prefix}-postgres" })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the RDS PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into the common tag set for all resources."
  type        = map(string)
  default     = {}
}

variable "instance_class" {
  description = "RDS instance class for the PostgreSQL instance."
  type        = string
  default     = "db.t3.medium"
}

variable "allocated_storage" {
  description = "Allocated storage (GB) for the RDS instance."
  type        = number
  default     = 20

  validation {
    condition     = var.allocated_storage >= 20 && var.allocated_storage <= 16384
    error_message = "Allocated storage must be between 20 and 16384 GB."
  }
}

variable "allowed_client_cidr" {
  description = "CIDR block permitted to reach PostgreSQL on port 5432. Defaults to the VPC CIDR; set this to your Airbyte CI runner CIDR for external access."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = var.allowed_client_cidr != "0.0.0.0/0" && can(cidrnetmask(var.allowed_client_cidr))
    error_message = "The allowed client CIDR must be a valid CIDR and must not be 0.0.0.0/0; scope it to a specific network."
  }
}

locals {
  name_prefix = "airbyte-connector-testing"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      Purpose     = "airbyte-connector-testing"
      ManagedBy   = "terraform"
    },
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-b" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_kms_key" "rds" {
  description             = "KMS key encrypting the Airbyte connector testing RDS storage and master credentials secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow PostgreSQL (5432) access for Airbyte connector testing"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from the allowed client CIDR"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.allowed_client_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rds-sg" })
}

resource "aws_db_subnet_group" "airbyte_test" {
  name       = "${local.name_prefix}-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-subnet-group" })
}

resource "random_password" "rds_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "airbyte_test_db" {
  name        = "${local.name_prefix}/rds-master"
  description = "Master credentials for the Airbyte connector testing PostgreSQL instance"
  kms_key_id  = aws_kms_key.rds.arn

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "airbyte_test_db" {
  secret_id = aws_secretsmanager_secret.airbyte_test_db.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.airbyte_test.address
    port     = aws_db_instance.airbyte_test.port
    dbname   = aws_db_instance.airbyte_test.db_name
    username = aws_db_instance.airbyte_test.username
    password = random_password.rds_master.result
  })
}

resource "aws_db_instance" "airbyte_test" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  allocated_storage = var.allocated_storage
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  db_name  = "airbyte_test"
  username = "airbyte_admin"
  password = random_password.rds_master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.airbyte_test.id
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  auto_minor_version_upgrade = true
  apply_immediately          = false
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db" })

  lifecycle {
    prevent_destroy = true
  }
}

output "rds_endpoint" {
  description = "Hostname of the RDS instance for the Airbyte test harness."
  value       = aws_db_instance.airbyte_test.address
}

output "rds_port" {
  description = "Port on which the RDS instance accepts connections."
  value       = aws_db_instance.airbyte_test.port
}

output "database_name" {
  description = "Name of the database created for Airbyte connector testing."
  value       = aws_db_instance.airbyte_test.db_name
}

output "db_username" {
  description = "Master username for the Airbyte test database."
  value       = aws_db_instance.airbyte_test.username
}

output "master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials. Retrieve the secret value at runtime; it is never exposed in outputs."
  value       = aws_secretsmanager_secret.airbyte_test_db.arn
}

###############################################################################
# Airbyte Connector Test Harness - PostgreSQL 15 on AWS RDS
#
# Greenfield configuration: every dependency (VPC, subnets, routing, security
# group, DB subnet group, and master credentials) is created in this file.
# No data lookups against pre-existing infrastructure are used.
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (non-infrastructure metadata only, defaulted for unattended apply)
###############################################################################

variable "environment" {
  description = "Environment tag applied to all resources. Pure metadata; defaulted so terraform apply runs unattended."
  type        = string
  default     = "test"
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_cidr        = "10.0.0.0/16"
  master_username = "airbyte_admin"

  # Two distinct AZs resolved from live provider metadata (never hardcoded).
  public_subnet_azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  common_tags = {
    Environment = var.environment
    Project     = "airbyte-connector-tests"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "airbyte-test-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "airbyte-test-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-public-rt"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = local.public_subnet_azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "airbyte-test-public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS subnet group and security group
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "airbyte-test-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "airbyte-test-db-subnet-group"
  })
}

resource "aws_security_group" "rds" {
  name        = "airbyte-test-rds-sg"
  description = "PostgreSQL access restricted to the Airbyte test VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL 5432/tcp from within the Airbyte test VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-rds-sg"
  })
}

###############################################################################
# Master credentials (generated, stored in Secrets Manager - no plaintext)
###############################################################################

resource "random_password" "master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+"
}

resource "aws_secretsmanager_secret" "rds_master" {
  name        = "airbyte-test/postgres/master"
  description = "Master credentials for the Airbyte connector test PostgreSQL instance"

  tags = merge(local.common_tags, {
    Name = "airbyte-test-postgres-master-secret"
  })
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master.result
  })
}

###############################################################################
# RDS PostgreSQL 15 instance
###############################################################################

resource "aws_db_instance" "airbyte_postgres" {
  identifier     = "airbyte-test-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = "db.t3.micro"

  # IMPORTANT - USER-SPECIFIED VALUE RETAINED AS-IS:
  # allocated_storage = 5 is kept exactly as requested. Note that AWS RDS
  # enforces a minimum of 20 GiB allocated storage for the PostgreSQL engine;
  # the RDS API will reject 5 GB at apply time. This constraint is surfaced
  # here rather than silently changed - raise to 20 if deployment is required.
  allocated_storage = 5

  db_name  = "airbyte_test"
  username = local.master_username
  password = random_password.master.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true

  # Managed, low-maintenance settings (provider schema argument names:
  # backup_window and maintenance_window, valid top-level arguments of
  # aws_db_instance; backup_window is meaningful given
  # backup_retention_period = 7, and the two windows do not overlap).
  auto_minor_version_upgrade   = true
  backup_retention_period      = 7
  backup_window                = "03:00-04:00"
  maintenance_window           = "sun:05:00-sun:06:00"
  apply_immediately            = false
  multi_az                     = false
  storage_encrypted            = true

  # Disposable test context: no final snapshot on destruction, but the stateful
  # instance itself is still guarded against accidental terraform destroy.
  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "airbyte-test-postgres"
  })
}

###############################################################################
# Outputs for Airbyte connector test tooling (password is never exposed)
###############################################################################

output "rds_endpoint_address" {
  description = "Connection endpoint (host) of the Airbyte connector test PostgreSQL instance."
  value       = aws_db_instance.airbyte_postgres.address
}

output "rds_port" {
  description = "Port on which the PostgreSQL instance listens."
  value       = aws_db_instance.airbyte_postgres.port
}

output "rds_database_name" {
  description = "Name of the Airbyte test database."
  value       = aws_db_instance.airbyte_postgres.db_name
}

output "rds_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.rds_master.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables
#------------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used as the Name tag prefix across all resources."
  type        = string
  default     = "airbyte-connector-tests"
}

variable "environment" {
  description = "Environment name applied to the Environment tag of every resource."
  type        = string
  default     = "dev"
}

variable "instance_class" {
  description = "RDS instance class for the PostgreSQL instance."
  type        = string
  default     = "db.t3.micro"
}

variable "master_username" {
  description = "Master username for the RDS PostgreSQL instance."
  type        = string
  default     = "airbyte_admin"

  validation {
    condition     = can(regex("^[a-zA-Z][a-zA-Z0-9_]{0,62}$", var.master_username))
    error_message = "Master username must start with a letter and contain only letters, digits, or underscores (max 63 characters)."
  }
}

variable "admin_cidr" {
  description = "Trusted admin CIDR (office/VPN range) allowed to connect to PostgreSQL on port 5432."
  type        = string
  default     = "10.0.0.0/8"

  validation {
    condition     = var.admin_cidr != "0.0.0.0/0" && var.admin_cidr != "::/0" && can(cidrnetmask(var.admin_cidr))
    error_message = "admin_cidr must be a valid, restrictive IPv4 CIDR block; 0.0.0.0/0 is not permitted."
  }
}

#------------------------------------------------------------------------------
# Locals
#------------------------------------------------------------------------------

locals {
  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

#------------------------------------------------------------------------------
# Static provider metadata: available AZs
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Networking: dedicated VPC, public subnets, internet gateway, routing
#------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

#------------------------------------------------------------------------------
# RDS subnet group (public subnets, required for a publicly accessible DB)
#------------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name       = "${var.project_name}-db-subnet-group"
  subnet_ids = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-db-subnet-group"
  })
}

#------------------------------------------------------------------------------
# Security group: PostgreSQL ingress restricted to the trusted admin CIDR only
#------------------------------------------------------------------------------

resource "aws_security_group" "postgres" {
  name        = "${var.project_name}-postgres-sg"
  description = "PostgreSQL access for the Airbyte connector test RDS instance (restricted ingress)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from trusted admin CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-postgres-sg"
  })
}

#------------------------------------------------------------------------------
# Master credentials: generated password stored in Secrets Manager
#------------------------------------------------------------------------------

resource "random_password" "master" {
  length           = 24
  special          = true
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${var.project_name}-db-master-credentials"
  description = "Master credentials for the Airbyte connector test PostgreSQL instance."

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-db-master-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.master.result
    engine   = aws_db_instance.main.engine
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
  })
}

#------------------------------------------------------------------------------
# RDS PostgreSQL 15 instance (dev/test lifecycle, RDS-managed defaults)
#------------------------------------------------------------------------------

resource "aws_db_instance" "main" {
  identifier     = "${var.project_name}-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = "airbyte"
  username = var.master_username
  password = random_password.master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  publicly_accessible    = true
  multi_az               = false

  auto_minor_version_upgrade = true
  apply_immediately          = true
  backup_retention_period    = 1
  skip_final_snapshot        = true
  deletion_protection        = false
  copy_tags_to_snapshot      = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Outputs for the Airbyte test harness (no secret values are ever emitted)
#------------------------------------------------------------------------------

output "rds_endpoint_address" {
  description = "RDS PostgreSQL endpoint address."
  value       = aws_db_instance.main.address
}

output "rds_port" {
  description = "RDS PostgreSQL listening port."
  value       = aws_db_instance.main.port
}

output "rds_database_name" {
  description = "Initial database name on the RDS PostgreSQL instance."
  value       = aws_db_instance.main.db_name
}

output "rds_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (retrieve the value via AWS SDK/CLI only)."
  value       = aws_secretsmanager_secret.db_master.arn
}

###############################################################################
# Terraform & Provider configuration
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "test"
}

variable "db_instance_class" {
  description = "RDS instance class for the Airbyte connector test PostgreSQL instance."
  type        = string
  default     = "db.t3.medium"
}

variable "db_master_username" {
  description = "Master username for the Airbyte connector test PostgreSQL instance."
  type        = string
  default     = "airbyteadmin"
}

variable "allowed_cidr_blocks" {
  description = "CIDR blocks allowed to reach PostgreSQL on port 5432. Set this to the egress CIDR(s) of the Airbyte connector test harness (e.g., CI runner networks outside AWS). 0.0.0.0/0 is rejected."
  type        = list(string)
  default     = ["203.0.113.0/24"]

  validation {
    condition = (
      length(var.allowed_cidr_blocks) > 0 &&
      !contains(var.allowed_cidr_blocks, "0.0.0.0/0") &&
      alltrue([for cidr in var.allowed_cidr_blocks : can(cidrnetmask(cidr))])
    )
    error_message = "allowed_cidr_blocks must be non-empty, contain valid CIDR blocks, and must not include 0.0.0.0/0."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "airbyte-connector-test"

  common_tags = {
    Environment = var.environment
    Purpose     = "airbyte-connector-testing"
  }
}

###############################################################################
# Availability zone lookup (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking: VPC, public subnets, IGW, and routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-b" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS subnet group and security group
###############################################################################

resource "aws_db_subnet_group" "airbyte" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Public subnets hosting the Airbyte connector test PostgreSQL instance"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_security_group" "airbyte_pg" {
  name        = "${local.name_prefix}-pg-sg"
  description = "PostgreSQL access for Airbyte connector testing, restricted to approved harness CIDRs"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from Airbyte connector test harness CIDRs"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = var.allowed_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-pg-sg" })
}

###############################################################################
# Encryption: customer-managed KMS key (rotation enabled)
###############################################################################

resource "aws_kms_key" "rds" {
  description             = "KMS key for Airbyte connector test PostgreSQL storage and Secrets Manager encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-kms" })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}-postgres"
  target_key_id = aws_kms_key.rds.key_id
}

###############################################################################
# Master credentials: apply-time generation, stored in Secrets Manager
###############################################################################

resource "random_password" "master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}/postgres/master-credentials"
  description             = "Master credentials for the Airbyte connector test PostgreSQL instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres-master-secret" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.db_master_username
    password = random_password.master_password.result
  })
}

###############################################################################
# Parameter group (postgres15 family)
###############################################################################

resource "aws_db_parameter_group" "airbyte_postgres15" {
  name        = "${local.name_prefix}-postgres15-params"
  family      = "postgres15"
  description = "Parameter tuning for the Airbyte connector test PostgreSQL 15 instance"

  parameter {
    name  = "idle_in_transaction_session_timeout"
    value = "300000"
  }

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres15-params" })
}

###############################################################################
# PostgreSQL 15 instance for Airbyte connector testing
###############################################################################

resource "aws_db_instance" "airbyte_postgres" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "15"
  instance_class = var.db_instance_class

  allocated_storage     = 500
  max_allocated_storage = 1000
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name  = "airbyte"
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.airbyte.name
  vpc_security_group_ids = [aws_security_group.airbyte_pg.id]
  parameter_group_name   = aws_db_parameter_group.airbyte_postgres15.name

  port                = 5432
  publicly_accessible = true
  multi_az            = false

  backup_retention_period    = 7
  backup_window              = "01:00-03:00"
  maintenance_window         = "sun:04:00-sun:06:00"
  auto_minor_version_upgrade = true

  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-postgres-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-postgres" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the Airbyte connector test PostgreSQL instance."
  value       = aws_db_instance.airbyte_postgres.endpoint
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_identifier      = "main-mysql-db"
  db_name            = "maindb"
  db_master_username = "dbadmin"
  db_port            = 3306

  common_tags = {
    Project   = "main-aws-environment"
    ManagedBy = "terraform"
  }
}

# Static provider metadata lookup for AZ placement (no pre-existing state required)
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking: VPC, subnets, internet gateway, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "main-vpc" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "main-public-subnet-1" })
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "main-public-subnet-2" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "main-internet-gateway" })
}

# Mandatory route path: 0.0.0.0/0 -> internet gateway so the RDS instance
# can be publicly reachable from the subnets below.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "main-public-route-table" })
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Database security group
###############################################################################

resource "aws_security_group" "database" {
  name        = "main-database-sg"
  description = "Allow inbound MySQL (3306) to the publicly accessible RDS instance"
  vpc_id      = aws_vpc.main.id

  # Explicitly justified by the requirement for a publicly accessible MySQL database.
  ingress {
    description = "MySQL from anywhere (publicly accessible MySQL requirement)"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "main-database-sg" })
}

###############################################################################
# RDS subnet group spanning two availability zones
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "main-db-subnet-group"
  subnet_ids = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  tags = merge(local.common_tags, { Name = "main-db-subnet-group" })
}

###############################################################################
# Master credentials: generated and persisted in AWS Secrets Manager
###############################################################################

resource "random_password" "master" {
  length           = 20
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "main-mysql-db/master-credentials"
  description = "Master credentials for the ${local.db_identifier} MySQL RDS instance"

  tags = merge(local.common_tags, { Name = "main-mysql-db-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username             = local.db_master_username
    password             = random_password.master.result
    engine               = "mysql"
    host                 = aws_db_instance.main.address
    port                 = aws_db_instance.main.port
    dbname               = local.db_name
    dbInstanceIdentifier = local.db_identifier
  })
}

###############################################################################
# MySQL RDS instance
###############################################################################

resource "aws_db_instance" "main" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0.39"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  storage_type          = "gp3"
  max_allocated_storage = 100

  db_name  = local.db_name
  username = local.db_master_username
  password = random_password.master.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  storage_encrypted   = true
  deletion_protection = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final"

  tags = merge(local.common_tags, { Name = local.db_identifier })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Connectivity outputs (no secret values are ever output)
###############################################################################

output "db_endpoint" {
  description = "Connection endpoint (host:port) for the MySQL database."
  value       = aws_db_instance.main.endpoint
}

output "db_address" {
  description = "Hostname of the MySQL database."
  value       = aws_db_instance.main.address
}

output "db_port" {
  description = "Port the MySQL database is listening on."
  value       = aws_db_instance.main.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials. Retrieve the password via Secrets Manager (get-secret-value); it is intentionally not exposed as an output."
  value       = aws_secretsmanager_secret.db_master.arn
}

# Terraform settings
# NOTE: The `provider "aws"` block (intended region: us-east-1) is intentionally
# omitted — the deployment harness injects the provider configuration externally.

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "trusted_office_cidr" {
  description = "Explicitly trusted office/VPN CIDR block allowed to reach MySQL (3306). The database is publicly reachable, so this scope must stay narrow; open CIDRs are rejected."
  type        = string
  default     = "10.20.0.0/24"

  validation {
    condition     = can(cidrhost(var.trusted_office_cidr, 0))
    error_message = "trusted_office_cidr must be a valid CIDR block, e.g. 10.20.0.0/24."
  }

  validation {
    condition     = var.trusted_office_cidr != "0.0.0.0/0" && var.trusted_office_cidr != "::/0"
    error_message = "trusted_office_cidr must be an explicit trusted range; 0.0.0.0/0 is not permitted for a publicly accessible database."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "main"
  environment = "production"

  db_name            = "maindb"
  db_master_username = "dbadmin"

  common_tags = {
    Project     = "main"
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking — VPC, public subnets, internet gateway, routing
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-subnet-b" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# RDS supporting resources — DB subnet group, security group, KMS, credentials
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict MySQL (3306) ingress to the trusted office/VPN CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from trusted office/VPN CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.trusted_office_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

resource "aws_kms_key" "rds" {
  description             = "Customer-managed key for main MySQL RDS storage and credential secret"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rds-kms" })
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}-mysql-master-credentials"
  description             = "Master credentials for the main MySQL RDS instance"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-mysql-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master.result
    engine   = "mysql"
    port     = 3306
    dbname   = local.db_name
  })
}

###############################################################################
# RDS MySQL instance
###############################################################################

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-mysql"
  engine         = "mysql"
  engine_version = "5.7.44" # NOTE: MySQL 5.7 is legacy; 5.7.44 is the final 5.7 patch — never omit the patch version.
  instance_class = "db.t3.medium"

  allocated_storage = 500
  storage_type      = "gp3"
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  db_name = local.db_name

  # Credentials are sourced exclusively from Secrets Manager — never inlined.
  # Schema-valid argument names for aws_db_instance (provider v5): username / password.
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = true # Public endpoint is intentional; ingress is tightly restricted via the db security group.

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true # Copies resource tags onto automated and final snapshots for traceability/recoverability.

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-mysql-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-mysql" })
}

###############################################################################
# Outputs
###############################################################################

output "rds_endpoint" {
  description = "Full connection endpoint (host:port) of the main MySQL RDS instance."
  value       = aws_db_instance.main.endpoint
}

output "rds_address" {
  description = "DNS hostname of the main MySQL RDS instance."
  value       = aws_db_instance.main.address
}

output "rds_port" {
  description = "Port the main MySQL RDS instance listens on."
  value       = aws_db_instance.main.port
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allowed_db_cidr_blocks" {
  description = "CIDR blocks explicitly allowed to reach MySQL on port 3306. Never set to 0.0.0.0/0."
  type        = list(string)
  default     = ["10.0.0.0/16"]

  validation {
    condition     = alltrue([for cidr in var.allowed_db_cidr_blocks : cidr != "0.0.0.0/0" && cidr != "::/0"])
    error_message = "Open ingress (0.0.0.0/0 or ::/0) is not permitted for the database security group."
  }
}

locals {
  name_prefix   = "main"
  db_identifier = "${local.name_prefix}-mysql-db"
  db_username   = "dbadmin"
  db_name       = "appdb"
  db_port       = 3306

  common_tags = {
    ManagedBy   = "terraform"
    Project     = "mysql-rds"
    Environment = "greenfield"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "public_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-0" })
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-1" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_0" {
  subnet_id      = aws_subnet.public_0.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict MySQL (3306) ingress to explicitly approved CIDR blocks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from approved CIDR blocks"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = var.allowed_db_cidr_blocks
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

resource "random_password" "db" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_lower        = 1
  min_upper        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_creds" {
  name        = "${local.name_prefix}/rds/${local.db_identifier}/master-credentials"
  description = "Master credentials for the ${local.db_identifier} MySQL instance"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-creds" })
}

resource "aws_secretsmanager_secret_version" "db_creds" {
  secret_id = aws_secretsmanager_secret.db_creds.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db.result
    engine   = "mysql"
    port     = aws_db_instance.main.port
    host     = aws_db_instance.main.address
    dbname   = local.db_name
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "DB subnet group spanning two AZs for ${local.db_identifier}"
  subnet_ids  = [aws_subnet.public_0.id, aws_subnet.public_1.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_db_instance" "main" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "5.7"
  instance_class = "db.t3.micro"

  allocated_storage = 10
  storage_type      = "gp2"
  storage_encrypted = true

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"
  copy_tags_to_snapshot   = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = local.db_identifier })
}

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL RDS instance"
  value       = aws_db_instance.main.endpoint
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials"
  value       = aws_secretsmanager_secret.db_creds.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  db_username = "dbadmin"
  db_name     = "appdb"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "rds" {
  name        = "rds-postgres-sg"
  description = "Allow PostgreSQL access on TCP 5432"
  vpc_id      = aws_vpc.main.id

  # Justified exception: the request explicitly mandates a publicly accessible
  # database, so PostgreSQL (TCP 5432) is open to 0.0.0.0/0. All other ingress
  # ports remain closed.
  ingress {
    description = "PostgreSQL from anywhere (required for publicly accessible RDS)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-postgres-sg"
  }
}

resource "random_password" "db_master" {
  length            = 24
  special           = true
  override_special  = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "rds-postgres-master-credentials"
  description = "Master credentials for the publicly accessible RDS PostgreSQL instance"

  tags = {
    Name = "rds-postgres-master-credentials"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

resource "aws_db_subnet_group" "postgres" {
  name        = "postgres-db-subnet-group"
  description = "Subnet group for the PostgreSQL RDS instance (subnets in distinct AZs)"
  subnet_ids  = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = {
    Name = "postgres-db-subnet-group"
  }
}

resource "aws_db_instance" "postgres" {
  identifier             = "postgres-db"
  engine                 = "postgres"
  engine_version         = "15.3"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_type           = "gp3"
  db_name                = local.db_name
  username               = local.db_username
  password               = random_password.db_master.result
  db_subnet_group_name   = aws_db_subnet_group.postgres.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true

  storage_encrypted         = true
  deletion_protection       = true
  backup_retention_period   = 7
  skip_final_snapshot       = false
  final_snapshot_identifier = "postgres-db-final-snapshot"
  copy_tags_to_snapshot     = true
  multi_az                  = false

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "postgres-db"
  }
}

output "db_endpoint" {
  description = "Connection endpoint for the PostgreSQL RDS instance"
  value       = aws_db_instance.postgres.endpoint
}

output "db_port" {
  description = "Port the PostgreSQL RDS instance listens on"
  value       = aws_db_instance.postgres.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret containing the database master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "main"
  db_username = "dbadmin"
  db_name     = "appdb"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-subnet-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-route-table"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = {
    Name = "${local.name_prefix}-db-subnet-group"
  }
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-db-sg"
  description = "Allow inbound PostgreSQL on port 5432 for the publicly accessible RDS instance"
  vpc_id      = aws_vpc.main.id

  # 0.0.0.0/0 on 5432 is intentional and justified: the RDS instance is
  # deployed as publicly accessible per the environment requirements.
  ingress {
    description = "PostgreSQL from anywhere (public access)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name_prefix}-db-sg"
  }
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the RDS PostgreSQL instance"

  tags = {
    Name = "${local.name_prefix}-db-master-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id     = aws_secretsmanager_secret.db_master.arn
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgres"
  engine_version = "15.3"
  instance_class = "db.t4g.micro"
  db_name        = local.db_name

  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  allocated_storage = 200
  storage_type      = "gp2"
  storage_encrypted = true

  publicly_accessible = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-snapshot"

  tags = {
    Name = "${local.name_prefix}-postgres"
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "rds_endpoint" {
  description = "Connection endpoint (host:port) for the RDS PostgreSQL database"
  value       = aws_db_instance.main.endpoint
}

output "rds_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials"
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "allowed_ingress_cidr" {
  description = "CIDR block permitted to reach MySQL on TCP 3306. Defaults to 0.0.0.0/0 because a publicly accessible MySQL instance was explicitly requested; restrict this in production."
  type        = string
  default     = "0.0.0.0/0"
}

locals {
  name = "rds-mysql-public"

  master_username = "admin"
  database_name   = "appdb"

  common_tags = {
    Project   = "rds-mysql-public"
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Greenfield networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# RDS subnet group (requires subnets in at least two AZs)
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.name}-subnets"
  description = "Subnet group spanning two AZs for the public MySQL RDS instance."
  subnet_ids  = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name}-subnets"
  })
}

# ---------------------------------------------------------------------------
# Master credentials (randomly generated, stored in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "rds_master" {
  length           = 20
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "rds_master" {
  name        = "${local.name}-master-password"
  description = "Master credentials for the ${local.name} MySQL RDS instance."

  tags = merge(local.common_tags, {
    Name = "${local.name}-master-password"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "rds_master" {
  secret_id = aws_secretsmanager_secret.rds_master.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = local.database_name
    username = local.master_username
    password = random_password.rds_master.result
  })
}

# ---------------------------------------------------------------------------
# Security group
# ---------------------------------------------------------------------------

# INTENTIONAL EXPOSURE: the user explicitly requested a publicly accessible
# MySQL instance, so TCP 3306 ingress is opened to the world (0.0.0.0/0) by
# default via var.allowed_ingress_cidr. Restrict the variable for production.
resource "aws_security_group" "rds" {
  name        = "${local.name}-sg"
  description = "Public MySQL access on TCP 3306 (intentionally open per requirements)."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from allowed CIDR (default 0.0.0.0/0 - explicitly requested public access)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [var.allowed_ingress_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name}-sg"
  })
}

# ---------------------------------------------------------------------------
# RDS MySQL instance
# ---------------------------------------------------------------------------

resource "aws_db_instance" "mysql" {
  identifier     = local.name
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.database_name
  username = local.master_username
  password = random_password.rds_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = true
  multi_az               = false

  backup_retention_period    = 7
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name}-final-${random_id.final_snapshot_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = local.name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (never expose the plaintext password)
# ---------------------------------------------------------------------------

output "rds_endpoint" {
  description = "Connection endpoint (host:port) of the MySQL RDS instance."
  value       = aws_db_instance.mysql.endpoint
}

output "rds_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials. Retrieve the password via AWS CLI/console (e.g. aws secretsmanager get-secret-value --secret-id <arn>); it is never printed by Terraform."
  value       = aws_secretsmanager_secret.rds_master.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata only (greenfield-safe lookup)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "db_master_username" {
  description = "Master username for the RDS MySQL 5.7 instance (never 'admin' or 'root')."
  type        = string
  default     = "dbadmin"
}

variable "allowed_admin_cidr_blocks" {
  description = "CIDR blocks allowed to connect to the database on TCP 3306. Defaults to 0.0.0.0/0 because the user explicitly requested a publicly accessible RDS instance; scope this down to an admin CIDR in real deployments."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  db_identifier = "mysql57-${var.environment}-db"

  common_tags = {
    Environment = var.environment
    Project     = "rds-mysql-5-7"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Network foundation (greenfield: created from scratch)
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# RDS subnet group (references only subnets created in this configuration)
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "rds" {
  name       = "mysql57-${var.environment}-db-subnet-group"
  subnet_ids = [aws_subnet.public[0].id, aws_subnet.public[1].id]

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-db-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Security group: ingress restricted to TCP 3306 only
# ---------------------------------------------------------------------------
resource "aws_security_group" "rds_public" {
  name        = "mysql57-${var.environment}-rds-sg"
  description = "Public access to the RDS MySQL instance on TCP 3306 only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from allowed CIDR blocks (default 0.0.0.0/0 per public-access requirement)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = var.allowed_admin_cidr_blocks
  }

  egress {
    description = "Outbound MySQL to the VPC CIDR only (replication/diagnostics)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "mysql57-${var.environment}-rds-sg"
  })
}

# ---------------------------------------------------------------------------
# Randomly generated master password (never plaintext in config)
# ---------------------------------------------------------------------------
resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?" # excludes '/', '@', '"' and space (RDS-restricted characters)
}

# ---------------------------------------------------------------------------
# Secrets Manager storage for the master password
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "db" {
  name                    = "rds/mysql57/${var.environment}/master-password"
  description             = "Master password for the ${local.db_identifier} RDS MySQL instance"
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id     = aws_secretsmanager_secret.db.id
  secret_string = random_password.db_master_password.result
}

# ---------------------------------------------------------------------------
# RDS MySQL 5.7 instance: 200 GB gp3, db.t3.micro, publicly accessible
# ---------------------------------------------------------------------------
resource "aws_db_instance" "mysql_db" {
  identifier = local.db_identifier

  engine                  = "mysql"
  engine_version          = "5.7.44"
  instance_class          = "db.t3.micro"
  allocated_storage       = 200
  max_allocated_storage   = 250
  storage_type            = "gp3"
  storage_encrypted       = true
  port                    = 3306
  publicly_accessible     = true
  multi_az                = false
  auto_minor_version_upgrade = true

  db_name                = null
  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds_public.id]

  username = var.db_master_username
  password = random_password.db_master_password.result

  deletion_protection     = true
  backup_retention_period = 7
  copy_tags_to_snapshot   = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (password value is never exposed; only the secret ARN)
# ---------------------------------------------------------------------------
output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the RDS MySQL 5.7 instance."
  value       = aws_db_instance.mysql_db.endpoint
}

output "db_instance_address" {
  description = "Hostname of the RDS MySQL 5.7 instance."
  value       = aws_db_instance.mysql_db.address
}

output "db_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master password."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

