provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resources for tagging"
  type        = string
  default     = "production"
}

locals {
  option_group_name = "option-group-pike"
}

resource "aws_db_option_group" "option_group_pike" {
  name                     = local.option_group_name
  option_group_description = "Option group for SQL Server Enterprise Edition, major engine version 11.00"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  tags = {
    Name        = local.option_group_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

variable "environment" {
  description = "Environment classification applied as a tag to all resources (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

locals {
  option_group_name = "option-group-pike"
  iam_role_name     = "rds-sqlserver-audit-cloudwatch-logs"
  iam_policy_name   = "rds-sqlserver-audit-cloudwatch-logs-policy"

  rds_log_group_arn_prefix = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/rds/*"

  common_tags = {
    Name        = local.option_group_name
    Environment = var.environment
  }
}

resource "aws_db_option_group" "pike" {
  name                     = local.option_group_name
  option_group_description = "SQL Server Enterprise Edition (major version 11.00) option group enabling Transparent Data Encryption (TDE) and SQL Server audit with CloudWatch Logs export."
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    option_name = "TDE"
  }

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "cloudwatch_logs_export"
      value = "true"
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "rds_audit_assume_role" {
  statement {
    sid     = "RDSServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_audit" {
  name               = local.iam_role_name
  description        = "Role assumed by Amazon RDS to publish SQL Server audit logs to Amazon CloudWatch Logs."
  assume_role_policy = data.aws_iam_policy_document.rds_audit_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "rds_audit_cloudwatch_logs" {
  statement {
    sid    = "RDSAuditLogDelivery"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      local.rds_log_group_arn_prefix,
      "${local.rds_log_group_arn_prefix}:*",
    ]
  }
}

resource "aws_iam_role_policy" "rds_audit_cloudwatch_logs" {
  name   = local.iam_policy_name
  role   = aws_iam_role.rds_audit.name
  policy = data.aws_iam_policy_document.rds_audit_cloudwatch_logs.json
}

output "option_group_id" {
  description = "ID of the RDS option group (reference this as option_group_name on a future aws_db_instance)."
  value       = aws_db_option_group.pike.id
}

output "option_group_arn" {
  description = "ARN of the RDS option group."
  value       = aws_db_option_group.pike.arn
}

output "audit_role_arn" {
  description = "ARN of the IAM role assumed by RDS to deliver SQL Server audit logs to CloudWatch Logs."
  value       = aws_iam_role.rds_audit.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  option_group_name = "option-group-pike"
  audit_bucket_name = "option-group-pike-audit-logs"
  audit_role_name   = "rds-sqlserver-audit-role"
  audit_policy_name = "rds-sqlserver-audit-s3-policy"

  common_tags = {
    Project   = "rds-sqlserver-ee-option-group"
    ManagedBy = "terraform"
  }
}

# -----------------------------------------------------------------------------
# S3 bucket that receives SQL Server audit logs (stateful: prevent_destroy)
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "audit_logs" {
  bucket = local.audit_bucket_name

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_bucket_name
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "audit_logs" {
  bucket = aws_s3_bucket.audit_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

# Deny any request to the bucket or its objects that is not made over TLS.
# Actions are explicitly enumerated (no wildcard principal combined with a
# wildcard action).
resource "aws_s3_bucket_policy" "audit_logs_tls_only" {
  bucket = aws_s3_bucket.audit_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:PutObject",
        ]
        Resource = [
          aws_s3_bucket.audit_logs.arn,
          "${aws_s3_bucket.audit_logs.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })

  depends_on = [
    aws_s3_bucket_public_access_block.audit_logs,
    aws_s3_bucket_server_side_encryption_configuration.audit_logs,
    aws_s3_bucket_versioning.audit_logs,
  ]
}

# -----------------------------------------------------------------------------
# IAM role trusted by RDS for SQLSERVER_AUDIT, plus least-privilege S3 policy
# -----------------------------------------------------------------------------
resource "aws_iam_role" "rds_sqlserver_audit" {
  name = local.audit_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRdsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_role_name
    },
  )
}

resource "aws_iam_policy" "rds_sqlserver_audit_s3" {
  name        = local.audit_policy_name
  description = "Least-privilege S3 access for RDS SQL Server audit log delivery"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PutAuditLogObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject"]
        Resource = ["${aws_s3_bucket.audit_logs.arn}/*"]
      },
      {
        Sid      = "ListAuditLogBucket"
        Effect   = "Allow"
        Action   = ["s3:ListBucket"]
        Resource = [aws_s3_bucket.audit_logs.arn]
      },
    ]
  })

  tags = merge(
    local.common_tags,
    {
      Name = local.audit_policy_name
    },
  )
}

resource "aws_iam_role_policy_attachment" "rds_sqlserver_audit_s3" {
  role       = aws_iam_role.rds_sqlserver_audit.name
  policy_arn = aws_iam_policy.rds_sqlserver_audit_s3.arn
}

# -----------------------------------------------------------------------------
# RDS option group for SQL Server EE (major version 11 -> "11.00")
# -----------------------------------------------------------------------------
resource "aws_db_option_group" "option_group_pike" {
  name                     = local.option_group_name
  option_group_description = "SQL Server EE option group with TDE and S3 audit logging"
  engine_name              = "sqlserver-ee"
  major_engine_version     = "11.00"

  option {
    option_name = "TDE"
  }

  option {
    option_name = "SQLSERVER_AUDIT"

    option_settings {
      name  = "IAM_ROLE_ARN"
      value = aws_iam_role.rds_sqlserver_audit.arn
    }

    option_settings {
      name  = "S3_BUCKET_ARN"
      value = aws_s3_bucket.audit_logs.arn
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.option_group_name
    },
  )

  depends_on = [
    aws_iam_role_policy_attachment.rds_sqlserver_audit_s3,
    aws_s3_bucket_policy.audit_logs_tls_only,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

variable "project" {
  description = "Project name applied to all resources through provider default_tags."
  type        = string
  default     = "aurora-mysql-proxy"
}

variable "environment" {
  description = "Environment name applied to all resources through provider default_tags."
  type        = string
  default     = "dev"
}

locals {
  name_prefix        = "aurora-mysql"
  db_master_username = "dbadmin"
  mysql_port         = 3306
}

# Well-known static lookups only: AZ metadata and the current account ID
# (used to scope the service trust policy). No discovery of pre-existing
# infrastructure.

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Network foundation: DNS-enabled VPC (required for RDS Proxy endpoint name
# resolution) with two private subnets across two AZs. No internet gateway,
# no public subnets, no NAT.
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-a"
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-private-b"
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-subnet-group"
  description = "Private subnets across two AZs for the Aurora MySQL cluster and RDS Proxy"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = {
    Name = "${local.name_prefix}-subnet-group"
  }
}

# -----------------------------------------------------------------------------
# Dedicated KMS key used for both Aurora storage encryption and Secrets Manager.
# -----------------------------------------------------------------------------

resource "aws_kms_key" "aurora" {
  description             = "Encrypts Aurora MySQL storage and the database credentials secret"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "aurora" {
  name          = "alias/${local.name_prefix}-encryption-key"
  target_key_id = aws_kms_key.aurora.key_id
}

# -----------------------------------------------------------------------------
# Security groups. SG bodies are declared separately from their rules so the
# proxy and cluster groups can reference each other without a dependency cycle.
# -----------------------------------------------------------------------------

resource "aws_security_group" "rds_proxy" {
  name        = "${local.name_prefix}-proxy-sg"
  description = "RDS Proxy: MySQL ingress from the VPC only, egress limited to the Aurora cluster"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-proxy-sg"
  }
}

resource "aws_security_group" "aurora" {
  name        = "${local.name_prefix}-cluster-sg"
  description = "Aurora MySQL: MySQL ingress from the RDS Proxy security group only"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-cluster-sg"
  }
}

resource "aws_vpc_security_group_ingress_rule" "proxy_ingress_from_vpc" {
  security_group_id = aws_security_group.rds_proxy.id
  description       = "MySQL from the VPC CIDR only - never 0.0.0.0/0"
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = local.mysql_port
  ip_protocol       = "tcp"
  to_port           = local.mysql_port
}

resource "aws_vpc_security_group_egress_rule" "proxy_egress_to_aurora" {
  security_group_id            = aws_security_group.rds_proxy.id
  description                  = "MySQL to the Aurora cluster security group only"
  referenced_security_group_id = aws_security_group.aurora.id
  from_port                    = local.mysql_port
  ip_protocol                  = "tcp"
  to_port                      = local.mysql_port
}

resource "aws_vpc_security_group_ingress_rule" "aurora_ingress_from_proxy" {
  security_group_id            = aws_security_group.aurora.id
  description                  = "MySQL from the RDS Proxy security group only"
  referenced_security_group_id = aws_security_group.rds_proxy.id
  from_port                    = local.mysql_port
  ip_protocol                  = "tcp"
  to_port                      = local.mysql_port
}

# -----------------------------------------------------------------------------
# Master credentials: generated password stored encrypted in Secrets Manager
# and reused by the Aurora cluster so the two stay in sync.
# -----------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 28
  special          = true
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
  override_special = "!#%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "db" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the Aurora MySQL cluster, consumed by RDS Proxy"
  kms_key_id  = aws_kms_key.aurora.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master_password.result
  })
}

# -----------------------------------------------------------------------------
# IAM: role trusted by the RDS service, with a least-privilege policy that only
# allows reading the single database secret and decrypting it with the
# dedicated KMS key.
# -----------------------------------------------------------------------------

resource "aws_iam_role" "db_proxy" {
  name = "${local.name_prefix}-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "db_proxy_secret_access" {
  name        = "${local.name_prefix}-proxy-secret-access"
  description = "Least-privilege access for RDS Proxy to the database secret and its KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadDatabaseSecret"
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.db.arn
      },
      {
        Sid      = "DecryptDatabaseSecret"
        Effect   = "Allow"
        Action   = "kms:Decrypt"
        Resource = aws_kms_key.aurora.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "db_proxy_secret_access" {
  role       = aws_iam_role.db_proxy.name
  policy_arn = aws_iam_policy.db_proxy_secret_access.arn
}

# -----------------------------------------------------------------------------
# Aurora MySQL cluster (encrypted, backed up, deletion-protected) reachable
# only through the RDS Proxy security group.
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  engine                    = "aurora-mysql"
  engine_version            = "8.0.mysql_aurora.3.05.2"
  database_name             = "appdb"
  master_username           = local.db_master_username
  master_password           = random_password.db_master_password.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.aurora.id]
  storage_encrypted         = true
  kms_key_id                = aws_kms_key.aurora.arn
  backup_retention_period   = 14
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final-snapshot"

  tags = {
    Name = "${local.name_prefix}-cluster"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier                            = "${local.name_prefix}-writer-1"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = "aurora-mysql"
  instance_class                        = "db.t4g.medium"
  availability_zone                     = data.aws_availability_zones.available.names[0]
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn
  performance_insights_retention_period = 7
  copy_tags_to_snapshot                 = true

  tags = {
    Name = "${local.name_prefix}-writer-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier                            = "${local.name_prefix}-reader-1"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = "aurora-mysql"
  instance_class                        = "db.t4g.medium"
  availability_zone                     = data.aws_availability_zones.available.names[1]
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  publicly_accessible                   = false
  performance_insights_enabled          = true
  performance_insights_kms_key_id       = aws_kms_key.aurora.arn
  performance_insights_retention_period = 7
  copy_tags_to_snapshot                 = true

  tags = {
    Name = "${local.name_prefix}-reader-1"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# RDS Proxy for connection pooling and management. engine_family = "MYSQL" is
# the provider-level value for any MySQL-protocol database, including Aurora
# MySQL 8.0 clusters. There is no separate "engine" argument on aws_db_proxy;
# "MYSQL" here denotes the engine family, which the provider schema restricts
# to MYSQL, POSTGRESQL, or SQLSERVER.
# -----------------------------------------------------------------------------

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.db_proxy.arn
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  vpc_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora MySQL master credentials from Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db.arn
  }

  tags = {
    Name = "${local.name_prefix}-proxy"
  }

  depends_on = [
    aws_iam_role_policy_attachment.db_proxy_secret_access,
    aws_secretsmanager_secret_version.db,
  ]
}

# The default target group's name is assigned automatically by the RDS service
# (it is always "default") and is a computed-only attribute in provider v5.x,
# so it must not be configured here. The group exists solely to carry the
# connection_pool_config for the proxy.

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

# Registers the cluster as the proxy target; AWS resolves it to the cluster's
# immutable resource ID (aws_rds_cluster.main.cluster_resource_id) and routes
# to the writer/reader endpoints. target_group_name reads the computed "name"
# of the default target group rather than hardcoding the string "default".

resource "aws_db_proxy_target" "aurora" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id
}

# -----------------------------------------------------------------------------
# Outputs (no secret values)
# -----------------------------------------------------------------------------

output "rds_proxy_endpoint" {
  description = "RDS Proxy endpoint for managed, pooled connections to Aurora MySQL."
  value       = aws_db_proxy.main.endpoint
}

output "aurora_cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster."
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster."
  value       = aws_rds_cluster.main.reader_endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ----------------------------------------------------------------------------
# Locals: values reused across the configuration
# ----------------------------------------------------------------------------
locals {
  name_prefix     = "aurora-mysql"
  database_name   = "appdb"
  master_username = "dbadmin"
  db_port         = 3306

  common_tags = {
    Project     = "aurora-mysql-proxy"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ----------------------------------------------------------------------------
# Networking foundation
# ----------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Private subnets shared by the Aurora MySQL cluster and the RDS Proxy"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

# ----------------------------------------------------------------------------
# Security groups: strict isolation, no open CIDRs anywhere
# ----------------------------------------------------------------------------
resource "aws_security_group" "aurora" {
  name        = "${local.name_prefix}-cluster-sg"
  description = "Aurora MySQL cluster: ingress restricted to the RDS Proxy only"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster-sg" })
}

resource "aws_security_group" "proxy" {
  name        = "${local.name_prefix}-proxy-sg"
  description = "RDS Proxy: ingress restricted to the VPC, egress restricted to the cluster"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-proxy-sg" })
}

# Cluster ingress: TCP 3306 from the proxy security group only.
resource "aws_vpc_security_group_ingress_rule" "aurora_from_proxy" {
  security_group_id            = aws_security_group.aurora.id
  description                  = "TCP 3306 from the RDS Proxy security group"
  referenced_security_group_id = aws_security_group.proxy.id
  ip_protocol                  = "tcp"
  from_port                    = local.db_port
  to_port                      = local.db_port
}

# Proxy ingress: TCP 3306 from the VPC CIDR only.
resource "aws_vpc_security_group_ingress_rule" "proxy_from_vpc" {
  security_group_id = aws_security_group.proxy.id
  description       = "TCP 3306 from inside the VPC"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = local.db_port
  to_port           = local.db_port
}

# Proxy egress: TCP 3306 scoped to the cluster security group only.
resource "aws_vpc_security_group_egress_rule" "proxy_to_aurora" {
  security_group_id            = aws_security_group.proxy.id
  description                  = "TCP 3306 to the Aurora cluster security group"
  referenced_security_group_id = aws_security_group.aurora.id
  ip_protocol                  = "tcp"
  from_port                    = local.db_port
  to_port                      = local.db_port
}

# ----------------------------------------------------------------------------
# Database credentials: generated, never hardcoded, stored in Secrets Manager
# ----------------------------------------------------------------------------
resource "random_password" "db_master" {
  length           = 28
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}-db-credentials"
  description = "Master credentials for the Aurora MySQL cluster"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.db_master.result
  })
}

# ----------------------------------------------------------------------------
# Aurora MySQL cluster and instances
# ----------------------------------------------------------------------------
resource "aws_rds_cluster" "aurora_mysql" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  engine                    = "aurora-mysql"
  engine_version            = "8.0.mysql_aurora.3.05.2"
  engine_mode               = "provisioned"
  database_name             = local.database_name
  master_username           = local.master_username
  master_password           = random_password.db_master.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.aurora.id]
  port                      = local.db_port
  storage_encrypted         = true
  backup_retention_period   = 7
  copy_tags_to_snapshot     = true
  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-cluster-final-snapshot"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cluster" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier                   = "${local.name_prefix}-writer"
  cluster_identifier           = aws_rds_cluster.aurora_mysql.id
  engine                       = "aurora-mysql"
  engine_version               = aws_rds_cluster.aurora_mysql.engine_version
  instance_class               = "db.r6g.large"
  db_subnet_group_name         = aws_db_subnet_group.main.name
  promotion_tier               = 0
  performance_insights_enabled = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-writer" })
}

resource "aws_rds_cluster_instance" "reader" {
  identifier                   = "${local.name_prefix}-reader"
  cluster_identifier           = aws_rds_cluster.aurora_mysql.id
  engine                       = "aurora-mysql"
  engine_version               = aws_rds_cluster.aurora_mysql.engine_version
  instance_class               = "db.r6g.large"
  db_subnet_group_name         = aws_db_subnet_group.main.name
  promotion_tier               = 1
  performance_insights_enabled = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-reader" })
}

# ----------------------------------------------------------------------------
# IAM for the RDS Proxy (least privilege: GetSecretValue on one secret only,
# granted via a single managed-policy + attachment pairing)
# ----------------------------------------------------------------------------
resource "aws_iam_role" "rds_proxy" {
  name = "${local.name_prefix}-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-proxy-role" })
}

resource "aws_iam_policy" "rds_proxy_secrets" {
  name        = "${local.name_prefix}-proxy-secrets-access"
  description = "Allows the RDS Proxy to read the Aurora credentials secret"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "secretsmanager:GetSecretValue"
        Resource = aws_secretsmanager_secret.db_credentials.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secrets" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secrets.arn
}

# ----------------------------------------------------------------------------
# RDS Proxy: connection pooling in front of the Aurora cluster
# ----------------------------------------------------------------------------
resource "aws_db_proxy" "main" {
  name                   = "aurora-mysql-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  vpc_security_group_ids = [aws_security_group.proxy.id]

  idle_client_timeout = 1800
  debug_logging       = false
  require_tls         = true

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora master credentials resolved from Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(local.common_tags, { Name = "aurora-mysql-proxy" })

  depends_on = [
    aws_iam_role_policy_attachment.rds_proxy_secrets,
    aws_secretsmanager_secret_version.db_credentials,
  ]
}

resource "aws_db_proxy_default_target_group" "default" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.default.name
  db_cluster_identifier = aws_rds_cluster.aurora_mysql.id
}

# ----------------------------------------------------------------------------
# Outputs (non-sensitive only; no credentials exposed)
# ----------------------------------------------------------------------------
output "aurora_cluster_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.aurora_mysql.endpoint
}

output "aurora_cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.aurora_mysql.reader_endpoint
}

output "rds_proxy_endpoint" {
  description = "Connection endpoint of the RDS Proxy"
  value       = aws_db_proxy.main.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# =============================================================================
# Static, well-known lookups only (no pre-existing infrastructure is assumed)
# =============================================================================
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# =============================================================================
# Locals
# =============================================================================
locals {
  project            = "aurora-mysql"
  environment        = "production"
  vpc_cidr           = "10.0.0.0/16"
  db_master_username = "dbadmin"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# =============================================================================
# Networking: VPC, private database subnets, and DB subnet group
# =============================================================================
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-subnet-${count.index + 1}"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.project}-db-subnet-group"
  description = "Private subnets hosting the Aurora MySQL database tier"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-subnet-group"
  })
}

# =============================================================================
# Security groups
# =============================================================================
resource "aws_security_group" "rds_proxy" {
  name        = "${local.project}-proxy-sg"
  description = "RDS Proxy ingress: MySQL 3306 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to the Aurora cluster and the Secrets Manager endpoint inside the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-sg"
  })
}

resource "aws_security_group" "aurora" {
  name        = "${local.project}-aurora-sg"
  description = "Aurora cluster ingress: MySQL 3306 from the RDS Proxy security group only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the RDS Proxy security group"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.rds_proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-sg"
  })
}

resource "aws_security_group" "secretsmanager_endpoint" {
  name        = "${local.project}-secrets-endpoint-sg"
  description = "HTTPS access to the Secrets Manager interface VPC endpoint"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-secretsmanager-endpoint-sg"
  })
}

# Interface VPC endpoint so the RDS Proxy can reach Secrets Manager from a
# VPC that has no internet access.
resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.secretsmanager_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-secretsmanager-endpoint"
  })
}

# =============================================================================
# KMS encryption, generated credentials, and Secrets Manager
# =============================================================================
resource "aws_kms_key" "db_credentials" {
  description             = "Customer managed key encrypting the Aurora MySQL database credentials secret"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-credentials-key"
  })
}

resource "aws_kms_alias" "db_credentials" {
  name          = "alias/${local.project}-db-credentials"
  target_key_id = aws_kms_key.db_credentials.key_id
}

resource "random_password" "db_master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.project}/db/credentials"
  description = "Master credentials for the Aurora MySQL cluster"
  kms_key_id  = aws_kms_key.db_credentials.arn

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-credentials"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.db_master_username
    password = random_password.db_master_password.result
  })
}

# =============================================================================
# IAM for the RDS Proxy
# =============================================================================
data "aws_iam_policy_document" "rds_proxy_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_proxy" {
  name               = "${local.project}-proxy-role"
  description        = "Assumed by RDS Proxy to read database credentials"
  assume_role_policy = data.aws_iam_policy_document.rds_proxy_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-role"
  })
}

data "aws_iam_policy_document" "rds_proxy_secret_access" {
  statement {
    sid       = "ReadDatabaseCredentialsSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:DescribeSecret", "secretsmanager:GetSecretValue"]
    resources = [aws_secretsmanager_secret.db_credentials.arn]
  }

  statement {
    sid       = "DecryptDatabaseCredentialsSecret"
    effect    = "Allow"
    actions   = ["kms:Decrypt"]
    resources = [aws_kms_key.db_credentials.arn]
  }
}

resource "aws_iam_role_policy" "rds_proxy_secret_access" {
  name   = "${local.project}-proxy-secret-access"
  role   = aws_iam_role.rds_proxy.name
  policy = data.aws_iam_policy_document.rds_proxy_secret_access.json
}

resource "aws_iam_policy" "rds_proxy_secret_access" {
  name        = "${local.project}-proxy-secret-access"
  description = "Least-privilege access for the RDS Proxy to the database credentials secret"
  policy      = data.aws_iam_policy_document.rds_proxy_secret_access.json

  tags = merge(local.common_tags, {
    Name = "${local.project}-proxy-secret-access-policy"
  })
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secret_access" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secret_access.arn
}

# =============================================================================
# Aurora MySQL cluster and instances
# =============================================================================
resource "aws_rds_cluster_parameter_group" "main" {
  name        = "${local.project}-cluster-parameter-group"
  family      = "aurora-mysql8.0"
  description = "Cluster parameters for the Aurora MySQL cluster"

  parameter {
    name  = "slow_query_log"
    value = "1"
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-cluster-parameter-group"
  })
}

resource "aws_rds_cluster" "main" {
  cluster_identifier = "${local.project}-cluster"
  engine             = "aurora-mysql"
  engine_mode        = "provisioned"
  database_name      = "appdb"
  master_username    = local.db_master_username

  # Master credentials are managed by RDS in Secrets Manager; the RDS-created
  # master user secret is encrypted with the dedicated customer-managed KMS key.
  manage_master_user_password   = true
  master_user_secret_kms_key_id = aws_kms_key.db_credentials.arn

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.aurora.id]

  backup_retention_period      = 5
  preferred_backup_window      = "07:00-09:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"

  storage_encrypted         = true
  kms_key_id                = aws_kms_key.db_credentials.arn
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.project}-final-snapshot"

  enabled_cloudwatch_logs_exports = ["error", "slowquery"]
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.main.name

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-cluster"
  })

  depends_on = [aws_secretsmanager_secret_version.db_credentials]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "main" {
  count = 2

  identifier         = "${local.project}-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.main.id
  engine             = "aurora-mysql"
  engine_version     = aws_rds_cluster.main.engine_version
  instance_class     = "db.r6g.large"

  availability_zone = data.aws_availability_zones.available.names[count.index]

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.db_credentials.arn

  tags = merge(local.common_tags, {
    Name = "${local.project}-aurora-instance-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# =============================================================================
# RDS Proxy and target wiring
# =============================================================================
resource "aws_db_proxy" "main" {
  name                   = "${local.project}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  vpc_subnet_ids         = aws_subnet.private[*].id

  auth {
    auth_scheme = "SECRETS"
    description = "Database credentials stored in Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-db-proxy"
  })

  depends_on = [
    aws_iam_role_policy.rds_proxy_secret_access,
    aws_iam_role_policy_attachment.rds_proxy_secret_access,
    aws_secretsmanager_secret_version.db_credentials,
  ]
}

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

# The target type (TRACKED_CLUSTER) is computed automatically by the provider
# from db_cluster_identifier and must not be set explicitly.
resource "aws_db_proxy_target" "main" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id

  depends_on = [aws_db_proxy_default_target_group.main]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# User-controlled variables (no credentials, IDs, or infrastructure attributes)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Short name used to prefix and tag all resources (lowercase letters, digits, hyphens)."
  type        = string
  default     = "aurora-proxy"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,61}[a-z0-9]$", var.project_name))
    error_message = "project_name must be 3-63 lowercase alphanumeric characters or hyphens, starting with a letter."
  }
}

variable "master_username" {
  description = "Master username for the Aurora MySQL cluster (never use 'admin')."
  type        = string
  default     = "aurora_admin"

  validation {
    condition     = var.master_username != "admin" && can(regex("^[a-zA-Z][a-zA-Z0-9_]{0,62}$", var.master_username))
    error_message = "master_username must be 1-63 alphanumeric or underscore characters and must not be 'admin'."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = var.project_name

  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
    Project     = var.project_name
  }
}

# -----------------------------------------------------------------------------
# Data sources (static provider metadata only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Runtime-generated database credentials and Secrets Manager storage
# -----------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 26
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "random_id" "final_snapshot" {
  byte_length = 4
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}-db-master"
  description = "Master credentials for the ${local.name_prefix} Aurora MySQL cluster"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-secret"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = var.master_username
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

# Aurora cluster security group: MySQL ingress ONLY from the RDS Proxy SG
resource "aws_security_group" "db_cluster" {
  name        = "${local.name_prefix}-db-cluster-sg"
  description = "Aurora MySQL cluster - allow MySQL only from the RDS Proxy security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from RDS Proxy only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.rds_proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-cluster-sg"
  })
}

# RDS Proxy security group: MySQL ingress ONLY from the VPC CIDR
resource "aws_security_group" "rds_proxy" {
  name        = "${local.name_prefix}-rds-proxy-sg"
  description = "RDS Proxy - allow MySQL from within the VPC, egress limited to MySQL and Secrets Manager"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL to the Aurora cluster within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "HTTPS to the Secrets Manager interface endpoint within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-proxy-sg"
  })
}

# Secrets Manager endpoint security group: HTTPS ingress ONLY from the VPC CIDR
resource "aws_security_group" "secrets_endpoint" {
  name        = "${local.name_prefix}-secrets-endpoint-sg"
  description = "Secrets Manager interface endpoint - allow HTTPS from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secrets-endpoint-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# Private Secrets Manager interface endpoint so the proxy can retrieve
# credentials without internet or NAT access
resource "aws_vpc_endpoint" "secretsmanager" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.secretsmanager"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.secrets_endpoint.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secretsmanager-endpoint"
  })
}

# -----------------------------------------------------------------------------
# IAM role for RDS Proxy (least privilege)
# -----------------------------------------------------------------------------

resource "aws_iam_role" "rds_proxy" {
  name = "${local.name_prefix}-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-proxy-role"
  })
}

resource "aws_iam_role_policy" "rds_proxy_secrets" {
  name = "${local.name_prefix}-rds-proxy-secrets-policy"
  role = aws_iam_role.rds_proxy.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ReadProxySecret"
        Effect   = "Allow"
        Action   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
        Resource = [aws_secretsmanager_secret.db_master.arn]
      },
      {
        Sid      = "DecryptProxySecret"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = ["*"]
        Condition = {
          StringEquals = {
            "kms:ViaService" = "secretsmanager.us-east-1.amazonaws.com"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Aurora MySQL cluster
# -----------------------------------------------------------------------------

resource "aws_rds_cluster" "main" {
  cluster_identifier        = "${local.name_prefix}-cluster"
  engine                    = "aurora-mysql"
  engine_version            = "8.0.mysql_aurora.3.08.0"
  engine_mode               = "provisioned"
  database_name             = "appdb"
  master_username           = var.master_username
  master_password           = random_password.db_master.result
  db_subnet_group_name      = aws_db_subnet_group.main.name
  vpc_security_group_ids    = [aws_security_group.db_cluster.id]
  storage_encrypted         = true
  backup_retention_period   = 7
  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_id.final_snapshot.hex}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "main" {
  count = 2

  identifier                            = "${local.name_prefix}-instance-${count.index}"
  cluster_identifier                    = aws_rds_cluster.main.id
  engine                                = aws_rds_cluster.main.engine
  engine_version                        = aws_rds_cluster.main.engine_version
  instance_class                        = "db.r6g.large"
  db_subnet_group_name                  = aws_db_subnet_group.main.name
  availability_zone                     = element(data.aws_availability_zones.available.names, count.index)
  publicly_accessible                   = false
  auto_minor_version_upgrade            = false
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-${count.index}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# RDS Proxy
# -----------------------------------------------------------------------------

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_subnet_ids         = aws_subnet.private[*].id
  vpc_security_group_ids = [aws_security_group.rds_proxy.id]
  require_tls            = true
  debug_logging          = false

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora master credentials from Secrets Manager"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_master.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy"
  })

  depends_on = [
    aws_iam_role_policy.rds_proxy_secrets,
    aws_secretsmanager_secret_version.db_master,
    aws_vpc_endpoint.secretsmanager,
  ]
}

# NOTE: aws_db_proxy_default_target_group does not support tagging at the
# provider/RDS API level. Tagging compliance is satisfied by the parent
# aws_db_proxy.main, which carries the merged common_tags.
resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name         = aws_db_proxy.main.name
  target_group_name     = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.cluster_identifier

  depends_on = [aws_rds_cluster_instance.main]
}

# -----------------------------------------------------------------------------
# Outputs (non-sensitive endpoints only)
# -----------------------------------------------------------------------------

output "aurora_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.reader_endpoint
}

output "rds_proxy_endpoint" {
  description = "Endpoint of the RDS Proxy"
  value       = aws_db_proxy.main.endpoint
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used to derive resource names and tags (non-infrastructure value only)"
  type        = string
  default     = "production"
}

locals {
  name_prefix     = "${var.environment}-aurora-mysql"
  master_username = "dbadmin"

  common_tags = {
    Project     = "aurora-mysql-rds-proxy"
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "proxy" {
  name        = "${local.name_prefix}-proxy-sg"
  description = "RDS Proxy security group - MySQL ingress from application tier within VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC (application tier)"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound so the proxy can reach the Aurora cluster"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy-sg"
  })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Aurora MySQL security group - MySQL ingress only from the RDS Proxy"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the RDS Proxy security group only"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.proxy.id]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_kms_key" "db_credentials" {
  description             = "Customer managed KMS key used to encrypt the Aurora MySQL credentials secret"
  enable_key_rotation     = true
  is_enabled              = true
  deletion_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials-key"
  })
}

resource "aws_kms_alias" "db_credentials" {
  name          = "alias/${local.name_prefix}-db-credentials"
  target_key_id = aws_kms_key.db_credentials.key_id
}

resource "random_password" "master_password" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name                    = "${local.name_prefix}-db-credentials"
  description             = "Master credentials for the Aurora MySQL cluster, consumed by RDS Proxy"
  kms_key_id              = aws_kms_key.db_credentials.arn
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master_password.result
  })
}

resource "aws_iam_role" "rds_proxy" {
  name        = "${local.name_prefix}-proxy-role"
  description = "IAM role assumed by RDS Proxy to read the database credentials secret"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRDSProxyAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "rds_proxy_secret_access" {
  name        = "${local.name_prefix}-proxy-secret-access"
  description = "Least-privilege access for RDS Proxy: read the credentials secret and decrypt it with the customer managed KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadDatabaseSecret"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = [
          aws_secretsmanager_secret.db_credentials.arn
        ]
      },
      {
        Sid      = "DecryptDatabaseSecret"
        Effect   = "Allow"
        Action   = ["kms:Decrypt"]
        Resource = [aws_kms_key.db_credentials.arn]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "rds_proxy_secret_access" {
  role       = aws_iam_role.rds_proxy.name
  policy_arn = aws_iam_policy.rds_proxy_secret_access.arn
}

resource "aws_rds_cluster" "main" {
  cluster_identifier              = "${local.name_prefix}-cluster"
  engine                          = "aurora-mysql"
  engine_version                  = "8.0.mysql_aurora.3.05.2"
  engine_mode                     = "provisioned"
  database_name                   = "appdb"
  master_username                 = local.master_username
  master_password                 = random_password.master_password.result
  db_subnet_group_name            = aws_db_subnet_group.main.name
  vpc_security_group_ids          = [aws_security_group.db.id]
  storage_encrypted               = true
  kms_key_id                      = aws_kms_key.db_credentials.arn
  port                            = 3306
  backup_retention_period         = 7
  preferred_backup_window         = "03:00-04:00"
  preferred_maintenance_window    = "sun:04:30-sun:05:30"
  deletion_protection             = true
  copy_tags_to_snapshot           = true
  enabled_cloudwatch_logs_exports = ["error"]
  apply_immediately               = true
  skip_final_snapshot             = false
  final_snapshot_identifier       = "snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cluster"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "writer" {
  identifier_prefix                     = "aurora-mysql-"
  cluster_identifier                    = aws_rds_cluster.main.id
  instance_class                        = "db.r6g.large"
  engine                                = "aurora-mysql"
  engine_version                        = aws_rds_cluster.main.engine_version
  availability_zone                     = data.aws_availability_zones.available.names[0]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  auto_minor_version_upgrade            = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_rds_cluster_instance" "reader" {
  identifier_prefix                     = "aurora-mysql-"
  cluster_identifier                    = aws_rds_cluster.main.id
  instance_class                        = "db.r6g.large"
  engine                                = "aurora-mysql"
  engine_version                        = aws_rds_cluster.main.engine_version
  availability_zone                     = data.aws_availability_zones.available.names[1]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  auto_minor_version_upgrade            = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-2"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_proxy" "main" {
  name                   = "${local.name_prefix}-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  role_arn               = aws_iam_role.rds_proxy.arn
  vpc_security_group_ids = [aws_security_group.proxy.id]
  vpc_subnet_ids         = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  auth {
    auth_scheme = "SECRETS"
    description = "Aurora MySQL master credentials"
    iam_auth    = "DISABLED"
    secret_arn  = aws_secretsmanager_secret.db_credentials.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-proxy"
  })

  depends_on = [
    aws_iam_role_policy_attachment.rds_proxy_secret_access,
    aws_secretsmanager_secret_version.db_credentials
  ]
}

resource "aws_db_proxy_default_target_group" "main" {
  db_proxy_name = aws_db_proxy.main.name

  connection_pool_config {
    connection_borrow_timeout    = 120
    max_connections_percent      = 100
    max_idle_connections_percent = 50
    session_pinning_filters      = ["EXCLUDE_VARIABLE_SETS"]
  }
}

resource "aws_db_proxy_target" "main" {
  db_proxy_name        = aws_db_proxy.main.name
  target_group_name    = aws_db_proxy_default_target_group.main.name
  db_cluster_identifier = aws_rds_cluster.main.id
}

output "aurora_cluster_writer_endpoint" {
  description = "Writer endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.endpoint
}

output "aurora_cluster_reader_endpoint" {
  description = "Reader endpoint of the Aurora MySQL cluster"
  value       = aws_rds_cluster.main.reader_endpoint
}

output "rds_proxy_endpoint" {
  description = "Connection endpoint of the RDS Proxy"
  value       = aws_db_proxy.main.endpoint
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials (secret value is never exposed)"
  value       = aws_secretsmanager_secret.db_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging all Lightsail resources."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_lightsail_key_pair" "main" {
  name = "basic-lightsail-key"

  tags = local.common_tags
}

resource "aws_lightsail_instance" "basic_lightsail" {
  name              = "basic-lightsail"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_instance_public_ports" "basic_lightsail" {
  instance_name = aws_lightsail_instance.basic_lightsail.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
  }

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
  }
}

resource "aws_lightsail_static_ip" "basic_lightsail" {
  name = "basic-lightsail-ip"
}

resource "aws_lightsail_static_ip_attachment" "basic_lightsail" {
  static_ip_name = aws_lightsail_static_ip.basic_lightsail.id
  instance_name  = aws_lightsail_instance.basic_lightsail.id
}

output "static_public_ip" {
  description = "Stable public IPv4 address attached to the Lightsail instance."
  value       = aws_lightsail_static_ip.basic_lightsail.ip_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "instance_name_prefix" {
  description = "Prefix used to name Lightsail resources in this configuration."
  type        = string
  default     = "lightsail"
}

variable "environment" {
  description = "Value applied to the Environment tag on Lightsail resources."
  type        = string
  default     = "dev"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the web server."
  type        = string
  default     = "nano_3_0"
}

variable "admin_ssh_cidr" {
  description = "CIDR block permitted to reach TCP/22 (SSH) on the instance. Must not be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = can(cidrnetmask(var.admin_ssh_cidr)) && var.admin_ssh_cidr != "0.0.0.0/0"
    error_message = "admin_ssh_cidr must be a valid IPv4 CIDR and must not be 0.0.0.0/0 (SSH must stay restricted)."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  instance_name = "${var.instance_name_prefix}-web"
}

resource "aws_lightsail_key_pair" "main" {
  name = "${var.instance_name_prefix}-key"
}

resource "aws_lightsail_instance" "main" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = {
    Name        = local.instance_name
    Environment = var.environment
  }

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail

    dnf update -y

    dnf install -y nginx

    cat > /usr/share/nginx/html/index.html <<'HTML'
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <title>Lightsail Web Server</title>
      </head>
      <body>
        <h1>Hello from Amazon Lightsail</h1>
        <p>This landing page was provisioned by Terraform user_data at first boot.</p>
      </body>
    </html>
    HTML

    systemctl enable nginx
    systemctl start nginx
  EOF

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_instance_public_ports" "main" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = [var.admin_ssh_cidr]
  }
}

output "instance_public_ip_address" {
  description = "Public IPv4 address of the Lightsail web instance."
  value       = aws_lightsail_instance.main.public_ip_address
}

output "instance_arn" {
  description = "ARN of the Lightsail web instance."
  value       = aws_lightsail_instance.main.arn
}

output "key_pair_name" {
  description = "Name of the Lightsail key pair attached to the instance."
  value       = aws_lightsail_key_pair.main.name
}

output "key_pair_private_key" {
  description = "Private key for the Lightsail key pair. Retrieve once to seed your SSH agent; do not commit or distribute."
  value       = aws_lightsail_key_pair.main.private_key
  sensitive   = true
}

