terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata lookup only - no dependency on pre-existing infrastructure
data "aws_availability_zones" "available" {
  state = "available"
}

variable "lightsail_bundle" {
  description = "Lightsail bundle ID controlling the WordPress instance size."
  type        = string
  default     = "nano_3_0"

  validation {
    condition     = can(regex("^[a-z0-9_]+$", var.lightsail_bundle))
    error_message = "Bundle ID must be a valid Lightsail bundle identifier (lowercase letters, numbers, underscores)."
  }
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9-]{1,20}$", var.environment))
    error_message = "Environment must be 1-20 lowercase alphanumeric or hyphen characters."
  }
}

locals {
  wordpress_name = "wordpress-${var.environment}"

  common_tags = {
    Name        = local.wordpress_name
    Environment = var.environment
  }
}

# SSH key pair provisioned in-config; Lightsail generates the key material.
# The private_key attribute is sensitive and is intentionally never exposed.
resource "aws_lightsail_key_pair" "wordpress" {
  name = "${local.wordpress_name}-key"

  tags = local.common_tags
}

resource "aws_lightsail_instance" "wordpress" {
  name              = local.wordpress_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "wordpress"
  bundle_id         = var.lightsail_bundle
  key_pair_name     = aws_lightsail_key_pair.wordpress.name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Lightsail static IPs cannot be tagged - the resource schema exposes only `name`.
resource "aws_lightsail_static_ip" "wordpress" {
  name = "${local.wordpress_name}-ip"
}

resource "aws_lightsail_static_ip_attachment" "wordpress" {
  static_ip_name = aws_lightsail_static_ip.wordpress.name
  instance_name  = aws_lightsail_instance.wordpress.name
}

# Open ONLY TCP 80 (HTTP) and TCP 443 (HTTPS) to the internet.
# Port 22 (SSH) and all other ports remain closed; Lightsail public ports
# cannot be CIDR-restricted, so management ports must never be published here.
resource "aws_lightsail_instance_public_ports" "wordpress" {
  instance_name = aws_lightsail_instance.wordpress.name

  port_info {
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }
}

output "instance_name" {
  description = "Name of the Lightsail WordPress instance."
  value       = aws_lightsail_instance.wordpress.name
}

output "static_public_ip" {
  description = "Stable public IPv4 address attached to the Lightsail WordPress instance."
  value       = aws_lightsail_static_ip.wordpress.ip_address
}

output "availability_zone" {
  description = "Availability Zone hosting the Lightsail WordPress instance."
  value       = aws_lightsail_instance.wordpress.availability_zone
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (user-controlled, non-infrastructure values with safe defaults)
# ---------------------------------------------------------------------------

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "web-instance"
}

variable "blueprint_id" {
  description = "Lightsail blueprint ID (OS image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle ID (instance size) for the instance."
  type        = string
  default     = "nano_3_0"
}

variable "tags" {
  description = "Tags applied to Lightsail resources that support tagging."
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Data sources (static provider metadata only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# SSH access credentials
# ---------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "lightsail_key_pair" {
  name = "${var.instance_name}-key-pair"
}

# ---------------------------------------------------------------------------
# Lightsail instance
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance" "web_instance" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.lightsail_key_pair.name

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
  EOF

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Static IPv4 address (independent resource so it survives instance replacement)
# ---------------------------------------------------------------------------

resource "aws_lightsail_static_ip" "static_ip" {
  name = "${var.instance_name}-static-ip"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_static_ip_attachment" "static_ip_attachment" {
  static_ip_name = aws_lightsail_static_ip.static_ip.name
  instance_name  = aws_lightsail_instance.web_instance.name
}

# ---------------------------------------------------------------------------
# Firewall: only the required ports/protocols are opened
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "web_instance_ports" {
  instance_name = aws_lightsail_instance.web_instance.name

  port_info {
    protocol   = "tcp"
    from_port  = 22
    to_port    = 22
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "static_ip_address" {
  description = "Allocated static IPv4 address attached to the Lightsail instance."
  value       = aws_lightsail_static_ip.static_ip.ip_address
}

output "instance_public_ip_address" {
  description = "Public IPv4 address of the Lightsail instance."
  value       = aws_lightsail_instance.web_instance.public_ip_address
}

output "instance_name" {
  description = "Name of the Lightsail instance."
  value       = aws_lightsail_instance.web_instance.name
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

#------------------------------------------------------------------------------
# Variables — non-infrastructure values only, all defaulted so that
# `terraform apply` runs unattended.
#------------------------------------------------------------------------------

variable "instance_name" {
  description = "Name of the Lightsail instance."
  type        = string
  default     = "web-dualstack"
}

variable "blueprint_id" {
  description = "Lightsail blueprint (operating system image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the instance."
  type        = string
  default     = "nano_3_0"
}

variable "admin_ssh_cidrs" {
  description = "IPv4 CIDR blocks permitted to reach TCP 22 (SSH). Replace the documentation-range default with your administrator networks."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "admin_ssh_ipv6_cidrs" {
  description = "IPv6 CIDR blocks permitted to reach TCP 22 (SSH). Replace the documentation-range default with your administrator networks."
  type        = list(string)
  default     = ["2001:db8::/32"]
}

variable "tags" {
  description = "Tags applied to the Lightsail instance and key pair. Note: aws_lightsail_static_ip does not support tagging in the AWS provider schema, so the static IP is left untagged."
  type        = map(string)
  default = {
    Name      = "web-dualstack"
    ManagedBy = "terraform"
  }
}

#------------------------------------------------------------------------------
# Data source — static, well-known AZ metadata for the current region
# (the AZ name is never hardcoded).
#------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

#------------------------------------------------------------------------------
# Lightsail key pair for SSH access. The generated private key material is
# never embedded in this configuration, in variables/locals, or in outputs.
#------------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "web" {
  name = "${var.instance_name}-key"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Lightsail instance — dualstack is declared via ip_address_type = "dualstack"
# (the provider schema's only supported mechanism for dual addressing): the
# instance receives a public IPv4 address plus auto-assigned public IPv6
# addresses. Lightsail manages its own networking outside of any VPC, so no
# VPC/subnet/security-group resources are used.
#------------------------------------------------------------------------------

resource "aws_lightsail_instance" "web" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.web.name
  ip_address_type   = "dualstack"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

#------------------------------------------------------------------------------
# Instance firewall — replaces the permissive defaults with least-privilege
# rules:
#   TCP 80 / TCP 443 : open to the world over IPv4 and IPv6 (public web access)
#   TCP 22 (SSH)     : restricted to the administrator CIDR variables
#------------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "web" {
  instance_name = aws_lightsail_instance.web.name

  port_info {
    from_port  = 80
    to_port    = 80
    protocol   = "tcp"
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    from_port  = 443
    to_port    = 443
    protocol   = "tcp"
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    from_port  = 22
    to_port    = 22
    protocol   = "tcp"
    cidrs      = var.admin_ssh_cidrs
    ipv6_cidrs = var.admin_ssh_ipv6_cidrs
  }
}

#------------------------------------------------------------------------------
# Static IP — keeps the public IPv4 address stable across stop/start, while
# the IPv6 address remains auto-assigned by Lightsail. This resource does not
# support tags in the provider schema, so no tags argument is set here.
#------------------------------------------------------------------------------

resource "aws_lightsail_static_ip" "web" {
  name = "${var.instance_name}-static-ip"
}

resource "aws_lightsail_static_ip_attachment" "web" {
  static_ip_name = aws_lightsail_static_ip.web.name
  instance_name  = aws_lightsail_instance.web.name
}

#------------------------------------------------------------------------------
# Outputs — dualstack endpoints (none contain secrets).
#------------------------------------------------------------------------------

output "public_ipv4_address" {
  description = "Stable public IPv4 address of the Lightsail instance (static IP)."
  value       = aws_lightsail_static_ip.web.ip_address
}

output "ipv6_addresses" {
  description = "Auto-assigned public IPv6 addresses of the Lightsail instance (dualstack)."
  value       = aws_lightsail_instance.web.ipv6_addresses
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for the Lightsail instance, SSH key pair, and related resource naming."
  type        = string
  default     = "greenfield"
}

variable "blueprint_id" {
  description = "Lightsail blueprint (operating system image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "bundle_id" {
  description = "Lightsail bundle (instance size) for the instance."
  type        = string
  default     = "micro_3_0"
}

variable "ssh_allowed_cidr" {
  description = "Admin CIDR block permitted to reach SSH (TCP/22) on the Lightsail instance. Must never be 0.0.0.0/0."
  type        = string
  default     = "203.0.113.0/24"

  validation {
    condition     = var.ssh_allowed_cidr != "0.0.0.0/0" && can(cidrnetmask(var.ssh_allowed_cidr))
    error_message = "ssh_allowed_cidr must be a valid CIDR block and must not be the open internet (0.0.0.0/0)."
  }
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "greenfield"
    ManagedBy = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  ssh_key_pair_name   = "${var.project_name}-ssh-key"
  ssh_key_secret_name = "${var.project_name}-ssh-private-key"
  static_ip_name      = "${var.project_name}-static-ip"
}

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_lightsail_key_pair" "main" {
  name       = local.ssh_key_pair_name
  public_key = tls_private_key.main.public_key_openssh

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "ssh_key" {
  name        = local.ssh_key_secret_name
  description = "SSH private key for the ${var.project_name} Lightsail instance."

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "ssh_key" {
  secret_id     = aws_secretsmanager_secret.ssh_key.arn
  secret_string = tls_private_key.main.private_key_openssh
}

resource "aws_lightsail_instance" "main" {
  name              = var.project_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.blueprint_id
  bundle_id         = var.bundle_id
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_static_ip" "main" {
  name = local.static_ip_name
}

resource "aws_lightsail_static_ip_attachment" "main" {
  static_ip_name = aws_lightsail_static_ip.main.name
  instance_name  = aws_lightsail_instance.main.name
}

resource "aws_lightsail_instance_public_ports" "main" {
  instance_name = aws_lightsail_instance.main.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = [var.ssh_allowed_cidr]
  }
}

output "static_ip" {
  description = "Public static IP address attached to the Lightsail instance."
  value       = aws_lightsail_static_ip.main.ip_address
}

output "instance_name" {
  description = "Name of the Lightsail instance."
  value       = aws_lightsail_instance.main.name
}

output "ssh_private_key_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the SSH private key. Retrieve the key with aws secretsmanager get-secret-value."
  value       = aws_secretsmanager_secret.ssh_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

variable "environment" {
  description = "Environment classification applied to the Environment tag."
  type        = string
  default     = "production"
}

variable "managed_by" {
  description = "Tool identifier applied to the ManagedBy tag."
  type        = string
  default     = "terraform"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  relational_database_name = "app-mysql-db"
  master_database_name     = "app_core_db"
  master_username          = "appadmin"
  final_snapshot_name      = "${local.relational_database_name}-final-snapshot"
  backup_window            = "10:00-10:30"
  maintenance_window       = "sun:06:00-sun:06:30"

  common_tags = {
    Name        = local.relational_database_name
    Environment = var.environment
    ManagedBy   = var.managed_by
  }
}

# Database master credentials are generated at apply time and never hardcoded.
resource "random_password" "db_master" {
  length           = 20
  special          = true
  override_special = "!#$%^&*()-_=+[]{}:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "random_id" "secret_name_suffix" {
  byte_length = 4
}

# Lightsail managed relational database (MySQL 8.0 via blueprint, micro bundle).
# Engine family and major version are encoded in blueprint_id; engine and
# engine_version are computed read-only attributes on this resource.
resource "aws_lightsail_database" "main" {
  relational_database_name     = local.relational_database_name
  availability_zone            = data.aws_availability_zones.available.names[0]
  master_database_name         = local.master_database_name
  master_username              = local.master_username
  master_password              = random_password.db_master.result
  blueprint_id                 = "mysql_8_0"
  bundle_id                    = "micro_2_0"
  preferred_backup_window      = local.backup_window
  preferred_maintenance_window = local.maintenance_window
  publicly_accessible          = false
  skip_final_snapshot          = false
  final_snapshot_name          = local.final_snapshot_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Master credentials are persisted in Secrets Manager; no plaintext secrets in
# configuration, variables, or locals.
resource "aws_secretsmanager_secret" "db" {
  name        = "lightsail/database/${local.relational_database_name}-${random_id.secret_name_suffix.hex}"
  description = "Master credentials for the ${local.relational_database_name} Lightsail managed database."
  tags        = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_lightsail_database.main.master_endpoint_address
    port     = aws_lightsail_database.main.master_endpoint_port
    dbname   = local.master_database_name
    username = local.master_username
    password = random_password.db_master.result
  })
}

output "lightsail_database_master_endpoint_address" {
  description = "Master endpoint address of the Lightsail managed database."
  value       = aws_lightsail_database.main.master_endpoint_address
}

output "lightsail_database_master_endpoint_port" {
  description = "Port of the Lightsail managed database master endpoint."
  value       = aws_lightsail_database.main.master_endpoint_port
}

output "lightsail_database_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret that stores the database master credentials."
  value       = aws_secretsmanager_secret.db.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to all resources. Non-secret value with a safe default so terraform apply runs unattended."
  type        = string
  default     = "dev"
}

locals {
  project_name = "mysql-app"

  common_tags = {
    Project     = local.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Database master password generated in-config (never hardcoded, never in a
# variable default). Lightsail forbids '/', '"', and '@' in master passwords,
# so override_special excludes them.
# -----------------------------------------------------------------------------

resource "random_password" "mysql_db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
}

# -----------------------------------------------------------------------------
# Lightsail compute
# -----------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "mysql_app_server" {
  name = "mysql-app-server-key"
  tags = local.common_tags
}

resource "aws_lightsail_instance" "mysql_app_server" {
  name              = "mysql-app-server"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "micro"
  key_pair_name     = aws_lightsail_key_pair.mysql_app_server.name
  tags              = local.common_tags
}

# Only SSH, HTTP, and HTTPS are exposed publicly. Port 3306 is intentionally
# never opened: Lightsail public ports are all-or-nothing per port, so the
# database port stays closed and the DB remains reachable only over the
# Lightsail internal network.
resource "aws_lightsail_instance_public_ports" "mysql_app_server" {
  instance_name = aws_lightsail_instance.mysql_app_server.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }
}

# -----------------------------------------------------------------------------
# Lightsail managed MySQL database
# The MySQL engine (version 8.0) is selected via blueprint_id = "mysql_8_0";
# engine/engine_version are provider-computed attributes and are not
# configurable in the aws provider v5 schema.
# -----------------------------------------------------------------------------

resource "aws_lightsail_database" "mysql_db" {
  relational_database_name     = "mysql-db"
  availability_zone            = data.aws_availability_zones.available.names[0]
  blueprint_id                 = "mysql_8_0"
  bundle_id                    = "micro_ha"
  master_database_name         = "appdb"
  master_username              = "dbadmin"
  master_password              = random_password.mysql_db_master.result
  publicly_accessible          = false
  backup_retention_enabled     = true
  preferred_backup_window      = "03:15-03:45"
  preferred_maintenance_window = "mon:05:00-mon:05:30"
  apply_immediately            = true
  final_snapshot_name          = "mysql-db-final-snapshot"
  tags                         = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Secrets Manager (no plaintext secrets in configuration; the master password
# is the sensitive managed attribute of random_password, the same value fed to
# the database's master_password, and never a literal or variable default)
# -----------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "mysql_db_master_password" {
  name        = "mysql-app/mysql-db-master-password"
  description = "Master credentials for the Lightsail MySQL database (aws_lightsail_database.mysql_db)."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql_db_master_password" {
  secret_id = aws_secretsmanager_secret.mysql_db_master_password.id
  secret_string = jsonencode({
    engine   = aws_lightsail_database.mysql_db.engine
    host     = aws_lightsail_database.mysql_db.master_endpoint_address
    port     = 3306
    dbname   = aws_lightsail_database.mysql_db.master_database_name
    username = aws_lightsail_database.mysql_db.master_username
    password = random_password.mysql_db_master.result
  })
}

resource "aws_secretsmanager_secret" "mysql_app_server_ssh_key" {
  name        = "mysql-app/mysql-app-server-ssh-key"
  description = "SSH private key generated for the Lightsail key pair (aws_lightsail_key_pair.mysql_app_server)."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "mysql_app_server_ssh_key" {
  secret_id     = aws_secretsmanager_secret.mysql_app_server_ssh_key.id
  secret_string = aws_lightsail_key_pair.mysql_app_server.private_key
}

# -----------------------------------------------------------------------------
# IAM: least-privilege access to the database credentials secret only
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "mysql_app_assume_role" {
  statement {
    sid     = "AllowAssumeByApplicationWorkload"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "mysql_app_server" {
  name               = "mysql-app-server-role"
  description        = "Workload role for the application server; may read only the MySQL database credentials secret."
  assume_role_policy = data.aws_iam_policy_document.mysql_app_assume_role.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "mysql_db_secret_read" {
  statement {
    sid = "ReadMysqlDbMasterSecret"
    actions = [
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
    ]
    resources = [aws_secretsmanager_secret.mysql_db_master_password.arn]
  }
}

resource "aws_iam_policy" "mysql_db_secret_read" {
  name        = "mysql-app-mysql-db-secret-read"
  description = "Least-privilege read access to the Lightsail MySQL master credentials secret."
  policy      = data.aws_iam_policy_document.mysql_db_secret_read.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "mysql_db_secret_read" {
  role       = aws_iam_role.mysql_app_server.name
  policy_arn = aws_iam_policy.mysql_db_secret_read.arn
}

# -----------------------------------------------------------------------------
# Outputs (references ARNs and non-sensitive endpoints only, never secret values)
# -----------------------------------------------------------------------------

output "mysql_app_server_public_ip" {
  description = "Public IP address of the Lightsail application server instance."
  value       = aws_lightsail_instance.mysql_app_server.public_ip_address
}

output "mysql_db_master_endpoint" {
  description = "Lightsail internal-network endpoint of the MySQL database (not reachable from the internet)."
  value       = aws_lightsail_database.mysql_db.master_endpoint_address
}

output "mysql_db_master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials. Reference this ARN instead of the secret value."
  value       = aws_secretsmanager_secret.mysql_db_master_password.arn
}

output "mysql_app_server_ssh_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Lightsail instance SSH private key."
  value       = aws_secretsmanager_secret.mysql_app_server_ssh_key.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
