terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Static provider metadata lookup only (no dependency on existing infrastructure)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Variables (safe defaults so `terraform apply` runs unattended)
# ---------------------------------------------------------------------------
variable "database_identifier" {
  description = "Unique name of the Lightsail relational database."
  type        = string
  default     = "appdb-postgres"

  validation {
    condition     = can(regex("^[a-zA-Z][a-zA-Z0-9_-]{0,254}$", var.database_identifier))
    error_message = "database_identifier must start with a letter and contain only letters, digits, underscores, and hyphens (max 255 characters)."
  }
}

variable "master_database_name" {
  description = "Name of the initial PostgreSQL database created on the instance."
  type        = string
  default     = "appdb"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,62}$", var.master_database_name))
    error_message = "master_database_name must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 63 characters)."
  }
}

variable "master_username" {
  description = "Master username for the Lightsail PostgreSQL instance."
  type        = string
  default     = "dbadmin"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{0,62}$", var.master_username))
    error_message = "master_username must start with a lowercase letter and contain only lowercase letters, digits, and underscores (max 63 characters)."
  }
}

variable "environment" {
  description = "Environment name applied as a tag to all resources."
  type        = string
  default     = "production"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  final_snapshot_name = "${var.database_identifier}-final-snapshot"

  common_tags = {
    Name        = var.database_identifier
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Master credential generation (no plaintext passwords anywhere in config)
# ---------------------------------------------------------------------------
resource "random_password" "master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

# ---------------------------------------------------------------------------
# Secret persistence (credential stored in Secrets Manager, never output)
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "postgres_master_credentials" {
  name        = "${var.database_identifier}/master-credentials"
  description = "Master credentials for the ${var.database_identifier} Lightsail PostgreSQL database."
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "postgres_master_credentials" {
  secret_id = aws_secretsmanager_secret.postgres_master_credentials.id
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_lightsail_database.postgres.master_endpoint_address
    port     = aws_lightsail_database.postgres.master_endpoint_port
    dbname   = var.master_database_name
    username = var.master_username
    password = random_password.master_password.result
  })
}

# ---------------------------------------------------------------------------
# Lightsail PostgreSQL database
# ---------------------------------------------------------------------------
resource "aws_lightsail_database" "postgres" {
  relational_database_name = var.database_identifier
  availability_zone        = data.aws_availability_zones.available.names[0]
  master_database_name     = var.master_database_name
  master_username          = var.master_username
  master_password          = random_password.master_password.result
  blueprint_id             = "postgres_16"
  bundle_id                = "micro_2_0"

  # Keep the database private; no public exposure.
  publicly_accessible = false

  # Automated backups
  backup_retention_enabled     = true
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:05:00-sun:06:00"

  # Create a final snapshot on intentional deletion.
  skip_final_snapshot = false
  final_snapshot_name = local.final_snapshot_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (non-sensitive only)
# ---------------------------------------------------------------------------
output "database_arn" {
  description = "ARN of the Lightsail PostgreSQL database."
  value       = aws_lightsail_database.postgres.arn
}

output "master_database_name" {
  description = "Name of the initial database created on the Lightsail PostgreSQL instance."
  value       = aws_lightsail_database.postgres.master_database_name
}

output "database_endpoint_address" {
  description = "Private endpoint address of the Lightsail PostgreSQL database (publicly_accessible is false)."
  value       = aws_lightsail_database.postgres.master_endpoint_address
}

output "database_endpoint_port" {
  description = "Port the Lightsail PostgreSQL database listens on."
  value       = aws_lightsail_database.postgres.master_endpoint_port
}

output "master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the database master credentials."
  value       = aws_secretsmanager_secret.postgres_master_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used only for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  # Lightsail relational database names allow only alphanumeric characters and
  # hyphens (no underscores), with alphanumeric first/last characters.
  resource_name        = "greenfield-postgres-db"
  master_database_name = "appdb"
  master_username      = "dbadmin"
  final_snapshot_name  = "greenfield-postgres-db-final-snapshot"
  secret_name          = "greenfield/postgres-db/master-password"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_password" "postgres_master_password" {
  length           = 24
  special          = true
  min_upper        = 2
  min_lower        = 2
  min_numeric      = 2
  min_special      = 2
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "postgres_db_master_password" {
  name        = local.secret_name
  description = "Master password for the ${local.resource_name} Lightsail PostgreSQL database."

  tags = {
    Name        = "${local.resource_name}-master-password"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "postgres_db_master_password" {
  secret_id     = aws_secretsmanager_secret.postgres_db_master_password.id
  secret_string = random_password.postgres_master_password.result
}

resource "aws_lightsail_database" "postgres_db" {
  relational_database_name = local.resource_name
  availability_zone        = data.aws_availability_zones.available.names[0]

  # The blueprint encodes the engine and major version; engine_version is a
  # computed attribute on this resource and must not be set explicitly.
  blueprint_id = "postgres_13"
  bundle_id    = "micro_2_0"

  master_database_name = local.master_database_name
  master_username      = local.master_username
  master_password      = aws_secretsmanager_secret_version.postgres_db_master_password.secret_string

  # Core requirement: apply configuration changes immediately instead of
  # waiting for the preferred maintenance window.
  apply_immediately = true

  publicly_accessible      = false
  backup_retention_enabled = true

  preferred_backup_window      = "07:17-07:47"
  preferred_maintenance_window = "Tue:04:00-Tue:04:30"

  skip_final_snapshot = false
  final_snapshot_name = local.final_snapshot_name

  tags = {
    Name        = local.resource_name
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

output "database_arn" {
  description = "ARN of the Lightsail PostgreSQL database."
  value       = aws_lightsail_database.postgres_db.arn
}

output "database_master_endpoint" {
  description = "Hostname of the Lightsail PostgreSQL database endpoint."
  value       = aws_lightsail_database.postgres_db.master_endpoint_address
}

output "database_master_endpoint_port" {
  description = "Port of the Lightsail PostgreSQL database endpoint."
  value       = aws_lightsail_database.postgres_db.master_endpoint_port
}

output "master_password_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master password."
  value       = aws_secretsmanager_secret.postgres_db_master_password.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "disk_name" {
  description = "Name of the Lightsail disk (also used for the Name tag)"
  type        = string
  default     = "main-data-disk"

  validation {
    condition     = can(regex("^[a-zA-Z0-9]([a-zA-Z0-9\\-_\\.]{1,253}[a-zA-Z0-9])?$", var.disk_name))
    error_message = "Disk name must be 2-255 characters using letters, numbers, hyphens, underscores, or periods."
  }
}

variable "disk_size_gb" {
  description = "Size of the Lightsail disk in GB"
  type        = number
  default     = 32

  validation {
    condition     = var.disk_size_gb >= 8 && var.disk_size_gb <= 16384
    error_message = "Lightsail disk size must be between 8 and 16384 GB."
  }
}

variable "environment" {
  description = "Environment tag applied to the Lightsail disk"
  type        = string
  default     = "production"
}

locals {
  tags = {
    Name        = var.disk_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_lightsail_disk" "main" {
  name              = var.disk_name
  size_in_gb        = var.disk_size_gb
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource tags"
  type        = string
  default     = "dev"
}

variable "disk_size_gb" {
  description = "Size of the Lightsail disk in GB"
  type        = number
  default     = 32
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  instance_name = "app_instance"
  disk_name     = "app_data_disk"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = "lightsail-disk-attachment"
  }
}

resource "aws_lightsail_key_pair" "main" {
  name = "${local.instance_name}-key"

  tags = local.common_tags
}

resource "aws_lightsail_instance" "app_instance" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.main.name

  tags = local.common_tags
}

resource "aws_lightsail_instance_public_ports" "app_instance_ports" {
  instance_name = aws_lightsail_instance.app_instance.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }
}

resource "aws_lightsail_disk" "app_data_disk" {
  name              = local.disk_name
  size_in_gb        = var.disk_size_gb
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lightsail_disk_attachment" "app_data_disk_attachment" {
  disk_name     = aws_lightsail_disk.app_data_disk.name
  instance_name = aws_lightsail_instance.app_instance.name
  disk_path     = "/dev/xvdf"
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance"
  value       = aws_lightsail_instance.app_instance.public_ip_address
}

output "disk_name" {
  description = "Name of the Lightsail disk attached to the instance"
  value       = aws_lightsail_disk.app_data_disk.name
}

output "disk_attachment_path" {
  description = "Device path at which the disk is attached on the instance"
  value       = aws_lightsail_disk_attachment.app_data_disk_attachment.disk_path
}

terraform {
  required_version = "~> 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Inputs (user-controlled values only via variables with safe defaults)
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tagging (lowercase letters, digits, hyphens)."
  type        = string
  default     = "storage-demo"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,30}$", var.project_name))
    error_message = "project_name must be 2-31 lowercase alphanumeric characters or hyphens, starting with a letter or digit."
  }
}

variable "environment" {
  description = "Deployment environment used for naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,14}$", var.environment))
    error_message = "environment must be up to 15 lowercase alphanumeric characters or hyphens, starting with a letter or digit."
  }
}

# -----------------------------------------------------------------------------
# Static provider metadata only
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix   = "${var.project_name}-${var.environment}"
  key_pair_name = "${local.name_prefix}-key-pair"
  # Random suffix keeps the bucket name DNS-compatible and globally unique
  # (3-63 chars, lowercase letters, digits, hyphens).
  bucket_name   = "${local.name_prefix}-storage-${random_id.bucket_suffix.hex}"
  instance_name = "${local.name_prefix}-compute"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# -----------------------------------------------------------------------------
# SSH key pair for the compute instance (key material generated by Lightsail)
# -----------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "compute" {
  name = local.key_pair_name
}

# -----------------------------------------------------------------------------
# Storage unit: Lightsail object storage bucket
# -----------------------------------------------------------------------------

resource "aws_lightsail_bucket" "storage" {
  name      = local.bucket_name
  bundle_id = "small_1_0"

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Programmatic credentials so the compute instance can authenticate to the
# bucket. Only the provider-generated attributes are referenced.
resource "aws_lightsail_bucket_access_key" "compute" {
  bucket_name = aws_lightsail_bucket.storage.name
}

# -----------------------------------------------------------------------------
# Compute service: Lightsail instance linked to the bucket
# -----------------------------------------------------------------------------

resource "aws_lightsail_instance" "compute" {
  name              = local.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2023"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.compute.name

  # Bootstrap script: install/configure the AWS CLI, write the Lightsail
  # bucket access-key credentials (Terraform references only), then perform
  # a round-trip object write/read to verify the storage <-> compute linkage.
  user_data = <<-EOF
#!/bin/bash
set -euo pipefail

LOG_FILE="/var/log/lightsail-bucket-linkage.log"
exec > "$LOG_FILE" 2>&1

echo "Lightsail bucket linkage bootstrap started at $(date --iso-8601=seconds)"

# Install the AWS CLI if it is not already present.
if ! command -v aws >/dev/null 2>&1; then
  dnf install -y aws-cli || dnf install -y awscli || true
fi
if ! command -v aws >/dev/null 2>&1; then
  curl -sSL "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.sh" -o /tmp/awscliv2-install.sh
  bash /tmp/awscliv2-install.sh --update
fi
aws --version

# Write the Lightsail bucket access-key credentials for root and ec2-user.
ACCESS_KEY_ID="${aws_lightsail_bucket_access_key.compute.access_key_id}"
SECRET_ACCESS_KEY="${aws_lightsail_bucket_access_key.compute.secret_access_key}"
BUCKET_NAME="${aws_lightsail_bucket.storage.name}"

for AWS_DIR in /root/.aws /home/ec2-user/.aws; do
  install -d -m 0700 "$AWS_DIR"
  printf '[default]\naws_access_key_id = %s\naws_secret_access_key = %s\n' "$ACCESS_KEY_ID" "$SECRET_ACCESS_KEY" > "$AWS_DIR/credentials"
  printf '[default]\nregion = %s\noutput = json\n' "us-east-1" > "$AWS_DIR/config"
  chmod 0600 "$AWS_DIR/credentials" "$AWS_DIR/config"
done
chown -R ec2-user:ec2-user /home/ec2-user/.aws

# Verify the linkage with a round-trip object write/read against the bucket.
TEST_FILE="/tmp/lightsail-linkage-test.txt"
TEST_COPY="/tmp/lightsail-linkage-test-download.txt"
TEST_KEY="verification/lightsail-linkage-test.txt"

echo "lightsail-bucket-linkage-test $(date --iso-8601=seconds)" > "$TEST_FILE"

aws s3 cp "$TEST_FILE" "s3://$BUCKET_NAME/$TEST_KEY"
aws s3 cp "s3://$BUCKET_NAME/$TEST_KEY" "$TEST_COPY"
diff -q "$TEST_FILE" "$TEST_COPY"
aws s3 ls "s3://$BUCKET_NAME/verification/"

echo "SUCCESS: bucket linkage verified; round-trip write/read to s3://$BUCKET_NAME completed."
echo "linkage_status=success" > /var/log/lightsail-bucket-linkage-status.txt
EOF

  tags = merge(local.common_tags, {
    Name = local.instance_name
  })
}

# -----------------------------------------------------------------------------
# Firewall hygiene: SSH (TCP 22) only, restricted to the default port set
# -----------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "compute" {
  instance_name = aws_lightsail_instance.compute.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = ["0.0.0.0/0"]
  }
}

# -----------------------------------------------------------------------------
# Outputs for automated verification
# -----------------------------------------------------------------------------

output "bucket_name" {
  description = "Name of the Lightsail object storage bucket."
  value       = aws_lightsail_bucket.storage.name
}

output "bucket_arn" {
  description = "ARN of the Lightsail object storage bucket."
  value       = aws_lightsail_bucket.storage.arn
}

output "instance_name" {
  description = "Name of the Lightsail compute instance."
  value       = aws_lightsail_instance.compute.name
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail compute instance."
  value       = aws_lightsail_instance.compute.public_ip_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Data sources (static provider metadata only — no pre-existing infrastructure)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Variables
###############################################################################

variable "instance_blueprint" {
  description = "Lightsail blueprint (OS image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "instance_bundle" {
  description = "Lightsail bundle (size) for the instance."
  type        = string
  default     = "nano_3_0"
}

variable "disks" {
  description = "Map of Lightsail disk name to disk size in GB. Every disk is created in the instance's Availability Zone and attached to the instance."
  type        = map(number)
  default = {
    "app-data" = 32
    "app-logs" = 16
  }

  validation {
    condition     = length(var.disks) >= 1
    error_message = "At least one disk must be defined."
  }

  validation {
    condition     = alltrue([for size in values(var.disks) : size >= 1])
    error_message = "Every disk size must be at least 1 GB."
  }
}

variable "common_tags" {
  description = "Common tags applied to all Lightsail resources for cost tracking and compliance."
  type        = map(string)
  default = {
    Environment = "production"
    Project     = "lightsail-multi-disk-app"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Shared naming prefix so instance, key pair, and disks are consistently named.
  name_prefix = "lightsail-app"
}

###############################################################################
# SSH key pair (generated by Lightsail; private key is never emitted to
# configuration, variable defaults, locals, or outputs)
###############################################################################

resource "aws_lightsail_key_pair" "app" {
  name = "${local.name_prefix}-keypair"

  tags = var.common_tags
}

###############################################################################
# Lightsail instance
###############################################################################

resource "aws_lightsail_instance" "app" {
  name              = local.name_prefix
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.instance_blueprint
  bundle_id         = var.instance_bundle
  key_pair_name     = aws_lightsail_key_pair.app.name

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Restrict inbound access to SSH, HTTP, and HTTPS only — no other ports are
# opened to the internet.
resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    from_port = 22
    to_port   = 22
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 80
    to_port   = 80
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    from_port = 443
    to_port   = 443
    protocol  = "tcp"
    cidrs     = ["0.0.0.0/0"]
  }
}

###############################################################################
# Disks (stateful data volumes) — for_each over the user-controlled disk set
###############################################################################

resource "aws_lightsail_disk" "volumes" {
  for_each = var.disks

  name              = each.key
  size_in_gb        = each.value
  availability_zone = aws_lightsail_instance.app.availability_zone

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Explicitly attach every disk to the instance in the same apply. The mount
# path is derived deterministically from the disk name; co-location with the
# instance is guaranteed by the disk resource's availability_zone reference.
resource "aws_lightsail_disk_attachment" "app" {
  for_each = var.disks

  disk_name     = aws_lightsail_disk.volumes[each.key].name
  instance_name = aws_lightsail_instance.app.id
  disk_path     = "/mnt/${each.key}"
}

###############################################################################
# Outputs (verification only — no secret material)
###############################################################################

output "instance_public_ip" {
  description = "Public IPv4 address of the Lightsail instance."
  value       = aws_lightsail_instance.app.public_ip_address
}

output "instance_ssh_username" {
  description = "Default SSH username for the instance blueprint."
  value       = aws_lightsail_instance.app.username
}

output "attached_disks" {
  description = "Map of attached Lightsail disk names to their Lightsail disk IDs."
  value       = { for disk_name, disk in aws_lightsail_disk.volumes : disk_name => disk.id }
}

###############################################################################
# Terraform + Provider
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Data sources (static lookups only — greenfield account, nothing pre-existing)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Variables (all defaulted so terraform apply runs non-interactively)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "bucket_name" {
  description = "Globally-unique, lowercase name for the Lightsail bucket."
  type        = string
  default     = "tf-lightsail-app-bucket-a1b2c3d4"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-.]{1,61}[a-z0-9]$", var.bucket_name))
    error_message = "Bucket name must be 3-63 characters of lowercase letters, numbers, periods, or hyphens."
  }
}

variable "bucket_bundle_id" {
  description = "Lightsail object storage bundle for the bucket."
  type        = string
  default     = "small_1_0"
}

variable "instance_blueprint_id" {
  description = "Lightsail blueprint (OS image) for the instance."
  type        = string
  default     = "amazon_linux_2023"
}

variable "instance_bundle_id" {
  description = "Lightsail instance bundle (instance size)."
  type        = string
  default     = "nano_3_0"
}

variable "admin_cidr" {
  description = "CIDR block permitted to reach SSH (TCP 22). Keep it narrow; never 0.0.0.0/0."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.admin_cidr)) && var.admin_cidr != "0.0.0.0/0"
    error_message = "admin_cidr must be a valid CIDR block and must not be 0.0.0.0/0."
  }
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "lightsail-bucket-access"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

###############################################################################
# Lightsail key pair — SSH keys fully Terraform-managed, never the account
# default key pair
###############################################################################

resource "aws_lightsail_key_pair" "app" {
  name = "app_server_key"
  tags = local.common_tags
}

###############################################################################
# Lightsail bucket — private by default (no public access configured), no
# force_destroy, and protected from destruction. Access is granted exclusively
# through the Lightsail resource access grant below.
###############################################################################

resource "aws_lightsail_bucket" "main" {
  name      = var.bucket_name
  bundle_id = var.bucket_bundle_id

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Lightsail instance
###############################################################################

resource "aws_lightsail_instance" "app" {
  name              = "app_server"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = var.instance_blueprint_id
  bundle_id         = var.instance_bundle_id
  key_pair_name     = aws_lightsail_key_pair.app.name

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y nginx
    systemctl enable --now nginx
    echo "<h1>Lightsail app server</h1>" > /usr/share/nginx/html/index.html
  EOF

  tags = local.common_tags
}

###############################################################################
# Firewall — authoritative port configuration: only SSH from the admin CIDR
# and web ports are open; every other port remains closed.
###############################################################################

resource "aws_lightsail_instance_public_ports" "app" {
  instance_name = aws_lightsail_instance.app.name

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = [var.admin_cidr]
  }

  port_info {
    protocol  = "tcp"
    from_port = 80
    to_port   = 80
    cidrs     = ["0.0.0.0/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 443
    to_port   = 443
    cidrs     = ["0.0.0.0/0"]
  }
}

###############################################################################
# Least-privilege grant — only this instance may access only this bucket.
# No wildcard resources, no "*" anywhere.
###############################################################################

resource "aws_lightsail_bucket_resource_access" "app_to_bucket" {
  bucket_name   = aws_lightsail_bucket.main.name
  resource_name = aws_lightsail_instance.app.id
}

###############################################################################
# Outputs
###############################################################################

output "bucket_name" {
  description = "Name of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.name
}

output "bucket_url" {
  description = "URL of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.url
}

output "bucket_arn" {
  description = "ARN of the Lightsail bucket."
  value       = aws_lightsail_bucket.main.arn
}

output "instance_public_ip" {
  description = "Public IP address of the Lightsail instance."
  value       = aws_lightsail_instance.app.public_ip_address
}

# Lightsail Certificate
# Issues a Lightsail (ACM-backed) TLS certificate for a primary domain with
# optional subject alternative names. DNS CNAME validation records are exposed
# as outputs so they can be registered in the domain's DNS zone out-of-band.

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "domain_name" {
  description = "Primary fully-qualified domain name the Lightsail certificate is issued for."
  type        = string
  default     = "example.com"

  validation {
    condition     = can(regex("^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$", var.domain_name))
    error_message = "domain_name must be a valid FQDN containing only lowercase letters, digits, hyphens, and dots (e.g. example.com)."
  }
}

variable "alternative_names" {
  description = "Optional set of subject alternative names (FQDNs) to include in the certificate."
  type        = set(string)
  default     = []

  validation {
    condition = alltrue([
      for name in var.alternative_names :
      can(regex("^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\\.)+[a-z]{2,63}$", name))
    ])
    error_message = "Each alternative name must be a valid FQDN containing only lowercase letters, digits, hyphens, and dots (e.g. www.example.com)."
  }
}

variable "environment" {
  description = "Environment label applied to resource tags for ownership and cost tracking."
  type        = string
  default     = "production"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]{0,18}[a-z0-9])?$", var.environment))
    error_message = "environment must be 1-20 lowercase alphanumeric characters or hyphens."
  }
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  # Lightsail certificate names accept lowercase alphanumeric characters and
  # hyphens only (1-255 chars). Derive a stable, human-readable, per-domain
  # unique name from the primary domain.
  certificate_name = "main-${replace(var.domain_name, ".", "-")}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Lightsail Certificate
# ------------------------------------------------------------------------------

resource "aws_lightsail_certificate" "main" {
  name        = local.certificate_name
  domain_name = var.domain_name

  # Schema-bound argument name for SANs; the provider automatically adds
  # domain_name as a SAN, so no value transformation is required here.
  subject_alternative_names = var.alternative_names

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "certificate_name" {
  description = "Name of the Lightsail certificate."
  value       = aws_lightsail_certificate.main.name
}

output "certificate_arn" {
  description = "ARN of the Lightsail certificate."
  value       = aws_lightsail_certificate.main.arn
}

output "certificate_created_at" {
  description = "Creation timestamp of the Lightsail certificate (issuance progress is observable via the domain_validation_records output, which populates once DNS validation begins)."
  value       = aws_lightsail_certificate.main.created_at
}

output "domain_validation_records" {
  description = "DNS validation options that must be registered in the domain's DNS zone (out-of-band) so Lightsail can validate and issue the certificate."
  value       = aws_lightsail_certificate.main.domain_validation_options
}

output "domain_validation_cname_records" {
  description = "Convenience view of the CNAME validation records (name/type/value) ready to be added to the domain's DNS zone."
  value = {
    for record in aws_lightsail_certificate.main.domain_validation_options :
    record.resource_record_name => {
      name  = record.resource_record_name
      type  = record.resource_record_type
      value = record.resource_record_value
    }
  }
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "custom_domain_name" {
  description = "Custom domain name to serve the distribution from. Leave empty (default) to serve from the distribution's default HTTPS-enabled DNS target."
  type        = string
  default     = ""
}

resource "random_id" "suffix" {
  byte_length = 4
}

locals {
  # Lightsail bucket names live in the global S3 namespace and only allow
  # lowercase letters, numbers and hyphens, so a random suffix is appended
  # to guarantee a globally unique name.
  bucket_name = "static-assets-${random_id.suffix.hex}"

  distribution_name = "static-cdn-${random_id.suffix.hex}"
}

# Private Lightsail bucket used as the sole origin of the distribution.
# Lightsail buckets are private by default; they are never exposed publicly
# and are only shared with the distribution through
# aws_lightsail_bucket_resource_access below.
#
# Note: the provider cannot manage Lightsail bucket objects via Terraform
# (no aws_lightsail_bucket_object resource exists), so origin content such as
# index.html is seeded post-apply via the Lightsail console/CLI or the
# S3-compatible API with bucket access keys, outside Terraform state.
resource "aws_lightsail_bucket" "static_assets" {
  name      = local.bucket_name
  bundle_id = "small_2_0"

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Lightsail distributions support exactly one origin; default_cache_behavior
# always targets that origin (there is no separate target_origin_id argument).
resource "aws_lightsail_distribution" "static_cdn" {
  name             = local.distribution_name
  bundle_id        = "small_1_0"
  ip_address_type  = "dualstack"
  is_enabled       = true
  certificate_name = var.custom_domain_name != "" ? aws_lightsail_certificate.custom_domain[0].name : null

  default_cache_behavior {
    behavior = "cache"
  }

  cache_behavior_settings {
    allowed_http_methods = "GET, HEAD, OPTIONS"
    cached_http_methods  = "GET, HEAD"
    default_ttl          = 86400
    minimum_ttl          = 0
    maximum_ttl          = 31536000

    forwarded_query_strings {
      option = true
    }
  }

  origin {
    name        = aws_lightsail_bucket.static_assets.name
    region_name = "us-east-1"
  }

  tags = var.tags
}

# Grant the distribution read access to the private bucket. The bucket itself
# stays private; the distribution is the only egress path.
resource "aws_lightsail_bucket_resource_access" "distribution_origin_access" {
  bucket_name   = aws_lightsail_bucket.static_assets.name
  resource_name = aws_lightsail_distribution.static_cdn.name
}

# Only created when a custom domain is supplied; otherwise the distribution
# serves content over HTTPS from its default DNS target.
resource "aws_lightsail_certificate" "custom_domain" {
  count = var.custom_domain_name != "" ? 1 : 0

  name        = "static-cdn-cert-${random_id.suffix.hex}"
  domain_name = var.custom_domain_name

  tags = var.tags
}

output "distribution_dns_target" {
  description = "Default DNS target of the Lightsail distribution (CloudFront endpoint serving the bucket origin)."
  value       = aws_lightsail_distribution.static_cdn.domain_name
}

output "static_assets_bucket_name" {
  description = "Name of the private Lightsail bucket used as the distribution origin."
  value       = aws_lightsail_bucket.static_assets.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Lightsail distributions are only available in us-east-1,
# so the origin instance must live in us-east-1 as well.
provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used to build unique, lowercase Lightsail resource names and the Environment tag."
  type        = string
  default     = "production"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,40}$", var.environment))
    error_message = "Environment must start with a lowercase letter or number and contain only lowercase letters, numbers, and hyphens."
  }
}

variable "tags" {
  description = "Resource tags (for example Project, Owner) merged with the Environment tag onto every Lightsail resource."
  type        = map(string)
  default = {
    Project = "lightsail-cdn-origin"
  }
}

variable "admin_ssh_cidrs" {
  description = "IPv4 CIDR blocks allowed to reach SSH (TCP 22) on the origin instance. Must never include 0.0.0.0/0."
  type        = list(string)
  default     = ["203.0.113.0/24"]

  validation {
    condition     = length(var.admin_ssh_cidrs) > 0 && !contains(var.admin_ssh_cidrs, "0.0.0.0/0") && !contains(var.admin_ssh_cidrs, "::/0")
    error_message = "Port 22 must not be open to the world. List specific administrator CIDR blocks instead."
  }
}

variable "domain_name" {
  description = "Custom domain name served by the distribution. You must control this domain's DNS to complete Lightsail certificate validation."
  type        = string
  default     = "cdn.example.com"

  validation {
    condition     = can(regex("^([a-z0-9]([a-z0-9-]*[a-z0-9])?\\.)+[a-z]{2,63}$", var.domain_name))
    error_message = "Domain name must be a valid lowercase hostname (for example cdn.example.com)."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "cdn-${var.environment}"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    },
  )
}

# ---------------------------------------------------------------------------
# SSH key pair for the origin instance
# ---------------------------------------------------------------------------

resource "aws_lightsail_key_pair" "origin" {
  name = "${local.name_prefix}-origin-key"
  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Origin instance (stateful website host)
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance" "origin" {
  name              = "${local.name_prefix}-origin"
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "os_ubuntu_22_04"
  bundle_id         = "nano_3_0"
  key_pair_name     = aws_lightsail_key_pair.origin.name
  tags              = local.common_tags

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    export DEBIAN_FRONTEND=noninteractive

    apt-get update -y
    apt-get install -y --no-install-recommends nginx

    printf '%s\n' \
      '<!doctype html>' \
      '<html lang="en">' \
      '  <head>' \
      '    <meta charset="utf-8">' \
      '    <title>Lightsail CDN origin</title>' \
      '    <link rel="stylesheet" href="/static/main.css">' \
      '  </head>' \
      '  <body>' \
      '    <h1>Hello from the Lightsail origin instance</h1>' \
      '    <script src="/static/app.js"></script>' \
      '  </body>' \
      '</html>' \
      >/var/www/html/index.html

    mkdir -p /var/www/html/static
    printf '%s\n' 'body{font-family:system-ui,sans-serif;margin:3rem}' >/var/www/html/static/main.css
    printf '%s\n' 'console.log("static asset served from the Lightsail origin");' >/var/www/html/static/app.js

    printf '%s\n' \
      'server {' \
      '    listen 80 default_server;' \
      '    listen [::]:80 default_server;' \
      '    server_name _;' \
      '    root /var/www/html;' \
      '    index index.html;' \
      '    add_header Cache-Control "no-cache, must-revalidate" always;' \
      '    location /static/ {' \
      '        add_header Cache-Control "public, max-age=2592000, immutable" always;' \
      '    }' \
      '}' \
      >/etc/nginx/sites-available/default

    nginx -t
    systemctl enable nginx
    systemctl restart nginx
  EOF

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Instance firewall: 80/443 public (required for origin fetches),
# 22 restricted to the admin CIDR allow-list only.
# ---------------------------------------------------------------------------

resource "aws_lightsail_instance_public_ports" "origin" {
  instance_name = aws_lightsail_instance.origin.name

  port_info {
    protocol   = "tcp"
    from_port  = 80
    to_port    = 80
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol   = "tcp"
    from_port  = 443
    to_port    = 443
    cidrs      = ["0.0.0.0/0"]
    ipv6_cidrs = ["::/0"]
  }

  port_info {
    protocol  = "tcp"
    from_port = 22
    to_port   = 22
    cidrs     = var.admin_ssh_cidrs
  }
}

# ---------------------------------------------------------------------------
# TLS certificate for the custom domain
# ---------------------------------------------------------------------------

resource "aws_lightsail_certificate" "site" {
  name        = "${local.name_prefix}-cert"
  domain_name = var.domain_name
  tags        = local.common_tags
}

# ---------------------------------------------------------------------------
# CDN distribution in front of the origin instance
# ---------------------------------------------------------------------------

resource "aws_lightsail_distribution" "cdn" {
  name             = "${local.name_prefix}-distribution"
  bundle_id        = "small_1_0"
  ip_address_type  = "dualstack"
  is_enabled       = true
  certificate_name = aws_lightsail_certificate.site.name
  tags             = local.common_tags

  origin {
    name            = aws_lightsail_instance.origin.name
    region_name     = "us-east-1"
    protocol_policy = "http-only"
  }

  # HTTPS at the edge is enforced by the attached Lightsail certificate;
  # the default behavior is least-exposure: only explicitly enumerated
  # static-asset paths are cached, everything else hits the origin.
  default_cache_behavior {
    behavior = "dont-cache"
  }

  cache_behavior_settings {
    allowed_http_methods = "GET,HEAD,OPTIONS"
    cached_http_methods  = "GET,HEAD"
    minimum_ttl          = 0
    default_ttl          = 86400
    maximum_ttl          = 31536000

    forwarded_cookies {
      option = "none"
    }

    # "default" forwards only the baseline header set Lightsail requires;
    # no custom viewer headers leak to the origin or vary the cache key.
    forwarded_headers {
      option = "default"
    }

    forwarded_query_strings {
      option                     = false
      query_strings_allowed_list = []
    }
  }

  # Static assets are cached at the edge with long TTLs.
  cache_behavior {
    path     = "/static/*"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.css"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.js"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.jpg"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.jpeg"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.png"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.svg"
    behavior = "cache"
  }

  cache_behavior {
    path     = "*.woff2"
    behavior = "cache"
  }

  # Dynamic paths always bypass the cache and hit the origin.
  cache_behavior {
    path     = "/api/*"
    behavior = "dont-cache"
  }

  depends_on = [aws_lightsail_instance_public_ports.origin]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "distribution_domain_name" {
  description = "FQDN of the Lightsail distribution (CDN endpoint)."
  value       = aws_lightsail_distribution.cdn.domain_name
}

output "distribution_url" {
  description = "HTTPS URL of the Lightsail distribution."
  value       = "https://${aws_lightsail_distribution.cdn.domain_name}"
}

output "distribution_arn" {
  description = "ARN of the Lightsail distribution."
  value       = aws_lightsail_distribution.cdn.arn
}

output "origin_instance_public_ip" {
  description = "Public IPv4 address of the Lightsail origin instance."
  value       = aws_lightsail_instance.origin.public_ip_address
}

output "certificate_validation_records" {
  description = "DNS records that must be created to validate the Lightsail certificate for the custom domain. These CNAME records populate after apply."
  value = [
    for option in aws_lightsail_certificate.site.domain_validation_options :
    "${option.resource_record_type} ${option.resource_record_name} -> ${option.resource_record_value}"
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix used to derive the globally unique archive bucket name."
  type        = string
  default     = "org-archive"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,31}$", var.name_prefix))
    error_message = "name_prefix must be 2-32 lowercase alphanumeric characters or hyphens."
  }
}

variable "environment" {
  description = "Environment identifier (e.g. dev, staging, prod) used in resource names and tags."
  type        = string
  default     = "prod"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,11}$", var.environment))
    error_message = "environment must be 1-12 lowercase alphanumeric characters or hyphens."
  }
}

variable "object_lock_retention_days" {
  description = "Default COMPLIANCE-mode S3 Object Lock retention period in days."
  type        = number
  default     = 365

  validation {
    condition     = var.object_lock_retention_days > 0
    error_message = "Object lock retention must be at least 1 day."
  }
}

variable "noncurrent_version_retention_days" {
  description = "Days after a version becomes noncurrent before it is expired (default 7 years)."
  type        = number
  default     = 2555

  validation {
    condition     = var.noncurrent_version_retention_days > 0
    error_message = "Noncurrent version retention must be at least 1 day."
  }
}

locals {
  bucket_name = "${lower(var.name_prefix)}-${lower(var.environment)}-${random_id.archive_suffix.hex}"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Purpose     = "long-term-archive"
  }
}

resource "random_id" "archive_suffix" {
  byte_length = 4
}

resource "aws_kms_key" "archive" {
  description             = "SSE-KMS encryption key for the long-term S3 archive bucket"
  is_enabled              = true
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "glacier_archive" {
  bucket              = local.bucket_name
  object_lock_enabled = true

  tags = merge(local.common_tags, {
    Name = local.bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.archive.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.glacier_archive.arn,
          "${aws_s3_bucket.glacier_archive.arn}/*",
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyPutObjectWithoutKmsEncryption"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.glacier_archive.arn}/*"
        Condition = {
          StringNotEquals = {
            "s3:x-amz-server-side-encryption" = "aws:kms"
          }
        }
      },
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.glacier_archive]
}

resource "aws_s3_bucket_lifecycle_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  depends_on = [aws_s3_bucket_versioning.glacier_archive]

  rule {
    id     = "glacier-tiering-and-retention"
    status = "Enabled"

    filter {}

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    transition {
      days          = 365
      storage_class = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = var.object_lock_retention_days
    }
  }

  depends_on = [aws_s3_bucket_versioning.glacier_archive]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "archive_operator" {
  name        = "${lower(var.name_prefix)}-${lower(var.environment)}-archive-operator"
  description = "Role assumed by archive operators for S3 Glacier ingest and retrieval"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAssumeFromEc2"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "archive_access" {
  name        = "${lower(var.name_prefix)}-${lower(var.environment)}-archive-access"
  description = "Least-privilege access to the S3 archive bucket and its KMS encryption key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListArchiveBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.glacier_archive.arn
      },
      {
        Sid    = "ArchiveObjectActions"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:RestoreObject",
        ]
        Resource = "${aws_s3_bucket.glacier_archive.arn}/*"
      },
      {
        Sid    = "ArchiveKmsKeyUsage"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = aws_kms_key.archive.arn
      },
    ]
  })
}

resource "aws_iam_role_policy_attachment" "archive_operator" {
  role       = aws_iam_role.archive_operator.name
  policy_arn = aws_iam_policy.archive_access.arn
}

output "archive_bucket_id" {
  description = "Name (ID) of the long-term archive bucket."
  value       = aws_s3_bucket.glacier_archive.id
}

output "archive_bucket_arn" {
  description = "ARN of the long-term archive bucket."
  value       = aws_s3_bucket.glacier_archive.arn
}

output "archive_kms_key_arn" {
  description = "ARN of the KMS key used to encrypt archive objects."
  value       = aws_kms_key.archive.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables (user-controlled values with unattended-apply defaults)
# ------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name applied as the Environment tag on all taggable resources."
  type        = string
  default     = "prod"
}

variable "backup_plan_tag_value" {
  description = "Value of the BackupPlan resource tag that enrolls resources into the AWS Backup plan."
  type        = string
  default     = "long-term-archive-and-backup"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "prod"
    Purpose     = "long-term-archive-and-backup"
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# Data sources (static, well-known metadata lookups only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  archive_bucket_name = "long-term-storage-${local.account_id}-archive"
  backup_bucket_name  = "long-term-storage-${local.account_id}-backup"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  backup_role_name      = "aws-backup-long-term-service-role"
  backup_vault_name     = "long-term-backup-vault"
  backup_plan_name      = "long-term-backup-plan"
  backup_selection_name = "long-term-tag-based-selection"

  backup_managed_policy_backup_arn  = "arn:${local.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForBackup"
  backup_managed_policy_restore_arn = "arn:${local.partition}:iam::aws:policy/AWSBackupServiceRolePolicyForRestores"

  noncurrent_version_retention_days = 2557 # ~7 years
}

# ------------------------------------------------------------------------------
# Central customer-managed KMS key
# ------------------------------------------------------------------------------

resource "aws_kms_key" "long_term_storage" {
  description             = "Central customer-managed key for long-term archive and backup encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "long-term-storage-key"
  })
}

resource "aws_kms_alias" "long_term_storage" {
  name          = "alias/long-term-storage"
  target_key_id = aws_kms_key.long_term_storage.key_id
}

# ------------------------------------------------------------------------------
# Primary long-term archive bucket
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "archive" {
  bucket = local.archive_bucket_name

  tags = merge(local.common_tags, {
    Name = local.archive_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "archive" {
  bucket = aws_s3_bucket.archive.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "archive" {
  bucket = aws_s3_bucket.archive.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.long_term_storage.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "archive" {
  bucket = aws_s3_bucket.archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_lifecycle_configuration" "archive" {
  bucket = aws_s3_bucket.archive.id

  rule {
    id     = "long-term-tiering-and-expiry"
    status = "Enabled"

    filter {}

    transition {
      days          = 30
      storage_class = "STANDARD_IA"
    }

    transition {
      days          = 90
      storage_class = "GLACIER"
    }

    transition {
      days          = 365
      storage_class = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = local.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "archive_tls_only" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.archive.arn,
      "${aws_s3_bucket.archive.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "archive" {
  bucket = aws_s3_bucket.archive.id
  policy = data.aws_iam_policy_document.archive_tls_only.json

  depends_on = [aws_s3_bucket_public_access_block.archive]
}

# ------------------------------------------------------------------------------
# Immutable WORM backup bucket (Object Lock in COMPLIANCE mode)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "backup" {
  bucket              = local.backup_bucket_name
  object_lock_enabled = true

  tags = merge(local.common_tags, {
    Name = local.backup_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "backup" {
  bucket = aws_s3_bucket.backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.long_term_storage.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "backup" {
  bucket = aws_s3_bucket.backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_object_lock_configuration" "backup" {
  bucket = aws_s3_bucket.backup.id

  depends_on = [aws_s3_bucket_versioning.backup]

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 90
    }
  }
}

data "aws_iam_policy_document" "backup_tls_only" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.backup.arn,
      "${aws_s3_bucket.backup.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "backup" {
  bucket = aws_s3_bucket.backup.id
  policy = data.aws_iam_policy_document.backup_tls_only.json

  depends_on = [aws_s3_bucket_public_access_block.backup]
}

# ------------------------------------------------------------------------------
# Account-level S3 public access protection
# ------------------------------------------------------------------------------

resource "aws_s3_account_public_access_block" "main" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# AWS Backup IAM role
# ------------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_assume_role" {
  statement {
    sid     = "AllowAWSBackupToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup" {
  name               = local.backup_role_name
  assume_role_policy = data.aws_iam_policy_document.backup_assume_role.json

  tags = merge(local.common_tags, {
    Name = local.backup_role_name
  })
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_managed_policy_backup_arn
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = local.backup_managed_policy_restore_arn
}

# ------------------------------------------------------------------------------
# AWS Backup vault (KMS-encrypted, vault-locked)
# ------------------------------------------------------------------------------

resource "aws_backup_vault" "main" {
  name        = local.backup_vault_name
  kms_key_arn = aws_kms_key.long_term_storage.arn

  tags = merge(local.common_tags, {
    Name = local.backup_vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "main" {
  backup_vault_name  = aws_backup_vault.main.name
  min_retention_days = 90
}

# ------------------------------------------------------------------------------
# AWS Backup plan (daily / weekly / monthly)
# lifecycle values are reconciled with AWS Backup API constraints:
#   - delete_after must be >= 90 days (also enforced by vault lock)
#   - cold retention must be >= 90 days (delete_after >= cold_storage_after + 90)
# ------------------------------------------------------------------------------

resource "aws_backup_plan" "main" {
  name = local.backup_plan_name

  tags = merge(local.common_tags, {
    Name = local.backup_plan_name
  })

  rule {
    rule_name         = "daily"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 * * ? *)"

    lifecycle {
      delete_after = 90
    }
  }

  rule {
    rule_name         = "weekly"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 ? * MON *)"

    lifecycle {
      cold_storage_after = 90
      delete_after       = 180
    }
  }

  rule {
    rule_name         = "monthly"
    target_vault_name = aws_backup_vault.main.name
    schedule          = "cron(0 5 1 * ? *)"

    lifecycle {
      cold_storage_after = 90
      delete_after       = 365
    }
  }
}

# ------------------------------------------------------------------------------
# Tag-based backup selection
# Note: aws_backup_selection is a non-taggable AWS resource (the underlying
# CreateBackupSelection API does not support tags), so no tags argument is set.
# ------------------------------------------------------------------------------

resource "aws_backup_selection" "main" {
  name         = local.backup_selection_name
  plan_id      = aws_backup_plan.main.id
  iam_role_arn = aws_iam_role.backup.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "BackupPlan"
    value = var.backup_plan_tag_value
  }

  depends_on = [
    aws_iam_role_policy_attachment.backup,
    aws_iam_role_policy_attachment.restore,
  ]
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------

output "archive_bucket_name" {
  description = "Name of the long-term archive S3 bucket."
  value       = aws_s3_bucket.archive.id
}

output "archive_bucket_arn" {
  description = "ARN of the long-term archive S3 bucket."
  value       = aws_s3_bucket.archive.arn
}

output "backup_bucket_name" {
  description = "Name of the immutable backup S3 bucket."
  value       = aws_s3_bucket.backup.id
}

output "backup_bucket_arn" {
  description = "ARN of the immutable backup S3 bucket."
  value       = aws_s3_bucket.backup.arn
}

output "kms_key_arn" {
  description = "ARN of the central customer-managed KMS key."
  value       = aws_kms_key.long_term_storage.arn
}

output "backup_vault_arn" {
  description = "ARN of the encrypted AWS Backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_plan_arn" {
  description = "ARN of the AWS Backup plan."
  value       = aws_backup_plan.main.arn
}

# =============================================================================
# S3 Glacier vault + AWS Data Lifecycle Manager (DLM) snapshot archiving
# =============================================================================

terraform {
  required_version = ">= 1.5.0, < 2.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "project_name" {
  description = "Base project name used to derive resource names."
  type        = string
  default     = "glacier-archive"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]*$", var.project_name))
    error_message = "project_name must start with a lowercase letter or digit and contain only lowercase letters, digits, and hyphens."
  }
}

variable "snapshot_retention" {
  description = "Number of daily snapshots retained by the DLM lifecycle policy."
  type        = number
  default     = 14

  validation {
    condition     = var.snapshot_retention >= 1 && var.snapshot_retention <= 1000
    error_message = "snapshot_retention must be between 1 and 1000."
  }
}

variable "common_tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Environment = "production"
    Owner       = "platform-team"
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Data sources (pure static provider metadata lookups only)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = lower(var.project_name)
  vault_name  = "${local.name_prefix}-vault"

  # The vault ARN is composed from static provider metadata (partition, region,
  # account ID) plus the deterministic vault name. Terraform rejects a resource
  # referencing its own attributes (a self-reference is treated as a graph
  # cycle), so the inline vault access policy cannot use
  # aws_glacier_vault.archive_vault.arn directly. This local produces the exact
  # same ARN the vault resource will receive.
  glacier_vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${local.vault_name}"

  dlm_target_tags = { Backup = "true" }
}

# -----------------------------------------------------------------------------
# KMS key: encrypts the backup source volume; DLM snapshots inherit it
# -----------------------------------------------------------------------------

resource "aws_kms_key" "archive_key" {
  description             = "CMK for the backup source volume and DLM-managed snapshots"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = var.common_tags
}

resource "aws_kms_alias" "archive_key_alias" {
  name          = "alias/${local.name_prefix}-archive-key"
  target_key_id = aws_kms_key.archive_key.key_id
}

resource "aws_kms_key_policy" "archive_key_policy" {
  key_id = aws_kms_key.archive_key.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = aws_kms_key.archive_key.arn
      },
      {
        Sid    = "AllowDLMRoleSnapshotOperations"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.dlm_exec.arn
        }
        Action = [
          "kms:CreateGrant",
          "kms:DescribeKey",
          "kms:Decrypt",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:ReEncrypt*"
        ]
        Resource = aws_kms_key.archive_key.arn
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# DLM execution role
# -----------------------------------------------------------------------------

resource "aws_iam_role" "dlm_exec" {
  name = "${local.name_prefix}-dlm-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "dlm.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.common_tags
}

resource "aws_iam_role_policy_attachment" "dlm_exec_default" {
  role       = aws_iam_role.dlm_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSDataLifecycleManagerDefaultRole"
}

# -----------------------------------------------------------------------------
# S3 Glacier archive vault (server-side AES-256 encryption at rest is built in)
# The provider models the vault access policy as the inline `access_policy`
# string attribute; there is no standalone vault-policy resource type.
# -----------------------------------------------------------------------------

resource "aws_glacier_vault" "archive_vault" {
  name = local.vault_name

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowDLMRoleGlacierOperations"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.dlm_exec.arn
        }
        Action = [
          "glacier:UploadArchive",
          "glacier:InitiateJob",
          "glacier:DownloadJob",
          "glacier:AbortMultipartUpload"
        ]
        Resource = local.glacier_vault_arn
      }
    ]
  })

  tags = var.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Encrypted backup source volume (DLM target; snapshots inherit the CMK)
# -----------------------------------------------------------------------------

resource "aws_ebs_volume" "backup_source" {
  availability_zone = data.aws_availability_zones.available.names[0]
  size              = 10
  type              = "gp3"
  encrypted         = true
  kms_key_id        = aws_kms_key.archive_key.arn

  tags = merge(
    var.common_tags,
    local.dlm_target_tags,
    {
      Name = "${local.name_prefix}-backup-source"
    },
  )

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# DLM lifecycle policy: daily 0300 UTC snapshots with bounded retention.
# The Glacier vault above (aws_glacier_vault.archive_vault) serves as the
# long-term archive destination; the retain_rule below delivers the daily
# snapshot rotation that feeds the vault archival strategy.
# Note: the DLM API restricts policy descriptions to [0-9A-Za-z _-], so the
# description below deliberately avoids colons, equals signs, and commas.
# -----------------------------------------------------------------------------

resource "aws_dlm_lifecycle_policy" "glacier_archive_lifecycle" {
  description        = "Daily snapshot retention for Backup-tagged volumes feeding the Glacier vault archival strategy"
  execution_role_arn = aws_iam_role.dlm_exec.arn
  state              = "ENABLED"

  policy_details {
    resource_types = ["VOLUME"]

    target_tags = local.dlm_target_tags

    schedule {
      name      = "daily-0300-utc"
      copy_tags = true

      create_rule {
        cron_expression = "cron(0 3 * * ? *)"
      }

      # Snapshots inherit encryption from the encrypted source volume
      # (aws_kms_key.archive_key), so every DLM-managed snapshot is
      # encrypted with the archive CMK.
      retain_rule {
        count = var.snapshot_retention
      }
    }
  }

  tags = var.common_tags

  depends_on = [aws_iam_role_policy_attachment.dlm_exec_default]
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "glacier_vault_name" {
  description = "Name of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.name
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.arn
}

output "dlm_lifecycle_policy_arn" {
  description = "ARN of the DLM lifecycle policy."
  value       = aws_dlm_lifecycle_policy.glacier_archive_lifecycle.arn
}

# Terraform configuration for an S3 Glacier vault with KMS-encrypted SNS notifications consumed by SQS

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      ManagedBy   = "terraform"
      Environment = var.environment
    }
  }
}

# -----------------------------------------------------------------------------
# Variables (user-controlled naming/tagging only)
# -----------------------------------------------------------------------------

variable "vault_name" {
  description = "Name of the S3 Glacier vault. Lowercase alphanumeric characters and hyphens only (bounded so derived SNS/SQS names stay within AWS service limits)."
  type        = string
  default     = "terraform-archive-vault"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,64}$", var.vault_name))
    error_message = "vault_name must start with a lowercase letter or digit and contain only lowercase alphanumeric characters and hyphens (1-65 characters)."
  }
}

variable "environment" {
  description = "Environment name applied to every resource through provider default tags."
  type        = string
  default     = "prod"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,63}$", var.environment))
    error_message = "environment must be a lowercase alphanumeric/hyphen string (e.g. dev, staging, prod)."
  }
}

# -----------------------------------------------------------------------------
# Static, well-known provider metadata lookups (no pre-existing infrastructure)
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  sns_topic_name = "${var.vault_name}-notifications"
  sqs_queue_name = "${var.vault_name}-notifications"

  # The vault's own ARN, assembled from well-known account metadata so it can be
  # referenced inside the vault's resource-based access policy (a resource
  # cannot reference its own attributes).
  vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${var.vault_name}"
}

# -----------------------------------------------------------------------------
# KMS key: encrypts SNS notification payloads at rest
# -----------------------------------------------------------------------------

resource "aws_kms_key" "glacier_vault_notifications" {
  description             = "Encrypts SNS notification payloads published by the ${var.vault_name} S3 Glacier vault."
  key_usage               = "ENCRYPT_DECRYPT"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowGlacierAndSnsEncryptedPublishing"
        Effect = "Allow"
        Principal = {
          Service = [
            "glacier.amazonaws.com",
            "sns.amazonaws.com"
          ]
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "${var.vault_name}-notifications-key"
  }
}

# -----------------------------------------------------------------------------
# SNS topic: encrypted sink for vault notifications
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "glacier_vault_notifications" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.glacier_vault_notifications.arn

  tags = {
    Name = local.sns_topic_name
  }
}

# -----------------------------------------------------------------------------
# S3 Glacier vault (the Glacier vault service, not an S3 bucket storage class)
# -----------------------------------------------------------------------------

resource "aws_glacier_vault" "main" {
  name = var.vault_name

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "glacier:*"
        Resource  = local.vault_arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  notification {
    events = [
      "ArchiveRetrievalStarted",
      "ArchiveRetrievalCompleted",
      "InventoryRetrievalStarted",
      "InventoryRetrievalCompleted"
    ]
    sns_topic = aws_sns_topic.glacier_vault_notifications.arn
  }

  tags = {
    Name = var.vault_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# SNS topic policy: confused-deputy protection for Glacier publishing
# -----------------------------------------------------------------------------

resource "aws_sns_topic_policy" "glacier_vault_notifications" {
  arn = aws_sns_topic.glacier_vault_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGlacierVaultPublish"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.glacier_vault_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.main.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# SQS fan-out: programmatic consumption of vault notifications
# -----------------------------------------------------------------------------

resource "aws_sqs_queue" "glacier_vault_notifications" {
  name                    = local.sqs_queue_name
  sqs_managed_sse_enabled = true

  tags = {
    Name = local.sqs_queue_name
  }
}

resource "aws_sns_topic_subscription" "glacier_vault_notifications" {
  topic_arn            = aws_sns_topic.glacier_vault_notifications.arn
  protocol             = "sqs"
  endpoint             = aws_sqs_queue.glacier_vault_notifications.arn
  raw_message_delivery = true

  depends_on = [aws_sqs_queue_policy.glacier_vault_notifications]
}

resource "aws_sqs_queue_policy" "glacier_vault_notifications" {
  queue_url = aws_sqs_queue.glacier_vault_notifications.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowSnsTopicSendMessage"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.glacier_vault_notifications.arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = aws_sns_topic.glacier_vault_notifications.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "glacier_vault_id" {
  description = "ID (name) of the S3 Glacier vault."
  value       = aws_glacier_vault.main.id
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "sns_topic_arn" {
  description = "ARN of the KMS-encrypted SNS topic that receives Glacier vault notifications."
  value       = aws_sns_topic.glacier_vault_notifications.arn
}

output "sqs_queue_arn" {
  description = "ARN of the SQS queue that consumes Glacier vault notifications."
  value       = aws_sqs_queue.glacier_vault_notifications.arn
}

output "sqs_queue_url" {
  description = "URL of the SQS queue that consumes Glacier vault notifications."
  value       = aws_sqs_queue.glacier_vault_notifications.url
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "notification_email" {
  description = "Email endpoint subscribed to the Glacier vault notification SNS topic. The recipient must confirm the SNS subscription email."
  type        = string
  default     = "glacier-ops@example.com"
}

locals {
  common_tags = {
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_caller_identity" "current" {}

# Customer managed key used to encrypt the SNS notification topic at rest.
resource "aws_kms_key" "sns" {
  description             = "KMS key for the Glacier vault notification SNS topic"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "kms:*"
      },
      {
        Sid    = "AllowSNSToUseKey"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "glacier_vault_notifications_key" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "glacier_notifications" {
  name              = "glacier_vault_notifications"
  kms_master_key_id = aws_kms_key.sns.arn

  tags = merge(local.common_tags, { Name = "glacier_vault_notifications" })
}

# Note: S3 Glacier automatically encrypts all vault contents at rest with
# AWS-managed AES-256; there is no provider resource for vault-level
# customer-managed key encryption. Recorded below as a tag for traceability.
resource "aws_glacier_vault" "main" {
  name = "glacier_archive_vault"

  notification {
    events    = ["ArchiveRetrievalCompleted", "InventoryRetrievalCompleted"]
    sns_topic = aws_sns_topic.glacier_notifications.arn
  }

  tags = merge(local.common_tags, {
    Name       = "glacier_archive_vault"
    Encryption = "aws-managed-aes256"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Least-privilege topic policy: Glacier may only publish to this topic and
# only for events originating from the vault declared in this configuration.
resource "aws_sns_topic_policy" "glacier_publish" {
  arn = aws_sns_topic.glacier_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGlacierVaultPublish"
        Effect = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "SNS:Publish"
        Resource = aws_sns_topic.glacier_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "glacier_notifications_email" {
  topic_arn = aws_sns_topic.glacier_notifications.arn
  protocol  = "email"
  endpoint  = var.notification_email
}

output "glacier_vault_name" {
  description = "Name of the S3 Glacier vault."
  value       = aws_glacier_vault.main.name
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic receiving Glacier vault event notifications."
  value       = aws_sns_topic.glacier_notifications.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "vault_name" {
  description = "Snake_case name of the S3 Glacier vault."
  type        = string
  default     = "archive_data_vault"

  validation {
    condition     = can(regex("^[a-z][a-z0-9_]{2,49}$", var.vault_name))
    error_message = "Vault name must be snake_case: lowercase letters, digits, and underscores, 3-50 characters, starting with a letter."
  }
}

variable "tags" {
  description = "Tags applied to all resources for consistent labeling."
  type        = map(string)
  default = {
    Environment = "production"
    Name        = "archive_data_vault"
    ManagedBy   = "terraform"
  }
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  vault_name = var.vault_name

  vault_access_role_name = "${local.vault_name}-access-role"

  vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${local.vault_name}"

  glacier_vault_actions = [
    "glacier:InitiateJob",
    "glacier:DescribeJob",
    "glacier:GetJobOutput",
    "glacier:DescribeVault",
    "glacier:ListJobs",
  ]

  glacier_destructive_actions = [
    "glacier:DeleteArchive",
    "glacier:DeleteVault",
  ]
}

resource "aws_glacier_vault" "main" {
  name = local.vault_name
  tags = var.tags

  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowVaultAccessOverTLS"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.vault_access.arn
        }
        Action   = local.glacier_vault_actions
        Resource = local.vault_arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "true"
          }
        }
      },
      {
        Sid    = "DenyDestructiveActionsToNonAdminPrincipals"
        Effect = "Deny"
        Principal = {
          AWS = aws_iam_role.vault_access.arn
        }
        Action   = local.glacier_destructive_actions
        Resource = local.vault_arn
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "vault_access" {
  name = local.vault_access_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEc2ToAssumeVaultAccessRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "glacier_read_only" {
  role       = aws_iam_role.vault_access.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AWSGlacierReadOnlyAccess"
}

resource "aws_iam_role_policy" "vault_access" {
  name = "glacier-vault-scoped-access"
  role = aws_iam_role.vault_access.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ScopedGlacierVaultAccess"
        Effect   = "Allow"
        Action   = local.glacier_vault_actions
        Resource = aws_glacier_vault.main.arn
      }
    ]
  })
}

output "glacier_vault_arn" {
  description = "ARN of the S3 Glacier vault."
  value       = aws_glacier_vault.main.arn
}

output "glacier_vault_name" {
  description = "Name of the S3 Glacier vault."
  value       = aws_glacier_vault.main.name
}

output "vault_access_role_arn" {
  description = "ARN of the IAM role authorized to access the Glacier vault."
  value       = aws_iam_role.vault_access.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static, well-known provider/account metadata used to build the vault ARN and
# vault URL without hardcoding any account-specific identifiers.
data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

variable "vault_name" {
  description = "Name of the S3 Glacier vault used as the long-term archival storage target."
  type        = string
  default     = "app-archive-vault"
}

variable "retention_in_days" {
  description = "Minimum archive retention window (in days) enforced by the vault access policy."
  type        = number
  default     = 365

  validation {
    condition     = var.retention_in_days > 0
    error_message = "retention_in_days must be a positive number of days."
  }
}

variable "environment" {
  description = "Environment tag value applied to the vault."
  type        = string
  default     = "production"
}

variable "owner" {
  description = "Owner tag value applied to the vault."
  type        = string
  default     = "platform-engineering"
}

variable "purpose" {
  description = "Purpose tag value applied to the vault."
  type        = string
  default     = "long-term-archive"
}

locals {
  vault_arn = "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/${var.vault_name}"
  vault_url = "https://glacier.${data.aws_region.current.name}.amazonaws.com/${data.aws_caller_identity.current.account_id}/vaults/${var.vault_name}"
}

# S3 Glacier automatically encrypts all vault contents at rest with AES-256
# server-side encryption; no additional encryption configuration is required
# and no secrets are managed in this configuration.
#
# Note: the Terraform AWS provider does not support initiating a Glacier
# Vault Lock (there is no vault_lock block or aws_glacier_vault_lock
# resource), so the minimum archive retention window is enforced through the
# vault access policy below instead of a Vault Lock policy.
resource "aws_glacier_vault" "archive_vault" {
  name = var.vault_name

  # Vault access policy:
  #   1. DenyInsecureTransportRequests - denies all glacier service requests
  #      made over insecure transport for this vault.
  #   2. DenyDeleteArchiveBeforeRetentionWindow - enforces the minimum archive
  #      retention window by denying glacier:DeleteArchive for any archive
  #      younger than var.retention_in_days (glacier:ArchiveAgeInDays
  #      condition, expressed as a JSON string as IAM numeric conditions
  #      require).
  #
  # Both statements are scoped to this vault's ARN only, so the policy never
  # combines a wildcard Action with a wildcard Resource.
  access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransportRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "glacier:*"
        Resource  = local.vault_arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "DenyDeleteArchiveBeforeRetentionWindow"
        Effect    = "Deny"
        Principal = "*"
        Action    = "glacier:DeleteArchive"
        Resource  = local.vault_arn
        Condition = {
          NumericLessThan = {
            "glacier:ArchiveAgeInDays" = tostring(var.retention_in_days)
          }
        }
      }
    ]
  })

  tags = {
    Environment = var.environment
    Owner       = var.owner
    Purpose     = var.purpose
  }

  # The vault holds immutable, long-lived archives; block accidental deletion.
  lifecycle {
    prevent_destroy = true
  }
}

output "vault_name" {
  description = "Name of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.name
}

output "vault_arn" {
  description = "ARN of the S3 Glacier archive vault."
  value       = aws_glacier_vault.archive_vault.arn
}

output "vault_url" {
  description = "HTTPS URL of the S3 Glacier archive vault."
  value       = local.vault_url
}

output "vault_lock_status" {
  description = "Vault Lock completion status. The Terraform AWS provider does not support Glacier Vault Lock initiation, so no Vault Lock is provisioned here; minimum archive retention is instead enforced through the vault access policy (DenyDeleteArchiveBeforeRetentionWindow statement)."
  value       = "NotConfigured"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "environment" {
  description = "Environment name applied to all resource tags."
  type        = string
  default     = "production"
}

variable "notification_email" {
  description = "Email address subscribed to Glacier vault archive-retrieval notifications. Non-secret default keeps terraform apply unattended."
  type        = string
  default     = "cloud-ops@example.com"
}

# ------------------------------------------------------------------------------
# Data sources (static lookups only)
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------

locals {
  vault_name = "archive_vault"
  topic_name = "glacier-notifications"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ------------------------------------------------------------------------------
# KMS key used for server-side encryption of the notification SNS topic
# ------------------------------------------------------------------------------

resource "aws_kms_key" "glacier_notifications" {
  description             = "Customer managed key for server-side encryption of the Glacier vault notification SNS topic."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableIAMPermissions"
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid       = "AllowGlacierToEncryptNotifications"
        Effect    = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.topic_name}-key"
  })
}

# ------------------------------------------------------------------------------
# SNS topic receiving Glacier vault event notifications
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "glacier_notifications" {
  name              = local.topic_name
  display_name      = "GlacierVaultNotifications"
  kms_master_key_id = aws_kms_key.glacier_notifications.key_id

  tags = merge(local.common_tags, {
    Name = local.topic_name
  })
}

resource "aws_sns_topic_policy" "glacier_notifications" {
  arn = aws_sns_topic.glacier_notifications.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowGlacierVaultPublish"
        Effect    = "Allow"
        Principal = {
          Service = "glacier.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.glacier_notifications.arn
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_glacier_vault.archive_vault.arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Glacier vault with archive-retrieval-completed notification wiring
# ------------------------------------------------------------------------------

resource "aws_glacier_vault" "archive_vault" {
  name = local.vault_name

  notification {
    events    = ["ArchiveRetrievalCompleted"]
    sns_topic = aws_sns_topic.glacier_notifications.arn
  }

  tags = merge(local.common_tags, {
    Name = local.vault_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_subscription" "archive_retrieval_email" {
  topic_arn = aws_sns_topic.glacier_notifications.arn
  protocol  = "email"
  endpoint  = var.notification_email
}

###############################################################################
# main.tf
#
# Internet-facing Network Load Balancer (NLB) in front of a single t2.micro
# EC2 instance running a lightweight HTTP server on port 80.
#
# Fully self-contained: VPC, subnets, IGW, routing, security group, EC2
# target, NLB, target group, listener, and attachment are all declared here.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  project     = "nlb-ec2-demo"
  environment = "dev"

  common_tags = {
    project     = local.project
    environment = local.environment
    managed_by  = "terraform"
  }
}

###############################################################################
# Data sources (static/well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-b"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security
###############################################################################

resource "aws_security_group" "nlb_target" {
  name        = "${local.project}-nlb-target-sg"
  description = "Allow HTTP to the NLB target from anywhere (NLB preserves client source IPs)"
  vpc_id      = aws_vpc.main.id

  # Justification: an internet-facing NLB preserves the client source IP for
  # TCP traffic, so the target security group must accept port 80 from
  # 0.0.0.0/0. Port 80 is the only publicly allowed inbound port; no other
  # inbound ports are open.
  ingress {
    description = "HTTP from anywhere (internet-facing NLB preserves client source IPs)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-nlb-target-sg"
  })
}

###############################################################################
# EC2 target instance
###############################################################################

resource "aws_instance" "web" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t2.micro"
  subnet_id                   = aws_subnet.public_a.id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.nlb_target.id]

  root_block_device {
    encrypted             = true
    volume_size           = 8
    volume_type           = "gp3"
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data_replace_on_change = true

  user_data = <<-EOF
#!/bin/bash
set -euxo pipefail

# Install and start nginx from the Amazon Linux 2023 repositories so the
# NLB TCP health checks on port 80 pass.
dnf install -y nginx

echo "<h1>Hello from $(hostname -f) behind an internet-facing NLB</h1>" > /usr/share/nginx/html/index.html

systemctl enable nginx
systemctl start nginx
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.project}-web"
  })
}

###############################################################################
# Network Load Balancer
###############################################################################

resource "aws_lb" "nlb" {
  name               = "${local.project}-nlb"
  load_balancer_type = "network"
  internal           = false
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  # The only target lives in one AZ; cross-zone load balancing lets the NLB
  # node in the second AZ forward traffic to it.
  enable_cross_zone_load_balancing = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-nlb"
  })
}

resource "aws_lb_target_group" "web" {
  name        = "${local.project}-tg"
  port        = 80
  protocol    = "TCP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "80"
    interval            = 30
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.nlb.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.web.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-http-listener"
  })
}

resource "aws_lb_target_group_attachment" "web" {
  target_group_arn = aws_lb_target_group.web.arn
  target_id        = aws_instance.web.id
  port             = 80
}

###############################################################################
# Outputs
###############################################################################

output "nlb_dns_name" {
  description = "Public DNS name of the internet-facing NLB (primary test endpoint)"
  value       = aws_lb.nlb.dns_name
}

output "nlb_arn" {
  description = "ARN of the Network Load Balancer"
  value       = aws_lb.nlb.arn
}

output "web_instance_id" {
  description = "Instance ID of the EC2 target behind the NLB"
  value       = aws_instance.web.id
}

output "web_instance_public_ip" {
  description = "Public IPv4 address of the EC2 target behind the NLB"
  value       = aws_instance.web.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "alb-${var.environment}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/20"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-1"
    Environment = var.environment
  }
}

resource "aws_subnet" "public_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.16.0/20"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-2"
    Environment = var.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for the internet-facing ALB: allows public HTTP/HTTPS ingress and restricts egress to HTTP within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP to backend targets within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "${local.name_prefix}-alb-sg"
    Environment = var.environment
  }
}

resource "aws_lb_target_group" "main" {
  name        = "${local.name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    timeout             = 5
  }

  tags = {
    Name        = "${local.name_prefix}-tg"
    Environment = var.environment
  }
}

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-alb"
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_1.id, aws_subnet.public_2.id]

  drop_invalid_header_fields = true
  enable_deletion_protection = true
  idle_timeout               = 60

  tags = {
    Name        = "${local.name_prefix}-alb"
    Environment = var.environment
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name        = "${local.name_prefix}-listener-http"
    Environment = var.environment
  }
}

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "alb_arn" {
  description = "ARN of the Application Load Balancer."
  value       = aws_lb.main.arn
}

output "target_group_arn" {
  description = "ARN of the ALB target group."
  value       = aws_lb_target_group.main.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-lb-tf-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "test-lb-tf-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.0.0/20"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-lb-tf-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.16.0/20"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "test-lb-tf-public-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "test-lb-tf-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb_sg" {
  name        = "test-lb-tf-alb-sg"
  description = "Security group for the test-lb-tf application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "test-lb-tf-alb-sg"
  }
}

resource "aws_lb" "test_lb_tf" {
  name                       = "test-lb-tf"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  enable_deletion_protection = true

  tags = {
    Name = "test-lb-tf"
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging"
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the NLB target instances"
  type        = string
  default     = "t3.micro"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  az_count     = 2
  selected_azs = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Component   = "network-load-balancer"
    }
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc-${var.environment}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw-${var.environment}"
  })
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.selected_azs[count.index]
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "public-${local.selected_azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-rt-${var.environment}"
  })
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "targets" {
  name        = "nlb-targets-${var.environment}"
  description = "Allow HTTP traffic to the NLB target instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere (application port 80 only)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP health checks from NLB nodes within the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "nlb-targets-sg-${var.environment}"
  })
}

resource "aws_launch_template" "target" {
  name          = "nlb-target-lt-${var.environment}"
  description   = "Launch template for NLB target instances"
  image_id      = data.aws_ami.al2023.id
  instance_type = var.instance_type

  vpc_security_group_ids = [aws_security_group.targets.id]

  update_default_version = true

  user_data = base64encode(<<-EOT
    #!/bin/bash
    dnf install -y nginx
    systemctl enable nginx
    systemctl start nginx
  EOT
  )

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 8
      volume_type = "gp3"
      encrypted   = true
    }
  }

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "nlb-target-${var.environment}"
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name = "nlb-target-${var.environment}"
    })
  }

  tags = merge(local.common_tags, {
    Name = "nlb-target-lt-${var.environment}"
  })
}

resource "aws_autoscaling_group" "targets" {
  name                      = "nlb-targets-asg-${var.environment}"
  min_size                  = local.az_count
  max_size                  = local.az_count
  desired_capacity          = local.az_count
  vpc_zone_identifier       = aws_subnet.public[*].id
  target_group_arns         = [aws_lb_target_group.main.arn]
  health_check_type         = "ELB"
  health_check_grace_period = 60

  launch_template {
    id      = aws_launch_template.target.id
    version = aws_launch_template.target.latest_version
  }

  instance_refresh {
    strategy = "Rolling"

    preferences {
      min_healthy_percentage = 100
    }
  }

  dynamic "tag" {
    for_each = local.common_tags

    content {
      key                 = tag.key
      value               = tag.value
      propagate_at_launch = true
    }
  }
}

resource "aws_lb" "main" {
  name                             = "main-nlb-${var.environment}"
  load_balancer_type               = "network"
  internal                         = false
  ip_address_type                  = "ipv4"
  enable_cross_zone_load_balancing = true
  enable_deletion_protection       = true

  subnets = aws_subnet.public[*].id

  tags = merge(local.common_tags, {
    Name = "main-nlb-${var.environment}"
  })
}

resource "aws_lb_target_group" "main" {
  name                 = "main-tg-${var.environment}"
  port                 = 80
  protocol             = "TCP"
  vpc_id               = aws_vpc.main.id
  target_type          = "instance"
  deregistration_delay = 30

  health_check {
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    port                = "traffic-port"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "main-tg-${var.environment}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "main-listener-${var.environment}"
  })
}

output "nlb_dns_name" {
  description = "Public DNS name of the Network Load Balancer"
  value       = aws_lb.main.dns_name
}

output "target_group_arn" {
  description = "ARN of the NLB target group"
  value       = aws_lb_target_group.main.arn
}

output "asg_name" {
  description = "Name of the Auto Scaling Group serving as NLB targets"
  value       = aws_autoscaling_group.targets.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  name_prefix       = "nlb-eip"
  environment       = "production"
  access_log_prefix = "nlb-access-logs"
  log_bucket_name   = "nlb-access-logs-${data.aws_caller_identity.current.account_id}"
}

# -----------------------------------------------------------------------------
# Network foundation
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.name_prefix}-vpc"
    Environment = local.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.name_prefix}-igw"
    Environment = local.environment
  }
}

resource "aws_subnet" "public_az1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-az1"
    Environment = local.environment
  }
}

resource "aws_subnet" "public_az2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name        = "${local.name_prefix}-public-az2"
    Environment = local.environment
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.name_prefix}-public-rt"
    Environment = local.environment
  }
}

resource "aws_route_table_association" "public_az1" {
  subnet_id      = aws_subnet.public_az1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_az2" {
  subnet_id      = aws_subnet.public_az2.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Static Elastic IPs for the Network Load Balancer (one per AZ)
# -----------------------------------------------------------------------------

resource "aws_eip" "nlb_az1" {
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-eip-az1"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "nlb_az2" {
  domain = "vpc"

  tags = {
    Name        = "${local.name_prefix}-eip-az2"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# S3 bucket for NLB access logging
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "access_logs" {
  bucket = local.log_bucket_name

  tags = {
    Name        = "${local.name_prefix}-access-logs"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  bucket = aws_s3_bucket.access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBLogDeliveryPutObject"
        Effect    = "Allow"
        Principal = {
          Service = "logdelivery.elasticloadbalancing.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.access_logs.arn}/${local.access_log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# Internet-facing Network Load Balancer with explicitly specified Elastic IPs
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-nlb"
  load_balancer_type = "network"
  internal           = false
  ip_address_type    = "ipv4"

  subnet_mapping {
    subnet_id     = aws_subnet.public_az1.id
    allocation_id = aws_eip.nlb_az1.id
  }

  subnet_mapping {
    subnet_id     = aws_subnet.public_az2.id
    allocation_id = aws_eip.nlb_az2.id
  }

  access_logs {
    bucket  = aws_s3_bucket.access_logs.id
    prefix  = local.access_log_prefix
    enabled = true
  }

  tags = {
    Name        = "${local.name_prefix}-nlb"
    Environment = local.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_lb_target_group" "main" {
  name     = "${local.name_prefix}-tg"
  port     = 80
  protocol = "TCP"
  vpc_id   = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "traffic-port"
    interval            = 30
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = {
    Name        = "${local.name_prefix}-tg"
    Environment = local.environment
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name        = "${local.name_prefix}-listener-80"
    Environment = local.environment
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "nlb_dns_name" {
  description = "Public DNS name of the Network Load Balancer."
  value       = aws_lb.main.dns_name
}

output "nlb_static_ip_az1" {
  description = "Static Elastic IP serving the Network Load Balancer in the first AZ."
  value       = aws_eip.nlb_az1.public_ip
}

output "nlb_static_ip_az2" {
  description = "Static Elastic IP serving the Network Load Balancer in the second AZ."
  value       = aws_eip.nlb_az2.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to resource names and tags."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "internal_alb_${var.environment}"

  # "internal" must not be the leading token: the AWS ELB API reserves the
  # "internal-" name prefix, so it is placed after the environment segment.
  alb_name_prefix = "${var.environment}-internal"

  # Statically assigned private IPs, one per private subnet, each inside the
  # corresponding subnet CIDR (10.0.1.0/24 and 10.0.2.0/24).
  alb_private_ips = [
    "10.0.1.10",
    "10.0.2.10",
  ]

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_private_b"
  })
}

resource "aws_security_group" "alb_sg" {
  name        = "${local.alb_name_prefix}-alb-sg"
  description = "Internal ALB ingress restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from within the VPC only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS from within the VPC only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb_sg"
  })
}

resource "aws_security_group" "backend_sg" {
  name        = "${local.alb_name_prefix}-backend-sg"
  description = "Allows HTTP only from the internal ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the internal ALB only (SG-to-SG reference)"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "Egress restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_backend_sg"
  })
}

resource "aws_lb" "internal_alb" {
  name                       = "${local.alb_name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  drop_invalid_header_fields = true

  subnet_mapping {
    subnet_id            = aws_subnet.private_a.id
    private_ipv4_address = local.alb_private_ips[0]
  }

  subnet_mapping {
    subnet_id            = aws_subnet.private_b.id
    private_ipv4_address = local.alb_private_ips[1]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb"
  })
}

resource "aws_lb_target_group" "app_tg" {
  name        = "${local.alb_name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_app_tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app_tg.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_http_listener"
  })
}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_instance" "backend" {
  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private_a.id
  vpc_security_group_ids      = [aws_security_group.backend_sg.id]
  associate_public_ip_address = false

  user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable --now httpd
    echo "Hello from $(hostname -f)" > /var/www/html/index.html
  EOF

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_backend"
  })
}

resource "aws_lb_target_group_attachment" "backend" {
  target_group_arn = aws_lb_target_group.app_tg.arn
  target_id        = aws_instance.backend.id
  port             = 80
}

output "alb_dns_name" {
  description = "Private DNS name of the internal application load balancer."
  value       = aws_lb.internal_alb.dns_name
}

output "alb_private_ips" {
  description = "Statically assigned private IPs of the internal application load balancer."
  value       = aws_lb.internal_alb.subnet_mapping[*].private_ipv4_address
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource tagging only."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ----------------------------------------------------------------------------
# Static, well-known lookups (no pre-existing infrastructure required)
# ----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ----------------------------------------------------------------------------
# Networking
# ----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "vpc-main"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "subnet-public-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "igw-main"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "rt-public"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ----------------------------------------------------------------------------
# Security groups
# ----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "alb-main"
  description = "Public ALB security group: allow HTTP/HTTPS from the internet"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "alb-main"
  })
}

resource "aws_security_group" "instances" {
  name        = "ec2-web"
  description = "Web instance security group: allow HTTP only from the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "ec2-web"
  })
}

# ----------------------------------------------------------------------------
# Instance IAM (least-privilege SSM access, no key pairs required)
# ----------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "web" {
  name               = "ec2-web-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "ec2-web-role"
  })
}

resource "aws_iam_role_policy_attachment" "web_ssm" {
  role       = aws_iam_role.web.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "web" {
  name = "ec2-web-profile"
  role = aws_iam_role.web.name
}

# ----------------------------------------------------------------------------
# Web instances
# ----------------------------------------------------------------------------

resource "aws_instance" "web" {
  count = 2

  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public[count.index].id
  vpc_security_group_ids = [aws_security_group.instances.id]
  iam_instance_profile   = aws_iam_instance_profile.web.name

  user_data = <<-EOF
#!/bin/bash
set -euo pipefail

dnf install -y python3

mkdir -p /srv/www
echo "<html><body><h1>Hello from ec2-web-${count.index + 1}</h1></body></html>" > /srv/www/index.html

{
  echo "[Unit]"
  echo "Description=Lightweight Python HTTP server on port 80"
  echo "After=network-online.target"
  echo ""
  echo "[Service]"
  echo "ExecStart=/usr/bin/python3 -m http.server 80 --directory /srv/www"
  echo "Restart=always"
  echo ""
  echo "[Install]"
  echo "WantedBy=multi-user.target"
} > /etc/systemd/system/webserver.service

systemctl daemon-reload
systemctl enable --now webserver.service
EOF

  user_data_replace_on_change = true

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "ec2-web-${count.index + 1}"
  })

  depends_on = [aws_iam_role_policy_attachment.web_ssm]
}

# ----------------------------------------------------------------------------
# Load balancer, target group, listener, and target registration
# ----------------------------------------------------------------------------

resource "aws_lb_target_group" "main" {
  name        = "tg-main"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  deregistration_delay = 30

  tags = merge(local.common_tags, {
    Name = "tg-main"
  })
}

resource "aws_lb" "main" {
  name               = "alb-main"
  load_balancer_type = "application"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = [for subnet in aws_subnet.public : subnet.id]

  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = merge(local.common_tags, {
    Name = "alb-main"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "alb-main-http-listener"
  })
}

resource "aws_lb_target_group_attachment" "web" {
  count = 2

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.web[count.index].id
  port             = 80
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the application load balancer."
  value       = aws_lb.main.dns_name
}

output "target_group_arn" {
  description = "ARN of the target group backing the load balancer."
  value       = aws_lb_target_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "dev"
}

locals {
  name_prefix = "alb-nlb-chain"

  # Static, plan-time-deterministic private IPs for the internal NLB,
  # derived from each subnet's literal CIDR block (single source of truth).
  nlb_private_ip_a = cidrhost(aws_subnet.public_a.cidr_block, 10)
  nlb_private_ip_b = cidrhost(aws_subnet.public_b.cidr_block, 10)

  common_tags = {
    Environment = var.environment
  }
}

# ---------------------------------------------------------------------------
# Availability zone lookup (static provider metadata)
# ---------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Network foundation
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# AMI lookup - Amazon Linux 2023 (public/well-known AMI lookup)
# ---------------------------------------------------------------------------
data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb_sg" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Front-tier ALB security group: inbound HTTP/HTTPS from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

resource "aws_security_group" "instance_sg" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Backend instance security group: inbound HTTP only from the ALB security group"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the front-tier ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

# ---------------------------------------------------------------------------
# Front-tier: internet-facing Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "front" {
  name               = "${local.name_prefix}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_target_group" "alb_front" {
  name        = "${local.name_prefix}-alb-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "HTTP"
    path                = "/"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-tg"
  })
}

# ALB -> NLB chaining: register the NLB's static private IPs as IP targets
resource "aws_lb_target_group_attachment" "nlb_ip_a" {
  target_group_arn = aws_lb_target_group.alb_front.arn
  target_id        = local.nlb_private_ip_a
  port             = 80

  depends_on = [aws_lb_listener.nlb_tcp_80]
}

resource "aws_lb_target_group_attachment" "nlb_ip_b" {
  target_group_arn = aws_lb_target_group.alb_front.arn
  target_id        = local.nlb_private_ip_b
  port             = 80

  depends_on = [aws_lb_listener.nlb_tcp_80]
}

resource "aws_lb_listener" "alb_http_80" {
  load_balancer_arn = aws_lb.front.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_front.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-listener-80"
  })
}

# ---------------------------------------------------------------------------
# Back-tier: internal Network Load Balancer with static private IPs
# ---------------------------------------------------------------------------
resource "aws_lb" "internal_nlb" {
  name               = "${local.name_prefix}-nlb"
  internal           = true
  load_balancer_type = "network"

  subnet_mapping {
    subnet_id            = aws_subnet.public_a.id
    private_ipv4_address = local.nlb_private_ip_a
  }

  subnet_mapping {
    subnet_id            = aws_subnet.public_b.id
    private_ipv4_address = local.nlb_private_ip_b
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb"
  })
}

resource "aws_lb_target_group" "nlb_backend" {
  name        = "${local.name_prefix}-nlb-tg"
  port        = 80
  protocol    = "TCP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "80"
    interval            = 30
    timeout             = 10
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb-tg"
  })
}

resource "aws_lb_listener" "nlb_tcp_80" {
  load_balancer_arn = aws_lb.internal_nlb.arn
  port              = 80
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb_backend.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nlb-listener-80"
  })
}

# ---------------------------------------------------------------------------
# Backend tier: EC2 instances (chain terminus)
# ---------------------------------------------------------------------------
resource "aws_instance" "backend_a" {
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_a.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Backend node: $(hostname -f)</h1>" > /var/www/html/index.html
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-a"
  })
}

resource "aws_instance" "backend_b" {
  ami                    = data.aws_ami.amazon_linux_2023.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public_b.id
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  root_block_device {
    encrypted   = true
    volume_size = 8
    volume_type = "gp3"
  }

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Backend node: $(hostname -f)</h1>" > /var/www/html/index.html
  EOF

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-backend-b"
  })
}

# Register both instances into the NLB backend target group
resource "aws_lb_target_group_attachment" "backend_a" {
  target_group_arn = aws_lb_target_group.nlb_backend.arn
  target_id        = aws_instance.backend_a.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "backend_b" {
  target_group_arn = aws_lb_target_group.nlb_backend.arn
  target_id        = aws_instance.backend_b.id
  port             = 80
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "alb_dns_name" {
  description = "Public DNS name of the front-tier Application Load Balancer."
  value       = aws_lb.front.dns_name
}

output "nlb_dns_name" {
  description = "Private DNS name of the internal Network Load Balancer."
  value       = aws_lb.internal_nlb.dns_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for consistent Name/Environment tags across all resources"
  type        = string
  default     = "alb-redirect"
}

locals {
  common_tags = {
    Name        = var.project_name
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = local.common_tags
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = local.common_tags
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = local.common_tags
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "${var.project_name}-alb-sg"
  description = "Public web ports for the internet-facing redirect ALB"
  vpc_id      = aws_vpc.main.id

  # Justification: this is an internet-facing ALB whose sole purpose is to
  # redirect public web traffic; TCP/80 is the entry point that issues the
  # HTTP -> HTTPS redirect.
  ingress {
    description = "HTTP from anywhere; listener issues a permanent redirect to HTTPS"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Justification: TCP/443 is the redirect destination, so it is opened for
  # public web traffic destined for this load balancer only.
  ingress {
    description = "HTTPS from anywhere; the redirect destination"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

resource "aws_lb" "alb" {
  name                       = var.project_name
  load_balancer_type         = "application"
  internal                   = false
  ip_address_type            = "ipv4"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = local.common_tags
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
      host        = "#{host}"
      path        = "#{path}"
      query       = "#{query}"
    }
  }

  tags = local.common_tags
}

output "alb_dns_name" {
  description = "Public DNS name of the ALB; send an HTTP request here to verify the 301 redirect"
  value       = aws_lb.alb.dns_name
}

output "http_listener_arn" {
  description = "ARN of the HTTP listener that performs the permanent redirect"
  value       = aws_lb_listener.http.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "dev"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-vpc"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-igw"
    }
  )
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.0.0/20"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-public-a"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.16.0/20"
  map_public_ip_on_launch = true

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-public-b"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-public-rt"
    }
  )
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "alb-fixed-response-sg"
  description = "Allows inbound HTTP to the fixed-response ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-sg"
    }
  )
}

resource "aws_lb" "main" {
  name                       = "alb-fixed-response"
  load_balancer_type         = "application"
  internal                   = false
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response"
    }
  )
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "OK - served by ALB fixed-response"
      status_code  = "200"
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = "alb-fixed-response-http-listener"
    }
  )
}

output "alb_dns_name" {
  description = "Public DNS name of the ALB. Verify the fixed response with: curl http://$(terraform output -raw alb_dns_name)"
  value       = aws_lb.main.dns_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used only for resource naming and tagging, never for infrastructure attributes."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z]([a-z0-9-]{0,14}[a-z0-9])?$", var.environment))
    error_message = "environment must be 1-16 lowercase alphanumeric characters or hyphens, start with a letter, and not end with a hyphen."
  }
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN. When non-empty, an HTTPS listener with the identical authenticate-cognito -> forward action pair is created, the port-80 listener becomes a 301 redirect to HTTPS, and TCP 443 ingress is opened on the ALB security group. Leave empty (default) so apply runs unattended with only the HTTP listener."
  type        = string
  default     = ""

  validation {
    condition     = var.certificate_arn == "" || startswith(var.certificate_arn, "arn:")
    error_message = "certificate_arn must be an ACM certificate ARN (arn:...) or an empty string."
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix          = "cognito-alb-${var.environment}"
  tls_enabled          = var.certificate_arn != ""
  alb_log_prefix       = "alb-logs"
  alb_logs_bucket_name = lower("alb-logs-${var.environment}-${random_string.log_suffix.result}")
}

# -----------------------------------------------------------------------------
# Data sources (static / well-known lookups only, no pre-existing infrastructure)
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_region" "current" {}

data "aws_elb_service_account" "main" {}

# -----------------------------------------------------------------------------
# Random identifiers
# -----------------------------------------------------------------------------

resource "random_string" "cognito_prefix" {
  length    = 12
  upper     = false
  lower     = true
  numeric   = false
  special   = false
  min_lower = 12
}

resource "random_string" "log_suffix" {
  length    = 8
  upper     = false
  lower     = true
  numeric   = false
  special   = false
  min_lower = 1
}

# -----------------------------------------------------------------------------
# Networking
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_prefix}-public-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security groups (standalone rules so the conditional TLS rule can be added
# without mixing inline and aws_security_group_rule resources)
# -----------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "ALB: inbound HTTP(S) from the internet, egress to backend on TCP 80 only"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-alb-sg"
  }
}

resource "aws_security_group" "backend" {
  name        = "${local.name_prefix}-backend-sg"
  description = "Backend: inbound TCP 80 from the ALB only, egress for package retrieval"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-backend-sg"
  }
}

resource "aws_security_group_rule" "alb_ingress_http" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "alb_ingress_https" {
  count = local.tls_enabled ? 1 : 0

  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "alb_egress_http_to_backend" {
  type                     = "egress"
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  security_group_id        = aws_security_group.alb.id
  source_security_group_id = aws_security_group.backend.id
}

resource "aws_security_group_rule" "backend_ingress_http_from_alb" {
  type                     = "ingress"
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  security_group_id        = aws_security_group.backend.id
  source_security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "backend_egress_https_packages" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.backend.id
}

resource "aws_security_group_rule" "backend_egress_http_packages" {
  type              = "egress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.backend.id
}

# -----------------------------------------------------------------------------
# Cognito user pool, ALB app client, and hosted UI domain
# -----------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-users"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  # allow_admin_create_user_only = false keeps self sign-up enabled
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_CODE"
  }

  email_configuration {
    email_sending_account = "COGNITO_DEFAULT"
  }

  deletion_protection = "ACTIVE"

  tags = {
    Name = "${local.name_prefix}-users"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "alb" {
  name         = "${local.name_prefix}-alb-client"
  user_pool_id = aws_cognito_user_pool.main.id

  # Client secret is required for ALB "authenticate-cognito" federation.
  # It is retrieved by the ALB service itself and is never output here.
  generate_secret = true

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
  ]

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["openid", "email", "profile"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = ["https://${aws_lb.main.dns_name}/oauth2/idpresponse"]
  logout_urls   = ["https://${aws_lb.main.dns_name}"]

  token_validity_units {
    access_token  = "hours"
    id_token      = "hours"
    refresh_token = "days"
  }

  access_token_validity  = 1
  id_token_validity      = 1
  refresh_token_validity = 30
}

resource "aws_cognito_user_pool_domain" "main" {
  domain       = random_string.cognito_prefix.result
  user_pool_id = aws_cognito_user_pool.main.id
}

# -----------------------------------------------------------------------------
# Backend compute
# -----------------------------------------------------------------------------

resource "aws_instance" "backend" {
  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public_a.id
  vpc_security_group_ids      = [aws_security_group.backend.id]
  associate_public_ip_address = true

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    volume_size           = 8
    volume_type           = "gp3"
    encrypted             = true
    delete_on_termination = true
  }

  user_data = <<-EOT
    #!/bin/bash
    set -euxo pipefail
    dnf install -y nginx
    systemctl enable --now nginx
    echo '<h1>Backend OK - served through the Cognito-authenticated ALB</h1>' > /usr/share/nginx/html/index.html
  EOT

  depends_on = [aws_route_table_association.public_a]

  tags = {
    Name = "${local.name_prefix}-backend"
  }
}

# -----------------------------------------------------------------------------
# Target group
# -----------------------------------------------------------------------------

resource "aws_lb_target_group" "app" {
  name        = "${local.name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${local.name_prefix}-tg"
  }
}

resource "aws_lb_target_group_attachment" "backend" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.backend.id
  port             = 80
}

# -----------------------------------------------------------------------------
# ALB access log bucket
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "alb_logs" {
  bucket = local.alb_logs_bucket_name

  tags = {
    Name = local.alb_logs_bucket_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket                  = aws_s3_bucket.alb_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    id     = "expire-alb-access-logs"
    status = "Enabled"

    filter {
      prefix = "${local.alb_log_prefix}/"
    }

    expiration {
      days = 90
    }

    noncurrent_version_expiration {
      noncurrent_days = 30
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_ownership_controls" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowELBLogDeliveryPutObject"
        Effect    = "Allow"
        Principal = {
          AWS = data.aws_elb_service_account.main.arn
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.alb_logs.arn}/${local.alb_log_prefix}/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

# -----------------------------------------------------------------------------
# Application Load Balancer
# -----------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = local.name_prefix
  load_balancer_type = "application"
  internal           = false
  ip_address_type    = "ipv4"

  security_groups = [aws_security_group.alb.id]
  subnets         = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.alb_log_prefix
    enabled = true
  }

  depends_on = [
    aws_route_table_association.public_a,
    aws_route_table_association.public_b,
    aws_s3_bucket_policy.alb_logs,
  ]

  tags = {
    Name = local.name_prefix
  }
}

# -----------------------------------------------------------------------------
# Listeners
# -----------------------------------------------------------------------------

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  # When TLS is enabled the port-80 listener becomes a permanent 301 redirect.
  dynamic "default_action" {
    for_each = local.tls_enabled ? [1] : []
    content {
      type  = "redirect"
      order = 1

      redirect {
        port        = "443"
        protocol    = "HTTPS"
        status_code = "HTTP_301"
      }
    }
  }

  # When TLS is disabled the port-80 listener fronts the Cognito auth flow:
  # authenticate-cognito (order 1) followed by forward (order 2), so the
  # authenticate-cognito action is never the terminal action.
  dynamic "default_action" {
    for_each = local.tls_enabled ? [] : [1]
    content {
      type  = "authenticate-cognito"
      order = 1

      authenticate_cognito {
        user_pool_arn              = aws_cognito_user_pool.main.arn
        user_pool_client_id        = aws_cognito_user_pool_client.alb.id
        user_pool_domain           = aws_cognito_user_pool_domain.main.domain
        on_unauthenticated_request = "authenticate"
        session_cookie_name        = "AWSELBAuthSessionCookie-1"
        session_timeout            = 3600
      }
    }
  }

  dynamic "default_action" {
    for_each = local.tls_enabled ? [] : [1]
    content {
      type             = "forward"
      order            = 2
      target_group_arn = aws_lb_target_group.app.arn
    }
  }
}

resource "aws_lb_listener" "https" {
  count = local.tls_enabled ? 1 : 0

  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  certificate_arn   = var.certificate_arn
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"

  default_action {
    type  = "authenticate-cognito"
    order = 1

    authenticate_cognito {
      user_pool_arn              = aws_cognito_user_pool.main.arn
      user_pool_client_id        = aws_cognito_user_pool_client.alb.id
      user_pool_domain           = aws_cognito_user_pool_domain.main.domain
      on_unauthenticated_request = "authenticate"
      session_cookie_name        = "AWSELBAuthSessionCookie-1"
      session_timeout            = 3600
    }
  }

  default_action {
    type             = "forward"
    order            = 2
    target_group_arn = aws_lb_target_group.app.arn
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "cognito_hosted_ui_sign_in_url" {
  description = "Cognito hosted UI sign-in URL used by the ALB authenticate-cognito action."
  value       = "https://${aws_cognito_user_pool_domain.main.domain}.auth.${data.aws_region.current.name}.amazoncognito.com/login"
}

output "target_group_arn" {
  description = "ARN of the target group backing the authenticated listener."
  value       = aws_lb_target_group.app.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all defaulted — terraform apply runs fully non-interactive)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging and resource naming."
  type        = string
  default     = "dev"
}

variable "domain_name" {
  description = "Public domain name for the ALB HTTPS listener certificate."
  type        = string
  default     = "app.example.com"
}

variable "oidc_issuer" {
  description = "OIDC issuer identifier of the identity provider."
  type        = string
  default     = "https://accounts.google.com"
}

variable "oidc_authorization_endpoint" {
  description = "OIDC authorization endpoint of the identity provider."
  type        = string
  default     = "https://accounts.google.com/o/oauth2/v2/auth"
}

variable "oidc_token_endpoint" {
  description = "OIDC token endpoint of the identity provider."
  type        = string
  default     = "https://oauth2.googleapis.com/token"
}

variable "oidc_user_info_endpoint" {
  description = "OIDC user info endpoint of the identity provider."
  type        = string
  default     = "https://openidconnect.googleapis.com/v1/userinfo"
}

variable "oidc_client_id" {
  description = "OIDC client ID issued by the identity provider."
  type        = string
  default     = "replace-with-your-oidc-client-id"
}

variable "application_port" {
  description = "Port the backend targets listen on."
  type        = number
  default     = 80
}

variable "health_check_path" {
  description = "Health check path for the target group."
  type        = string
  default     = "/"
}

variable "tags" {
  description = "Tags applied to every resource (merged with per-resource Name tags)."
  type        = map(string)
  default = {
    Project   = "alb-oidc"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Data sources (static lookups only) and locals
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  azs             = slice(data.aws_availability_zones.available.names, 0, 2)
  log_prefix      = "alb-access-logs"
  log_bucket_name = "alb-oidc-logs-${data.aws_caller_identity.current.account_id}-${var.environment}"
  common_tags     = merge(var.tags, { Environment = var.environment })
}

###############################################################################
# Networking (built from scratch)
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "alb-oidc-vpc-${var.environment}" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "alb-oidc-igw-${var.environment}" })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "public-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 11)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "private-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "public-rt-${var.environment}" })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count = 2

  domain     = "vpc"
  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-eip-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_nat_gateway" "main" {
  count = 2

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  depends_on    = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(local.common_tags, { Name = "private-rt-${local.azs[count.index]}-${var.environment}" })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "alb-sg-${var.environment}"
  description = "ALB ingress: HTTPS and HTTP from the internet only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP from anywhere (redirected to HTTPS)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "All outbound to targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "alb-sg-${var.environment}" })
}

resource "aws_security_group" "targets" {
  name        = "app-sg-${var.environment}"
  description = "Application targets: application port from the ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from the ALB security group"
    from_port       = var.application_port
    to_port         = var.application_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "All outbound (software updates via NAT)"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "app-sg-${var.environment}" })
}

###############################################################################
# Backend targets (private instances)
###############################################################################

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.al2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.private[count.index].id
  vpc_security_group_ids      = [aws_security_group.targets.id]
  associate_public_ip_address = false

  user_data = <<-EOT
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable --now httpd
    echo "<h1>Healthy - backend instance ${count.index}</h1>" > /var/www/html/index.html
  EOT

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  tags = merge(local.common_tags, { Name = "app-${local.azs[count.index]}-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Target group and registration
###############################################################################

resource "aws_lb_target_group" "main" {
  name                 = "tg-oidc-${var.environment}"
  port                 = var.application_port
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = var.health_check_path
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, { Name = "tg-oidc-${var.environment}" })
}

resource "aws_lb_target_group_attachment" "app" {
  count = 2

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.app[count.index].id
  port             = var.application_port
}

###############################################################################
# ALB access-log S3 bucket
###############################################################################

resource "aws_s3_bucket" "alb_logs" {
  bucket = local.log_bucket_name

  tags = merge(local.common_tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "ELBAccessLogDelivery"
        Effect    = "Allow"
        Principal = { Service = "logdelivery.elasticloadbalancing.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.alb_logs.arn}/${local.log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

###############################################################################
# TLS certificate and Application Load Balancer
###############################################################################

resource "aws_acm_certificate" "alb" {
  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = merge(local.common_tags, { Name = "alb-cert-${var.environment}" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "main" {
  name               = "alb-oidc-${var.environment}"
  load_balancer_type = "application"
  internal           = false
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "alb-oidc-${var.environment}" })

  depends_on = [aws_s3_bucket_policy.alb_logs]
}

###############################################################################
# OIDC client secret: generated at apply time (no plaintext anywhere in code)
# and durably persisted in Secrets Manager
###############################################################################

resource "random_password" "oidc_client_secret" {
  length           = 32
  special          = true
  override_special = "-_.~"
}

resource "aws_secretsmanager_secret" "oidc_client_secret" {
  name        = "alb-oidc/client-secret-${var.environment}"
  description = "OIDC client secret used by the ALB authenticate-oidc listener."

  tags = merge(local.common_tags, { Name = "alb-oidc-client-secret-${var.environment}" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "oidc_client_secret" {
  secret_id     = aws_secretsmanager_secret.oidc_client_secret.id
  secret_string = random_password.oidc_client_secret.result
}

data "aws_secretsmanager_secret_version" "oidc_client_secret" {
  secret_id = aws_secretsmanager_secret.oidc_client_secret.id

  depends_on = [aws_secretsmanager_secret_version.oidc_client_secret]
}

###############################################################################
# Listeners
###############################################################################

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type = "authenticate-oidc"

    authenticate_oidc {
      authorization_endpoint     = var.oidc_authorization_endpoint
      token_endpoint             = var.oidc_token_endpoint
      user_info_endpoint         = var.oidc_user_info_endpoint
      issuer                     = var.oidc_issuer
      client_id                  = var.oidc_client_id
      client_secret              = data.aws_secretsmanager_secret_version.oidc_client_secret.secret_string
      session_cookie_name        = "AWSELBAuthSessionCookie-1"
      scope                      = "openid"
      on_unauthenticated_request = "authenticate"
    }
  }

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resources for consistent tagging."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-zA-Z0-9][a-zA-Z0-9-]{0,19}$", var.environment))
    error_message = "Environment must be 1-20 alphanumeric characters or hyphens."
  }
}

# --- Static/well-known data lookups only (no pre-existing infrastructure) ---

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

locals {
  vpc_cidr = "10.0.0.0/16"

  az_count           = 2
  availability_zones = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  subnet_az_map = {
    for idx, az in local.availability_zones :
    az => cidrsubnet(local.vpc_cidr, 8, idx + 1)
  }

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# --- Inspection VPC networking ---

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-public-rt"
  })
}

resource "aws_subnet" "appliance" {
  for_each = local.subnet_az_map

  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = each.value
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-public-${each.key}"
  })
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.appliance

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# --- Security groups ---

resource "aws_security_group" "appliance_sg" {
  name        = "gwlb-appliance-sg"
  description = "Permit inbound GENEVE (UDP/6081) traffic from within the inspection VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "GENEVE-encapsulated traffic from the inspection VPC"
    from_port   = 6081
    to_port     = 6081
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-sg"
  })
}

resource "aws_security_group" "ssm_endpoints" {
  name        = "gwlb-ssm-endpoints-sg"
  description = "Permit HTTPS from within the inspection VPC to the SSM interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from the inspection VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-ssm-endpoints-sg"
  })
}

# Interface endpoints so the keyless (no public IP, no SSH) appliances can
# reach AWS Systems Manager for management access.
resource "aws_vpc_endpoint" "ssm" {
  for_each = toset(["ssm", "ssmmessages", "ec2messages"])

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [for subnet in aws_subnet.appliance : subnet.id]
  security_group_ids  = [aws_security_group.ssm_endpoints.id]
  private_dns_enabled = true

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-${each.key}-endpoint"
  })
}

# --- Appliance IAM (keyless management via SSM) ---

resource "aws_iam_role" "appliance_ssm" {
  name = "gwlb-appliance-ssm-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-ssm-role"
  })
}

resource "aws_iam_role_policy_attachment" "appliance_ssm_core" {
  role       = aws_iam_role.appliance_ssm.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "appliance" {
  name = "gwlb-appliance-instance-profile"
  role = aws_iam_role.appliance_ssm.name

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-instance-profile"
  })
}

# --- Appliance instances ---

resource "aws_instance" "appliance" {
  for_each = aws_subnet.appliance

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = each.value.id
  vpc_security_group_ids      = [aws_security_group.appliance_sg.id]
  associate_public_ip_address = false
  iam_instance_profile        = aws_iam_instance_profile.appliance.name

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-appliance-${each.key}"
  })
}

# --- Gateway Load Balancer ---

resource "aws_lb_target_group" "gwlb_targets" {
  name        = "gwlb-targets"
  target_type = "instance"
  protocol    = "GENEVE"
  port        = 6081
  vpc_id      = aws_vpc.main.id

  health_check {
    protocol            = "TCP"
    port                = "traffic-port"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-targets"
  })
}

resource "aws_lb" "gwlb" {
  name               = "gwlb-inspection"
  load_balancer_type = "gateway"

  subnets = [for subnet in aws_subnet.appliance : subnet.id]

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection"
  })
}

resource "aws_lb_listener" "gwlb" {
  load_balancer_arn = aws_lb.gwlb.arn
  protocol          = "GENEVE"
  port              = 6081

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.gwlb_targets.arn
  }

  tags = merge(local.common_tags, {
    Name = "gwlb-inspection-listener"
  })
}

resource "aws_lb_target_group_attachment" "appliance" {
  for_each = aws_instance.appliance

  target_group_arn = aws_lb_target_group.gwlb_targets.arn
  target_id        = each.value.id
  port             = 6081
}

resource "aws_vpc_endpoint_service" "gwlb" {
  acceptance_required        = false
  gateway_load_balancer_arns = [aws_lb.gwlb.arn]
  allowed_principals         = [local.account_root_arn]

  tags = merge(local.common_tags, {
    Name = "gwlb-endpoint-service"
  })
}

# --- Outputs for downstream consumer VPCs ---

output "gateway_load_balancer_arn" {
  description = "ARN of the Gateway Load Balancer."
  value       = aws_lb.gwlb.arn
}

output "gateway_load_balancer_arn_suffix" {
  description = "ARN suffix of the Gateway Load Balancer (useful for CloudWatch metrics and alarms)."
  value       = aws_lb.gwlb.arn_suffix
}

output "gateway_load_balancer_endpoint_service_name" {
  description = "Service name that downstream consumer VPCs use to create Gateway Load Balancer endpoints."
  value       = aws_vpc_endpoint_service.gwlb.service_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "alb_demo"
  environment = "dev"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_igw"
  })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_subnet_${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_public_route_table"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Load balancer security group
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}_alb_sg"
  description = "Ingress 80/443 from the internet, egress limited to target application port 80 inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "HTTP to application targets inside the VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb_sg"
  })
}

# ---------------------------------------------------------------------------
# Application load balancer
# ---------------------------------------------------------------------------

resource "aws_lb" "main" {
  name               = replace("${local.name_prefix}-alb", "_", "-")
  internal           = false
  load_balancer_type = "application"
  ip_address_type    = "ipv4"
  security_groups    = [aws_security_group.alb.id]
  subnets            = aws_subnet.public[*].id

  enable_deletion_protection = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_alb"
  })
}

resource "aws_lb_target_group" "main" {
  name        = replace("${local.name_prefix}-tg", "_", "-")
  target_type = "instance"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    port                = "traffic-port"
    healthy_threshold   = 2
    unhealthy_threshold = 3
    interval            = 30
    timeout             = 5
    matcher             = "200"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}_http_listener"
  })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the application load balancer."
  value       = aws_lb.main.dns_name
}

output "alb_zone_id" {
  description = "Route 53 hosted zone ID of the application load balancer."
  value       = aws_lb.main.zone_id
}

output "target_group_arn" {
  description = "ARN of the ALB target group."
  value       = aws_lb_target_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used to derive Name tags for all resources"
  type        = string
  default     = "alb-ip-tg"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = var.project_name
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name}-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name}-igw"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name}-public-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name}-public-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name}-public-rt"
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "${local.name}-alb-sg"
  description = "Allows inbound HTTP and HTTPS traffic to the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "${local.name}-alb-sg"
  }
}

resource "aws_lb" "main" {
  name                       = "${local.name}-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true
  enable_deletion_protection = true

  tags = {
    Name = "${local.name}-alb"
  }
}

resource "aws_lb_target_group" "main" {
  name                 = "${local.name}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = {
    Name = "${local.name}-tg"
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Project/environment name used for resource naming and tagging."
  type        = string
  default     = "demo"

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{0,20}$", var.environment))
    error_message = "The environment name must be 1-21 lowercase alphanumeric characters or hyphens, starting with a letter."
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  account_id           = data.aws_caller_identity.current.account_id
  log_bucket_name      = "${var.environment}-alb-access-logs-${local.account_id}"
  log_prefix           = "${var.environment}/alb-access-logs"
  lambda_function_name = "${var.environment}-alb-lambda"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking foundation
# ---------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${var.environment}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-igw" })
}

resource "aws_subnet" "public" {
  for_each                = { for idx, az in data.aws_availability_zones.available.names : az => idx }
  vpc_id                  = aws_vpc.main.id
  availability_zone       = each.key
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, each.value)
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, { Name = "${var.environment}-public-${each.key}" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${var.environment}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each       = aws_subnet.public
  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# ALB security group (HTTP only from the internet)
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${var.environment}-alb-sg"
  description = "Public ALB security group: HTTP from anywhere, all egress allowed"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-alb-sg" })
}

# ---------------------------------------------------------------------------
# Dedicated S3 bucket for ALB access logs
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "alb_logs" {
  bucket = local.log_bucket_name

  tags = merge(local.common_tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket                  = aws_s3_bucket.alb_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "alb_logs" {
  statement {
    sid    = "AllowELBLogDeliveryPutObject"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "arn:aws:s3:::${aws_s3_bucket.alb_logs.id}/${local.log_prefix}/AWSLogs/${local.account_id}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id
  policy = data.aws_iam_policy_document.alb_logs.json

  depends_on = [
    aws_s3_bucket_public_access_block.alb_logs,
    aws_s3_bucket_ownership_controls.alb_logs,
  ]
}

# ---------------------------------------------------------------------------
# Application Load Balancer
# ---------------------------------------------------------------------------
resource "aws_lb" "main" {
  name               = "${var.environment}-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [for subnet in aws_subnet.public : subnet.id]

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  tags = merge(local.common_tags, { Name = "${var.environment}-alb" })

  depends_on = [aws_s3_bucket_policy.alb_logs]
}

# ---------------------------------------------------------------------------
# Lambda target group
# ---------------------------------------------------------------------------
resource "aws_lb_target_group" "lambda" {
  name                               = "${var.environment}-lambda-tg"
  target_type                        = "lambda"
  lambda_multi_value_headers_enabled = true

  tags = merge(local.common_tags, { Name = "${var.environment}-lambda-tg" })
}

# ---------------------------------------------------------------------------
# Lambda execution role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "lambda_exec" {
  name = "${var.environment}-lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })

  tags = merge(local.common_tags, { Name = "${var.environment}-lambda-exec-role" })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# ---------------------------------------------------------------------------
# CloudWatch log group with explicit retention
# ---------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/${local.lambda_function_name}"
  retention_in_days = 14

  tags = merge(local.common_tags, { Name = "${local.lambda_function_name}-logs" })
}

# ---------------------------------------------------------------------------
# Lambda function (package built in-file from inline handler source)
# ---------------------------------------------------------------------------
data "archive_file" "lambda" {
  type        = "zip"
  output_path = "${path.module}/lambda_payload.zip"

  source {
    content = <<-EOT
      import json


      def lambda_handler(event, context):
          """Handle an ALB request and return a valid ALB Lambda response."""
          return {
              "statusCode": 200,
              "statusDescription": "200 OK",
              "isBase64Encoded": False,
              "headers": {
                  "Content-Type": "text/html; charset=utf-8"
              },
              "body": "<html><body><h1>Hello from Lambda behind an ALB</h1><p>Environment: ${var.environment}</p></body></html>"
          }
      EOT
    filename = "lambda_function.py"
  }
}

resource "aws_lambda_function" "main" {
  function_name    = local.lambda_function_name
  description      = "Lambda target registered in the ${var.environment} application load balancer target group"
  role             = aws_iam_role.lambda_exec.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.12"
  filename         = data.archive_file.lambda.output_path
  source_code_hash = data.archive_file.lambda.output_base64sha256

  tags = merge(local.common_tags, { Name = local.lambda_function_name })

  depends_on = [
    aws_cloudwatch_log_group.lambda,
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]
}

# ---------------------------------------------------------------------------
# ALB invoke permission and target registration
# ---------------------------------------------------------------------------
resource "aws_lambda_permission" "from_alb" {
  statement_id  = "AllowExecutionFromALB"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.main.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = aws_lb_target_group.lambda.arn
}

resource "aws_lb_target_group_attachment" "lambda" {
  target_group_arn = aws_lb_target_group.lambda.arn
  target_id        = aws_lambda_function.main.arn

  depends_on = [aws_lambda_permission.from_alb]
}

# ---------------------------------------------------------------------------
# HTTP listener forwarding to the Lambda target group
# ---------------------------------------------------------------------------
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda.arn
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "lambda_target_group_arn" {
  description = "ARN of the Lambda target group."
  value       = aws_lb_target_group.lambda.arn
}

output "lambda_function_name" {
  description = "Name of the Lambda function registered as the ALB target."
  value       = aws_lambda_function.main.function_name
}

output "lambda_function_arn" {
  description = "ARN of the Lambda function registered as the ALB target."
  value       = aws_lambda_function.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_ami" "amazon_linux_2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-2023.*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

locals {
  name_prefix = "alb-demo"
  environment = "dev"
  log_prefix  = "alb-access-logs"

  common_tags = {
    Environment = local.environment
  }
}

# ---------------------------------------------------------------------------
# Network foundation
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet-${count.index + 1}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "alb" {
  name        = "${local.name_prefix}-alb-sg"
  description = "Ingress for the public Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-sg"
  })
}

resource "aws_security_group" "targets" {
  name        = "${local.name_prefix}-targets-sg"
  description = "Ingress for ALB backend instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTP from the ALB security group only"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-targets-sg"
  })
}

# ---------------------------------------------------------------------------
# Target group, load balancer, listener
# ---------------------------------------------------------------------------

resource "aws_lb_target_group" "app" {
  name        = "${local.name_prefix}-tg"
  vpc_id      = aws_vpc.main.id
  port        = 80
  protocol    = "HTTP"
  target_type = "instance"

  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = "/"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-tg"
  })
}

resource "aws_lb" "main" {
  name               = "${local.name_prefix}-alb"
  load_balancer_type = "application"
  internal           = false

  security_groups = [aws_security_group.alb.id]
  subnets         = aws_subnet.public[*].id

  drop_invalid_header_fields = true

  access_logs {
    bucket  = aws_s3_bucket.alb_logs.id
    prefix  = local.log_prefix
    enabled = true
  }

  depends_on = [aws_s3_bucket_policy.alb_logs]

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-http-listener"
  })
}

# ---------------------------------------------------------------------------
# Backend instances
# ---------------------------------------------------------------------------

resource "aws_instance" "app" {
  count = 2

  ami                         = data.aws_ami.amazon_linux_2023.id
  instance_type               = "t3.micro"
  subnet_id                   = aws_subnet.public[count.index].id
  associate_public_ip_address = true
  vpc_security_group_ids      = [aws_security_group.targets.id]

  user_data = <<-EOF
    #!/bin/bash
    dnf install -y httpd
    echo "<h1>Hello from $(hostname -f)</h1>" > /var/www/html/index.html
    systemctl enable --now httpd
  EOF

  user_data_replace_on_change = true

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
    instance_metadata_tags      = "disabled"
  }

  root_block_device {
    volume_size = 8
    volume_type = "gp3"
    encrypted   = true
  }

  depends_on = [aws_route_table_association.public]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-app-${count.index + 1}"
  })
}

resource "aws_lb_target_group_attachment" "app" {
  count = 2

  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.app[count.index].id
  port             = 80
}

# ---------------------------------------------------------------------------
# ALB access log bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "alb_logs" {
  bucket = "${local.name_prefix}-alb-logs-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-alb-logs"
  })
}

resource "aws_s3_bucket_public_access_block" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "alb_logs" {
  statement {
    sid    = "AllowELBLogDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logdelivery.elasticloadbalancing.amazonaws.com"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.alb_logs.id}/${local.log_prefix}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "alb_logs" {
  bucket = aws_s3_bucket.alb_logs.id
  policy = data.aws_iam_policy_document.alb_logs.json

  depends_on = [aws_s3_bucket_public_access_block.alb_logs]
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "alb_dns_name" {
  description = "Public DNS name of the Application Load Balancer"
  value       = aws_lb.main.dns_name
}

output "alb_target_group_arn" {
  description = "ARN of the ALB target group"
  value       = aws_lb_target_group.app.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "dev"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "main-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
