  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "main-public-route-table"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "alb" {
  name        = "main-alb-sg"
  description = "Security group for the internet-facing application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "main-alb-sg"
  })
}

resource "aws_lb" "main" {
  name               = "main-app-alb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]

  enable_deletion_protection = false

  tags = merge(local.common_tags, {
    Name = "main-app-alb"
  })
}

resource "aws_lb_target_group" "main" {
  name     = "main-app-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  target_type          = "instance"
  deregistration_delay = 300

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, {
    Name = "main-app-tg"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, {
    Name = "main-http-listener"
  })
}

output "alb_dns_name" {
  description = "Public DNS name of the application load balancer"
  value       = aws_lb.main.dns_name
}

output "target_group_arn" {
  description = "ARN of the target group attached to the load balancer"
  value       = aws_lb_target_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# -----------------------------------------------------------------------------
# Variables (non-secret, user-tunable, all with defaults)
# -----------------------------------------------------------------------------

variable "environment" {
  description = "Environment name used only for resource tagging."
  type        = string
  default     = "dev"
}

variable "db_name" {
  description = "Initial database name created on the PostgreSQL instance."
  type        = string
  default     = "appdb"
}

variable "master_username" {
  description = "Master username for the RDS instance (non-secret)."
  type        = string
  default     = "dbadmin"
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = "greenfield-rds"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# -----------------------------------------------------------------------------
# Networking: VPC, isolated database subnets, local-only route tables
# -----------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-${count.index}"
      Tier = "database"
    }
  )
}

# Local-only route table: no internet gateway route, DB tier is fully isolated.
resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt-${count.index}"
      Tier = "database"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Security group: PostgreSQL access restricted to the VPC CIDR only
# -----------------------------------------------------------------------------

resource "aws_security_group" "rds" {
  name_prefix = "${local.name_prefix}-rds-"
  description = "Allow PostgreSQL (5432) access only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.common_tags
}

# -----------------------------------------------------------------------------
# Encryption: customer-managed KMS key for RDS storage and the credential secret
# -----------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "KMS key for RDS storage encryption and master credential secret"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# -----------------------------------------------------------------------------
# Master credentials: generated password, stored encrypted in Secrets Manager
# -----------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "main" {
  name        = "${local.name_prefix}/postgres/master-credentials"
  description = "Master credentials for ${local.name_prefix} PostgreSQL instance"
  kms_key_id  = aws_kms_key.rds.arn

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "main" {
  secret_id = aws_secretsmanager_secret.main.id
  secret_string = jsonencode({
    engine   = aws_db_instance.main.engine
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = aws_db_instance.main.db_name
    username = aws_db_instance.main.username
    password = random_password.db_master.result
  })
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL instance
# -----------------------------------------------------------------------------

resource "aws_db_instance" "main" {
  identifier = "${local.name_prefix}-postgres"

  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"

  db_name = var.db_name
  username = var.master_username
  password = random_password.db_master.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  storage_encrypted          = true
  kms_key_id                 = aws_kms_key.rds.arn
  publicly_accessible        = false
  multi_az                   = false
  deletion_protection        = true
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  backup_target           = "region"
  maintenance_window      = "sun:04:30-sun:05:30"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-postgres-final-snapshot"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs: non-sensitive connection metadata only
# -----------------------------------------------------------------------------

output "db_instance_address" {
  description = "Connection address (hostname) of the RDS PostgreSQL instance."
  value       = aws_db_instance.main.address
}

output "db_instance_endpoint" {
  description = "Full connection endpoint (host:port) of the RDS PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project         = "mysql-db"
  environment     = "production"
  master_username = "admin"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "terraform"
    Project     = local.project
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-subnet-${count.index + 1}"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-route-table"
  })
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "mysql" {
  name        = "${local.project}-sg"
  description = "Allow inbound MySQL from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL to within the VPC"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.project}-subnet-group"
  description = "Subnet group for the MySQL RDS instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.project}-subnet-group"
  })
}

resource "random_password" "master_password" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:"
}

resource "aws_db_instance" "mysql" {
  identifier     = "${local.project}-instance"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t4g.micro"

  db_name  = "appdb"
  username = local.master_username
  password = random_password.master_password.result

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  port                   = 3306
  publicly_accessible    = false
  multi_az               = false

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.project}-final-snapshot"

  tags = merge(local.common_tags, {
    Name = "${local.project}-instance"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "master_credentials" {
  name = "${local.project}-master-credentials"

  tags = merge(local.common_tags, {
    Name = "${local.project}-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "master_credentials" {
  secret_id = aws_secretsmanager_secret.master_credentials.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.master_password.result
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
  })
}

output "db_instance_address" {
  description = "DNS address of the RDS MySQL instance"
  value       = aws_db_instance.mysql.address
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret storing the RDS master credentials"
  value       = aws_secretsmanager_secret.master_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "prod"
}

variable "common_tags" {
  description = "Common tags applied consistently to all resources."
  type        = map(string)
  default = {
    Project   = "greenfield-data-platform"
    Owner     = "platform-team"
    ManagedBy = "terraform"
  }
}

locals {
  name          = "${var.environment}-postgres"
  db_identifier = "${local.name}-db"
  common_tags   = merge(var.common_tags, { Environment = var.environment })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name}-private-${count.index + 1}"
    Tier = "database"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.db_identifier}-subnets"
  description = "Private subnets spanning multiple AZs for the ${local.name} database tier"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-subnets"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "postgres" {
  name        = "${local.db_identifier}-sg"
  description = "Restrict ingress to PostgreSQL (TCP 5432) from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL access from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound restricted to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-sg"
  })
}

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for ${local.name} storage encryption and Performance Insights"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name}-rds-key"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

resource "aws_db_parameter_group" "main" {
  name        = "${local.db_identifier}-params"
  family      = "postgres16"
  description = "Custom PostgreSQL 16 parameters for ${local.db_identifier}"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name  = "shared_preload_libraries"
    value = "pg_stat_statements"
  }

  parameter {
    name         = "log_min_duration_statement"
    value        = "1000"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  tags = merge(local.common_tags, {
    Name = "${local.db_identifier}-params"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "main" {
  identifier     = local.db_identifier
  engine         = "postgresql"
  engine_version = "16.4"
  instance_class = "db.t4g.large"

  allocated_storage     = 50
  max_allocated_storage = 500
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name                     = "appdb"
  username                    = "dbadmin"
  manage_master_user_password = true

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.postgres.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  multi_az               = true
  publicly_accessible    = false
  port                   = 5432

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.rds.arn

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-${random_id.final_snapshot_suffix.hex}"

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
}

output "db_instance_address" {
  description = "DNS address of the PostgreSQL instance."
  value       = aws_db_instance.main.address
}

output "db_instance_port" {
  description = "Port the PostgreSQL instance listens on."
  value       = aws_db_instance.main.port
}

output "db_master_user_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials (secret value is never exposed)."
  value       = aws_db_instance.main.master_user_secret[0].secret_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# Variables (all defaulted so `terraform apply` runs non-interactively)
# ---------------------------------------------------------------------------

variable "project_name" {
  description = "Project name used for resource naming and tags."
  type        = string
  default     = "memory-optimized-postgres"
}

variable "environment" {
  description = "Deployment environment used for tagging and naming."
  type        = string
  default     = "production"
}

variable "vpc_cidr" {
  description = "CIDR block for the dedicated VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block (e.g. 10.0.0.0/16)."
  }
}

# ---------------------------------------------------------------------------
# Data sources (pure static provider metadata only)
# ---------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "dbadmin"
  database_name   = "appdb"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Project     = var.project_name
  }
}

# ---------------------------------------------------------------------------
# Networking: dedicated VPC with private subnets across two AZs
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 1)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Private subnets across multiple Availability Zones for the PostgreSQL instance."
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# ---------------------------------------------------------------------------
# Security: database security group restricted to port 5432 from the VPC CIDR
# ---------------------------------------------------------------------------

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Allow PostgreSQL (TCP 5432) only from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# ---------------------------------------------------------------------------
# Credentials: generated master password stored in Secrets Manager
# ---------------------------------------------------------------------------

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

resource "aws_secretsmanager_secret" "db" {
  name                    = "${local.name_prefix}/db-master-credentials"
  description             = "Master credentials for the memory-optimized PostgreSQL instance."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db" {
  secret_id = aws_secretsmanager_secret.db.id
  secret_string = jsonencode({
    username = local.master_username
    password = random_password.db_master_password.result
    engine   = aws_db_instance.postgres.engine
    host     = aws_db_instance.postgres.address
    port     = aws_db_instance.postgres.port
    dbname   = aws_db_instance.postgres.db_name
  })
}

# ---------------------------------------------------------------------------
# Tuning: memory-optimized PostgreSQL parameter group (16 GiB db.r7g.large)
# ---------------------------------------------------------------------------

resource "aws_db_parameter_group" "main" {
  name        = "${local.name_prefix}-pg16-tuned"
  family      = "postgres16"
  description = "Parameters tuned for a memory-optimized PostgreSQL workload on db.r7g.large (16 GiB RAM)."

  # 4 GiB = 25% of 16 GiB RAM, expressed in 8 kB pages (static parameter, requires reboot)
  parameter {
    name         = "shared_buffers"
    value        = "524288"
    apply_method = "pending-reboot"
  }

  # 12 GiB = 75% of 16 GiB RAM, expressed in 8 kB pages
  parameter {
    name         = "effective_cache_size"
    value        = "1572864"
    apply_method = "immediate"
  }

  parameter {
    name         = "max_connections"
    value        = "300"
    apply_method = "immediate"
  }

  # 16 MiB, expressed in kB
  parameter {
    name         = "work_mem"
    value        = "16384"
    apply_method = "immediate"
  }

  # 1 GiB, expressed in kB
  parameter {
    name         = "maintenance_work_mem"
    value        = "1048576"
    apply_method = "immediate"
  }

  # SSD-optimized planner cost for random I/O
  parameter {
    name         = "random_page_cost"
    value        = "1.1"
    apply_method = "immediate"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-pg16-tuned"
  })
}

# ---------------------------------------------------------------------------
# Memory-optimized PostgreSQL instance (db.r7g.large, Multi-AZ, encrypted)
# ---------------------------------------------------------------------------

resource "random_string" "final_snapshot_suffix" {
  length  = 8
  special = false
  upper   = false
}

resource "aws_db_instance" "postgres" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "16"
  instance_class = "db.r7g.large"

  allocated_storage     = 100
  max_allocated_storage = 1000
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name  = local.database_name
  username = local.master_username
  password = random_password.db_master_password.result
  port     = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]
  parameter_group_name   = aws_db_parameter_group.main.name

  multi_az                   = true
  publicly_accessible        = false
  deletion_protection        = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  backup_retention_period = 14
  backup_window           = "02:00-03:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_string.final_snapshot_suffix.result}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the memory-optimized PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

output "db_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the PostgreSQL master credentials."
  value       = aws_secretsmanager_secret.db.arn
}

output "db_subnet_group_arn" {
  description = "ARN of the DB subnet group spanning the private subnets."
  value       = aws_db_subnet_group.main.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Prefix used for resource names and the Name tag."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment name applied to all resources via the Environment tag."
  type        = string
  default     = "production"
}

locals {
  name_prefix     = var.project_name
  db_identifier   = "mysql-db-instance"
  db_name         = "appdb"
  master_username = "dbadmin"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 10)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "mysql" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Multi-AZ private subnet group for the ${local.db_identifier} MySQL instance."

  subnet_ids = [
    aws_subnet.private_a.id,
    aws_subnet.private_b.id,
  ]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "mysql" {
  name        = "${local.name_prefix}-mysql-sg"
  description = "Allow MySQL (3306) only from within the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC only."
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-sg"
  })
}

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${var.project_name}/${var.environment}/db-master-password"
  description             = "Master credentials for the ${local.db_identifier} MySQL instance."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-secret"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    engine   = "mysql"
    host     = aws_db_instance.mysql.address
    port     = aws_db_instance.mysql.port
    dbname   = aws_db_instance.mysql.db_name
    username = local.master_username
    password = random_password.db_master_password.result
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 25
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name         = local.db_name
  username        = local.master_username
  password        = random_password.db_master_password.result
  port            = 3306

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]
  publicly_accessible    = false

  apply_immediately          = true
  auto_minor_version_upgrade = true
  deletion_protection        = true
  copy_tags_to_snapshot      = true

  backup_retention_period = 7
  backup_window           = "01:00-02:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the MySQL master credentials. Retrieve the password by reading this secret; the plaintext password is never exposed in configuration or outputs."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used strictly for resource tagging."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = var.environment
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "mysql-vpc" })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[0]
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "mysql-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[1]
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "mysql-private-b" })
}

resource "aws_db_subnet_group" "mysql" {
  name        = "mysql-db-subnet-group"
  description = "Subnet group for the mysql-db RDS instance (spans two AZs)"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, { Name = "mysql-db-subnet-group" })
}

resource "aws_security_group" "mysql" {
  name        = "mysql-db-sg"
  description = "Restrict MySQL access to TCP/3306 from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "mysql-db-sg" })
}

resource "random_password" "db_master" {
  length           = 20
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "mysql-db/master-credentials"
  description             = "Master credentials for the mysql-db RDS instance"
  recovery_window_in_days = 0

  tags = merge(local.common_tags, { Name = "mysql-db-master-secret" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = "admin"
    password = random_password.db_master.result
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = "mysql-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = "appdb"
  username = "admin"
  password = random_password.db_master.result
  port     = 3306

  db_subnet_group_name   = aws_db_subnet_group.mysql.name
  vpc_security_group_ids = [aws_security_group.mysql.id]

  publicly_accessible        = false
  multi_az                   = false
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:05:00-sun:06:00"

  skip_final_snapshot = true
  deletion_protection = false

  tags = merge(local.common_tags, { Name = "mysql-db" })
}

output "db_instance_address" {
  description = "Connection address (hostname) of the mysql-db RDS instance."
  value       = aws_db_instance.mysql.address
}

output "db_instance_endpoint" {
  description = "Full connection endpoint (host:port) of the mysql-db RDS instance."
  value       = aws_db_instance.mysql.endpoint
}

output "db_instance_port" {
  description = "Port the mysql-db RDS instance listens on."
  value       = aws_db_instance.mysql.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the mysql-db master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Static provider metadata: AZs available in the current region
data "aws_availability_zones" "available" {
  state = "available"
}

variable "project_name" {
  description = "Project name used for resource naming and the Project tag."
  type        = string
  default     = "myapp"
}

variable "environment" {
  description = "Environment name used for resource naming and the Environment tag."
  type        = string
  default     = "production"
}

locals {
  name_prefix     = "${var.project_name}-${var.environment}"
  master_username = "dbadmin"
  db_name         = "appdb"
  db_port         = 3306

  common_tags = {
    Environment = var.environment
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

# --- Network foundation (greenfield: everything is created here) ---

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Subnet group spanning two AZs for ${local.name_prefix} RDS instances"
  subnet_ids  = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

# --- Network access control: MySQL reachable only from inside the VPC ---

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL traffic only from within the ${local.name_prefix} VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

# --- Master credentials: generated securely, stored in Secrets Manager ---

resource "random_password" "db_master_password" {
  length           = 24
  special          = true
  override_special = "!#%*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name        = "${local.name_prefix}-db-master-credentials"
  description = "Master credentials for the ${local.name_prefix} primary MySQL instance"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_credentials" {
  secret_id = aws_secretsmanager_secret.db_credentials.id
  secret_string = jsonencode({
    username             = local.master_username
    password             = random_password.db_master_password.result
    engine               = "mysql"
    host                 = aws_db_instance.primary.address
    port                 = local.db_port
    dbname               = local.db_name
    dbInstanceIdentifier = aws_db_instance.primary.identifier
  })
}

# --- Shared parameter group (family matches the pinned engine version) ---

resource "aws_db_parameter_group" "mysql" {
  name        = "${local.name_prefix}-mysql-params"
  family      = "mysql8.0"
  description = "Shared parameter group for ${local.name_prefix} primary and replica"

  parameter {
    name  = "character_set_server"
    value = "utf8mb4"
  }

  parameter {
    name  = "character_set_client"
    value = "utf8mb4"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mysql-params"
  })
}

# --- Primary MySQL instance ---

resource "aws_db_instance" "primary" {
  identifier     = "${local.name_prefix}-primary"
  engine         = "mysql"
  engine_version = "8.0.36"
  instance_class = "db.t3.medium"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"

  db_name  = local.db_name
  username = local.master_username
  password = random_password.db_master_password.result

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  port                = local.db_port
  publicly_accessible = false
  multi_az            = false

  storage_encrypted       = true
  backup_retention_period = 7
  copy_tags_to_snapshot   = true
  deletion_protection     = true

  auto_minor_version_upgrade = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-primary-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary"
  })
}

# --- Read replica (native replication, same network, sizing, and encryption) ---

resource "aws_db_instance" "replica" {
  identifier          = "${local.name_prefix}-replica"
  replicate_source_db = aws_db_instance.primary.arn
  instance_class      = "db.t3.medium"

  db_subnet_group_name   = aws_db_subnet_group.main.name
  parameter_group_name   = aws_db_parameter_group.mysql.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  storage_encrypted   = true

  copy_tags_to_snapshot      = true
  deletion_protection        = true
  auto_minor_version_upgrade = true

  skip_final_snapshot = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replica"
  })
}

# --- Outputs ---

output "primary_db_endpoint" {
  description = "Connection endpoint (hostname) of the primary MySQL instance."
  value       = aws_db_instance.primary.address
}

output "replica_db_endpoint" {
  description = "Connection endpoint (hostname) of the MySQL read replica."
  value       = aws_db_instance.replica.address
}

output "db_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master credentials (the secret value itself is never exposed)."
  value       = aws_secretsmanager_secret.db_credentials.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "greenfield-rds"
}

variable "environment" {
  description = "Environment name applied to all resources via tags."
  type        = string
  default     = "dev"
}

locals {
  name_prefix    = lower(replace(var.project, "/[^a-zA-Z0-9-]/", ""))
  vpc_cidr       = "10.0.0.0/16"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.medium"
  db_port        = 5432

  tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[count.index]
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 11)
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_db_subnet_group" "rds" {
  name        = "${local.name_prefix}-rds-subnet-group"
  description = "Private subnets across multiple AZs for RDS instances"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-subnet-group"
  })
}

resource "aws_security_group" "db_main" {
  name        = "${local.name_prefix}-db-sg"
  description = "Database security group: ingress/egress limited to the engine port from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL to within the VPC only (e.g. replication)"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_kms_key" "db_main" {
  description             = "Customer managed KMS key for RDS storage encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "db_main" {
  name          = "alias/${local.name_prefix}-db-main"
  target_key_id = aws_kms_key.db_main.key_id
}

resource "random_password" "db_main" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}/rds/master"
  description             = "Master credentials for the RDS PostgreSQL instances"
  recovery_window_in_days = 7

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-master"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = "dbadmin"
    password = random_password.db_main.result
  })
}

resource "aws_db_parameter_group" "main" {
  name        = "${local.name_prefix}-pg16-params"
  family      = "postgres16"
  description = "Managed database parameters for PostgreSQL 16 RDS instances"

  parameter {
    name  = "log_min_duration_statement"
    value = "1000"
  }

  parameter {
    name  = "log_connections"
    value = "1"
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-pg16-params"
  })
}

resource "aws_db_instance" "source" {
  identifier     = "${local.name_prefix}-source-db"
  engine         = local.engine
  engine_version = local.engine_version
  instance_class = local.instance_class

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.db_main.arn

  db_name  = "appdb"
  username = "dbadmin"
  password = random_password.db_main.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.db_main.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  publicly_accessible    = false

  multi_az                   = false
  auto_minor_version_upgrade = false
  backup_retention_period    = 7
  backup_window              = "03:00-04:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-source-db-final"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-source-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_snapshot" "source" {
  db_instance_identifier = aws_db_instance.source.identifier
  db_snapshot_identifier = "${local.name_prefix}-source-db-snapshot"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-source-db-snapshot"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_instance" "restored" {
  identifier     = "${local.name_prefix}-restored-db"
  engine         = local.engine
  engine_version = local.engine_version
  instance_class = local.instance_class

  snapshot_identifier = aws_db_snapshot.source.db_snapshot_identifier

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.db_main.arn
  port                  = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.db_main.id]
  parameter_group_name   = aws_db_parameter_group.main.name
  publicly_accessible    = false

  multi_az                   = false
  auto_minor_version_upgrade = false
  backup_retention_period    = 7
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-restored-db-final"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-restored-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "restored_db_identifier" {
  description = "Identifier of the RDS instance restored from the snapshot."
  value       = aws_db_instance.restored.identifier
}

output "restored_db_endpoint" {
  description = "Connection endpoint address of the restored RDS instance."
  value       = aws_db_instance.restored.address
}

output "restored_db_port" {
  description = "Port that the restored RDS instance listens on."
  value       = aws_db_instance.restored.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the RDS master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

variable "tags" {
  description = "Consistent tags applied across every resource in this configuration."
  type        = map(string)

  default = {
    Project     = "rds-postgres-baseline"
    Environment = "dev"
    ManagedBy   = "terraform"
  }
}

locals {
  common_tags   = var.tags
  db_identifier = "rds-postgres-baseline"
  db_name       = "appdb"
  db_username   = "appadmin"
  db_port       = 5432
}

# Static provider metadata lookup (AZ availability), no account-state dependency.
data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-vpc" })
}

resource "aws_subnet" "rds_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-subnet-a" })
}

resource "aws_subnet" "rds_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-subnet-b" })
}

resource "aws_db_subnet_group" "rds" {
  name        = "${local.db_identifier}-subnet-group"
  description = "Subnet group for the ${local.db_identifier} RDS PostgreSQL instance."
  subnet_ids  = [aws_subnet.rds_a.id, aws_subnet.rds_b.id]

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-db-subnet-group" })
}

resource "aws_security_group" "rds" {
  name        = "${local.db_identifier}-sg"
  description = "Allow PostgreSQL (5432) only from inside the VPC."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound responses and maintenance traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-sg" })
}

###############################################################################
# Master credentials (generated at apply time, stored in Secrets Manager)
###############################################################################

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.db_identifier}/master-credentials"
  description = "Master credentials for the ${local.db_identifier} RDS PostgreSQL instance."

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-master-secret" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Database
###############################################################################

resource "aws_db_parameter_group" "rds" {
  name   = "${local.db_identifier}-params"
  family = "postgres16"

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  tags = merge(local.common_tags, { Name = "${local.db_identifier}-parameter-group" })
}

resource "aws_db_instance" "rds" {
  identifier     = local.db_identifier
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 100
  storage_type          = "gp3"
  iops                  = 3000
  storage_throughput    = 125

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db_master.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  parameter_group_name   = aws_db_parameter_group.rds.name

  multi_az                   = false
  publicly_accessible        = false
  storage_encrypted          = true
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  backup_retention_period = 7
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final-snapshot"

  tags = merge(local.common_tags, { Name = local.db_identifier })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.arn
  secret_string = jsonencode({
    engine   = "postgres"
    host     = aws_db_instance.rds.address
    port     = aws_db_instance.rds.port
    dbname   = local.db_name
    username = local.db_username
    password = random_password.db_master.result
  })
}

###############################################################################
# Outputs
###############################################################################

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) for the RDS PostgreSQL instance."
  value       = aws_db_instance.rds.endpoint
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to apply to all taggable resources."
  type        = map(string)
  default     = {}
}

locals {
  master_username = "dbadmin"
  db_name         = "appdb"
  db_port         = 5432

  identifier        = lower("${var.environment}-postgres-${random_id.suffix.hex}")
  subnet_group_name = "${local.identifier}-db-subnet-group"
  secret_name       = "rds/postgres/${local.identifier}/master"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Component   = "rds-postgres"
    },
  )
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%&*()-_=+[]{}"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.identifier}-vpc" })
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_subnet" "private_0" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.identifier}-private-0" })
}

resource "aws_subnet" "private_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.identifier}-private-1" })
}

resource "aws_db_subnet_group" "main" {
  name       = local.subnet_group_name
  subnet_ids = [aws_subnet.private_0.id, aws_subnet.private_1.id]

  tags = merge(local.common_tags, { Name = local.subnet_group_name })
}

resource "aws_security_group" "rds" {
  name        = "${local.identifier}-rds-sg"
  description = "Restrict PostgreSQL access to sources inside the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC CIDR only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, { Name = "${local.identifier}-rds-sg" })
}

resource "aws_kms_key" "rds" {
  description             = "Encrypts RDS storage and the database master credentials secret"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = local.secret_name
  description             = "Master credentials for ${local.identifier}"
  kms_key_id              = aws_kms_key.rds.arn
  recovery_window_in_days = 7

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id

  secret_string = jsonencode({
    username = local.master_username
    password = random_password.db_master.result
    engine   = "postgres"
    port     = local.db_port
    dbname   = local.db_name
  })
}

# db.m5.large is used because db.t3.* instance classes do not support
# the io1 (provisioned IOPS) storage type on Amazon RDS.
resource "aws_db_instance" "main" {
  identifier     = local.identifier
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.m5.large"

  # io1 requires provisioned IOPS and a minimum of 100 GiB allocated storage.
  allocated_storage = 100
  storage_type      = "io1"
  iops              = 3000
  storage_encrypted = true
  kms_key_id        = aws_kms_key.rds.arn

  db_name  = local.db_name
  username = local.master_username
  password = random_password.db_master.result
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = false

  auto_minor_version_upgrade = true
  backup_retention_period    = 7
  backup_window              = "01:00-02:00"
  maintenance_window         = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot      = true
  deletion_protection        = true
  skip_final_snapshot        = false
  final_snapshot_identifier  = "${local.identifier}-final"

  tags = merge(local.common_tags, { Name = local.identifier })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the RDS PostgreSQL instance."
  value       = aws_db_instance.main.endpoint
}

output "db_instance_address" {
  description = "Hostname of the RDS PostgreSQL instance."
  value       = aws_db_instance.main.address
}

output "db_instance_port" {
  description = "Port the RDS PostgreSQL instance listens on."
  value       = aws_db_instance.main.port
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for naming and tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

locals {
  env         = lower(var.environment)
  name_prefix = "db-restore-${local.env}"

  vpc_cidr             = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]

  # Master username stored in Secrets Manager; password is generated by random_password.
  db_username   = "dbadmin"
  backup_prefix = "backups/mysql-xtrabackup/"

  tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}:?"
}

#-------------------------------------------------------------------------------
# Network foundation
#-------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-nat"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

#-------------------------------------------------------------------------------
# Database security group
#-------------------------------------------------------------------------------

resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds-sg"
  description = "Allow MySQL (3306) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from within the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # No egress rules declared: the database requires no outbound access, and
  # Terraform removes the default allow-all egress rule when none is specified.

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-sg"
  })
}

#-------------------------------------------------------------------------------
# Customer-managed KMS key (RDS storage encryption + S3 backup SSE-KMS)
#-------------------------------------------------------------------------------

resource "aws_kms_key" "rds" {
  description             = "Customer managed key for RDS storage encryption and S3 backup bucket SSE-KMS"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-kms"
  })
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.rds.key_id
}

#-------------------------------------------------------------------------------
# Backup source bucket (Percona XtraBackup files for MySQL S3 import)
#-------------------------------------------------------------------------------

resource "aws_s3_bucket" "db_backup" {
  bucket        = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  force_destroy = false

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-backup-${random_id.suffix.hex}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.rds.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "db_backup" {
  bucket = aws_s3_bucket.db_backup.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.db_backup.arn,
          "${aws_s3_bucket.db_backup.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

#-------------------------------------------------------------------------------
# RDS-to-S3 import IAM role
#-------------------------------------------------------------------------------

resource "aws_iam_role" "rds_s3_import" {
  name = "${local.name_prefix}-rds-s3-import"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowRdsAssumeRole"
        Effect    = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-s3-import"
  })
}

resource "aws_iam_role_policy" "rds_s3_import" {
  name = "${local.name_prefix}-s3-import-access"
  role = aws_iam_role.rds_s3_import.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ListBackupBucket"
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.db_backup.arn
      },
      {
        Sid      = "ReadBackupObjects"
        Effect   = "Allow"
        Action   = ["s3:GetObject", "s3:GetObjectVersion"]
        Resource = "${aws_s3_bucket.db_backup.arn}/*"
      }
    ]
  })
}

# The ingestion role must be able to decrypt the SSE-KMS protected backup objects.
resource "aws_iam_policy" "rds_kms_decrypt" {
  name        = "${local.name_prefix}-rds-kms-decrypt"
  description = "Allow the RDS S3 ingestion role to decrypt backup objects protected by the customer managed KMS key"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DecryptBackupObjects"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:DescribeKey"]
        Resource = aws_kms_key.rds.arn
      }
    ]
  })

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-rds-kms-decrypt"
  })
}

resource "aws_iam_role_policy_attachment" "rds_kms_decrypt" {
  role       = aws_iam_role.rds_s3_import.name
  policy_arn = aws_iam_policy.rds_kms_decrypt.arn
}

#-------------------------------------------------------------------------------
# Master credentials in Secrets Manager
#-------------------------------------------------------------------------------

resource "aws_secretsmanager_secret" "db_master" {
  name        = "${local.name_prefix}/db-master-credentials"
  description = "Master credentials for the ${local.name_prefix}-restored-db MySQL instance"

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-db-master-credentials"
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id

  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
  })
}

#-------------------------------------------------------------------------------
# MySQL database restored from S3 (Percona XtraBackup import)
#-------------------------------------------------------------------------------

resource "aws_db_instance" "restored_db" {
  identifier     = "${local.name_prefix}-restored-db"
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.rds.arn

  db_name = "appdb"
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  port                   = 3306
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-final-${random_id.suffix.hex}"

  # Backup files (Percona XtraBackup format) must be uploaded to
  # s3://<bucket>/backups/mysql-xtrabackup/ before this instance can be created.
  # The bucket and instance are both provisioned in the provider region (us-east-1).
  s3_import {
    source_engine         = "mysql"
    source_engine_version = "8.0"
    bucket_name           = aws_s3_bucket.db_backup.bucket
    bucket_prefix         = local.backup_prefix
    ingestion_role        = aws_iam_role.rds_s3_import.arn
  }

  tags = merge(local.tags, {
    Name = "${local.name_prefix}-restored-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

#-------------------------------------------------------------------------------
# Outputs
#-------------------------------------------------------------------------------

output "rds_endpoint_address" {
  description = "Connection endpoint (hostname) of the restored MySQL DB instance."
  value       = aws_db_instance.restored_db.address
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the DB master credentials (secret value is never exposed; retrieve it via secretsmanager:GetSecretValue)."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "production"
}

variable "additional_tags" {
  description = "Additional tags merged into the common tags applied to all resources."
  type        = map(string)
  default     = {}
}

locals {
  name_prefix = lower("${var.project_name}-${var.environment}")

  common_tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.additional_tags
  )

  vpc_cidr            = "10.0.0.0/16"
  num_private_subnets = 3

  db_engine   = "postgres"
  db_name     = "appdb"
  db_port     = 5432
  db_master_username = "dbadmin"

  # RDS storage autoscaling is enabled by setting max_allocated_storage
  # higher than allocated_storage (20 GiB baseline scaling up to 200 GiB).
  db_allocated_storage     = 20
  db_max_allocated_storage = 200

  db_identifier = "${local.name_prefix}-postgres"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# Network foundation (fully managed, greenfield)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_subnet" "private" {
  count                   = local.num_private_subnets
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private" {
  count          = local.num_private_subnets
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Database placement and access control
# ---------------------------------------------------------------------------

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Private subnets across multiple AZs for ${local.db_identifier}"
  subnet_ids  = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-subnet-group" })
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict PostgreSQL access to the VPC CIDR only for ${local.db_identifier}"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL to within the VPC only"
    from_port   = local.db_port
    to_port     = local.db_port
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-sg" })
}

# ---------------------------------------------------------------------------
# Encryption key
# ---------------------------------------------------------------------------

resource "aws_kms_key" "database" {
  description             = "Encrypts ${local.db_identifier} storage and its master credentials secret"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-kms-key" })
}

# ---------------------------------------------------------------------------
# Master credentials (generated, never hardcoded, stored in Secrets Manager)
# ---------------------------------------------------------------------------

resource "random_password" "db_master" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name                    = "${local.name_prefix}-db-master-credentials"
  description             = "Master credentials for ${local.db_identifier}"
  kms_key_id              = aws_kms_key.database.key_id
  recovery_window_in_days = 30

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-db-master-credentials" })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    engine   = local.db_engine
    port     = local.db_port
    dbname   = local.db_name
    username = local.db_master_username
    password = random_password.db_master.result
  })
}

# ---------------------------------------------------------------------------
# PostgreSQL instance with gp3 storage autoscaling enabled
# ---------------------------------------------------------------------------

resource "aws_db_instance" "postgres" {
  identifier     = local.db_identifier
  engine         = local.db_engine
  engine_version = "16.8"
  instance_class = "db.t3.medium"

  # Storage autoscaling: baseline 20 GiB, automatically scales up to 200 GiB.
  allocated_storage     = local.db_allocated_storage
  max_allocated_storage = local.db_max_allocated_storage
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.database.arn

  db_name  = local.db_name
  username = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["username"]
  password = jsondecode(aws_secretsmanager_secret_version.db_master.secret_string)["password"]
  port     = local.db_port

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  multi_az               = true

  backup_retention_period    = 14
  copy_tags_to_snapshot      = true
  auto_minor_version_upgrade = true

  performance_insights_enabled          = true
  performance_insights_retention_period = 7
  performance_insights_kms_key_id       = aws_kms_key.database.arn

  deletion_protection       = true
  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.db_identifier}-final"

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(local.common_tags, { Name = local.db_identifier })
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "db_instance_identifier" {
  description = "Identifier of the PostgreSQL instance."
  value       = aws_db_instance.postgres.identifier
}

output "db_instance_endpoint" {
  description = "Connection endpoint (host:port) of the PostgreSQL instance."
  value       = aws_db_instance.postgres.endpoint
}

output "db_master_credentials_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the database master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project_name" {
  description = "Project name used as the prefix for all resource names."
  type        = string
  default     = "app"
}

variable "environment" {
  description = "Environment name applied as a tag to every resource."
  type        = string
  default     = "production"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "db" {
  name        = "${local.name_prefix}-db-sg"
  description = "Allow inbound PostgreSQL traffic only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from VPC CIDR only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

resource "aws_db_subnet_group" "main" {
  name        = "${local.name_prefix}-db-subnet-group"
  description = "Multi-AZ subnet group for the managed PostgreSQL instance"
  subnet_ids  = aws_subnet.private[*].id

  tags = local.common_tags
}

resource "random_id" "final_snapshot_suffix" {
  byte_length = 4
}

resource "aws_db_instance" "main" {
  identifier     = "${local.name_prefix}-db"
  engine         = "postgres"
  engine_version = "15.8"
  instance_class = "db.t3.medium"

  allocated_storage     = 50
  max_allocated_storage = 100
  storage_type          = "gp3"
  storage_encrypted     = true

  db_name                     = "appdb"
  username                    = "dbadmin"
  manage_master_user_password = true
  port                        = 5432

  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.db.id]

  publicly_accessible = false
  multi_az            = true

  backup_retention_period = 14
  backup_window           = "02:00-03:00"
  maintenance_window      = "sun:04:00-sun:05:00"

  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = "${local.name_prefix}-db-final-snapshot-${random_id.final_snapshot_suffix.hex}"

  enabled_cloudwatch_logs_exports       = ["postgresql", "upgrade"]
  performance_insights_enabled          = true
  performance_insights_retention_period = 7

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db"
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name applied consistently to all resource tags."
  type        = string
  default     = "production"
}

variable "vpc_cidr" {
  description = "CIDR block for the greenfield VPC hosting the database."
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  name_prefix               = "app-${var.environment}"
  final_snapshot_identifier = "${local.name_prefix}-postgres-final-snapshot"

  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Network foundation (greenfield)
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
  })
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db-subnet-group"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-subnet-group"
  })
}

resource "aws_security_group" "database" {
  name        = "${local.name_prefix}-db-sg"
  description = "Restrict PostgreSQL access to the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "PostgreSQL traffic back to the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-db-sg"
  })
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key for database storage and managed master password
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "rds_kms_key" {
  statement {
    sid    = "AllowAccountRootAdministrativeAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateAlias",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DeleteAlias",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateAlias",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowRDSToManageMasterUserPasswordSecret"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["rds.amazonaws.com"]
    }

    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key for RDS storage encryption and the RDS-managed master user secret"
  deletion_window_in_days = 30
  is_enabled              = true
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.rds_kms_key.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rds-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/rds-master-secret-key"
  target_key_id = aws_kms_key.this.key_id
}

# -----------------------------------------------------------------------------
# RDS PostgreSQL instance with RDS-managed master password in Secrets Manager
# -----------------------------------------------------------------------------

resource "aws_db_parameter_group" "main" {
  name   = "${local.name_prefix}-postgres16-params"
  family = "postgres16"

  parameter {
    name  = "log_min_duration_statement"
    value = "5000"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres16-params"
  })
}

resource "aws_db_instance" "this" {
  identifier     = "${local.name_prefix}-postgres"
  engine         = "postgres"
  engine_version = "16.4"
  instance_class = "db.t3.micro"

  allocated_storage     = 20
  max_allocated_storage = 200
  storage_type          = "gp3"
  storage_encrypted     = true
  kms_key_id            = aws_kms_key.this.arn

  db_name  = "appdb"
  username = "dbadmin"

  # RDS-managed master password: RDS creates, stores, and rotates the master
  # credentials in AWS Secrets Manager, encrypted with the specified KMS key.
  # No plaintext password is ever defined in this configuration.
  manage_master_user_password   = true
  master_user_secret_kms_key_id = aws_kms_key.this.arn

  port                   = 5432
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.database.id]
  publicly_accessible    = false
  multi_az               = false

  parameter_group_name       = aws_db_parameter_group.main.name
  auto_minor_version_upgrade = true

  backup_retention_period = 14
  backup_window           = "03:00-04:00"
  maintenance_window      = "sun:04:30-sun:05:30"

  deletion_protection       = true
  copy_tags_to_snapshot     = true
  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "rds_endpoint" {
  description = "Connection endpoint of the RDS PostgreSQL instance."
  value       = aws_db_instance.this.endpoint
}

output "rds_managed_master_secret_arn" {
  description = "ARN of the RDS-managed master user secret in AWS Secrets Manager. Only the ARN is exposed; the secret value is managed exclusively by RDS rotation."
  value       = aws_db_instance.this.master_user_secret[0].secret_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "tags" {
  description = "Additional tags applied consistently to all resources."
  type        = map(string)
  default     = {}
}

locals {
  db_identifier               = "myapp-mysql"
  db_name                     = "myappdb"
  db_username                 = "dbadmin"
  vpc_name                    = "myapp-vpc"
  subnet_group_name           = "myapp-rds-subnet-group"
  security_group_name         = "myapp-rds-mysql-sg"
  secret_name                 = "myapp/mysql/master"
  final_snapshot_identifier   = "myapp-mysql-final-snapshot"
  initial_snapshot_identifier = "myapp-mysql-initial-snapshot"

  common_tags = merge(var.tags)
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_subnet" "rds_az0" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az0"
  })
}

resource "aws_subnet" "rds_az1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-rds-az1"
  })
}

resource "aws_db_subnet_group" "rds" {
  name       = local.subnet_group_name
  subnet_ids = [aws_subnet.rds_az0.id, aws_subnet.rds_az1.id]

  tags = merge(local.common_tags, {
    Name = local.subnet_group_name
  })
}

resource "aws_security_group" "rds" {
  name        = local.security_group_name
  description = "Allow MySQL access only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "MySQL from the VPC CIDR only"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "MySQL traffic restricted to the VPC CIDR"
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })
}

resource "random_password" "db_master" {
  length           = 24
  special          = true
  override_special = "!#$%*()-_=+[]{}:?"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_secretsmanager_secret" "db_master" {
  name        = local.secret_name
  description = "Master credentials for the ${local.db_identifier} MySQL instance"

  tags = merge(local.common_tags, {
    Name = local.secret_name
  })
}

resource "aws_secretsmanager_secret_version" "db_master" {
  secret_id = aws_secretsmanager_secret.db_master.id
  secret_string = jsonencode({
    username = local.db_username
    password = random_password.db_master.result
    engine   = "mysql"
    port     = 3306
    host     = aws_db_instance.mysql.address
    dbname   = aws_db_instance.mysql.db_name
  })
}

resource "aws_db_instance" "mysql" {
  identifier     = local.db_identifier
  engine         = "mysql"
  engine_version = "8.0"
  instance_class = "db.t3.micro"

  allocated_storage = 20
  storage_type      = "gp3"
  storage_encrypted = true

  db_name  = local.db_name
  username = local.db_username
  password = random_password.db_master.result

  db_subnet_group_name   = aws_db_subnet_group.rds.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  publicly_accessible = false
  multi_az            = false

  backup_retention_period    = 7
  auto_minor_version_upgrade = true
  copy_tags_to_snapshot      = true
  deletion_protection        = true

  skip_final_snapshot       = false
  final_snapshot_identifier = local.final_snapshot_identifier

  timeouts {
    create = "40m"
    update = "80m"
    delete = "60m"
  }

  tags = merge(local.common_tags, {
    Name = local.db_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_db_snapshot" "mysql_snapshot" {
  db_instance_identifier = aws_db_instance.mysql.identifier
  db_snapshot_identifier = local.initial_snapshot_identifier

  tags = merge(local.common_tags, {
    Name = local.initial_snapshot_identifier
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "db_instance_endpoint" {
  description = "Connection endpoint of the MySQL instance."
  value       = aws_db_instance.mysql.endpoint
}

output "db_instance_identifier" {
  description = "Identifier of the MySQL instance."
  value       = aws_db_instance.mysql.identifier
}

output "db_master_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the master credentials."
  value       = aws_secretsmanager_secret.db_master.arn
}

output "db_snapshot_identifier" {
  description = "Identifier of the manual MySQL snapshot."
  value       = aws_db_snapshot.mysql_snapshot.db_snapshot_identifier
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default = {
    Project   = "efs-file-storage"
    Owner     = "platform-team"
    Compliance = "internal"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "efs-${var.environment}"

  common_tags = merge(
    var.tags,
    {
      Name        = local.name_prefix
      Environment = var.environment
      ManagedBy   = "terraform"
    },
  )
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    },
  )
}

resource "aws_subnet" "private_a" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[0]
  cidr_block        = "10.0.1.0/24"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-a"
      Tier = "private"
    },
  )
}

resource "aws_subnet" "private_b" {
  vpc_id            = aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[1]
  cidr_block        = "10.0.2.0/24"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-b"
      Tier = "private"
    },
  )
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-sg"
  description = "Allow inbound NFS (TCP 2049) only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-efs-sg"
    },
  )
}

resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-efs-token"
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"
  encrypted        = true

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-efs"
    },
  )
}

resource "aws_efs_mount_target" "private_a" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private_a.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_mount_target" "private_b" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private_b.id
  security_groups = [aws_security_group.efs.id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "tags" {
  description = "Consistent tags (Name, Environment, ManagedBy) applied to every taggable resource in this configuration."
  type        = map(string)

  default = {
    Name        = "efs-shared-storage"
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  az_count   = 2
  az_names   = slice(data.aws_availability_zones.available.names, 0, local.az_count)
  account_id = data.aws_caller_identity.current.account_id

  private_subnets = {
    for idx, az in local.az_names :
    az => cidrsubnet(aws_vpc.main.cidr_block, 8, idx + 10)
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(var.tags, {
    Name = "efs-vpc"
  })
}

resource "aws_subnet" "private" {
  for_each          = local.private_subnets
  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value
  availability_zone = each.key

  tags = merge(var.tags, {
    Name = "efs-private-${each.key}"
  })
}

resource "aws_security_group" "efs_mount_targets" {
  name        = "efs-mount-target-sg"
  description = "Permit NFS (TCP 2049) access to EFS mount targets from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC CIDR only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic scoped to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(var.tags, {
    Name = "efs-mount-target-sg"
  })
}

resource "aws_kms_key" "efs" {
  description             = "Customer managed CMK used to encrypt the EFS file system at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableIAMDelegationForAccountRoot"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:Get*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEFSServiceToUseKeyForThisAccountOnly"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:CallerAccount" = local.account_id
            "kms:ViaService"    = "elasticfilesystem.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, {
    Name = "efs-encryption-key"
  })
}

resource "aws_kms_alias" "efs" {
  name          = "alias/efs-shared-storage"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "main" {
  creation_token   = "efs-shared-storage-main"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  lifecycle_policy {
    transition_to_archive = "AFTER_90_DAYS"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = merge(var.tags, {
    Name = "efs-shared-storage"
  })
}

resource "aws_efs_mount_target" "main" {
  for_each        = aws_subnet.private
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = each.value.id
  security_groups = [aws_security_group.efs_mount_targets.id]
}

resource "aws_efs_access_point" "app" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/app"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "750"
    }
  }

  tags = merge(var.tags, {
    Name = "efs-access-point-app"
  })
}

resource "aws_efs_backup_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  backup_policy {
    status = "ENABLED"
  }
}

output "efs_file_system_id" {
  description = "ID of the EFS file system."
  value       = aws_efs_file_system.main.id
}

output "efs_dns_name" {
  description = "DNS name of the EFS file system used by clients to mount the share."
  value       = aws_efs_file_system.main.dns_name
}

output "efs_security_group_id" {
  description = "ID of the security group attached to the EFS mount targets."
  value       = aws_security_group.efs_mount_targets.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for the Environment tag on all resources."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "platform-efs"
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

# ---------------------------------------------------------------------------
# Networking foundation (greenfield: everything created in this file)
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "efs_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az-a"
  })
}

resource "aws_subnet" "efs_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet-az-b"
  })
}

# ---------------------------------------------------------------------------
# Customer-managed KMS key for EFS encryption at rest
# ---------------------------------------------------------------------------

resource "aws_kms_key" "efs" {
  description             = "Customer managed key for EFS encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid = "EnableAccountRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid = "AllowEfsServiceToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "elasticfilesystem.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
          "kms:CreateGrant"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${local.name_prefix}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

# ---------------------------------------------------------------------------
# EFS file system
# ---------------------------------------------------------------------------

resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-${var.environment}"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-file-system"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Security group: NFS (TCP 2049) from the VPC CIDR only
# ---------------------------------------------------------------------------

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-nfs-sg"
  description = "Allow NFS (TCP 2049) from within the VPC only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nfs-sg"
  })
}

# ---------------------------------------------------------------------------
# Mount targets (two AZs for high availability)
# ---------------------------------------------------------------------------

resource "aws_efs_mount_target" "a" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.efs_a.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_mount_target" "b" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.efs_b.id
  security_groups = [aws_security_group.efs.id]
}

# ---------------------------------------------------------------------------
# Client access principal (IAM role + instance profile for EC2 consumption)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEc2ToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "efs_client" {
  name               = "${local.name_prefix}-client-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-client-role"
  })
}

data "aws_iam_policy_document" "efs_client" {
  statement {
    sid    = "EfsClientMountWriteRootAccess"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess"
    ]
    resources = [aws_efs_file_system.main.arn]
  }
}

resource "aws_iam_policy" "efs_client" {
  name   = "${local.name_prefix}-client-policy"
  policy = data.aws_iam_policy_document.efs_client.json
}

resource "aws_iam_role_policy_attachment" "efs_client" {
  role       = aws_iam_role.efs_client.name
  policy_arn = aws_iam_policy.efs_client.arn
}

resource "aws_iam_instance_profile" "efs_client" {
  name = "${local.name_prefix}-client-profile"
  role = aws_iam_role.efs_client.name
}

# ---------------------------------------------------------------------------
# EFS file system policy (enforce TLS in transit, scope client actions)
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "efs_file_system" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["elasticfilesystem:*"]
    resources = [aws_efs_file_system.main.arn]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowClientAccessForClientRole"
    effect = "Allow"
    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess"
    ]
    resources = [aws_efs_file_system.main.arn]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.efs_client.arn]
    }
  }
}

resource "aws_efs_file_system_policy" "main" {
  file_system_id = aws_efs_file_system.main.id
  policy         = data.aws_iam_policy_document.efs_file_system.json

  depends_on = [
    aws_efs_mount_target.a,
    aws_efs_mount_target.b
  ]
}

# ---------------------------------------------------------------------------
# Automated backups
# ---------------------------------------------------------------------------

resource "aws_efs_backup_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  backup_policy {
    status = "ENABLED"
  }
}

# ---------------------------------------------------------------------------
# Access point (constrained POSIX identity and controlled root directory)
# ---------------------------------------------------------------------------

resource "aws_efs_access_point" "app" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    gid = 1000
    uid = 1000
  }

  root_directory {
    path = "/app"

    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "0755"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-access-point"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_name" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "efs-backup"
}

locals {
  name_prefix = "${var.project_name}-${var.environment_name}"

  common_tags = {
    Name        = local.name_prefix
    Environment = var.environment_name
    Project     = var.project_name
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index + 1}"
  })
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs-mount-target-sg"
  description = "Permits NFS (TCP 2049) ingress only from within the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC only"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-mount-target-sg"
  })
}

resource "aws_kms_key" "efs" {
  description             = "Customer-managed KMS key used to encrypt the EFS file system at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-kms-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${local.name_prefix}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "efs" {
  creation_token   = "${local.name_prefix}-efs"
  performance_mode = "generalPurpose"
  throughput_mode  = "elastic"
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  backup_policy {
    status = "ENABLED"
  }
}

resource "aws_efs_file_system_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnforceEncryptionInTransit"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.efs.arn
        Condition = {
          BoolIfExists = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_efs_mount_target" "efs" {
  for_each = {
    for idx, subnet_id in aws_subnet.private[*].id : tostring(idx) => subnet_id
  }

  file_system_id  = aws_efs_file_system.efs.id
  subnet_id       = each.value
  security_groups = [aws_security_group.efs.id]
}

output "efs_file_system_id" {
  description = "The ID of the EFS file system."
  value       = aws_efs_file_system.efs.id
}

output "efs_dns_name" {
  description = "The DNS name of the EFS file system (mount point)."
  value       = aws_efs_file_system.efs.dns_name
}

output "efs_backup_policy_status" {
  description = "The status of the EFS automatic backup policy."
  value       = aws_efs_backup_policy.efs.backup_policy[0].status
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

